window.RB_SHARDS=window.RB_SHARDS||{};window.RB_SHARDS[18]=[{"i":41454,"n":"(קלעי)","bk":[["מקור ברוך",""]]},{"i":41455,"n":"קאבילו, משה מאזמיר","b":"מדפיס באזמיר אצל ר דוד חזן-תצג."},{"i":41456,"n":"קאבילי, אברהם בכור משלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"בית מנוחה\"-תריא - עם כמה מחבריו."},{"i":41457,"n":"קאבילי, מנחם מקושטא","f":"שמואל","b":"רב בקושטא בזמן הרא\"ם. חתם-רפ על החזרת הפרנס ר שאלתיאל. בנו - ר שמואל."},{"i":41458,"n":"קאבילי, שמואל או שלמה מקושטא","f":"מנחם","b":"מחכמי קושטא, מגיה בדפוס שלמה יעבץ. הו\"ל את שו\"ת הרא\"ם."},{"i":41459,"n":"קאבלה, בוגיד מגרבה","f":"מכלוף","b":"פרסם מאמרים ב\"מקבציאל\" - גרבה תרצה."},{"i":41460,"n":"קאבסי, אברהם","b":"מחכמי קאבס בתקופת הגאונים"},{"i":41461,"n":"קאבסי, אברהם מטריפולי","bt":"רך","dt":"רץ - בערך","b":"נגיד בטריפולי, נשיא הקהלה-רן. נזכר בשו\"ת ר יעקב בירב. הנגיד הראשון הידוע בטריפולי."},{"i":41462,"n":"קאגופונו, יוסף משלוניקי","f":"משה","dt":"רעה","b":"משורר מחכמי שלוניקי."},{"i":41463,"n":"קאג'יג', יצחק מקושטא או אלגיר","f":"אברהם","b":"תלמיד ר יוסף ן מניר, רב בקצמטינא. נזכר בשו\"ת הריב\"ש (שגם מודה לו על החסד שעשה עם רבו-ר יוסף ן מניר). (בארזי הלבנון מופיע כך: \"תלמיד ר יוסף מגיד. מחכמי קושטא\" - וכנראה טעות)."},{"i":41464,"n":"קאג'יג', שלמה מאלגיר","bt":"תך","dt":"תץ - בערך","b":"רב באלגיר, חתום על החרם נגד נחמיה חייא חיון."},{"i":41465,"n":"קאגיג'י, בנימין","b":"מגדולי חכמי מצרים-שס\"ז"},{"i":41466,"n":"קאדושין, יצחק יהודה מניו יורק","k":"בעל ברית יצחק","b":"רב בניו יורק. חיבר \"ברית יצחק\" נ\"י תרנז."},{"i":41467,"n":"קאדיש, דוד מהראדים","b":"תלמיד ר יונתן איבשיץ. ראב\"ד הראדים-בוהמיה."},{"i":41468,"n":"קאהן, אביגדור יהודה מדיסעל","f":"מאיר מאיפלשג","dt":"תשד","dp":"אושוויץ","b":"תלמיד השב\"ס. חתן ר יחיאל מיכל אויש מפאקש. דיין בדיסעל-תרסג, פאקש-תרעט. נספה בשואה."},{"i":41469,"n":"קאהן, אברהם ברוך מקובנה","k":"בעל ברכת אב","b":"רב בקובנה, ארה\"ב. חיבר \"ברכת אב\" מיניאפוליס תרס."},{"i":41470,"n":"קאהן, אברהם יצחק מתולדות אהרן","f":"אהרן דוד","k":"אדמור מתולדות אהרן","dt":"תשנז","dp":"ירושלים","b":"נכד ר שמואל העליר מצפת. תלמיד ישיבת סטמר אצל ר יואל טיטלבוים. חתן ר אהרן ראטה האדמור משומרי אמונים, אדמור בירושלים על מקום חותנו. הו\"ל ספרי חותנו עם הערות ממנו. חיבר \"דברי אמונה\", ועוד. בניו ר שמואל יעקב על מקומו אחריו כאדמור מתולדות אברהם יצחק, ור דוד על מקומו אחריו כאדמור מתולדות אהרן."},{"i":41471,"n":"קאהן, אברהם מאלגיר וצרפת","bt":"תקצה","dt":"תרעג","b":"רב בקצמטינא-תרכב, אלגיר - מטעם הקונסיסטואר. שאלה ממנו לר אליהו חזן בענין קידושין. חיבר \"היהודים באפריקה הצפונית\" - בצרפתית - ובספר רשימה של רבני אלגיר. הסכים על \"זבחי תרועה\" - ליוורנו תרכז לר שלמה זרקא."},{"i":41472,"n":"קאהן, אברהם מארה\"ב","k":"בעל יעקל דער יאנקי","bt":"1860","bp":"פודבראזי-ליד וילנא","dt":"1951","dp":"ניו יורק","b":"תלמיד ביהמ\"ד למורים בוילנא. היגר לארה\"ב ויסד שם אגודות מקצועיות של פועלים יהודים. הראשון שהחל בתעמולה סוציאליסטית באידיש באמריקה. פרסם מאמרים ב\"רוסקי יאבריי\", \"וויאסטניק יאברופי\". הו\"ל \"נייע צייט\". השתתף בקונגרס הסוציאליסטי בבריסל ובהשפעתו נתקבלה החלטה כנגד האנטישמיות. יסד את \"פארווערטס\" בניו יורק שהפך לעתון היהודי הגדול בעולם. ביקר בארץ-1925, והתקרב לציונות. חיבר גם \"בלעטער פון מיין לעבען\", ועוד."},{"i":41473,"n":"קאהן, אברהם מארה\"ב","bp":"ראדין","b":"מפרושי איישישוק, נסמך מאת: ר חיים יעקב וידורביץ ממוסקבה, ר שמואל צבי ויין. היגר לניו יורק וכיהן כרב אנשי וולוזין בניו יורק, ראש ביהמ\"ד אנשי וארשא, ביהמ\"ד אנשי ישראל."},{"i":41474,"n":"קאהן, אברהם מארה\"ב","b":"גביר ועסקן ציבור בניו יורק, ממיסדי ביהמ\"ד \"תפארת ציון\" בברונסויל, נשיא ישיבת רבי חיים ברלין, ראש ביהכ\"נ \"בני ישראל\" בבנסנהורסט."},{"i":41475,"n":"קאהן, אברהם מרדכי מצנסטחוב","b":"פרסם מאמרים ב\"חדרי תורה\" - קראקא תרפו."},{"i":41476,"n":"קאהן, אהרן הכהן מדברצין","f":"יו\"ט ליפמן כץ מאירשא","dt":"תרסו - כ תשרי","dp":"דברצין","b":"תלמיד הכת\"ס. חתן ר אליעזר צבי הרש הלוי לוינגר ממגנדורף בעל \"בני לוי\". מחכמי דברצין."},{"i":41477,"n":"קאהן, אהרן הכהן מפרשבורג","b":"תלמיד הכת\"ס. חתן ר חיים ניישלס מפרשבורג. מחכמי פרשבורג. בנו - ר יוסף שמחה מהמבורג."},{"i":41478,"n":"קאהן, אהרן שמואל הכהן","dt":"תשג","b":"רב בסעטשאווטשע"},{"i":41479,"n":"קאהן, אלחנן מוילנא","f":"יקותיאל משווקסנא","k":"חנן סלנטר","bp":"שועקסנא","dt":"תרלט - יז סיון","dp":"וילנא","b":"חתן בסלנט והתישב שם והיה תלמיד חבר לר זונדל סלנט מירושלים, וחברו של ר ישראל סלנטר. גביר ותלמיד חכם והתישב בפטרבורג. עזר ותרם בעניני הכלל והפרט. לעת זקנתו התישב אצל בניו בוילנא."},{"i":41480,"n":"קאהן, אליהו מאלגיר","b":"רב בענאבא(=בון) מטעם הקונסיסטואר."},{"i":41481,"n":"קאהן, אליהו מואשאר-נאמען","f":"יעקב יוסף מאנאד","bt":"תרמ - בערך","dt":"תשד - ג סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, ור שלמה זלמן עהרנרייך מטשאבא. חתן ר שלמה סופר מבערגסאס - בנו של הכת\"ס, ועבר לשם. רב בואשאר-נאמען (=נאמעני - בגליל בערגסאס)-תרסה. בזיוו\"ש חתן ר בנציון שלזינגר משמילויא. נספה בשואה. בנו ר בנציון רב בסנטפעטר וניו יורק."},{"i":41482,"n":"קאהן, אליעזר מאלגיר וצרפת","dt":"תרלו","dp":"אלגיר","b":"רבה הראשון של ווהראן-תרז מטעם הקונסיסטואר, אלגיר-תרכד-תרלו."},{"i":41483,"n":"קאהן, בועז משיקגו","k":"בעל חלקת בועז","b":"רב בשיקגו-תשג."},{"i":41484,"n":"קאהן, בנימין זאב וולף מבאדען","f":"שמואל הכהן","bt":"תקצה","bp":"רודניץ","dt":"תרעג - ל אד\"א","dp":"סערדאוהל","b":"תלמיד הכת\"ס, ור רפאל שולהאף מפרג. חתן ר משה בישיץ מסערדאוהל, ועבר לשם. רב בדיאסעג, הקהילה החרדית בבדען (וינה)-תרלח, בנו ר שלמה על מקומו אחריו."},{"i":41485,"n":"קאהן, בנימין זאב וולף ממאלטש","b":"רב במאלטש-תר\"פ"},{"i":41486,"n":"קאהן, בנציון מסנט-פעטער ונ\"י","f":"אליהו כץ קאהן מוואשר","k":"בעל שערי ציון","bt":"תרעד","bp":"ואשאר-נאמען","dt":"תשנט - יד צמוז","dp":"קרית יואל - מונרו","b":"תלמיד הדעת סופר, ור שלמה צבי שטרסר מדברצין. חתן ר משה חיים גרינפלד מסנט-פעטר, וכיהן כרב לצד חותנו. ניצל מהשואה ואחריה רב בסנט-פעטר. בזיוו\"ש חתן ר שאול יחזקאל רייך מסנט פעטר. רב בניו יורק-תשז. חיבר גם \"אבני ציון\"."},{"i":41487,"n":"קאהן, ברוך מארה\"ב","f":"מאיר שלום","k":"בעל שביל הזהב","bp":"ראסיין","b":"נכד ר שאול בנימין מואלודק, ונכד(-אבי אמו) ר משלם זלמן רבינוביץ-בנו של ר דב בר מראסיין. מחכמי בריינסק-פלך גרודנא, היגר לארה\"ב והתישב בניו יורק. פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":41488,"n":"קאהן, גרשון מנחם מסענזשארץ","f":"ישכר בער מסענזשארץ","bt":"תרלח","bp":"ערדא-סנזשארץ","dt":"תשד","b":"רב בערדא-סענזשארץ-תרעז על מקום אביו. חתנו ר יהושע ברוך קרויס רב הצעיר לצדו. נספה בשואה."},{"i":41489,"n":"קאהן, דוד יעקב הכהן מגרוסורדין","f":"אהרן מדברצין","b":"ראש הקהל בגרוסורדין."},{"i":41490,"n":"קאהן, דוד מתולדות אהרן","f":"אברהם יצחק-תולדות אה","k":"אדמור מתולדות אברהם","b":"בן האדמור מתולדות אברהם. אדמור בירושלים על מקום אביו."},{"i":41491,"n":"קאהן, הנרי מארה\"ב","bt":"1863","bp":"לונדון","b":"תלמיד הרב שפייערס בלונדון. היגר לארה\"ב והיה רב במקומות שונים, ובהם קהילת \"עדת ישראל\" בגלווסטון-טקסס. חיבר ספרים באנגלית, ומאמרים במאספים שונים ובהם של החברה היהודית ההיסטורית."},{"i":41492,"n":"קאהן, וולף מוינר-באדן","f":"שב יעקב","b":"רב בווינר-באדן"},{"i":41493,"n":"קאהן, חיים יהודה מקריטשוב","f":"גרשון","bt":"תריח","b":"רב בקריטשוב-פלך מוהילוב-תרן. (מאותה השנה נרשם גם ר יהודה ליב קריינדל)."},{"i":41494,"n":"קאהן, חנוך חיים הכהן מירושלים","f":"צבי הירש","bt":"תרל","bp":"וילקו-דאברא-פלך מונקטש","dt":"תשטו","b":"לאחר שנתייתם גדל ולמד אצל ר חנניה יו\"ט טיטלבוים בעל \"קדושת יו\"ט\", ור\"מ בישיבת רבו, חתן המדפיס ר מנחם מנדל וידר מסיגט רב בווילקו-דברה(=נאדי-באבראן)-תרנב, עלה לירושלים-תרס וסירב לרבנות, יסד את כולל מונקטש בירושלים ואת שכונת בתי מונקטש וביהמ\"ד \"תפארת צבי\". חיבר ספרים שונים - בכת\"י. התפרסם כמקובל וצדיק."},{"i":41495,"n":"קאהן, חנניה דב כץ מפעסט וארה\"ב","k":"בעל שיטה מקובצת החדש","b":"רב בפעסט, ארה\"ב. חיבר יחד עם ר יקותיאל מרדכי שיק \"שיטה מקובצת החדש\"."},{"i":41496,"n":"קאהן, יונתן מסאלאש","b":"דומ\"צ בסאללאש."},{"i":41497,"n":"קאהן, יוסף דב בר הכהן מוינה","f":"יו\"ט ליפמן ממטרסדורף","k":"בעל דברי יוסף","bt":"תריד","bp":"מטרסדורף","dt":"תרנח - כה שבט","dp":"מטרסדורף","b":"תלמיד השב\"ס, ור דוד ביסטריץ ממילכדורף. חתן ר בנימין שלמה זלמן שפיצר מוינה - חתנו של החת\"ס. רב בקהילת \"עדת ישראל\" שיפשוהל בוינה על מקום חותנו."},{"i":41498,"n":"קאהן, יוסף הכהן מפרוינקירכן","f":"ישעיה מיערגין","bt":"תרח","bp":"יערגין","dt":"תרצב - כב אד\"ב","dp":"פרוינקירכן","b":"תלמיד הכת\"ס. חתן ר ברוך שילר מפערטא סנט מיקלאש. שו\"ב בטשארנא-תרלט, פרוינקירכן-תרסב."},{"i":41499,"n":"קאהן, יוסף יצחק מקטוביץ","b":"מחותן עם הדעת סופר, חתנו - ר אברהם שמואל בנימין סופר מפרשבורג. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":41500,"n":"קאהן, יוסף משה מלודז","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":41501,"n":"קאהן, יוסף שמחה הכהן מהמבורג","f":"אהרן מפרשבורג","k":"בעל שמחת כהן","bt":"תרכו","bp":"פרשבורג","dt":"תרפח - ז ניסן","dp":"המבורג","b":"תלמיד השב\"ס, ור משה גרינולד מחוסט. חתן דודו ר גבריאל שמואל ניישלס מפרשבורג. רב בפרשבורג-תרנו, מחכמי הקלויז בהמבורג-תרס."},{"i":41502,"n":"קאהן, יעקב מאינוארצלב","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":41503,"n":"קאהן, יצחק יוסף כץ מסאמאש","f":"אברהם תלמיד החת\"ס","bt":"תקפה","bp":"פעטרא-ליד מארגרטן","dt":"תרפא - טו תשרי","dp":"סאמאש-אויוואר","b":"תלמיד הכת\"ס, ור יצחק אהרן לנדסברג בגרוסורדין. שו\"ב במארוש-לודאש, רב בסאמוש-אויוואר-תרלה - בגליל הרבנות של ר מנדל פאנט מדעש שהעביר אליו כפרים ועיירות מסביב - למעלה מ-40 שנה. הותקף בעתון הניאולוגים על סירובו לחקוק במצבות תאריכים נוצריים. רוב חבוריו אבדו בשואה. נשאר פנקס בכת\"י ובו הספד על ר הלל ליכטנשטין-תרנא, ועוד. חתנו ר אברהם שלמה אליאש על מקומו אחריו."},{"i":41504,"n":"קאהן, ירמיה הכהן מסלטפינא","f":"ישכר בער מאויהל","bt":"תרלה","bp":"אויהל","dt":"תרצג - כב טבת","dp":"וינה","b":"תלמיד בעל \"ערוגת הבשם\". חתן ר שלמה הירש שלומוביץ מביטשקוף, ועבר לשם ולמד עם ר אלתר שאול פפר בעל \"אבני זכרון\". רב בניאראד-סרדה, דיין בנאסוד-תרסח, דיין בסלטפינא-תרע ליד סיגט. מתורתו ב\"וילקט יוסף\"."},{"i":41505,"n":"קאהן, ישכר דב מאויהל","f":"יעקב","k":"בעל בינת ישכר-תרפד","bt":"תקצ-ד","bp":"שאמשון-ליד דברצין","dt":"תרפג - ג אייר","dp":"ערדא-סענזשארץ","b":"תלמיד החת\"ס, ר מנחם א\"ש באונגוואר, אצל ר אשר אנשל יונגרייז בעל \"מנוחת אשר\" מטשנגער(=צ'אנגר), ר שמעלקא קליין בעל \"צרור החיים\" בסעליש, ור ירמיה לעוו בעל \"דברי ירמיה\" באויהל, בעל \"בית היוצר\" מחוסט, ר מנחם א\"ש מאונגואר. חתן ר מאיר אברהם מצ'אבא בעל \"פרי לצדיק\". דיין באוהל-תרכב אצל רבו ר ירמיה לעוו, בזיוו\"ש חתן גיסו ר יצחק יוסף בליך מגאווא, וביזוו\"ש חתן אלמנת ר משה שטיין מערדא סענזשארץ(=סט-גיורג)-תרלז על מקום ר משה שטיין, וראש ישיבה ובנו ר גרשון מנדל על מקומו אחריו, רב במארוש-ואשארהי-תרעז ונהג אדמורות. (למרות שמו לא היה כהן), הצטרף לתנועה הציונית ובקונגרס הציוני הדתי בפרשבורג-תרסד - הציע לרבני הונגריה להצטרף ל\"מזרחי\", אולם לאחר מכן נאלץ לחזור בו - בלחץ הרבנים החרדים וחתם על קול קורא נגד קונגרס המזרחי - יחד עם 120 רבנים, ואף חיבר חוברת \"רב לכם משכימי קום\" כנגד ר משה שמואל גלזנר מקלויזנבורג וחיים ויסבורג שהיו מראשי התנועה הציונית בטרנסילבניה. חיבר גם \"דגול מרבבה\", \"דעת מוסר\", ועוד."},{"i":41506,"n":"קאהן, ליבר מקוזין","f":"בנימין","bt":"תרלג","b":"רב בקאזין(=קוזין)-פלך קיוב-תרנח."},{"i":41507,"n":"קאהן, מאיר מוולנדדורף","f":"משה צבי מנעמש ביק","dt":"תרסח - כב שבט","dp":"וולנדורף?","b":"תלמיד הכת\"ס, ר זאב וולף טננבוים, מהר\"ם א\"ש. דיין בוואלנדורף-תרמו."},{"i":41508,"n":"קאהן, מאיר מראויטש","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":41509,"n":"קאהן, מיכאל מפולדא","f":"נפתלי הרץ","k":"בעל שטרי עסקא","bt":"תריא","b":"נכד-אבי אמו ר מיכאל פיקארט. חתן ר אשר אנשל שטרן מהמבורג. תלמיד ר מאיר להמן ממגנצא, ר שמואל בונדי, ביהמ\"ד לרבנים בברלין, בעל תואר ד\"ר. רב בזמטר(=זאמטער)-פלך פוזנא-תרלז, פולדא-פלך פוזנא-תרלח. חיבר ספרים וחוברות בלשון אשכנז."},{"i":41510,"n":"קאהן, מנחם נחום","f":"שלמה יהודה בן בנציון","bt":"תרכא-ט","b":"נכד ר בן ציון מזינקוב-פלך קיוב-קרובו של האדמור ר ישראל מרוזין (שניהם מצאצאי ר צבי מקראסטשוב). תלמיד ר יחזקאל פרנקל מהוסיאטין בעל \"דברי אברהם\", ר יהושע שפירא מרוזין, ר מרדכי דב מרוזין משטפאנשט. רב ברוזין-תרנד, קריליבקה, קזטין-פלך קיוב, ויאזובקה-ווהלין-תרנט. נסמך מאת: ר נפתלי מסקווירא, ר מרדכי דב מהורנסטייפל."},{"i":41511,"n":"קאהן, מרדכי יעקב","dt":"תרעג - טז סיון","b":"מו\"צ באדאמיש-תרמ\"ה"},{"i":41512,"n":"קאהן, מרדכי מבודפשט","b":"ראש השובי\"ם בבודפשט. אביו של ר חנניה דב מבודפשט-ברוקלין."},{"i":41513,"n":"קאהן, משה זאב משיקגו","dt":"תשיז","b":"רב בשיקגו. פרסם מאמרים ב\"הכוכב\" - מונקטש-נ\"י תרצה, \"לקט ששנ\"ה\" - סטמר תרצד, \"המגיד\" - סטמר תרפח-תרצט, \"שערי אורה\" - מיהאלביץ תרץ-תרצד, \"תבונה\" - ירושלים תשא-תשח."},{"i":41514,"n":"קאהן, משה מאסלינגן","f":"נתן הכהן","bt":"תרלב","b":"רב בעסלינגן-תרסג, מרגנטהיים."},{"i":41515,"n":"קאהן, פנחס יעקב מלייפציג","f":"ראובן הכהן","k":"בעל אוצר הביאורים","bt":"תרלח","bp":"לקנבך או קוברסדורף","dt":"תשכא - כו אב","dp":"ירושלים","b":"תלמיד השב\"ס, ור מרדכי רייכנפלד מינושהאזא. מחכמי לייפציג-תרעה, לונדון-תרצט. עלה לירושלים-תשיט. חיבר ספר הסימנים השלם. עורך ספרי חזקה רבה. פרסם מאמרים ב\"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":41516,"n":"קאהן, צבי הירש הכהן מירושלים","f":"חנוך חיים מירושלים","k":"בעל גנזי דרשות ורעיו","bt":"תרנח","bp":"סיגט","b":"עלה בילדותו עם משפחתו לירושלים, תלמיד ישיבות ירושלים, ר חיים הלר. נסמך מאת ר חיים יוסף זוננפלד בירושלים, עבר לארה\"ב-תרפא וכיהן כרב \"קהל עדת ישורון\" בהרלם-ניו יורק, \"בני אברהם\", יסד ביהמ\"ד \"דגל ירושלים\"-תרפה, מיסד קהלת \"בית המדרש תפארת ישראל\" בריברסייד. ממיסדי המושבה רעננה בארץ ישראל."},{"i":41517,"n":"קאהן, צבי הירש מדרצ'ה ונ\"י","f":"יונתן בנימין-נפש יונ","k":"בעל לקוטי צבי-תשמא","bt":"תרן","bp":"סעליש","dt":"תשלא - יח אלול","dp":"ארה\"ב - ירושלים","b":"תלמיד ר יהודה גרינוולד בסטמר, ור משה גרינוולד בחוסט. חתן ר ברוך ליכטנשטין מקראסנא. רב בסאלארד-גליל גרוסורדין-תרע, בהמלצת ר משה הרש פוקס רב גרוסורדין והגליל, רב בדרצ'קה(=דרטשקא)-ליד דברצין. בזמן השואה היה בוינה - בידיעת הגיסטפו, לאחר השואה דיין בבית הדין המיוחד לעגונות בבודפשט. היגר לארה\"ב-תשז וכיהן כרב בניו יורק, פטרסון-ניו ג'רסי. חיבר \"לקוטי צבי\" תל אביב תשמא - ובסופו ספר זכרונותיו מתקופת השואה."},{"i":41518,"n":"קאהן, צדוק מפאריס","k":"בעל הרצאות לנוער","bt":"תקצט","bp":"מנהיים","dt":"תרסה","b":"למד במיץ, פאריס. רבה האורטודוכסי של פאריס, ורב ראשי בצרפת-תרמח. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":41519,"n":"קאהן, ראובן מנארווא","f":"אליהו","bt":"תריג","b":"רב בנארווא-פלך גרודנא-תרלז. חתנו - ר משה מרדכי פרלין מלובאשוב."},{"i":41520,"n":"קאהן, שלמה מצרפת","b":"רב בנימס-צרפת-תרע."},{"i":41521,"n":"קאהן, שמואל יעקב מירושלים","f":"אברהם יצחק-תולדות אה","k":"אדמור מתולדות אברהם","b":"בן האדמור מתולדות אברהם. אדמור על מקום אביו בשם האדמור מתולדות אברהם יצחק."},{"i":41522,"n":"קאהן, שמואל מוירצבורג","f":"בנימין זאב וולף מבדן","bt":"תרלג","bp":"דיאסעג","dt":"תרפב","dp":"וירצבורג","b":"תלמיד השב\"ס. מחכמי וירצבורג."},{"i":41523,"n":"קאהן-זלצר, מנחם מאונדורף","f":"מיכאל זלצר - האבא","dt":"תרמג - ז סיון","b":"חתן הרב באונסדורף. דיין באונסדורף. נזכר ב\"שו\"ת מהר\"ם א\"ש\", ושו\"ת חתן סופר."},{"i":41524,"n":"קאזאב, מרדכי מפרג","b":"חתן ר יונתן איבשיץ. מחכמי פרג."},{"i":41525,"n":"קאזאק, יוסף מבריסק","b":"חתן השר ר שאול וייל. נזכר בשו\"ת \"משאת בנימין\", חתם על תקנת לובלין - איסור קנית רבנות בכסף."},{"i":41526,"n":"קאזי, יוסף מפוזנא ולבוב","dp":"פוזנא","b":"חתן השר שאול וייל. רב בבריסק, לבוב, פוזנא-שע. לדעת בעל כלילת יופי בספרו - הוא הנזכר בשו\"ת מהר\"ם מלובלין שהיה אב\"ד בלבוב בזמן הסמ\"ע. בנו - ר שלמה זלמן."},{"i":41527,"n":"קאזי, שלמה זלמן מלבוב","f":"יוסף מפוזנא","dt":"שעב - כג טבת","dp":"לבוב","b":"רב בלבוב."},{"i":41528,"n":"קאזינר, יהודה ליב מלבוב","f":"צבי הירש","b":"מחכמי לבוב, חתם-תקכב."},{"i":41529,"n":"קאזינר, משה מלבוב (מיזיס)","f":"אליהו","b":"מראשי קהלת לבוב או דיין בלבוב, חתם-תסא על תקנות קהלת זולקוא, חתם-תעח עם ר צבי בן משה מרגליות, ר משה קיקניש, ועוד."},{"i":41530,"n":"קאזינר, צבי הירש מלבוב (מיזיס)","f":"משה","dt":"תצח - כא חשון","dp":"לבוב","b":"חתן הגביר ר אריה יהודה ליב גינצבורג בן ר נפתלי בעל \"נפתלי שבע רצון\". גביר מחכמי לבוב, פרנס. בניו - ר יהודה ליב, ר משה."},{"i":41531,"n":"קאזלרי, וידאל מספרד","k":"בעל הנהגת הבריאות","b":"רופא בספרד, תרגם ספר רפואה לעברית בשם \"הנהגת הבריאות\"."},{"i":41532,"n":"קאזס, משה מבריסק","b":"מחכמי בריסק, נזכר ב\"גבעת שאול\" לר שאול מלומזה."},{"i":41533,"n":"קאט-שנפלד, מרדכי","k":"בעל דברי יושר","dt":"תרלז - כז טבת","b":"ראב\"ד בנייטרא"},{"i":41534,"n":"קאטליאר, אברהם מארה\"ב","f":"מיכאל","k":"בעל דרך ארץ החדשה","bp":"טראשקון-פלך קובנא","b":"תלמיד ר יוסף שאול מוילקומיר. היגר לארה\"ב-תרמח. מחכמי קליבלנד."},{"i":41535,"n":"קאטס, יוסף הלוי מהלובקי","f":"חיים הלוי","bt":"תרלו","dt":"תשג","b":"דרשן,רב פעלים,רב בווישינטא-תר\"ס,הלובקי-תרס\"ד"},{"i":41536,"n":"קאטץ, אליהו בר משקודוויל","b":"הקים ישיבה קטנה בשקודוויל-אחרי מלחה\"ע ה-I ועמד בראשה יחד עם ר שאול זקש. הישיבה משכה את אנשי הישובים הסמוכים שבאו לבקש בה חתנים לבנותיהם."},{"i":41537,"n":"קאטץ, חיים מרדכי מארה\"ב","f":"יעקב","r":"מייסד וראש ישיבת טלז' באמריקה","bt":"תרנד","bp":"שאדובה","dt":"תשכה - יב כסלו","dp":"ויקליף - ארץ ישראל","b":"תלמיד ישיבות סלובודקה, וולוזין, טלז. חתן ר יוסף יהודה בלוך מטלז. ממקימי המכינה לישיבת טלז, ומנהל כולל האברכים בטלז. ממיסיד תנועת צעירי אגודת ישראל, פעיל בתנועת \"יבנה\". הגיע לארה\"ב-תש והקים עם גיסו ר מאיר בלוך את ישיבת טלז בקליבלנד וכיהן שם כראש ישיבה. מאמר ממנו ב\"שעורי דעת\" - שנחאי תשו.","bk":[["באר מחוקק - על התורה, שיעורי דעת, שיחות, מאמרים",""]]},{"i":41538,"n":"קאיירי, יהודה מאזמיר","dt":"תקמד - ח סיון","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":41539,"n":"קאים, שלמה","b":"תלמיד ר בצלאל אשכנזי בעל \"שיטה מקובצת\". נזכר בספר החזיונות, ובשו\"ת מהר\"ב אשכנזי."},{"i":41540,"n":"קאים, שמעיה מאלגיר","b":"רב ומשורר באלגיר. קרובו של ר שלמה בן דוד קאים שנזכר אצל שד\"ל ב\"שם טוב\". נזכר ב\"אוצר השירה והפיוט\" לדוידזון."},{"i":41541,"n":"קאין, יהודה מעגערבעג'","f":"שמעון","k":"בעל מנוחת יהודה-תרפו","bt":"תרטז","dt":"תרפו - יט טבת","dp":"עגערבעג'","b":"תלמיד ר שמואל ארנפלד בבעטלען. ר משה קליין בסילאג-צ'ה, בישיבת מהריא\"ץ במארגרטן. חתן ר יצחק אויש מקלויזנבורג-תרמא. רב בכפר עגערבעג'-ליד קלויזנבורג. נפטר בדרכו לארץ."},{"i":41542,"n":"קאין, יוסף מקלויזנבורג","b":"רב בקלויזנבורג-תקטז."},{"i":41543,"n":"קאין, שלמה מאלגיר","f":"שמואל","bt":"ל - בערך","dt":"קך - בערך","b":"רב ודיין בתלמסאן, נזכר ע\"י הרשב\"ץ, וע\"י הרשב\"ש - בענין שטר שכתב."},{"i":41544,"n":"קאך, אנשל משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":41545,"n":"קאך, חיים מגוטנבורג","f":"אפרים","bt":"תרכז","b":"תלמיד ישיבת קולמר, שטרסבורג, ביהמ\"ד לרבנים בברסלוי, בעל תואר ד\"ר. רב בברמן, גוטנבורג-שבדיה-תרנט. חיבר פירוש למשלי."},{"i":41546,"n":"קאך, יהושע מקוסוב","k":"ר יהושע פלאקסאווע","dt":"תקסט - יג ניסן","b":"אחיו של ר שמואל שמחה זימל. כינויו \"פלאקסאווע\" = בעל בכי."},{"i":41547,"n":"קאך, יוסף מפרשבורג","f":"ליב","b":"חתם על תקנות הח\"ק בפרשבורג-תקס."},{"i":41548,"n":"קאך, יעקב משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":41549,"n":"קאך, יצחק","f":"יהושע קאך","dt":"תקפג - יז טבת","b":"איש מופת"},{"i":41550,"n":"קאך, שמואל שמחה זימל","f":"יצחק קאך","b":"חותן מנחםמנדל מקאסוב"},{"i":41551,"n":"קאלאוגרה, משה משלוניקי","f":"יצחק","b":"מדפיס בשלוניקי אצל אברהם בן דוד נחמן ויום טוב קאנפיליאש-תע."},{"i":41552,"n":"קאלאחורי, משה משלוניקי","dt":"רעט - כט אלול","dp":"שלוניקי","b":"ממגורשי ספרד ומחכמי שלוניקי, מוצאו מקאלאחורי-קסטיליה."},{"i":41553,"n":"קאלאמינש, יהושע אברהם משלוניקי","f":"שמחה","k":"בעל מילי דבדיחותא","b":"מחכמי שלוניקי. חיבר \"מילי דבדיחותא\" - שלוניקי שפ-בערך."},{"i":41554,"n":"קאלבו, אברהם מסרייבו","b":"רב בסרייבו-שץ."},{"i":41555,"n":"קאלבו, משה מאזמיר","b":"גזבר \"חברת יתומות\" של קהלת פורטוגל באזמיר-שנות ה-ת'."},{"i":41556,"n":"קאלהוראנו, חיים מספרד ופאס","b":"ממגורשי ספרד,כנראה בא לפאס"},{"i":41557,"n":"קאלהוראנו, עלאל מפאס","b":"מחכמי פאס-שנות ה-ש'."},{"i":41558,"n":"קאלהורה, מתתיה","f":"דוד הרוקח מקובנא","b":"נהרג עק\"ה לאחר ויכח עם נזיר דומיניקני-תחילת שנות ה-ש'."},{"i":41559,"n":"קאלהורנו, אפרים מפאס","b":"רב בפאס, חתם-תנח על תקנה יחד עם ר מנחם סירירו, ר וידאל הצרפתי, היעב\"ץ, ועוד."},{"i":41560,"n":"קאליו שיבא, רפאל אברהם מיאנינ","b":"דיין מחכמי יאנינה-יוון. התכתב עם ר יוסף מולכו (נפטר בתקכח)."},{"i":41561,"n":"קאליך, יהודה ליבש","b":"דומ\"צ בבילקא-תרע\"ד"},{"i":41562,"n":"קאלימטו, יצחק מירושלים","dt":"תקכב - טו טבת","dp":"ירושלים","b":"מחכמי ירושלים. נזכר ב\"לשון ערומים\"."},{"i":41563,"n":"קאלימרו, יעקב מירושלים","dt":"תרפד - ז שבט","b":"מרבני ירושלים,שד\"ר לערי תוגרמא"},{"i":41564,"n":"קאלימרו, יצחק מירושלים","dt":"תרטו - יח שבט","b":"מגדולי רבני ירושלים,שד\"ר בחברון"},{"i":41565,"n":"קאלימרו, יצחק מירושלים","f":"רפאל","dt":"תרמד - י תשרי","dp":"ירושלים","b":"מחכמי ירושלים ומראשי \"בית אל\", בשנת תרטז בשליחות ירושלים במרוקו. בשנת תריד בשליחות חברון. הגיה את הספר \"נהר שלום\" לר שלום שרעבי, ואת \"דברי שלום\" לר אברהם שלום שרעבי. חתם על פסקים בענין \"השר נסים שמאמא-תרלד, ועוד. הגיה \"שער רוח הקדש\" למהרח\"ו - ירושלים תרלד."},{"i":41566,"n":"קאלימרו, רפאל מירושלים","f":"יצחק","k":"בעל שיורי ברכה","dt":"תקצב - ב תמוז","dp":"ירושלים או מצרים","b":"תלמיד ר יעקב רפאל מנשה בלאריסה. מחכמי ישיבת \"בית אל\" בירושלים, הוציא לאור \"שיורי ברכה\" חדושי דינים מהחיד\"א עם הגהות ממנו - שלוניקי תקעד. תשובותיו בספר \"חקרי לב\" וב\"דברי שלום\" של חכמי דורו. דרשה ממנו בכת\"י בענין יציאת מצרים. בשליחות בבלקן, מצרים ושם פסק בענין ממזרים. התישב במצרים ולדעת גאון נפטר שם."},{"i":41567,"n":"קאלינא, ישראל יהושע ממגנישוב","b":"רב במגנישוב. פרסם מאמרים ב\"עמק הלכה\" - וארשא תרפו."},{"i":41568,"n":"קאלינא, מרדכי מוארשא","k":"בעל מכתבי תורה","b":"רב בוישעגראד-תרץ. פרסם מאמרים ב\"דגל התורה\" - וארשא תרפב, \"עמק הלכה\" - וארשא תרפו."},{"i":41569,"n":"קאליף, ברוך מפרשבורג","dt":"תקפו","dp":"פרשבורג","b":"תלמיד החת\"ס. נספה צעיר בזמן שלמד בישיבה (טבע כשהלך לטבול ערב שבועות בנהר)."},{"i":41570,"n":"קאליפארי, יעקב מפוזנא","f":"יצחק דיין","b":"דיין בפוזנא-תקץ, אצל ר עקיבא איגר."},{"i":41571,"n":"קאליפארי, יצחק מפוזנא","f":"יוסף דרשן","b":"דיין בפוזנא-תק\"י"},{"i":41572,"n":"קאליפארי, שלמה מלונשיץ","f":"ישראל שמואל קאליהארי","b":"רב בלונשיץ-ת\"י"},{"i":41573,"n":"קאלמארי, משה מאזמיר","b":"מראשוני המאמינים בשבתי צבי-תח."},{"i":41574,"n":"קאלמנוב, אשר מירושלים","b":"מראשי כולל קרלין בירושלים, חתם-תרמב עם ר אהרן משה שפירא."},{"i":41575,"n":"קאלפו, חיים כלב מאזמיר","b":"גביר באזמיר?-תקף-ץ בערך. סייע לישיבת \"מגן שאול\" ותרם ספרים."},{"i":41576,"n":"קאלפו, כלב מאזמיר","dt":"תעז - ד אלול","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":41577,"n":"קאלפו, משה מכיאו","b":"מראשי הקהלה באי כיאו-שנות ה-ת'."},{"i":41578,"n":"קאלפו, שמואל מאזמיר","b":"מחכמי אזמיר, תלמיד בישיבת ר חיים פלאג'י."},{"i":41579,"n":"קאלקיי, חיים מאזמיר","b":"מחכמי אזמיר-שנות ה-ת'."},{"i":41580,"n":"קאם, חיים שלמה","f":"שמעון זימל","k":"בעל ויבן שלמה","dt":"תרצב - ל אד\"א","b":"רב ברציצא(=רעציצע). חיבר גם \"חיי שלמה\" בכת\"י עם הסכמות מגדולי דורו. מתורתו ב\"דברי מלכיאל\" לר מלכיאל צבי הלוי מלומזה.","bk":[["ויבן שלמה","חולין-יור\"ד"]]},{"i":41581,"n":"קאמונדו, אברהם מוינה","b":"גביר מראשי ומיסדי עדת יהודי תוגרמה בוינה-תעח (על פי הסכם השלום בין האוסטרים לתורכים)."},{"i":41582,"n":"קאמונדו, אברהם מקושטא","dp":"פאריס - קושטא","b":"גביר בקושטא, תמך ביהודי ארץ ישראל, בסוף ימיו עבר לפאריס. בניו: בכור, נסים המשיכו את פעילותו לטובת היהודים אחריו. אחיו - ר יצחק מקושטא שנפטר ללא ילדים והוריש את רכושו לאחיו."},{"i":41583,"n":"קאמונדו, חיים מקושטא","f":"אברהם","b":"מחכמי קושטא-שנות ה-תק'. אחיו - ר שלמה בעל \"נהרות דמשק\"."},{"i":41584,"n":"קאמונדו, יצחק מקושטא","b":"גביר בקושטא, נפטר ללא ילדים והוריש את רכושו לגביר הנדיב אברהם."},{"i":41585,"n":"קאמונדו, משה מקושטא ופאריס","dt":"תרצה","dp":"פאריס","b":"גביר בקושטא, עבר לפאריס, תרם אוסף אמנות חשוב לממשלת צרפת, בנו הרוזן נסים נהרג במלחה\"ע ה-I."},{"i":41586,"n":"קאמונדו, נסים מקושטא","dt":"תרמט - אדר","dp":"קושטא","b":"גביר בקושטא, תרם הרבה."},{"i":41587,"n":"קאמונדו, רפאל שלמה מקושטא","f":"אברהם","bt":"תקסח","bp":"קושטא","dt":"תרכו - י טבת","dp":"קושטא","b":"גביר בקושטא, נזכר ב\"הלבנון\"."},{"i":41588,"n":"קאמונדו, שלמה מקושטא","f":"אברהם","k":"בעל נהרות דמשק","b":"גביר ודיין מחכמי קושטא, עלה לארץ-תקס. חיבר \"נהרות דמשק\" וחלק שני בשם \"בן משק\", והיו בכת\"י בידי ר משה מרדכי מיוחס (נדפסו בשלוניקי תקסב). עסק במסחר ונסע לאמשטרדם-תקכה ושם סייע בהדפסת \"פאר הדור\" לר מרדכי תמה. היה מחלוקת בינו לבין ר מרדכי בכמוהר\"ר מנחם בענין עסקי."},{"i":41589,"n":"קאמונדו, שמואל גיליבי","k":"בעל נהרות דמשק","b":"חכם הכולל,מגדולי שאלוניקי-תק\"מ (כנראה טעות)"},{"i":41590,"n":"קאמין, דוד מבאדקי","f":"חיים צבי","k":"בעל בית דוד","bt":"תרד","dt":"תרפב","dp":"ירושלים","b":"שו\"ב בבאדקי, טשכונאוצי (טשרנוביץ?), חיבר \"בית דוד\" ורשה תרסב, בשנת תרעג עלה לירושלים."},{"i":41591,"n":"קאמיסער, פנחס מראסיין","f":"שלמה זלמן מראסיין","dt":"תרנז - כז אדר","dp":"ראסיין","b":"נכד(-אבי אמו) ר מנחם מנדל מראסיין וגירטעגאלי. אב\"ד ושו\"ב בגראפסקאי-מושבה יהודית בפלך יקטרינסלב."},{"i":41592,"n":"קאמפוס, יוסף מרדכי מסרייבו","dt":"תרעג - ט אב","dp":"ירושלים","b":"גביר מחכמי סרייבו, עלה לירושלים והיה גבאי ישיבת \"שבחי ירושלים\" לעולי בוסניה."},{"i":41593,"n":"קאמפיליאש, יוסף משלוניקי","dp":"שלוניקי","b":"מחכמי שלוניקי"},{"i":41594,"n":"קאמפיליאש, יצחק משלוניקי","f":"משה","dt":"שעז - כח שבט","dp":"שלוניקי","b":"דיין בשלוניקי, חתם על קבת עדות אצל ר שלמה ן חסון-שעה."},{"i":41595,"n":"קאמפיליאש, שם טוב משלוניקי","b":"תלמיד ר שמואל חיון. ש\"ץ בשלוניקי-שע."},{"i":41596,"n":"קאמראז, צבי יצחק מאספאלע","b":"אב\"ד אספאלע-ליטא. גיסו ר שלום ליב זינובר בעל דברי שלום."},{"i":41597,"n":"קאנדל, חיים מספינקא","f":"אריה","k":"הו\"ל פלח הרימון-תרצב","dt":"תש..","b":"חסיד ספינקא. נכד ר חיים קאנדל שהיה שו\"ב בכפר רעמיט-ליד ספינקא. תלמיד ישיבת ספינקא אצל האדמור ר אברהם אביש הורביץ, חתן ר בןציון שכטר מקרעטשנוף. הו\"ל \"פלח הרימון\" לר בצלאל מסלוצק עם קונטרס \"הוספת חיים\" ממנו - סעאיני תרצב. נספה בשואה."},{"i":41598,"n":"קאנדל, חיים מרעמיט","b":"חסיד ספינקא. שו\"ב בכפר רעמיט-ליד ספינקא."},{"i":41599,"n":"קאנווי","k":"ראה: אלקנווי","b":"מגדלי חכמי ירושלים-רפ\"ד"},{"i":41600,"n":"קאנוויסר, שמעון יצחק הלוי מלונ","b":"שו\"ב בלונדון. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה, \"בית ועד לחכמים\" - לונדון תרסב."},{"i":41601,"n":"קאנטארי, שלמה משלוניקי","b":"מחכמי שלוניקי-רפ."},{"i":41602,"n":"קאניזשא, אשר זליג מסעט-פעטר","f":"יוסף","bt":"תקנז","bp":"קעניערעש","dt":"תקץ - י שבט","dp":"סנט-פעטר","b":"תלמיד החת\"ס. רב באלמאשד-תקעט, סנט-פעטער-תקפג על מקום ר אברהם צבי הכהן."},{"i":41603,"n":"קאניטשער, אברהם מבענדר","f":"יחיאל ברוך","bt":"תרכח","bp":"בענדר","b":"רב בבענדר-בסרביה-תרסג."},{"i":41604,"n":"קאניצי, בנימין ממצרים","b":"רב במצרים-שנות ה-ש', חתם עם ר יעקב קשטרו על פס\"ד."},{"i":41605,"n":"קאניצר, הלל","dt":"תריח","b":"רב בבעלעד-תקצ\"ח"},{"i":41606,"n":"קאנן, יוליוס מפרשבורג","b":"עסק בהצלת יהודים בראשית ימי השואה - תרצח."},{"i":41607,"n":"קאנפילייאש, יום טוב משלוניקי","f":"משה","b":"מדפיס בשלוניקי-תנד עם ר אברהם בן דוד נחמן."},{"i":41608,"n":"קאנפילייאש, יוסף משלוניקי","f":"יעקב","dt":"תקח","dp":"שלוניקי","b":"מחכמי שלוניקי. מדפיס-תקב אצל בצלאל הלוי אשכנזי, הכין לדפוס \"מטה אשר\" לר אשר שלם."},{"i":41609,"n":"קאסטילו, יעקב מאמשטרדם","b":"מחכמי אמשטרדם, הדפיס-תך עם ר אפרים בואינו את השו\"ע."},{"i":41610,"n":"קאסטילנובו, מנחם עזריה מאיר","f":"אליהו","k":"בעל מסגרת השלחן","bt":"תקלב","bp":"סיינה-איטליה","dt":"תרז - א אייר","dp":"ליוורנו","b":"עבר לליוורנו והיה סופר בבית הגביר יהושע ריקנטי, רב בסיינה, פדובה, ראש ישיבה בליוורנו-תקפד. חיבר גם \"עמק המלך\".","bk":[["מסגרת השלחן – יו\"ד",""],["עמק המלך - שו\"ת",""],["עמק המלך","שו\"ת"]]},{"i":41611,"n":"קאסלרי","f":"דוד","k":"בעל מאמר בקדחת הדבר ראה: קשלרי","b":"רופא בביזאלו-קטלוניה. חיבר ספרים ברפואה, ובהם על מגפת הדבר-1348, \"המסעדים\", \"עלה רענן\", ועוד. ר קלונימוס בן קלונימוס הקדיש לו את ספרו \"אבן בחן\"."},{"i":41612,"n":"קאפאדוש, אהרן מאמשטדם","b":"גביר באמשטרדם-תקלז בזמן ביקור החיד\"א."},{"i":41613,"n":"קאפואנו, אנגל משלוניקי","dt":"שה - כב אלול","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":41614,"n":"קאפואנו, יהודה משלוניקי","f":"יוסף","dt":"תרטז - ה סיון","dp":"שלוניקי","b":"דיין בשלוניקי-תרטו."},{"i":41615,"n":"קאפון, אברהם אהרן","bt":"תריג","bp":"בוקרשט","dt":"תרצא - כח אלול","dp":"סרייבו","b":"פרסם מאמרים וחתם לפעמים אב\"ק, מטיף וש\"ץ בקהלות בולגריה. הו\"ל \"לה אלבוראדה\"-תרנח, עבר לסרייבו."},{"i":41616,"n":"קאפון, יהושע מרוסג'וק","b":"מאנשי קהלת רוסג'וק-תקס בערך."},{"i":41617,"n":"קאפון, יוסף מוידין","b":"מחברי החברא קדישא בוידין-תקלג, עם הרופא חיים דוד בן גבריאל."},{"i":41618,"n":"קאפון, משה משלוניקי","dt":"רצז - כא אייר","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":41619,"n":"קאפון, שלמה מוידין ורוסג'וק","b":"מחכמי וידין, ברח לרוסג'וק-תקס."},{"i":41620,"n":"קאפון, שלמה מקושטא","b":"מחכמי קושטא, חברו של ר רפאל ביטראן המזכירו ב\"זכור לטוב\"."},{"i":41621,"n":"קאפוס, מורה מסודיטץ","b":"רב בסודיטץ-תרס\"ד"},{"i":41622,"n":"קאפושוואר מאראד","b":"רב ניאולוגי באראד במאה ה-19."},{"i":41623,"n":"קאפח, דוד מתימן וירושלים","f":"סעיד","b":"מקובל מחכמי תימן, עלה לארץ ובדרכו נתעכב במצרים וכיהן כדיין. עלה לירושלים וכיהן כדיין בקהילה התימנית בירושלים. חתם-תרפו על איסור להשתתף בבחירות. מחכמי \"בית אל\", ורב ביהכ\"נ נחום בשכונת שערי פינה, ור סעיד שריאן על מקומו אחריו כרב בביהכ\"נ."},{"i":41624,"n":"קאפח, חיים מצנעא-תימן","f":"חיים","k":"בעל עטרת חיים","bt":"תרעו","bp":"צנעא","b":"עלה לא\"י,חיבר \"עטרת חיים\" פירוש על התורה"},{"i":41625,"n":"קאפח, יוסף מירושלים","b":"רב ודיין בתימן, ירושלים."},{"i":41626,"n":"קאפח, יחיא מצנעא-תימן","f":"סולימן","bt":"תרי-כ","dt":"תרצב - יא כסלו","b":"מקובל,מרביץ תורה,רב בצנעא"},{"i":41627,"n":"קאפח, יחיא מתימן","b":"רב בדומאר(תימן)"},{"i":41628,"n":"קאפח, יחיא מתימן","f":"יחיא אלקפח","dt":"תרעא","b":"רב ברצאבה(תימן)"},{"i":41629,"n":"קאפטאן, שמעון מוילנא","dt":"תרכה","b":"גביר ונדבן מפורסם בוילנא."},{"i":41630,"n":"קאפילוטו, חיים מירושלים","f":"רחמים","b":"נכד ר יעקב ויורשו. מחכמי ירושלים-תרמז, וחתם על הסכמות שונות."},{"i":41631,"n":"קאפילוטו, יעקב מירושלים","f":"יצחק","k":"הו\"ל תקנות ירושלים","bt":"תקעא","bp":"רודוס","dp":"מצרים","b":"מחכמי ירושלים, מתלמידי ר אברהם חיים גאגין. בשנת תקצט בשליחות בתורכיה וצפון אפריקה. בשנת תרב היה מעורכי הספר \"תקנות ירושלים\". בהמשך היה ראש בית הדין לספרדים בירושלים. בשנת תרכד בשליחות במצרים ושם נפטר."},{"i":41632,"n":"קאפל מרודיק","f":"משה מסאמבור","b":"רב ברודיק-ת\"ר"},{"i":41633,"n":"קאפלס, יוסף מפרג","f":"משה","b":"נמנה על החתומים (פרנומרנטן) על \"קול קול יעקב\" - תקסב. הניח חדושים על הש\"ס בכת\"י."},{"i":41634,"n":"קאפסוטו, דניאל מצפת","bp":"איטליה","b":"עלה לצפת בשנת תעה, והיה מחכמי צפת, בשנת תעח הסכים על ספר \"הון עשיר\" לר עמנואל חי ריקי, בשנת תפא חתם עם חכמי צפת על כתב שליחות לר משה ישראל ברודוס. בשנת תפב בשליחות צפת. בשנת תפח חתם על כתב שליחות ר רפאל ישראל קמחי."},{"i":41635,"n":"קאפסוטו, דניאל מצפת","b":"בשליחות קהילת צפת. נזכר ב\"הון עשיר\"."},{"i":41636,"n":"קאפסון, ברוך מנחם מנדל בן ציון","f":"שאול","bt":"תרכז","b":"רב בשלובשנה(=שלאוועשניא)-ווהלין-תרנו."},{"i":41637,"n":"קאפף, אברהם","f":"שמואל בן יהודה","b":"מחכמי ברצלונה-קנ. חתם עם אחיו ר יצחק על החרם נגד הפילוסופיה."},{"i":41638,"n":"קאפף, אברהם הצרפתי מטולידו","b":"בן למשפחה צרפתית בספרד. מחכמי טולדו בזמן הרשב\"א ובזמן קרוב משפחתו ר אברהם בן יצחק קאף שהיה מחכמי ברצלונה."},{"i":41639,"n":"קאפף, אברהם מברצלונה","f":"יצחק","b":"מחכמי ברצלונה בזמן הרשב\"א, וחתם על כמה מתשובותיו."},{"i":41640,"n":"קאפף, יעקב אשר מערלוי וירושלים","dt":"תרצה - כו תשרי","dp":"ירושלים","b":"גדל בערלוי(=אויהל), וכשהגיע שליח ארץ ישראל - ר טוביה גולדברגר לערלוי(=אויהל), התאכסן אצל אביו ר יצחק ור יעקב אשר שהיה נער צעיר החליט להצטרף אליו בחזרתו לארץ - בהסכמת הוריו. תלמיד כולל אונגרן בירושלים, ישיבת \"תורת חיים\", \"שער השמים\" אצל המקובל ר שמעון צבי הורביץ."},{"i":41641,"n":"קאפף, יצחק","f":"שמואל בן יהודה","b":"מחכמי ברצלונה-קנ. חתם עם אחיו ר אברהם על החרם נגד הפילוסופיה."},{"i":41642,"n":"קאפף, יצחק מערלוי","f":"אברהם","k":"בעל עין הבדולח","dt":"תרפט - ט חשון","b":"תלמיד ר חיים צבי מנהיימר באונגואר. רב ודיין בערלוי(=אויהל) אצל ר שמעון סופר. גבאי כולל הונגריה בא\"י. חיבר גם \"לקיטת יצחק בן אברהם\". בנו - ר יעקב אשר."},{"i":41643,"n":"קאפף, נחמן","dt":"תשג","b":"רב בהיינובקה"},{"i":41644,"n":"קאפף, עקיבא מספרד","b":"מחכמי ספרד בזמן הר\"ן. תלמיד ר יהודה בן הרא\"ש."},{"i":41645,"n":"קאץ, מיכאל ממאלטיץ","f":"אבלי","bt":"תריז","b":"רב במאלטיץ-פלך מוהילוב-תרמח."},{"i":41646,"n":"קאץ, שמואל הלל הכהן מראייגראד","f":"מרדכי גימפל","k":"בעל מעיל שמואל","bt":"תרלב-ד","b":"רב ברייגראד(=רייגרוד)-פלך לומזה-תרסב. נסמך מאת: ר יהודה ליב גורדון מסמרגון בעל \"דגל יהודה\", ר יהושע לאינג משערשוב בעל \"עץ יהושע\", ר חיים הרץ הלפרין מביאליסטוק. גיסו של ר צבי סלאבאדקער מירושלים."},{"i":41647,"n":"קאר, דב","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":41648,"n":"קארא, יצחק איזיק מברלין","f":"ש'","b":"חתן ר אברהם איגר מראויטש-בכורו של ר עקיבא איגר מפוזנא. מחכמי ברלין. קיבל מחותנו את כתה\"י של הגהות ר עקיבא איגר על השו\"ע, והוציאם לאור במהדורה תנינא."},{"i":41649,"n":"קארא, נפתלי משרימס","b":"רב בשרימס-ת\"ר"},{"i":41650,"n":"קארא, צבי מלאבוי","f":"נפתלי משרימס","dt":"תרנד - כב אלול","dp":"המבורג","b":"מצאצאי ר יוסף קארו. תלמיד ר שלמה פלסנר מפוזן, ר שלמה יהודה רפפורט מפרג, נסמך מאת: ר יעקב צבי מקלנבורג. רב בלאבוי, בסוף ימיו עבר לברמרהאפן."},{"i":41651,"n":"קאראוידה, יצחק הלוי משלוניקי","dt":"רצו-ז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":41652,"n":"קאראלי, ישראל אשר מפרוינקירכן","f":"צבי מטורנא","k":"בעל בני ישראל","bt":"תרעג","bp":"טורנא","dt":"תשה - כז תשרי","b":"תלמיד הדעת סופר, ור שמואל שוורץ מקאשוי, ור שמואל דוד אונגר מנייטרא ור יואל טיטלבוים מסטמר. חתן ר יעקב יוסף זינגר ממאראש-ואשארהעלי. רב בפרוינקירכן על מקום חותנו זקנו - ר משה שמעון הלוי. נספה בשואה. פרסם מאמרים ב\"הלכות החדש\" - טירוני תרצא - קובץ מאת תלמידי ר שמואל דוד אונגר מטירנוי."},{"i":41653,"n":"קארבליו, יצחק","f":"מרדכי ברוך","bt":"תצא","dt":"תקיט","b":"נפטר בגיל 28. חיבר \"ספר הזכרונות וחיי יצחק\" נדפס לזכרו ע\"י אביו בעל \"תועפות ראם\"."},{"i":41654,"n":"קארבליו, מרדכי ברוך מתונס","k":"בעל תועפות ראם","dt":"תקמה","dp":"תונס","b":"תלמיד ר יצחק לומברוזו בעל \"זרע יצחק\", וכיהן כדיין בתונס אצל רבו-תקיח. רב בק\"ק פורטוגל בתונס על מקום רבו, והתפרנס ממסחר ולא מהרבנות. בנו ר יצחק נפטר בחייו, חתנו - ר יצחק אלחאייך הספידו בספרו \"מערתא דדייני\", וכיהן על מקומו אחריו. חיבר גם \"מירא דחיא\"."},{"i":41655,"n":"קארדניאל, יהודה","f":"יצחק","b":"תרגם את ספר הכוזרי-שנות ה-תתק', ונדחה מפני תרגומו של ר יהודה ן תבון."},{"i":41656,"n":"קארה, שלמה מתימן","f":"יוסף - זבחי אלקים","bt":"[תקסד]","bp":"צנעא","dt":"תרמט - ח אלול","dp":"צנעא","b":"רב ראשי בצנעא-תרט על מקום אביו. ברח מאימת השלטונות לקרית אל-קאבל-תריט, לאחר הכבוש התורכי-תרלב חזר לצנעא ונתמנה ל\"חכם באשי\", ופעל רבות למען אחיו בזכות קשריו עם השלטון."},{"i":41657,"n":"קארו, אברהם מאדרינופול","f":"רפאל","k":"בעל אם למקרא","b":"מצאצאי ר יוסף קארו. תלמיד (וגדל בביתו) ר אליעזר ן נחום, ונזכר בספרו \"חזון נחום\". רב באדרינופול-תק. חיבר קונטרס על \"אם למקרא\". נפטר צעיר."},{"i":41658,"n":"קארו, אברהם מקאליש ושלוניקי","f":"יצחק","b":"מדפיס בקושטא-של אצל דוד אזוביב."},{"i":41659,"n":"קארו, איסטילה משלוניקי","b":"מנהלת ביה\"ס כי\"ח לבנות בשלוניקי-תרלה."},{"i":41660,"n":"קארו, אפרים מספרד וירושלים","f":"יוסף בן אפרים","b":"מגדולי חכמי ספרד, יצא לניקופול-רנב, עלה לירושלים. אביו של ר יוסף בעל ה\"שלחן ערוך\". בשנת רסט חתם על תקנה לשחור תלמידי חכמים מתשלום מס. אחיו של ר יצחק בעל \"תולדות יצחק\". בנו - ר יצחק מירושלים."},{"i":41661,"n":"קארו, דוד מברוד","f":"יצחק","k":"בעל אהל רחל","bt":"תק","bp":"ברודי","dt":"תקס","b":"רב בברודי-תקם. חיבר \"אהל רחל\" שקלוב תקן."},{"i":41662,"n":"קארו, דוד מפוזנא","b":"חיבר \"ברית אמת\" ובו \"ברית אחים\", ו\"ברית בית אל\" על מנהגי הריפורמים, \"נקם ברית\" ובו יצא כנגד תקנות בי\"ד המבורג בספר \"אלה דברי הברית\"."},{"i":41663,"n":"קארו, ידידיה משלוניקי","f":"יהודה","bt":"שס","bp":"שלוניקי","dt":"תיט - יז תמוז","dp":"שלוניקי","b":"נכד ר יוסף קארו. תלמיד ר מרדכי קלעי בשלוניקי, עבר למנטובה."},{"i":41664,"n":"קארו, ידידיה משלוניקי","f":"שלמה קארו","b":"מגדולי חכמי שאלוניקי"},{"i":41665,"n":"קארו, יהודה","f":"יצחק קארו","b":"רב באדרינופולי"},{"i":41666,"n":"קארו, יהודה מצפת ושלוניקי","f":"יוסף - בית יוסף","b":"מגדולי חכמי צפת, שלוניקי. הו\"ל שו\"ת אביו. אולי היה בן נוסף באותו השם - שנפטר צעיר."},{"i":41667,"n":"קארו, יוסף - בית יוסף","f":"אפרים","k":"בעל בית יוסף","bt":"רמח","bp":"ספרד","dt":"שלה - יג ניסן","dp":"צפת","b":"גורש מספרד עם משפחתו ועברו לקושטא, שם למד אצל אביו ודודו ר יצחק. היה רב באדרינופול חתן ר חיים אלבלג, בזיוו\"ש חתן ר יצחק סבע מאדרינופול, ובזיוו\"ש חתן ר זכריה אשכנזי מירושלים. התגורר בניקופול (בולגריה) ועלה לצפת דרך מצרים. נסמך על ידי ר יעקב בירב. יסד ישיבה ועמד בראש בית הדין. חיבר שולחן ערוך ובית יוסף ועוד."},{"i":41668,"n":"קארו, יוסף מספרד","b":"רב בטולידו-ריח. בניו - ר יצחק, ר אפרים, ונכדו ר יוסף בעל \"בית יוסף\"."},{"i":41669,"n":"קארו, יוסף משלוניקי","dt":"שפ - כו תמוז","dp":"שלוניקי","b":"גביר מחכמי שלוניקי."},{"i":41670,"n":"קארו, יוסף משלוניקי","dt":"שפב - יח אב","dp":"שלוניקי","b":"מחכמי שלוניקי. נפטר צעיר."},{"i":41671,"n":"קארו, יצחק מירושלים","f":"אפרים-מספרד וירושלים","k":"בעל תולדות יצחק","dt":"שיח - לפני","b":"רב בירושלים-שנות ה-ש'. (לדברי רוזניס הוא המחבר תולדות יצחק והוא שהיה דודו של ר יוסף קארו - לא מסתדר עם התאריכים ועם שם אביו)."},{"i":41672,"n":"קארו, יצחק מספרד וקושטא וירושל","f":"יוסף","k":"בעל תולדות יצחק","bt":"ריח","bp":"טוליטולא (ספרד)","dt":"רצה","dp":"ירושלים","b":"תלמיד ר יצחק קנפנטון בספרד, וכן למד רפואה. מחכמי ספרד, כיהן כרב בליסבון-עוד לפני גירוש ספרד וקלט את אביו ובני משפחתו שגורשו מספרד, עבר לקושטא לאחר גירוש פורטוגל, עלה לירושלים. חיבר \"תולדות יצחק\" קושטא רעד. בזמן הגירוש נפטרו ילדיו. כתביו עברו לבנו ר יוסף-הבית יוסף ולנכדו ר יהודה, וכמה מתשובתיו בספר השו\"ת של ר יוסף קארו."},{"i":41673,"n":"קארו, יצחק מקושטא","f":"שלמה","b":"רופא מחכמי קושטא-שנות ה-ש'. בעל ספריה חשובה."},{"i":41674,"n":"קארו, רפאל מאדרינופול","f":"שלמה","b":"נכד ה\"בית יוסף\". רב באדרינופול-שצ, נזכר אצל ר חיים שבתי משלוניקי."},{"i":41675,"n":"קארו, שלמה מקושטא","f":"יוסף - בית יוסף","bt":"ש","bp":"צפת","dt":"שפו או שפ","dp":"קושטא ?","b":"נכד ר יצחק סבע. גיסו של ר יוסף מטרני, למד אצל אביו, בשליחות אביו באיטליה, רב באזמיר-שכח, נזכר בשו\"ת ר יחיאל בסאן. חזר לצפת עד בשנת שסד עבר לקושטא. היה מחלוקת בין רבני צפת בענין יבום אשת אחיו ר יצחק שנפטר ללא ילדים. בניו (כנראה): ר רפאל מאדרינופול, הרופא החכם ר יצחק קארו מקושטא היה בנו (ארזי הלבנון), ויתכן שר אברהם קארו בן רפאל מאדריאנופול היה נכדו."},{"i":41676,"n":"קארו, שמואל","dt":"תרלה - ו סיון","b":"רב בציזלברג"},{"i":41677,"n":"קארו, שמואל ממרוקו - א","b":"מקובל,מגדולי חכמי מרוקו-ק\"צ"},{"i":41678,"n":"קארו, שמואל מסאלי וראבאט-מרוקו","f":"שלמה","dt":"תקט - אחרי","b":"רב ברבאט-סאלי-תקט, ודיין עם ר אליעזר דאבילא, וחתנו ר עיוש אלמליח על מקומו אחריו. והסכים על \"חפץ ה'\" לר חיים ן עטר בעל \"אור החיים\", וכנראה היה חברו. תשובותיו בספרי חכמי דורו. היה מהמתנגדים לר שמואל זאווי במחלוקת השחיטה, ובמחלוקת הדיינות בסאלי, יחד עם היעב\"ץ ורבני מכנאס. נזכר במורה צדק ביעקב, חתם ב\"חפץ השם\", ו\"כתר תורה\". חתנו - ר עיוש אלמליח מסאלי."},{"i":41679,"n":"קארוג'י, יהודה מאלגיר","b":"רב באלגיר, עלה לארץ-תקף והתישב בצפת. בשליחות חברון במרוקו-תקצב."},{"i":41680,"n":"קארי, אברהם יצחק משטמפן","b":"מחכמי שטמפן, חתם-תריב על מינוי ר אליעזר וינטר לרב בשטמפן."},{"i":41681,"n":"קארי, שמואל משטמפן","b":"מחכמי שטמפן, חתם-תקעו על כתב רבנות ר מרדכי בנט."},{"i":41682,"n":"קאריאון, יצחק","f":"שלמה","b":"רב מחכמי יון. תשובה ממנו ב\"משפטי שמואל\" לר שמואל קלעי."},{"i":41683,"n":"קאריאון, שמואל מקאבאלה","b":"רב בקאבאלה-שנות ה-ש'. (אולי הוא שהיה דיין בשלוניקי)."},{"i":41684,"n":"קאריאון, שמואל משלוניקי","b":"דיין בשלוניקי-שנג - יחד עם חבריו ר יצחק מיוני ור דוד משה שמשון."},{"i":41685,"n":"קאריגל, אברהם יצחק שאול","bt":"תקנג","bp":"חברון","b":"מחכמי חברון-תרכ\"ב"},{"i":41686,"n":"קאריגל, אברהם מחברון","b":"מחכמי חברון. בשנת תקכח חתום על כתב שליחות של ר דוד בן מארג'י"},{"i":41687,"n":"קאריגל, אברהם מירושלים","f":"דוד","b":"דיין בעדת הספרדים בירושלים-תלה, שו\"ב בזמן ר אברהם יצחקי. בשליחות באיטליה-תם ותורכיה. היה חתנו של ר אברהם רויגו. עשה הגהות ל\"ימין משה\" לר משה וינטורה. בנו - ר חיים משה קאריגל."},{"i":41688,"n":"קאריגל, דוד מירושלים","b":"מגדולי חכמי ירושלים-ת\"י"},{"i":41689,"n":"קאריגל, חיים משה מירושלים","f":"אברהם","k":"בעל ימין משה","b":"מחכמי ירושלים-תעב, חתנו של ר אברהם רוויגו. קרוב לר אברהם יצחקי. הביא לדפוס את ספרו של ר משה וינטורה \"ימין משה\"."},{"i":41690,"n":"קאריגל, נחמיה מחברון","b":"מחכמי חברון, בשנת תקכג חתם על כתב שליחות ר חיים באגאיו ור יצחק זאבי."},{"i":41691,"n":"קאריגל, רפאל חיים יצחק מחברון","bt":"תצג","bp":"חברון","dt":"תקלז - יב אייר","dp":"ברבדוס - ולא סורינם","b":"דרשן מחכמי חברון תלמיד ר דוד מלמד, בשנת תקיד בשליחות בארצות המזרח, והתעכב בלונדון ולימד שם תורה. בשנת תקיז בשליחות באירופה, והיה גם בקורסאו-אמריקה והתעכב שם כשנתיים, בשנת תקכח בשליחות בלונדון ובאמריקה והיה בג'מייקה, סורינום, קנדה וארה\"ב - והתעכב שם כמה שנים, ולבסוף כיהן כרב בברבאדוס עד לפטירתו. בהיותו בניו פורט פגש את החכם הנוצרי עזרא סטילס, והתידד אתו, והתכתב עמו בעברית בענינים שונים ובהם אודות המשיח, וסטילס בזכרונותיו מספר בשבח ידידו זה."},{"i":41692,"n":"קאריגל, שמואל מחברון","b":"מחכמי חברון, בשנת תקי חתם על קבלת כספים, בשנת תקלה חתם על כתב שליחות ר משה הכהן סקלי."},{"i":41693,"n":"קאריו, אברהם שמואל","bt":"תקנג","bp":"חברון","dt":"תרכב - אחרי","b":"מחכמי חברון-תקצט, חבר בבית דינו של ר משה פיררה, היה בין החותמים על הקמת ישיבת מגן אבות"},{"i":41694,"n":"קאריו, דוד אברהם חיים מירושלים","dt":"תריט - י-טז שבט","dp":"ירושלים","b":"מחכמי ירושלים, חתם על שטר התקשרות עם הד\"ר אוגוסט לודויג פרנקל אודות ביה\"ס שלו."},{"i":41695,"n":"קאריו, יהודה","b":"מחכמי חברון, בשנת תקצט חתם על סדרי הכוללות."},{"i":41696,"n":"קאריו, יוסף יהושע מירושלים","f":"דוד אברהם חיים","k":"בעל בני יוסף","bt":"תקסז","bp":"ירושלים","dt":"תרמג - י אלול","dp":"אזמיר","b":"מחכמי ירושלים וחברון, חתן ר משה יום טוב, וחותנו של ר אברהם עוזיאל. היה ראבד בירושלים. חיבר \"בני יוסף\" נדפס בסוף \"כפי אהרן\" ירושלים תרמו. בשנת תרד חתם על הסכם בקהלה הספרדית. נספד בספר \"אברהם את ידו\"."},{"i":41697,"n":"קאריו, נסים חיים מחברון","b":"מחכמי חברון. חתם שני לר סלימן מנחם מני-תרסז. וחתם גם עם ר חיים חזקיהו מדיני."},{"i":41698,"n":"קאריליו, יוסף מברוסה","b":"רב בברוסיה-ת'."},{"i":41699,"n":"קארמונה, אברהם מירושלים","dt":"תצט","dp":"ירושלים","b":"מחכמי ירושלים. נספד בספר \"שמע יעקב\" לר יעקב אלגזי"},{"i":41700,"n":"קארמונה, אליהו מקושטא","b":"חתן ר חזקיה אלפנדרי. גביר מחכמי קושטא-שנות ה-תק', החזיק ישיבה בביתו. אחיו - משה. בניו - יצחק, משה, חזקיה, (בחלק ה רוזניס מכנה את יצחק בכור בטעות שלמה)."},{"i":41701,"n":"קארמונה, ג'יליבי בכור יצחק","f":"אליהו","bt":"תקלג","bp":"קושטא","dt":"תקפו - תמוז","dp":"קושטא","b":"נכד ר יצחק קארמונה. גביר מראשי קהלת קושטא-תקצה. בניו - אליה, דוד, חיים, אהרן ונסים, ועוד 4 בנות."},{"i":41702,"n":"קארמונה, יהודה ראובן משלוניקי","b":"מחכמי שלוניקי."},{"i":41703,"n":"קארמונה, משה מקושטא","bt":"תמב","b":"גביר מחכמי קושטא-שנות ה-תק', סייע בהדפסת \"דברי חפץ\"-תקנה, \"נר מצוה\" לר יהודה ן סיד. בנו - אליהו נפטר בחיי אביו, אחיו - אליהו."},{"i":41704,"n":"קארמונה, שלמה","b":"מתומכי ש\"ץ, טען שנגלה אליו אליהו הנביא בענין ש\"ץ."},{"i":41705,"n":"קארנוואסער, יחזקאל ישראל","b":"מחכמי סוסנוביץ. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ."},{"i":41706,"n":"קארנוואסער, ישכר דב מרדכי","b":"מחכמי סוסנוביץ. פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":41707,"n":"קארניק, משה מגלוגא","b":"מ\"מ בגלוגא. חיבר \"אבל יחיד\" - ברסלוי תקף - הספד על ר אברהם טיקטין מברסלוי. אולי בנו - ר משה ברל\"ש מאמשטרדם, בעל \"הדרי קודש\" ו\"עזרת הסופר\"."},{"i":41708,"n":"קארפ, אלחנן בנציון מניו יורק","k":"בעל בית ציון","b":"חתן אב\"ד סלוצק. רב בניו יורק. חיבר \"בית ציון\" נ\"י תרפא."},{"i":41709,"n":"קארפ, יעקב ישראל מזוויהל בוסטו","f":"מרדכי מאטלי","k":"אדמור מזוויהל בוסטון","bt":"תרמ-ג","bp":"מזיבוז","b":"תלמיד ישיבת נווהרדוק. נסמך מאת: ר יחיאל מיכל אפשטין, ר רפאל מבוברויסק, ר מרדכי אשמינר מסלונים, ר אלתר קונסטינר. חתן ר יחיאל מיכל מקוריץ (ולאחר שנהרגה אשתו בידי הבולשביקים - נשא את אחותה). רב בזוויהל-ווהלין, עבר לארהב-תרפד וכיהן כרב ואדמור בבוסטון-תרפד. נסמך מאת: ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\", ר מרדכי מסלונים, ר אהרן זאב וייל מקיוב. חיבר \"מקוה ישראל\" ו\"נצח ישראל\"."},{"i":41710,"n":"קארפ, מרדכי מטלי ממזיבוז","k":"אדמור ממזבוז","b":"אדמו\"ר ממזיבוז-תר\"נ"},{"i":41711,"n":"קארפ, שמואל יצחק מזוויהל","f":"יעקב ישראל מזוויהל","k":"אדמור מזוויהל ארהב","dt":"תשלה","dp":"בוסטון","b":"חתן ר יוסף מאיר ממחנובקא (טשרנוביל). אדמור מזוויהל בארה\"ב על מקום אביו."},{"i":41712,"n":"קארפ, שרגא פיבל מלבוב","b":"חסיד זידיטשוב. דיין בלמברג-תרך אצל ר יוסף שאול נתנזון, ונזכר בספרו, הסכים בשם רבו על \"רבע שקל כסף\" למברג תרמב."},{"i":41713,"n":"קארפיליו, ברוך מלאריסה","b":"רב בלאריסה - בדור שלאחר הגירוש."},{"i":41714,"n":"קארפמן, מרדכי מבני ברק","b":"פרסם מאמרים ב\"תפארת ציון\" - בני ברק תשב - קובץ תלמידי ישיבת \"תפארת ציון\"."},{"i":41715,"n":"קארציר, פנחס","b":"רב-שנת ש\"פ"},{"i":41716,"n":"קארק","k":"ראה: קורק","b":"תלמיד ישיבות איישישוק, וולוזין, נסמך מאת: ר יצחק אלחנן מקובנא, והנצי\"ב. מו\"צ בקובנא-תרמז כ-40 שנה אצל ר יצחק אלחנן ואצל בנו ר צבי הירש, ומנהל כולל אברכים פרושים בקובנא על מקומם. יו\"ר הסתדרות \"המזרחי\" וציר בקונגרס הציוני. עלה לארץ-תרפז."},{"i":41717,"n":"קאשוריש די, דוד משלוניקי וצפת","b":"מחכמי שלוניקי, עלה לצפת, מרביץ תורה בצפת-שסא, ירושלים, חברון."},{"i":41718,"n":"קאשטילו, אברהם יצחק מליוורנו","f":"יוסף","k":"בעל תפלה זכה","bt":"תפו","bp":"אנקונא","dt":"תקמט","b":"הגיע לליוורנו בגיל 13. חתן ר אדם בונדי. רב מדקדק ש\"ץ ומשורר בליוורנו בזמן החידא. סידר \"תפלה זכה\" - ליוורנו - עם פירושים. משיריו בספר \"קול עוגב\" לר פיפרנו זרח אברהם - שכתב את תולדות הרב קאסטילו בספרו. חיבר \"ארבע מרכבות\" ועוד. מבניו הרופא ר יוסף קאסטילו, והרופא ר שמואל."},{"i":41719,"n":"קאשטילו, יוסף מליוורנו","f":"אברהם יצחק מליוורנו","dt":"תקם - בערך","b":"למד רפואה בפיסא. משורר, רופא מומחה - התחיל לחבר ספר רפואה (באישורו וברכתו של הדוכס הגדול ליאופולדו הראשון) - אך נפטר באמצע. אחיו ר שמואל למד רפואה גם הוא. תרגם לאיטלקית את דרשת אביו על מות הקיסר פרנץ השני. משיריו ב\"קול עוגב\"."},{"i":41720,"n":"קאשטילן, דוד הכהן משלוניקי","dt":"שפז - כד סיון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":41721,"n":"קאשיריש די, דוד משלוניקי","dp":"ירושלים","b":"רב בשלוניקי, עלה לצפת-שסא, רב בירושלים-תח. קרובו של ר דוד קונפורטי בעל \"קורא הדורות\"."},{"i":41722,"n":"קאשע, יצחק (שנור) מטרנוב","b":"רב בטרנוב, קרניץ."},{"i":41723,"n":"קב, גרשון שלום מבאטאק","bt":"תרלח","b":"רב בבוטוק(=באטיק)-פלך קובנא-תרסז, עלה לארץ-תרפה."},{"i":41724,"n":"קבליירו, אברהם מפורטוגל ושלוני","b":"מאנוסי פורטוגל, הגיע לשלוניקי - שנות ה-ש'."},{"i":41725,"n":"קבליירו, אליעזר משלוניקי","dt":"שצא - י תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":41726,"n":"קבליירו, יעקב מצפת","b":"מחכמי צפת-שנות ה-ש'."},{"i":41727,"n":"קבליירו, יצחק מונציה","k":"בעל נחל איתן","dt":"תע","b":"מחכמי טורקיה, עבר לונציה. תלמיד ר דניאל אישטרוטה. חיבר \"נהרות איתן\", ו\"נחל איתן\" ונדפס עם \"פרח לבנון\" לר יהודה פרץ - תעב. ?? לא באוצר ??"},{"i":41728,"n":"קבליירו, משה מקושטא","b":"גביר מחכמי קושטא-שנות ה-תק'."},{"i":41729,"n":"קבליירו, שאלתיאל משלוניקי שלמה","b":"משורר בשלוניקי-שנות ה-ש', מחברי ר גדליה ן יחיא המשורר משלוניקי."},{"i":41730,"n":"קבליירו, שלמה משלוניקי","bp":"ספרד","b":"רופא בשלוניקי, מראשי קהלת קטלוניה בשלוניקי-רנב. (או קהלת פורטוגזים)."},{"i":41731,"n":"קבליירו, שמואל משלוניקי","dt":"תטו - כח אב","dp":"שלוניקי","b":"גביר ממנהיגי קהלת שלוניקי. נפטר בחיי אביו."},{"i":41732,"n":"קבליר, שלמה משלוניקי","f":"שמואל","k":"הו\"ל ילקוט שמעוני","dt":"רץ - כה סיון","dp":"שלוניקי","b":"נינו של הרופא ר שמואל דלוניל. רב ק\"ק פורטוגל בשלוניקי, הו\"ל \"ילקוט שמעוני\" רפז. בנו - ר שאלתיאל."},{"i":41733,"n":"קבצניק, מתתיהו גדליה","f":"דב מאישישוק","bt":"תרלז","bp":"אישישוק","b":"תלמיד ישיבת וולוזין, כולל קובנא. רב באראן-תרסא על מקום חותנו, סארנא-ווהלין-תרסג. נסמך מאת: ר שלמה הכהן מוילנא, ר חיים סולוביציק, ר יצחק מפוניבז, ר בן ציון מביעלסק, ועוד."},{"i":41734,"n":"קבק, אהרן אברהם","f":"נטע קלונימוס","k":"בעל שלמה מולכו","bt":"1883","bp":"סמרגון","dt":"1944","dp":"ירושלים","b":"אביו היה רב בוישיי. נדד בארצות שונות. למד בברלין, צרפת ושוייץ. עלה לארץ והיה מורה לעברית. חיבר רומנים ומחזות ובהם \"לבדה\", \"מעל המגדל\", ועוד."},{"i":41735,"n":"קבק, נתן נטע קלונימוס","f":"שלמה יצחק מקראווה","k":"בעל שלמי נדבה","bt":"תריד","bp":"קראווה-פלך וילנא","dt":"תרעג","b":"תלמיד ר יעקב מראגולה. רב בווישיי(=וישייאי)-פלך סובאלק-תרן על מקום ר אליהו מרגליות. בנו הסופר אהרן אברהם קבק."},{"i":41736,"n":"קבק, שלמה יצחק מקרעווא","b":"מצאצאי מהר\"ם פאדובה. רב בקרעווא-פלך סובאלק-תרל."},{"i":41737,"n":"קגיל, יצחק מצאנז","dt":"תרכז","b":"רב בצאנז"},{"i":41738,"n":"קדוש, דוד","k":"בעל המגיד ממראקש","bp":"מראקש","dp":"ירושלים","b":"דרשן מגיד, עלה לנהריה, חיבר \"המגיד ממראקש\""},{"i":41739,"n":"קדוש, דוד מאלגיר","bt":"תרי","dt":"תרץ - בערך","b":"רב בלמדייא."},{"i":41740,"n":"קדוש, חיים מפאס","b":"מחכמי פאס-שנות ה-ת'. דור חמישי ממנו היה בשנת תקפד."},{"i":41741,"n":"קדוש, משה מאלגיר וצרפת","f":"דוד מלמדייא","bt":"תרסג","bp":"למדייא-אלגיר","b":"רב בדיג'ון-צרפת-תרפז מטעם הקונסיסטואר."},{"i":41742,"n":"קדוש, שלמה ממרוקו","dt":"תשיז - כ אייר","b":"רב ודרשן במראקש."},{"i":41743,"n":"קדוש, שמעון ליב","dt":"תשג","b":"רב בריגא"},{"i":41744,"n":"קדושים, יצחק מאזמיר","b":"רב באזמיר. נזכר ב\"מזכרת משה\"."},{"i":41745,"n":"קדושין, יצחק ליב","bt":"תריט","dt":"תרצב - כג אייר","b":"רב בניו יורק"},{"i":41746,"n":"קדיש","b":"רב-שנת תק\"י"},{"i":41747,"n":"קדיש, אורי יצחק מסטרליסק","f":"אשר","dt":"תרעא","dp":"ירושלים","b":"חסיד בלז. עלה לירושלים ועסק בקבלה - תלמידו היה ריא\"ז מרגליות. חיבר בעילום שמו \"פתורא דאבא\" ירושלים תרסה."},{"i":41748,"n":"קדיש, ליפמן","dt":"תצו","b":"דיין בפרג"},{"i":41749,"n":"קדישביץ, קלונימוס קלמן יצחק","f":"פסח מרדכי","k":"בעל תולדות יצחק","bt":"תרלח","bp":"לוטובה-ליד אניקשט","dt":"תשג","b":"כונה בשם \"הצדיק מלוטובה\". מגדולי התורה בליטא. תלמיד ישיבת טלז. רבה האחרון של אניקשט. נספה בשואה."},{"i":41750,"n":"קדלבורג, זלמן","b":"גביר מחכמי פרשבורג"},{"i":41751,"n":"קדש, שרה","k":"בעל רפואות און עצות","bp":"וילנא","b":"למדה בבי\"ס למילדות בוילנא-1820. מיילדת. חיברה חוברת רפואות און עצות, \"תחינה ליולדות\". ?? לא באוצר ??"},{"i":41752,"n":"קדשי, אברהם הקראי ממצרים","b":"מראשי עדת הקראים במצרים-תב אצל ברוך הנשיא."},{"i":41753,"n":"קהל, אנשיל מרדיחוב","bp":"קמינקא","b":"חסיד סטרטין מחצר האדמור בסטרטין. רב ברדיחוב. חתן ר יעקב שמואל ראבפוגל מרדיחוב."},{"i":41754,"n":"קהל, יעקב מבילקמין","bt":"תר","dt":"תרנג","b":"רב בבילקמין."},{"i":41755,"n":"קהלני, שלום מתימן","f":"יחיא רבה של מנא'כה","bp":"מנא'כה-תימן","b":"מחכמי תימן. רב באסמרה-אתיופיה - בתחילת המאה ה-20."},{"i":41756,"n":"קהת מאוסציא","b":"מחכמי אוסציא - תשובה אליו \"מנחת שי\"."},{"i":41757,"n":"קהת מואריש(=ועריש)","b":"מתלמידי הבעשט, ואחריו מתלמידי ר ליב שרה'ס. תלמידו - ר אורי שרגא פיבל מקריסנפולי-דובנקא בעל \"אור החכמה\"."},{"i":41758,"n":"קהת מלבוב","f":"אליעזר","dt":"שפח - י סיון","dp":"לבוב","b":"מחכמי לבוב."},{"i":41759,"n":"קהת מראסיין","b":"אב\"ד ראסיין."},{"i":41760,"n":"קהתי, משה מתימן","f":"שלום","bt":"תרס","bp":"צנעא-תימן","b":"עלה לארץ בילדותו, עו\"ד, הו\"ל קטעים מספר המוסר לפייטן התימני ר זכריה בן סעדיה המכונה מארי יחיא אלצהרי."},{"i":41761,"n":"קו, ליאופולד מפרשבורג - רופא","b":"רופא בפרשבורג-תקץ."},{"i":41762,"n":"קוא, נפתלי הרץ סגל מפרג","f":"חיים","dt":"תקלב - טו חשון","dp":"וינה","b":"גביר ושתדלן מראשי קהלת פרג, בשליחות הקהל בוינה ונפטר בשליחותו."},{"i":41763,"n":"קואהל, יהודה אריה ליב","f":"עוזר","k":"בעל ערי יהודה","bp":"סרהיי","dt":"תרסה","dp":"ירושלים","b":"רבה של ראדין, עלה לירושלים. חיבר \"ערי יהודה\" וילנא תרכה, ועוד"},{"i":41764,"n":"קואינקא, יצחק משלוניקי","f":"שם טוב","b":"מחכמי שלוניקי-שנות ה-ת'. נזכר ב\"סם חיי\" לר בנימין עשהאל."},{"i":41765,"n":"קואינקה, אברהם מירושלים","bt":"תקפז","bp":"שלוניקי","dt":"תרנא - יז כסלו","dp":"ירושלים","b":"עלה לירושלים-תריח. בנו ר בן ציון, אחיו - ר וידאל."},{"i":41766,"n":"קואינקה, בן ציון שמואל וידאל","f":"אברהם","k":"בעל צדקה ומשפט","bt":"תרכז","bp":"ירושלים","dt":"תרצז - טז חשון","dp":"ירושלים","b":"דיין בירושלים, חתן קרובו ר יהודה קואינקה. בשנת תרנח בראש ישיבת \"תפארת ירושלים\", הוציא לאור ירחון \"המאסף\" הופיע מתרנו - תרעד. בשנת תקנז דיין בירושלים, בשנת תרנט בשליחות בהודו, הוצע לו להיות רב בבגדד אך הוא סירב. בחורף תרס בשליחות בשלוניקי ובמצרים בשליחות כולל הספרדים בחברון. בשליחות חברון בהודו-תרנט, באמריקה-תרסב, ושהה שם כשנתיים. בתרסד דיין בבית דינו של ר יעקב שאול אלישר, (רב במצרים-תרסז) רב בחברון-תרצא. בשנת תרסו רכש ספריה גדולה והחל לעסוק במסחר ספרים. חיבר \"צדקה ומשפט\" ירושלים תרפו, ועוד. עורך \"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעד, הופיע בתחילה כמוסף ל\"הצבי\" לאליעזר בן יהודה, ובהמשך מוסף ל\"חבצלת\" - ובתמיכת הברון שמעון זאב רוטשילד.","bk":[["הושיע ציון – עה\"ת",""],["הזכרונות והתולדות",""],["זכרון לאברהם",""],["תפארת ציון – בירורים",""]]},{"i":41767,"n":"קואינקה, וידאל מירושלים","bt":"תקע (וי\"א תקל)","bp":"שלוניקי","dt":"תרכב -ב-יב אד\"ב","dp":"ירושלים","b":"מקובל מחכמי שלוניקי, עלה לירושלים-תריא (וי\"א תקע - וכנראה טעות), והיה מראשי ישיבת \"בית אל\", נתמך בידי הגביר ר שלמה יחזקאל יהודה. בין תלמידיו בעל \"שמן ששון\" וחתנו ר אליהו פריידיס(=פארידיש), חדושים ממנו בקבלה בספר \"תולדות אהרן ומשה\". אחיו - ר אברהם ואחיינו - ר בן ציון קואינקה עורך המאסף."},{"i":41768,"n":"קואינקה, חיים שם טוב משלוניקי","dt":"תקך","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":41769,"n":"קואינקה, יהודה מירושלים","f":"משה","dt":"תרמב - כו אדר","dp":"ירושלים","b":"עלה לארץ-תרו."},{"i":41770,"n":"קואינקה, יצחק מספרד","b":"מגדולי חכמי ספרד"},{"i":41771,"n":"קואינקה, יצחק משלוניקי","f":"משה יצחק משלוניקי","b":"גביר בשלוניקי. תרם למערכת המים של הישיבה בשלוניקי-תקיב"},{"i":41772,"n":"קואינקה, יצחק משלוניקי - א","dt":"תפד","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":41773,"n":"קואינקה, משה יצחק משלוניקי - ב","b":"חתן ר יוסף קובו. גביר מראשי קהלת שלוניקי-תקד, ומורשה הקהלה, חתם אז מטעם הקהלה על הסכם בין יהודי איטליה היושבים בשלוניקי לבין בני קהלת שלוניקי בענין הסדרת המס. סייע בהדפסת ספר חותנו וספר \"אדמת קודש\" לר משה מזרחי. תרם מכספו עם ר יוסף זונאנה לת\"ת בשלוניקי-תקיב. בנו - יצחק."},{"i":41774,"n":"קואינקה, משה מירושלים","dt":"תקעט - טז שבט","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לירושלים, אבי משפחת קואינקה בירושלים."},{"i":41775,"n":"קואינקה, משה מירושלים","f":"יהודה","dt":"תריא - יט סיון","dp":"ירושלים","b":"עלה משלוניקי לירושלים-תרו יחד עם בנו ר יהודה."},{"i":41776,"n":"קואינקה, משה משלוניקי","f":"אברהם","dt":"תרי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":41777,"n":"קואינקה, משה משלוניקי - א","b":"דיין בשלוניקי-שס בערך - בזמן ר אהרן ן חסון."},{"i":41778,"n":"קואינקה, עזריאל משה משלוניקי","dt":"תרעד","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":41779,"n":"קואינקה, שם טוב משלוניקי","b":"מחכמי שלוניקי-תקיא."},{"i":41780,"n":"קואינקה, שם טוב משלוניקי - א","dt":"תסו","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":41781,"n":"קובו, אברהם משה משלוניקי","dt":"תרח","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":41782,"n":"קובו, אברהם משלוניקי","dt":"תקח","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":41783,"n":"קובו, אברהם משלוניקי","dt":"תרה","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":41784,"n":"קובו, אברהם משלוניקי","dt":"רצג - כא שבט","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":41785,"n":"קובו, אברהם משלוניקי","b":"שו\"ב בשלוניקי-שנות ה-תק'."},{"i":41786,"n":"קובו, אליהו משלוניקי","f":"יהודה","k":"בעל אדרת אליהו","bt":"שפ-ח","bp":"שלוניקי","dt":"תמט - ד כסלו","dp":"שלוניקי","b":"חתן ר משה חיים שבתי משלוניקי. מחכמי קושטא, ראש ישיבה, רב הכולל בשלוניקי-תל על מקום ר חסדאי פרחיה הכהן, ו\"ריש מתא\" בשלוניקי על מקום חותנו ואחיינו - ר יוסף בן שמעיה קובו על מקומו אחריו. חיבר \"אדרת אליהו\". חתנו - ר יהושע חנדאלי. מתלמידיו: ר שמואל יצחק מודיגליאנו, ר צבי הירש אשכנזי \"חכם צבי\". בנו - ר יהודה.","bk":[["אדרת אליהו – שו\"ת",""],["שו\"ת אדרת אליהו",""]]},{"i":41787,"n":"קובו, ברוך מירושלים","f":"יוסף בכור (חזקיה)","dt":"תקעה","dp":"מרוקו","b":"מחכמי ירושלים, בשליחות בצפון אפריקה ונהרג במרוקו בדרכו."},{"i":41788,"n":"קובו, דוד מרומא","f":"אברהם","b":"רב ברומא. חתום ב\"מלחמה לה'\"-תעד על החרם נגד נחמיה חיון."},{"i":41789,"n":"קובו, חזקיה יוסף בכור מירושלים","f":"יצחק","dt":"תקפד - יז חשון","b":"מחכמי שלוניקי, עלה עם אביו לירושלים והיה מחכמי ירושלים, בשליחות בקושטא-תקסב, בצפון אפריקה-תקפב, ונפטר בדרכו. הדפיס ספר \"הפרדס\" לרשי בקושטא. בנו ר יצחק הספידו בספר \"יצחק לשוח\" ירושלים תרנט. חדושים ממנו בספר \"עטרת זהב\" לר יצחק בדהב ירושלים תרנח. בנו - ר ברוך מירושלים."},{"i":41790,"n":"קובו, חיים אברהם משלוניקי","f":"יעקב","dt":"תרו","dp":"שלוניקי","b":"דיין יתומים ואלמנות בשלוניקי. אחיו של ר אשר-רבה של שלוניקי. מתורתו בספר בנו ר יהודה \"יהודה יעלה\". חתנו - ר שמואל חביב."},{"i":41791,"n":"קובו, חיים חיימוג'ו משלוניקי","f":"רפאל אשר משלוניקי","b":"רב וראש ישיבה בשלוניקי."},{"i":41792,"n":"קובו, חנניה משלוניקי","dt":"תקפח - כב ניסן","dp":"שלוניקי","b":"מחכמי שלוניקי. אחיו של ר אשר."},{"i":41793,"n":"קובו, חנניה משלוניקי","f":"יעקבאג'י","dt":"תרפט","dp":"שלוניקי","b":"מחכמי שלוניקי, בנו של רבה של שלוניקי. סירב לרבנות העיר על מקום אביו, ובמקומו נתמנה ר יעקב מאיר מירושלים-תרסח. חבר בועד הרוחני - \"מיג'ליש רוחני\", ועסק בצרכי ציבור. הו\"ל ספר אביו \"כוכב מיעקב\"."},{"i":41794,"n":"קובו, יהודה אברהם משלוניקי","dt":"תקכא","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":41795,"n":"קובו, יהודה משלוניקי","dt":"שצו - יג אלול","b":"רב בשלוניקי. עמד בראש משלחת אל השולטן בקושטא בענין המס על היהודים - נהרג עק\"ה בידי השולטן בגלל נסיונו להגן על בני עדתו. בנו - ר אליהו משלוניקי."},{"i":41796,"n":"קובו, יהודה משלוניקי","f":"אברהם","k":"בעל יהודה יעלה","dt":"תרמח","dp":"שלוניקי","b":"בן אחיו של ר אשר קובו-רבה של שלוניקי. דיין בשלוניקי, תלמיד ר' יעקב נחמיאש. מתלמידיו ר דוד פיפאנו. חיבר שו\"ת \"יאודה יעלה\". באוצר הרבנים תאריך הפטירה - תרסז."},{"i":41797,"n":"קובו, יהודה משלוניקי","f":"שמעיה","dt":"תף","dp":"שלוניקי","b":"רב בשלוניקי - אחיו של ר יוסף. מתורתם ב\"באר יצחק\" לר יצחק ן שאנגי."},{"i":41798,"n":"קובו, יהודה משלוניקי","f":"יוסף - גבעות עולם","dt":"תצט","dp":"שלוניקי","b":"מחכמי שלוניקי. מדרשותיו בספר אביו \"גבעות עולם\". בניו - ר שמואל, ר רפאל חיים אברהם (כך לפי רוזניס, לדעת אחרים - ר רפאל חיים היה בן ר שמואל בן אברהם קובו)."},{"i":41799,"n":"קובו, יוסף חזקיהו משלוניק-הנכד","f":"שמעיה?","k":"בעל בן פורת יוסף","dt":"תקכב - יז תשרי","dp":"שלוניקי או ירושלים","b":"נכדו של ר יוסף שמעיה קובו הזקן. מחכמי שלוניקי או קושטא, אביו של ר יצחק קובו, עלה לירושלים וכיהן כדיין עם ר יוסף בן אהרן ן חסון. חיבר \"בן פורת\" שלוניקי תקנז. הניח ספרים נוספים. תלמידו - ר יצחק ן שאנגי הספידו ב\"באר לחי רואי\" והביא מחדושיו."},{"i":41800,"n":"קובו, יוסף חיים משלוניקי","f":"אשר קובו","k":"סיניור חיימוג'ו קובו","bt":"תרד","dt":"תרעא - כה חשון","dp":"שלוניקי","b":"בן הרב הראשי, וחתן ר יעקב קובו. גביר מחכמי ונדיבי שלוניקי, יסד ישיבה ובה ספרים רבים שירש מאביו ומבני משפחתו-נשרפה בשריפה הגדולה-תרעז. הניח בצוואתו רבע מרכושו לטובת הת\"ת בשלוניקי. נפטר ללא ילדים. גיסו - ר אשר שמואל שמחה פעל לחידוש הישיבה אחר פטירתו ופעלה עד השואה."},{"i":41801,"n":"קובו, יוסף משלוניקי","f":"שמעיה","k":"בעל גבעות עולם","bt":"שצו","bp":"שלוניקי","dt":"תפז - טז אלול","dp":"שלוניקי","b":"תלמיד בישיבת נתן העזתי בשלוניקי-תלז. נכד(-אבי אמו) ר יוסף אמריליו. רב הכולל בשלוניקי על מקום ר אהרן פרחיה הכהן, ורב ראשי-תסד על מקום ר שמואל יצחק מודיליאנו (ולפי רוזניס על מקום דודו - ר אליהו קובו, ומשנהו ברבנות היה - ר יוסף דוד). חברו של דודו-אחי אמו - ר שלמה אמריליו, וקבלו כמה מנהגים מנתן העזתי והנהיגום בשלוניקי. חיבר דרשות והספדים שרובם אבדו. בנו - ר יהודה, חתנו - ר משה קואינקא."},{"i":41802,"n":"קובו, יוסף משלוניקי","f":"יהודה","dt":"תקכג","dp":"שלוניקי","b":"מחכמי שלוניקי. חיבר ציונים וחדושים על השו\"ע, ותלמידו ר שלמה הכהן פרחיה הו\"ל בשם \"בן פורת יוסף\"."},{"i":41803,"n":"קובו, יוסף משלוניקי","dt":"תקי","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":41804,"n":"קובו, יוסף משלוניקי","f":"יעקב","dt":"תקצט","dp":"שלוניקי","b":"מחכמי שלוניקי. אחיו של ר אשר. נפטר במגיפה."},{"i":41805,"n":"קובו, יעקב יוסף משלוניקי","dt":"תרנז - יז טבת","dp":"שלוניקי","b":"דיין לבתים וחצרות בשלוניקי."},{"i":41806,"n":"קובו, יעקב יעקבאג'י","f":"חנניה","k":"בעל כוכב מיעקב","bt":"תקפד","bp":"שלוניקי","dt":"תרסה-ז -כז ניסן","dp":"שלוניקי","b":"תלמיד וחתן דודו ר אשר קובו-רבה של שלוניקי. מרביץ תורה, הקים מוסדות - ובהם בימ\"ד לרבנים בשלוניקי-תרנז (מעזבון יוסף ן שושן ואשתו רחל), רב ראשי בשלוניקי-תרמה. השיב לר משה הלוי מקושטא אודות כת ה\"דונמה\" בשלוניקי, על פי בקשת השולטן עבדול חאמיד. בנו - ר חנניה, חתניו: ר חיים יוסף קובו, ור אשר שמחה."},{"i":41807,"n":"קובו, יעקב משלוניקי","f":"אברהם","dt":"תקעו","dp":"שלוניקי","b":"גביר מחכמי שלוניקי. חיבר הקדמה ל\"חיי אברהם\"-תקסד. בנו - ר אשר."},{"i":41808,"n":"קובו, יעקב משלוניקי","b":"רב בשלוניקי. יסד בית מדרש לרבנים \"בית יוסף\" בשלוניקי-תרנז (בכספי עזבון יוסף ן שושן ואשתו רחל)."},{"i":41809,"n":"קובו, יצחק בכור מירושלים - א","f":"יוסף חזקיהו","k":"בעל גדולי הארץ-בכת\"י","bp":"שלוניקי","dt":"תקסז - ג אב","dp":"ירושלים","b":"מחכמי שלוניקי, עלה לירושלים עם אביו או בנו ר חזקיה יוסף והיה מחכמי ירושלים, תלמיד ר מיוחס בכר שמואל בעל \"פרי האדמה\", חבר בית דינו של ר יום טוב אלגזי. חתום עם ר מרדכי חיים מיוחס. בנו - ר חזקיה יוסף. הסכים על \"יד רמה\"-תקן, חדושי המאירי-תקנג, \"דין אמת\"-תקסא."},{"i":41810,"n":"קובו, יצחק חנניה משלוניקי","b":"נכד ר יעקב קובו? פעיל מהפכני וכתב מאמרים בעתונות בעד המהפכה-1908."},{"i":41811,"n":"קובו, יצחק מירושלים - ב","f":"חזקיה יוסף","k":"בעל דגל מחנה","bt":"תקל","bp":"ירושלים או שלוניקי","dt":"תריד - כד אב","dp":"אלכסנדריה","b":"מחכמי שלוניקי עלה לירושלים, בשנת תקנט חתם בין רבני ירושלים, בשנת תקפח חתם על כתב שליחות ר יוסף דוד עייאש. חיבר \"דגל מחנה\" על ספר \"מחנה אפרים\", \"תפארת בחורים\" ירושלים תרנח. נתמנה לראשון לציון בירושלים-תרח על מקום ר אברהם חיים גאגין. בגיל 84 שנה יצא בשליחות קהלת ירושלים יחד עם ר שאול אלישר, ונפטר במצרים (בדרכו ללונדון). נכדו ר יצחק בדהאב - ראה ישיבה בירושלים - החזיק בכתביו והזכירם ב\"פרדס התורה והחכמה\" ו\"ציון וירושלים\". חיבר גם \"הדר זקנים\"."},{"i":41812,"n":"קובו, יצחק משלוניקי","f":"יעקב","dt":"תרמא","dp":"שלוניקי","b":"דיין בשלוניקי. אחיו של ר אשר-הרב הראשי."},{"i":41813,"n":"קובו, ציון מקיוסטנדיל","b":"דיין בקיוסטנדיל-תקנו אצל ר יצחק שמואל חרבון, יחד עם ר חיים ן משה."},{"i":41814,"n":"קובו, רפאל אשר משלוניקי","f":"יעקב","k":"בעל שער אשר","bt":"תקנז","bp":"שלוניקי","dt":"תרלה - יט טבת","b":"בן למשפחת רבנים חשובה בספרד ובשלוניקי. תלמיד דודו ר דוד ברזילי. דיין בשלוניקי-תקצה, רב ראשי בשלוניקי-תרט לצד ר חנניה סאפורטה ור דוד יוסף על מקום ר שאול מולכו. חיבר גם \"מתוקים מדבש\" בסוף ספרו \"שער אשר\". חיבר הקדמות לספרי חכמי עירו. היה ה\"חכם באשי\" הראשון בעירו לאחר פגישתו עם הסולטן מיג'יד-תריז - שהעניק לו גם תואר \"מיג'ידיאי\" ותרם כסף לטובת מוסדות הקהלה. בתוקף תפקידו הרשמי היה רשאי להטיל קנסות ועונשים ואף להכניס לבית הסוהר את העוברים על חוקי התורה בעירו. לא קיבל שכר עבור רבנותו. נאמר עליו כי משמת בטל כבוד התורה בשלוניקי. בנו - ר חיים - חיימוג'ו משלוניקי. חתם-תקצה עם ר משה ברכה ור מרדכי מטאלון.","bk":[["שער אשר (מטה אשר)",""],["שער אשר",""]]},{"i":41815,"n":"קובו, רפאל חיים אברהם בכור משל","f":"שמואל בן אברהם","k":"בעל חיי אברהם","dt":"תקנב-ד","dp":"שלוניקי","b":"נינו ר יוסף קובו והו\"ל את ספרו \"גבעות עולם\"-תקמד. חתן ר אשר עמנואל שלם, והגיה את ספר חותנו \"מטה אשר\" עם הוספות ממנו-תקח. רב ראשי בשלוניקי על מקום ר רפאל אלעזר נחמיאש, ור יצחק ברכה, ר יוסף ן יעיש ור אברהם בנבנישתי גטניו, ור חיים יוסף ן ארדיטי על מקומו אחריו (נבחרו ביחד כ\"רבני הכולל\". חיבר \"חיי אברהם\"-תקסד וכולל גם קונטרס על \"בעל התרומות\". השמות חיים ורפאל נוספו לו בשעת מחלתו. בנו - ר יעקב. (לפי רוזניס היה בנו של ר יהודה בן ר יוסף קובו)."},{"i":41816,"n":"קובו, שבתי משלוניקי","f":"יהודה","b":"מחכמי שלוניקי. (אין פרטים - חתימתו על ספר \"תורת חיים\" - שלוניקי תעה."},{"i":41817,"n":"קובו, שלמה מאבילונה-אלבניה","b":"פרנס קהלת קשטיליה באבילונה בזמן ר דוד מסיר ליאון-שנות ה-ר'-ש'."},{"i":41818,"n":"קובו, שמואל משלוניקי","f":"יהודה בן יוסף","dt":"תקלו","dp":"שלוניקי","b":"גביר בשלוניקי. נכד ר יוסף קובו משלוניקי, וסייע בהדפסת ספר זקנו. בנו - ר אברהם משלוניקי."},{"i":41819,"n":"קובו, שמעיה משלוניקי - א","f":"יהודה","dt":"תכג","dp":"שלוניקי","b":"חתן ר יוסף אמריליו. רב בשלוניקי. בנו - ר יוסף-רבה של שלוניקי."},{"i":41820,"n":"קובו, שמעיה משלוניקי - ב","dt":"תעז","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":41821,"n":"קובו, שמעיה משלוניקי - ג","dt":"תקט","dp":"שלוניקי","b":"גביר בשלוניקי."},{"i":41822,"n":"קובוביצקי (קובובי), אריה","bt":"1896","bp":"קורשאן","dt":"1966","dp":"ירושלים","b":"היגר לבלגיה והיה חבר עירית אנטורפן-1929. עו\"ד מפורסם ועסקן ציוני, מפעילי הקונגרס היהודי העולמי וציר בקונגרסים ציוניים. עורך \"התקוה\", \"פאלק און ארבעט\", ועוד. עלה לארץ וכיהן כשגריר בצ'כיה, ארגנטינה. נשיא \"יד ושם\"."},{"i":41823,"n":"קובי, בכור אברהם מטבריה","b":"חתם על קבלה-תרפג מישיבת חכמי הספרדים בטבריה."},{"i":41824,"n":"קובינסקי, אפרים","b":"רב בקובין"},{"i":41825,"n":"קובלנץ, אברהם מארה\"ב","f":"יהודה זונדל","b":"נכד ר שלמה זלמן משובאץ-פלך קובנא. רב בבולטימור."},{"i":41826,"n":"קובלנץ, גרשון (יעקב) מזיא ממיץ","k":"בעל חנה דוד","b":"תלמיד ר יעקב רישר בעל \"שבות יעקב\", ויצא להגן עליו מהשגות חכמי דורו. מראשי קהילת מיץ-תצד, נשא ונתן עם ר יחזקאל קצנלנפוגן ור יהודה מילר ור שמואל הילמן. בנו ר\"י הו\"ל את ספרו \"קרית חנה\" מיץ תקמה."},{"i":41827,"n":"קובלנקה, אלימלך מאוסטרופולי","f":"מרדכי","bt":"תרמד","b":"רב באוסטרופולי(=אסטרופאלי)-ווהלין-תרסד."},{"i":41828,"n":"קובלנקה, אפרים מאיוונקוב","f":"מרדכי","bt":"תרלה","b":"חתן ר משה מאיוונקוב, ובזיוו\"ש חתן ר אליהו ליב זשוראווליאוו מנארודיטש. רב בוורניקוב-פלך פולטובה, איוואנקוב-פלך קיוב-תרנט על מקום חותנו. נסמך מאת: ר מרדכי דובער מהורנסטיפל."},{"i":41829,"n":"קובלנקה, מרדכי","b":"רב-שנת תר\"נ"},{"i":41830,"n":"קובלנקה, משה מאליקסנדרובקי","f":"מרדכי","bt":"תרלח","b":"רב בוורנקוב-תרסג,אלכסנדרובסקה(=אליקסאנדרובקי)-פלך צרניגוב-תרסח."},{"i":41831,"n":"קובלסקי, יהודה ליב מולאצלאווק","b":"רב בוולוצלובק-תרע. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב."},{"i":41832,"n":"קובלסקי, יחיאל מיכל","dt":"תשיא - ה טבת","b":"רב פעלים,מחשובי רבני ארה\"ב"},{"i":41833,"n":"קובלר, אליעזר ליפא מסקלט","f":"יצחק מסטניסלב","bt":"תקנד","dt":"תרמד","b":"רב בסקלט(=סקאלטאט)-תריד."},{"i":41834,"n":"קובלר, גדליה מאיר מסקוהל","b":"מחכמי סקוהל - ממשתתפי \"הפרדס\"-תרצא."},{"i":41835,"n":"קובלר, זלמן מסטניסלב","b":"רב בסטניסלב. חתן ר צבי הירש מרגליות."},{"i":41836,"n":"קובלר, יוסף מזלישטשיק","b":"גביר מחכמי זלישטשיק-תקצח."},{"i":41837,"n":"קובלר, יצחק אליהו מזלישטשיק","b":"מחכמי זלישטשיק-תריג."},{"i":41838,"n":"קובלר, יצחק מסטניסלב","f":"מרדכי מקמניץ","b":"רב בסטניסלב. בן דודו של ה\"ישמח משה\" ונכד ר אהרן זליג מסטניסלב. חתן ר צבי מלסקירוניא."},{"i":41839,"n":"קובלר, מרדכי מקמניץ","f":"זלמן מסטניסלב","b":"רב בבורשטשוב(=ברטשוב), קמניץ. גיסם של \"צלותא דאברהם\", \"באר יצחק\" ו\"מאיר נתיבים\"."},{"i":41840,"n":"קובלר, משה","f":"משלם מקולומיאה","bt":"תרכ","b":"חתן ר ישכר בר מיברוב. רב בהערצא-תרמו, פנטשא-תרמח."},{"i":41841,"n":"קובלר, משלם מקולומיאה ושאץ","f":"ע'","b":"רב בקולומיאה-תרמד, שאץ. נכד ר שלמה מנדבורנה. בנו ר משה אב\"ד הערצא."},{"i":41842,"n":"קובלר, שלמה","b":"רב בנדבורנו-תק\"צ"},{"i":41843,"n":"קובנט, יצחק","b":"ר\"מ בריגה-תרפ\"ה"},{"i":41844,"n":"קובנר, אברהם אורי","f":"צבי","k":"בעל חקר דבר","bt":"1842","bp":"וילנא","dt":"1909","dp":"לומז'ה","b":"התחבר באודסה לסופרים עבריים, הושפע מההשכלה ויצא כנגד דת ישראל ומנהגיה, עבר לפטרבורג ופרסם ברוסית. נידון למאסר על זיוף, התנצר ונשא אישה נוצריה, ולאחר מכן החל להגן על היהודים והחליף מכתבים על כך עם סופרים רוסיים ובהם דוסטויבסקי, התישב בלומז'ה והחל להתענין מחדש בחיים היהודיים. לאחר פרעות קישינוב פרסם מאמר ברוסית בשם \"מפנקסו של יהודי\". כתביו נדפסו בשם \"כל כתבי אברהם אורי קובנר\" - ת\"א תשז."},{"i":41845,"n":"קובנר, אליהו מאיר","bt":"תרסד","dt":"תשלד - יט חשון","b":"מרביץ תורה ברחובות"},{"i":41846,"n":"קובנר, מיכאל","bt":"1923","bp":"וילנא","dt":"1943","b":"מפעילי המחתרת בגיטו וילנא בזמן השואה, עבר לפלוגת גלזמן ביערות נארוטש. נספה בשואה. אחיו - המשורר אבא קובנר."},{"i":41847,"n":"קובנר, מרדכי אליעזר מוילנא","f":"שלמה זלמן","k":"בעל קרני ראם","bt":"תקס","bp":"קובנא","dt":"תרלד - י תשרי","dp":"וילנא","b":"חתן ר תנחום מוילנא, מתלמידי ישיבת הארבעים בוילנא. גביר מחכמי וילנא ומלמד ברבים. פירושיו למסכת שבת נדפסו בתוך ש\"ס וילנא, ופירושיו גם ב\"נתיבות עולם\" לר צבי הירש קצנלנבוגן, וב\"טורי אבן\" לר אריה ליב בן אשר. פרסם מאמרים ב\"תבונה\" - ממל-קניגסברג תרכא."},{"i":41848,"n":"קובנר, שאול (סבלי)","f":"צבי","bt":"1837","bp":"וילנא","dt":"1896","dp":"קיוב","b":"רופא ברוסיה, חוקר מדע הרפואה ותולדותיה ופרסם ספרים ומחקרים בנושא - ברוסית. פרסם גם בכתבי עת עבריים ובהם \"הרמב\"ם בתור רופא\" ב\"המליץ\", ועוד."},{"i":41849,"n":"קובק יוסף יצחק","bt":"1830","dt":"ה'תרעג 1913","bk":[["גנזי נסתרות",""]]},{"i":41850,"n":"קוברטובסקי, ישכר דוב (דוד)","f":"חיים ברוך","bt":"תרד","b":"רב בדובנקה(=דובנעקא)-תרנז."},{"i":41851,"n":"קוברסקי, הרץ","bt":"1869","bp":"וילנא","dt":"1941","dp":"וילנא","b":"יו\"ר מחלקת החינוך של צ.ב.ק. פרסם מאמרים בגרמנית ורוסית. פרסם מאמרים בעתונות וילנא. נספה בשואה בגיטו וילנא."},{"i":41852,"n":"קוגן, פטר","bt":"1872","bp":"לידא","dt":"1932","b":"בלשן ברוסית וגרמנית בפטרבורג. חיבר ברוסית \"תולדות ספרות מערב אירופה\", ועוד."},{"i":41853,"n":"קודרון, מתתיה אברהם","b":"תלמיד ר חיים יהודה ישראל מרודוס."},{"i":41854,"n":"קודש, שלמה מליא וישראל","k":"בעל קופישוק שהיתה","bp":"קופישוק","b":"מחנך ועסקן, עלה לארץ. חיבר \"קופישוק שהיתה\" תל אביב תשו. ?? לא באוצר ??"},{"i":41855,"n":"קוה (קווע), ישראל הלוי שצריץ","b":"רב בשצריץ-תרנה."},{"i":41856,"n":"קוה, אפרים משה","k":"בעל הינטערלאסעגע","bt":"תפא","bp":"ברסלוי","dt":"1790","b":"בקי בשפות, עבר לברלין, משורר, כתב עליו - ברטולד אוירבך בספרו \"דיכטר אונד קויפמן\"."},{"i":41857,"n":"קוה, חיים אברהם סגל משצריץ","dt":"תרלא","b":"רב בשצריץ, בנו ר ישראל על מקומו אחריו."},{"i":41858,"n":"קוה-שיי, יעקב מרוהטין","dt":"תרסו","b":"רב ברוהטין."},{"i":41859,"n":"קוהוט, חנוך יהודה אלכסנדר מנ\"י","f":"ישראל","k":"בעל ערוך השלם-תרלח","bt":"תרב","bp":"פלאג'האזה-מחוז פשט","dt":"תרנד - יט אייר","b":"תלמיד בסמינר לרבנים בברסלוי. רב הקהלה הניאולוגית בסקשפהרוואר (=שטולווייסנבורג). רב בפעטש(=פינפקירכן)-תרלד, רב הקהילה הניאולוגית בגרוסורדין-תרמב, ישב לפעמים גם בקלויזנבורג לבקשת בני הקהילה הניאולוגית. היגר לארה\"ב-תרמה וכיהן כרב קהילת \"אהבת חסד\" בניו יורק. תמך בזרם השמרני (=קונסרבטיבי), וממיסדי הסמינר לרבנים שם, והיה ממתנגדי הריפורמים הקיצונים. פרסם מחקרים ודרשות בגרמנית ואנגלית, וספר לתולדות עם ישראל בהונגרית. אלמנתו רבקה קוהוט היתה עסקנית צבורית בנ\"י ומלאה תפקידים ממשלתיים בכירים."},{"i":41860,"n":"קוהלמן, יוסף מפרשבורג","b":"מראשי ה\"מנזה\" בישיבת פרשבורג-תרץ."},{"i":41861,"n":"קוויאט, דוד מניו יורק","f":"יצחק קאוויאט","k":"בעל סוכות דוד","b":"ראב\"ד בראשי, ר\"מ בישיבת מיר בניו יורק. פרסם מאמרים ב\"תורה אור\" - שנחאי תשו, \"תלפיות\" - שנחאי תשו."},{"i":41862,"n":"קוויאט, יצחק","b":"רב בראש-תר\"מ"},{"i":41863,"n":"קוויאט, צבי הירש מפיעסק","f":"יצחק מגרודנא","k":"בעל חמדת צבי","bt":"תרל","b":"ר\"מ ומו\"צ בביאליסטוק, רב בפיעסק-פלך גרודנא-תרסו."},{"i":41864,"n":"קווינסקי, יעקב הירש","b":"רב ביאקטרינוסלאב-תר\"מ"},{"i":41865,"n":"קוונאט, דוד נח מבאלווא","f":"משה אליהו","bt":"תרלד","dt":"תשג","b":"נסמך מאת: ר חיים עוזר מוילנא, ר חיים יהודה סוסניצר מסמרגון. חתן ר יהודה-רבה של אנטאליפט-פלך קובנא. רב בבאלווע-פלך פסקוב-תרסו."},{"i":41866,"n":"קוונאט, ר' י' מריגא","b":"פרסם מאמרים ב\"פלפול החברים - ריגא תרפד - מאסף תלמידי ישיבת ריגא."},{"i":41867,"n":"קוועטש, שלמה מלייפניק וניקלשבו","f":"דוד","k":"בעל חכמת שלמה","bt":"תקנט","dt":"תרטז - כד שבט","b":"תלמיד ר מרדכי בנט מניקלשבורג, ורב על מקומו אחריו, רב בפייסלינג-תקפט, לייפניק-תקצב, ניקלשבורג-תרטו על מקום רבו (אך נפטר לאחר חצי שנה)."},{"i":41868,"n":"קוועצקי, יחיאל מיאמפלא","k":"בעל גורל גדליהו","b":"רב ביאמפלא-רוסיה, קורונה-ניו יורק. חיבר \"גורל גדליהו\" נ\"י תרעד. ?? לא באוצר ??"},{"i":41869,"n":"קוזאני, שמואל משלוניקי","f":"לוי קוזין","b":"רופא מגדולי חכמי שאלוניקי-שפ."},{"i":41870,"n":"קוזאק, יוסף דב הכהן מחדרה וזסל","f":"משלם","bt":"תרם","dt":"תשיז","dp":"ישראל","b":"תלמיד ישיבת וולוזין. חתן ר פנחס מרומנוב-מחוז סלוצק (ובמקום אחר חתן ר אליעזר גולדברג מרומנובה). רב בזסלב(=זאסלאוו)-מחוז מינסק-תרסה, חדרה-תרפו. פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":41871,"n":"קוזאקוב, יחזקאל זאב","f":"ישראל","k":"בעל בית ציון","bt":"תרו","b":"רב בדוברומישלה(=דאברא-מישליא)-תרל. חיבר גם \"דורש לציון\", ועוד."},{"i":41872,"n":"קוזבניקוב, דב זאב","b":"מו\"צ ביקטרינסלוב-תר\"ם"},{"i":41873,"n":"קוזי כץ, משלם","f":"מנחם כהן רפא","b":"מגדולי חכמי ויניציאה-ש\"מ"},{"i":41874,"n":"קוזין, יוסף משלוניקי","dt":"תקה","b":"גביר בשלוניקי. נפטר ללא ילדים, והוריש חלק מנכסיו לאחייניתו ובעלה - ר יוסף בן אברהם מולכו משלוניקי, ואלמנתו - אסתר סייעה בידי ר יוסף בהדפסת ספרו \"אהל יוסף\". לפי רוזניס הוא או אלמנתו אסתר היו במצרים."},{"i":41875,"n":"קוזין, לוי משלוניקי","k":"בעל עליית קיר קטנה","bt":"שכה","bp":"שלוניקי","dt":"שפה - א אייר","dp":"שלוניקי","b":"רב בשלוניקי ודיין, רב בונציה. חתם עם ר שלמה הלוי ור אברהם יצחקי-שנז. בנו - ר שמואל קוזין שהדפיס את ספרו, חתנו - ר אברהם פשריאל ונכדיו - ר לוי, ר יוסף. חיבר גם \"תוצאות חיים\" - שלוניקי (או קורוג'ישמי)."},{"i":41876,"n":"קוזינירי","b":"קונסול צרפת בשלוניקי-תקלח, כתב על כת ה\"דונמה\" בשלוניקי."},{"i":41877,"n":"קוזלובסקי, משה מנדל","dt":"תרפט - כסלו","b":"מרביץ תורה,מו\"צ בווילנה,ר\"מ בוורשה"},{"i":41878,"n":"קוזמינסקי, אליעזר צבי","f":"יצחק","bt":"תרטז","b":"נכד ר זליג ניסן מפילוויע, ונכד ר ישראל אברהם רבין מפרוסקרוב. רב ביארמליניץ-פודוליה-תרמד."},{"i":41879,"n":"קוזרניק, אלתר חיים מסוכא","dt":"תרפא","b":"רב בסוכא."},{"i":41880,"n":"קוט, דוד מפרשבורג","b":"ממיסדי אגודה \"עץ חיים\" - פרשבורג תרעא - ללימוד תורה של חבורה מחכמי פרשבורג."},{"i":41881,"n":"קוט, עמנואל מפרשבורג","b":"מג\"מ ומחברי אגודה \"עץ חיים\" - פרשבורג תרעא - ללימוד תורה של חבורה מחכמי פרשבורג."},{"i":41882,"n":"קוטיינר, אליהו מוארשא","b":"רב קהלת ברסלב \"בית אמונה ברחוב גזשיבוב-וארשא-תרצה. נסמך מאת ר אברהם אלחנן ספקטור מענזייאב."},{"i":41883,"n":"קוטלר שלמה נתן","bt":"1855","dt":"ה'תרפ 1920","b":"שו\"ת או\"ח. ר' שלמה נתן קוטלר. רב בלוקניק. נדפס תרצ\"ו.","bk":[["בית שלמה",""],["כרם שלמה","שו\"ת"]]},{"i":41884,"n":"קוטלר, אברהם יצחק מארה\"ב","b":"רב קהלת \"אהבת ישראל\" בג'מייקא-ניו יורק."},{"i":41885,"n":"קוטלר, אהרן מקלצק ואמריקה","f":"שניאור זלמן פינס","k":"בעל חדושי רבינו אהרן","bt":"תרנב","bp":"סוסלוביץ(=סביסלוביץ)","dt":"תשכג - ב כסלו","dp":"אמריקה - ירושלים","b":"תלמיד ר זלמן סנדר שפירא מקריניק, וישיבות סלובודקה וסלוצק. חתן ר איסר זלמן מלצר מסלוצק בעל \"אבן האזל\". ר\"מ בישיבת סלוצק-תרעד, עבר עם הישיבה לקלצק-ליטא, בשליחות-תרצז באמריקה לטובת הישיבה. עבר עם הישיבה לוילנא-תש, ברח דרך רוסיה ליפן ומשם הגיע לארה\"ב-תשא, והיה פעיל בועד ההצלה. הקים ישיבה בלייקווד-תשד. בנו ר שניאור ר\"מ בישיבה, ור מלכיאל על מקומו אחריו כראש הישיבה. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ, \"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":41886,"n":"קוטלר, נחום מפטרבורג","f":"אריה בן מתתיה","dt":"תרץ","dp":"ברלין","b":"גביר בפטרבורג."},{"i":41887,"n":"קוטלר, שלמה נתן ליב מניו יורק","f":"יצחק אהרן","k":"בעל כרם שלמה","bt":"תרטו","bp":"קובנא","dt":"תרץ-ף - כה שבט","dp":"ירושלים","b":"תלמיד ר אליעזר גורדון מטלז, ור יעקב יוסף מוילנא וניו יורק. ר\"מ בלומז'ה-תרלה, רב וראש ישיבה בסלובודקה, רב באוז'וואנט, קורשאן, לוקניק, עבר לניו יורק לבקשת רבו ר יעקב יוסף-רבה של נ\"י כדי לעזור לו ברבנות וכיהן כרב בניו יורק וראש ישיבת \"רבי יצחק אלחנן\" הראשון. חזר לליטא-תרסא וכיהן כרב בקורשאן, לוקניק, אחרי מלחה\"ע ה-I רב בדטרויט. עלה לירושלים-תרצג. חתניו: ר יעקב משה חרלפ מירושלים, ר אריה ליב קפלן משיקגו. חיבר גם \"בית שלמה\". פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא, \"המאסף\", ועוד."},{"i":41888,"n":"קוטלר, שניאור מלייקווד","b":"ראש ישיבת לייקווד."},{"i":41889,"n":"קוטן, אהרן ליב ממנוסטרישץ","f":"מתתיהו","k":"אדמור ממנוסטרישץ נ\"י","dt":"תשלב - כח חשון","dp":"ארהב","b":"אדמור במנוסטרישץ על מקום אביו. ניצל מהשואה, והגיע דרך רוסיה לארה\"ב וכיהן כאדמור, בנו ר שלמה על מקומו אחריו."},{"i":41890,"n":"קוטן, אלכנסר סנדר מזלוזיץ","f":"יוסף אהרן מלשנוב","bt":"תרם","dt":"תש","b":"חתן ר משה בר גוטוירט מלינסק. רב בזלוזיץ."},{"i":41891,"n":"קוטן, אשר מזלוזיץ","f":"שלמה יעקב מלשנוב","bt":"תר","dt":"תרעו","b":"רב בזלוזיץ, בנו ר אלכסנדר על מקומו אחריו."},{"i":41892,"n":"קוטן, יוסף אהרן מלעשנוב","f":"שלמה יעקב","bt":"תקץ","dt":"תרמא","b":"חתן ר משה שפירא מסלאוויטא (בן ר פנחס מקוריץ). רב בלעשנוב על מקום אביו. בנו ר שלמה יעקב על מקומו אחריו."},{"i":41893,"n":"קוטן, יצחק מטיסמניץ","f":"משה חיים אפ' ליברזון","k":"אדמור מטיסמניץ","bt":"תרא","bp":"ברדיטשוב","dt":"תרסז - כד חשון","b":"נין הבעשט. חתן ר שלמה יעקב קטון מלעשנוב. עבר עם שני אחיו לבוקובינה מאימת הצבא, האחד שינה שמו לגוטסמן, והשני ר ישראל ליברזון - אדמור מסאהל. ר יצחק שינה שמו לקוטן - שמו צורף לתעודת לידה למשפחת חותנו ר שלמה יעקב קוטן אב\"ד לשנוב. אדמור בברוד, עבר לטיסמניץ."},{"i":41894,"n":"קוטן, מתתיהו מסטניסלב","f":"יצחק מטיסמניץ","k":"אדמור ממנוסטרישץ","bt":"תרכה","dt":"תרצה - יח שבט","b":"אדמור במנוסטרישטש, ועבר לסטניסלב."},{"i":41895,"n":"קוטן, שלמה חיים מסאהל","f":"יצחק מטיסמניץ","b":"חתן דודו ר ישראל ליברזון מסאהל בקולומיאה."},{"i":41896,"n":"קוטן, שלמה יעקב מלעשנוב","f":"אריה ליב מלודמיר","bt":"תקן","dt":"תרל","b":"רב בלעשנוב-תרכט, בנו ר יוסף אהרן על מקומו אחריו."},{"i":41897,"n":"קוטן, שלמה יעקב מלעשנוב","f":"יוסף אהרן מלשנוב","bt":"תרלג","dt":"תרצד","b":"רב בלעשנוב על מקום אביו, ברודי, לודמיר (ולדימיר-ולדימרץ). חתן ר מנחם מוניש הלפרין מברודי. סייע לחותנו בהוצאת \"מנחם משיב נפש\" והוסיף הערות משלו. נכדו - ר אלכסנדר מזלוזיץ."},{"i":41898,"n":"קוטנא שלום בן אהרן","bt":"1826","dt":"ה'תרסט 1909","bk":[["מספד תמרורים",""]]},{"i":41899,"n":"קוטנא, אהרן מטאטא","f":"יוסף","k":"בעל שארית יוסף","r":"רב בטאטיס","bt":"תקנד","bp":"טאטוס(=טאטא)","dt":"תרלד - יב כסלו","dp":"טאטוס(=טאטא)","b":"תלמיד ר שלום אולמן מלקענבך, ור בנימין זאב חיות מוארפאלטא, והחת\"ס. חתן ר משה ליב לבל מדארדע ועבר לשם. רב בטאטוס לצד אביו ועל מקומו אחריו-תקפט (במורשת רבני הונגריה מופיע - רב הקהילה הניאולוגית בטאטוס(=טאטא טו-וארוש)-תקעד. חיבר גם \"דעת זקנים\", \"משחת אהרן\".","bk":[["משחת אהרן - נדה",""],["שארית יוסף - הערות על הדעת זקנים",""]]},{"i":41900,"n":"קוטנא, יוסף מטאטיס","f":"אהרן קמפנר","dt":"תקפט","b":"ראב\"ד בפאפא, רב בטאטוס-תקעג על מקום ר אהרן קמפנר. נזכר בחת\"ס. בנו - ר אהרן שהו\"ל \"דעת זקנים\" אויבן(=בודפשט) תקצד."},{"i":41901,"n":"קוטנא, ישראל מבאניהאד","b":"דיין בבניהאד-תקצד-תרלב."},{"i":41902,"n":"קוטנא, שלום מאיזנשטט","f":"אהרן מטאטוס","k":"בעל קול על המים","bt":"תקפו","bp":"טאטוס","dt":"תרסט - טז שבט","dp":"איזנשטט","b":"תלמיד הכת\"ס, ור אברהם אולמן מלקנבך. חתן ר ידידיה גוטליב פישר משטוהל-ויסנבורג. רב במאר-תרט, קאפושוואר-תריד, איזנשטט-תרל. חיבר גם \"עתרת שלום ואמת\". פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"תל תלפיות\" - וייצען תרנב-תרעד."},{"i":41903,"n":"קוטנפלן (ק\"פ), יוסף מעיר חדש","k":"בעל בתי נפש","bt":"תקכג","bp":"העלישוי","dt":"תקעג-ה - ה תמוז","dp":"שטאמפן","b":"מכונה גם ר יוסף ברסלוי. דרשן, רב בהאליטש על מקום ר יהודה דרזניץ, גאייא, אונגריש ברוד-תקנד, עיר חדש-תקסב על מקום ר אברהם וינר (לאחר שהחת\"ס סירב להצעה) ור דוד דייטש על מקומו אחריו, שטמפן-תקסח על מקום ר אריה ליב טויבר שעבר לגאלאנט. הסכים על פירוש יונה ואגדות רבב\"ח להגר\"א. חתנו - ר שמואל פעסל, בנו - ר וולף ברעסלא - הו\"ל ספר אביו בשם \"בתי נפש\". נספד מאת החת\"ס. (ישנו רב נוסף בשם יוסף שהיה בעיר חדש והיה קרובו של הנודע ביהודה והיה גם בברודי - ויש שהחליפו ביניהם)"},{"i":41904,"n":"קוטנפלן, וולף מהעלישוי","f":"יוסף - בתי נפש","b":"הו\"ל ספר אביו \"בתי נפש\" - וינה תקעה."},{"i":41905,"n":"קוטנפלן, שמואל","k":"ק\"פ, שמואל","b":"רב-שנת תר\"י"},{"i":41906,"n":"קוטנר, אברהם אלתר","bt":"תרסא","dt":"תשלה - יא אדר","b":"רב בשימליצה(בסרביה),רב בלוד-תש\"ח"},{"i":41907,"n":"קוטקין, אליעזר חיים מסקידל","b":"רב בסקידל. אביו של ר מאיר יוסף בעל \"פנים מאירות\"."},{"i":41908,"n":"קוטקין, מאיר יוסף מיאנוב","f":"אליעזר חיים מסקידל","k":"בעל פנים מאירות","bt":"תקפז","bp":"סקידל","b":"רב ברוסי(=ראש)-מחוז וולקוביסק, ברסטוביץ, יאנובה. חיבר גם ביאור על הירושלמי, וכתב בהקדמתו כי מטרת ספרו \"לחלקו בחינם יען כי אין לי בנים וספרי יהיה ציון נפשי\". חתנו - ר שמואל אביגדור כגן-גרשטין."},{"i":41909,"n":"קוידנער, שמואל ליב","k":"בעל עולת שמואל","bt":"תקכו","dt":"תקצח","b":"תלמיד חבר לר בצלאל רנשבורג. רב בטאבור, בודוויז-בוהמיה, פרג-תקצה. חיבר גם \"אהבת אמת\""},{"i":41910,"n":"קויטלמכר, מאיר","b":"פרסם מאמרים ב\"תל תלפיות\" - וייצען תרנב-תרעד."},{"i":41911,"n":"קוימבראנו, משה מפיררה","b":"רב בפיררה. תשובה ממנו בענין המקוה ברוויגו."},{"i":41912,"n":"קוינט, אליהו מניו יורק","k":"בעל מנוחת אליהו","b":"רב בניו יורק."},{"i":41913,"n":"קויף, אלימלך סגל","b":"חתן הרב מקנטשוגה. תלמיד ה\"שואל ומשיב\"."},{"i":41914,"n":"קויפטייל, דוד יצחק מביסטריץ","f":"חיים צבי","bp":"צאנז","dt":"תרפא - ח אב","b":"ישב כמלמד לבנים אצל ר מרדכי יהודה לעוו מאינטרדם. דיין בביסטריץ, וראב\"ד, ועזב בגלל מחלוקת בענין בניית בית הכנסת, ובנו ר מרדכי על מקומו אחריו. מקורב ל\"דברי חיים\", וממניחי היסוד לחסידות צאנז, סיגט ובלז בביסטריץ. מתלמידיו - ר אברהם יהושע פריינד האדמור מנאסוד."},{"i":41915,"n":"קויפטייל, מרדכי מביסטריץ","f":"דוד יצחק","b":"רב בביסטריץ על מקום אביו. מקורב לחסידות."},{"i":41916,"n":"קויפמן מוילקומיר","b":"דיין בווילקומיר"},{"i":41917,"n":"קויפמן משטמפן","b":"פרנס ממנהיגי קהלת שטאמפי-תקו. חתן ר זנויל גיירינג."},{"i":41918,"n":"קויפמן, אברהם זאב","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":41919,"n":"קויפמן, אברהם מסיגט","b":"מדפיס בסיגט. הדפיס \"הלבנון\" - סיגט תרפו."},{"i":41920,"n":"קויפמן, אהרן אריה מוישניובטשיק","k":"בעל יד לאהרן","b":"רב בויניובטשיק (ליד בוצאץ). חיבר \"יד לאהרן\" ו\"לב לארי\" - בכתב יד."},{"i":41921,"n":"קויפמן, גרשון שלום מיאנוב","b":"פרסם מאמרים ב\"חדרי תורה\" - קראקא תרפו."},{"i":41922,"n":"קויפמן, דוד מבודפשט","f":"יהודה ליב","bt":"1852","dt":"1899","b":"הסטוריון וחוקר חכמת ישראל. מלמד בביהמ\"ד לרבנים בבודפשט. הוריש אוסף גדול של כתבי יד עבריים ושרידים מגניזת קהיר לאקדמיה למדעים בבודפשט. היה דין ודברים בינו לבין המזרחן האנטישמי לאגארד. פרסם מאמרים ב\"ירושלים\" - ירושלים תרמב-תרעט."},{"i":41923,"n":"קויפמן, זאב וולף מוילנא","f":"ישעיה הכהן מוילנא","k":"בעל שירי זקן","bt":"תקפו","bp":"וילנא","dt":"תרמז - כד אייר","dp":"ריגא","b":"תלמידי משכילי וילנא ובהם אד\"ם הכהן, ור מרדכי אהרן גינצבורג. בקי בשפות (היה מתורגמן בבית המושל). סופר. מלמד לנערים בריגא. חיבר שירים ומשלים במאספים שונים בשם \"זק\"ן\". בנו יעקב קפלן-חתן יל\"ג הו\"ל כמה מחבורי אביו בשם \"ישן נושן\" בתוך ספר חותנו \"תולדות יל\"ג\". ?? לא באוצר ??"},{"i":41924,"n":"קויפמן, חיים יואל מארה\"ב","k":"בעל מראה לדעת","b":"רב בארה\"ב-תרצט."},{"i":41925,"n":"קויפמן, יוסף זאב מארה\"ב","k":"בעל זכרון יוסף זאב","b":"רב בארה\"ב-תרסד."},{"i":41926,"n":"קויפמן, יעקב יהודה מלויפהיים","b":"אב\"ד לויפהיים-תר."},{"i":41927,"n":"קויפמן, יעקב צבי ממארגרטין","f":"מנחם מנדל","k":"בעל זכרון מנחם","bt":"תרסא","dt":"תשד","b":"גדל אצל זקנו ר ישראל חיים פרידמן מראחוב בעל \"לקוטי מהרי\"ח\". תלמיד הדעת סופר, וזקנו המהרי\"ח. חתן ר שמואל זלמן וינברגר ממארגרטן. דיין ומו\"ץ במארגרטן-תרפו. נספה בשואה. הו\"ל ספר זקנו - לקוטי מהרי\"ח עם הגהות ממנו בשם \"זכרון מנחם\" - סטמר תרצב. פרסם מאמרים ב\"קובץ מפרשי התורה\" - מארגרטן תרצג. ?? לא באוצר ??"},{"i":41928,"n":"קויפמן, יקותיאל מוינה","b":"דיין בווינה-ת\"ט"},{"i":41929,"n":"קויפמן, מנחם מנדל","b":"חתן ר ישראל חיים פרידמן מראחוב בעל ליקוטי מהרי\"ח. אביו של ר יעקב צבי קופמן ממארגרטן."},{"i":41930,"n":"קויפמן, משה אברהם יקותיאל","k":"בעל לחם הפנים","b":"דיין בקארטשין-תעה. חתן ר אברהם אבלי בעל \"מגן אברהם\". חיבר \"לחם הפנים\", \"חוקי חיים\"."},{"i":41931,"n":"קויפמן, משה יקותיאל הכהן מקוטנ","f":"אביגדור","k":"בעל מאכלת אברהם","b":"רב בקוטנא ועוד קהלות. חתן ה\"מגן אברהם\" ובנו - בעל \"מאכלת אברהם\". חיבר \"חוקי חיים\", \"חוקי דעת\", \"חקת התורה\" - והוא פירוש על \"ישמח ישראל\" לר ישראל שמואל קליפארי, ועוד."},{"i":41932,"n":"קויפמן, פנחס מיאנוב","f":"מהרש\"א","b":"רב ביאנוב. פרסם מאמרים ב\"אסיפת חכמים\" - מלניץ תרפח, \"יגדיל תורה\" - פראגא-וארשא תרפז, \"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":41933,"n":"קויפמן, ראובן מלונדון","b":"רב בלונדון. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":41934,"n":"קולביאנסקי, ישעיהו","f":"טוביה","bt":"1892","bp":"יאנובה","b":"למד אמנות בוילנא. צייר. למד בברלין אצל הרמן שטרוק, והוגו קויפמן. עלה לארץ-1933, עבר לצרפת-1950. מיצירותיו \"נגר יהודי\", ועוד."},{"i":41935,"n":"קולבק, משה","bt":"1896","bp":"סמרגון","dt":"1941","dp":"בעל לידער","b":"תלמיד ישיבות ליטא. פרסם שירים בעברית, ועבר לאידיש. חיבר שירים מפורסמים ובהם \"שטערענדל\", \"די שטאט\". עבר לרוסיה הקומוניסטית, נאסר בזמן הטיהורים ומת בכלא. חיבר גם \"משיח בן אפרים\", ועוד."},{"i":41936,"n":"קולואר די, יעקב מצפת","b":"מגדולי חכמי צפת-ש\"ל"},{"i":41937,"n":"קולודצקי, דוד נחמן מווישיי","b":"רב בווישיי-תר\"צ"},{"i":41938,"n":"קולודצקי, חיים","dt":"תשיד","b":"מרבני ניו יורק,עלה לא\"י-תרפ\"ח"},{"i":41939,"n":"קולודצקי, יצחק","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה - ירושלים תשא."},{"i":41940,"n":"קולודצקי, נחמן מאליטא","b":"רב בוישיי על מקום ר נתן נטע קבק, סייני, אליטא על מקום ר יואל זלקינד בעל \"בית יואל\", ור אהרן מילבסקי בעל \"מנחת אהרן\" על מקומו אחריו-תרפט."},{"i":41941,"n":"קולודצקי, שכנא מירושלים","b":"חתם-תרצו כעד על הלואה לרכישת בנין ישיבת חברון בירושלים."},{"i":41942,"n":"קולודרו, אליהו מאזמיר","dt":"תקיט - כח ניסן","dp":"אזמיר","b":"דרשן באזמיר."},{"i":41943,"n":"קולומבו, שמואל מליוורנו","f":"דוד","k":"בעל מדינת בבל","bt":"תרכח","bp":"פיגלאנו-איטליה","b":"תלמיד ר יהודה רקח, ר ישראל קושטא, ר אליהו בן אמוזג בעל \"אם למקרא\". ד\"ר לפילוסופיה מאניברסיטת פיסא, רב בליוורנו-תרנו לצד רבו ר ישראל קושטא, רב לצד ר אליהו בן אמוזג, רב הכולל-תרן. חיבר גם \"קבורה ושרפה\", ועוד."},{"i":41944,"n":"קולון, דוד אשכנזי ממצרים","b":"ברח מפרעות תח בפולין והתישב במצרים. ביקש היתר לשאת אישה שניה."},{"i":41945,"n":"קולון, יוסף הצרפתי","b":"רב-שנת ת\"ר"},{"i":41946,"n":"קולון, יוסף מאיטליה","f":"שלמה","k":"מהרי\"ק","dt":"רמ","dp":"פאדובה","b":"גדול רבני איטליה, פוסק הדור, רב בקאנברי, סאבויה, פיימונטי, לומברדיה, מייסטרי, בולוניה, מנטובה."},{"i":41947,"n":"קולון, יוסף מירושלים - הנכד","f":"פרץ מאיטליה וירושלים","b":"מחכמי ירושלים, עלה מאיטליה לירושלים עם אביו, היה נכדו של המהרי\"ק. בשנת רפא חתם על מכתב לאחד הנדיבים עם ראשי ישיבת ר יצחק שולל. מוזכר בשות מהרלב\"ח. יש גם במצרים."},{"i":41948,"n":"קולון, יוסף מצפת","f":"משה לטף","b":"מחכמי קהלת האשכנזים בצפת. חתן - ר זכריה אשכנזי מירושלים וצפת, וגיסו של ר יוסף קארו ? כך אצל רוזניס."},{"i":41949,"n":"קולון, פרץ מאיטליה","f":"יוסף-מהר\"י קולון","dt":"רפז - לפני","dp":"ירושלים","b":"נשלח על ידי אביו לר משה קפסלי בקושטא לפשר במחלוקת ביניהם, ור משה קרבו ועמד לימינו במחלוקת שהיתה לו עם ר אליהו מזרחי. מקושטא עלה עם בנו ר יוסף (לימים מרבני ירושלים) לצפת, ונתמנה לאחד מראשי הקהלה יחד עם ר יוסף סרגוסי ועוד. היה ראש ישיבה בצפת, בשנת רפב כיהן כרב בירושלים. בנו - ר יוסף מירושלים."},{"i":41950,"n":"קולוניא די, אברהם חי ממנטובה","bp":"תקטו","b":"תלמיד ר ישראל גדליה קאזיס, גיסו של ר יעקב קאזיס. רב במנטובה, מראשי הרבנים שנקראו לסנהדרין שכינס נפוליאון בפאריז-תקסו. רב בטריאסט. פרסם מאמרים בצרפתית."},{"i":41951,"n":"קולורני, אברהם ממנטובה","b":"מחכמי מנטובה ומקורב לדוכס ולמלך רודלפו השני. חיבר ספר בלטינית ואיטלקית המורה כיצד לכתוב מכתבים - פרג."},{"i":41952,"n":"קולורני, מלאכי","k":"בעל מגלת ספר","b":"חיבר \"מגלת ספר\" בכת\"י (ברשימת ר חיים יוסף בן מיכל)."},{"i":41953,"n":"קולייר, אברהם מאולוניא","b":"רב באבילונא-אלבניה, שנון-רן. היה במחלוקת עם ר דוד מסיר ליאון באבילונא."},{"i":41954,"n":"קוליק, דוד","b":"מתורתו (מכת\"י) ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":41955,"n":"קולמן, נתן נטע מטשארנא","f":"בנימין מפרוינקריכן","bt":"תקפ","bp":"פרוינקירכן","dt":"תרמב - ב שבט","dp":"פאראד","b":"תלמיד החת\"ס, והכת\"ס. חתן ר דוד רוזנברג מצעהלים ועבר לשם-תרד. רב בשארוואר-תריח, טשארנא-תריט, חתנו ר זאב וולף כהנא על מקומו אחריו."},{"i":41956,"n":"קולפא, דוד מאיר יהודה מפפד\"מ","b":"מראשי קהילת פפד\"מ, והיה בראש מחנה שנקרא על שמו במחלוקת בפפד\"א-תקי, כנגד מחנה משפחת קן (וגם בחצר הקיסר בוינה התערבו במחלוקת)."},{"i":41957,"n":"קולפא, זיסל מאיר יהודה מפפד\"מ","dt":"תקלט - יט אדר","dp":"פפד\"מ","b":"מראשי קהילת פפד\"מ - מראשי סיעת קולפא במחלוקת עם משפחת קן, ומבין 12 מחברי תקנות הקהילה-תקיג. סוכן החצר של הקיסר, בעל השפעה ושתדלן לטובת היהודים."},{"i":41958,"n":"קולפא, יצחק מפפד\"מ","b":"מראשי קהילת פפד\"מ. חתן ר נתן מאז בעל \"בנין שלמה\"."},{"i":41959,"n":"קולקע, שמשון מלייפניק","b":"תלמיד ר ברוך בעל \"ברוך טעם\". חתן ר נחום טריבטש מניקלשברג - המזכירו בספריו. אב\"ד פוסטל-פודיבין (מורביה)."},{"i":41960,"n":"קולר, יהושע מברוד","b":"מחכמי ברודי, דולובוב (ליד רידיק). עלה לארץ."},{"i":41961,"n":"קומבריאל, אברהם משלוניקי -הנ","b":"נכד ר אברהם שנהרג בספרד עק\"ה. דיין בשלוניקי-שס בערך בזמן ר אהרן ן חסון. חתנו - ר יקותיאל עיזוז (חתנו או חותנו של ר אדוניקם בן מנחם לונזאנו."},{"i":41962,"n":"קומורן, אהרן מאושפאל","dt":"תשג","b":"רב באושפאל"},{"i":41963,"n":"קומטינו, מרדכי מקושטא","k":"בעל כתר תורה","b":"רב בקושטא. חיבר \"כתר תורה\", \"ספר השם\", \"ספר האחד\", ועוד - בכת\"י (אצל די רוסי). דרשה לכבודו בספר הדרשות לר אפרים בן גרשון הרופא מוורוגה."},{"i":41964,"n":"קומיץ, ישראל יצחק מלובטש","b":"מגיד מישרים בלובטש(=לובץ)-תרמ-תרן. חתנו - ר אריה ליב קלמנוביץ בעל \"לב אהרן\"."},{"i":41965,"n":"קומלי, שלום מתימן","b":"דיין בדמת-תימן - במאה ה-19. חתם על פסק דין-תריח."},{"i":41966,"n":"קונא די, אהרן מאמשטרדם","k":"בעל תעלומות חכמה","b":"רופא יהודי פורטוגזי באמשטרדם. חיבר ספר בעניני רפואה בספרדית והולנדית בשם \"תעלומות חכמה\" - תקלו - כת\"י."},{"i":41967,"n":"קונדה, אהרן מאלוסק","f":"זלמן","bt":"תרלו","dt":"תשב - יד אלול","b":"רב באלוסק-וואהלין-תרסה, סארנה."},{"i":41968,"n":"קונוביץ, יחזקאל מניו יורק","k":"בעל אוצר התלמוד","b":"מחכמי ניו יורק, חיבר אוצר התלמוד והמדרשים."},{"i":41969,"n":"קונורטי, חיים אשכנזי מרוסג'וק","dt":"תר - ז ניסן","b":"ש\"ץ וסופר הקהל ברוסג'וק-תקסב."},{"i":41970,"n":"קונורטי, חיים שמואל הכהן","k":"הסיניור","bt":"תקע","bp":"איטליה","dt":"תריג - יז אלול","dp":"טבריה","b":"עלה לארץ לאחר תקפג (בגליס תקפז) והתישב בטבריה, אב\"ד בטבריה-תרה (עם הדיינים ר אברהם הכהן דוויק, ר רפאל ארזי), בנה את הבנין על קברו של ר' מאיר בעל הנס, וראש ישיבת \"מדרש שמואל\" שם. בשליחות בטורקיה ואיטליה-תרא לאחר הרעש של שנת תקצז, בהיותו בפוליפולי השיב שתי תשובות לרב העיר ר מתתיהו בן ארולייא, בשנת תרד בהיותו בשליחות באיטליה, הסכים בטריאסט על הספר \"אמת ליעקב\" לר יעקב ניניו, שהיה חתנו. וכך בערים נוספות באיטליה בהן עבר. השפיע על עשיר בשם \"סיניור\" להקים ישיבה בטבריה \"מדרש סיניור\", וישב בראשה. תשובותיו נדפסו בסוף ספרו של חתנו \"זרע יעקב\". כתבים נוספים בכתב יד. לפי גליס נפטר תרלא. חיבר הקדמה לספר ידידו ר יצחק גואיטא - \"שדה יצחק\". (לפי גאון תאריך פטירתו - תרלג)."},{"i":41971,"n":"קונורטי, סימן טוב מסופיה וקושט","f":"אברהם","b":"גביר מראשי קהלת קושטא-תקצה."},{"i":41972,"n":"קונורטי, עזריאל","f":"יהודה אברהם","b":"אביו של ר אהרן עזריאל בעל \"כפי אהרן\"."},{"i":41973,"n":"קוניאן, יהודה","b":"רב באקווי (איטליה)-שסג. השיב ב\"פלגי מים\" בענין המקוה ברוויגו."},{"i":41974,"n":"קוניאן, ישראל מאיטליה וקושטא","b":"רופא באיטליה, קושטא. מתורגמן המשלחת מונציה בקושטא על מקום יוחנן נבון שהוצא להורג."},{"i":41975,"n":"קוניאן, ישראל מפדובה","dt":"תקפד - ו אדר","dp":"פדובה","b":"תלמיד ר עזריאל אלאטינו. רב בפדובה. הניח ספר דרשות בכת\"י. תלמידו - ר יוסף אלמנצי בעל \"הגיון בכנור\", ו\"מעיל קינה\" - ובו הספיד את רבו. חתם על הפסק של ר ברוך עוזר מהמבורג כנגד הריפורמים."},{"i":41976,"n":"קוניאן, שלמה מאיטליה","f":"יוסף?","bt":"ת","bp":"פדובה","dt":"תעט","dp":"ונציה","b":"רופא, רב בפדובה-תס. מתלמידיו - ר טוביה הכהן בעל \"מעשה טוביה\", ור שלמה חיבר הקדמה לספר תלמידו."},{"i":41977,"n":"קוניזו, שלם ממראקש","b":"מחכמי מראקש, חתם-תקמז עם חכמי דורו בעניני טריפות."},{"i":41978,"n":"קוניץ, אליעזר","b":"דומ\"צ בסעניץ-תקמ\"ז"},{"i":41979,"n":"קוניץ, יהודה ליב","b":"רב בסעמיקלוש-תקל\"ג-תקע\"ד"},{"i":41980,"n":"קוניץ, יוסף","b":"רב בנייזץ-תקס\"ה"},{"i":41981,"n":"קוניץ, יעקב","k":"בעל זרע יעקב","b":"מחכמי אויבן-תק\"י"},{"i":41982,"n":"קוניץ, משה","k":"בעל המצרף","bt":"תקלד","dt":"תקצז","b":"תלמיד ר וולף בוסקוביץ, הנודע ביהודה, ר\"מ מינץ. רב בברסלוי, אויבן. בסוף ימיו נטה להשכלה.","bk":[["בן יוחאי",""]]},{"i":41983,"n":"קוניץ, משה מאויבן","f":"מנחם","k":"בעל בן יוחאי","bt":"תקלד","bp":"אויבן","dt":"תקצז - כז שבט","dp":"בודפשט","b":"נכד-אבי אביו ר גרשון אשכנזי, ונכד-אבי אמו בעל \"חוות יאיר\". תלמיד ר בנימין וולף בוסקוביץ באויבן, ה\"נודע ביהודה\" בפראג. חתן הגביר ר שלמה הכהן מברסלוי ועבר לשם, דומ\"צ באויבן ובפעסט. חיבר גם \"בית רבי\" - המחזה העברי הראשון בהונגריה. הטיף לתפילה בהברה ספרדית. חיבר מונוגרפיה על ר שמעון בר יוחאי - ובה מתוכח עם ר יעקב עמדין בדבר מחבר ספר הזהר. ?? לא באוצר ??"},{"i":41984,"n":"קוניץ, צבי הירש מבעלעד","f":"משה מלקנבך","bt":"תקמה","dt":"תרך - יד אלול","dp":"עלעד","b":"תלמיד החת\"ס, ור שמולם איגרא מפרשבורג. מחכמי מיהאלי-תקעח, רב בביילעד(=בעלעד) והגלילות-תקס או תקץ."},{"i":41985,"n":"קוניצר, אברהם","bt":"תרכח","b":"מו\"צ בבנדר-תרס\"ג"},{"i":41986,"n":"קונמבריאל, אברהם הקדוש מארגא","b":"רב באראגון. נהרג עק\"ה עם חברו ר שמעון אלמושנינו. ונזכר ב\"מאמץ כח\" לר\"מ אלמושנינו."},{"i":41987,"n":"קונמבריאל, אברהם משלוניקי","f":"משה","b":"נכד ר אברהם הקדוש מספרד. מרביץ תורה, דרשן בשלוניקי."},{"i":41988,"n":"קונסטנטינר, אלתר","b":"רב בשנת תרנ\"ו"},{"i":41989,"n":"קונפורטי דוד","bt":"1617","dt":"ה'תנ 1690","bk":[["קורא הדורות",""]]},{"i":41990,"n":"קונפורטי, גבריאל","f":"דוד","b":"מגדולי חכמי דורו, רב בשלוניקי-תכ."},{"i":41991,"n":"קונפורטי, דוד אשכנזי - הנכד","k":"בעל קורא הדורות","bt":"שעח","bp":"שלוניקי","dt":"תן או תמב","dp":"שלוניקי","b":"חתן ר אדוניקם בן מנחם לונזאנו. נכד ר דוד קונפורטי הזקן ואמו - ממשפחת ר דוד קאסיריס. מחכמי שלוניקי, תלמיד ר עזריה זאבי, ר אשר זבולון מיבוגרד, ר דניאל איסטרושה, קבלה למד אצל ר יפת המצרי שקיבל מר חיים ויטאל. למד גם ר אצל ר מרדכי קלעי יחד עם ר ידידיה בן שלמה קארו (שסיפר לו זכרונות מזקנו - ר יוסף קארו). עלה לירושלים ולמד אצל ר יוסף איסקפה. למד במצרים אצל ר אברהם אכסנדרי בקהיר, בעזה פגש את ר משה בן ישראל נגארה. בשנת תך התיישב בירושלים-תך, חתן ר אדוניקם בן מנחם לונזאנו. יצא בשליחות לאזמיר, היה רב במצרים-תלא, היה בחליפת מכתבים עם חכמי דורו. תשובותיו בספרי חכמי דורו. חיבר ספר \"קורא הדורות\" ונציה תקו. (אצל גירונדי יש כנראה טעות בתאריך הפטירה)."},{"i":41992,"n":"קונפורטי, דוד משלוניקי","b":"רב בשאלוניקי-ת\"פ"},{"i":41993,"n":"קונפורטי, דוד משלוניקי - הזקן","f":"עמנואל בן יקותיאל","b":"מחכמי שלוניקי ומשורר, תלמיד דודו (אחי אמו) ר שאלתיאל חפץ, בתקופת ר' חיים ויטאל. חברו של ר ישראל אבא. זקנו של ר דוד בעל \"קורא הדורות\"."},{"i":41994,"n":"קונפורטי, יעקב מקיוסטנדיל","b":"דיין בקיוסטנדיל-תקנה, יחד עם ר שמואל קונפורטי, ור שלמה בכ\"ר אברהם."},{"i":41995,"n":"קונפורטי, יצחק מירושלים","dt":"תקנו - תמוז","dp":"ירושלים","b":"מחכמי ירושלים"},{"i":41996,"n":"קונפורטי, שמואל מצפת","f":"מרדכי","k":"בעל קול שמואל","bt":"תק","bp":"קיוסטנדיל","dp":"צפת","b":"תלמיד ר ישכר אבולעפיה בסופיה, ר יעקב טיבה בקיוסטנדיל. דיין ורב הכולל בקיוסטנדיל על מקום רבו ותלמידו ר יצחק שמואל חרבון על מקומו אחריו, עלה לצפת-תקנו. חיבר גם \"עולת תמיד\", ועוד."},{"i":41997,"n":"קונפינו, אהרן מקושטא","bp":"שלוניקי","dp":"קושטא","b":"תלמיד ר חיים שבתי בשלוניקי. מגדולי חכמי שלוניקי, מרביץ תורה בקושטא - אחרי שעג."},{"i":41998,"n":"קונפינו, דוד מירושלים","b":"מגדולי רבני ירושלים"},{"i":41999,"n":"קונפינו, יהודה אברהם מירושלים","k":"בעל ליברו מיניסטירוז","b":"מחכמי ירושלים, חיבר ספר בלאדינו והוא ליקוטים מ\"מורה באצבע\" לחיד\"א."},{"i":42000,"n":"קונפינו, יצחק מירושלים","b":"מקובל,מחכמי ירושלים-תק\"י"},{"i":42001,"n":"קונפינו, יצחק מירושלים","b":"מקובל מחכמי ירושלים-תס."},{"i":42002,"n":"קונפינו, שבתי משלוניקי","dt":"תקי","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":42003,"n":"קונפראדו, יהודה משלוניקי","b":"דיין בשלוניקי"},{"i":42004,"n":"קונפראדו, יעקב משלוניקי","f":"משה פירפיניאן","dt":"שפה - ח אד\"א","dp":"שלוניקי","b":"מחכמי שלוניקי. נפטר צעיר."},{"i":42005,"n":"קונפראדו, שמעיה משלוניקי"},{"i":42006,"n":"קונציו, יוסף מאסטי","k":"בעל דברי אסתר","b":"רב באסטי. חיבר \"דברי אסתר\" - אסטי."},{"i":42007,"n":"קונקי, אברהם מאלגיר","f":"שלמה","b":"תלמיד הרשב\"ש. רב במארקא-אלגיר- בשנות הר', ונזכר בשו\"ת הרשב\"ש, וב\"יכין ובועז\" לבני הרשב\"ש."},{"i":42008,"n":"קונקי, אברהם מחברון","f":"לוי","k":"בעל אבק סופרים","bt":"תח","bp":"חברון","dt":"תפד - אחרי","dp":"חברון","b":"מחכמי חברון, חותנם של ר אברהם ישראל זאבי ושל ר אברהם יצחקי, בשנת תמה שליח באירופה, ואת קורותיו כתב בספר \"אבק דרכים\" בכת\"י חיבר ספר \"אבק סופרים\" אמשטרדם תסד, עם הסכמת ר נפתלי כץ אב\"ד פרנקפורט שארחו בביתו. כנראה מקורב לשבתאות."},{"i":42009,"n":"קונקי, ידידיה מירושלים ואלגיר","b":"מחכמי ירושלים בשנת תקך, חברו של ר יהודה עייאש המזכירו בספרו \"וזאת ליהודה\"."},{"i":42010,"n":"קונקי, יוסף מחברון","k":"בעל ספר על הסמ\"ג","bp":"חברון","dp":"חברון","b":"מחכמי חברון וירושלים, חבר בית דינו של ר אברהם יצחקי, בן אחיו של ר אברהם קונקי. היה רבו של ר יצחק רפפורט בעל \"בתי כהונה\". חיבר ספר על הסמ\"ג שאבד ברובו. ר חיים בנבנישתי מזכירו בספריו. הסכים על ספר \"פרי חדש\" בשנת תסה. בשנת תסד חתם על כתב שליחות ר אברהם רויגו ור חיים חזן. בשנת תנא בשליחות באלגיר, ובשנת תעח שליח צפת בתורכיה."},{"i":42011,"n":"קונקי, שמואל מגיברלטר","b":"מחכמי גיברלטר-שנות התק'. חיבר הגהות והערות על ספר הזכרונות למהר\"ש אבוהב - ונדפס."},{"i":42012,"n":"קונשטט, אברהם אריה מפרשבורג","f":"אליעזר ליפמן מפרשבור","b":"בנו - ר ברוך מפולדא."},{"i":42013,"n":"קונשטט, אברהם מפרשבורג","bt":"תריב","dt":"תרצה","dp":"פרשבורג","b":"מחכמי פרשבורג ומראשי החברא קדישא."},{"i":42014,"n":"קונשטט, אלחנן מירושלים","f":"ברוך מפולדא","b":"ראש ישיבת קול תורה בירושלים-תשכז על מקום אביו."},{"i":42015,"n":"קונשטט, אליעזר ליפמן מפרשבורג","f":"אברהם אריה","bt":"תקסד","bp":"פרשבורג","dt":"תרנה - יג אדר","dp":"פרשבורג","b":"תלמיד החת\"ס ומחכמי פרשבורג. חתן ר מיכאל אליעזר פריישטאט מפרשבורג. היה בלן במקוה בפרשבורג וב\"חתן סופר\" מביא עדות ממנו בשם החת\"ס בענין שיעור המקוה. החת\"ס היה מסדר קידושיו ואסר לנגן בגלל שבאותו היום נודע על פטירת מהר\"ם בנעט."},{"i":42016,"n":"קונשטט, ברוך מפולדא","f":"אברהם אריה מפרשבורג","k":"בעל יענה ברוך","bt":"תרמו","bp":"פרשבורג","dt":"תשכז - טו שבט","dp":"ירושלים","b":"תלמיד הדעת סופר. מג\"מ בפרשבורג בחברה \"אגודת רעים\"-נוסדה תרסד, דיין בופלדא-תרעד. ניצל מהשואה ועלה לירושלים, הקים את ישיבת \"קול תורה\" יחד עם ר יחיאל מיכל שלזינגר, ועמד בראשה, בנו ר אלחנן על מקומו אחריו. חתנו - ר קלמן כהנא - רב בקיבוץ חפץ חיים בעל שנת השבע."},{"i":42017,"n":"קונשטט, יעקב קופל חריף מוערבוי","f":"צבי הירש","k":"בעל חידושי יעב\"ץ","bt":"תקכו","dt":"תקצו - כא כסלו","b":"תלמיד ר יוסף שטינהרט בעל \"זכרון יוסף\", בעל \"נודע ביהודה\", חתן ר אברהם פעסעלס משטמפן (או של בנו ר שמואל). רב בקדלבורג(=קרלבורג)-תקנא, וערבוי-תקנג וראש ישיבה. בניו - ר אברהם יחזקאל רייך בעל \"תורת יחזקאל\", אפרים שמעון. נכדו - ר יעקב קופל דושינסקי הו\"ל \"תולדות יעקב\" לתולדותיו. מתלמידיו: ר אשר יונגריז מטשנגר בעל \"מנוחת אשר\", ר יאול אונגר מפאקש בעל שו\"ת ריב\"א, ר דוד שיק מטאקאי, ר חיים צבי מנהיימר מאונגוואר, ר יצחק אהרן לנדסברג, ועוד."},{"i":42018,"n":"קונשטט, יצחק מגרוסורדין","f":"אליעזר ליפמן","k":"בעל לוח ארז-תרמו","bt":"תקצח","bp":"פרשבורג","dt":"תרסט - כא סיון","dp":"רדיביץ","b":"תלמיד ר חזקיה פיבל פלויט בשוראן, הכת\"ס ולמד עם בנו השב\"ס. חתן ר יוסף גינז-שלזינגר מוינה ופרשבורג - חתנו החורג של החת\"ס ועבר אל חותנו בפרשבורג ובוינה, בזיוו\"ש חתן ר אפרים מרדכי פוהרילס מאושטיצקי. רב באבון(אבאני)-מחוז פשט-תרכב על מקום ר יעקב הרצוג בעל \"פרי יעקב\", רב ה\"קהלה הקטנה\" שהתפלגה מהקהלה החרדית בגרוסורדין-תרמב, רדוביץ(=רדיוויץ)-תרמג. (במורשת הונגריה - היה רב בקהילת הסטטוס-קוו בגרוסורדין עד שהוכרזה כאורטודוכסית ובה בעת גם בקלויזנבורג). חיבר חוברת הספד בגרמנית לר שמעון סופר מקראקא."},{"i":42019,"n":"קונשטט, מאיר מוינה","f":"יצחק מראדיביץ","b":"תלמיד השב\"ס, מחכמי וינה. הו\"ל ספר אביו \"לוח ארז החדש\". תשובה אליו ב\"שבט סופר\"."},{"i":42020,"n":"קונשטט, מיכאל מפרשבורג","f":"אליעזר ליפמן","bt":"תרא","bp":"פרשבורג","dt":"תרעו - י סיון","dp":"פרשבורג","b":"תלמיד הכת\"ס. שו\"ב וש\"ץ בפרשבורג, מלמד ב\"יסודי התורה\" בפרשבורג-תרמה, וישב לצדו - ר פייש פישמן ונאמר עליהם \"ר מיכאל מימין מהלל ור פייש משמאל ממלל\"."},{"i":42021,"n":"קונשטט, צבי","b":"רב-שנת תק\"מ"},{"i":42022,"n":"קונשטט, צבי הרש מוינה","f":"אליעזר ליפמן מפרשבור","bt":"תרה","bp":"פרשבורג","dt":"תרצג","b":"תלמיד הכת\"ס. חתן ר יצחק יהודה ליב פריישטט מוינה. מחכמי וינה. חתנו ר דוד שפיצר מוינה, ונכדו - ר שלמה שפיצר מירושלים מחבר ספרים לתולדות ישראל."},{"i":42023,"n":"קוסביצקי, משה","f":"אביגדור","bt":"1899","bp":"סמרגון","dt":"1966","dp":"ניו יורק - ירושלים","b":"תלמיד בישיבת מייליס בוילנא. למד אצל החזנים אפרים שליאפאק בסמרגון, אליהו זלודקובסקי בוילנא, ופרו' לודביג. חזן בביה\"כ הגדול בוילנא, מ.\"מ החזן סירוטה בוארשא, למד אצל לליווא, מגנס ועוד. הופיע בקונצרטים, ביקר בארץ-1934, בניו יורק-1938, בזמן השואה ברח לרוסיה ואחריה עבר לארה\"ב. נחשב לגדול החזנים בזמנו - וסירב להצעות להופיע באופרה."},{"i":42024,"n":"קוסובינר, צבי מירושלים","dt":"תרטו - ט טבת","dp":"ירושלים","b":"מחכמי ירושלים"},{"i":42025,"n":"קוסובסקי, אברהם אבלי מירושלים","f":"יהושע","bp":"ליטא","dt":"תרנה - י טבת","dp":"ירושלים","b":"עלה מוילקוביסק ליטא, בשנת תרטז היה בירושלים, כיהן כדיין בית הדין שבחורבת ר יהודה החסיד. משגיח ובוחן בת\"ת \"עץ חיים\"-תרכב, בנו - ר יהושע חיים בעל \"הקונקורדנציה\"."},{"i":42026,"n":"קוסובסקי, אהרן דוד מיאנוב","f":"יעקב דב","bt":"תרטז","b":"רב ביאנובה-פלך גרודנא-תרסא, פראזאווע-פלך גרודנא-תרסה."},{"i":42027,"n":"קוסובסקי, חיים יהושע","f":"אברהם אבלי קוסובסקי","k":"בעל הקונקורדנציה","bt":"תרלג","dt":"תשכ - כה אייר","b":"רב בוילקוביסק, ירושלים. חיבר \"מעיני הישועה\". פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, רסם מאמרים ב\"המאור\" - תל אביב תרצה, \"קול תורה\" - ירושלים תרץ. חתנו - ר ישראל ליבוביץ.","bk":[["אוצר התרגום",""],["אוצר לשון התוספתא",""],["מבשרת ירושלים",""],["מפתח לתורה",""],["ספר התושיה",""],["אוצר לשון המשנה - קורקודנציה למשנה",""],["אוצר לשון התוספתא - קורקודנציה לתוספתא",""],["יד הלשון - דקדוק",""],["מעייני הישועה",""],["תורת החשבון - חשבון",""]]},{"i":42028,"n":"קוסובסקי, יוסף עקיבא מוילנא","f":"מרדכי מקאסאווי","dt":"תרך - ד אייר","dp":"וילנא","b":"חתן ר מיכעלע זעזמיר. גביר מחכמי וילנא. תרם לשיקום והחזקת בתי הקברות בוילנא וסביבתה, גבאי ומנהל ת\"ת, וסייע לרעבים בשנות הרעב - יחד עם חברו הגביר ר אריה לבנזון. נוסח מצבתו מאת אד\"ם הכהן."},{"i":42029,"n":"קוסובסקי-שחור, יחיאל מיכל","f":"יצחק מיוהנסבורג","dp":"תשכד - כו ניסן","b":"רב בליטא. ניצל מהשואה והצטרף אל הוריו ביוהנסבורג. רב ביוהנסבורג-תשיב על מקום אביו. גיסו(בעל אחותו) - ר ישראל בן ירוחם ליבוביץ."},{"i":42030,"n":"קוסובסקי-שחור, יצחק","f":"שאול","k":"בעל שבת ומועד","bt":"תרלח","bp":"בוטען","b":"נכד-אבי אביו ר חיים ליב שחור ממיר, ומצאצאי ר יעקב ברלין-אחיו של הנצי\"ב, ונכד-אבי אמו ר זאב וולף רידקין מבוטען. תלמיד גיסו ר יוסף דוד שחור מסמיאטיץ, ישיבת טלז. רב באיוויע-תרסה, אגוסטוו(=אוגוסטוב)-תרפה, וולקוביסק, רב ראשי ביוהנסבורג-תרצד ובנו ר יחיאל מיכל על מקומו אחריו. פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ, \"בית מדרש\" - תל אביב תשא - לתולדות ר חיים עוזר גרודזנסקי, \"פרי עץ חיים\" - טלז תרצט - קובץ תלמידי ישיבת טלז, \"תלפיות\" - נ\"י תשד. חתנו - ר ישראל ליבוביץ בן המשגיח ממיר."},{"i":42031,"n":"קוסטא די, אברהם מארה\"ב"},{"i":42032,"n":"קוסטא די, בנימין מלונדון","dt":"תקכד","dp":"לונדון?","b":"גביר בלונדון, יסד ישיבה-תצד בלונדון בשם \"מחנה רפאל\", ויסד עם הגביר ר יצחק דוד לעווי את ישיבת \"אספת חברים\"."},{"i":42033,"n":"קוסטא די, יצחק מלונדון","dt":"תקכד","b":"תלמיד ר דוד ניטו מלונדון. רב בלונדון, הגיע לאמריקה-תקי, וכיהן כרב בצ'רלסטון-תקכב, על מקום ר משה הכהן."},{"i":42034,"n":"קוסטא, שלמה מליוורנו","b":"מחכמי ליוורנו, דודו של ר חזקה די סילבה בעל \"פרי חדש\"."},{"i":42035,"n":"קוסטא, שמואל מליוורנו","b":"רב בליוורנו, נזכר בשות מהרי\"ף - ר יעקב פרג'י."},{"i":42036,"n":"קוסטליץ, גבריאל משטיינמנגר","f":"אהרן","k":"בעל מים מגבא","dt":"תרעח - א אלול","dp":"ירושלים","b":"תלמיד הכת\"ס, ור נצתן בנימין ליבר מפרשבורג. חתן ר אהרן אלעזר גשטטנר משארקאני. מחכמי שטיינמאנגר, עלה לירושלים והיה ממקורבי ר יוסף חיים זוננפלד."},{"i":42037,"n":"קוסטלניץ, יהודה ליב מסלונים","b":"רב בחבורת קוברין, סלונים, עלה לארץ תרלו. סופרו של ר אברהם וינברג האדמור מסלונים הראשון. בנו ר מרדכי חיים התמנה לאדמור מסלונים-תשי בירושלים."},{"i":42038,"n":"קוסטלניץ, מרדכי חיים מסלונים","f":"יהודה ליב","k":"אדמור מסלונים בישראל","r":"דיין בטבריה, וממונה כולל רייסין, בסוף ימיו מנהיג עדת חסידי סלונים, הסיפורי נכתבו על ידי הרה\"ח ר' פנחס שמעון קופילוביץ","bt":"תרכח","dt":"תשיד - יב טבת","dp":"ירושלים","b":"עלה לארץ-תרלו. חתן ר אליעזר כץ מצפת, ובזיוו\"ש חתן ר משה פטרושקא. מחשובי חסידי סלונים, תלמיד ר דוד מלובין-צפת. התמנה לאדמור-תשי בגיל 82 אחר הרצחו בשואה של האדמור ר שלמה דוד יהושע מסלונים ברנוביץ ור שלמה דוד יהושע וינברג על מקומו אחריו. דיין בטבריה-תרעד, ירושלים-תרצז. חיבר \"מאמר מרדכי\". מתולדותיו ב\"מרביצי תורה מעולם החסידות\".","bk":[["מאמר מרדכי",""],["סיפורי מרן הרמ\"ח - סיפורי צדיקים שנשמעו מפי",""],["סיפורי מרן הרמ\"ח - סיפורי צדיקים שנשמעו מפי, מאמר מרדכי",""]]},{"i":42039,"n":"קוסטקובסקי, איזיק","dt":"תשג","b":"רב בלומזה"},{"i":42040,"n":"קופאנו, דוד מירושלים","dp":"ירושלים","b":"מחכמי ירושלים-שנות ה-תק'."},{"i":42041,"n":"קופהון, דובריל מקולומיאה","b":"מחכמי קולומיאה. תשובה אליו - \"אורין תליתאי\"."},{"i":42042,"n":"קופטיל, דוד יצחק מצאנז","f":"חיים צבי","dt":"תרפא","b":"רב בביסטריץ-תרטז, יסד בימ\"ד לחסידי צאנז-סיגט והחזיק שם ישיבה."},{"i":42043,"n":"קופטשיק-נהיר, צביהירש","f":"שמחה קופשטיק","bt":"תרלו","dt":"תשכ - ב אב","b":"רב בשדה לבן-תר\"ס,עלה לא\"י-תרפ\"ד"},{"i":42044,"n":"קופיא, שרה סולס","b":"אשה משכילה מאיטליה (ונציה). חיברה שירים ומאמר השארות הנפש ונדפס בונציה. ר יהודה אריה ממודנא מזכירה לשבח בהקדמת חבורו אסתר - שנכתב לכבוד האשה הזאת."},{"i":42045,"n":"קופיאנס, משה משלוניקי","b":"נבחר לפרלמנט היוני מטעם שלוניקי, ושר הכספים, עלה לארץ והיה שגריר ישראל ביון-1949."},{"i":42046,"n":"קופיו, יצחק מקאשטוריה","f":"מיכאל","b":"דיין בקאשטוריאה-שנות ה-תק' אצל ר אברהם גראסיאני."},{"i":42047,"n":"קופיל דיין מלובלין","b":"מחברי הח\"ק בלובלין. חתם-תפג בפנקס הח\"ק."},{"i":42048,"n":"קופיל מאפטא","b":"תלמיד החוזה מלובלין, היהודי הקדוש מפשיסחא, ור מנחם מנדל מקוצק. נפטר בן למעלה מ-90."},{"i":42049,"n":"קופילוביץ, מנחם נחום מואשלישוק","b":"גביר בואשלישוק. חתנו - ר מנחם אליעזר בעל יעיר קינו."},{"i":42050,"n":"קופילטוס, משה","f":"זלמן","b":"גיסו של ר ישראל זקנו של ה\"ישמח משה\"."},{"i":42051,"n":"קופילטיס, זלמן","f":"קופל","b":"חתן נכדת הט\"ז. זקנו של ר מנחם מנדל מקוסוב."},{"i":42052,"n":"קופילטיס, יהודה ליב מקולומיאה","f":"אפרים פישל","bt":"תקפה","bp":"קולומיאה","b":"חתן ר אליעזר בר מסקאלא. עלה לארץ-תרה והתישב בצפת."},{"i":42053,"n":"קופילטיס, קופל","bp":"שנייטוך","b":"אבי משפחת קופילטיס (על שמו - קופל). אחיינו של התוי\"ט. גורש מאשכנז והתישב בקולומיאה. גביר ותלמיד חכם."},{"i":42054,"n":"קופימן, אהרן","f":"אלכסנדר","bt":"1803","bp":"גרודנא","dt":"1893","dp":"פטרבורג","b":"בקי בשפות, אמנותת. בעל ספריה גדולה ובה כתבי יד עתיקים. התעשר ממסחר בעצים והיה גביר בפטרבורג, מייסדי ביה\"כ הגדול בפטרבורג, ועסקן במוסדות ציבור שונים."},{"i":42055,"n":"קופין, יעקב מבודה","f":"מנחם","b":"רב בבודין(=בודה)-שנות ה-ש'."},{"i":42056,"n":"קופינו, אליעזר","b":"אין פרטים."},{"i":42057,"n":"קופיץ, דב בר","b":"מו\"צ בוורשה-תר\"ע"},{"i":42058,"n":"קופל מפפד\"מ","f":"גימפל","k":"בעל מנהגים דקהלתנו","b":"מחכמי פפד\"מ. חיבר עם אחיו ישראל - ספר על מנהגי קהלת פפד\"מ - פפד\"מ תקסח."},{"i":42059,"n":"קופל מקראקא","f":"ר\"נ","b":"מחכמי קראקא. נהרג עק\"ה."},{"i":42060,"n":"קופל, אליהו הלוי מטורקא","dt":"תרצו - בערך","b":"מחכמי טורקא. תשובה אליו - \"שושנים לדוד\"."},{"i":42061,"n":"קופל, יודל מבלטאשנא","b":"רב בבאלאטאשאנא. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":42062,"n":"קופל, יוסף יצחק מגבוזדזיץ","b":"רב בגוזדזיץ. תשובה אליו - \"האלף לך שלמה\"."},{"i":42063,"n":"קופל, יצחק מנימוז'ה","f":"יהושע צבי","k":"בעל אמרי חי-תשכט","bt":"תרכז","bp":"נימוז'ה","dt":"תשד - יז אדר","b":"תלמיד בעל \"קדושת יו\"ט\" בסיגט. חתן ר אהרן ברגפלד, וגיסו של ר צבי ברגפלד מנימוזה. מלמד לנערים בנימוז'ה, עבר לדעש. כתביו אבדו בשואה, ובנו ר אברהם הציל חלק מהם אחר השואה. נדפסו בתוך \"ארחות המשפטים\" - תל אביב תשכט."},{"i":42064,"n":"קופלביץ (אלמוג), יהודה","f":"דוד","k":"בעל חבל סדום","bt":"1896","bp":"סולי-פלך וילנא","b":"ממשפחת ר חיים עוזר גרודזנסקי. תלמיד ישיבת וולוזין. הצטרף לתנועת \"החלוץ\" והיה עוזרו של יוסף טרומפלדור, עלו לארץ-1920, בשליחות ברוסיה ואירופה, בפרס והיה ציר מטעם פרס בקונגרס הציוני ה-יז. ממיסדי קיבוץ \"רמת רחל\"-1934, פועל בסדום, ראש מועצת איזור \"תמר\". חיבר \"חבל סדום\" יחד עם בן ציון ונסקי-אשל. ?? לא באוצר ??"},{"i":42065,"n":"קופלוביץ, אברהם צבי מסללונים","f":"חיים","bt":"תרכה","b":"ר\"מ וראש ישיבה בסלונים-תרנט, רב בזעלווא-פלך גרודנא-תרסו."},{"i":42066,"n":"קופלוביץ, יצחק מדרביאן","b":"רב בדרביאן על מקום ר ישראל איסר לוין."},{"i":42067,"n":"קופלוביץ, מנחם מסקופישוק","dt":"תשג","b":"רבה האחרון של סקופישוק(=סקאפישק). נספה בשואה."},{"i":42068,"n":"קופלוביץ, צבי הירש","bt":"תרכה","b":"ראש ישיבה בסלונים-תרנ\"ט,רב בזעלווא-תרס\"ו"},{"i":42069,"n":"קופלושניק, ראובן","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":42070,"n":"קופלזון, צמח","bt":"1869","bp":"וילנא","dt":"1934","dp":"מוסקבה","b":"תלמיד גימנסיה בפוניבז. הצטרף ל\"בונד\", היגר לניו יורק-1905. למד רפואה. ניהל הוצאת ספרים סוציאליסטית. חיבר ספר זכרונות. עבר לרוסיה-1923 והיה חבר בועדה לחקר תולדות תנועת הפועלים היהודית."},{"i":42071,"n":"קופלמן, יצחק דב מניו יורק","k":"בעל קובץ שיעורים","bt":"תרסו","bp":"חרקוב","b":"תלמיד ר שמעון שקופ בגרודנה. גלה ללסיביר במלחה\"ע ה-I, ואחריה ראש ישיבת קאפלען באנטורפן, ראש ישיבת \"שערי יושר\" בניו יורק, ראש ישיבה בלוצרן על מקום ר משה סולוביציק. הציל את כתבי רבו ומהם נדפס חדושי רבי שמעון שקופ."},{"i":42072,"n":"קופלמנש, מרדכי","k":"בעל פירוש לתפלות","dt":"תד - יד סיון","b":"מגדולי חכמי קרקא"},{"i":42073,"n":"קופלר, מנשה מבריגל","bt":"תרך","dt":"תרץ","b":"רב בבריגל עם ר חיים טיטלבוים. בנו ר שלום על מקומו אחריו."},{"i":42074,"n":"קופלר, משה יעקב מסיגט","b":"מזכיר הקהלה בסיגט. כתב דף מגילת יוחסין-תרצח."},{"i":42075,"n":"קופלר, משלם מפליפטש","b":"מחכמי פליפטש. תשובה אליו - \"מחזה אברהם\"-תרסה."},{"i":42076,"n":"קופלר, שלום מבריגל","f":"מנשה","bt":"תרסט","dt":"תש..","b":"ר\"מ בישיבת גורליץ. רב בבריגל על מקום אביו. נספה בשואה."},{"i":42077,"n":"קופלר, שמואל ממריאמפול","f":"אברהם דוד מרבינו מקמ","k":"אדמור ממירופול נ\"י","dt":"תרצח - כ סיון","b":"נכד ר שמואל מקמינקא. היגר לארה\"ב-תרפג, וכיהן כאדמור מקמינקא, וכונה \"הצדיק ממירופול\". חיבר \"תפארת שמואל\". מתורתו בכתב העת \"הפרדס\". בנו ר משה - לא נהג אדמורות."},{"i":42078,"n":"קופנהגן, חיים מיכאל","f":"לייזר-אב\"ד קיל","k":"בעל צפירת תפארה","b":"מחכמי רוגוזין. חיבר \"הלכות תפילין\" עם תרגום גרמני בשם \"צפירת תפארה\" - ברסלוי תקצב."},{"i":42079,"n":"קופר, נתן אבא","f":"אהרן יחיאל","b":"מו\"צ בלודז-תר\"פ"},{"i":42080,"n":"קופרברג, אברהם מברוד","b":"רב בסטניסלב. חתנו ר פנחס רימלט אב\"ד זולקוא. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":42081,"n":"קופרואסר, יצחק מאיר מקאליש","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":42082,"n":"קופריץ, יעקב אהרן מסומלישאק","k":"בעל נהורא דיעקב","bp":"זעזמיר","b":"רב בסומלישאק-פלך וילנא."},{"i":42083,"n":"קופרמן, חיים צבי מאושפיצין","f":"משה מאושפיצין","bt":"תקסב","dt":"תרמב","b":"שם המשפחה המקורי היה קליינהנדלר. חתן הגביר ר לייבל שיינברג. תלמיד ר דב בר פרומר מאושפיצין. רב באושפיצין על מקום רבו. ידידו של ר האדמור שלמה מבובוב."},{"i":42084,"n":"קופרמן, חיים צבי מאושפיצין","f":"יעקב אלעזר","b":"ניצל מהשואה, כיהן כרב באושפיצין (אושוויץ) אחר השואה. היגר לארה\"ב, מחסידי בובוב בניו יורק. חתן ר שמואל שמלקא ספרין מעיר ישן (חתנו של ר אליהו בומבך מאושפיצין). ההדיר את ספר חותנו זקנו \"אהל יהושע\"."},{"i":42085,"n":"קופרמן, יוסף משלם","f":"ברוך","k":"קאפיר מאן","b":"חיבר חדושים על שו\"ע קולמיאה תקצח - בכתב יד."},{"i":42086,"n":"קופרמן, יצחק","f":"דוד מאושפיצין","b":"מחכמי וינה-תרסד. ממקורבי ר בן ציון מבובוב."},{"i":42087,"n":"קופרמן, יצחק סנדר","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"תלפיות\" - שנחאי תשו."},{"i":42088,"n":"קופרניק, אברהם","f":"אהרן קופער","k":"בעל לקורות בני ישראל","bt":"1821","bp":"וילנא","dt":"1893","dp":"דעמציבא","b":"חתן ר יעקב שמרל הלפרין מוילנא. תלמיד ישיבת וולוזין, משכיל חובב תורה. מתומכי ה\"כולל\" בקובנא. עבר לקיוב והיה פעיל ציבור. פרסם ב\"המליץ\". חיבר \"לקורות בני ישראל בקיוב\", (ובעיר וילנא מעיר כי יש בספרו הרבה השמטות). בנו ליאון - עורך דין מפורסם והסניגור במשפט עלילת הדם בקוטאיס."},{"i":42089,"n":"קופרשטוק יצחק נתן","bt":"1922","dt":"ה'תשעא 2011","bk":[["מאורות נתן",""],["מאורות נתן – חנוכה, פורים, חשמל בשבת",""]]},{"i":42090,"n":"קופרשטוק, ישראל ניסן ממאקובה","f":"משה אריה","k":"בעל עני בן פחמא","bt":"תריח","dt":"תרץ","b":"גיסו של ר יחיאל האדמור מאלכסנדר. חתן ר ראובן יהודה (חתנו של ר שרגא פיבל דנציגר ממאקובה), ובזיוו\"ש חתן ר שמואל יעקב קופיל קליגסברג מקאלושין. רב בפרשיסחא, ריזאן, מאקובה כ-40 שנה. עלה לירושלים-תרפה ויסד ישיבה \"ישמח ישראל\" אלכסנדר, והיה מראשי חסידות אלכסנדר."},{"i":42091,"n":"קופרשטין, אברהם אליעזר מלמברג","f":"טוביה מלמברג","dt":"תשב","b":"מראשי המזרחי בלמברג, צעורכי יודישע בלעטער וממשתתפי \"בת קול\", \"המסילה\" ועוד. נספה בשואה."},{"i":42092,"n":"קופרשטין, שמחה מוערעשואר","k":"בעל שירת האדון","b":"רב בווערעשוואר-תר\"ך"},{"i":42093,"n":"קופרשמיד, שמעון צבי מנריוב","b":"רב בנריוב-תרמג."},{"i":42094,"n":"קופשטין, יהודה הלוי","f":"יעקב קופשטיין","b":"רב באנסאניע-תר\"ע"},{"i":42095,"n":"קופשטין, יעקב הלוי מנימנצין","f":"מרדכי סנדר","k":"בעל בית לוי","bt":"תרז","dt":"תרצד - יז תשרי","b":"מו\"ץ בלידא-תרלג אצל ר מרדכי מלצר, רב בנימענצין-פלך וילנא-תרמד. פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט. נסמך מאת: ר מרדכי מלצר מלידא, ר איזיק חריף מסלונים, ר אליהו שיק מלידא, ר אברהם שמואל דיסקין מוולקוביסק. חיבר גם \"פרי יעקב\", \"תורת הלויים\", \"שם יעקב\", ועוד. מתורתו בספרי חכמי דורו ובהם \"גן צבי\", \"ברית יצחק\", \"שמן למאור\" ועוד. בניו: ר מרדכי סנדר מראדין, ר יהודה מאנסאניע-ארה\"ב, ר אליעזר מטאווריג."},{"i":42096,"n":"קופשטין, מרדכי סנדר","f":"יעקב מנימנצין","b":"רב בראדין, עלה לא\"י-תרצ\"ד"},{"i":42097,"n":"קופשטין, צבי הירש","b":"החזיק בהעתק פנקס ח\"ק באוסטרהא."},{"i":42098,"n":"קופשטין, שמחה מבודפשט","b":"רב בבודפשט."},{"i":42099,"n":"קופשטיק, צבי משדה לבן","b":"אב\"ד שדה לבן (רוסיה). חתנו - ר בנימין זאב בנדיקט מחיפה. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":42100,"n":"קופשטיק, שמחה","dt":"תרס","b":"רב בשדה לבן. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":42101,"n":"קוק, אברהם יצחק הכהן-ראי\"ה","f":"שלמה זלמן","k":"בעל שבת הארץ","r":"הרב הראשי לארץ ישראל","bt":"תרכה","bp":"גריווא-קורלנד","dt":"תרצה - ב אלול","b":"תלמיד ר יעקב בן מרדכי גימפל יפה בלוצין, סמרגון, ר ראובן מדוינסק. תלמיד ישיבת לוצין, סמרגן-תרמג, וולוזין וכונה \"העילוי מפוניבז\" והנצי\"ב אמר עליו \"זה שנים רבות לא ראתה וולוזין בחור כזה\". חתן ר אליהו דוד תאומים מפוניבז - האדר\"ת. בהתחלה סירב לרבנות אולם בהשפעת החפץ חיים הסכים, וכיהן כרב בזיימל, בויסק. רב ביפו-תרסג על מקום ר נפתלי הרץ. בזמן מלחה\"ע ה-I היה בשוויץ-תרעד, רב בלונדון-תרעו. רב בירושלים-תרעח, הקים ישיבת \"מרכז הרב\" בירושלים-תרפא. רב ראשי בארץ ישראל-תרפא. בשליחות בארה\"ב-תרפד עם ר משה מרדכי אפשטין, ור א.ד. שפירא מקובנא. ביקר בראש משלחת רבנים במושבות החדשות בארץ-תרפז. חיבר ספרים רבים ומאמרים רבים. בנו ר צבי יהודה. הו\"ל כתב עת \"עיטור סופרים\" - וילנא תרמח. פרסם מאמרים ב\"הפלס\" - ברלין תרסא-תרסה, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז, \"קול תורה\" - ירושלים תרץ, \"תורה מציון\" - ירושלים תרנה-תרסה.","bk":[["משפט כהן","שו\"ת - אחרונים"],["דעת כהן","שו\"ת - אחרונים"],["עזרת כהן","שו\"ת - אחרונים"],["אורח משפט","שו\"ת - אחרונים"],["אורות התשובה","מחשבה ומוסר - אחרונים"],["אגרות הראיה",""],["אדר היקר ועקבי הצאן",""],["אורות",""],["ארץ חפץ",""],["באר אליהו",""],["זבחי ראיה",""],["זכרון ראי\"ה",""],["חבש פאר - תפילין",""],["חזון הגאולה",""],["טוב ראי",""],["מאמרי הראיה",""],["מדבר שור",""],["מוסר אביך ומדות הראיה",""],["מצות ראיה",""],["משנת הרב",""],["סדר תפילה והודאה",""],["עולת ראיה – הגדה של פסח",""],["עטור סופרים",""],["עין איה – עין יעקב",""],["עץ הדר",""],["קובץ מאמרים",""],["ראש מילין",""],["שבת הארץ",""],["שמונה קבצים",""],["שמועות ראי\"ה",""],["כתבי הראי\"ה (הרב קוק)",""]]},{"i":42102,"n":"קוק, דב הכהן מקרוק","f":"שלמה זלמן","bt":"תרלג","bp":"גריווא-קורלנד","dt":"תשי - יח אדר","dp":"ירושלים","b":"אחיו של הראי\"ה. רב בקרוק-מחוז שאוולי - פלך קובנא, יליזבטגרד, עפולה-תרפו מנהל המכון התורני \"הרי פישל\" בירושלים. בנו - ר רפאל מטבריה."},{"i":42103,"n":"קוק, חיים","bt":"תרכז","b":"רב בגוטבורג-תרנ\"ז"},{"i":42104,"n":"קוק, נחום הכהן","f":"יצחק הכהן","b":"חתן ר דובער יפה (המכונה ר בעריל קארעליטשער). נפטר צעיר ואשתו נישאה לר עזריאל מרעזיצא, בנו - ר שלמה זלמן ונכדו ר אברהם יצחק הכהן קוק."},{"i":42105,"n":"קוק, צבי יהודה מירושלים","f":"אברהם יצחק הכהן","k":"בעל למצות הארץ","bt":"תרנא","bp":"זיימל","b":"עלה עם אביו לארץ. תלמיד ישיבת \"תורת חיים\" בירושלים. ראש ישיבת \"מרכז הרב\". הו\"ל את ספרי אביו. פרסם מאמרים ב\"תבונה\" - ירושלים תשא-תשח."},{"i":42106,"n":"קוק, רפאל הכהן מטבריה","f":"דוב קוק","dt":"תשל","b":"רב בטבריה-תשל. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה - ירושלים תשא, \"המאור\" - תל אביב תרצה, \"קול תורה\" - ירושלים תרץ-תשז."},{"i":42107,"n":"קוק, שלמה הכהן","f":"רפאל קוק","dt":"תשלב","b":"רב ברחובות-תשכ\"ח"},{"i":42108,"n":"קוק, שלמה זלמן הכהן","f":"נחום קוק","k":"אבי הראי\"ה קוק","dt":"תרפט - כג שבט","b":"לאחר פטירת אביו גדל אצל אביו חורגו ר עזריאל מרעזיצא. חתן ר רפאל בן אברהם מפריל ושעביז. שד\"ר ישיבת וולוזין, וישיבת \"עץ חיים\" בירושלים. עלה לירושלים-תרסט. חתן ר רפאל מגדולי חסידי ה\"צמח צדק\" ונכדת המקובל ר אברהם אב\"ד סאבז' ופרייל."},{"i":42109,"n":"קוק, שמואל חנא מירושלים","b":"פרסם מאמרים ב\"אפריון\" - בודפשט תרפד, \"בית הכנסת\" - תל אביב תשו, \"הדביר\" - ירושלים תרעט."},{"i":42110,"n":"קוקומריל, דוד מאלגיר","bt":"קץ","dt":"רס - בערך","b":"רב באלגיר, מקורב לר\"י אברהם ששפורטש מהוניין ונזכר בספרו."},{"i":42111,"n":"קוקוס, יהושע","b":"מגדולי חכמי פאס-ש\"ה"},{"i":42112,"n":"קוקוש, יוסף מפרשבורג","b":"חזן בביהכ\"נ הגדול בפרשבורג בזמן הכת\"ס."},{"i":42113,"n":"קוקיא, אפרים הלוי מירושלים","f":"יעקב","k":"בעל ילקוט אפרים","bt":"תקעד","bp":"אחיזקא","dt":"תרן - ט כסלו","dp":"ירושלים","b":"עלה לירושלים-תרל עם בניו דוד ויוסף, הקים ישיבה בביתו בשם \"אהל יעקב\"."},{"i":42114,"n":"קוקיא, בנימין מירושלים","bp":"טיפליס","b":"עלה לירושלים בילדותו, תלמיד \"דורש ציון\", גביר בירושלים."},{"i":42115,"n":"קוקיא, יוסף הלוי מירושלים","b":"רב בירושלים, חתם-תרמא עם ר זלמן ראם, ר אברהם מבורך ועוד."},{"i":42116,"n":"קוקס, יוסף מברעזין","f":"אליהו חיים","k":"בעל עדות ביהוסף","bt":"תרא","bp":"קאיידנוב","b":"תלמיד ר שמחה שמואל מסטופצי בעל \"משרת משה\". רב בטשערקוב-פלך מוהילוב-תרכה, שויסלאץ-פלך מינסק, פראפאיסק-פלך מוהילוב, שוערזנא(=שוורזינץ)-פלך מינסק ,שאצק-פלך מינסק, ברעזין-פלך מינסק-תרסה. חיבר גם \"עלי הגיון\", \"חקירות העדות\"."},{"i":42117,"n":"קוקס, משה מקושטא","k":"בעל אבן ספיר-כת\"י","b":"מחכמי קושטא-קן."},{"i":42118,"n":"קור, דוב (דוד) מליסקוב","dt":"תשג","b":"רב בליסקווה(=ליסקוב). פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":42119,"n":"קוראל, יהודה ישראל","dt":"תקעח - כה שבט","b":"מקובל,רבה של ירושלים"},{"i":42120,"n":"קוראל, יעקב מירושלים","k":"בעל זמרת הארץ","dt":"תקעח - כה שבט","dp":"ירושלים","b":"מחכמי ירושלים, דיין אצל ר משה יוסף מרדכי מיוחס, ואצל ר מרדכי הלוי. בשנת תקמב חתם על פסק דין, בשנת תקסא חתם על תקנת מס היורדים, ועוד. דיין אצל ר יעקב משה עייאש וראב\"ד על מקומו אחריו-תקע, בשנת תקעז נתמנה ל\"ראשון לציון\" על מקום ר יעקב עייאש, ור רפאל יוסף חזן על מקומו אחריו. חיבר \"זמרת הארץ\" שאבד, חדושים ממנו בספר \"אהל ישרים\" לר יצחק בונן."},{"i":42121,"n":"קוראל, רפאל נתן מירושלים","dt":"תקצו - בערך","dp":"ירושלים","b":"דיין בירושלים. בשליחות בתורכיה, והשיב תשובה בהיותו ביוזיל חיסאר. נספד ב\"רני ושמחי\" אזמיר תרלד."},{"i":42122,"n":"קורב, חיים יצחק מזאגר ונ\"י","f":"שאול","k":"בעל נתיבות חיים","bt":"תרלב","bp":"פילטן-קורלנד","dt":"תשיז - ג סיון","b":"תלמיד ישיבת טלז, דוינסק. חתן ר משה יצחק מפוניבז, מו\"צ בפוניבז-תרסב על מקום חותנו, פלונגיאן(=פולאנגן)-תרסח, פבלוגרד-בזמן מלחה\"ע ה-I, זאגר חדש על מקום ר יעקב כץ. היגר לארה\"ב וכיהן כרב בשיקגו, הרלם-ארה\"ב-תרפב, עלה לירושלים-תשיב. חיבר גם \"טל שחקים\", ועוד. פרסם מאמרים ב\"הנצנים\" - תל אביב תשא - קובץ תלמידי ישיבת הישוב החדש בת\"א, \"המתיבתא\" - נ\"י תשג."},{"i":42123,"n":"קורב, יעקב ישראל מגריידינג","b":"חסיד רוזין. שו\"ב וסופר בגריידינג-תרלג. בנו ר וולוויל על מקומו אחריו."},{"i":42124,"n":"קורדבני, בנימין","bt":"תרז","bp":"משהד","dt":"תרפ","dp":"ישראל","b":"הנהיג את קהילת משהד בתקופת אנוסי משהד, עלה לישראל"},{"i":42125,"n":"קורדובה די, יהושע חזקיה","k":"בעל אמת ואמונה","bt":"תפ","bp":"אמשטרדם","b":"מחכמי אמשטרדם, תלמיד ר אברהם די קוסטא אבנ דאנא, רב באמשטרדם-תקד, רב ודיין בקורסאו-תקט אצל ר שמואל מינדיס סולא, רב בג'מייקה-תקיג למעלה מארבעים שנה."},{"i":42126,"n":"קורדובה, אליהו מאזמיר","dt":"תפח - ח אייר","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":42127,"n":"קורדובה, יעקב מקושטא","b":"גביר בקושטא-שנות ה-ת', סייע ללומדי תורה."},{"i":42128,"n":"קורדובירו, אברהם"},{"i":42129,"n":"קורדובירו, גדליה מצפת","f":"משה - הרמ\"ק","bt":"שכב","bp":"צפת","dt":"שפה או שעח","dp":"איטליה או ירושלים","b":"אביו הרמ\"ק נפטר כשהיה בן 8, למד אצל ר שלמה סגיס, ואצל ר שלמה אלקבץ מחבר \"לכה דודי\" שהיה דודו. נסע לאיטליה ועסק בהדפסת ספרי אביו-שמ והתפרנס ממסחר ספרים, ונעזר על ידי ר מנחם עזריה מפאנו, הוציא לאור את ספרי אביו \"סדר עבודת יום הכפורים\" ו\"אור נערב\" וכתב להם הקדמות, וכן ספר \"פירוש שיר השירים\" לר אלישע גאליקו, וספרים נוספים. לאחר שנת שן חזר לירושלים ומתמנה ל\"שיך אל יהוד\", בשנת שעד גם ראש בית הדין, בשנת שסט בשליחות באיטליה, ר יום צהלון כותב על ויכוח הלכתי ביניהם, בינו ובין ר מנחם די לונזאנו עברו דברי ריבות כנראה מספר \"טובה תוכחת\"."},{"i":42130,"n":"קורדובירו, יהודה ממצרים","b":"מחכמי מצרים-שנות ה-ת'."},{"i":42131,"n":"קורדובירו, יהודה ממצרים","b":"מצאצאי ר משה מצפת. רב במצרים-תס בזמן ר יוסף נזיר הלוי."},{"i":42132,"n":"קורדובירו, יעקב מירושלים","b":"דיין בירושלים-תרך אצל ר חיים דוד חזן."},{"i":42133,"n":"קורדובירו, משה מירושלים","f":"גדליה בן הרמ\"ק","b":"מחכמי ירושלים, מהסובלים בפרעות אבן פארוך-שפה."},{"i":42134,"n":"קורדובירו, משה מליוורנו","b":"רופא,מרבני ליוורנו-ת\"כ"},{"i":42135,"n":"קורדובירו, משה מצפת","f":"יעקב או גדליה","k":"רמ\"ק","bt":"רנב-רפד","dt":"של - כא-ה תמוז","dp":"צפת","b":"מוצא משפחתו מקורדובה-ספרד - ומכאן שמו. אבי חכמת הקבלה בדורו, שיטתו נתפשטה ע\"י מקובלי צפת. מארבעת הנסמכים ע\"י מהר\"י בירב - בגיל 18. כיהן כדיין בצפת, תלמיד ר יוסף קארו ותשובות ממנו ב\"אבקת רוכל\". מתלמידיו - ר אליהו די וידאש, ר אברהם גלנטי, ר חיים ויטאל, ורמ\"ע מפאנו שלא פגשו מעולם אך החשיבו כרבו, לדעת רוזניס גם האר\"י. חיבר ספרים רבים בקבלה. גיסו - ר שלמה אלקבץ."},{"i":42136,"n":"קורדובירו, משה רפאל","b":"תלמיד ר שמואל ן סיד-סיריליו."},{"i":42137,"n":"קורדוברו משה","bt":"1522","dt":"ה'של 1570","bk":[["אור נערב",""],["אילמה רבתי",""],["גרושין",""],["זבחי שלמים",""],["ספר גרושין",""],["עסיס רמונים",""],["פירוש סדר עבודת יום הכפורים",""],["פירוש עבודת יום הכפורים",""],["שיעור קומה",""],["תומר דבורה",""],["תורת הקבלה",""]]},{"i":42138,"n":"קורדוזא, אברהם נוניס מארה\"ב","b":"מראשוני הקהלה בסאוואנא-ג'ורג'יה-שנות ה-ת'."},{"i":42139,"n":"קורדונסקי, אליהו הלוי","f":"אהרן אריה","k":"בעל אמרות טהורות","bt":"תרכא","b":"מצאצאי ר גדליה מלוניץ בעל \"תשואות חן\". רב בויניצא-פודוליה. חיבר גם \"אדרת אליהו\"."},{"i":42140,"n":"קורדיליא, לוי משלוניקי","b":"מחכמי שלוניקי-שץ."},{"i":42141,"n":"קורונא, יעקב אשכנזי","f":"משה","bt":"תמח","dt":"תקכט","dp":"ירושלים","b":"מחכמי ירושלים וחברו של ר יצחק זרחיה אזולאי-אבי החיד\"א, בשליחות ירושלים וחזר בשנת תפא. בשנת תצט חתם על הסכמה לספר \"אדמת קודש\", בשנת תקיח נמנה על חכמי ישיבת ר יעקב פיררה. חתנו ר משה בן שבתי יצא בשליחות בשנת תקט ובשנת תקכא, בהיותו בפרג נפגש עם ר יחזקאל לנדא המביא שאלה בשמו (\"חכם יעקב דיקורני\") בספרו \"נודע ביהודה\"."},{"i":42142,"n":"קורוניל, יצחק מאזמיר","b":"מחכמי אזמיר-שנות ה-ת'."},{"i":42143,"n":"קורונל, נחמן נתן מירושלים","f":"דוד","k":"בעל בית נתן","r":"מו\"ל תשובת הגאונים ועוד","bt":"תקע","bp":"אמשטרדם","dt":"תרן - כז אב","dp":"ירושלים","b":"תלמיד ישיבת \"עץ חיים\" באמשטרדם, מחכמי אמשטרדם, עלה לצפת ואחר הרעש לירושלים, למד ב\"בית אל\". חברו של ר יהוסף שוורץ. עסק בהוצאה לאור של כתב יד קדומים. חיבר \"בית נתן\" וינה תריד, ועוד. בשנת תרכד בשליחות באירופה. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז. הו\"ל ספרים מכתבי יד קדמונים. חתנו - ר צבי מיכל.","bk":[["בית נתן [עמ\"ס ברכות]",""],["זכר נתן",""],["בית נתן",""],["חמשה קונטרסים",""],["בית נתן – ברכות",""],["זכר נתן – דין עוברי דרכים",""]]},{"i":42144,"n":"קורח, חיים","f":"יוסף","k":"בעל ליקוטים לתורה","bt":"תקפד","bp":"צנעא","dt":"תרעד - כ אלול","dp":"צנעא","b":"מגדולי חכמי צנעא,הרביץ תורה לילדים,חיבר \"ליקוטים לתורה\" ופירושי תורה וספרי הלכה"},{"i":42145,"n":"קורח, יחיא מצנעא","f":"חיים בן יוסף","bt":"תרג","dt":"תרסח","dp":"מצרים","b":"רב בביהכ\"נ יוסף עואץ וביהכ\"נ חובארה בצנעא-תימן. עסק בהעתקת ספרי קודש. נפטר במצרים בדרכו לארץ ישראל."},{"i":42146,"n":"קורח, סעדיה מתימן","dt":"תד - בערך","b":"מקובל מחכמי תימן. רבו של ר יצחק ונה שנהיה לימים מגדולי חכמי תימן."},{"i":42147,"n":"קורח, עמרם מתימן","k":"בעל נוה שלום","bt":"תרלא","bp":"צנעא","dt":"תשיג","dp":"ירושלים","b":"רבה האחרון של תימן-תרצד, עלה לארץ-תשט."},{"i":42148,"n":"קורח, שלום מתימן","k":"בעל מדרש אשרי","bt":"תרלג","bp":"צנעא","dt":"תשיג - יג חשון","dp":"ירושלים","b":"נכד ר יוסף קורח שכיהן כרב במצרים. מחכמי צנעא-תימן. עלה לירושלים-תשי. חיבר גם \"דרך החכמים\", \"דברי שלום\", ועוד."},{"i":42149,"n":"קורטאל, שמעון משלוניקי","dt":"רצג - ז אייר","dp":"שלוניקי","b":"מחכמי שלוניקי"},{"i":42150,"n":"קורי, יצחק מאזמיר","b":"חתן ר רחמים יהודה די שיגורה. דיין באזמיר-שנות ה-תר. נזכר ב\"דרשה לחיים\" לר חיים יצחק מודעי, ב\"אברהם אנכי\" לר אברהם פלאג'י, בהקדמת מעם לועז לר חיים פלאג'י."},{"i":42151,"n":"קורי, משה הרופא מיוזיל-היסאר","b":"רופא מחכמי יוזיל-היסאר-שנות ה-ת'."},{"i":42152,"n":"קוריאט אברהם בן יהודה","bt":"1800","dt":"ה'תרה 1845","bk":[["ברית אבות",""]]},{"i":42153,"n":"קוריאט, אברהם ממרוקו - א","b":"נזכר בהקדמת \"ברית אבות\" לר משה הכהן. ראש משפחת קוריאט."},{"i":42154,"n":"קוריאט, אברהם ממרוקו - ב","bt":"תרא","b":"תלמיד ר יצחק ן ואליד. רב בטיטואן-מרוקו-תרע."},{"i":42155,"n":"קוריאט, אברהם ממרוקו - ג","f":"יהודה","k":"בעל ברית אבות","b":"מחכמי מוגדור-מרוקו. חיבר ספר פיוטים ואבד-תרד."},{"i":42156,"n":"קוריאט, אשר מצפת","b":"מחכמי ארץ ישראל, בשנת תקכג בשליחות בכורדיסטן, ובמרוקו. על שטר שליחותו חתומים - ר אברהם בן אשר, ר שלם בכר שלמה צרפתי, ר אברהם מימרן, ר שלמה צבע."},{"i":42157,"n":"קוריאט, בכור אשר מאלכנסדריה","k":"בעל אשר ברכו ה'","b":"רב באלכסנדריה-תרעח."},{"i":42158,"n":"קוריאט, יהודה מטיטואן","f":"רפאל אברהם","k":"בעל מאור ושמש","bp":"טיטואן-מקובל","b":"מחכמי טיטואן-שנת ה-תק'."},{"i":42159,"n":"קוריאט, יהודה מטיטואן-מרוקו","f":"אברהם","k":"בעל טופח סביב","dt":"תקמח-ט","b":"מו\"ץ בטיטואן, עם ר אפרים מונסונייגו, ור\"י ן מלכא. חיבר שו\"ת ודרושים ואבדו ברובם-במלחמה-תקן, מהכתבים ששרדו נדפס \"טופח סביב\", \"נופך ספיר\" - פיסא תקעב. העתיק בכתב ידו-תצו \"קערת כסף\" לר\"י האיזובי. בניו - ר יצחק בעל \"מעשה רוקם\", ר רפאל אברהם בעל זכות אברהם."},{"i":42160,"n":"קוריאט, יצחק מטיטואן","f":"אברהם","b":"מחכמי טיטואן-תרב."},{"i":42161,"n":"קוריאט, יצחק מטיטואן וירושלים","f":"יהודה מטיטואן","k":"בעל מעשה רוקם","bp":"טיטואן-מרוקו","dt":"תקסה - יז כסלו","dp":"ירושלים או ליוורנו","b":"מחכמי טיטואן. אחיו של ר רפאל אברהם. עלה לירושלים אחרי פרעות תקן. חיבר \"פחד יצחק\" בתוך ספר \"מעשי רוקם\" פיורדא תקסו, וכן \"נחלת אבות\" ליוורנו תרד. הסכים בליוורנו על \"המון חוגג\", \"פת לחם\"."},{"i":42162,"n":"קוריאט, יצחק ממוגדיר - ג","f":"אברהם","k":"בעל נחלת אבות","b":"מחכמי מוגדור."},{"i":42163,"n":"קוריאט, יצחק ממראקש - א","b":"רב במראקש-שמ. (אולי נקרא מהרי\"ק ב\"תקפו של יוסף\"). ראש המשפחה."},{"i":42164,"n":"קוריאט, משה מטיטואן","b":"סופר שטרות בטיטואן-שנות התק'."},{"i":42165,"n":"קוריאט, רפאל אברהם ממרוקו - א","f":"יהודה מטיטואן","k":"בעל זכות אברהם","bt":"תקמז","bp":"טיטואן(מרוקו)","dt":"תקסו - יא חשון","b":"מו\"ץ במוגדור-תקמז, גיברלטר-תקנב, ליוורנו, חיבר גם \"זכות אבות\". אחיו - ר יצחק מטיטואן בעל \"מעשה רוקם\". בנו - ר יהודה בעל \"מאור ושמש\"."},{"i":42166,"n":"קוריאט, שמואל ממרוקו","b":"מחכמי מרוקו-שעז, תשובה אליו מאת ר שמואל ן דנאן."},{"i":42167,"n":"קוריאל די, בנימין משלוניקי","dt":"שצד - א תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":42168,"n":"קוריאל די, יוסף משלוניקי","dt":"שצה - כה תשרי","dp":"שלוניקי","b":"גביר מחכמי שלוניקי."},{"i":42169,"n":"קוריאל די, ישראל מצפת","f":"מאיר","bp":"[ספרד]","b":"בן למגורשי ספרד (ואולי נולד שם בעצמו). תלמיד ר יוסף פאסי באדרינופול(=אדריאנופול), יחד עם המבי\"ט. רב וראש ישיבה באדריאנופול-רפח, עבר לקושטא ונשא ונתן עם ר יוסף טאיטצק ור אברהם ירושלמי, עמד בראש ישיבה בשלוניקי ומתלמידיו שם - ר סעדיה לונגו. רב ודיין בצפת עם ר יוסף קארו והמבי\"ט, והיה ניצב לימין ר יוסף במחלוקתו עם המבי\"ט. מבין הסמוכים ע\"י ר יעקב בירב. מתלמידיו בצפת - ר בצלאל אשכנזי שהביא ממנו בספריו, ור מרדכי הכהן מאר\"ץ. חתנו - ר משה נג'ארה מתלמידי הארי. בנו ר משה רב ודייןבצפת."},{"i":42170,"n":"קוריאל די, משה מצפת","f":"ישראל","dt":"שץ","dp":"דמשק","b":"רב בצפת בזמן ר יעקב בירב. תלמיד ר יוסף קארו. ראב\"ד בצפת. בשנת שץ יצא לדמשק להשיא את בנו ונפטר שם."},{"i":42171,"n":"קוריאל, אברהם","b":"רב בויניציאה-תקמ\"ב"},{"i":42172,"n":"קוריאל, אלברט משלוניקי","b":"קומוניסט, נבחר לפרלמנט היוני מטעם שלוניקי."},{"i":42173,"n":"קוריאל, אליהו מאזמיר","dt":"תקכט - כז כסלו","dp":"אזמיר","b":"מרבני איזמיר"},{"i":42174,"n":"קוריאל, דוד מקושטא ואדרינופול","b":"רופא מחכמי אדרינופול, נשלח-תכז אל נתן העזתי שרצה להגיע לאדרינופול עם ר אשר אשכנזי ור יהודה בן משולם."},{"i":42175,"n":"קוריאל, ישראל מאיר מצפת","f":"משה או מאיר","bt":"רסב","bp":"אדרינופול","dt":"שא","b":"מחכמי שלוניקי, בשנת רצה עלה לצפת, היה תלמיד ר יוסף פאסי משלוניקי, נשא ונתן עם ר יוסף קארו ור משה מטרני, והיה רבו של ר בצלאל אשכנזי ושל ר מרדכי כהן בעל \"שפתי כהן\", הוסמך על ידי ר יעקב בירב והיה חתנו של ר משה נג'ארה. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא."},{"i":42176,"n":"קוריאל, ישראל מצפת - ב","b":"מגדולי חכמי צפת-ת\"ק"},{"i":42177,"n":"קוריאל, משה מצפת","f":"ישראל","dt":"שץ","dp":"בגדד","b":"מחכמי צפת בזמן ר יעקב בירב, תלמיד ר יוסף קארו, היה ראב\"ד בצפת. בשנת שץ היה בבגדד להשיא את בנו ושם נפטר. חתם-שלא על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא."},{"i":42178,"n":"קורייא, אברהם"},{"i":42179,"n":"קוריין, אדולף מלינץ","b":"רב בלינץ-אוסטריה."},{"i":42180,"n":"קוריין, ויקטור מלינץ","b":"רב בלינץ-אוסטריה."},{"i":42181,"n":"קורייש ן, יהודה","b":"בלשן,אבי הדקדוק העבריגר במאהרת בין מרוקו לאלג'יריה-ד'תר\"ן,בדורו של הרס\"ג"},{"i":42182,"n":"קורינלדי דוד חיים בן יהודה משה","bt":"1700","dt":"ה'תקל 1770","bk":[["בית דוד",""]]},{"i":42183,"n":"קורינלדי, דוד חיים מאיטליה","k":"בעל בית דוד","dt":"תקלא","dp":"ליוורנו","b":"מדקדק ותוכן, רב ברוויגו, ליוורנו-תק, טריאסט. חיבר \"בית דוד\". החיד\"א הדפיס חלק מהגהותיו על השו\"ע בספרו \"חיים שאל\" בקונטרס \"שיורי ברכה\" ובקונטרס \"טוב עין\" בתוך ספרו \"ועד לחכמים\". (היו שניסו לטעון שלא הוא חיבר את \"בית דוד\" - אך חברו בעל \"פחד יצחק\" - דוחה בתוקף את דבריהם)."},{"i":42184,"n":"קורינלדי, דוד מאיטליה","b":"תלמיד ר נתן בן עזריאל יואל פיקרלי מוירונה. מוהר\"ם נווארה ב\"ימי תמימים\" - מספר כי ראה קינה לזכרו."},{"i":42185,"n":"קורלנדר, אברהם","b":"ראב\"ד בסרדהעלי-תקפ\"ד,מו\"צ באבאני-תק\"צ,רב בסנטאנדרש"},{"i":42186,"n":"קורלנדר, אברהם מגרוסורדין","f":"יצחק ממיטוי-קורלנד","dt":"תקצו - ט אב","dp":"[גרוסורדין]","b":"תלמיד ר יוסף הצדיק בפוזנא - חתן הנודע ביהודה, ואצל ר משולם איגרא בפרשבורג. חתן אחות חברו ר משה שטיין מנאג'פאלו. דיין בגרוסורדין אצלר יוסף רוזנפלד. דיין בדונא סרדאהי-תקפד, רב באבון וסט אנדראש. עבר לגרוסורדין אל בניו הגבירים ר רפאל ור אליהו."},{"i":42187,"n":"קורלנדר, אהרן הירש (אדולף)","k":"בעל דברי אגדה ודברי","bt":"1816","bp":"קאלם","b":"מורה לדת באופן, קלויזנבורג. עבר לוינה-1870."},{"i":42188,"n":"קורלנדר, אליהו מגרוסורדין","b":"מחכמי גרוסורדין. חתנו - ר אריה ליב פנט מגרוסורדין."},{"i":42189,"n":"קורלנץ, יוסף שמעון מצנסטחוב","b":"רב בצנסטחוב, אחיו חורגו של ר נחום אש - אב\"ד צנסטחוב."},{"i":42190,"n":"קורלק, שמואל מפיסקא","f":"יוסף מאיר מרעטה","bt":"תרכט","bp":"רעטה","dt":"תש - ערב רה","b":"תלמיד השב\"ס, חברו של ר משה בן השב\"ס. חתן ר יצחק הלוי שוורץ מהאלאש. מחכמי פיסקע. נכדו (בן בתו) ר שמואל אליעזר שטרן מבני ברק."},{"i":42191,"n":"קורמן, אברהם מנרול","f":"יקותיאל זאב","bt":"תרעח","bp":"נרול","b":"תלמיד ישיבת בובוב. עלה לארץ. אוטודידקט וחיבר עשרות ספרים ופרטיהם בספרו \"מושגים בהלכה\" תל אביב תשסב."},{"i":42192,"n":"קורמן, יצחק מאיר","b":"מחשובי חסידי ברסלב, מחותן עם ר ישראל דב אודסר מטבריה."},{"i":42193,"n":"קורמן, שמשון אידל משימבורג ובו","b":"מחכמי שימבורג, בויסק."},{"i":42194,"n":"קורן, חיים מורבוביץ וארה\"ב","f":"יעקב מגריידינג","k":"בעל תו חיים","bt":"תריג","b":"מו\"צ ביארמליניץ-תרמג, רב בוורבוביץ(וערבאוויץ)-פודוליה, עבר לארה\"ב. חיבר ספר שו\"ת."},{"i":42195,"n":"קורן, יהודה צבי מרוזניאטוב","dt":"תש..","b":"רב ברוזניאטוב. ת\"ח בעל זכרון מיוחד במינו. נספה בשואה."},{"i":42196,"n":"קורן, יעקב מגריידינג","b":"מו\"צ בגריידינג-תר\"ל"},{"i":42197,"n":"קורן, יקותיאל זלמן מטרנוב","b":"מחכמי טרנוב, רב בפטרובוסלא. פרסם ב\"המגיד\" תרכט."},{"i":42198,"n":"קורן, ישראל","f":"צבי דב מקראקא","dt":"תשא","b":"חסיד צורטקוב. חתן ר שלמה זלקא מניסקא."},{"i":42199,"n":"קורנבוים, חיים מאיר מפודקמין","b":"מחכמי פודקמין. ממשתתפי \"אהל מועד\"."},{"i":42200,"n":"קורנבליא, שמואל מגאיא","b":"תלמיד החת\"ס. חתן ר אשר שטסל מגאיא, רב בגאיא לצד חותנו ועל מקומו אחריו-תרא. רב באונגריש אוסטרוי-תרכז."},{"i":42201,"n":"קורנבליט, אברהם יצחק","dt":"תשנא","b":"רב ומחנך בגליציה. היגר לארה\"ב וכיהן כרב בניו יורק."},{"i":42202,"n":"קורנבליט, אלקנה","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":42203,"n":"קורנבליט, צבי הירש מקופיטשיניץ","b":"מחכמי קופיטשיניץ. תשובה אליו - במהרש\"ם-תרס."},{"i":42204,"n":"קורנגוט, יוסף חנינא סגל","f":"יצחק זאב","bt":"תרעט","dt":"תש..","b":"תלמיד ר מרדכי יהודה פריינד. ר\"מ בישיבת עץ חיים בובוב - במישלניץ. התכתב עם גדולי דורו. נספה בשואה."},{"i":42205,"n":"קורנגולד, בנימין מלונטשיץ","b":"חתן ר חיים ברוידא מהורדנא בעל \"תורה אור\". רב בנאשעלסק, לונטשיץ-תר."},{"i":42206,"n":"קורנגולד, י' ליבר חריף","dt":"תקעב - יד טבת","b":"ר\"מ ודיין בקרקא"},{"i":42207,"n":"קורנגולד, יהודה ליבר מקראקא","f":"בנימין מקראקא","k":"ליבר חריף","bt":"תק","dt":"תקעב","b":"חתן ר ליב זיינווילס. דיין בקראקא ועמד בראש ישיבה. בין תלמידיו ה\"ברוך טעם\", ועוד גדולי הדור הבא. הניח חדושים על הש\"ס - בכתב יד."},{"i":42208,"n":"קורנדא, יצחק איגנץ מבריסל","bt":"תקעא","bp":"פרג","dt":"תרמד - ט ניסן","dp":"וינה","b":"משכיל, עבר לבריסל והו\"ל כתב עת. מראשי הקהלה היהודית בוינה. פרסם ספרים ומאמרים. ציר מטעם העיר וינה, וחבר בועד הכללי לממשלת אוסטריה."},{"i":42209,"n":"קורניצר, אליהו מסובוטיטש ופרשב","f":"מנחם מנלי","bp":"סבאטיטש","dt":"תרו - בערך","dp":"פרשבורג","b":"חתן החתם סופר. בנו - ר עקיבא"},{"i":42210,"n":"קורניצר, יואב מסערנטש","f":"שמואל מסערנטש","b":"תלמיד הכת\"ס, ור שמואל עהרנפלד ממטרסדורף. גר בברעזאוויץ, סערענטש-תרמב, עסקן ציבורי בלשכת הקהלות האורטודוכסיות בבודפשט."},{"i":42211,"n":"קורניצר, יוסף נחמיה מקראקא","f":"עקיבא מקראקא","k":"בעל חדושי יוסף נחמיה","bt":"תרמא","bp":"קראקא","dt":"תרצג - ב אייר","dp":"קראקא","b":"נתייתם בילדותו וגדל אצל דודו ר שלמה אלכסנדרי סופר מסערט. תלמיד השב\"ס, ור יהודה גרינוולד מבאניהאד וסטמר. חתן ר פנחס חיים קליין מסעליש. ר\"מ בישיבת חותנו בסעליש-תרס. רב בסעליש על מקום חותנו. בידידות עם גדולי האדמורים והרבנים. נשיא הלשכה האורתודוכסית בקרפטים. רבה של קראקא-תרפה ובנו ר שמואל שמלקא על מקומו אחריו. חיבר \"שו\"ת וחדושי רבי יוסף נחמיה\" בני ברק תשמו. חתנו ר שבתי פרנקל מהדיר הרמב\"ם. פרסם מאמרים ב\"שערי תורה\" - קראקא תרפה.","bk":[["חידושי רבנו יוסף נחמיה – עה\"ת",""],["שו\"ת וחידושי רבנו יוסף נחמיה",""],["דרשות רבנו יוסף נחמיה",""]]},{"i":42212,"n":"קורניצר, משה מפאראד","f":"אליהו מפרשבורג","dt":"תרעח - יט תמוז","b":"נכד החת\"ס. חתן ר אברהם גשטטנר משארקאני, ובזיוו\"ש חתן ר עמרם גרינולד מטשארנא, ובזיוו\"ש חתן ר יוסף גינז-שלזינגר מוינה. רב בשארקאני-תרכח, פאראד. עלה לירושלים."},{"i":42213,"n":"קורניצר, עקיבא מקראקא","f":"אליהו מסאבאטיש","k":"בעל חדושי עקיבא קורנ","bt":"תקצח","dt":"תרנב - יא טבת","b":"נכד החת\"ס, גדל אצל אביו חורגו ר בנימין שלמה זלמן שפיצר מוינה. תלמיד הכת\"ס, והמכתב סופר. חתן דודו ורבו ר שמעון סופר מקראקא בעל \"מכתב סופר\" ועבר לשם-תרכב, וכיהן כרב לצד חותנו בקראקא היה ראב\"ד בפועל על מקום חותנו - אולם המשכילים מנעו את ההכרה הרשמית. חיבר גם \"מספד מר\" קראקא תרמג. בנו ר יוסף נחמיה רב בסעליש-קראקא."},{"i":42214,"n":"קורניצר, עקיבא פנחס מטאלטשווא","f":"יואב מסערנטש","dt":"תשד","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור מרדכי יהודה ליב וינקלר מהעדילא-מאדע. מחכמי סערענטש, רבה האחרון של טאלטשווא-תרפח. נספה בשואה."},{"i":42215,"n":"קורניצר, שמואל מסערענטש","f":"אליהו מפרשבורג","bt":"תקצג","bp":"פרשבורג","b":"נכד החת\"ס. תלמיד הכת\"ס. חתן ר יואב הלוי ביליצר-תריג, רב בסערענטש, ובנו ר יואב רב בסערענטש."},{"i":42216,"n":"קורניצר, שמואל שמלקא מקראקא","f":"יוסף נחמיה","bt":"תרסה","bp":"סעליש","dt":"תש","b":"חתן הגביר ר שרגא פיבל טירקל. רב בקראקא-תרצג. נספה בשואה (לאחר שביקש עזרה מההגמון סאפעהא - שמסרם לנאצים. נשלח לאושביץ ואפרו נשלח לקהילת קראקא."},{"i":42217,"n":"קורנלי (קרנלה), אברהם מסטרי","b":"רב בסטרי."},{"i":42218,"n":"קורנלי, משה יהודה מסטרי","b":"רב בסטרי."},{"i":42219,"n":"קורנמל נחום צבי","bt":"1908","dt":"ה'תשנב 1992","bk":[["תפארת צבי",""]]},{"i":42220,"n":"קורנמל, מרדכי מפשצלוב","f":"שבתי","k":"בעל מאמר מרדכי","bt":"תרמד","bp":"טרנוב","dt":"תרפח","b":"רב בפשצלוב, מחוז פראטער בוינה. חתן ר נחום צבי סגל הורביץ מריגליץ. חיבר \"מאמר מרדכי\" בילגוריא תרצו."},{"i":42221,"n":"קורנמל, נחום צבי מפשצלוב","f":"מרדכי","k":"בעל תפארת צבי","b":"עבר מפשצלוב לוינה עם הוריו. רב מחוז פראטער בוינה על מקום אביו. ההדיר ספר אביו \"מאמר מרדכי\" והוסיף לו ח\"ב. הגיע לארה\"ב-תרצט. וכיהן כרב באלבני. חיבר \"תפארת צבי\" ניו יורק תשכו."},{"i":42222,"n":"קורנפיין, יצחק איציק מלקנבך","b":"בנו - ר צבי מציריך."},{"i":42223,"n":"קורנפיין, מרדכי משטינמנגר","b":"תלמיד ר עזריאל הילדסהימר. רב בשטיינמנגר-תרן. השתתף עם רבו באסיפת רבנים-תרנט, ובמשלחת רבנים אל הקיסר-תרנד. תשובה אליו בשו\"ת מהר\"ם שיק, וב\"נחלת בנימין\"."},{"i":42224,"n":"קורנפיין, צבי מציריך","f":"יצחק איציק מלקנבך","bt":"תרכט","bp":"לקנבך","dt":"תשיט - יא תמוז","dp":"ציריך","b":"תלמיד השב\"ס, ור יעקב סנידרס מראב. חתן ר יהודה בלוך מציריך. מורה בענדיגן (שוויץ), רבה הראשון של קהילת החרדים בציריך במשך כיובל שנים."},{"i":42225,"n":"קורנפלד, אברהם ממאקווא","f":"שמואל","k":"בעל אהל אברהם","bt":"תר","bp":"פאסטא","dt":"תרסג - כד סיון","dp":"בודפשט","b":"תלמיד הכת\"ס, ור אהרן דוד דייטש מבאלאש-יארמוט. חתן ר יחיאל שלזינגר מפרשבורג. רב במאקווא."},{"i":42226,"n":"קורנפלד, אהרן","b":"רב ביעניקו-תר\"ל"},{"i":42227,"n":"קורנץ, משה אהרן","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":42228,"n":"קורנריך, אברהם מלימנוב","dt":"תשב","b":"רב בלימנוב. נספה בשואה."},{"i":42229,"n":"קורסין, יעקב","dt":"ד'תתקסה - ל שבט","b":"מגדולי הראשונים בצרפת"},{"i":42230,"n":"קורף יהושע בן גדליה","bt":"1905","dt":"ה'תשסז 2007","bk":[["ביאור תניא",""],["לקוטי ביאורים בספר התניא",""]]},{"i":42231,"n":"קורפי, שמואל משלוניקי","b":"מחכמי שלוניקי-בשנות ה-ת'."},{"i":42232,"n":"קורץ, אברהם זלמן מארה\"ב","f":"יצחק איזיק","bp":"סופראסלע-פלך ביאליסטוק","dt":"תשט - א אייר","b":"תלמיד ישיבת ראדין, כולל קובנא. נסמך מאת ר משה מרדכי אפשטין. חתן ר מרדכי הכהן. מחכמי ולקוביסק, היגר לארה\"ב-תרפד וכיהן כרב באיסטאן(=אירי?)-פנסילבניה, רוצ'סטר-ניו-יורק."},{"i":42233,"n":"קורץ, אהרן יוסף מזבלטוב","f":"מרדכי דוד ממליץ","k":"בעל יד המאיר","b":"חסיד דזיקוב. חתן ר נתן צבי הלוי הורביץ. מחכמי זבלטוב. היגר לארה\"ב-אחר מלחמת העולם ה-I. חיבר \"יד המאיר\" מונקטש תרסו, ועוד."},{"i":42234,"n":"קורץ, זאב וולף מבובוב","b":"רב בבובוב. תשובה אליו - מהר\"ש-תרנז."},{"i":42235,"n":"קורץ, זאב וולף מטרנוב","dt":"תשג","b":"רב בועד הרבנים בטארנא"},{"i":42236,"n":"קורץ, זלמן יוסף מטרנוב","b":"מחכמי טרנוב. חמיו של ר יצחק רפפורט מקראקא שהיה דיין בטרנוב."},{"i":42237,"n":"קורץ, יהודה זינדל מבובוב","b":"מחכמי בובוב. תשובה אליו \"קול יהודה\"-תרנו."},{"i":42238,"n":"קורץ, יהודה ליב מרופשיץ","f":"יחיאל","bt":"תרכג","bp":"טרנוב","b":"מחובבי ציון בטרנוב. כתב ה\"המגיד\". חתן חיה קוס מרופשיץ, ועבר לרופשיץ. ממיסדי \"אהבת ציון\"-תרנב. התכתב עם הרבנים קלישר וריינס. ביקר בארץ-תרס, ועלה לארץ-תרצג, והתישב בתל מונד. חיבר 3 חוברות ובהם: \"האתרוג\" דרוהוביטש תרנח."},{"i":42239,"n":"קורץ, יוסף מטרנוב","b":"רב בטרנוב. נספה בשואה."},{"i":42240,"n":"קורץ, יעקב מפשצלוב","b":"רב בפשצלוב, רב ור\"מ בטרנוב."},{"i":42241,"n":"קורץ, ישראל מטורנה","b":"רב בטורנא, סנוק. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"בית מאיר\" - אוסטרובצה - פיעטרקוב - תרצא."},{"i":42242,"n":"קורץ, מנחם מנדל","b":"ראב\"ד במיקלוש-תר\"י"},{"i":42243,"n":"קורץ, צבי הירש מרישא","f":"אליעזר","bp":"רישא או ז'ישוב","dt":"תש..","b":"נכד ר פנחס מקוריץ. תלמיד ר אבא אפלבוים. בעל תואר דוקטור מוינא. רב מטיף בברלין, שלוניקי-תרצג - נתמנה ע\" חוגי המשכילים שהתנגדו לרב המכהן ר חיים חביב (לפי זכרון שלוניקי היה במחלוקת עם רבים מבני הקהלה ואף תבע את העתונים היהודים המבקרים אותו בביהמ\"ש), רב הכולל ביון. מיודד עם המלך וראש הממשלה. נספה בשואה. (בניגוד לטענות כאילו שיתף פעולה עם הנאצים - מתברר כי ההפך הוא הנכון - ע\"פ נתן עק - עיון חדש בקיטרוג על רבה של שלוניקי, ידיעות יד ושם, לעומת זאת בזכרון שלוניקי - מביע דעה הפוכה)."},{"i":42244,"n":"קורצווייל, עמרם מפרשבורג","b":"שו\"ב בפרשבורג. חתן ר אליעזר ליפמן קונשטט מפרשבורג."},{"i":42245,"n":"קורצוויל, אברהם אריה מטריטש","f":"עמרם מפרשבורג","bt":"תרכז","bp":"פרשבורג","dt":"תרץ","b":"תלמיד השב\"ס. חתן ר מרדכי קורנפין משטיינמאנגר, ובזיוו\"ש חתן ר ברוך עקפלד מטשוז. מורה במעדלינג (ליד וינה)-תרנג, רב בפירניץ-תרנה, טריטש-תרפו."},{"i":42246,"n":"קורצוויל, מיכאל מפפדמ","f":"עמרם מפרשבורג","b":"תלמיד השב\"ס. חתן דודו ר אברהם אריה קונשטט מפרשבורג... שו\"ב בפפדמ. נספה בשואה. חתנו ר שמעון צבי דייטש מפרוינקירכן - ר\"מ בישיבת אהל שמעון - ערלוי(=אויהל) בירושלים."},{"i":42247,"n":"קורצוויל, עמרם מפרשבורג","b":"שו\"ב בפרשבורג-תרכז. חתן ר אליעזר ליפמן קונשטט מפרשבורג. בניו - ר מיכאל שו\"ב בפפדמ, ר אברהם אריה מטריטש. חתנו - ר שמואל דונט מפרשבורג."},{"i":42248,"n":"קורצמן, יעקב מטיסמניץ","f":"אפרים","bp":"טיסמניץ","b":"מחכמי טיסמניץ. הדפיס ספר אביו \"כוכב מיעקב\" למברג תרכד."},{"i":42249,"n":"קורצר, גרשון מלמברג","f":"יהושע פלק","k":"בעל נחלת יהושע","bt":"תר","dt":"תרעג","b":"נינו של הסמ\"ע. תלמיד ל\"שואל ומשיב\", מחכמי למברג וסירב לרבנות. השאיר חיבור על הש\"ס והרמבם. חיבר \"נחלת יהושע\" למברג תרצד."},{"i":42250,"n":"קורק, ישראל ניסן מקובנא","f":"חיים יעקב מקובנא","bt":"תריט או תרכג","bp":"קאמיי-פלך קובנא","dt":"תרצח - כב סיון","dp":"תל אביב","b":"תלמיד ישיבות איישישוק, וולוזין, נסמך מאת: ר יצחק אלחנן מקובנא, והנצי\"ב. מו\"צ בקובנא-תרמז כ-40 שנה אצל ר יצחק אלחנן ואצל בנו ר צבי הירש, ומנהל כולל אברכים פרושים בקובנא על מקומם. יו\"ר הסתדרות \"המזרחי\" וציר בקונגרס הציוני. עלה לארץ-תרפז."},{"i":42251,"n":"קורקדי, אברהם","b":"מחכמי איזמיר"},{"i":42252,"n":"קורקוס, אברהם ממראקש","b":"מו\"ץ במראקש עם ר יצחק חרוש, ר יצחק פינטו ור אברהם פינטו, חתם על פס\"ד-תקיח. בנו - ר משה."},{"i":42253,"n":"קורקוס, אברהם ממרוקו","dt":"תקע - ל אדר","b":"מחכמי מרוקו"},{"i":42254,"n":"קורקוס, אליהו מרומא","f":"שלמה בן דוד","b":"עשיר מופלג, מחכמי רומא, וחתם בתקנות חכמי איטליה-שיד. אחיו של ר יהושע."},{"i":42255,"n":"קורקוס, חזקיה מנוח מרומא הזקן","dt":"תי","b":"מגדולי חכמי איטליה,רב ברומא. תשובה ממנו ב\"באר עשק\"-תלד. כנראה זקנו של הרב בעל אותו השם."},{"i":42256,"n":"קורקוס, חזקיה מנוח מרומא הנכד","f":"יצחק","bt":"תכ","dt":"תצ","b":"גדול בתורה ורפואה,רב ברומא-תסב-תעד. תשובה ממנו ב\"שמש צדקה\"-תצד."},{"i":42257,"n":"קורקוס, יהושע מפאס","dt":"שיא - אחרי","dp":"פאס?","b":"תלמיד ר משה חלאווה. רב בפאס, חתם על תקנות בשנים - ש, שה, שיא, עם ר נחמן סנובאל, ר אברהם חאגיז, ר יהודה חינדא, ור יצחק נהון."},{"i":42258,"n":"קורקוס, יהושע מרומא","f":"שלמה בן דוד","b":"מחכמי רומא-שיד. אחיו של ר אליהו."},{"i":42259,"n":"קורקוס, יוסף מגיברלטר","k":"בעל יוסף חן","b":"מחכמי גיברלטר-שנות ה-תק'. חיבר \"יוסף חן\" על התורה ונספח לספר \"שיעור קומה\". סייע ליהודי מרוקו בזמן הרעב-תקפה."},{"i":42260,"n":"קורקוס, יוסף ממרוקו","b":"מחכמי מראקש או פאס, חתם על פס\"ד-תקכח, נזכר ב\"נימוקי שמואל\" לר שמואל צרפתי."},{"i":42261,"n":"קורקוס, יוסף מספרד וירושלים","k":"בעל ספרא דבי רב","bp":"ספרד","dt":"ש (1540)","b":"מגולי ספרד שהגיעו לירושלים וחברו של הרדב\"ז. חיבר \"ספרא דבי רב\" אזמיר תקיז, מוזכר על ידי ר יוסף קארו בספריו. החידא מעיד כי תשובה טז בספר \"אבקת רוכל\" היא מר יוסף קורקוס. נשא ונתן עם חכמי דורו."},{"i":42262,"n":"קורקוס, יצחק מספרד וירושלים","b":"אחיו של ר יוסף. ממגורשי ספרד שהגיע לירושלים. רב ודיין בירושלים-רפ, הרלב\"ח כותב עליו בתשובה, בנו היה ר שלמה קורקוס מחכמי ירושלים."},{"i":42263,"n":"קורקוס, יצחק מרומא","f":"מרדכי","b":"רב ברומא. חתום ב\"מלחמה לה'\"-תעד על החרם נגד נחמיה חיון."},{"i":42264,"n":"קורקוס, מאיר ממראקש.","dt":"תקא","b":"מחכמי מראקש."},{"i":42265,"n":"קורקוס, מנוח מסיינה","b":"רב בסיינה. חותנו של ר ישמעאל הכהן, תשובה ממנו בספר חותנו - \"זרע אמת\"."},{"i":42266,"n":"קורקוס, מרדכי ממראקש","dt":"תשיח - ה תמוז","b":"רב במראקש כארבעים שנה. נקבר ליד חברו הדיין ר משה זריהן."},{"i":42267,"n":"קורקוס, מרדכי מרומא","b":"מחכמי הישיבה ברומא. הסכים על \"ראשית בכורי קציר\" - ונציה-פיררה תעה."},{"i":42268,"n":"קורקוס, משה ממראקש ומוגאדור","f":"אברהם","b":"מחכמי מראקש, רב במוגאדור-מרוקו-תקמז."},{"i":42269,"n":"קורקוס, שלמה מאיטליה","f":"דוד","b":"בן למשפחה ממגורשי ספרד. רב ברומא. בניו ר אליהו ור יהושע שהיו מחכמי איטליה ועשירים."},{"i":42270,"n":"קורקוס, שלמה מירושלים","f":"יצחק","k":"בעל ביאור ליסוד עולם","b":"מחכמי ירושלים, בשנת שח חתם על תקנת המס, חיבר ביאור על הספר \"יסוד עולם\" לר יצחק ישראלי - בכתב יד."},{"i":42271,"n":"קורקוס, שמואל מאיטליה","b":"מחכמי איטליה-שנות ה-ש'. נזכר ב\"אמרי שפר\" לר\"נ אשכנזי מצפת."},{"i":42272,"n":"קורקוס, שמואל מירושלים - ב","b":"מחכמי ירושלים-אחרי תרמג."},{"i":42273,"n":"קורקידי, אברהם","f":"דוד","k":"בעל ויקח אברהם","bt":"תקעג","bp":"אזמיר","dt":"תרמה","dp":"ירושלים","b":"דרשן, עזב את אזמיר אחרי השריפה-תרא, ש\"צ ושוחט בוש אדאסי, רב בבירגאמה(=בראגמה)-תרטו, עלה לירושלים-תרמא עם בנו נסים. חתן ר' חיים משה הכהן. חיבר ספר \"ויקח אברהם\" אזמיר תרמב","bk":[["ויקח אברהם","מפרשי רמב\"ם"]]},{"i":42274,"n":"קורקידי, חיים משה","f":"אברהם","dt":"תרמג - ו תמוז","dp":"איזמיר","b":"מחכמי ורבני איזמיר,חיבר \"משה עבד\" דרשות"},{"i":42275,"n":"קורקידי, נסים מירושלים","f":"אברהם","bt":"תרלב","bp":"ברגאמה-ליד אזמיר","b":"עלה לארץ עם הוריו-תרמא, תלמיד \"דורש ציון\", ר שמעון חרוש, ישיבת \"תפארת ירושלים\" אצל ר חזקיה שבתי. מורה ביפו, עסקן צבור בקהלה הספרדית בתל אביב."},{"i":42276,"n":"קושטא, ישראל מליוורנו","b":"רב בליוורנו-תר\"נ"},{"i":42277,"n":"קושטא, שמואל מליוורנו","b":"רב בליוורנו-תמ, חתם-תנט על כתב תמיכה בר משה חגיז. בשליחות קהלת טבריה-תקסג."},{"i":42278,"n":"קושטנטין, משה משלוניקי","dt":"שו - יח תמוז","dp":"שלוניקי","b":"מחכמי שלוניקי-ש'."},{"i":42279,"n":"קושטנטין, שבתי משלוניקי","b":"מבני הקהלה האיטלקית בשלוניקי-תקד וחתם אז על הסכם בין האיטלקים לבין בני קהלת שלוניקי בענין הסדרת המס."},{"i":42280,"n":"קושי, משלם","b":"תשובה אליו מחברו מהר\"ם פדובה."},{"i":42281,"n":"קושלביץ, משה מלויקובה-ליטא","b":"רב בלויקובה(=ליקובא)."},{"i":42282,"n":"קושלביץ, שמואל מארה\"ב","f":"צבי יהודה (זקס)","k":"בעל נתיבות שמואל","bp":"סלובודקה","dt":"תשכג","dp":"נ\"י - ירושלים","b":"היגר לארה\"ב-תרפה, ר\"מ ישיבת \"תורה ודעת\" בניו יורק, ורב בנ\"י. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה, \"המסלה\" - נ\"י תרצו, \"המתיבתא\" - נ\"י תשג, \"קול תורה\" - ירושלים תרץ."},{"i":42283,"n":"קושלביץ-זקס, צבי יהודה","f":"משה","bp":"לויקובה","dt":"תרעט","dp":"סמיאטיץ","b":"רב בפודזאלווה-תרן, ראצק-תרנב, טיקטין-תרנז, סמיאטיץ-תרסח."},{"i":42284,"n":"קושלבסקי, אליהו מארה\"ב","b":"פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":42285,"n":"קושלבסקי, ישראל אריה","b":"פרסם מאמרים ב\"אור תורה\" - לונדון תרצד."},{"i":42286,"n":"קושלבסקי, משה אהרן","dt":"תשג","b":"רב בדטנעווע"},{"i":42287,"n":"קושלבסקי, עזריאל זליג נח מיגוס","k":"בעל עין צופים","bt":"תרכו","dt":"תשג","b":"רב באוגוסטוב(=יאגוסטוב)-תרסב. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"הלבנון\" - סטמר תרפח, \"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":42288,"n":"קושלבסקי, שמואל","f":"יקותיאל","k":"בעל תודה וקול זמרה","b":"הסטודנט היהודי הראשון באוני' וילנא. הוסמך כרופא-1824, רופא בנאסוויז והתפרסם ברחבי ליטא, היה מקובל על האצולה הפולנית. חסיד ליובאויטש ושמר בקפדנות על דיני ישראל - רבנים התירו לו לנסוע בשבת לבקר חולים. ריפא יהודים בחינם. חיבר \"לוחות הסימנים למחלות ריאה ולב\"."},{"i":42289,"n":"קזאני, אנטולי (זרחיה) הפייטן","f":"דוד","b":"פייטן וחיבר \"לרנן חסדך\" ליוצר של פסח, ורשות להפטורה."},{"i":42290,"n":"קזאני, שבתי מקהיר","f":"[שמואל מקאנדיה]","b":"מחכמי קהיר-שסו, חתם אז עם ר יעקב קשטרו ור יעקב אשכנזי ור משה ראובן גרשון."},{"i":42291,"n":"קזיס, אשר משלוניקי","f":"יצחק","b":"גביר בשלוניקי, ומראשי הקהלה על מקום אביו - אחרי תקו."},{"i":42292,"n":"קזיס, בנימין מאדרינופול וקושטא","f":"דוד","k":"בעל מגילת ספר","bp":"אדרינופול","dt":"תצה","dp":"צפת","b":"תלמיד ר אליעזר נחום. רב באדרינופול, קושטא, חיבר \"מגילת ספר\" על הסמ\"ג קושטא תקי. בשנת תצג עלה לצפת וכיהן שם כרב, השאיר כתבים רבים בכתב יד,"},{"i":42293,"n":"קזיס, ברוך","b":"תשובה ממנו ב\"באר שבא\". מוזכר ב\"קול עוגב\". חיבר מוסר לבית העלמין."},{"i":42294,"n":"קזיס, דוד מתונס","b":"מחכמי תונס-תרס וחוקר חכמת ישראל. פרסם מאמרים ובהם ב\"מזרח ומערב\" ובו חיבורי חכמי תונס לדורותיהם."},{"i":42295,"n":"קזיס, חנניה מפירנצי","f":"מנחם","k":"בעל קנאת סופרים","dt":"תסד","b":"רופא מחכמי איטליה, כנראה נולד בפירארה, רב בפירינצי בזמן הרמ\"ז ונזכר בספרו, חיבר \"קנאת סופרים\" להגנת הרמב\"ם בספר המצוות. (לפי רוזניס היה באדרינופול)."},{"i":42296,"n":"קזיס, יום טוב ממונשטיר","b":"רב במונשטיר-שמח."},{"i":42297,"n":"קזיס, יוסף ברוך ממנטובה","f":"משה הרופא","b":"רב ורופא במנטובה-תק. מתורתו בספרי חכמי דורו ובהם \"פחד יצחק\", \"שמש צדקה\" ועוד. קינה לזכרו מאת ר יעקב ישראל בילגראדי."},{"i":42298,"n":"קזיס, יוסף מפשוורסק יאנוב וחלם","f":"ישראל סירקין מפשוורס","k":"אדמור מחלם","b":"נכד ר מרדכי סירקין בעל מים עמוקים (באלפסי מופיע כאביו), ונכד-אבי אמו ר זכריה מנדל מירוסלב. רב בפשוורסק (לפי וונדר), רב ואדמור-תקעה בלברטוב-תקף, יאנוב, חעלמא(=חלם). מצאצאי בעל הב\"ח - ר יואל סירקיש ושינה שמו לקזיס. בניו: ר ישראל שמואל נייהויז מטומשוב, ר אריה ליב נייהויז."},{"i":42299,"n":"קזיס, יעקב יצחק משלוניקי","b":"נשיא קהלת שלוניקי-תרפא."},{"i":42300,"n":"קזיס, יעקב ממנטובה","f":"ישראל גדליה ממנטובה","b":"רב ורופא במנטובה. בנו הרופא - ר ישראל גדליה."},{"i":42301,"n":"קזיס, יעקב מקנדיא","b":"רב בקנדיא-שנות ה-ת'."},{"i":42302,"n":"קזיס, יצחק משלוניקי","b":"גביר מראשי קהלת שלוניקי-תקד ומורשה הקהלה, סירב לחתום אז מטעם הקהלה על ההסכם בין יהודי איטליה היושבים בשלוניקי לבין בני קהלת שלוניקי בענין הסדרת המס. סייע בהדפסת \"פרשת הכסף\" לר משה סוראנגה, נדב ספר תורה ור משה אמריליו דרש אז לכבודו."},{"i":42303,"n":"קזיס, ישראל גדליה ממנטובה","f":"יוסף ברוך","dt":"תקנג","b":"רב ורופא במנטובה והסכים על ספרו של ר חיים ן עטר - \"פרי תואר\". חתם-תקלח עם ר שלמה למפרונטי ור יעקב חיים ן יחיא. תלמידו - ר אברהם חי קולוניא. בנו ר ר יעקב קזיס רב ורופא במנטובה."},{"i":42304,"n":"קזיס, ישראל גדליה ממנטובה","f":"יעקב ממנטובה","dt":"תרח - בערך","b":"רב ורופא (במנטובה?)"},{"i":42305,"n":"קזיס, לוליאנו שלום ממנטובה","f":"שמואל","k":"בעל דרך ישרה","b":"רב ורופא במנטובה-שפב. פסק ממנו בענין המס בקהילה נדפס בשם \"דרך ישרה\". נהרג במאורעות של שנת שץ (1630)."},{"i":42306,"n":"קזיס, מנחם מאיטליה ואדרינופול","f":"אלחנן או אלישע","k":"בעל שלום הבית","dt":"תסד","b":"רב במנטובה-תב, פיררה-תטו. חיבר \"שלום הבית\". בנו - ר חנניה בעל \"קנאת סופרים\". תשובות ממנו בכת\"י - תיח עם הסכמת הרבנים בורגו ומונציליסי. נקבר נפטר בער\"ש ונקבר במוצ\"ש - ועל כך התרעם הרב מה טוב בספרו - ערך \"קבורת חכם\"."},{"i":42307,"n":"קזיס, מנחם משלוניקי","b":"רופא בשלוניקי-תרס."},{"i":42308,"n":"קזיס, משה ממנטובה","f":"שמואל בן משה","k":"בעל שיטה לחולין","bt":"שי","dt":"שעז - כב אב","b":"רב ורופא במנטובה-שמו בזמן הרמ\"ז. תלמיד הרב\"ע מפאנו. חיבר שיטה לחולין בכת\"י. נספד ע\"י ר יוסף מרדכי בן חנניה אליקים ריאיטי. בנו ר יוסף ברוך רב ורופא (מתשובותיו ב\"פחד יצחק\"), בנו - ר ישראל גדליה - רב במנטובה, ובנו - ר יעקב רב ורופא במנטובה, ובנו ר ישראל גדליה. נזכר ב\"שלטי הגבורים\". דודו ורבו של בעל \"מנחת שי\".."},{"i":42309,"n":"קזיס, נתן מקומירג'ינה","dt":"תקנז","b":"מחכמי קומירג'ינה. נפטר צעיר ונספד מאת ר חיים אברהם אישטרושא."},{"i":42310,"n":"קזיס, שלמה משלוניקי","dt":"תקכג - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"כתונת יוסף\"-תקכג."},{"i":42311,"n":"קזיס, שמואל מאיטליה","f":"משה","dt":"שלב - כט אלול","b":"רב במנטובה-שיט, בולוניה, מעורב בפרשת הגט תמרי ונטורוצו. הגיה \"מקור חיים\" לר שמואל סרסה. נספד ע\"י ר יהודה מוסקאטו. מקצת מתורתו בספרי חכמי דורו. בנו - ר משה."},{"i":42312,"n":"קזלברקי, אברהם גרשון","b":"רב בניעזנפראבסק. פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":42313,"n":"קזנאטשי, יוסף מברוסילוב","f":"יהושע","bt":"תרלו","b":"רב בבראסילב(=ברוסילוב)-פלך קיוב-תרנט."},{"i":42314,"n":"קזנוביץ, עמנואל משה","f":"יקותיאל","bt":"1853","bp":"ז'אלודק-פלך וילנא","dt":"1927","dp":"וושינגטון","b":"תלמיד ישיבות ליטא. למד בביה\"ס האוונגלי בבזל. מזרחן וארכיאולוג. היגר לארה\"ב-1892 והיה מורה לתולדות הכנסיה בביה\"ס התיאולוגי גרמני בנוארק. מנהל המחלקה הארכיאולוגית במוזיאון בוושינגטון. חיבר ספרים באנגלית על חקר הדתות."},{"i":42315,"n":"קזרנוב, משה שאול","f":"יהודה ליב","k":"בעל בינה בספר איוב","b":"מצאצאי ר יעקב צבי מאליק."},{"i":42316,"n":"קטאלאני, אברהם מונציה-א","k":"בעל מצרף השכל","dt":"שנו - בערך","dp":"ונציה","b":"אב\"ד בונציה-שנות ה-ש'."},{"i":42317,"n":"קטאלאני, אברהם מונציה-ב","k":"בעל עולם הפוך","b":"מחכמי ונציה-שץ חיבר \"עולם הפוך\" על המגפה שהיתה בונציה, עם שירים מבנו - ר משה."},{"i":42318,"n":"קטאלאני, אריה מפדובה","dt":"שפב","dp":"פדובה","b":"מחכמי פדובה."},{"i":42319,"n":"קטאלאני, שמואל משלוניקי","dt":"תנט - בערך","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":42320,"n":"קטורזה, אברהם מתונס","dt":"תקמא","dp":"תונס","b":"תלמיד ר יצחק לומברזו בעל \"זרע יצחק\". רב ור\"מ בתוניס דודו - הרב פייאתוסי כותב עליו בספרו \"מקור ברוך\"."},{"i":42321,"n":"קטורזה, דוד מג'רבה","k":"בעל תנובות שדי","dt":"תש - ניסן","b":"מגדולי רבני תונס, חיבר \"תנובות שדי\" על הלכות שחיטה וטריפות. פרסם מאמרים ב\"הירח\" - ג'רבה תשח."},{"i":42322,"n":"קטורזי, דון יוסף","b":"מופיע בתשובות הריב\"ש"},{"i":42323,"n":"קטינא, חיים יעקב מנירבוגאט","dt":"תשד","b":"רב בנירבוגאט. חתן ר שמואל בנימין יונגרייז מפילעק."},{"i":42324,"n":"קטינא, יעקב מחוסט","k":"בעל רחמי האב","dt":"תרן - ט שבט","b":"תלמיד הדברי חיים מצאנז. ראב\"ד בחוסט-תרל עוד לפני בואו של המהר\"ם שיק. חיבר גם \"קרבן עני\" בעילום שמו.","bk":[["רחמי האב",""]]},{"i":42325,"n":"קטינא, ישראל מבניהאד","dt":"תרלב - כ תמוז","b":"דומ\"צ בבוניהאד(=בניהאד)"},{"i":42326,"n":"קטיעי, סעדיה מתימן","f":"משה","bt":"תמב","bp":"צנעא","b":"רב בצנעא על מקום ר דוד חותר. היה בקשר עם המהרי\"ץ"},{"i":42327,"n":"קטלאן, אברהם","f":"אליהו קטלן","b":"מגדולי חכמי דורו-ש\"פ"},{"i":42328,"n":"קטלאן, אליהו משלוניקי","b":"מחכמי שלוניקי-שנות ה-ש'."},{"i":42329,"n":"קטלאן, משה מחלב","b":"מראשי קהלת הספרדים בחלב-שנות ה-ש'."},{"i":42330,"n":"קטן - משפחה","b":"משפחה במרוקו."},{"i":42331,"n":"קטן, אברהם מאדרינופול","f":"שלמה","b":"רב באדרינופול-תע."},{"i":42332,"n":"קטן, אברהם מטיטואן","b":"מחכמי טיטואן, חתם על פס\"ד-תכט."},{"i":42333,"n":"קטן, אברהם מפאס","b":"סופר ביה\"ד בפאס, חתם על שטר-שיג עם ר משה אתיג'אר."},{"i":42334,"n":"קטן, בכור יצחק","b":"דיין באיזמיר"},{"i":42335,"n":"קטן, דניאל מסרייבו","b":"דיין בסרייבו-תלב, עם ר יצחק ליווא ור יוסף מוסאפיר."},{"i":42336,"n":"קטן, חיים מקושטא ואדרינופול","b":"מחכמי קושטא מאנדרינופלא, דיין בקושטא-תטז עם ר יונתן גלנטי ור יצחק פראנסיס."},{"i":42337,"n":"קטן, יעקב מפאס","f":"אברהם","k":"בעל רפואות וסגולות","b":"מחכמי פאס-תע, בקי בכימיה ורפואה, חתם על קיום פס\"ד-תעט של ר שלמה בירדוגו ור יוסף אזנאתי, עם ר אברהם בן דוד חסין. חיבר ספר רפואות וסגולות שנכתב בידי חברו ר אלעזר בהלול בפאס-תעח - בכת\"י"},{"i":42338,"n":"קטן, יצחק מאלגיר","f":"יעקב","b":"רב בתלמסאן, ונזכר בשטר-תפז."},{"i":42339,"n":"קטנוף, חזקיה","k":"בעל מדרש חזקיה","dt":"תשכב - כג שבט","b":"מחכמי בוכארה,דרשן בירושלים,בבית כנסת \"בבא תמא\" בשכונת הבוכרים,חיבר \"מדרש חזקיה\""},{"i":42340,"n":"קטקובסקי, יוסף מפריסלב","f":"זאב","k":"בעל דרכי חיים","bt":"תרא","b":"רב בטשיגרין(=טשוגרין)-פלך קיוב-תרכז, פעריסלב(=פערעיאסלעוו, פטרויסלב)-פלך פולטובה-תרמז. חיבר גם \"נחלת יהושע\", \"דרכי החיים\", \"נחלת יהושע\"."},{"i":42341,"n":"קטריבס, יוסף","b":"מגדולי חכמי דורו-ש\"צ"},{"i":42342,"n":"קטריבס, שמעיה","b":"מחכמי טוניס-תקמ\"ו"},{"i":42343,"n":"קטריבס, שמריה מטבריה","k":"בעל זכר צדיק","bp":"טבריה","dt":"תקלד - א ניסן","dp":"תונס","b":"רב בטבריה, בזמן חידוש הישוב-תק, חתם על כתב שליחות-תקח לר מסעוד בונאן, ועל כתב שליחות ר יונה אשכנזי, בשליחות באלגיר-תקטו ונשא ונתן עם רב העיר ר יהודה עייאש, כשהגיע לתונס נשאר לכהן כרב עד פטירתו. היה במרוקו-תקיט ואישר תשובה לר יעקב ן צור. חיבר \"זכר צדיק\" (בתוך \"אברהם יגל\" לר אברהם הכהן) נדפס ליוורנו תרג, ועוד.","bk":[["זכר צדיק",""]]},{"i":42344,"n":"קיבלוביץ, יהודה ליב הכהן מצירי","f":"שניאור זלמן מליובטש","b":"רב בקיציץ-פלך בוברויסק, צירין-פלך נוברדוק, ר\"מ בטאוריג, ר\"מ בראסיין. מתורתו ב\"הדרת מרדכי\"."},{"i":42345,"n":"קיהן, יעקב יצחק מלודז","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":42346,"n":"קיוואויטש, זלמן צבי משעשיק","f":"אפרים מיכל","bt":"תרב או תרכ","b":"רב בשעשיק-פלך קובנא-תרל או תרנ,טימישלע(=טשימישליע)-בסרביא."},{"i":42347,"n":"קיזלניק, יצחק מנחם מריזאווליה","bt":"תקצח","dt":"תרעו -יח-כ כסלו","b":"חתן ר שמואל חסיד מריזאווליה. תלמיד ר מנחם א\"ש מאונגוואר. רב בריזאווליה כ-50 שנה, ובנו ר שמואל שמלקא נבחר על מקומו אחריו - אולם נשאר בריסקווה - ור חיים מרדכי גוטליב כיהן על מקומו אחריו. בזמן מלחמת העולם ה-I כשכבשו הרוסים את המקום, החביא הרב את הנשים ומפקד היחידה חקרו באלימות וסירב לגלות ואחר כמה ימים נפטר. נספד ב\"יגל יעקב\" לר חיים מרדכי יעקב גוטליב."},{"i":42348,"n":"קיזלניק, משה מריזאווליה","f":"שמואל שמלקא מריסקווה","dt":"תשד","b":"נכד ר יצחק מנחם מריזאווליה(=ריזאוולע). רב בכפר סטרימטרה, רב בריזאווליה על מקום אבותיו. נספה בשואה."},{"i":42349,"n":"קיזלניק, שמואל שמלקא מריזאוליה","f":"יצחק מנחם מריזאווליה","dt":"תרפה","b":"דיין בריסקווה(=רוסקוב), נבחר לרב בריזאווליה על מקום אביו-תרעו אך נשאר בריסקווה, ובנו ר משה על מקומו אחרי ר חיים מרדכי גוטליב."},{"i":42350,"n":"קיזעליך, משה מרעזאווליע","b":"אב\"ד רעזאווליע."},{"i":42351,"n":"קיזר, אברהם מהאליטש","f":"יוסף מסערעד","dt":"תרכד - יז אב","b":"ראב\"ד בהאליטש."},{"i":42352,"n":"קיזר, אלתר נח הכהן מדרוהוביטש","f":"אריה מאיר","k":"אדמור מקוויאשד-חן מר","bt":"תרח-י-יב","bp":"נשכיז","dt":"תרף - ח אלול","dp":"ירושלים","b":"נקרא מיכאלנסקי(=מיכלאנקיס) (שם אמו) ושינה שמו לקייסר (כתר). תלמיד ר יצחק מנשכיז בעל \"תולדות יצחק\". עלה לארץ-תרלב או תרלח. למד קבלה עם ר מרדכי עבאדי מארם-צובא בעל \"מעין מים א\"ב\". נסע להונגריה-תרלז, רב ברעמיט (ליד סיגט או ספינקה) החל לנהוג באדמורות והיה מחלוקת על כך (המהר\"ם שיק והייטב לב יצאו כנגדו עם אחרים) - ונאלץ לעזוב את המדינה לאחר שנמסר דינו לערכאות, ומאז בכל מקום אליו הגיע היו שרדפוהו - בעיקר החסידים. מגיד בסענינא, עבר לקיוויאשד, זלישטשיק, הורודנקה, דרוהוביטש, רב ביאסי, יורדנוב, לונדון, עלה שנית לירושלים. חיבר יחד עם חברו ר מרדכי עבאדי \"חן מרדכי\", חיבר גם \"נתיבות חן\" לונדון תרנט. מתולדותיו ב\"תולדות חן\"."},{"i":42353,"n":"קיזר, אפרים הלל מפרשבורג","f":"אריה יהודה מגלנטא","k":"בעל תקון לאה","b":"מחכמי פרשבורג. החזיק בספריה הגדולה ביותר בעיר - ותלמידי חכמים רבים נעזרו בספריו, ומגיד שיעור בביהכ\"נ."},{"i":42354,"n":"קיזר, אריה יהודה ליב מגאלאנטא","f":"מרדכי מגלנטא","dt":"תרצו - כה חשון","dp":"גאלאנטא","b":"תלמיד השב\"ס, ור מרדכי יהודה ליב וינקלר מהעדילא-מאדע. חתן ר יעקב רוזנר. מחכמי גאלאנטא. בנו ר אפרים הלל מפרשבורג בעל \"תקון לאה\"."},{"i":42355,"n":"קיזר, ויליאם","k":"בעל \"ליעדער און פאעז","bt":"1876","bp":"קובנא","dt":"1939","dp":"ניו יורק","b":"משורר בקובנא. היגר לארה\"ב והיה חלוץ השירה האידית בארה\"ב ובשיריו הוא מתאר את חייהם של המהגרים וגעגועיהם לעולם הישן. ?? לא באוצר ??"},{"i":42356,"n":"קיזר, יוסף מסערעד","b":"דיין בסערעד-תקפ. נזכר בשו\"ת חת\"ס. בנו - ר אברהם מהאליטש."},{"i":42357,"n":"קיזר, מרדכי מגאלאנטא","b":"חתן ר אריה יהודה ליב רייכהרט מקאטה."},{"i":42358,"n":"קיזר, שמואל מלונדון","f":"יצחק","b":"רב בלונדון, ביקר בניו יורק-תקלה והשיב לשאלות והכריע בסכסוך השו\"ב. ונזכר ב\"מלאכת הקדש\"."},{"i":42359,"n":"קיטאי, יוסף מרמת גן","f":"אליעזר קיטיגורודסקי","bt":"תרנז","bp":"צרקס","dt":"תשמב","b":"עסקן הקהלה הדתית ברמת גן. חתן ר אהרן שטיין (נכד ר\"נ מרופשיץ), ובזיוו\"ש חתן ר חיים אלתר מפיטסבורג."},{"i":42360,"n":"קיטובר, אהרן"},{"i":42361,"n":"קיטובר, ישראל הלוי","k":"בעל בירורי המדות","dt":"תרע - ג שבט","b":"נכד ר משה קיטובר-גיסו של ר אברהם-גיסו של הבעש\"ט. רב בפולשטין, ובנו ר מרדכי על מקומו אחריו. חיבר גם \"שביל אמונה\" על \"אמונות ודעות\" לר סעדיה גאון, \"דברי ישראל\", ועוד."},{"i":42362,"n":"קיטובר, מרדכי הלוי","f":"ישראל - בירורי המדות","bt":"תרלד","b":"מצאצאי ר משה קיטובר, ומצד אמו מצאצאי ר משולם זוסיא (זושא) מאניפולי. רב בפולשטין-פלך מינסק-תרסד על מקום אביו. נסמך מאת: ר אברהם שאול מחאטין."},{"i":42363,"n":"קיטובר, משה","f":"מנחם מנדל","dt":"תצח - יז שבט","b":"מקובל,איש מופת,רב בקיטוב. גיסו של ר אברהם גרשון-גיסו של הבעש\"ט."},{"i":42364,"n":"קיטיגורודסקי,אליעזר מדרוהוביטש","f":"פנחס מרווצק","k":"העילוי מרווצק","bt":"תרלב","bp":"רווצק (רוסיה)","dt":"תשיד","b":"חסיד סדיגורא. למד בוולוזין, במיר ובסלובודקה. חתן ר מרדכי חיים הרצברג מחרסון וברזן , עבר לגור אצל חותנו. נפצע כשאירגן הגנה בפני פורעים-תרסה. יסד ישיבות ברחבי גליציה. התישב בסכודניצה עם אחיו ר אברהם, אח נוסף ר רפאל ראש ישיבת אור תורה בסטניסלב. ניסה ליסד ישוב חסידי בארגנטינה. עלה לארץ-תרצא והתגורר ברחובות."},{"i":42365,"n":"קיטייסקא, ברוך מסטולין","k":"בעל מקור ברוך","b":"רב בסטולין, ילסווטגרד(=יעלסוועטגרד). קרוב של ר נחום שטינקריצער הכהן מוילנא."},{"i":42366,"n":"קיידנובר, אהרן שמואל מוילנא","f":"ישראל","k":"בעל תפארת שמואל","r":"אב\"ד ניקלשבורג, בריסק, פיורדה, פרנקפורט דמיין, קראקא","bt":"שפד","bp":"קידאן או וילנא","dt":"תלו-ח - יט תמוז","dp":"חמלניק או קראקא","b":"תלמיד ר יעקב מלובלין, ובנו ר אברהם יהושע השל מקראקא. חתן ר אברהם ר אלעזרש מוילנא. רב ברישא, ביאלה, וילנא וברח בגזירות-תח והגיע לוינה, חזר ושוב ברח בזמן מלחמת שבדיה-פולין-תטו והתישב בקורוב-ליד לובלין ונאלץ לברוח שוב - אך בנותיו נרצחו עק\"ה בידי הקוזקים, הגיע למהרן וכיהן כרב בניקלשבורג-תיח, גלוגאו, פיורדא, פפד\"מ-תכח על מקום ר מנחם מנדל בס, קראקא והגליל-תלח על מקום ר אריה ליב דער הויכער ור יצחק חריף לנדא על מקומו אחריו, בשנת תכט ישב באלטונא כחצי שנה בדרכו מפפד\"מ לפולין. בהקדמה לספרו \"ברכת הזבח\" הוא מתאר את חורבן קהלת לובלין. חיבוריו לתלמוד שימשו יסוד למהדורת התלמוד בפפד\"א-תנז. רבים מכתביו אבדו. מחותן עם ר מאיר איזנשטט בעל \"פנים מאירות\", ועם בעל ר אפרים בעל שער אפרים ועם בעל הש\"ך ועם בעל הב\"ח. בנו - ר צבי הירש בעל \"קב הישר\". חתניו - ר נחום הכהן-אחיו של בעל הש\"ך, ר ישעיה הכהן מויטבסק, ר יוסף ר הרץ מגלוגא.","bk":[["אמונת שמואל",""],["ברכת הזבח",""],["ברכת שמואל",""],["תפארת שמואל",""]]},{"i":42367,"n":"קיידנובר, דוד","f":"ישראל","dp":"סלוצק","b":"אחיו של ר אהרן שמואל קיידנובר. הו\"ל ספר אחיו \"ברכת הזבח\"."},{"i":42368,"n":"קיידנובר, יוסף חסיד","f":"אברהם פייגס"},{"i":42369,"n":"קיידנובר, נחום","f":"ישראל","k":"בעל מאה ברכות","b":"אחיו של ר אהרן שמואל קיידנובר. (אולי זו טעות ומחבר הספר הוא ר שלום שכנא בן ר יונה נחום אחיו של בעל הש\"ך."},{"i":42370,"n":"קיידנובר, צבי הירש","f":"אהרן שמואל","k":"בעל קב הישר","r":"ראש ישיבת מאור עיניים - רחסמטריווקא ואח\"כ ראש ישיבת אופקים","bt":"תעב?","bp":"וילנא","dt":"תעב - טו אד\"ב","dp":"פפד\"מ","b":"חתן ר יצחק גנץ מפפד\"מ. תלמיד ר יוסף בן יהודה - בקבלה. ניצל מפרעות תח. רב במינסק. נאסר בעלילה עם משפחתו, ומששוחרר עבר לפפד\"מ - שם כיהן אביו כרב. הו\"ל ספרי אביו עם הגהותיו. ספרו \"קב הישר\" תורגם לאידיש ואף ללדינו. חתניו - ר יצחק שוורצשילד, ר אלחנן הענלא בן בנימין קיררכהן בעל \"שמחת הנפש\".","bk":[["קב הישר",""],["קב הישר - מוסר",""]]},{"i":42371,"n":"קיידנר, ליב חריף מריטובה","k":"לייבציג חריף","dt":"תרמה","b":"רב בריטובה, וויסוקי. ידידו של \"הגדול ממינסק\" שהמליץ עליו לרבנות סעלץ (כשעבר לפרוזין) - אך לא הסתייע. חתנו - ר אברהם אהרן בורשטיין מטאוריג וירושלים."},{"i":42372,"n":"קייזרלינג, מאיר מבודפשט","b":"רב בבודפשט-1870. נודע בדרשותיו בגרמנית. חיבר ספר לתולדות יהודי ספרד, מונוגרפיה על משה מנדלסון. חיבר מאמרים רבים בעתוני התקופה."},{"i":42373,"n":"קייזרלינג, משה מבודפשט","b":"חוקר שפת הלדינו."},{"i":42374,"n":"קיילנד, אלכסנדר - סופר נורבגי","b":"סופר נורבגי-נוצרי, ביקר בשלוניקי-תרנט ותיאר את הקהלה היהודית."},{"i":42375,"n":"קיים קדיש מאודסה","f":"צבי","b":"דיין באודסה, חתם-תרמד עם ר יוסף ישראל הלפרין."},{"i":42376,"n":"קיים קדיש מקרוטושין","f":"קיים קדיש","k":"בעל מאמר קדישין","b":"תלמיד ר יונתן איבשיץ. דיין בקורוטשין-תק'. נכדו ר קיים קדש, ונינו ר דב בער שטיינאייזן מוילנא."},{"i":42377,"n":"קיימות כמה מסורות, ראה הערה","b":"על אודות מחבר \"פסקי תוספות\", מצאנו כמה דעות: יש אומרים, שהוא הרא\"ש (שם הגדולים מערכת ספרים ע' פסקי תוספות, בשם דברי אמת) ויש אומרים, שחיברם הטור (שם הגדולים שם, בשם לחם שמים [יעב\"ץ] על המשניות סוף פסחים). אחרים אומרים, שהמחבר הוא ר' יחזקיה, דודו של ר\"א מטוך (אוצר הספרים ע' פסקי תוספות, בשם ר\"א משלצטט). פעמים רבות, החידושים שבפסקי תוספות אינם מופיעים בתוס' שלפנינו, וזאת משום שהם נעשו על פי קבצי תוספות אחרים מאלו הנדפסים בגליון הש\"ס (שם הגדולים שם; זכר יהוסף ח\"א סוס\"י עב).","bk":[["פסקי תוספות",""]]},{"i":42378,"n":"קיל, יחיאל מסנוק - א","k":"בעל זכרון יחיאל","b":"תלמיד ה\"בני ישכר\". רב בטרווא, נוביטץ-ליד סנוק, אדמור בסנוק ועל קברו הוקם \"אוהל\". רוב חבוריו אבדו. חיבר \"זכרון יחיאל\" פרמישלא תרנד. ?? לא באוצר ??"},{"i":42379,"n":"קיל, יחיאל מסנוק - ב","f":"יצחק אייזיק","bt":"תרסג","bp":"סנוק","dt":"תשמו","b":"נכד השרף מסטרליסק ור\"ח מקוסוב. עבר לשוויץ ונתקבל לשגרירות פולין בברן, משם עסק בהצלת אלפי יהודים - ארגן הנפקת דרכונים זרים ממדינות שונות ליהודים בזמן השואה (ביניהם האדמור מבלז). אחר המלחמה היגר לניו יורק, טורונטו ומיאמי. עסק כל ימיו בעזרה וחסד. נשיא מוסדות בלז בארה\"ב, בנו ר יצחק איזיק מטורונטו על מקומו אחריו."},{"i":42380,"n":"קילוב, משה","b":"רב בריגא"},{"i":42381,"n":"קילטי, יהודה הפייטן","f":"אהרן","b":"פייטן ביוון. חיבר יוצרות לפרשות מיוחדות ולפסח."},{"i":42382,"n":"קילמן, משה מלנצקריני","b":"פרסם מאמרים ב\"קול תורה\" - וארשא תרסח."},{"i":42383,"n":"קימל, דב בר מקניהניטש","f":"יצחק איזיק הלוי","k":"בעל בית הלוי","bt":"תרך","dt":"תרצז","b":"תלמיד ר מאיר גוטשטיין מבלשביץ. רב בסאסוב-תרסב אצל ר שלמה מייער. רב בקניהניטש-תרסח. נכדו ר מנוח הנדל על מקומו אחריו. חיבר \"בית הלוי\" על נועם מגדים לבעל פמ\"ג - מונקטש תרע."},{"i":42384,"n":"קימל, דוד הלוי מקניהיניטש","b":"פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":42385,"n":"קימלמן, יחזקאל יהודה מסוסנוביץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":42386,"n":"קימלמן, יצחק מבנדין","b":"תלמיד ר ישכר דב מראדושיץ, ר אברהם יעקב מסדיגורא, ובנו ר יצחק מבויאן. אב\"ד בנדין."},{"i":42387,"n":"קימפלפלד, בנימין","b":"רב בווסילקוב-תרל\"ה"},{"i":42388,"n":"קינדלש, יחזקאל מנאחאד","f":"יצחק","k":"הו\"ל מראה יחזקאל קטן","bt":"שץ","dt":"תסד","b":"דיין בפרג, אב\"ד נאחוד-תס. תלמיד ר אהרן שמעון שפירא מפרג והו\"ל קיצור מספרו \"מראה יחזקאל - תנה."},{"i":42389,"n":"קינדרמן, נח","dt":"תשג","b":"ראב\"ד בקאלושין"},{"i":42390,"n":"קינדרמן, שלמה יצחק מאושפיצין","b":"תלמיד בישיבת כתר תורה באושפיצין. מתורתו ב\"כתר תורה\" - אושפיצין תרצט."},{"i":42391,"n":"קינס, ישכר דוב","dt":"תקצא - כא תמוז","b":"דיין בקרקא"},{"i":42392,"n":"קינסט, פנחס מלודז","b":"פרסם מאמרים ב\"המפלפל\" - קראקא תרעג."},{"i":42393,"n":"קינסטליכר, אהרן מסעבען","f":"צבי מסעבען","b":"תלמיד הדעת סופר. מחכמי סעבען. עלה לארץ והתישב בבני ברק."},{"i":42394,"n":"קינסטליכר, אליעזר מבנפי-הוניאד","f":"צבי מסעבען","b":"רב בבאנפי-הוניאד."},{"i":42395,"n":"קינסטליכר, אליעזר מבעטלען","f":"צבי מהרמנשטדט","b":"חתן ר שלמה זלמן ליכטנשטין מבעטלען. רב בהוניאד. נספה בשואה."},{"i":42396,"n":"קינסטליכר, דב מירושלים","f":"צבי מסעבען","b":"תלמיד הדעת סופר. עלה לירושלים."},{"i":42397,"n":"קינסטליכר, יחזקאל מסעבען","f":"צבי מסעבען","b":"מחכמי סעבען."},{"i":42398,"n":"קינסטליכר, משה זושא מביסטריץ","f":"צבי מסעבען","b":"תלמיד הדעת סופר. מחכמי ביסטריץ-באניא."},{"i":42399,"n":"קינסטליכר, צבי הירש מסעבען","f":"אריה ליב מהומנא","k":"בעל באר צבי-תשכט","bt":"תרכט","bp":"האנשוביץ","dt":"תשכה - ז אד\"א","dp":"ירושלים","b":"תלמיד ר אליעזר דייטש בהאנשוביץ, בעל \"ערוגת הבשם\" בחוסט, והשב\"ס. חתן הגביר ר יצחק הכהן הנדלר מבאיאר-וואגאש, ועבר לשם. רב בטשרנוביץ, דיין באנפי-הוניאד-תרסב, סעבען-תרעט, רב הקהלה הספרדית בהרמנשטדט. ניצל מהשואה, ואחריה עליה לירושלים-תשט. נשיאר כולל \"אהבת ציון\" זיבנבירגן. בנו ר דב וחתנו ר בצלאל שטרן הו\"ל את ספריו."},{"i":42400,"n":"קינסטלינגר, זיסקינד","f":"יחיאל מוישניצה","b":"ראש ישיבת בובוב."},{"i":42401,"n":"קינציקר, הרצל","b":"מרביץ תורה בטיסמניץ-תק\"נ"},{"i":42402,"n":"קינקולקין, שאול","bt":"1830","dt":"1908","b":"מוכר ספרים. \"נושא תרבות פולנית אחרון בליטא. נאסר-1861 על הפצת כרוזים פטריוטים וספרות פולנית וישב שנה בבית הסוהר בוילנא השתתף במרד הפולני-1863. הלוויתו בוילנא הפכה להפגנה פטריוטית פולנית, והעתונות הפולנית פרסמה מאמרים נלהבים לזכרו. המשורר הפולני ודליסלב סירוקומלא הנציח אותו בפואימה \"מוכר הספרים ברחוב\"."},{"i":42403,"n":"קיס, אברהם ישראל מאנגליה","bp":"אנגליה","dt":"תקפט - יא חשון","dp":"פילדלפיה","b":"הגיע לאיי הודו המערבית באמריקה, רב בפילדלפיה-תקפד."},{"i":42404,"n":"קיסטר, יצחק ממושציסק","f":"יהודה צבי","bt":"תרסו","bp":"מושציסק","b":"ד\"ר למשפטים בלמברג. עלה לארץ-תרצה. שופט בבית המשפט העליון-תשכה, ובעל זיקה למשפט העברי. ממקורב לרב מפוניבז'. חתן ר עקיבא שוימר מגורליץ, ובזיוו\"ש חתן ר יעקב מה-יפית מריגה."},{"i":42405,"n":"קיסילוב, משה אהרן","k":"בעל משברי ים","b":"רב בבריסוב,חרבין-תר\"ע,רב הכולל לקהילות במזרח הרחוק"},{"i":42406,"n":"קיסין, אברהם מקובנא","k":"בעל הטבע -קובנא תרצח","bt":"1899","bp":"פוניבז","dt":"1945","dp":"דכאו","b":"מורה לטבע בגימנסיה העברית ריאלית בקובנא. חוקר הצמחיה של אזור הים הבלטי. פעיל בחיי הציבור בליטא. יו\"ר אגודת המורים העבריים, ועורך בטאונה \"במשעולי החנוך\". הו\"ל יחד עם א.ש. פינטשוק ספרי לימוד במדעי הטבע. ?? לא באוצר ??"},{"i":42407,"n":"קיסלוביץ, אליעזר (קרעשובר)","b":"ר\"מ בישיבה בגריבוב-תרצג, אצל האב\"ד ר מרדכי זאב הלברשטט, עבר עםו לצאנז כשר מרדכי התמנה שם לרב על מקום אביו - וכיהן כר\"מ בישיבתו. רב בקרשניק. הוזמן ע\"י מהר\"ם שפירא ללמד בישיבה - אולם לא הסתייע. נספה בשואה. מתורתו \"ברכה משולשת\"."},{"i":42408,"n":"קיפי, חיים מחימא","f":"שלמה","bt":"תרל","bp":"אלחימה","dt":"תרצה","dp":"אלחימה","b":"רב בעיר חימא"},{"i":42409,"n":"קיפניס, יהושע פאלק מנארינסק","f":"יחיאל מיכל","bt":"תרח","b":"רב בנארינסק-ווהלין-תרמג."},{"i":42410,"n":"קיפניס, שמואל מירושלים","f":"יהושע פאלק","k":"בעל נתיבות שמואל","bt":"תרמג","bp":"נארינסק-אוקראינה","dt":"תשלט","b":"נכד-אבי אביו הר\"י מקמינקא, ונכד-אבי אמו ר שמואל מנארינסק וסטולין. תלמיד ר שמריה נח שניאורסון בקיבוץ החבדי בבוברויסק. נסמך מאת: ר מאיר שפירא בבוברויסק, האדמורים מצ'רנוביל, הורוסטיפל. רב באוורוטש-פלך ווהלין-תרסז, עלה לירושלים-תרצד, מגדולי חכמי ופעילי ירושלים-תרצד, מייסד \"אוצר הפוסקים\", ו\"התאחדות רבנים פליטי רוסיה\" בירושלים. קבלה בידיו שהוא דור 35 לשושלת רבנים."},{"i":42411,"n":"קיץ יוסף","bt":"1890","dt":"ה'תשכ 1960","bk":[["אונזער בעוועגונג",""]]},{"i":42412,"n":"קיצה חיים בן יצחק","bt":"1772","dt":"ה'תרי 1850","bk":[["אוצר חיים",""],["שנות חיים",""]]},{"i":42413,"n":"קיצינגן, זלמן מוירצבורג","b":"מגדולי חכמי התורה בווירצבורג,נירנברג,רגנשבורג-ר\"כ"},{"i":42414,"n":"קיצינגן, יוסף מפרג","bt":"שמד","dt":"שסז - ו אב","b":"מגדולי חכמי פרג"},{"i":42415,"n":"קיצינגן, יעקב ממזריטש","f":"יוסף","b":"תלמיד המהרש\"ל. אב\"ד מזריטש. חיבר פיוט על דיני סדר פסח, שיר \"סדר היום ביום שלחנא\" וסליחה ליום חמישי של עשי\"ת - \"אתאנו לבקש מחילתך\"."},{"i":42416,"n":"קיציס, זאב עוזר מטלוטשין","b":"נכד ר זאב וולף קיציס-תלמיד הבעש\"ט. נזכר במכתב ר ברוך ממזיבוז אל הרב מאפטא שאמר עליו שבחים."},{"i":42417,"n":"קיציס, נחמן דב","f":"זאב עוזר מטלוטשין","b":"מצאצאי ר זאב קיציס-תלמיד הבעש\"ט."},{"i":42418,"n":"קיצס, אלתר מזלישטשיק","b":"מחכמי זלישטשיק. חתן ר אברהם תאומים מזלישטשיק."},{"i":42419,"n":"קיצס, זאב וולף","b":"רב-שנת תק\"ל. מכתבים ממנו ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":42420,"n":"קיצע - משפחה","b":"מקור השם - עיירה קטנה ליד פרשבורג."},{"i":42421,"n":"קיצע, גרשון מטימישואר","f":"חיים מאלברט-אירשא","dt":"תרט - יב חשון","dp":"טימישואר","b":"תלמיד החת\"ס. דיין בטימישואר. נפטר בחיי אביו."},{"i":42422,"n":"קיצע, דוד משה מפרשבורג","b":"דומ\"צ בפרשבורג-תקל אצל ר מאיר ברבי. חתם על תקנות ר מאיר ברבי-תקכח."},{"i":42423,"n":"קיצע, חיים (שלזינגר) מאירשא","f":"יצחק מאויבן","k":"בעל אוצר החיים","dt":"תרט-י - א תמוז","b":"תלמיד ר משה מינץ, ר בנימין זאב רפפורט. חתן ר ישראל בריל מפלוטא, ובזיוו\"ש חתן ר מרדכי טאסק מפרשבורג. מו\"צ בווספרם(=ועספרעם), איזשאק, רב באירשא. הניח כ-80 כרכים של חדושים - ומהם נדפס \"אוצר חיים\". בניו: ר גרשון מאוגאר, ר מאיר מסארוש, ר שמואל שלזינגר, חתניו: ר יצחק צבי מרגרטן מאבראהאם, ר יוסף מייזנר מוינערן."},{"i":42424,"n":"קיצע, יחיאל מיכל מפרשבורג","f":"שמואל פינדר מקיצע","k":"בעל שלמי נדבה","dt":"תרה - כו אלול","dp":"פרשבורג","b":"גביר עשיר מראשי קהלת פרשבורג בזמן החת\"ס. תלמיד ר מרדכי בנט מניקלשבורג. חתן ר מנדל טעבן מפרשבורג. חתם על כתב מנוי הרבנות לחת\"ס. חיבר \"שלמי נדבה\" פרשבורג תקצח."},{"i":42425,"n":"קיצע, יצחק מקיצע","b":"ראב\"ד בקיצע-תקע, דיין באויבן(=בודפשט). בנו - ר חיים מאירשא, חתנו - ר שמעון-נכד ר שמואל קעלין בעל \"מחצית השקל\"."},{"i":42426,"n":"קיצע, מאיר מצעהלים","f":"משה יעקב","dt":"תקעה - לפני","b":"דיין ומו\"צ בצעהלים-הונגריה-שנות ה-תק'."},{"i":42427,"n":"קיצער, יעקב מפרשבורג","b":"משכיל בפרשבורג, חיבר חוברת בגרמנית נגד התלמוד - פרשבורג תריז וחילקה בחינם. כנגדו יצא חוברת תגובה \"קורצע אבפערטיגונג\" מאת ר זליג ליב שיק - התוקף את החיבור ומחברו."},{"i":42428,"n":"קיקי ן, דוד ממכנאס","b":"מחכמי מכנאס-שנות ה-ת'. בנו - ראובן עמד לדין בפני היעב\"ץ בהיותו במכנאס."},{"i":42429,"n":"קיקי ן, יוסף חיים מטבריה","b":"מרבני טבריה-תרע\"ד"},{"i":42430,"n":"קיקי ן, יעקב ממרוקו וירושלים","b":"רב ברבאט(מרוקו),עלה לירושלים-תרט\"ו"},{"i":42431,"n":"קיקי ן, ראובן ממכנאס","b":"מחכמי מכנאס-תפח."},{"i":42432,"n":"קיקי ן, ראובן ממרוקו וירושלים","b":"מחכמי רבאט-מרוקו, עלה לירושלים-תריח."},{"i":42433,"n":"קיקי ן, שמואל מטבריה","f":"דוד מרבאט","k":"בעל דוד שם","bt":"תרב או תריא","bp":"ראבט","dt":"תרעט - ג טבת","dp":"טבריה","b":"עלה בילדותו עם אביו לטבריה והיה מחכמי טבריה, פייטן ומשורר. חתנו של ר יוסף דוד אבולעפיה רבה של טבריה. בשנת תרסז בשליחות בצפון אפריקה. דיין בטבריה אצל ר יעקב הכהן סקלי, וראב\"ד על מקומו אחריו. מתלמידיו ר יעקב חי זריהן רבה של טבריה. בניו ר דוד שנפטר צעיר, ור אליהו ראובן שנפטר בשליחות טבריה בביירות. חיבר גם \"מערכות שמואל\""},{"i":42434,"n":"קיקי, חיים מטבריה","f":"שמואל","bt":"תרמז","bp":"טבריה","dt":"תרצה","dp":"עדן-תימן","b":"משכיל, התישב בחיפה, פרסם מאמרים בעתונים, עבר לירושלים, חזר לטבריה, בשליחות הקהלה בהודו - ונפטר בדרכו."},{"i":42435,"n":"קיקניש - משפחה","b":"משפחה מצאצאי יונה הנביא."},{"i":42436,"n":"קיקניש, אדל מדרוהוביטש","f":"משה מלבוב","dt":"תע-ח - כו אלול","dp":"לבוב","b":"נהרגה עק\"ה בעלילת דם."},{"i":42437,"n":"קיקניש, יעקב מלבוב","f":"אליעזר","dt":"שצא - כא תשרי","dp":"לבוב","b":"ר\"מ ומרביץ תורה בלבוב."},{"i":42438,"n":"קיקניש, יצחק מלבוב","f":"יעקב","dt":"תנז - ח חנוכה","dp":"לבוב","b":"דיין בלבוב."},{"i":42439,"n":"קיקניש, ישעיה מלבוב","f":"מרדכי","b":"דיין בלבוב, חתם-תקד בפנקס הקהלה, חתם-תקכו בענין עזבון לטובת יתומים."},{"i":42440,"n":"קיקניש, לוי מלבוב","f":"יעקב","k":"ר' לוי הרופא קיקינש","dt":"רסג - טו ניסן","dp":"לבוב","b":"רופא, אב\"ד וינה?, לבוב. (לדעת הספר מצבות קדש הוא שנזכר אצל בעל עטרת זקנים שהיה רופא ואב\"ד בוינה ונכד מהר\"ל רופא מוינה - אך בובר דוחה את דבריו)."},{"i":42441,"n":"קיקניש, משה מלבוב","f":"יעקב","dt":"תכט - ב אייר","dp":"לבוב","b":"ראב\"ד בלבוב. בתו אדיל מדרוהוביטש נהרגה עק\"ה - כו אלול תע."},{"i":42442,"n":"קיקניש, משה מלבוב - ב","f":"מהר\"ם קיקיון","b":"דיין בלבוב, חתם-תסא על תקנת קהלת זולקוא."},{"i":42443,"n":"קיקניש, שמואל מלבוב","f":"מאיר","dp":"לבוב","b":"מרביץ תורה, דיין בלבוב. אולי הוא שנזכר בשו\"ת מהר\"ם בלובלין."},{"i":42444,"n":"קירזנר, זליג מלנין","b":"רב בלנין. מתורתו ב\"תורה אור\" - שנחאי תשו."},{"i":42445,"n":"קירידו, ברכיה","f":"יעקב פילוסוף-קירידו","b":"ראש כת הדונמה על מקום אביו."},{"i":42446,"n":"קירידו, יוסף משלוניקי","dt":"תקיב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":42447,"n":"קירידו, יעקב מאזמיר","b":"חתן ר יוסף חזן בעל \"עין יהוסף\". מו\"ץ באזמיר (אינו יעקב קירידו פילוסוף שהיה חותנו של ש\"ץ)"},{"i":42448,"n":"קירכהיים, חיים מפפד\"מ","dt":"תק","b":"גביר בפפד\"מ, נחשד בשבתאות והוטל עליו קנס."},{"i":42449,"n":"קירכהיים, רפאל מפפד\"מ","k":"בעל כרמי שומרון","bt":"תקסד","bp":"פפד\"מ","dt":"תרמט","dp":"פפד\"מ","b":"שו\"ב בפפד\"מ, פנה להשכלה, התקרב לגייגר והצטרף לריפורמים, חיבר ספרים ומאמרים בתולדות ישראל. התנגד לר צבי הירש לעהרן ולפקידים ואמרכלים."},{"i":42450,"n":"קירכהן, מנוח הנלי","f":"צבי קיידנוב","k":"בעל שמחת הנפש","b":"רב-שנת ת\"ס"},{"i":42451,"n":"קירכמן, אלחנן חענלה","f":"צבי הירש קיידנובר","b":"שנת ת\"ס"},{"i":42452,"n":"קירנקרויט, ישראל","dt":"תשג","b":"רב בבארוב"},{"i":42453,"n":"קירש, ישעיה נפתלי הרץ מטשיטש","f":"שמואל יעקב","dt":"תשב","b":"רב בטשיטש. חסיד בלוזוב-ריבטיטש. נספה בשואה."},{"i":42454,"n":"קירש, רפאל מאברניק","f":"אלכסנדר","b":"תלמיד השב\"ס. רב בקלויז בהמבורג, אבארניק (מחוז פוזנא)-תרנה, בומברג, ברלין. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":42455,"n":"קירשבוים, יהודה ליב ממיטאוי","f":"יעקב","b":"גביר במיטאוי."},{"i":42456,"n":"קירשבוים, מנחם מנדל מפפד\"מ","b":"רב בפפד\"ם בדור שלפני השואה."},{"i":42457,"n":"קירשברג, יצחק מנחם מסוקולוב","dt":"תשב","b":"רב בסוקולוב-תרף, מעליץ. נספה בשואה."},{"i":42458,"n":"קירשנבוים, אברהם יעקב מפרמישלא","b":"מחכמי פרמישלא. ממשתתפי \"אהל מועד\"."},{"i":42459,"n":"קירשנבוים, אברהם צבי מסקאהל","b":"סופר סתם בסקול. תשובה אליו - \"דובב מישרים\" תרצד."},{"i":42460,"n":"קירשנבוים, חיים צבי מטרנוב","b":"רב בטרנוב, במלחמה העולם ה-I עבר לוינה."},{"i":42461,"n":"קירשנבוים, יוסף אליהו מירושלים","b":"הו\"ל \"קול תורה\" - ירושלים תרץ, \"תורת ארץ ישראל\" - ירושלים תרץ."},{"i":42462,"n":"קירשנבוים, יוסף חיים","f":"ישראל מאיר מדזיקוב","k":"בעל קב מים חיים","b":"חתן ר משה יהודה אפטר מטרנוב. רב בטרנוב על מקום חותנו. חיבר \"קב מים חיים\" - נדפס עם אמרי משה למותנו."},{"i":42463,"n":"קירשנבוים, ישראל מאיר מדזיקוב","b":"חסיד סדיגורא. רב בדזיקוב על מקום ר יהושע נוסבוים. למד עם בני האדמור."},{"i":42464,"n":"קירשנבוים, מ' יהודה מוארשא"},{"i":42465,"n":"קירשנבוים, מנדל מקראקא","f":"שמואל קירשבוים","k":"בעל דברי מנחם","bt":"תרכט","b":"רב במזיארניא-תרב, מו\"צ בקראקא. נסמך מאת: ר יצחק שמלקיס, מהרש\"ם מברעזן, ר אברהם מסוכטשוב בעל \"אגלי טל\"."},{"i":42466,"n":"קירשנבוים, מנחם מנדל מקראקא","f":"שמואל מקראקא","k":"בעל מנחם משיב","bt":"תרנה","bp":"קראקא","dt":"תשג","b":"תלמיד ר פנחס אליהו דמביצר והוציא לאור את ספר רבו \"גבעת פנחס\" עם הגהותיו בשם \"קצה הגבעה\" והספד. (אחד ממתנגדיו פרסם ב\"אהלי שם\" - ביוגרפיה בדויה עליו - והוא בתגובה קרא לספר \"אהלי שקרים\"). חתן הנגיד ר משה ליכט מויליצקה. רב בסקאלה-תרפז, פרנקפורט, ברלין-תרצז, ביקר בארץ-תרצו. נספה בשואה. חיבר \"מנחם משיב\" לובלין תרצה, \"ציון למנחם\" (ונספח לו קובץ מכתב העת \"המפלפל\"), ועוד. פרסם מאמרים ב\"אהל מועד\" - איזביצא - בילגוריי - תרפו, \"בית ועד לחכמים\" - סטמר תרפב, \"הבאר\" - וארשא תרפד, \"המפלפל\" - קראקא תרעג, \"קהלת אשר\" - אושפיצין תרפג, \"שערי ציון\" - ירושלים תרפא."},{"i":42467,"n":"קירשנבוים, משה יהודה מדובשיץ","f":"יוסף חיים מטרנוב","dt":"תש..","b":"חתן ר מתתיהו חיים הלפרין מדובשיץ. רב בלודז, אנדזיוב,אוטואצק, דובשיץ על מקום חותנו. עורך \"דגל הצעירים\" - וארשא תרפה, \"דגל הרבנים\" - וארשא תרפו. פרסם מאמרים ב\"אסיפת חכמים\" - מלניץ תרפח, \"הבאר\" - זאמושץ תרפד, פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב, \"יגדיל תורה\" - פראגא-וארשא תרפז. נספה בשואה."},{"i":42468,"n":"קירשנבוים, משה מטרנוב","dt":"תשג","b":"רב בטרנאוו"},{"i":42469,"n":"קירשנבוים, שמואל","b":"רב-שנת תר\"מ"},{"i":42470,"n":"קירשנבלום, יוסף חיים","dt":"תשג","b":"ראב\"ד בטארנא"},{"i":42471,"n":"קירשנבלום, משה יהודה","dt":"תשג","b":"רב בווישניווא-גורא"},{"i":42472,"n":"קירשנר, יעקב","f":"אבא","k":"ר יעקילע ר אביס","b":"ראש ישיבת כתר תורה דרדמוסק בקשאנוב."},{"i":42473,"n":"קירשנר, יעקב יוסף","f":"יהושע","bt":"תרמ","b":"מו\"צ בקאוול-תרס, רב בטוראוו-פלך מינסק-תרסח."},{"i":42474,"n":"קירשנר, יצחק מקשאנוב","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":42475,"n":"קיש, ארנולד מבודפשט","k":"בעל מרים","b":"רב ניאולוגי בואספרום-1896 והרמן הופר על מקומו אחריו, בודפשט ומחשובי הרבנים הניאולוגים בהונגריה. סופר ומשורר. חיבר סידור תפלה לנשים בשם \"מרים\" - בהונגרית, וסידור לנערות בשם \"נעמי\". תרגם להונגרית את כתבי מוריס רוזנפלד. חיבר תולדות חיים של אבן גבירול ור שמואל הנגיד. פרסם מאמרים בעתונים יהודיים ואחרים."},{"i":42476,"n":"קיש, חנניה יו\"ט ליפא מפרשוב","f":"שמואל שמלקא","k":"בעל פתיל חיי-תשלט","bp":"באניא","dt":"תשמא - י ניסן","dp":"בני ברק","b":"תלמיד בעל \"קרן לדוד\" בסטמר, ובעל \"עצי חיים\" בסיגט. עבר לפרשוב. ניצל מהשואה ואחריה עלה לארץ והתישב בבני ברק והשמיע דברי תורה ברבים."},{"i":42477,"n":"קישאליס, יצחק מאדרינופול","b":"רב באדרינופול-שנות ה-ש'."},{"i":42478,"n":"קישאליס, יצחק שמואל","k":"בעל יוסף השני","bt":"תרם","bp":"פיליפופולי","dt":"תרצא - ט חשון","dp":"פיליבי","b":"מורה בפרובאדיה. חיבר ספרים ומחזות."},{"i":42479,"n":"קלאוס, אהרן","f":"משה יוסף","bt":"1914","bp":"ז'וסלי","dt":"1961","dp":"תל אביב","b":"תלמיד הגימנסיה העברית בוילקומיר. פעיל ב\"בית\"ר\". עלה לארץ-1936. חבר במערכות עתונים בארץ. עורך שנתון העתונאים."},{"i":42480,"n":"קלאסין, דוד מירושלים","f":"אברהם","dt":"תרכה - טז תמוז","dp":"ירושלים","b":"ילד פרייסען, גר צדק, בעל פרדס ביפו."},{"i":42481,"n":"קלאץ, בער הרש","dt":"תשא","b":"רבה האחרון של סלנט"},{"i":42482,"n":"קלב, אברהם מסטריזוב","f":"תנחום יעקב","dt":"תש..","b":"שו\"ב בסטריזוב. חתן ר בצלאל שו\"ב מסטוטשין. נספה בשואה. בנו ר בן ציון שהציל יותר מ-3000 יהודים בשואה - ניצל והיגר לניו יורק (נכד ר לייביש ב\"ר אברהם נוביטניצר שתקע בשופר אצל ר צבי מרימנוב)."},{"i":42483,"n":"קלבאנוב, משה מרדכי מבוסטון","k":"בעל המדרש והמעשה","b":"רב ק\"ק קלויזנבורג בבוסטון. חיבר \"המדרש והמעשה\" ירושלים תרצב. ?? לא באוצר ??"},{"i":42484,"n":"קלביירו, שלמה מספרד","dt":"רפ - בערך","b":"רופא מחכמי קטלוניה-ספרד, אחרי הגירוש הגיע לשלוניקי ועסק ברפואה, והיה מראשי הקהלה."},{"i":42485,"n":"קלבנסקי-קליין, יהושע מארה\"ב","bt":"תרמב","dt":"תשיג","b":"רב בזסקוביץ-תר\"ס,גילוואן,וושינגטון-תרפ\"ד"},{"i":42486,"n":"קלגסבלד, יחזקאל","bp":"גליציה","dt":"תשנג","b":"ניצל מהשואה - גלה לסיביר, עלה לארץ והיה בעל תפלה בבית הכנסת הגדול בבני ברק. נפטר בלי ילדים."},{"i":42487,"n":"קלגסבלד, שלמה מקשנוב","bt":"תרסח","bp":"קשנוב","b":"יו\"ר צא\"י. עבר מקשנוב לאנטורפן-תרפו. ניצל מהשואה ואחריה עסק בשיקום קהילת מחזיקי הדת."},{"i":42488,"n":"קלגסברון, יהושע השל ברים ממיר","f":"מרדכי דוד","bt":"תרעג","bp":"ירושלים","dt":"תשמו","dp":"ירושלים","b":"ר\"מ בישיבת מיר, מיסד וראש ישיבת תפארת ישראל - רוזין."},{"i":42489,"n":"קלגסברון, יצחק מאיר","f":"דוד מוישניצא","bt":"תריד","bp":"גליציה","dp":"תרצז","b":"עלה לארץ-תרכז (עם המלצה מהאדמור משיניבה) - והיה ממונה כולל גליציה. חתן ר יהושע השל פרנקל-תאומים. בנו ר מרדכי דוד ברי\"ם (שם משפחתו - בן ר יצחק מאיר)."},{"i":42490,"n":"קלדרון, חיים מאזמיר","dt":"תקטז - כ תמוז","dp":"אזמיר","b":"רב באזמיר-שנות ה-ת'."},{"i":42491,"n":"קלדרון, יוסף מצפת","f":"עזרא","b":"מחכמי צפת, בשנת שמב חתם עם רבני צפת. דיין בשלוניקי-שמח - יחד עם ר דניאל אישקאפה."},{"i":42492,"n":"קלדרון, נסים מתורכיה","dt":"תרסו - כו שבט","dp":"טבריה","b":"עלה לטבריה."},{"i":42493,"n":"קלדרון, עזרא","b":"מחכמי חברון, בשנת תכא חתם על כתב שליחות ר חייא דיין."},{"i":42494,"n":"קלדרון, עזרא משלוניקי","b":"מחכמי שלוניקי-רץ."},{"i":42495,"n":"קלדרון, שם טוב מטבריה","b":"מחכמי טבריה, בשנת תקעו חתם על כתב שליחות ר חיים שלמה אבולעפיה, בשנת תקסו בשליחות במגרב."},{"i":42496,"n":"קלדרון, שמואל מאישקופיא","b":"רב הכולל באישקופיא או מונסטיר-תקנא."},{"i":42497,"n":"קלהארא, מתתיהו מקראקא","dt":"תכד","dp":"פיעטרקוב","b":"רוקח מחכמי קראקא. נהרג עק\"ה לאחר ויכוח דתי שהיה בקראקא עם נזיר דומיניקני."},{"i":42498,"n":"קלהרי, מנחם מנדל מקראקא. דוקטר","f":"מיכאל מיכל","dt":"תקלב - ז טבת","dp":"קראקא","b":"גביר מחכמי קראקא."},{"i":42499,"n":"קלוביסטיאן, פאול","b":"מומר ומלשין - בעקבות מלשינותו הוחרמו ספרי היהודים בפפד\"מ-תפז, ובמקומות נוספים. כמו כן נאסר ר דוד לידא בפריבורג עקב הלשנתו."},{"i":42500,"n":"קלוגהופט, אורי מסטרליסק","f":"פנחס","k":"השרף מסטרליסק","bt":"תק-תקיז","bp":"ינוב","dt":"תקפו - כג אלול","b":"מקורב לגדולי האדמורים ובהם ר אלימלך מליזנסק, ר פנחס מקוריץ, ובעיקר ר שלמה מקרלין. התגורר בלמברג והחל לנהוג אדמורות-תקנב אחר פטירת האדמור ר שלמה מקרלין. עבר לסטרליסק ונקרא בשם השרף מסטרליסק (על שום תפלתו המרשימה). בין חסידיו היו השר שלום מבלז, ותלמידו המובהק היה ר יהודה צבי ברנדוין - שמינהו ליורשו במקום בנו - ומסר לו ספר רפואות שקיבל מר שלמה מקרלין. בזיוו\"ש חתן ר יעקב קופל חסיד מקולומיאה, והיה גיסו של רמ\"מ מקוסוב. תלמידו ר זאב וולף שענבלום הדפיס לקט מחדושיו בשם \"אמרי קדוש\" למברג תרל. מתולדותיו ב\"אור עולם.. תלמיד ר יהודה צבי מסטרטין על מקומו אחריו (לפי אלפסי בנו ר שלמה על מקומו אחריו - ומהרי\"ץ על מקום בנו)."},{"i":42501,"n":"קלוגהופט, חיים אברהם מסטרליסק","f":"משה מסטרי","dt":"תשג - ו סיון","b":"נכד ר שלמה בן ר ללוי יצחק מאטיניא. חתן ר אשר ישעיה מסטרי (סמבור). נספה בשואה."},{"i":42502,"n":"קלוגהופט, יוסף מסטרליסק","f":"שלמה האדמור מסטרליסק","b":"רב בסטרליסק-תרנח."},{"i":42503,"n":"קלוגהופט, יעקב מברוד","b":"מחכמי ברודי. נכד ר מרדכי לורברבוים מצפת בן החוות דעת, והוציא לאור מספריו."},{"i":42504,"n":"קלוגהופט, לוי יצחק מאטיניא","f":"שלמה מסטרליסק","b":"נכד ר אורי השרף מסטרליסק. רב באטיניא, וחתנו ר אשר ישעיה פרנקל מסטרליסק על מקומו אחריו."},{"i":42505,"n":"קלוגהופט, לוי יצחק מסטרליסק","f":"משה מסטרי","bt":"תרסב","bp":"סטרליסק","dt":"תשמא - כב טבת","dp":"ירושלים","b":"חתן ר אפרים מרדכי שמרלר מוינה. רב בוינה. חסיד רוזין-צורטקוב. ניצל מהשואה - ברח לאנגליה-תרצט וכיהן כאדמור בלונדון. עלה לארץ-תשלז והתגורר בירושלים."},{"i":42506,"n":"קלוגהופט, משה מטרנופול","f":"יהודה צבי מטרנופול","b":"תלמיד ר משולם ראטה. רב בטרנופול, אוסטיטשקי, חירוב."},{"i":42507,"n":"קלוגהופט, משה מסטרי","f":"חיים","dt":"תשג","dp":"סטרי","b":"חתן ר שלמה ב\"ר לוי יצחק מאטיניא. נספה בשואה."},{"i":42508,"n":"קלוגהופט, שלמה מסטרליסק","f":"אורי השרף מסטרליסק","k":"אדמור מסטרליסק","bt":"תקם","dt":"תקפז - כב טבת","b":"מקורב לחוזה מלובלין ולר ישראל מרוזין. אדמור בסטרליסק - לאחר שהשרף העביר את ההנהגה לתלמידו ר יהודה צבי (=מהרי\"ץ) - שהתיישב בסטרטין. השר שלום מבלז והמהרי\"ץ נסעו אליו (כיהן כאדמור 4 חדשים). (לפי אלפסי היה אדמור על מקום אביו ומהרי\"ץ היה אדמור על מקומו אחריו בסטרטין)."},{"i":42509,"n":"קלוגמן, יוסף שמואל מפרמישלא","b":"רב בפרמישלא-תרכא."},{"i":42510,"n":"קלוגמן, יצחק צבי מוולברום","f":"מנחם מאיר מזווירציה","k":"בעל דברי צבי","b":"מחכמי וולברום, מיעכוב, קראקא. חתן ר משה שרגא בלוקובסקי. נספה בשואה. חיבר \"דברי צבי\" פיעטרקוב תרצב. ?? לא באוצר ??"},{"i":42511,"n":"קלוגמן, נפתלי מירושלים","b":"גבאי חברת תפארת בחורים (בזמן שכיהן שם ר יוסף שלום אלישיב), חתם-תשכו על שטר חוב של ר יוסף שלום אלישיב."},{"i":42512,"n":"קלוגר, אברהם בנימין מברוד","f":"שלמה (המהרשק)","k":"בעל אותות למועדים","bt":"תרא","bp":"ברודי","dt":"תרעו - כט חשון","b":"בספר אביו \"מלי דנזיקין\" כלל אביו כמה מחדושיו מגיל 7-10. חתן הגביר ר אברהם סטרימאר(=סטרימבר) מבלז (-בסרביה). סירב לשבת על מקום אביו בברודי בגלל גילו הצעיר. רב בזולקוא (והיה במחלוקת עם החסידים). חיבר \"אותות למועדים\" בודפשט תרעז. עסק כל ימיו בסידור והדפסת ספרי אביו. פרסם מאמרים ב\"אהל מועד\" - פודגורזע תרנח, \"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס, \"שערי תורה\" - וארשא תרסג. הספיד את ר שמואל בירנבוים בהיותו בדובנא-תרמז."},{"i":42513,"n":"קלוגר, אברהם צבי","f":"יוסף מגריינינג","dt":"תקצב - בערך","b":"רב בגריידינג על מקום אביו, בנו ר חיים דוד על מקומו אחריו."},{"i":42514,"n":"קלוגר, גדליה מלמברג","f":"יוסף מבוברקא","k":"בעל מנחת יוסף","b":"מחכמי למברג. חיבר \"מנחת יוסף\" למברג תרצה."},{"i":42515,"n":"קלוגר, דוד מדרוהוביטש","f":"צבי הירש מדרוהוביטש","b":"אמו נכדת הט\"ז, ונקרא על שמו. רב בדרוהוביטש. חתן ר יעקב אשכנז מירוסלב."},{"i":42516,"n":"קלוגר, זאב וולף מקראקא","b":"נגיד מחכמי קראקא. חתן ר משה הלברשטט מקשנוב."},{"i":42517,"n":"קלוגר, חיים דוד מגריידינג","f":"אברהם צבי מגריידינג","dt":"תרי - יד טבת","b":"רב בגריידינג על מקום אביו, בנו ר יצחק יהושע על מקומו אחריו."},{"i":42518,"n":"קלוגר, חיים יהודה מברוד","f":"שלמה (המהרש\"ק)","bt":"תקעב","bp":"ברודי","dt":"תריח","b":"מחכמי ברודי ומסייע לאביו ברבנות ובסידור כתביו. בתו שאשא מינדל נפטרה צעירה (ועל כך כותב מהרש\"ק בהקדמת ספרו \"נדרי זריזין\")."},{"i":42519,"n":"קלוגר, חיים מטשבין","f":"ישראל מטשבין","k":"בעל פרי חיים","bt":"תקפה","dt":"תרכט","b":"רב בטשבין על מקום אביו. בנו ר יוסף קלמן הוציא לאור את ספריו. חיבר \"פרי חיים\" פודגורזע תרס. ?? לא באוצר ??"},{"i":42520,"n":"קלוגר, יהודה אהרן מסטניסלב","f":"אברהם בנימין","k":"בעל תולדות שלמה","bt":"תרכט","bp":"ברודי","dt":"תרסו","b":"חתן הגביר ר יצחק רסוצקי מברדיטשוב. התישב בסטניסלב ועסק בתורה - סירב לרבנות. חלק מכתביו אבדו. חיבר \"תולדות שלמה\" למברג תרמח."},{"i":42521,"n":"קלוגר, יוסף בריש מפודגורזע","b":"חסיד צאנז בפודגורזע. בנו ר ישעיה מהדיר \"בעלי הנפש\" לראב\"ד, ור מנשה חתן רח\"י ירוחם מאלטשטט."},{"i":42522,"n":"קלוגר, יוסף מבוברקא","f":"יעקב מוישנה","b":"רב בבוברקא. חתן ר יעקב היילפרין מסוקוליבקה."},{"i":42523,"n":"קלוגר, יוסף מגריידינג","f":"דוד מדרוהוביטש","dt":"תקמט - כא חשון","b":"רב בגריידינג-תקכט, בנו ר אברהם צבי על מקומו אחריו (היה אביה של שושלת רבנים שנמשכה כ-170 שנה - עד השואה)."},{"i":42524,"n":"קלוגר, יוסף מגריידינג","f":"יצחק יהושע מגריידינג","bt":"תרי","dt":"תשג","b":"נכד ר משלם בעל \"בר ליואי\". תלמיד השו\"מ. רב בגריידינג-תרנח על מקום אביו (רבה האחרון של גריידינג - בני משפחתו ישבו שם ברבנות כ-170 שנה). נספה בשואה. חתן ר משה באבד ממיקוליניץ."},{"i":42525,"n":"קלוגר, יעקב מוישנה","f":"חיים דוד מגריידינג","b":"רב בוישנה-תריז."},{"i":42526,"n":"קלוגר, יעקב מלודז","f":"יהודה שלמה","b":"מו\"ץ בלודז-תרעח."},{"i":42527,"n":"קלוגר, יצחק יהושע מגריידינג","f":"חיים דוד מגריידינג","bt":"תקעט","dt":"תרסה","b":"נצר לעשרים דורות של רבנים. רב בגריידינג על מקום אביו, בנו ר יוסף על מקומו אחריו, הקים ישיבה ועמד בראשה. חתן ר משולם ישכר הורביץ מסטניסלב."},{"i":42528,"n":"קלוגר, ישעיה מגורליץ","f":"יוסף דב","b":"מחכמי גורליץ. השתתף ב\"הלבנון\"-תרפח. מו\"ל \"בעלי הנפש\" לראב\"ד - פיעטרקוב תרפז."},{"i":42529,"n":"קלוגר, ישראל מטשבין","f":"חיים מקשנוב","bt":"תקל","dt":"תקפו","b":"רב בטשבין."},{"i":42530,"n":"קלוגר, מאיר מקרקוביץ","f":"יצחק יהושע מגריידינג","bt":"תרכז","dt":"תשב","b":"רב בדוברומיל, גריידינג אצל אביו, קרקוביץ, בנו ר משולם על מקומו אחריו. חתן ר נפתלי הורביץ מדמביץ וי\"א חתן ר אלעזר קלונימוס בפרלשטין מדמביץ. נספה בשואה. פרסם מאמרים ב\"רבותינו שבגולה\" - פרשבורג תרעה."},{"i":42531,"n":"קלוגר, משלם","dt":"תשג","b":"רב בקראקוביץ"},{"i":42532,"n":"קלוגר, משלם ישכר מקראקא","f":"יוסף מגריידינג","k":"בעל מזון רוחני","bt":"תרם","dt":"תשב","b":"חתן ר אליעזר פסל מגורליץ. התגורר בקראקא וניהל את ביה\"ס תחכמוני. מנהיג המזרחי בעירו - רב ביהמ\"ד של המזרחי. היה מיועד לשבת על מקום אביו בגריידינג. נספה בשואה. חיבר \"מזון רוחני\" קראקא תרצז."},{"i":42533,"n":"קלוגר, שאול","f":"חיים דוד מגריידינג","b":"מחכמי דרוהוביטש-תרמה."},{"i":42534,"n":"קלוגר, שלמה (יעקב יוסף) מברוד","f":"יהודה אהרן מקומרוב","k":"המהרש\"ק","bt":"תקמה","dt":"תרכט - א תמוז","b":"מגדולי המשיבים בדורו. תלמיד ר מרדכי ראבין מזמושץ והמגיד מדובנא. חתן הנגיד ר חיים ויינרב מראווא, ובזיוו\"ש חתן ר אריה מרגליות מדובנא. רב בקוליקוב, יוזפוף, ברודי-כיובל שנים, היה במחלוקת עם תקיפי הקהל עם המשכילים ולעתים עם האב\"ד ר אלעזר לנדא - אך נחשב לאחד הגדולים בדורו. נסע לברדיטשוב בנוגע לשוחט והתעוררה מחלוקת גדולה סביב זה. עבר לברזן וחזר לברודי. התקרב לאדמור ר מאיר מפרימישלן. חיבר ספרים רבים וביניהם \"טוב טעם ודעת\" (טוט\"ד). הקים את ישיבת \"עץ חיים\" בברודי-תריא, והיתה כנראה הישיבה הראשונה בגליציה. פרסם מאמרים ב\"פליטת סופרים\" - וילנא תרכג, \"תבונה\" - ממל-קניגסברג תרכא."},{"i":42535,"n":"קלוגר, שלמה מאיר","f":"יוסף דוד מקראקא","dt":"תרצד","b":"חתן ר חיים יצחק ירוחם מאלטשטט."},{"i":42536,"n":"קלוגר, שלמה מברוד","f":"אברהם בנימין","k":"בעל שיח שלמה","bt":"תרלט","bp":"ברודי","dt":"תרצב","b":"חתן הגביר ר שמואל זנויל מאיסטריק. מחכמי איסטריק, ברח לוינה במלחמת העולם ה-I והציל חלק מכתבי אביו. נפטר ללא ילדים. חיבר \"שיח שלמה\" פוזוני תרעז."},{"i":42537,"n":"קלוגר, שלמה מטשעין","f":"מאיר מקרקוביץ","dt":"תש..","b":"מקורב לחסידות בלז ובובוב. חתן ר ליבל הוכשטיין. רב בטשעין. נספה בשואה."},{"i":42538,"n":"קלודניצקי, יצחק מדימער","f":"ברוך מרדכי","bt":"תרמו-טו","b":"תלמיד ר אליהו בן משה דב. רב בדימער-פלך קיוב-תרסו. נסמך מאת: ר דוד אירמינברג מברדיטשוב."},{"i":42539,"n":"קלודצקי, נחמן דוב מאליטא","bt":"תרמא","dt":"תרפו - שבט","b":"רב באליטא"},{"i":42540,"n":"קלוואן, יהושע מגלוואן וארה\"ב","f":"בנימין","bt":"תרמד","bp":"יאנישוק","b":"תלמיד ישיבת גרוזד אצל ר אהרן ואלקין, סלובודקא, נסמך מאת: ר רפאל שפירא, ר משה דנישבסקי, ר ברוך בר ליבוביץ. חתן ר אברהם שמואל סופר מזעזמיר. רב בזסקוביץ-פלך וילנא-תרסט, גילוואן-פלך קובנא-תרפא על מקום ר מנחם מנדל ליפשיץ בעל \"ברכת מנחם\", היגר לארה\"ב-תרפה וכיהן כרב בבורלינגטון-ורמונט, רב בוושינגטון. חבר אגודת הרבנים באמריקה, ממיסדי ישיבת \"בית יהודה\"."},{"i":42541,"n":"קלויבר, יצחק","b":"רב-שנת ר\"צ"},{"i":42542,"n":"קלויזנר ישראל","bt":"1905","dt":"ה'תשלז 1977","bk":[["קורות בית־העלמין הישן בוילנה",""],["תולדות הקהלה העברית בוילנה",""]]},{"i":42543,"n":"קלויזנר, אברהם מוינה","k":"בעל ספר המנהגים","dt":"קסז - אחרי","b":"מכונה מהרא\"ק. רב בוינה-קל, ניישטט-ליד וינה בזמן מהר\"מ הלוי הזקן, ר יעקל ור גרשון. חיבר הגהות והוספות לספר המנהגים של ר חיים פלטיאל. מתלמידיו: מהרי\"ל, ר איזיק טירנא. גיסו ר אהרן פלומלין. אשתו ובנו ר יונה שאול נהרגו בפרעות-קפא. ספרו נקרא גם \"מנהגי קלויזנר\"."},{"i":42544,"n":"קלויזנר, אליעזר מבוהמיה","dt":"רטו","b":"תלמיד בעל \"תרומת הדשן\" ונזכר שם. מחכמי הערעדש-בוהמיה. נהרג עק\"ה - כנראה רטו בגזירות הכומר פאסטריאנו."},{"i":42545,"n":"קלויזנר, אריה ליב","f":"זכריה מנדל מבלז","b":"נכד ר אריה ליב דער הויכער. בנו - ר יוסף מייסלינג ובוהאווי ולובלין."},{"i":42546,"n":"קלויזנר, אריה ליב מקראקא-הויכר","f":"זכריה מנדל (הנביא)","k":"ר ליב ר פישלס-תקוני","dt":"תלא - טו אייר","dp":"קראקא","b":"מכונה גם \"דער הויכער ר ליב\"(=הגבוה). אחיו של ר צבי הירש קלויזנר מלבוב. חתן ר אפרים פישל-מצאצאי המהרש\"ל. מו\"ץ בקראקא-תב, רב בוינה, פרמישלא, קראקא-תכד על מקום ר אברהם יהושע השל. הסכים על \"חלקת מחוקק\". בניו - ר אפרים פישל לודמיר, ר זכריה מנדל מבלז, ר יוסף מייטלינג בעל \"חותם השם\". חתניו ר זאב וולף בוכנר, ר יחזקאל יהושע פיבל תאומים מפרמישלא, ר שמואל מפיורדא בעל \"בית שמואל\" על השו\"ע. אחיו - ר צבי הירש מלבוב. (היו שהחליפו בינו לבין המהר\"ל - שהיה קרובו)"},{"i":42547,"n":"קלויזנר, אשר מבלז","f":"צבי הירש","b":"רב בבעלזא"},{"i":42548,"n":"קלויזנר, דוד טבלי מבריסק","f":"זכריה מנדל (הנביא)","k":"ר טעבלי בריסקר","b":"ר\"מ בבריסק. מחדושיו נדפס \"אסיפות יהודה\" לנכדו ר יוסף יהודה ליב בן ישראל איסר הלוי משרשוב. אחיו - ר אריה ליב קלויזנר (דער הויכער ר ליב) מקראקא, ר צבי הירש מלובלין."},{"i":42549,"n":"קלויזנר, זאב וולף מעקצין","bt":"תקכב - בערך","bp":"ראויטש","dt":"תרכב - י טבת","b":"רב בבוראראניק(=אבארניק)-תקסד, עקצין-ליד פוזנא-תקעא. בנו - ר צבי הירש בעל רץ למשנה. נפטר בגיל 100!"},{"i":42550,"n":"קלויזנר, זכריה מנדל מבלז -הננד","f":"אריה ליב הויכר מקראק","b":"אב\"ד בלז והגליל. בנו ר אריה ליב ונכדו ר יוסף אב\"ד ייסלינג ביחוב ולובלין."},{"i":42551,"n":"קלויזנר, זכריה מנדל מקראקא","f":"בנימין מפוזנא","k":"זכריה הנביא","dt":"תלב","dp":"ירושלים","b":"חתן ר בצלאל מוורמייזא וגיסו של המהר\"ל מפרג. מגדולי חכמי קראקא, נתקבל לנשיא א\"י, עלה לירושלים וקבלוהו כנשיא העדה. בניו: ר אריה ליב מוינה וקראקא (נפטר תלא) ונקרא \"דער הויכער ר ליב\", ר דוד טעבל רב בבריסק, ר צבי הירש אב\"ד לבוב ולובלין."},{"i":42552,"n":"קלויזנר, יהושע השל מלבוב","f":"צבי הירש מלבוב","b":"פרנס וראש הקהילה בלבוב. חבר בועד ארבע ארצות יחד עם אביו בלובלין-תלח. הסכים על תנ\"ך עם תרגום אשכנז עם אביו."},{"i":42553,"n":"קלויזנר, יוסף","f":"יהודה","k":"בעל הרעיון המשיחי","bt":"1874","bp":"אולקניק-פלך וילנא","dt":"1958","dp":"ירושלים","b":"הסטוריון וחוקר הספרות העברית. למד בישיבה מודרנית באודסה, אוני' היידלברג. פרסם מאמרים, ציר בקונגרס הציוני הראשון. עורך \"השלוח\", מרצה בישיבת אודסה-1907. עלה לארץ-1919, עורך האציקלופדיה העברית."},{"i":42554,"n":"קלויזנר, מרדכי מלוצקא","f":"צבי הירש מלבוב","b":"רב בלוצקא-תפ."},{"i":42555,"n":"קלויזנר, צבי הירש מלבוב ולובלי","f":"זכריה מנדל","k":"ר הירש ר מנדליש","dt":"תנא - ו-יז תשרי","dp":"לובלין","b":"למד עם שני חבריו - ר גרשון בעל \"עבודת הגרשוני\", ר מנחם מנדל אוירבך בן ר משלם זלמן פינהוף - בישיבת הב\"ח בקראקא, אצל ר יהושע בעל ה\"מגיני שלמה\", ואצל ר מנחם מנדל קרוכמל בעל \"צמח צדק\" (והזכירם בספרו) - והתישבו בקראקא. רב בלבוב-תוך העיר - ור יהודה יודל בן משה מלובלין היה אב\"ד חוץ לעיר, וברחו-תלג בזמן החורבן וחזרו, לובלין-תרמד על מקום ר נפתלי הירש חתן ר השל. ראש ועד ארבע ארצות בועד ירוסלב, הסכים על כמה ספרים. בניו: ר יהושע השל מלבוב, ר מרדכי מלוצקא, ר אשר מבלז. אחיו - ר אריה ליב פישלס מפרמישלא וקראקא."},{"i":42556,"n":"קלויזנר, צבי הירש מעקצין","f":"זאב וולף","k":"בעל רץ למשנה","b":"בנו של הרב של עוקצין-ליד פוזנא. חיבר \"רץ למשנה\" ברסלוי תריז, \"תא הרצים\" עם הסכמות המלבי\"ם, ור אליהו גוטמכר ועוד, \"כותל התא\" - בכת\"י."},{"i":42557,"n":"קלומיטי, ברוך מאזמיר","k":"בעל אבק דרכים","dt":"תקפה - ח אב","dp":"איזמיר","b":"נכד ר יעקב ן נאים בעל \"משכנות יעקב\". ראש ישיבת \"בית הלוי\" באיזמיר, חיבר \"אבק דרכים\""},{"i":42558,"n":"קלומיטי, ברוך מאזמיר","dt":"תקכח - כא אייר","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":42559,"n":"קלומיטי, יעקב מאזמיר","b":"חתנו - ר נסים חיים שלום מרגונטו."},{"i":42560,"n":"קלומיטי, יצחק מאזמיר","dt":"תמג - כה אב","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":42561,"n":"קלומיטי, ישעיה מאזמיר","b":"גביר מחכמי אזמיר-שנות ה-ת'."},{"i":42562,"n":"קלומיטי, משה מאזמיר","b":"נספד מאת - ר נסים חיים שלום מרגונטו-שנות ה-תק'."},{"i":42563,"n":"קלומיטי, משה מטבריה","dp":"טבריה","b":"מחכמי טבריה בזמן חידוש הישוב ע\"י ר חיים אבולעפיה-תק. חתם על כתב שליחות ר מסעוד בונאן-תקח."},{"i":42564,"n":"קלומיטי, נחמיה מיוון","f":"מנחם","k":"בעל מלחמת האמת","b":"מחכמי יוון-קעח. חיבר גם \"הנהגת הנפש\" בכת\"י."},{"i":42565,"n":"קלומיטי, שמואל מקושטא","b":"גביר מחכמי קושטא-ש', משורר. מחזיק ביד תלמידי חכמים."},{"i":42566,"n":"קלומיטי-אף נעים, יהודה מאזמיר","k":"בעל פירוש לתנ\"ך","b":"רב באזמיר. חיבר פירוש לתנ\"ך - כנזכר ב\"עין יוסף\"."},{"i":42567,"n":"קלומל, מאיר","f":"אברהם","bt":"1875","bp":"וידז","dt":"1936","dp":"תל אביב","b":"תלמיד ישיבות ליטא. למד באונ' ברלין, ביהמ\"ד לרבנים בברלין, עוזר לפרופ' אברהם ברלינר. התישב בוארשא ועסק בעסקנות צבורית ובעסקים, תורם, הצטיין כנואם, פעיל בג'וינט. ציר בקונגרס הציוני. מייסד הבנק המרכזי למוסדות אשראי. עלה לארץ-1933."},{"i":42568,"n":"קלונימוס איש רומי","dt":"ד'תתנו","dp":"וורמייזא","b":"עק\"ה,מגדולי הראשונים,בקי,מרביץ תורה ברומא"},{"i":42569,"n":"קלונימוס הזקן מבריסק","b":"רב בבריסק-שנת ש'"},{"i":42570,"n":"קלונימוס הזקן משפיירא-אשכנז","f":"יצחק","dt":"תתפו","b":"מגדולי הראשונים,פוסק,מקובל,מרביץ תורה באשפירא-ד'תתנ\"ו(הניצול היחיד מפרעות תתנ\"ו)"},{"i":42571,"n":"קלונימוס הכהן מואג-ביסטריץ","f":"דוד מטרענטשין","b":"חתן ר בנימין זאב עמריך מעיר חדש. רב בוואג-ביסטריץ-תקנ. בנו - ר דוד ביסטריץ ממילכדורף בעל \"בית דוד\"."},{"i":42572,"n":"קלונימוס מאויבן","b":"רב באויבן-ת\"כ"},{"i":42573,"n":"קלונימוס מבון-אשכנז","f":"רבינו יעקב מבונא","k":"רבינו קלונימוס מבונה","b":"מגדולי חכמי אשכנז,מרביץ תורה בבון-ד'תתק\"ל"},{"i":42574,"n":"קלונימוס מוילנא","f":"אברהם","b":"גביר בוילנא-תמד."},{"i":42575,"n":"קלונימוס מוילנא","f":"חיים","b":"דיין בוילנא, חתם-תקי עם היסו\"ד."},{"i":42576,"n":"קלונימוס מירושלים","f":"יעקב","k":"ר' קלונימוס בעל הנס","bp":"איטליה","dp":"ירושלים","b":"מקובל, הרב הראשון לעדת האשכנזים בירושלים-שח. נזכר בתשובת ר יוסף קארו שהיו לו שתי נשים. נקרא בעל הנס (החיה נוצרי שהעלילו שיהודים הרגוהו) ואולי הוא ר קלונימוס אחר. ראה גם: קלונימוס הברקשטן-חותנו של המהרש\"ל."},{"i":42577,"n":"קלונימוס מלוקה-איטליה","b":"מגדולי חכמי דורו,פייטן,מרביץ תורה בעיר לוקה שבלומברדיה(איטליה)-ד' תשס. רב ברומא. זקנו של ר נתן בעל הערוך. המלך קרלו השני - מלך צרפת - הביאו עם הגולים באיטליה לארץ אשכנז, ושיקם את חיי היהודים באשכנז. עליו ב\"עמק הבכא\" וב\"תולדות ר אלעזר הקליר\"."},{"i":42578,"n":"קלונימוס ממגנצא","k":"ר' קלונימוס הבחור","b":"מגדולי הראשונים,פייטן מובחר במגנצא,בעל קינות על גזירות תתנ\"ו"},{"i":42579,"n":"קלונימוס מנפולי","f":"קלונימוס","k":"בעל אבן בוחן","bt":"מו","dt":"פח","b":"גדול בתורה ומדעים ומקורב למלכות רב בנאפולי חיבר \"אבן בוחן\"."},{"i":42580,"n":"קלונימוס מסאסמקין","f":"פיבש","b":"רב בסאסמקין-תקפה."},{"i":42581,"n":"קלונימוס משפיירא","f":"יהודה","b":"פייטן באשכנז-ד'תתקכ, בן למשפחת פייטנים ידועה."},{"i":42582,"n":"קלונימוס סגל מוילנא ופרידבורג","f":"נפתלי","b":"דיין בוילנא, גלה-תטו ועבר לאשכנז, דיין בפרידבורג."},{"i":42583,"n":"קלונימוס סגל מפוזנא","f":"משה הקדוש","b":"דיין בפוזנא, חתם-תמא על תקנה בועד ירוסלב עם ר יהודה אברהם הלוי, ר יצחק כהנא מבריסק ופרמישלא ועוד."},{"i":42584,"n":"קלונימוס קלמן הברקשטן מאוסטרה","f":"ראה: הברקשטן, קלמן"},{"i":42585,"n":"קלונימוס קלמן מווידאמע","bt":"תריג","dt":"תרפח - י סיון","b":"רב בווידאמע"},{"i":42586,"n":"קלונימוס קלמן מוילנא","f":"ישכר בר-אחי הגר\"א","dt":"תקפב - ג כסלו","b":"חתן ר צבי יעקב מפודקמין. מגדולי חכמי וילנא-תקע."},{"i":42587,"n":"קלונימוס קלמן מלנצהוט","b":"חתן ר מנחם מנדל מרימנוב. נזכר באגרת ר יחזקאל מקרלסבורג (דעש)."},{"i":42588,"n":"קלונימוס קלמן מפפשטיץ","f":"הלל","b":"מחכמי פפשטיץ-תמג."},{"i":42589,"n":"קלונימוס קלמן מקראקא","f":"יונה קלונימוס קלמן","b":"רב בקרקא-שנת ש'"},{"i":42590,"n":"קלונימוס-תלמיד הרמבם","k":"בעל מסוה (משרת) משה","b":"תלמיד הרמב\"ם. חיבר \"מסוה משה\" להגן על מורה נבוכים - בכת\"י."},{"i":42591,"n":"קלונסקי, לוי אליעזר מחברון","b":"מראשי הקהלה בחברון-תרעד."},{"i":42592,"n":"קלופט יואל","bt":"1906","dt":"ה'תשמה 1985","bk":[["דעת יואל",""]]},{"i":42593,"n":"קלזון, שלמה","bt":"1896","bp":"קובנא","dt":"1945","dp":"מחנה לנדסהוט","b":"פעיל ב\"צעירי ציון\", ברשת הבנקים העממיים היהודיים בליטא, ערך מחקר על הכלכלה היהודית בליטא, בזמן השואה היה ממונה על גידולי הירקות בגיטו סלובודקה. נספה בשואה."},{"i":42594,"n":"קלטמן, יעקב צבי מויטעש","b":"תלמיד הכת\"ס. רב בויטעש(=ורטעש), נאדי-לעטא-תריז, וחתנו ר חיים גוטסמן על מקומו אחריו. נזכר בכת\"ס ובשו\"ת מהר\"ם שיק."},{"i":42595,"n":"קלטנובסקי, אברהם בנימין","f":"יוסף","k":"בעל אהבת אברהם","bt":"תרכא","bp":"וערישוב-פלך קאליש","b":"נכד-אבי אביו ר יעקב-חתנו של ר בנימין ביניש מקעמפנא, ונכד-אבי אמו ר שלמה הרופא. תלמיד ר אברהם בנימין מוערישוב. רב בווידאוו(=ויאדאווא)-פלך פיעטרקוב-תרנו. נסמך מאת בעל \"נפש חיה\". בנו: ר יצחק מאיר. הניח חבורים בכת\"י."},{"i":42596,"n":"קלטנובסקי, יצחק מאיר מסטרעצוב","f":"אברהם בנימין","b":"חתן הגביר ר פרץ וישנבסקי מקלישצוב. מו\"צ בסטערצוב-תרע."},{"i":42597,"n":"קלטר, דוד הכהן מאלטשטט","b":"רב באלטשטט (סמבור). בנו ר משה רב לצדו-תרל."},{"i":42598,"n":"קלי, יעקב","f":"חננאל","b":"נזכר בשו\"ת הרא\"ש. מאמר לתולדותיו ב\"ירושלים\" - ירושלים תרמב-תרעט - מאת ד\"ר אריה טויבר."},{"i":42599,"n":"קליבנוב, חיים מונדזיגולה","f":"נחום יהודה","dt":"תש","b":"רב בז'יים-ליטא, רבה האחרון של ונדזיגולה. נספה בשואה."},{"i":42600,"n":"קליבנוב, מרדכי ממינסק","f":"ר\"י","b":"גביר במינסק-תר בערך."},{"i":42601,"n":"קליבניר, משה ליב הכהן","f":"יוסף חיים","bt":"תריט","b":"מצאצאי החכם צבי, ובעל \"תבואות שור\". רב בברעסטיצקי-ווהלין-תרמא."},{"i":42602,"n":"קליבנסקי, יהודה ליב מקובנא","f":"יחזקאל","bt":"תקעז","bp":"קובנא","dt":"תרמט - כד אב","dp":"וילנא","b":"נכד ר שמואל מראגולה וירושלים. גביר מראשי קהילת קובנא. מייסד ביהמ\"ד החדש, ובית העלמין. פעל בענינים רבים יחד עם ר גדליה בכרך למען יהודי קובנא. חתנו - הגביר ר מרדכי גרודון מוילנא."},{"i":42603,"n":"קליבנסקי, יהושע מזוסקוביץ","f":"בנימין","bt":"תרמג","b":"רב בזאסקאוויץ-פלך וילנא-תרסט."},{"i":42604,"n":"קליבנסקי, יעקב","f":"פנחס אושפיז","bt":"1888","bp":"פילוישוק","dt":"1950","dp":"תל אביב","b":"תלמיד ישיבת סלובודקה. עלה לארץ-1910, מורה במקומות שונים, ועורך \"הד החנוך\"."},{"i":42605,"n":"קליג, דב אריה מריינזוב","f":"שמעון הלוי","k":"המתמיד מהרובישוב","bt":"תרמה","bp":"הרובישוב","dt":"תש","b":"תלמיד בבלז ואחר כך בלומזה. תלמיד ר בנימין פרלמן אחיו של ה\"גדול ממינסק\", למד בנוברדוק והיה מקורב ל\"ערוך השלחן\" . חתן ר בצלאל מלודמיר ובזיוו\"ש חתן ר יהודה גניוויש ממשוינא. התישב בקובנה, רב בפילווישקי, רייזנוב, למברג. חיבר \"לב אדם\" קראקא תרפד, \"שמירת שבת\"| למברג תרץ, ועוד.","bk":[["לב אריה",""]]},{"i":42606,"n":"קליג, משה הלוי מהורבשוב","f":"שמחה בונם הלוי","k":"בעל הלכה למשה-תרנט","bt":"תרח","bp":"הורבשוב","b":"כונה בילדותו \"משה'לע מתמיד\". תלמיד ר\"י אטינגר בלבוב. מו\"ץ בהורבשוב בחיי אביו ועל מקומו אחריו-תרלח. חיבר גם \"תקון עולם\" תרסה, ועוד חבורים בכת\"י."},{"i":42607,"n":"קליגסברג, שמואל יעקב קופיל","bt":"תריח","dt":"תרצה","b":"מצאצאי החוזה מלובלין. מגדולי רבני פולין. רב בקאלושין, מודזיץ, ועוד, לובלין-תרע, קאלושין והגליל-תרעא. חתנו ר ישראל ניסן קופרשטוך ממאקובה-גיסו של ר יחיאל האדמור מאלכסנדר."},{"i":42608,"n":"קליווניר, יוסף חיים","b":"רב-שנת תר\"כ"},{"i":42609,"n":"קליין, אברהם אבא","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":42610,"n":"קליין, אברהם יצחק מטוקאי","b":"דומ\"ץ בטוקאי-תר\"ס"},{"i":42611,"n":"קליין, אברהם יצחק מנירנברג","f":"שמואל מדונא פלדוואר","k":"בעל נחלת אברהם","bt":"תרלה","bp":"דונא-פאלדוואר","dt":"תשכא - כח טבת","dp":"בני ברק","b":"תלמיד השב\"ס, ור משה כץ מנייטרא. חתן ר אלעזר מינץ מקמפנא. רב בהונגריה, נירנברג-תרסט. עלה לארץ-תרצט וכיהן כרב בחיפה. חתנו - ר יוסף אברהם וולף מייסד הסמינר בבני ברק."},{"i":42612,"n":"קליין, אברהם מטארנאליא","f":"שמואל מנחם","bt":"תרסח","bp":"קלויזנבורג","dt":"תשמה - יג תמוז","dp":"ירושלים","b":"תלמיד הדעת סופר, רי\"צ דושינסקי בחוסט, ועוד. נסמך מאת: ר עקיבא סופר, ר מנחם ברודי מקאלוב, ר דוד שליסל, ר מאיר זאב זלצר, ר מנחם וייס. חתן ר יקותיאל ליכטנשטין מבאלקאן. רב ביאלשווא ורעצע-תרצז, ניצל מהשואה ואחריה רב בטארנאליא-תשה, ניו יורק-תשז ועמד בראש המשרד האמריקאי של ישיבת פרשבורג בירושלים. עלה לירושלים."},{"i":42613,"n":"קליין, אברהם צבי מסילאש","f":"יוסף","k":"בעל בארות אברהם","bt":"תריג","bp":"דיורקעני","dt":"תרפז - יג תשרי","dp":"סילאש באלהאש","b":"תלמיד הכת\"ס, ור אברהם קרפלס מגירבא. חתן ר משה הרצפלד מסילאש. רב בסילאש(=בלהאש)-תרלד."},{"i":42614,"n":"קליין, אלחנן מסולנוק","bp":"בוהמיה","b":"תלמיד ישיבות הונגריה. רבה הראשון של הקהילה הניאולוגית בסולנוק-מחוז יאס נאגי קון סולונק. פרש בגלל מחלוקת."},{"i":42615,"n":"קליין, אליהו מהאלמין","f":"שמואל שמלקא מחוסט","bt":"תריב","bp":"חוסט","dt":"תרפו-ח - א שבט","dp":"האלמין","b":"תלמיד הכת\"ס. חתן ר שלמה זלמן אולמן ממאקווא בעל \"יריעות שלמה\". רב בסעליש, רב וראש ישיבה בהאלמין-תרלד על מקום אחיו ר שלום במשך כ-54 שנה, ובנו ר יעקב שלום על מקומו אחריו. מתורתו ב\"אליהו ויוסף\" בתוך \"עיר חנוך\" ירושלים תשמב. בניו גם: ר שלמה זלמן מנאווא. חתניו: ר יוסף לעווי ממאנדאק, ר איזיק הברפלד מסאבאטיטש. מתורתו בספר אביו \"צרור החיים\", הניח חדושים ושו\"ת - בכת\"י."},{"i":42616,"n":"קליין, אליהו מקלויזנבורג","f":"שלמה זלמן מסילג'צה","b":"חתן ר אהרן צבי קלר משאמקוט. פעיל ציוני. רב בקהלה הניאולוגית בקלויזנבורג-תרץ. ניצל מהשואה, ואחריה עלה לארץ. נזכר בספר גיסו ר יוסף צבי הלפרין-הלפרט \"צרי לנפש\" ירושלים תשלט. פרסם מאמרים ב\"אהל שם\" - רומניה תשב - תשה."},{"i":42617,"n":"קליין, אליעזר חיים","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":42618,"n":"קליין, אפרים פישל מדווה","f":"נחמן מזענטא","b":"מצאצאי ר אורי פיבל מדובנקא בעל \"אור החכמה\" - שבנו ר משה התישב בזענטא והפיץ חסידות בהונגריה. תלמיד דודו ר מנחם סופר במארוש-ואשארהי, והתישב שם. רב בדווה-תרץ. ניצל מהשואה ואחריה רב במארוש-ואשארהי. עלה לירושלים. הו\"ל ספר חותנו \"מנחם משיב\" ירושלים תשלג, עם הקדמה והערות. בנו ר שמחה בונם קליין - עסקן חרדי בירושלים."},{"i":42619,"n":"קליין, אפרים פישל מדעווא","dp":"ירושלים","b":"חתן ר מנחם סופר ממאראש-ואשארהעלי. ניצל מהשואה. רב במאראש-ואשארהעלי על מקום חותנו - אחרי השואה והיה דיין בבית הדין להתרת עגונות ברומניה. עלה לירושלים."},{"i":42620,"n":"קליין, באלא מיאס-באראני","dt":"תשד","b":"רבה הניאולוגי האחרון של יאס-באראני. חיבר מאמר על מלכת שבא באגדה-1933. נספה בשואה."},{"i":42621,"n":"קליין, ברוך מאיר מניו יורק","k":"בעל נבואת מרדכי","bt":"תרלג","bp":"קרולה","dt":"תרצב - א כסלו","dp":"ניו יורק","b":"תלמיד ר מאיר פרלס בקרולה, ור אליעזר זוסמן סופר בהאלאש. חסיד ר מרדכי לייפר מנדבורנא. התישב בדברצין, בודפשט. היגר לארה\"ב-תרע וכיהן כרב בניו יורק. חיבר גם \"שאלו שלום ירושלים\" נ\"י תרעח."},{"i":42622,"n":"קליין, ג'יולא מבודפשט","k":"בעל ליקוטים בתורת הנ","b":"רבה הניאולוגי של סיגט-וואר, בודה-1887. חיבר \"לקוטים בתורת הנאום\". תרגם להונגרית את מסכת ברכות והיה מנהל ביה\"ס היהודי."},{"i":42623,"n":"קליין, דב בר מאויהל","f":"משה יעקב מניר-באטור","bt":"תרן","bp":"ניר-באטור","dt":"תשד - טו סיון","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור יהודה גרינולד מסטמר ור מרדכי יהודה ליב מהעדילא-מאדע. חתן ר זאב וולף כהנא מטשארנא. סייע לחותנו בניהול הישיבה, רב בטשארנא-תרפה. אויהל-תרצד. נספה בשואה. בנו ר מרדכי יצחק קליין מירושלים - תלמיד הדעת סופר."},{"i":42624,"n":"קליין, דב בר מהאלמין","f":"יעקב שלום מהאלמין","dt":"תשד","b":"חתן ר יצחק רוזנברג מסטמר. דיין בהאלמין-תרפח. הו\"ל ספר זקנו ר משה הרש פוקס \"יד רמה\" - גרוסורדין תש. נספה בשואה."},{"i":42625,"n":"קליין, דב בר מוינה","b":"תלמיד השב\"ס. מחכמי וינה-תרסט."},{"i":42626,"n":"קליין, דב מטשורנא","dt":"תשד","b":"דיין בטשארנא,רב באוהעל-תרצ\"ג"},{"i":42627,"n":"קליין, דוד מאויהל","b":"רב באויהל."},{"i":42628,"n":"קליין, דוד מגרוס וילייקא","dt":"תשג","b":"רב בגרוס-וילייקא"},{"i":42629,"n":"קליין, דוד מדובאווא","dt":"תשד","b":"רב בדובאווא"},{"i":42630,"n":"קליין, דוד ממונקטש","k":"בעל בית ארזים","r":"תלמיד בעל המנחת אלעזר","dt":"תשל - טו כסלו","b":"מגדולי מונקאטש,רב בארה\"ב,עלה לבני ברק,ירושלים","bk":[["בית ארזים - או\"ח",""],["פשיטי דספרא - שו\"ת חת\"ס",""],["קריאת ספר - קריאת התורה",""]]},{"i":42631,"n":"קליין, זאב צבי הכהן מאראטשקא","dt":"תרכט - בערך","b":"תלמיד החת\"ס. מחכמי באראטשקא-תרח."},{"i":42632,"n":"קליין, זאב צבי מאיזנשטט","f":"זכריה הכהן משאלא","k":"בעל חכמה עם נחלה","bt":"תרם","bp":"שאלא-סלובקיה","dt":"תשטו - ו-ז ניסן","dp":"ירושלים","b":"תלמיד השב\"ס, ור כלב פיבל שלינגר מטאפליטשן, ור שלמה זלמן ברייער מפפד\"מ ובעל תואר ד\"ר משם. חתן ר בן ציון וזעל (=ויזל) מברשוב וטורדה. רב במיינץ-תרסד, ברשוב(=קראנשטאד?)-תרסה על מקום חותנו, איזנשטט-תרעא, ברלין-תרפה. בזיוו\"ש חתן ר מיכאל לוי מלונדון - חתנו של ר שמשון ב\"ר רפאל הירש. עבר לארגנטינה-תרצח וכיהן כרב בבואנוס איירס. חיבר גם \"אורייתא בגלותא\" בואנוס איירס תשב. חיבר גם בגרמנית. פרסם מאמרים ב\"המגיד\" - סטמר תרפח, \"עטרת צבי\" - ירושלים תשא."},{"i":42633,"n":"קליין, זונדל מסיגט","bp":"ליבוי-קורלנד","dt":"תרעז","b":"חסיד בלז. מגיד בסיגט. חתנו היה ר משה שוורץ נאמן ביתם של רבני סיגט."},{"i":42634,"n":"קליין, זכריה הכהן משאלא","f":"זאב צבי מבאראטשקא","b":"חתן ר יצחק וייס משאלא."},{"i":42635,"n":"קליין, זלמן חיים מניו יורק","b":"פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":42636,"n":"קליין, זנוויל סגל","b":"תלמיד הכתב סופר"},{"i":42637,"n":"קליין, חיים אהרן יעקב ממארגרטן","b":"פרסם מאמרים ב\"קבוצי בחורים\" - מארגרטן תרצג."},{"i":42638,"n":"קליין, חיים צבי מקלינורדין","bt":"תקצה","dt":"תרעג - כה אלול","b":"רב בפדיוורנק,עבר לקליינוורדיין"},{"i":42639,"n":"קליין, יהודה אריה מבודפשט","f":"פנחס מאירשא","k":"בעל קול יהודה","bt":"תרמא","bp":"אירשא","dt":"תשמא - יא כסלו","dp":"ירושלים","b":"תלמיד השב\"ס, ור יוסף ליב סופר מפאקש. חתן ר צבי בלאס מטיסא-פירעד. מחנך ורב בבודפשט-תרעו. ניצל מהשואה. עלה לירושלים-תשו ולימד בבימ\"ד \"אור חיים\"."},{"i":42640,"n":"קליין, יהושע אריה הלוי מבודפשט","b":"דיין בבודפשט, חתם-תשיא עם ר עמרם יונגרייז."},{"i":42641,"n":"קליין, יוסף יחיאל צבי מפאקש","b":"רב בסעמניץ,פאקש-תק\"ס,שאמרע"},{"i":42642,"n":"קליין, יוסף מסערדאוהל","b":"רב בסערדאוהל."},{"i":42643,"n":"קליין, יחיאל מיכל מסאקאס","f":"יהודה","dt":"תרמו - יד אייר","dp":"קראלי","b":"רב בסאקאס וגליל ערדאד-ליד סטמר - בשנות ה'תרך-תרל"},{"i":42644,"n":"קליין, יעקב מטעטש ובילקא","f":"שמואל שמלקא קליין","b":"רב בטעטש, בילקא-ליד סעליש-תרכ. נפטר בחיי אביו."},{"i":42645,"n":"קליין, יעקב מנייטרא","b":"חתן ר מאיר לאשיץ מנייטרא. גיסם של ר אברהם פריישטט מקאמארן, ור אברהם ליטש רוזנבוים מנייטרא ופרשבורג.."},{"i":42646,"n":"קליין, יעקב מקלויזנבורג","b":"רב בקהילה הניאולוגית (קונגרסאית) בקלויזנבורג-1888."},{"i":42647,"n":"קליין, יעקב מקלויזנבורג","k":"בעל הציונות - תרפא","bt":"תרמג","bp":"מיהאלוביץ","dt":"תשיד - יד אד\"א","b":"תלמיד ר אליעזר דייטש בבוניהאד(=בניהאד). גביר מחכמי הוניאד ומראשי הציונים שם ועמד בראש הקהלה. בעל ספריה עשירה, עבר לקלויזנבורג והיה מנהיג המחנה הציוני דתי בטרנסילבניה. ניצל מהשואה ועלה לארץ-תשד והתישב בתל אביב. חלק גדול מספרייתו נתרם לספריית מוסד הרב קוק. חיבר גם \"יסודות מתימטים בתלמוד\", ו\"שטית הפלפול בתלמוד\" - תרפג."},{"i":42648,"n":"קליין, יעקב שלום מהאלמין","f":"אליהו מהאלמין","bt":"תרלז","bp":"האלמין","dt":"תשד","b":"תלמיד וחתן ר משה הרש פוקס מגרוסורדין. דיין בגרוסורדין אצל חותנו ורב חברת \"מחזיקי הדת\". רב בהאלמין-תרפח על מקום אביו וראש ישיבה. נספה בשואה. מתורתו ב\"וילקט יוסף\"."},{"i":42649,"n":"קליין, יצחק מסטמר","f":"ישראל מסטמר","k":"בעל זכרון לישראל-תרע","bt":"תרכא","bp":"טאב","dt":"תש..","b":"תלמיד השב\"ס, ור אליעזר זוסמן סופר מפאקש. חתן ר חיים פרידריך מטורץ. חכם בטאב-תרנה, סטמר (בקהילת סטאטוס קווא - והיה במחלוקת על כך עם חבריו הרבנים)-תרסב. נספה בשואה. עורך כתבי העת \"אהל יצחק\"-תרסג, \"המגיד\". בנו ר מנחם מנדל - רב בטורונטו. פרסם מאמרים ב\"הלבנון\" - סטמר תרפח, \"מגד ירחים\" - סיגט תרנח, \"המגיד\" - סטמר תרפח."},{"i":42650,"n":"קליין, יקותיאל מהאלנדייל","f":"שמואל מנחם מטשטשוביץ","b":"תלמיד הדעת סופר. רב בהאלנדייל."},{"i":42651,"n":"קליין, יקותיאל מירושלים","f":"יצחק","bp":"ירושלים","b":"מאנשי החברא קדישא בהר הזיתים בירושלים."},{"i":42652,"n":"קליין, ישראל חיים ממינסק","f":"מנחם מנדל","b":"מחכמי מינסק, הסכים על \"לוית חן\" לר חיים אביעזר מורגנשטרן."},{"i":42653,"n":"קליין, ישראל מניו יורק","f":"חיים צבי קליין","b":"רב בניו יורק-תר\"פ"},{"i":42654,"n":"קליין, ישראל משה מגרוסורדין","dt":"תרנד - ל ניסן","b":"תלמיד החת\"ס. דיין בגרוסורדין אצל ר יצחק אהרן לנדסברג, ראב\"ד בגרוסורדין."},{"i":42655,"n":"קליין, ישראל שמואל מפיעשאבאני","b":"רב בפיזעשאבאני-תר\"פ"},{"i":42656,"n":"קליין, מאיר מאויהל","k":"בעל תולדות שמואל","dt":"תשד","b":"בקי,מרביץ תורה באויהעל(=ערלוי)."},{"i":42657,"n":"קליין, מאיר ממארגרטן","f":"אליהו מהאלמין","dt":"תרף - יא תשרי","b":"מחכמי מארגרטן. מתורתו ב\"יריעות שלמה\" לזקנו ר שלמה זלמן אולמן ממאקווא."},{"i":42658,"n":"קליין, מאיר שרגא הכהן מבודפשט","f":"זכריה משאלא","dt":"תשיג","dp":"ירושלים","b":"תלמיד השב\"ס, ור יוסף צבי דושינסקי מחוסט. חתן ר ברוך דומא משארוואר. רב בבודפשט - ראש חברת ש\"ס-תרעז, עלה לירושלים והיה חבר בהנהלת העדה החרדית."},{"i":42659,"n":"קליין, מנחם מנדל מבודפשט","f":"שרגא יהודה פיבל","k":"בעל מלאה ברכת","bt":"תרלב","bp":"פרשבורג","dt":"תש - טו תמוז","dp":"בודפשט","b":"תלמיד השב\"ס. חתן ר משה כץ מנייטרא. מחכמי נירעדהאזא-תרסח, בודפשט."},{"i":42660,"n":"קליין, מרדכי דב מוינה","f":"שמואל","k":"בעל אמרי נועם-תרמג","dt":"תרמז - אחרי","b":"דיין בקלויזנבורג-תרי, וינה-תרכג רב בביהכ\"נ שיף."},{"i":42661,"n":"קליין, מרדכי ליב מקראקא","f":"קלונימוס קלמן מזבנא","k":"בעל אמרי יהודה","b":"חתן ר דוד טעבל יפה מקראקא. רב בקראקא על מקום חותנו. חיבר \"אמרי יהודה\" קראקא תרסב."},{"i":42662,"n":"קליין, מרדכי מדברצין","f":"משה","dp":"דברצין","b":"תלמיד הכת\"ס. חתן ר יצחק פישר מדברצין, ועבר לשם. רב בדברצין."},{"i":42663,"n":"קליין, משה מגרוסורדין","f":"אליהו מהאלמין","k":"בעל ויקהל משה","bt":"תרם","dt":"תשד - ז סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, ור משה צבי פוקס מגרוסורדין. חתן ר דוד פרידמן מצעהלים. דיין בצעהלים לצד חותנו. רב בראטה(=רעטהע)-תרעא וראש ישיבה, רב בביהמ\"ד של משפחת אולמן בגרוסורדין-תרעח, וחתנו ר שמואל זאב גולדמן בעל \"כנסת ישראל\" על מקומו אחריו. דודו הגביר ר ישכר אולמן ציוה 60000 כתר לקק\"ל ומהם ינתן שכר לרב של משפחת אולמן שילמד שיעורי תורה יומיים בשבוע לבני המשפחה - ונבחר ר משה אחיינו. חיבר \"זכרון שי\"."},{"i":42664,"n":"קליין, משה מוילייקה","dt":"תשד","b":"רב בווילייקה"},{"i":42665,"n":"קליין, משה ממונקטש","b":"חתן ר ר יקותיאל יהודה גרינוולד מיארע. מחכמי מונקאטש."},{"i":42666,"n":"קליין, משה מניו יורק","f":"שלמה זלמן מסילאדי","dt":"תשי","dp":"ניו יורק","b":"תלמיד השב\"ס. חתן לבית ינוביץ מזשיבא, ועבר לשם. עבר לניו יורק וכיהן שם כרב."},{"i":42667,"n":"קליין, משה מסילאדי-טשעה","f":"שמואל שמלקא קליין","dt":"תרעא","b":"רב בס' טשעה"},{"i":42668,"n":"קליין, משה מסילאדי-טשעה","f":"שמואל שמלקא מבאלקאן","bt":"תרג","bp":"באלקן","dt":"תרם - טז אדר","dp":"סילאדי-טשעה","b":"בגיל 10 נשלח עם חסידים לבקר את ה\"דברי חיים\" בצאנז ואמר פלפול חריף לפני הרב. תלמיד \"קול אריה\" במאד ור ירמיה לעוו באויהל, הכת\"ס, ור אברהם יהודה שוורץ מעדילא. חתן הגביר ר מנחם מנדל דייטש מאפראד - שהיה מחותנו של הכת\"ס. רב בסעליש-תרך לצד אביו, נאפראד-תרכג לצד חותנו, רבה הראשון של סילאדי-טשעה-תרכח, ובנו ר שלמה זלמן על מקומו אחריו."},{"i":42669,"n":"קליין, משה פרץ מקויל","dt":"תשג","b":"רב בקויל(=קאלי). פרסם מאמרים ב\"הלבנון\" - סטמר תרפח, \"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":42670,"n":"קליין, נפתלי יואל מארה\"ב","b":"רב בבראונזויק-ארה\"ב. פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":42671,"n":"קליין, עזריאל ליב הכהן מנייטרא","f":"זאב צבי מבארטשקא","b":"תלמיד הכת\"ס, ור חזקיה פיבל פלויט משוראן. רב בנייטרא. מחדושיו בספר בן אחיו \"חכמה עם נחלה\"."},{"i":42672,"n":"קליין, עקיבא מאיזנשטט","f":"זכריה הכהן משאלא","bt":"תרמג","dt":"תרצא - כב כסלו","dp":"איזנשטט","b":"תלמיד השב\"ס, ור משה צבי פוקס מגרוסורדין. חתן ר משה שמואל גלזנר מקלויזנבורג ועבר לשם. רב במיינץ, בעקעש-טשאבא-תרעב, איזנשטט-תרפו, וחתנו ר מרדכי יפה-שלזינגר על מקומו אחריו. (באוצר הרבנים תאריך פטירתו - תרפו)."},{"i":42673,"n":"קליין, עקיבא מנייטרא","f":"יעקב מנייטרא","bp":"נייטרא","dt":"תרמו - יט סיון","b":"תלמיד הכת\"ס. חתן ר בנימין בונם פשקוב מסערדאוהל. גביר מחכמי נייטרא, ומלמד לתלמידים."},{"i":42674,"n":"קליין, פישל מדיווא","b":"מו\"ץ בדיווא-תרפ.. בערך, יחד עם ר שמואל דוד היימן."},{"i":42675,"n":"קליין, פנחס דוד מבוקין","f":"זאב מאבראהאם","bp":"אבראהאם","dt":"תרלד - ז כסלו","dp":"ירושלים","b":"תלמיד החת\"ס. חתן ר מאיר אברהם מטשאבא. רב בבוקין. עלה לירושלים-תרכו."},{"i":42676,"n":"קליין, פנחס חיים מסעליש","f":"שמואל שמלקא מסעליש","dt":"תרפג - ג ניסן","dp":"סעליש","b":"תלמיד הכת\"ס. חתן ר ישראל רויז מסעליש. רב בטיסא-אוילאק, סעליש-תרלה על מקום אביו ובנו ר שלמה ישראל על מקומו אחריו, חתנו ר יוסף נחמיה קורניצר על מקומו אחריו, חתנו - ר נח יעקב דייטש - ר\"מ בסעליש."},{"i":42677,"n":"קליין, פנחס מאירשא","f":"חיים צבי","dt":"תרעו - כד סיון","dp":"אירשא","b":"חתן ר יהודה מייזנר מויינערן. רב באירשא-תרמב."},{"i":42678,"n":"קליין, פנחס מראדזין","b":"תלמיד בישיבת אוטואצק. פרסם מאמרים ב\"התמים\" - וארשא תרצה - קובץ חסידי חב\"ד."},{"i":42679,"n":"קליין, פרץ מאונגריש בראד","b":"תלמיד החת\"ס. גיסו של ר חיים זינגר מאונגריש-בראד. נאמן הקהלה באונגריש-בראד, מנהל שרביט העדה-תריט."},{"i":42680,"n":"קליין, פרץ מטורקא","b":"רב בטורקא-תרסח."},{"i":42681,"n":"קליין, צבי הירש מאויוארוש","b":"דומ\"צ באויווארוש-תר\"כ"},{"i":42682,"n":"קליין, ראובן חיים מדוויטקוף","f":"בנימין אליעזר אונגר","k":"בעל שנות חיים","bt":"תקפו","bp":"קראקא","dt":"תרלג - כב טבת","dp":"וינה","b":"נכד ר יעקב ואלבראם. משפחת אביו אונגר-אורבך, נתייתם בילדותו וגדל אצל משפחה בשם קליין במונקטש - ומכאן שמו. תלמיד החת\"ס, ור מאיר א\"ש מאונגוואר ובנו ר מנחם א\"ש וגדל בביתו. חתן ר צבי דב מגורודנה (ליד מונקטש). רב גליל דוויטקוף(=דוויטקיוו)-ליד מונקטש. נכדו - ר ישראל אפרים פישל סופר ממונקטש (שהיה גם נכד הרב מנאנאש)."},{"i":42683,"n":"קליין, ראובן חיים מסנינא","f":"צבי דוב","k":"בעל מטה ראובן","dt":"תשד","b":"רב בסאנינא-תרעב. פרסם מאמרים ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":42684,"n":"קליין, ש\"ז מדירנאך-צרפת","b":"רב בדירנאך-צרפת. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":42685,"n":"קליין, שלום מדאראג","b":"חתן ר יצחק נאנאשער. בנו - ר מיכאל."},{"i":42686,"n":"קליין, שלום מהאלמין","f":"שמואל שמלקא מבאלקאן","dt":"תרלד","b":"תלמיד ר מאיר א\"ש באונגוואר. חתן הגביר ר הערצקא מניר-מאד. רב בהאלמין-תרלא. נפטר בחיי אביו, אחיו ר אליהו על מקומו אחריו. (באוצר הרבנים תאריך פטירתו תרפד)."},{"i":42687,"n":"קליין, שלמה הכהן מזענטא","f":"גרשון יהודה ליב","k":"בעל לקוטי שלמה","bt":"תקצג","dt":"תרס - טז אד\"ב","dp":"זענטא","b":"תלמיד הכת\"ס, ור ליביש האן מדאביטשוי. חתן ר יואל אונגר מפאקש ועבר לשם. רב בפאקש-תריט, זענטא-תרכה. (באוצר מופיע תאריך פטירה תרפט) פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה.","bk":[["לקוטי שלמה","מפרשי רמב\"ם"]]},{"i":42688,"n":"קליין, שלמה זאב מקלמאר","b":"רב בקאלמאר-תרי. פרסם מאמרים ב\"כבוד הלבנון\" - ירושלים-פאריס תרכג-תרמב."},{"i":42689,"n":"קליין, שלמה זלמן מגאווע","f":"אליהו מהאלמין","bt":"תרכט או תרלה","dt":"תרעג - יא שבט","b":"נכד ר שלמה זלמן אולמן בעל \"יריעות שלמה\". תלמיד השב\"ס, ור משה צבי פוקס מגרוסורדין. רב בזענטא-תרנט, גאווא-תרסד וחתנו ר יצחק טיגרמן על מקומו אחריו. נסמך מאת: השב\"ס. הו\"ל ספר זקנו \"יריעות שלמה\" עם הקדמה ממנו."},{"i":42690,"n":"קליין, שלמה זלמן מסילאג' צ'ה","f":"אלעזר","k":"בעל זכרון שלמה-תשטו","bt":"תרל","bp":"סטמר","b":"תלמיד ר שלמה זלמן ארנרייך, ואצל בעל \"ערוגת הבשם\". התישב בכפר באסשט-ליד סילאג' טשאה (צ'ה)(=סעליש), ועבר לסילאג' צ'ה. נספה בשואה. בנו ר אלעזר דיין במארגרטן וכפר גדעון הו\"ל מספריו."},{"i":42691,"n":"קליין, שלמה זלמן מסילאד-טשעה","f":"משה מסילאדי-טשעה","k":"בעל עטרת שלמה","bt":"תרכב","bp":"סעליש","dt":"תשב - ט חשון","b":"רב בסילאדטשעה(=סעליש)-תרמ\"ב על מקום אביו - בהמלצת בעל \"ייטב לב\" - למרות גילו הצעיר וכיהן כ-60 שנה. חתן ר יקותיאל שוורץ ממנשטאר. חיבר קונטרס עגונות בענין עגונות מלחה\"ע ה-I, נדפס מכתביו גם \"לקוטי שלמה\" ת\"א תשמט."},{"i":42692,"n":"קליין, שלמה ישראל מסעליש","f":"פנחס חיים מסעליש","bt":"תרמד","bp":"סעליש","dt":"תשד-ה - ו אדר","dp":"ברגן בלזן","b":"תלמיד ישיבת אונסדורף. חתן ר נתנאל פריד בעל \"פני מבין\". רב בסעלעש(=סעליש)-תרעה. חיבר ספרים על התורה והש\"ס - בכת\"י. נספה בשואה. בניו - ר שמואל שמלקא הי\"ד, ר יוסף עוזר מניו יורק."},{"i":42693,"n":"קליין, שלמה מברעסטעש","b":"פרסם מאמרים ב\"דבר בעתו\" - פאקש תרסט."},{"i":42694,"n":"קליין, שלמה ממעזא קרסטש","f":"אריה ליב מסיגט","k":"בעל אהבת עולם-תרלה","bp":"סיגט","dt":"תרסט - יא טבת","b":"נכד ר אליהו פסטינגר מסיגט. תלמיד ר משה הרש פוקס בגרוסורדין. חתן ר אשר גרוסברג מבעלעניעש. רב במעזא-קרסטש(=ביהור קרסטש)-מחוז ביהור-תרן. חיבר גם \"דבר בעתו\", ועוד. עורך \"מגד ירחים\" - סיגט תרנח."},{"i":42695,"n":"קליין, שלמה מפישאבאני","dt":"תשד","b":"רב בפיזעשאבאני"},{"i":42696,"n":"קליין, שמואל דוד","b":"פרסם מאמרים ב\"עטרת צבי\" - ירושלים תשא."},{"i":42697,"n":"קליין, שמואל מאוקלאד","b":"פרסם מאמרים ב\"קבוצי בחורים\" - מארגרטן תרצג."},{"i":42698,"n":"קליין, שמואל מארשק אויבר וקנדה","b":"רב הקהילה הניאולוגית בארשק-אויבר. ניצל מהשואה והגיע למונטריאול-קנדה וכיהן כרב ראשי בקנדה, ופרופ' לשפות."},{"i":42699,"n":"קליין, שמואל מלמברג","b":"חסיד הדברי חיים. מכתב הדברי חיים אליו-תרכו."},{"i":42700,"n":"קליין, שמואל מנחם מצ'רנוביץ","f":"שלמה זלמן מסילאג צ'ה","k":"בעל רסיסי טל-תשלז","bt":"תרמב","bp":"סילאדי-טשעה","dt":"תרפו - טו תשרי","dp":"צ'רנוביץ","b":"תלמיד השב\"ס, ור משה צבי פוקס מגרוסורדין. חתן ר משה שמואל גלזנר מקלויזנבורג וסייע לחותנו בניהול הישיבה. רב בשעבעש-סלובקיה-תרסט, טשרנוביץ-תרפד. בניו - ר אברהם קליין מטארנאליא - הו\"ל \"רסיסי טל\" בתוך \"דור רביעי\" ירושלים תשלז, ור יקותיאל מהאלנדיל. (באוצר הרבנים מופיע שם אביו - משה)."},{"i":42701,"n":"קליין, שמואל מפוטנאק.","b":"חתנו - ר שלמה יהודה ליב זינגר מרימא-סאמבט."},{"i":42702,"n":"קליין, שמואל שמלקא מאלשד","f":"יעקב שלום מהאלמין","b":"חתן ר טוביה לרמן מדעש, ועבר לשם. דיין בהאלמין לצד אביו. רבה הראשון של אלשד-ליד גרוסורדין-תרצד. נספה בשואה."},{"i":42703,"n":"קליין, שמואל שמלקא מבאלקאני","k":"בעל צרור החיים","r":"אב\"ד סעליש","dt":"תרלה - ט אד\"ב","b":"תלמיד ישיבת ואשוואר-ליד סטמר, ר שלום אולמן מלקנבך. רבה הראשון של באלקאני, חוסט וראש ישיבה, סעליש-תרך על מקום ר חיים משה הכהן ובנו - ר פנחס חיים על מקומו אחריו. לתולדתיו ב\"רבי שמעלקא\" לנכדו ר שלמה זלמן קליין. חתם על ה\"קול קורא\" - נגד החלטת הקונגרס-תרכט לפילוג הקהילות בהונגריה.","bk":[["צרור החיים – ש\"ס ועה\"ת",""]]},{"i":42704,"n":"קליין, שרגא יהודה מפאקש","b":"חתן ר משה אריה ליב ליטש-רוזנבוים מפרשבורג. רב בפאקש ובודפשט."},{"i":42705,"n":"קליין-טשאבא, יוסף מסערדאוהל","k":"בעל דברי יוסף","dt":"תרנז - ז אדר","b":"מרביץ תורה,ראב\"ד בסערדאהעלי"},{"i":42706,"n":"קליינהנדלר, אברהם מבוכניה","b":"רב בבוכניה. אחיו של ר דוד מזבורוב."},{"i":42707,"n":"קליינהנדלר, דוד מזבורוב","b":"רב בלנצהוט, ויברניפקה, זבורוב-תרס, בנו ר שלמה על מקומו אחריו בזבורוב."},{"i":42708,"n":"קליינהנדלר, משה","b":"חתן ר בן ציון שליטא מזבורוב."},{"i":42709,"n":"קליינהנדלר, שלמה מזבורוב","f":"דוד מזבורוב","bt":"תרם","dt":"תשג","b":"רב בזבורוב עם גיסו ר בן ציון. נספה בשואה. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":42710,"n":"קליינר, אברהם אבא מביאליסטוק","dt":"תרמד - כ-כז שבט","b":"רב בביאליסטוק. הגיה את כתבי הגר\"א, והעתיקם בכתב ידו."},{"i":42711,"n":"קליינר, אליעזר מאמדור","b":"פרסם מאמרים ב\"קובץ מפרשי התורה\" - מארגרטן תרצג."},{"i":42712,"n":"קליינר, דוד","dt":"תשג","b":"רב בוורשה"},{"i":42713,"n":"קליינר, ישראל מחמעלניק","f":"שמואל","bt":"תרלז","b":"רב בחמלניק-פודוליה-תרס-פ."},{"i":42714,"n":"קליינר, שלמה יהודה ממנוסטרישטש","b":"מחכמי מנוסטרישטש-תרכו."},{"i":42715,"n":"קלייף, שמעון","b":"רב-שנת ת\"ק. חתנו - ר מרדכי רפפורט-שרנצל מסטעפן ולויצק."},{"i":42716,"n":"קליכטרלן, אברהם אשכנזי מבסקביץ","f":"משה","b":"אב\"ד בסקביץ. הסכים על \"אור חדש\" - אמשטרדם תלא."},{"i":42717,"n":"קלימאני, ברוך","b":"מקובל, מחכמי טורקיה בזמן ה\"בית יוסף\" ובעל \"מדבר יהודה\". הוציא לאור \"מעשי ה'\" לר אליעזר אשכנזי, \"ו\"תורת משה\" לר משה אלשיך, עם הקדמה ממנו."},{"i":42718,"n":"קלימאני, שמחה מונציה","k":"בעל דקדוק לה\"ק","dt":"תקמד - טו באב","b":"רב בונציה-תקכא. חיבר דקדוק לה\"ק בעברית ואיטלקית, \"ערוך מלות\" בכת\"י, \"קול שמחה\". שירים וקינות. והגיה ספרים שנדפסו בונציה."},{"i":42719,"n":"קלין שלום יוסף בן אברהם שמחה","dt":"ה'תש 1940","bk":[["קול סופרים",""]]},{"i":42720,"n":"קלין שלמה הכהן מפררוי","bt":"1833","dt":"ה'תרס 1900","bk":[["לקוטי שלמה",""]]},{"i":42721,"n":"קלין שמואל בן נטע","bt":"1724","dt":"ה'תקסו 1806","bk":[["מחצית השקל",""]]},{"i":42722,"n":"קלין שמואל שמלקא בן יוסף","bt":"1805","dt":"ה'תרלה 1875","bk":[["צרור החיים",""]]},{"i":42723,"n":"קלינבסקי, מאיר","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":42724,"n":"קלינברג, אברהם אריה ליב מסקלט","b":"מחכמי סקלט. תשובה אליו \"ארץ צבי\"."},{"i":42725,"n":"קלינברג, אברהם מרדכי מזלושיץ","f":"מנשה יעקב מבריגל","k":"אדמור מזלושיץ","bt":"תרג","bp":"קראקא","dt":"תרעח - יט חשון","b":"נכד האדמור מהרי\"א ספרין מקומרנא, שהביא ממנו בספרו \"אוצר החיים\". חתן ר משה רוטנברג מסקוליע. כיהן כאדמור בזלושיץ. עבר לקראקא. חיבר \"אלפי מנשה\", \"עלי זית\" - בכתב יד. בנו ר שם על מקומו אחריו כאדמור זלושיץ בקראקא."},{"i":42726,"n":"קלינברג, אליעזר מוילנא וארה\"ב","f":"אלכסנדר","k":"אליעזר בויסקער","bt":"תקצב","bp":"בויסק","dt":"תרנא - א אד\"א","dp":"פילדפליה","b":"חתן ר ישראל ליפשיץ אנטקאליער מוילנא. מו\"צ בוילנא על מקום חותנו, רב בפילדלפיה-תרמח, וחתנו ר דב אריה לוונטל הכהן על מקומו אחריו-תרנא. הספיד את ר מתתיה שטרשון ב\"אבל כבד\" לר משה שמעון אנטקולסקי - וילנא תרמו."},{"i":42727,"n":"קלינברג, אלכסנדר צבי מוולובה","f":"מנשה יעקב מבריגל","b":"רב במיידן, וולובה-תרכז. חתן ר יעקב קלוגר מסנדובה. רב בסנדובה על מקום חותנו. הוציא לאור \"זכרון דברים\" מזקנו ר אלכסנדר אייכנשטין מקומרנא."},{"i":42728,"n":"קלינברג, זידא משה חיים","f":"אברהם מרדכי מזלושיץ","k":"אדמור מקששוביץ","bt":"תרל","dt":"תשג - ניסן","b":"בן האדמור מזלושיץ בקראקא. רב ואדמור בקששוביץ (ליד קראקא). נספה בשואה."},{"i":42729,"n":"קלינברג, יעקב יוסף מוארשא","k":"בעל ספר המצות","dt":"תרלח - ד אב","b":"מו\"צ בוורשה"},{"i":42730,"n":"קלינברג, מתתיהו חיים מוארשא","dt":"תקצו - כד חשון","b":"תלמיד ר אלימלך מליזנסק, והחוזה מלובלין, ומראשוני החסידים בוארשא. מחותן עם האדמו\"ר ר אברהם מסוכטשוב."},{"i":42731,"n":"קלינברג, צבי הירש מלאנטשין","b":"תלמיד המהרש\"ם מברזאן - שהיה חותנו-זקנו. רב בלאנטשין, אחרי מלחה\"ע ה-I כשחרבה עירו עבר לקאלאמע. תשובה אליו - \"אמרי דוד\"-תרצב."},{"i":42732,"n":"קלינברג, צבי מוואלאווע","k":"בעל זכרון דברים","b":"רב בוואלאווע-תרכז, סאנדאווא-ווישנא על מקום חותנו-תרלא."},{"i":42733,"n":"קלינברג, שם מזלושיץ","f":"אברהם מרדכי מזלושיץ","k":"אדמור מזלושיץ","r":"אדמו\"ר מזלושיץ בקראקא","bt":"תרלב","bp":"סקוליע","dt":"תשג - כח ניסן","b":"חתן ר ישראל הורביץ מווסליץ. עבר עם אביו לקראקא-תרן. אדמור מזלושיץ בקראקא על מקום אביו. נספה בשואה. חיבר \"אהלי שם\" ירושלים תשכא.","bk":[["אהלי שם – תורה ומועדים",""]]},{"i":42734,"n":"קלינגר, זיידא מצפת","b":"דיין בצפת-תרמד, חתם עם ר דוד באבד, ר שמואל מחרסקוב."},{"i":42735,"n":"קלינגר, ישעיה ראובן מסיוען ויר","k":"בעל מעשה המנורה","dt":"תשג","b":"רב בסיווען, עלה לירושלים-תרכ. חיבר גם \"אבל משה\" - הספד על ר משה סלפקוביצר מיאס - ירושלים תרמד."},{"i":42736,"n":"קלינגר, ישראל יצחק","dt":"כ תמוז","b":"רב במלאווא-תר\"ס"},{"i":42737,"n":"קלינמן, אברהם הכהן ממארגרטן","b":"תלמיד וחתן ר שמואל זלמן וינברגר ממארגרטן. רב בסט מיקלוש, ניצל מהשואה, ואחריה רב במארגרטן והקים מחדש את הישיבה, היגר לארה\"ב וכיהן כרב בקהילת מארגרטן בניו יורק. בנו אהרן אליעזר מנתניה הו\"ל ספר יזכור לקהילת מארגרטין."},{"i":42738,"n":"קלינמן, אברהם יוסף חנוך","f":"שמואל זאב מואראהל","b":"תלמיד בעל \"עצי חיים\" בסיגט, ר יואל טיטלבוים בעל \"ויואל משה\", ור יהודה רוזנר בסעקעיהיד. שו\"ב בטרנסילבניה, ניצל מהשואה, עלה לארץ וכיהן כרב בכפר גדעון ובקרית אתא. הו\"ל \"אמרי יהודה\" לר יהודה רוזנר."},{"i":42739,"n":"קלינמן, אברהם ממינסק","f":"אשר אנשיל מליסא","k":"בעל עמוד הימיני","bp":"וילנא","dt":"תרי - בערך","b":"מגיד מישרים במינסק. עלה לארץ ונפטר בדרכו. חיבר \"עמוד הימיני\" (כולל ההספד שנשא על הגר\"א) מינסק תקעא. בנו - ר אשר מוידז בעל \"מעדני אשר\"."},{"i":42740,"n":"קלינמן, אהרן מקמיניץ","dt":"תרכו - ה ניסן","b":"תלמיד ר נח מלכוביץ, ור משה מקוברין. יסד את השטיבל החסידי הראשון בקמיניץ-ליטא."},{"i":42741,"n":"קלינמן, אלעזר מאיר מסטריזוב","b":"חתן ר אליעזר ירוחם ברון (נכדת הדברי חיים).שו\"ב בסטריזוב-תרנט, וישניצה, רב בטעשין."},{"i":42742,"n":"קלינמן, אשר מדוברומיל","f":"אברהם ממינסק","k":"בעל מעדני אשר","bt":"תקס","bp":"ליטא","dt":"תרך","b":"רב במאלאדעצנא, וידז. גורש מליטא-תקצג ועבר בלמברג בדרכו לארץ - אך נתקבל לרב בדוברומיל. חיבר \"מעדני אשר\" למברג תקצז. חתנו - ר מנחם מן ממינסק."},{"i":42743,"n":"קלינמן, חיים בן ציון מקובנא","b":"מנהל כולל קובנא-תרצד."},{"i":42744,"n":"קלינמן, יואל","f":"משה","b":"מרביץ תורה בישיבת בית יוסף,אסטרובה מזוביסק"},{"i":42745,"n":"קלינמן, ישעיה מסטמר","f":"משה יעקב ישכר","k":"בעל קרן ישעיה-תשד","dt":"תרצח - כח אד\"א","b":"תלמיד דודו ר ישעיה שטיינר האדמור מקריסטיר. תלמיד בעל \"ערוגת הבשם\" בחוסט. דיין בקיוועשד-גליל אוגוצה-תרסה, דיין בסטמר-תרע אצל ר חיים הלברשטם. החל להדפיס את ספרו \"קרן ישעיה\" סטמר תשד ורובו אבד בשואה. פרסם מאמרים ב\"בית ועד לחכמים\" - סטמר תרפב."},{"i":42746,"n":"קלינמן, מרדכי מכפר אמראד","f":"שמואל זאב מואראהל","k":"בעל מאמר מרדכי-תשמג","b":"תלמיד בעל \"עצי חיים\" בסיגט, ור יהודה רוזנר בסעקעיהיד. חתן ר מנחם קליין שו\"ב בטשוטשא. שו\"ב בכפר אמראד-ליד סטמר. נספה בשואה."},{"i":42747,"n":"קלינמן, נפתלי הרץ מדוברומיל","f":"אשר מדוברומיל","b":"מחכמי דוברומיל."},{"i":42748,"n":"קלינמן, שלמה דב","f":"אליעזר מאיר מסטריזוב","bt":"תרסט","dt":"תשמט","b":"גדל אצל ר אלעזר מאושפיצין. חתן ר יוסף ספיר מצאנז. שו\"ב ברוזוודוב. ניצל מהשואה (היה בסיביר) וחזר לכהן כרב בגלייוויץ, עבר לפריס וכיהן כרב. היגר לניו יורק-תשיד, לונדון-תשך."},{"i":42749,"n":"קלינמן, שמואל זאב מואראהל","f":"אלעזר","k":"בעל הוד שמואל-תשמג","dt":"תשיד - ח אלול","dp":"ואראהל","b":"תלמיד בעל \"דרכי תשובה\" במונקטש, ר שלום גולדנברג בסוואליווע, ר אליהו קליין בהאלמין ור יחזקאל בנט בוואראהל. חתן ר שמואל גרינפלד מניגרשט. שו\"ב בסאניסולי, אראד, מוינשטי, ואראהל. ניצל מהשואה. בניו ר שלום ור אברהם יוסף חנוך חיברו הקדמה לספרו והוסיפו מתולדותיו."},{"i":42750,"n":"קלינצלר, אריה ליב מוישניצה","f":"אהרן פנחס","b":"תלמיד הדברי חיים. חתן ר שמעון וייל מצאנז. רב בטשרני-דונייעץ."},{"i":42751,"n":"קלינקופ, יהודה אריה ליב","dt":"תרץ","b":"חסיד ר משה הורביץ מרוזוודוב. רב באיססטיטשין (=סטוטשין), רודניק - ר ברוך וצבי הירש הלברשטט."},{"i":42752,"n":"קלינקופמן, אלכסנדר מגרודזיסק","b":"רב בגרודיזסק-תרפב."},{"i":42753,"n":"קלינקיט, משה מצאנז","b":"רב בצאנז-תרן."},{"i":42754,"n":"קלינקרמר, בן ציון מלימנוב","b":"מחכמי לימנוב-תרפז."},{"i":42755,"n":"קלינרמן, אברהם מביאליסטוק","b":"רב בביאליסטוק. נפטר בגיל 41."},{"i":42756,"n":"קלינרמן, יואל מאוסטרוב","dt":"תש..","dp":"גיטו וילנא","b":"חתן נכדת הסבא מנוברדוק. ר\"מ בישיבת נוברדוק, ראש ישיבת נוברדוק במינסק-תרפח, ראש ישיבת נוברדוק באוסטרוב-מזוביצק. גלה לגיטו וילנא ונספה בשואה."},{"i":42757,"n":"קלינרמן, שמואל","b":"פרסם מאמרים ב\"אהל תורה\" - ירושלים תרצט."},{"i":42758,"n":"קליסניקר, אליהו מסמילא","f":"יעקב חיים","k":"בעל הליכות אליהו","bt":"תרכ","b":"רב בסמילא-פלך קיוב-תרמט. ממקורבי ר יוחנן מרחמיסטריבקא. חיבר \"הליכות אליהו\" וארשא תרסג."},{"i":42759,"n":"קליסקר, אברהם הכהן","f":"אברהם כץ מקאליסק","b":"רב בקאליסק עלה לא\"י"},{"i":42760,"n":"קליף, דניאל ממיטאוי והאזנפוט","k":"בעל ערוגה קטנה","bt":"תפט","bp":"אמשטרדם","dt":"תקנד","dp":"אמשטרדם","b":"תלמיד ר שמשון קרלסרוא. מחכמי מיטאוי, האזנפוט-קורלנד-תקלא."},{"i":42761,"n":"קליף, זכריה מפיורדא","b":"פרנס בקהלת פיורדא-שנות ה-תק'."},{"i":42762,"n":"קליף, יעקב מאה\"ו","f":"ישכר בער","k":"בעל שמן הקיק","dt":"תקיט - ח ניסן","dp":"אלטונא","b":"מחכמי אה\"ו. היה מקורב לר יעקב עמדין אך במחלוקת עם ר יונתן איבשיץ תמך בר יונתן. חיבר גם \"במת יחיד\"."},{"i":42763,"n":"קליף, ישכר בער מאה\"ו","dt":"תצח","b":"גביר עשיר ופרנס באה\"ו. בנו - ר יעקב בעל \"שמן הקיק\"."},{"i":42764,"n":"קליף, משה מברלין","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":42765,"n":"קליפן, שלמה","b":"פרסם מאמרים ב\"הדנו\" - נ\"י תרפה."},{"i":42766,"n":"קליפרא, ישראל שמואל","f":"שלמה מגזע יהודה","k":"בעל ישמח ישראל","dt":"ת - יג שבט","b":"רב באיטליה? חיבר \"ישמח ישראל\" (נדפס בקראקא שפו עם פירוש לר משה יקותיאל קויפמן), \"אור ישראל\", \"כרם שלמה\", ועוד."},{"i":42767,"n":"קליפרא, שלמה הרופא מקראקא","b":"רופא מחכמי קראקא. נזכר בשו\"ת הרמ\"א, ואצל מהרש\"ל. בנו - ר ישראל שמואל בעל \"ישמח ישראל\". מצאצאיו הקדוש ר מתתיהו קלהארא הרוקח שנהרג עק\"ה בפיעטרקוב."},{"i":42768,"n":"קליצר (גליצר),נתן נטע מפודהייץ","bt":"תקל","dt":"תר","b":"תלמיד ר משולם איגרא (אחד מהשלושה שהסכים להסמיך - האחרים החוות דעת ור אריה ליב הורביץ מסטניסלב). רב בפודהייץ על מקום ה\"לב אריה\", נכדו ר שמעון מלר על מקומו אחריו (משפחת מלר-לילינפלד המשיכו שם את חזקת הרבנות). רב בטיסמניץ."},{"i":42769,"n":"קליר אלעזר בן אלעזר","bt":"1741","dt":"ה'תקסא 1801","bk":[["אור חדש",""],["חות יאיר",""],["חות יאיר החדש",""],["חקר הלכה",""]]},{"i":42770,"n":"קליר, אלכסנדר זיסקינד מברוד","f":"אלעזר מרכניץ","bt":"תקלא","dt":"תרה","b":"חתן ר יעקב הלוי חרמץ מברודי, ועבר אל חותנו לברודי, והיה שם גביר תלמיד חכם. מחדושיו בספר אביו \"חקר הלכה\" רוב כתביו נשרפו."},{"i":42771,"n":"קליר, אלעזר מרכניץ וקעלין","f":"אלעזר מרכניץ","k":"בעל אור חדש","bt":"תצח","bp":"אייזנשטט","dt":"תקסב - טו חשון","b":"מגדולי דורו. חתן ר יהושע בר\"ץ. רב בזבלודובה-תקך, רכניץ-תקכח על מקום ר יהודה ליב סטאשאף ועמד שם בראש ישיבה ור אהרן פריישטאדטיל על מקומו אחריו, אויבן ישן-תקל, וישניצה-תקלח על מקום רנ\"ה לנדא ואחריו על מקומו ה\"ברוך טעם\", סקוביץ, קעלין (בוהמיה) ועמד בראש הישיבה, מלמד בברלין בבימ\"ד הקצין ר משה ב\"ר יצחק הלוי. חיבר \"אור חדש\" פירודא תקכו, ועוד. חתניו - ר יצחק פרנקל מליכטנשטט, ר דוד בן צבי הירש הורביץ בעל \"מחנה לוי\"."},{"i":42772,"n":"קליר, מאיר מברוד","f":"אלכסנדר זיסקינד","bt":"תקנה","dt":"תרלה","b":"חתן הפרנס ר זאב וולף מרשלקוביץ. גביר ותלמיד חכם בברודי. תכנן הקמת ישובים חקלאים יהודים-תרי. איש חסד בעל קשרים טובים אצל הקיסר והממשלה בוינה - בעל תואר רוזן ואביר. בנו נתן ירש ממנו תואר רוזן והיה חבר הבית העליון בוינה. תולדותיו בספר \"מעשה הקאליר\" לר ברוך ורבר."},{"i":42773,"n":"קלירס, משה מטבריה","f":"מאיר","k":"בעל תורת הארץ","bt":"תרלד-ח","bp":"צפת","dt":"תרצד","dp":"טבריה","b":"מחסידי סלונים ונסע אל האדמור לסלונים, הוסמך על ידי ר חיים מבריסק והאדר\"ת, התמנה לרבה של טבריה לאחר הוראת האדמור מסלונים. ראה ישיבת \"אור תורה\". חיבר \"תורת הארץ\" ירושלים תרפח, ועוד. פרסם מאמרים ב\"קול ישראל\" - ירושלים תרפא - ירחון חדו\"ת מאת \"צעירי אגודת ישראל בירושלים\"."},{"i":42774,"n":"קליש, אברהם מרדומסק","f":"מנחם מאמשינוב","k":"אדמור מאמשינוב רדומס","dt":"תשג","dp":"טרבלינקה","b":"חתן ר אברהם ישכר בער מרדומסק. אדמור מאמשינוב-רדומסק - לא נהג כמנהגי אדמור. בנו יחידו ר יעקב ישכר נפטר צעיר."},{"i":42775,"n":"קליש, אברהם משה מפאלניץ","f":"שמחה בונם מאוטואצק","k":"אדמור מאוטואצק פאלני","dt":"תרצח - ב אלול","b":"אדמור בפאלניץ, אוטואצק, וארשא."},{"i":42776,"n":"קליש, אדוארד מארה\"ב","bt":"1865","bp":"טולידו-אוהיו","b":"תלמיד ההיברו יוניון קולג'. רב ריפורמי בוילל, קהילת \"בית אהבה\" בריצמונד-וירגיניה. חיבר ספר על התפילה באנגלית."},{"i":42777,"n":"קליש, איזידור מארה\"ב","k":"בעל ועגוויזער פיר","b":"רב במילווקי, נייערשי. חיבר ספרים באנגלית ובלשון אשכנז. חיבר גם \"מבוא התלמוד\"."},{"i":42778,"n":"קליש, אלעזר מרכניץ","bt":"תקה","bp":"איזנשטט","b":"נכד המהר\"ם א\"ש. רב באיזנשטט, ובקהילות נוספות. היה בקשר מכתבים עם ה\"נודע ביהודה\"."},{"i":42779,"n":"קליש, גרשון מדיעסעג(=דיוסג)","f":"מרדכי מדעקי","k":"בעל עבודת הגרשוני","b":"תלמיד מהר\"ם שיק. רב בדיוסג(=דיאסעג)-מחוז טירנא. אחיו של ר מאיר מסאבאד-סאלאש, וגיסו של ר פנחס הכהן שטיינר מאילאק. בנו ר ישעיה ראב\"ד פרשבורג - נספה בשואה."},{"i":42780,"n":"קליש, דב בר מלויביטש","f":"שמעון מסקרנויץ","k":"אדמור מלויביטש","dt":"תשג","b":"חתן ר נתן נחום מקרימלוב (שושלת רדמוסק). תלמיד אביו ואחיו ר מרדכי מנחם מנדל. אדמור בלויביטש-תרפט והקים ישיבה \"שם משמעון\" שהוציאה כתב עת ובו מתורתו."},{"i":42781,"n":"קליש, זאב וולף מלבוב","b":"רב בלבוב, חתם-שפד על תקנת קהלת זולקוא, עם ר אברהם אשכנזי, ר אברהם הכהן בעל \"איתן האזרחי\", ור יעקב אליקים געטשליק."},{"i":42782,"n":"קליש, י' ישראל יצחק מפיאסנצה","f":"שמחה בונים קליש","dt":"תרסח - ו סיון","b":"רב בפיאסצנה"},{"i":42783,"n":"קליש, יאיר ממעזלברץ","f":"משלם דב ממונקטש","b":"רב במעזאלברץ. חתנו - ר יוסף אלימלך כהנא מאונגוואר."},{"i":42784,"n":"קליש, יהודה אריה ליב","k":"בעל גור אריה","dt":"תע - ז כסלו","b":"רב ור\"מ בלובזנץ, קרמזיר, קאליש, רב לאשכנזים באמשטרדם-תסח."},{"i":42785,"n":"קליש, יוסף זאב","b":"פרסם מאמרים ב\"הכוכב\" - מונקטש-נ\"י תרצה."},{"i":42786,"n":"קליש, יוסף מאמשינוב","f":"מנחם מאמשינוב","k":"אדמור מאמשינוב","bt":"תרלח","bp":"אמשינוב","dt":"תרצו - ג שבט","dp":"אוטואצק - וארשא","b":"חתן ר חיים אלעזר ואקס בעל \"נפש חיה\". רב באוסטרובה-תרסה, רב ואדמור באמשינוב-תרעט על מקום אביו. לאחר מחלתו נוספו לו השמות \"ירחמיאל אהרן\". מתולדותיו ב\"אהל יוסף\"."},{"i":42787,"n":"קליש, יוסף מאמשינוב ארה\"ב","f":"יצחק מאמשינוב ארה\"ב","k":"אדמור מאמשינוב ארה\"ב","b":"אדמור מאמשינוב בארה\"ב על מקום אביו."},{"i":42788,"n":"קליש, יוסף צבי מקראטשוב","f":"שמעון מסקרנויץ","r":"אדמו\"ר מסקרנביץ ורב דבני ברק","bt":"תרמו-ז","bp":"סקרניביץ-פולין","dt":"תשיז - א אד\"א","b":"חתן ר יצחק יעקב מביאלא (שושלת פשיסחא). רב בקארטשוב, נשיא \"אגודת ישראל\" בוארשא. עלה לארץ-תרצד וכיהן כרב בבני ברק-תרצז. מתורתו ב\"באהלי צדיקים\".","bk":[["שארית יוסף",""]]},{"i":42789,"n":"קליש, יחזקאל בונם","dt":"תשג","b":"רב בראטשוב"},{"i":42790,"n":"קליש, יחיאל חיים ישראל יצחק","f":"מנחם מנדל מאוטואצק","k":"אדמור מוארקי אוטובצק","b":"חתן ר אליעזר ליפשיץ מלודז-חתנו של ר יחאיל מאלכסנדר. אדמור בוארקי ואוטואצק והקים ישיבה."},{"i":42791,"n":"קליש, יעקב דוד ברוך מוארקי","f":"אברהם משה מפאלניץ","k":"אדמור מוארקי בארה\"ב","dt":"תשמג - יג שבט","dp":"טבריה","b":"חתן ר מנחם מנדל מוונגרוב-בן ר יצחק זליג מסוקולוב. אדמור מפאלניץ-וארקי בארה\"ב. עלה לירושלים."},{"i":42792,"n":"קליש, יעקב דוד מאמשינוב","f":"ישראל יצחק מוארקי","k":"אדמור מאמשינוב","bt":"תקעד","dt":"תרלח - ד כסלו","b":"חתן ר שמואל מפרצוב, ובזיוו\"ש חתן ר יעקב מזרנובצא(=יעקעלע מזארנאווצי - בנימין זאב יעקב מזרנובצא). רב בגוברצ'וב, גור, פשיסחא, גור, רב ואדמור באמשינוב. ממנהיגי היהודים בפולין בדורו. מתורתו ב\"שיח שרפי קדש\"."},{"i":42793,"n":"קליש, יעקב דוד מאמשינוב","f":"יוסף מאמשינוב","k":"אדמור מאמשינוב","r":"אב\"'ד ז'ירדאו שבפלך ורשא","bt":"תרסח","dt":"תשב - ניסן","dp":"וארשא","b":"חתן ר שלמה יוסקוביץ-חתנו של האדמור ר אברהם מרדכי מגור. רב בזירדוב-ליד וארשא, רב ואדמור באמשינוב-תרצו על מקום אביו (ונשאר גם רבה של זירדוב). נספה בשואה (בגיטו וארשא). מתולדותיו ב\"אהל יוסף\".","bk":[["זכרון קדוש",""]]},{"i":42794,"n":"קליש, יעקב יהודה מבלוינא","f":"שמעון מסקרנויץ","k":"אדמור מבלוינא","dt":"תרץ - יט תשרי","b":"חתן ר ישראל אהרן מאופוטשנא (שושלת נסכיז). תלמיד אביו ואחיו ר מרדכי מנחם מנדל מסקרנויץ. אדמור בבלוינא-תרפט כחצי שנה."},{"i":42795,"n":"קליש, יעקב מברלין","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":42796,"n":"קליש, יצחק מאוטובצק","k":"אדמור מאוטובצק","dt":"תש","b":"אדמו\"ר באוטובצק"},{"i":42797,"n":"קליש, יצחק מאמשינוב ארה\"ב","f":"יוסף מאמשינוב","dt":"תשנד - יט אדר","b":"ניצל מהשואה והגיע דרך וילנא ויפן לארה\"ב. כיהן כאדמור מאמשינוב בארה\"ב, והיה מזקני האדמורים בארה\"ב."},{"i":42798,"n":"קליש, יצחק מוארקי","f":"שמעון קאליש","bt":"תקלט","dt":"תרח - כב ניסן","b":"רב בגוברטשוב,ווארקי"},{"i":42799,"n":"קליש, ירחמיאל יהודה מאיר מאמשי","f":"שמעון שלום מאמשינוב","k":"אדמור מאמשינוב י-ם","bt":"תרסא","dt":"תשלו - כז אייר","b":"חתן ר יעקב אריה מוישקוב-לומאז (שושלת קוצק). עלה לירושלים-תשיד אחר פטירת אביו והקים ישיבה ע\"ש אביו \"שם עולם\". נכדו ר יעקב מילקובסקי - האדמור מאמשינוב."},{"i":42800,"n":"קליש, ירמיה מאופלא","f":"יעקב דוד מאמשינוב","k":"אדמור מוארקי באופלא","bt":"תרלג","bp":"אמשינוב","dt":"תשב","dp":"וארשא","b":"לאחר שנתייתם גדל אצל אחיו ר מנחם מאמשינוב. חתן ר מנדל שאטאן מוישיגראד, ובזיוו\"ש חתן ר אברהם איגר מלובלין. רב באופלא-ליד לובלין, בזמן מלחה\"ע ה-I נאסר באשמת ריגול ונאסר בלובלין, עבר לוארשא ליד אחיו."},{"i":42801,"n":"קליש, ישעיה מאמשטרדם וברלין","b":"מראשי הקהילה בברלין-תקד, חתם על כתב ההסכם עם ר דוד פרנקל הראב\"ד בברלין."},{"i":42802,"n":"קליש, ישעיה מפרשבורג","f":"גרשון מדיאסעג","bt":"תרמג-סג","bp":"דיאסעג","dt":"תשה - יח תשרי","dp":"אושוויץ","b":"תלמיד השב\"ס והדעת סופר, ור יצחק שוייגר מטאפלאטשן, ור יצחק שמעלקיס מלמברג. חתן ר יהודה ליב פרידמן מפרשבורג. רב ודיין בפרשבורג-תרעג ור\"מ בישיבה, וראש המורים-תשב על מקום ר דוד ועסלי. הו\"ל שות הריב\"ד לחותנו. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד. סייע לפליטים יהודים מפולין-תרפא - גם ל\"חלוצים\" שאינם שומרי תורה - והיו שיצאו נגדו על כך. מכתב ממנו-תרצט ובו מבקש סרטפיקט להגיע לארץ אך הדבר לא הסתייע, ונשאר באירופה, ונספה בשואה."},{"i":42803,"n":"קליש, ישעיה מפשיסחא","f":"יעקב דוד מאמשינוב","bt":"תרכט","dt":"תשג","b":"לאחר שנתייתם גדל אצל אחיו ר מנחם מאמשינוב. חתן ר מאיר מפשיסחא. התפרנס ממסחר, חידש את ביהמ\"ד של \"היהודי הקדוש\" בפשיסחא."},{"i":42804,"n":"קליש, ישראל יצחק יחיאל מפיאסנצ","f":"שמחה בונם מאוטואצק","k":"אדמור מאוטואצק בקאל","dt":"תרע..","b":"אדמור מאוטואצק בקאליש."},{"i":42805,"n":"קליש, ישראל יצחק מוארקי","f":"שמעון \"בעל רחמנות\"","k":"אדמור מוארקי","bt":"תקלח","dt":"תרח - כב ניסן","b":"מצאצאי בעל ה\"לבוש\". חתן ר מאיר מז'וריק-חסיד ללוב. תלמיד ר דוד האדמור מללוב, היהודי הקדוש מפשיסחא, ר שמחה בונם מפשיסחא ובנו ר אברהם משה. אדמור לחסידי פשיסחא על מקום רבו ר אברהם משה, עבר מפשיסחא לנדרזין בהוראת האדמור ר ירחמיאל וחתנו ר אהרן הכהן על מקומו אחריו, רב ואדמור בוארקי. מפורסם כ\"אוהב ישראל\". בילה רבות בוארשא בעסקי ציבור. מתורתו ב\"בית יצחק\", תולדות ב\"אהל יצחק\". חתניו: ר צבי מרדכי בונהארד בן אברהם משה מפשיסחא, ר אהרן הכהן מנאדרזין, ר אברהם מאיר מפראגה-וארשא."},{"i":42806,"n":"קליש, ישראל יצחק מסקרנויץ","f":"שמעון מסקרנויץ","dt":"תשב - כ חשון","dp":"וארשא","b":"חתן ר חיים מוארשא. אדמור בסקרנויץ-תרפז על מקום אביו. נספה בשואה."},{"i":42807,"n":"קליש, ליבש","b":"מו\"צ במונקאטש-תק\"צ"},{"i":42808,"n":"קליש, מאיר","b":"מו\"צ בסאבאדסאלאש-תרע\"ד"},{"i":42809,"n":"קליש, מאיר מסאבאד","f":"מרדכי מדעקי","b":"רב בסאבאד-סאלאש. אחיו של ר גרשון מדיאסעג."},{"i":42810,"n":"קליש, מנחם מאמשינוב","f":"יעקב דוד מאמשינוב","k":"אדמור מאמשינוב","bt":"תרכ","dt":"תרעח - טז כסלו","b":"חתן ר משה הלברשטט מביאלא-גדול. רב ואדמור באמשינוב-תרלח - בגיל 18. עסק בצרכי ציבור, ועבר לוארשא בזמן מלחה\"ע ה-I."},{"i":42811,"n":"קליש, מנחם מנדל מאוטואצק","f":"שמחה בונם מאוטואצק","k":"אדמור מאוטואצק","dt":"תרעט - יח אדר","b":"חתן ר אברהם ישכר בר מרדומסק, ובזיוו\"ש חתן הגביר ר פנחס אורבך. רב במאצ'ביץ, בסובון. אדמור באוטואצק על מקום אביו, בזמן מלחה\"ע ה-I עבר לוארשא."},{"i":42812,"n":"קליש, מרדכי מנחם מנדל מוארקי","f":"ישראל יצחק מווארקי","k":"אדמור מוארקי","bt":"תקעט","dt":"תרכח - טז סיון","b":"תלמיד ר מנחם מנדל מקוצק. האדמור האמצעי בווארקי(=ווארקא)-תרט ונודע כצדיק השותק. תולדותיו ב\"הצדיק השותק\". מתורתו ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":42813,"n":"קליש, מרדכי מנחם מנדל מסקרנויץ","f":"שמעון מסקרנויץ","dt":"תרפט - יח אדר","b":"חתן ר לוי יצחק מסיראטשין (שושלת ראדזימין). התפרס ממסחר. אדמור בסקרנויץ-תרפז על מקום אביו. עבר לוארשא."},{"i":42814,"n":"קליש, משלם דב ממונקטש","b":"דיין במונקטש. בנו ר יאיר ממעזלברץ."},{"i":42815,"n":"קליש, צבי אלימלך","b":"עורך \"החיים\" - אונגואר תרפב."},{"i":42816,"n":"קליש, קויפמן משטמפן","f":"יצחק איזיק ליבנא","dt":"תקם - יח טבת","dp":"שטאמפי","b":"חתן ר וולף בן יעקב חייט. מחכמי שטאמפי, חתם-תקיא בפנקס הקהלה, עבר עם אביו לטעפליץ-תקכב וחזר לשטאמפי. נפטר בחיי אביו. בניו - קופל (נולד תקיג), מאיר ( נולד תקכב), יונתן (נולד תקכז) - נקרא על שם רבו - ר יונתן איבשיץ."},{"i":42817,"n":"קליש, קופל משטמפן","f":"קויפמן משטאמפי","b":"נכד ר יצחק-רבה של שטאמפי. חתם על אגרת הרבנות של בעל \"דברי ר\"ש\", חתם-תקנג על מינוי ר שלום אולמן לרבה של שטמפן."},{"i":42818,"n":"קליש, שמחה בונם מוארקי","f":"מרדכי מנחם מנדל","bt":"תריא","dt":"תרסז - ב שבט","dp":"טבריה","b":"מצאצאי ר מרדכי יפה בעל הלבוש. חתן הגביר ר אליהו הרץ-חסיד אלכסנדר. אדמור בוארקי על מקום אביו, קארטשוב. התפרסם בחומרותיו. בשנת תרמז עזב את עדתו ועלה לטבריה אך גורש בידי המושל התורכי, חזר לפולין והתישב באוטואצק. בשנת תרסו עלה שוב לירושלים ללא משפחתו, עבר לחברון, וחזר לטבריה."},{"i":42819,"n":"קליש, שמחה בונם מפאלניץ","f":"אברהם משה מפאלניץ","k":"אדמור מפאלניץ","dt":"תש..","b":"חתן ר פנחס ישכר מסוסנוביץ (שושלת רדוביץ). אדמור בפאלניץ על מקום אביו - עוד בהיותו בחור. נספה בשואה."},{"i":42820,"n":"קליש, שמעון מסאבודקה","dt":"תשד","b":"רב בסאבדקה"},{"i":42821,"n":"קליש, שמעון מסקרנויץ","f":"מרדכי מנחם מנדל","k":"אדמור מוארקי בסקרנוי","bt":"תריח","dt":"תרפז - כ תשרי","b":"חתן ר דוד אליהו בנט מדזילאשין-חסיד וארקי. תלמיד ר דב בריש מביאלא (שושלת טשכנוב), וגיסו ר יעקב יהודה טננבוים מנאדרזין. אדמו\"ר בטורטשין, סקרנוביץ, ובניו ר ישראל יצחק ור מרדכי מנחם מנדל על מקומו אחריו. מתורתו ב\"באהלי צדיקים\"."},{"i":42822,"n":"קליש, שמעון שלום מאמשינוב","f":"מנחם מאמשינוב","k":"אדמור מאמשינוב","r":"אדמו\"ר מאמשינוב - אוטווצק","bt":"תרמג","bp":"אמשינוב","dt":"תשיד - יט אב","dp":"ניו יורק - טבריה","b":"חתן דודו ר ישעיה מפשיסחא. אדמור-תרעח על מקום אביו באטוואצק - ליד ורשה, היה מאריך בשלחן שבת עד עלות השחר. ביקר בארץ-תרצג למשך כשנה. ניצל מהשואה דרך וילנא, שנכחי, יפן, והגיע לארה\"ב-תשז והתישב בניו יורק. חיבר \"משמיע שלום\", \"אמרות טהורות\", מכתב ממנו ב\"שערי יצחק\" לר יצחק זאלער. אחיינו ר יצחק קאליש מאמשינוב בניו יורק. חיבר \"משמיע שלום\" ירושלים תשכט, ו\"אמרות טהורות\".","bk":[["אמרות טהורות",""]]},{"i":42823,"n":"קליש-ליבנא, זאב וולף מפרג","b":"מחכמי פרג, חתם-תקטו על כתב רבנות הנודע ביהודה"},{"i":42824,"n":"קליש-ליבנא, יצחק איזיק משטמפן","f":"קויפמן","k":"בעל חק יצחק","dt":"תקמג - ז אדר","dp":"טעפליץ","b":"תלמיד ר יונתן איבשיץ. מחכמי פרג, רב בשטאמפי(=שטמפן)-תקא וחתם-תקיא עם ר בנימין זאב בן יעקב, טעפליץ-שאנוי-בוהמיה-תקכב על מקום ר שמחה פופרש. ישב בבוררות ביערגן-תקכא - בסכסוך שבין קהלות פרשבורג שטמפן וסערדהאלי - יחד עם ר שמעון דוד מסערדהאלי, ר אהרן ברלין מניטרא, ר משה המבורגר מעיר חדש, ור יוסף יעקב סופאווא מסעניץ. הסכים על \"עטרת אליהו\"-תקלה. בנו - ר קופמן. אחיו - ר וולף ליבנא קליש מפרג."},{"i":42825,"n":"קלישר, אברהם משה","f":"יהודה ליב קלישר","k":"חתן ר' עקיבא איגר","dt":"תקסב","b":"רב בפילא-תקס\"ה"},{"i":42826,"n":"קלישר, אריה ליב","f":"מאיר מקרמניץ","b":"בנו - ר שלמה מליסא, ונכדו - ר צבי הירש. אחיו - ר יוחנן."},{"i":42827,"n":"קלישר, יהודה ליב מטהורן","f":"צבי הירש","bt":"תקפא","b":"פעל לטובת ישוב ארץ ישראל עם אביו, והמשיך גם אחר פטירתו. פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":42828,"n":"קלישר, יהודה ליב מליסא","f":"משה","k":"בעל יד החזקה","bt":"1750","dt":"תקפב - כז ניסן","dp":"ליסא","b":"מרביץ תורה, ראב\"ד בליסא-תקסז בזמן ר יעקב בעל הנתיבות.","bk":[["היד החזקה",""]]},{"i":42829,"n":"קלישר, מאיר מקרמניץ","b":"רב בקרמניץ-תק. בניו - ר יוחנן קרמניצר, ר אריה ליב קלישר, ר שמואל נאמן."},{"i":42830,"n":"קלישר, עקיבא","f":"יהודה ליב קלישר","dt":"תריז","b":"דיין בליסא"},{"i":42831,"n":"קלישר, צבי הירש מטהארן","f":"שלמה מליסא או ליב","k":"בעל מאזנים למשפט","r":"תלמיד רע\"א","bt":"תקנה","bp":"ליסא","dt":"תרלה - ה חשון","dp":"טהארן(=טהורן)","b":"מגדולי חכמי דורו, תלמיד ר יעקב מליסא בעל \"חוות דעת\", ור עקיבא איגר. פעל לישוב א\"י, והקים חברה לרכישת קרקע בארץ, ולהקמת \"מקוה ישראל\" ללמוד עבודת האדמה, רב בטאהרן(=טהורן)-פרוסיה-תקפה. פרסם מאמרים ב\"כבוד הלבנון\" - ירושלים תרכג - בין היתר קורא לחידוש הקרבנות, \"פליטת סופרים\" - וילנא תרכג, \"תבונה\" - ממל-קניגסברג תרכא. בנו - ר יהודה ליב.","bk":[["צבי לצדיק","מפרשי שו\"ע"],["מאזניים למשפט [הקדמה]","מפרשי שו\"ע"],["מאזניים למשפט [משנה אחרונה]","מפרשי שו\"ע"],["מאזניים למשפט","מפרשי שו\"ע"],["מאזניים למשפט [דיני תפיסה]","מפרשי שו\"ע"],["אבן בוחן – חו\"מ סי' פט",""],["אמונה ישרה - ביאור על איוב",""],["דרישת ציון",""],["יציאת מצרים – הגדה של פסח",""],["מאזניים למשפט – חושן משפט",""],["מאמר תורה מן השמים",""],["ספר הברית – עה\"ת",""],["פתח הדעת",""],["אמונה ישרה",""]]},{"i":42832,"n":"קלישר, ראובן","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":42833,"n":"קלישר, שלמה מליסא","f":"אריה ליב","b":"רב בליסא. בנו - ר צבי הירש."},{"i":42834,"n":"קלך, גרשון מאיסטריק","f":"ישעיה זלמן","b":"רב באיסטריק. צאצאיו הגרו לארה\"ב סביב תרמד."},{"i":42835,"n":"קלך, יהודה ליב מבילקא","b":"רב בבילקא-תרעג. נכד האדמור מזידיטשוב בעל \"עטרת צבי\" ואדמורי סטרטין."},{"i":42836,"n":"קלך, ישעיה זלמן מאיסטריק","f":"משה יוסף","dt":"תרמב","dp":"צפת","b":"חתן ר ישכר דב בריש מאיסטריק. רב באיסטריק-תרכט על מקום חותנו (מטעם חסידי בלז וצאנז) ובנו ר שמואל זנויל על מקומו אחריו לזמן קצר. עלה לארץ ובנו גם הוא אחריו לצפת."},{"i":42837,"n":"קלכהים, יעקב יצחק מירוסלב","f":"חיים שרגא מירוסלב","bt":"תרמב","bp":"ירוסלב","dt":"תשלה","b":"חתן ר משה למפין. כיהן כרב צבאי במלחמת העולם ה-I, נפל בשבי והוגלה לסיביר, כיהן כרב באומסק (כ-7 שנים). חזר לאירופה ועסק במסחר בברלין, עבר לקנדה-תרפט וכיהן כרב בקוויבק, ויניפג-תרצה, ניו ברונזביק, לנס (על גבול קנדה)."},{"i":42838,"n":"קלכהים, משה מירוסלב","f":"חיים שרגא","bt":"תרנו","bp":"ירוסלב","dt":"תשנו","b":"עלה לארץ-תרפו. בשליחות בארה\"ב-תרצט."},{"i":42839,"n":"קלמי, דוד מקושטא","b":"אב\"ד בקושטא-תריז. הסכים על \"מעשה נסים\" לר משה יצחק הלוי מסופיה."},{"i":42840,"n":"קלמי, חיים מבוקרשט וירושלים","k":"בעל מאמרים למקרא","bt":"תריג","bp":"בוקרשט","dt":"תרצג - ד טבת","dp":"אזמיר","b":"עלה לארץ, חתן ר אליהו נבון וגיסו של העסקן יוסף נבון ביי והצטרף לעסקי גיסו. פנה להוראה בחברת כי\"ח. פרסם מאמרים עם אליעזר בן יהודה בצרפתית עם תרגום עברי, סייע לתלמידו שי\"ש בעריכת מילון ספרדי צרפתי-תרנט, בשליחות באירופה וארה\"ב, מנהל בי\"ס באזמיר, התישב באלכסנדריה-מצרים."},{"i":42841,"n":"קלמי, יוסף מיוון","f":"משה בן דוד פרודוליאו","k":"בעל מנורת המאור","b":"מחכמי יוון, מליץ ומדקדק. חיבר גם \"מנחת יהודה\" לכבוד ר יהודה ן עטאר ממגורשי ספרד."},{"i":42842,"n":"קלמייר, אורי מפאלגי","k":"בעל אור תורה","b":"מצאצאי המהרש\"א. רב בפאלגי-שפ. חיבר \"אור תורה\" ובו מתורת זקנו - המהרש\"א."},{"i":42843,"n":"קלמן","b":"תשובה אליו בשו\"ת מהר\"ם פדובה."},{"i":42844,"n":"קלמן אשכנזי, מנחם הלוי מקושטא","b":"פרנס קהלת האשכנזים בקושטא-שן. היה במחלוקת עם ר שמואל יפה בעל \"יפה תואר\" אודות מינוי בנו ר יוסף יפה לרב בקהלה."},{"i":42845,"n":"קלמן הכהן מפפד\"מ","b":"מחכמי פפד\"מ-שכה, תמך אך לא חתם לצד ר אליעזר טרוויש וחכמי פפד\"מ על מכתב לרבני שוואבן בנוגע למחלוקת בין ר שמעון גינצבורג בתמיכת ר יצחק איזיק גינצבורג לבין ר נתן שאטין בתמיכת ר אליעזר טרוויש מפפד\"מ - בגלל שיש לו שייכות בדבר."},{"i":42846,"n":"קלמן הנסתר","f":"יעקב הנסתר","b":"אחיו של האדמור ר אהרן הגדול מקרלין. לימד את אחיינו ר אשר מסטולין, ואת ר אורי מסטרליסק."},{"i":42847,"n":"קלמן יצחק מבלזיץ","k":"אדמור מבלזיץ","dt":"תרכא","b":"תלמיד החוזה מלובלין, ר יצחק משה עזריאל מבלזיץ. אדמור בבלזיץ-תקצא."},{"i":42848,"n":"קלמן מאיזנשטט","b":"רב באייזנשטט-ת\"א"},{"i":42849,"n":"קלמן מבריסק","b":"פרוש,מקובל בבריסק-ש\"כ"},{"i":42850,"n":"קלמן מהאלוסק","b":"רב בהאלוסק"},{"i":42851,"n":"קלמן מוילנא","b":"מגדולי חכמי ווילנה-תק\"ל"},{"i":42852,"n":"קלמן מוילנא","f":"ישכר בר-אחי הגר\"א","dt":"תקפב","dp":"וילנא","b":"חתן ר צבי הירש אב\"ד פאדקמון."},{"i":42853,"n":"קלמן ממרפורק","b":"מגדולי רבני אשכנז,רב במרפורק-ר\"י"},{"i":42854,"n":"קלמן מעדנבורג","b":"רב בעדנבורג-קצ\"ט"},{"i":42855,"n":"קלמן מפינסק","f":"יוסף חסיד קוידנבר","b":"רב בפינסק"},{"i":42856,"n":"קלמן מפרשבורג","f":"יחיאל מיכל משטאפי","b":"מחכמי פרשבורג-תצא ומחברי החברא קדישא."},{"i":42857,"n":"קלמן מפרשבורג","f":"לאזל","b":"מחכמי פרשבורג, חתם-תקכה על תקנות החברא קדישא."},{"i":42858,"n":"קלמן צבי מלאדזין","dt":"תקכח - י כסלו","b":"עק\"ה,רב בלאדזין"},{"i":42859,"n":"קלמן שולמאן ב\"ר ירוחם פישל","dt":"תרנט","b":"סופר עברי בזמן ההשכלה שומר אמונים לדת ישראל לא רצה לתרגם את ספרו של גרץ לעברית כי לא היה שלם לגמרי בדת ישראל","bk":[["ארץ הקדם - תולדות אנשי ארץ הקדם",""],["דברי ימי עולם",""],["מחקר ארץ רוסיא",""],["צבי לכל הארצות - חיבת ארץ ישראל",""],["שפה ברורה - יופי הלשון העברית",""],["תולדות חכמי ישראל",""]]},{"i":42860,"n":"קלמן, אודון מיאס-באראני","b":"רב ניאולוגי ביאס-באראני-תרעא, ולאיוש קון על מקומו אחריו, רב בבאניא. פרסם מאמרים על תולדות התישבות היהודים במקום, ובחכמת ישראל."},{"i":42861,"n":"קלמן, אודון מקו-באניא","dt":"1950","b":"רב הקהילה הניאולוגית בקו-באניא-ליד-1921 בודפשט. חיבר \"איוב בפירושים של ימי הבינים\". תרגם את שיר השירים להונגרית. ניצל מהשואה, ואחריה ראש איגוד הרבנים הניאולוגים בהונגריה-1947. מורה בביהמ\"ד לרבנים בבודפשט."},{"i":42862,"n":"קלמן, אלתר מוישניובטשיק","f":"[יהודה מטרנירודה]","b":"חסיד הוסיאטין. תלמיד ר צבי הירש תאומים מחרסקוב. רב בוישניובטשיק, בנו ר יצחק על מקומו אחריו."},{"i":42863,"n":"קלמן, יהודה","f":"חנוך הניך מיאנוב","b":"תלמיד ר יוסף מימפולה. רב בטרנירודה (ליד סקלט)-תרלה."},{"i":42864,"n":"קלמן, יצחק מוישניובטשיק","f":"משה מוישניובטשיק","k":"בעל מורשת אבות","bt":"תרכז","bp":"מזריבקו (גליציה)","dt":"תרצד","b":"חתן ר זאב וולוויל מרדר מסקוריק. רב בוישניובטשיק על מקום אביו (והיתה מחלוקת בקהלה על כך - הוקם ב\"ד של גדולי גלציה בהשתתפות המהרש\"ם לדון בכך), הקים ישיבה ועמד בראשה. רב בפודהייץ (לאחר שגורש בזמן מלחמת העולם הראשונה) , וינה, עבר לארה\"ב-תרפה וכיהן כרב בג'מייקה (לונג אילנד). חיבר \"מורשת אבות\" ניו יורק תשלד."},{"i":42865,"n":"קלמן, מרדכי מטרנירודה","f":"[יהודה]","b":"רב בטרנירודה. תשובה אליו במהרשם."},{"i":42866,"n":"קלמן, משה מוישניובטשיק","f":"יהודה מטרנירודה","dt":"תרסה","b":"תלמיד המהרשם. רב בוישניובטשיק-תרמד, בנו ר יצחק על מקומו אחריו."},{"i":42867,"n":"קלמן, צבי יהודה מוישניובטשיק","f":"יצחק מוישניובטשיק","bt":"תרנו","bp":"וישניובטשיק","dt":"תרצו","b":"תלמיד ר מאיר ארק בוינה. חתן ר משה פיש מדינוב (נכד הבני ישכר). רב בוינה לצד אביו. עבר לקנדה-תרפח וכיהן כרב בטורונטו."},{"i":42868,"n":"קלמנוביץ, אברהם מארה\"ב","f":"אהרן אריה ליב מדאניפ","bt":"תרנא-ב","bp":"דלטיץ=דעליאטיץ-פלך מינסק","dt":"תשכד - ב אדר","b":"תלמיד ישיבות זוועהיל, איישישוק, סלובודקה, טלז. רב בראקוב-תרעג, טיקטין-תרפט וראש ישיבה שם. נשיא \"אגודת ישראל\", וישיבת מיר. ממקימי \"ועד ההצלה\" - עסק בהצלת ישיבת מיר לוילנא ולשנחאי. חבר מזכירות מועצת גדולי התורה יחד עם ר מנחם זומבא, ורי\"מ בידרמן. עבר לארה\"ב-תש, ראש ישיבת מיר בארה\"ב. ממיסדי \"אוצר התורה\" לחיזוק עולם התורה במרוקו יחד עם יצחק שלום ויוסף שמאע. בשליחות במרוקו ופעל להקמת ישיבות במרוקו ובצרפת."},{"i":42869,"n":"קלמנוביץ, אהרן אריה ליב מליטא","f":"אשר","k":"בעל לב אהרן","bt":"תרכח","bp":"לובטש-פלך מינסק","dt":"תשח - כ אייר","dp":"ירושלים","b":"תלמיד ישיבת נוברדוק וכונה בשם \"המתמיד מלובטש\", וכולל האברכים בקובנה. חתן ר ישראל יצחק קומיץ מלובטש(=לויבטש). רב בדידקוביץ(=דיקאוויץ)-פלך וואהלין-תרנח, בראשי(=באראשי)-ווהלין-תרסב, אניפאלי-תרפ, עלה לירושלים-תרצד. חיבר \"לב אהרן\", \"לב אריה\". בנו - ר אברהם-ראש ישיבת מיר."},{"i":42870,"n":"קלמנוביץ, זליג הירש","bt":"1881","dt":"1943","b":"תלמיד המכון לשפות המזרח בפטרבורג. חבר ב\"חרות\" - אגודה ציונית סוציאליסטית בראשות נ. סירקין. מרצה לספרות אידיש באונ' העממית היהודית בקיוב. מורה לספרות ותנ\"ך בגימנסיה העברית בפוניבז, עבר לקובנא, וילנא והיה מנהל ב\"ייווא\". פרסם מאמרים ומחקרים על נושאים שונים, ותרגם עשרות ספרים לאידיש, ובהם \"מלחמות היהודים\" - \"אידישע מלחמות\" ליוסף בן מתתיהו. המשיך לפרסם גם בזמן השואה בגיטו וילנא. נספה בשואה."},{"i":42871,"n":"קלמנס, יוסף צבי הלוי מיפו","f":"אברהם הלוי","k":"בעל בכורי ציון","r":"רבה של יפו","bt":"תרלב-ד","bp":"סלובודקה","dt":"תשך","b":"עלה לארץ-תרנא, תלמיד ישיבת ר מרדכי גימפל יפה ביהוד. חתן ר נפתלי הרץ הלוי - רבה של יפו, רב ודיין ליד חותנו ביפו, כשהתמנה הראי\"ה קוק על מקום חותנו כיהן לצדו כאב\"ד יפו. ממיסדי ישיבת \"אור זורח\" ביפו, וישיבת מאה שערים בירושלים, ממיסדי ביהכ\"נ הגר\"א בתל אביב. ממקימי הרבנות המאוחדת ואיחוד השחיטה בין אשכנזים וספרדים ביפו. חיבר גם \"זרע הארץ\", \"אמירה נעימה\", ועוד.","bk":[["תורת השביעית",""],["אמירה נעימה",""],["ביכורי ציון",""],["הוראות שעה",""],["השקפה לברכה",""],["ותאמר ציון",""],["זרע הארץ",""],["טיב קידושין",""],["כרם הארץ",""],["עשר תעשר",""],["תורת הרכבה",""],["תורת שמיטת כספים ופרוזבול",""],["נטע הארץ",""]]},{"i":42872,"n":"קלמנקש, אברהם - הזקן","b":"רב וראש מדינה בלובלין. בניו: ר יוסף מלובלין ור אליהו."},{"i":42873,"n":"קלמנקש, אברהם - הנכד","f":"אליהו","dt":"תיב - י אב","dp":"קראקא","b":"חתן ר שלמה קצנלנבוגן. דיין וספרא דמתא בקרקא אצל התוי\"ט."},{"i":42874,"n":"קלמנקש, אליהו מלבוב","f":"אברהם מלובלין","k":"בעל אדרת אליהו","dt":"שצו - ט ניסן","dp":"לבוב","b":"רב באפטא, לבוב-שץ על מקום ר קופל הכהן-שץ. חיבר \"אדרת אליהו\" - בכתב יד. נפטר באמצע דרשת שבת הגדול. חתם-שצז עם ר אהרן קלונימוס גראפין, ור אהרן לוריא. הסכים על \"אור חדש\"-שצו עם בעל הב\"ח ור שלמה בן יצחק סגל, על ספר הזכרון לר יצחק שפירא, נזכר ב\"ברכת המים\" אודות גט שסידר. בנו ר אברהם דיין אצל התוי\"ט בקראקא - והיה חתן הגביר ר זלמן ר יעקב וואהלש. אחיו - ר יוסף מלובלין."},{"i":42875,"n":"קלמנקש, אריה ליב","f":"יוסף קלמנקש","b":"בנו - ר אשר יעקב בעל אשל אברהם."},{"i":42876,"n":"קלמנקש, אשר יעקב אברהם מלבוב","f":"אריה ליב","k":"בעל אשל אברהם","dt":"תמא - טו סיון","dp":"לבוב","b":"מקובל, דיין בלמברג. חיבר \"אשל אברהם\" אמשטרדם תיב, \"מעיין החכמה\"."},{"i":42877,"n":"קלמנקש, בנימין מלבוב","f":"יהודה ליב","k":"בעל הנהגת הבית","dt":"תמט-סט - ז שבט","dp":"לבוב","b":"ר\"מ בלבוב. בנו - ר יהודה ליב מאיידליץ."},{"i":42878,"n":"קלמנקש, יהודה ליב מאידליץ","f":"בנימין מלבוב","b":"רב באיידליץ-ת\"ע"},{"i":42879,"n":"קלמנקש, יוסף יוסקי מלובלין","f":"אברהם מלובלין","bt":"רפז","dt":"שצז - א תשרי","dp":"פרג","b":"רב בלובלין, ביהם, פרג. הסכים על \"גלילות ארץ ישראל\" לר אליעזר הלוי איידליש מפרג. מובא ב\"איתן האזרחי\". ובספר תלמידו \"ברכת טוב\" - ונציה שצז. נפטר בגיל 110!"},{"i":42880,"n":"קלמנקש, מרדכי","b":"רב-שנת ת\"פ"},{"i":42881,"n":"קלמנקש, קאפל מלבוב","b":"רב בלבוב-שמז. מצאצאיו - ר אליעזר בעל שו\"ת השיב רבי אליעזר, ושם יחוסו."},{"i":42882,"n":"קלמנקש, קאפל מנייוויט","k":"בעל השיב ר אליעזר","dt":"תל - כא טבת","b":"רב באדטרווצי,נייוויט והמדינה"},{"i":42883,"n":"קלמס, דוד משה ממוסקבה","f":"יעקב ממוסקבה","b":"תלמיד ישיבת סלובודקה, נשלח ע\"י ר נתן צבי פינקל-הסבא מסלובודקה ליסד את ישיבת ר איסר זלמן מלצר בקלצק. רב במוסקבה."},{"i":42884,"n":"קלמס, יעקב מליטא","f":"דוד","bt":"תרמ","bp":"ז'וסלי","dt":"תשיג - כ טבת","dp":"ירושלים","b":"תלמיד ישיבות וילנא, קובנא. רב בפושאלט-תרסד, סאלוק-תרע, בוגורצקי(=בוגורודסק), מוסקבה-תרפו ופעל משם במסירות נפש להצלת נפשות ולחינוך יהודי תחת השלטון הקומוניסטי, עלה לירושלים-תרצד, חבר הרבנות הראשית, נשיא ועד העזרה לרבנים פליטי רוסיה. מייסד שכונת הרבנים ברוממה-ירושלים. הניח חדושים בכת\"י."},{"i":42885,"n":"קלמפמן, אברהם ברוך משיבאט","b":"גביר מחכמי שיבאט. חתנו - ר חיים יונה איטקין משיוינשוק."},{"i":42886,"n":"קלמפר, אנשיל","b":"הגהות ממנו על טור יו\"ד-תקעב בערך."},{"i":42887,"n":"קלמפרר, גימפל מטאבור","f":"יהודה","k":"בעל חיי יהונתן","bt":"תקעה","bp":"פרג","dt":"תרמד - א שבט","dp":"טאבור","b":"תלמיד החת\"ס, ר נחום טרעביטש מנקלשבורג ור יהודה ליב גלוגא מפרג, ור אליהו בונצלפדר שהיה גם חותנו. רב בטאבור-תרד. חיבר \"חיי יהונתן\" לתולדות ר יהונתן אייבשיץ בלשון אשכנז. ?? לא באוצר ??"},{"i":42888,"n":"קלמר פרומקין, שמואל","f":"יעקב ניישטטר","dt":"תרכז - יז אלול","b":"מרביץ תורה,עלה לירושלים-תריח וחזר לליטא-תרכא, עלה שנית-תרכו."},{"i":42889,"n":"קלמר, ג' מצ'ונגארד","dt":"תשד","b":"רב בקהילה הניאולוגית בצ'ונגארד-1936. נספה בשואה."},{"i":42890,"n":"קלמר, יוסף מניו יורק","bt":"תרמג","dt":"תשכג - כא שבט","b":"רב בלעטיציב,ניו יורק(ארה\"ב)-תרפ\"ח"},{"i":42891,"n":"קלמר, יעקב מסוגינד","b":"רב בסוגידה(=סוגינז). בניו - ר אליהו מקאליש, ר שמואל, ונכדו - ר אריה ליב פרומקין."},{"i":42892,"n":"קלמר, שמואל מירושלים","f":"יעקב ניישטטר","bt":"תקנז","bp":"ניישטט-טאוריג","dt":"תרכז - יז אלול","dp":"ירושלים","b":"מצאצאי החכם צבי ור מרדכי יפה בעל הלבושים. אחיו של ר אליהו רגולר. חתן ר אריה ליב ברוידא מקלם. רב בקאליש. חובב חכמת ישראל ובקי בדקדוק. עלה לירושלים-תריח. הניח כתבים על הש\"ס, קונטרס על ה\"שאגת אריה\", ועוד. בנו ר אריה ליב פרומקין בעל \"תולדות חכמי ירושלים\". חתניו: ר דב מרדכי מלוקניק, ר בנדט-נכד ר שמואל חסיד מראסיין, ר נפתלי איוונסקי, ר הלל מסלובודקה, ר יונה שלאם, ואחיו ר אריה ליב שלאם."},{"i":42893,"n":"קלמר, שמואל מקלם","b":"רב בקלם."},{"i":42894,"n":"קלנברג, אברהם יהודה מחרסקוב","f":"מרדכי מחרסקוב","bt":"תריט","bp":"סקלט","dt":"תשג","b":"תלמיד ר צבי הירש תאומים (המביאו בספרו \"ארץ צבי\"). רב בחצר האדמור מקופיטשניניץ. חתן ר יצחק קיבץ מסקלט. עבר לוינה בזמן מלחמת העולם ה-I, ואל בנו ר משה במיץ. נספה בשואה."},{"i":42895,"n":"קלנברג, חיים מרדכי מקופיטשיניץ","f":"משה ממיץ","bt":"תרסח","bp":"קופיטשיניץ","b":"רב בבלפורט (צרפת), בריסל, עלה לארץ-תשלט והתיישב בנתניה."},{"i":42896,"n":"קלנברג, משה ממיץ","f":"אברהם יהודה מחרסקוב","k":"בעל דרש משה","bt":"תרמב","bp":"סקלט","dt":"תשג","b":"חתן ר ישראל מרדכי טיטלבוים (חסיד הוסיאטין). תלמיד דודו ר אברהם יעקב מפרוביזנא. רב בקוטשערמארא, איבד את ספרייתו וכל כתביו בפלישת הרוסים (מלחמת העולם ה-I). רב בבודפסט, וינה, מיץ-תרפט. נספה בשואה - ונשתייר כתב יד של דרשותיו במחנה לא-לאנד (ליד טורס) לשם הוגלה. חיבר \"דרש משה\" בילגורי תרצה, ועוד."},{"i":42897,"n":"קלנברג, פנחס מבריסל","f":"משה ממיץ","bt":"תרעב","dt":"תשם","dp":"בריסל","b":"חזן ראשי בבריסל-תרצו, בתשיט הקים מערכת רבנות בצבא הבלגי. סופר ואמן. בידידות עם המלכה אליזבת."},{"i":42898,"n":"קלנג, דניאל מסארזע","dt":"תרצב - בערך","b":"רב בסמארזע (ליד טורקא)-תרפח."},{"i":42899,"n":"קלניגברג, מנשה יעקב מבריגל.","f":"חנוך הלל","b":"חתן מהרי\"א ספרין מקומרנא. רב בבריגל."},{"i":42900,"n":"קלנקוביץ, איזיק יעקב מדרוהיטשי","f":"יצחק שמריה הכהן","bt":"תרל","dt":"תשג","b":"רב בדרוהיטשין-פלך גרודנא-תרסג."},{"i":42901,"n":"קלנקוביץ, מרדכי מקראל","f":"אמ\"ת","b":"פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט. ?? - מי זה?"},{"i":42902,"n":"קלנר, אברהם הלוי מנאדי-קאועשע","dt":"תרסא","b":"אב\"ד נאדי-קאוועשעד. בנו ר קלונימוס שלום מטענקע - ניו גרסי."},{"i":42903,"n":"קלנר, אברהם יהודה מירושלים","f":"יוסף מפרשבורג","bt":"תרל","bp":"פרשבורג","dt":"תרעה - טו טבת","dp":"ירושלים","b":"תלמיד השב\"ס. חתן ר אליעזר מילר. עלה לירושלים. חתניו - ר זלמן חיים הומניר מירושלים ור פנחס דוד קליין מנהל כולל שומרי החומות בירושלים."},{"i":42904,"n":"קלנר, אברהם יצחק מטרנוב","b":"מעורכי \"תלפיות\" - טרנוב תרצח."},{"i":42905,"n":"קלנר, אברהם ממיאמי-ארה\"ב","f":"קלונימוס שלום מפאסיק","b":"רב במיאמי-פלורדיה."},{"i":42906,"n":"קלנר, יצחק מניר-באטור","f":"מרדכי","dt":"תשד - ג סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, ודודו ר יחזקאל בנט מסינער ואראלי. חתן ר משה גולדשטין מקאשוי. מחכמי ניר-באטור וכיהן כראש הקהלה. נספה בשואה."},{"i":42907,"n":"קלנר, מרדכי","b":"חתן ר גרשון בניצמין זאב וולף בנט מאונגוואר. גיסו של ר יחזקאל בנט מסניער-ואראלי."},{"i":42908,"n":"קלנר, קלונימוס שלום הלוי מטנקע","f":"אברהם מנאדי-קיוועשעד","bt":"תרמד","bp":"נאדי-קאוועשעד","dt":"תשיח - יג שבט","b":"תלמיד השב\"ס, ור מרדכי יהודה ליב וינקלר מהעדילא-מאדע. חתן ר יעקב שיק מנאדאודוואר. רב בטענקע--ליד גרוסורדין-תרע, (ניצל מהשואה) והיגר לאמריקה וכיהן כרב בפאסעיק-ניו גרסי. בנו - ר אברהם ממיאמי-פלורידה."},{"i":42909,"n":"קלעוואן, יהושע מליטא וארה\"ב","bp":"יאנישוק-ליטא","b":"היגר לארה\"ב וכיהן כרב בברלינגטון."},{"i":42910,"n":"קלעי, אברהם ירושלמי הקראי","f":"יאשיהו","k":"בעל אמונה אמן","b":"מחכמי הקראים-תעב בצופוט קאלע-קרים. חיבר גם \"שאול שאל\" על הלכות שחיטה\"."},{"i":42911,"n":"קלעי, אברהם מצפת וטבריה","dp":"טבריה","b":"ראש רבני צפת ואחר כך טבריה על מקום ר אלעזר ן יוחאי. נזכר בשו\"ת ר יוסף קארו, גם המבי\"ט מזכירו בתשובותיו, חתום בפסק המבוא בספר \"משפטי שמואל\" לר שמואל קלעי סימן עב."},{"i":42912,"n":"קלעי, אליהו מתורכיה","b":"גביר עשיר מחכמי תורכיה וסוחר אלמוגים ומצנפות, עלה לירושלים-שיח, ישב גם בצפת. אחיו של ר שמואל בעל \"משפטי שמואל\" ותמך בו. מתורתו בספר אחיו ואחרים מחכמי דורו. נשדד בדרכו ממצרים לארץ."},{"i":42913,"n":"קלעי, אליקים","b":"מרבני ארטא-ר\"מ"},{"i":42914,"n":"קלעי, אפרים מקלע-אלגיר","k":"בעל הגהות על הריף","bp":"קלעה חמאד","b":"תלמיד הרי\"ף, מגדולי חכמי דורו, מחכמי קלעה (יש אומרים קלעא איוב-ספרד וי\"א קלעא חמד-מרוקו - רבנו יונה מזכירו כר' אפרים הספרדי), (י\"א שהיה מרביץ תורה בצור-ד'תת\"פ - אבל כנראה זהו חכם אחר). תלמיד הרי\"ף באליסונה. חיבר השגות על הרי\"ף והביאם בעל המאור. תלמידו ר שלמה בן פרחון בעל מחברת הערוך - ומביא ממנו בספרו. לפעמים נזכר כר אפרים מקולינא והוא ט\"ס. חיבר גם פירוש לש\"ס (שמחה אסף - מאמרים לזכרון רצ\"פ חיות - וינה תרצג)."},{"i":42915,"n":"קלעי, ברוך משלוניקי","f":"שלמה","k":"בעל מקור ברוך","bp":"שלוניקי","dt":"שנז","b":"פוסק, מרביץ תורה, מחכמי טורקיה, תלמיד ר' אהרן ן' חסון, רב בסרדקופיס(=סידרוקאפסי), שלוניקי. חיבר שו\"ת \"מקור ברוך\". אחיו של ר מרדכי."},{"i":42916,"n":"קלעי, דוד מארטא","b":"רב בארטא(=ארטה), עלה לצפת-של."},{"i":42917,"n":"קלעי, חיים ליאון משלוניקי","f":"רפאל יהודה?","b":"מדפיס בשלוניקי-תקם יחד עם מרדכי נחמן."},{"i":42918,"n":"קלעי, יהודה רפאל ליאון משלוניק","k":"בעל פזמונים לטו בשבט","dt":"תקמב","dp":"שלוניקי","b":"מדפיס, עורך, דרשן, ומגיה, פייטן, מחכמי שלוניקי-תקמ. יסד בית דפוס-תקיד עם חברו מרדכי נחמן - והדפיסו כ-50 ספרים (האחרון שבהם \"מרכבת המשנה\"). חיבר שיר בלאדינו \"איס ראזון די אלאב'אר\" (שהיו שרים בחג שבועות), חיבר \"קומפלאס\" לט\"ו בשבט ונדפסו בתוך \"פרי עץ הדר\" שלוניקי תקם. בנו - ר חיים על מקומו אחריו כמדפיס."},{"i":42919,"n":"קלעי, יוחנן משלוניקי","f":"ליאון","k":"מהר\"י די ליאון","b":"דיין בשלוניקי-תצא, ורב-תקלד. הגיה ספרי \"בית דוד\", סופרו של ר יוסף דוד-מהרי\"ד כ-20 שנה."},{"i":42920,"n":"קלעי, יוסף הפייטן","f":"יעקב","b":"פייטן-שנות ה-ת'. מפיוטיו במחזורי טריפולי, רומא, רומניה, וגם בסדורי הקראים."},{"i":42921,"n":"קלעי, ליאון","b":"מחכמי איטליה. נספד ב\"באר יצחק\"."},{"i":42922,"n":"קלעי, ליאון משלוניקי וקושטא","b":"מדפיס בשלוניקי, עבר לקושטא-תקב לדפוס של בנימין בן משה רוסו."},{"i":42923,"n":"קלעי, מרדכי בכור משלוניקי","f":"שלמה","bt":"שטו","bp":"שלוניקי","dt":"תז - טו כסלו","dp":"שלוניקי","b":"תלמיד ר אהרן ן חסון, ר אהרן ששון ור יצחק פרנאקו. רב בשלוניקי וראש ישיבת \"פורטוגל יחייא\". מתלמידיו - ר דניאל אישטרושה, ר יהודה בנבנשתי, ר יוסף צרפתי, ר ידידיה קארו (נכד הב\"י), ר דוד קונפורטי, ועוד. הניח פסקים ונשרפו-שף. מפסקיו בספרי חבריו ובהם \"מקור ברוך\" לאחיו ר ברוך. בנו - שלמה - נפטר בחייו. גיסו - ר ישראל אבא."},{"i":42924,"n":"קלעי, משה משלוניקי","k":"בעל תפוחי זהב","b":"רב בשלוניקי"},{"i":42925,"n":"קלעי, משה משלוניקי","b":"דיין בשלוניקי-של."},{"i":42926,"n":"קלעי, פנחס מקושטא ושלוניקי","f":"יוחנן","b":"מדפיס בשלוניקי, עבר לקושטא-תקב לדפוס של בנימין בן משה רוסו."},{"i":42927,"n":"קלעי, רפאל יהודה משלוניקי","b":"יסד בית דפוס בשלוניקי-תקט, עם מרדכי נחמן, ובנו חיים ליאון על מקומו אחריו."},{"i":42928,"n":"קלעי, שלמה משלוניקי","b":"תלמיד ר דניאל אישטרושא. מחכמי שלוניקי, נפטר בחיי אביו."},{"i":42929,"n":"קלעי, שמואל מארטא-יוון","f":"משה","k":"בעל משפטי שמואל","bt":"רס-ע","bp":"טריקאלה-יוון או ונציה","dt":"שמה - בערך","b":"תלמיד ר חייא מאיר באיטליה, ר דוד הכהן(=הרד\"ך) בקורפו, ר בנימין בן שמריה. חתן ר בנימין בן מתתיה בעל \"בנימין זאב\". יצא עם חותנו לאיטליה בגלל המחלוקת, היה בונציה-רפה, ראב\"ד בארטא ור דוד וידאל על מקומו אחריו, ור שלמה ברוך - דיין בבית דינו, רב בוידין-שז, ליפאנטו וארטא, מו\"ץ בקהלת קיאנא בשלוניקי-שלד. חברם של רבני שלוניקי וקושטא המהרשד\"ם, ר יוסף טאיטצק, ור אברהם ירושלמי. מתשובותיו בספר חותנו \"בנימין זאב\". בניו: ר מתתיה, ר יעקב, וחתנו - ר שלמה בכ\"ר מתתיה."},{"i":42930,"n":"קלעי, שמואל מיאנינה - ב","b":"רב ביאנינה-של. קרוב משפחתו של ר שמואל קלעי מארטא ושלוניקי."},{"i":42931,"n":"קלעי, שמואל משלוניקי","b":"רב בשלוניקי. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא. מגיה בדפוס האחים בת שבע בשלוניקי-שנד."},{"i":42932,"n":"קלף, מאיר צבי מסלנט","dt":"תשג","b":"רבה האחרון של סלנט. נספה בשואה."},{"i":42933,"n":"קלף, מרדכי מסלנט","dt":"תשג","b":"רב בסלנט"},{"i":42934,"n":"קלפהולץ, חיים יעקב מירושלים","f":"ראובן","k":"בעל עקבי חיים","bt":"תרעה","bp":"ירושלים","dt":"תשכז","b":"תלמיד ר ישראל זאב מינצברג (ומוזכר בספרו) חתן ר יונה זאב הרשלר. בגלל פרנסתו יצא לארה\"ב (בעצת החזון איש) וישב ועסק בתורה בניו יורק. חיבר \"עקבי חיים\" ירושלים תשכט. בנו ר ראובן - משב\"ק המנחת יצחק. פרסם מאמרים ב\"תורת בית הוראה\" - ירושלים תשג - קובץ ישיבת רבנו חיים יוסף.","bk":[["עקבי חיים",""]]},{"i":42935,"n":"קלפהולץ, ישראל יעקב מבוכניה","k":"בעל נשמת ישראל","bt":"תרסט","bp":"בוכניה","dt":"תשמח","dp":"ירושלים","b":"חסיד בלז. תלמיד ר אלחנן וסרמן, ר אהרן קוטלר, והחפץ חיים. התיישב בבלז עצל האדמור המהרי\"ד. ניצל מהשואה ועלה לארץ. עסקן בחצר בלז. ערך \"נתיבות התורה\" בני ברק תשכב. חיבר \"נשמת ישראל\" בני ברק תשמט."},{"i":42936,"n":"קלפהולץ, ראובן","f":"מרדכי דוד מצאנז","dt":"תרצו","dp":"ירושלים","b":"חסיד צאנז. עלה לארץ ונרצח ע\"י פורעים ערבים."},{"i":42937,"n":"קלפטר, משה מנ\"י","b":"פרסם מאמרים ב\"דבר בעתו\" - פאקש תרסט. תשובה אליו מר משה סופר מטיסא-פירעד ב\"עמק הלכה\" - באטארקס תרפא."},{"i":42938,"n":"קלפי, יהודה מכיאו-יון","b":"מראשי הקהלה ומשמש כרב (לא רשמי) בכיאו-שנות ה-ש'. בנו - ר כלב."},{"i":42939,"n":"קלפי, כלב מכיאו-יון","f":"יהודה","b":"מראשי קהלת כיאו-שעג, ולאחר שהביאו לכהן כרב את ר משה הכהן מרודוס, כיהן כר\"מ בתלמוד תורה, יחד עם ר אלעזר הכהן מקושטא, ושלשת הרבנים ניהלו את קהלת כיאו."},{"i":42940,"n":"קלפפיש, אברהם מאיר מיבלונקה","f":"יעקב זאב מוארשא","dt":"תרכט - כה תשרי","b":"חתן ר יוסף חבר מיעדוובנע בעל \"בני יוסף\". רב ביאבלונקה."},{"i":42941,"n":"קלפפיש, אהרן יעקב מירושלים","b":"רב בשנאדאווא, ירושלים-תשה."},{"i":42942,"n":"קלפפיש, אהרן שלמה זלמן מויזנע","f":"יעקב זאב מוארשא","k":"בעל בית אהרן","b":"רב בוויזנע-תר\"נ"},{"i":42943,"n":"קלפפיש, אליעזר ליפא מלובעשוב","f":"שמריה יוסף","bt":"תרלח","b":"מצאצאי מהר\"ם פאדובה. נכד ר יעקב זאב מוארשא. תלמיד ישובות טלז, וולוזין. חתן ר אריה ליב בן ר יצחק מלובאשוב. ראב\"ד בלובאשוב(=לובעשאוו)-פלך מינסק-תרסז. נסמך מאת: ר שלמה הכהן מוילנא, ר רפאל שפירא מוולוזין, ר חיים הרץ מביאליסטוק, רה\"נ הארינבלס מוארשא."},{"i":42944,"n":"קלפפיש, יעקב זאב מוארשא","b":"רב בוורשה-תרך. בניו - ר שמואל זנויל, ר אהרן שלמה זלמן בעל \"בית אהרן\"."},{"i":42945,"n":"קלפפיש, יצחק מליביטש","f":"מרדכי מוארשא","bt":"תרלז","b":"תלמיד זקנו ר שלמה זנויל מוארשא. מו\"צ בוארשא-תר\"ס, רב בליביטש-פלך פלאצק-תרסד. נסמך מאת: ר אליהו חיים מייזל, ר מאיר יחיאל האלצשטוק מאסראיוצע, ר אברהם בורנשטין מראוונא, ר ירמיאל ישעיה מינצברג מליקאייע, ר פתחיה הארינבלאס מוארשא."},{"i":42946,"n":"קלפפיש, מרדכי מוארשא","f":"שמואל זנויל מוארשא","bt":"תריז","dt":"תרצ - ח כסלו","b":"מו\"צ בוארשא-תר\"נ"},{"i":42947,"n":"קלפפיש, שמואל זנויל מוארשא","f":"יעקב זאב מוארשא","bt":"תקפה","dt":"תרסב - ו חשון","b":"תלמיד ר משה ליב זילברברג בלאסק. ממלא מקום הרב בוארשא-תרלג (למעשה הרב בפועל)."},{"i":42948,"n":"קלפפיש, שמריה יוסף מוארשא","f":"יעקב זאב מוארשא","b":"גיסו של ר יעקב גזונדהייט מוארשא. דיין בוארשא-תרן. בנו - ר אליעזר ליפא מלובשוב(=לובאשוב). מחותניו: ר בנימין בינוש מויערשוב, ר יהושע השל מסטושין, ר ישראל יעקב מפלונסק, ר יעקב אריה ליב מדלובעשוב."},{"i":42949,"n":"קלפרא ישראל שמואל בן שלמה","bt":"1560","dt":"ה'ת 1640","bk":[["חקי דעת",""],["חקי חיים",""],["חקי משפט",""],["ישמח ישראל",""],["שלחן ערוך מטור אורח חיים עם פירוש חקי חיים",""]]},{"i":42950,"n":"קלצון, יוסף מצרפת","f":"ברוך","bp":"קלצון","dt":"ד'תתקצה -לפני","b":"מחכמי צרפת. נמנה על בעלי התוספות והיה זמן מה בפריס, עלה יחד עם אחיו ר מאיר עם ר שמשון משאנץ לארץ ישראל בד' תתקעא (1211), ועבר דרך מצרים שם פגש את ר אברהם בן הרמבם. בירושלים פגש את ר יהודה אלחריזי המזכירו בספרו. מופיע כמה פעמים בתוספות כר' יוסף איש ירושלים."},{"i":42951,"n":"קלצון, מאיר מצרפת","f":"ברוך","bp":"צרפת","b":"מבעלי התוספות, עלה עם אחיו ר יוסף בשיירת 300 העולים בשנת ד'תתקע (1211). ר אברהם בן הרמבם מזכירו באגרתו. פגש את ר יהודה אלחריזי בירושלים."},{"i":42952,"n":"קלצקו, יהודה יוליאן","f":"צבי הירש","bt":"1828","bp":"וילנא","dt":"1906","dp":"קרקוב","b":"נחשב לילד פלא, בגיל 13 חיבר שיר \"מנחת תודה\" לכבוד הוריו. תלמיד אוני' הידלברג. עבר לפאריס והתנצר, הו\"ל עתון פולני-1858, הוזמן ע\"י ממשלת אוסטריה להיות חבר במועצת המינסטריון לעניני חוץ. חבר בלנדטאג-גליציה. חיבר ספרים בפולנית וצרפתית."},{"i":42953,"n":"קלצקו, צבי הירש","bt":"1790","bp":"וילנא","dt":"1856","b":"מראשי הקהלה בוילנא. ביקר בגרמניה ופגש רבים מחכמי היהודים ובהם צונץ, פרידלנדר, ועוד. מקורב לפקידות הממשלתית הרוסית. ביתו היה בית ועד למשכילים ונכבדים יהודים, רוסים ופולנים. ממיסדי ביה\"ס החילוני הראשון בוילנא יחד עם ניסן רוזנטל. מימן את הדפסת \"אהבת ציון\" למאפו. אשתו טויבה שלטה בשפות רבות."},{"i":42954,"n":"קלצקי, אברהם ברוך מוילנא","f":"בנימין","bt":"תקעה","bp":"ליובטש-ליד נווהרדוק","dt":"תרמח - ה טבת","dp":"וילנא","b":"נכד-אבי אמו ר מנחם מנדל מאלשאן, ור ליבוש מליובטש. גיסו-אח אשתו של ר יעקב קלצקי מוילנא, ונשלח לשם לצורך לימודיו בוילנא. חתן הגביר ר יוסף גורדון. סירב לרבנות והתפרנס מחותנו ואח\"כ מעסקי אשתו. ר\"מ בהתנדבות בבימ\"ד יסו\"ד בוילנא. הניח הגהות וחדושים לש\"ס - בכת\"י. בקי בחשבון ואמר כי \"מי שאינו עוסק בחכמת החשבון אינו ראוי להיקרא אדם...\". מבניו: ר בנימין נפטר בחייו, ר לוי ירחמיאל מאודסה שהדפיס מכתבי אביו בתוך \"ערך תפלה\"."},{"i":42955,"n":"קלצקי, אהרן מוילקומיר","dt":"תרסז - לפני","b":"רב בוילקומיר."},{"i":42956,"n":"קלצקי, אליהו מברעזי","b":"פרסם מאמרים ב\"שמעתתי דרבנן\" - אודסה תרמז."},{"i":42957,"n":"קלצקי, אשר הרץ מוילנא","f":"קלונימוס קלמן","bt":"תקנז","dt":"תרכו - א ניסן","b":"אחיינו של ר ישכר בר-אחי הגר\"א. דיין בוילנא-תקצח. הגר\"א השתתף בפדיון הבן שלו-ערב יוה\"כ תקנח."},{"i":42958,"n":"קלצקי, אשר מוילנא","f":"יצחק איזיק מוילקומיר","dt":"תקפא - א חשון","dp":"וילנא","b":"חתן ר יצחק מפומפיאן בן ר מאיר. מחכמי וילנא. בניו: ר מרדכי מלצר - ראש ישיבת מייליס בוילנא, ר דוד - ר\"מ בישיבת ממייליס, ר שלמה משוינצאן."},{"i":42959,"n":"קלצקי, בנימין וולף מוילנא","f":"שלמה זלמן","k":"וועלוויל ליבע גיטעלס","dt":"תרט - יב טבת","dp":"וילנא","b":"נכד ר בנימין וולף בן ר אשר גינצבורג. חתן ר אהרן-אחי ר גרשון אמשטרדם, ובזיוו\"ש חתן ר אהרן טייביל'ס. גבאי ישיבת מייליס בוילנא. חתם על כתב התמנות ר ישראל סלנטר לראש הישיבה, על מקום ר מרדכי מלצר."},{"i":42960,"n":"קלצקי, בנימין וולף מוילנא - ב","f":"שמעון מוילנא","k":"ר וועלוועלע ר אשר'ס","bt":"תקמח - אחרי","dt":"תרלז - כח סיון","b":"נקרא ע\"ש דודו בעל אותו השם. נכד ר אשר גינצבורג. לאחר שנתייתם גדל אצל חתן אבי זקנו - ר ישכר בער-אחי הגר\"א. גביר מחכמי וילנא. חתן ר ישכר בער-אחי הגר\"א. בשנת תקנח היה הגר\"א בטקס פדיון בנו של ר קלמן-אחיינו של ר ישכר בר-אחי הגר\"א (הבן ר אשר הרץ קלצקי מוילנא) ור ישכר בער הציג את ר בנימין וולף בפני הגר\"א ואמר לו כי הוא עומד להיות חתנו וביקש ברכה - הגר\"א ברכו - והיה האחרון שזכה להתברך מפי הגר\"א."},{"i":42961,"n":"קלצקי, גרשון מוילנא","f":"שלמה הכהן","dt":"תרכד - טז שבט","b":"חתן ר יוסף בן יואל אוירבך, ובזיוו\"ש חתן ר שמואל שפירא, ובזיוו\"ש חתן ר צבי הלוי אפשטין. גביר מחכמי וילנא. לאחר שפרש מעסקיו נתמנה למורה לתלמוד בביהמ\"ד לרבנים. מחדושיו ב\"טורי אבן\" - קונטרס אחרון - תקצו. מבניו: ר יוסף מאיר, שלשת בניו נפטרו בחייו וכן בנותיו. נכדו - ר שבתי שעפטיל הכהן המכונה הר\"ש קלצקי רב מטעם בוילנא."},{"i":42962,"n":"קלצקי, דוד מוילנא","f":"אשר מוילנא","dt":"תריח - ז אב","b":"דיין בוילקומיר,ר\"מ בישיבת מייליס בוילנא יחד עם אחיו ר מרדכי ראש הישיבה."},{"i":42963,"n":"קלצקי, חיים מוילנא","f":"שמואל יהודה'ס","dt":"תרלח - כח טבת","b":"חתן ר יחזקאל הלוי לנדא מוילנא. גביר מחכמי וילנא. ראש הגבאים בבימ\"ד הגר\"א. בניו ר אברהם-חתן ר יוסף משה בן ר חיים רוטנר, ר ליב חתן ר מרדכי צבי גרודזנסקי מקאלואריא. חתניו: ר משה פינקלשטין מבריסק, הגביר ר זלמן הורביץ מקפוסט."},{"i":42964,"n":"קלצקי, יוסף יהודה יוליוס","f":"הרש","k":"בעל שולמית","dt":"1908","b":"בגיל 13 חיבר \"מנחת תודה\" ובו שירים להוריו. תלמיד רש\"י פין. חיבר שירים גם בפולנית. עבר ללמוד בקניגסברג. המיר את דתו ושינה שמו ליוליוס ועבר לצרפת ואוסטריה והיה יועץ מדיני."},{"i":42965,"n":"קלצקי, יעקב מוילנא","f":"ברוך פרנקפורטר","k":"יעקב קאסירער","dt":"תרז","dp":"ולקוביסק","b":"חתן הגביר ר ליבוש בן יעקב פרץ קלצקי. מחכמי וילנא. בנו ר ברוך מרדכי ליפשיץ מסמיאטיש, ולקוביסק, נוברדוק ושדליץ."},{"i":42966,"n":"קלצקי, ישכר בער מוילנא","f":"אשר","dt":"תרלא - ב כסלו","dp":"וילנא","b":"נינו של ר ישכר בער-אחי הגר\"א. חתן ר חיים הכהן מביעלסק. גביר מחכמי וילנא. החזיק בכת\"י זקנו ר ישכר בער - צוף דב\"ש."},{"i":42967,"n":"קלצקי, לוי ירחמיאל מאודסה","f":"אברהם ברוך מוילנא","k":"בעל ערך תפלה","bt":"תר","bp":"וילנא","b":"בקי בתורה והשכלה ובחכמת החשבון. התישב באודסה והיה מורה בת\"ת ומבקר ספרי ישראל שם. חיבר \"ערך תפלה\" וילנא תרכט - ובו על נוסח התפלה כוונותיה ודקדוקיה ובו מחדושי אביו, \"תלמוד תורה\", \"ראשון לחנוך\", ועוד. ספרו \"ערך תפלה\" זכה להערכה מצד חכמי וילנא ובהם ר מרדכי פלונגיאן, ר מתתיהו שטרשון, ועוד."},{"i":42968,"n":"קלצקי, ליבוש מליובטש","f":"יעקב פרץ","dt":"תקעו - ד תשרי","dp":"ליובטש","b":"חתן קרובו ר שמחה מליובטש. גביר מחכמי ליובטש. בנו ר בנימין מליובטש."},{"i":42969,"n":"קלצקי, מרדכי מוילנא","f":"אהרן יהודה ליב","dt":"תרב - ט ניסן","dp":"וילנא","b":"שינה שמו מגינצבורג. גביר בוילנא. מחותנו ר משה הלוי רוזנטל."},{"i":42970,"n":"קלצקי, שבתי שעפטיל מוילנא","f":"יוסף מאיר מוילנא","b":"נכד ר גרשון בן שלמה הכהן קלצקי מוילנא. תלמיד ביהמ\"ד לרבנים בוילנא. רב מטעם בוילנא. בשליחות-תרמה קהילת וילנא לפטרבורג עם ר אברהם קאראסיק ור מאיר גורדון לברך את הקיסר אלכסנדר השלישי בשם קהילת וילנא."},{"i":42971,"n":"קלצקי, שלמה משונציאן","f":"אשר מוילנא","b":"רב בשווינציאן"},{"i":42972,"n":"קלצקי-מינץ, הרש מוילנא","f":"אהרן מינץ","dt":"תרטז - טז כסלו","dp":"וילנא","b":"חתן גיסו ר שמואל יהודה'ס ושינה שמו ממינץ לשם חותנו קלצקי. גביר מחכמי וילנא, גבאי צ\"ג על מקום חותנו, ומפקח בית הספר לנערי ישראל. סייע לר משה טננבוים בעל \"מטעי משה\" בהדפסת חומש עם באור רמ\"ד (מנדלסון). חתנו - ר גדליה טיקטין אב\"ד ברסלוי. בנו יהודה."},{"i":42973,"n":"קלצקין, אברהם מלוזנא","f":"נפתלי הרץ משימברג","b":"רב ברומנוב, ליאזני-תרע."},{"i":42974,"n":"קלצקין, אליהו","f":"יעקב וילנא","b":"רב בדניבורג"},{"i":42975,"n":"קלצקין, אליהו מלובלין וירושלים","f":"נפתלי הרץ משימברג","k":"בעל אבן הראשה","bt":"תריב","bp":"אושפול","dt":"תרצב","dp":"ירושלים","b":"תלמיד ביהמ\"ד פרושים באיישישוק. חתן ר נחמן יעקובזון משקלוב, ובזיוו\"ש חתן ר ברוך מרדכי ליפשיץ מסמיאטיץ וולוקוביסק. היה עילוי כבר בנערותו וכך העיד עליו המלבי\"ם בנוגע לקונטרס שכתב בגיל 14 אודות דרך לימוד דרכי התנאים, רב בקארטוז-בריוזה(=ברעזי)-תרמא, מאריאמפול-תרנד, לובלין-תרע, עלה לירושלים-תרפח, וכיהן כאב\"ד אצל ר יוסף חיים זוננפלד. היה בקי בחכמות שונות שלט בשפות רבות והתענין באמנות ומוסיקה. השיב לכל התפוצות. מספריו: \"אבן הראשה\" ורשא תרמז, \"אמרי שפר\" ורשה תרנה ועוד עסק רבות בשאלות עגונות לאחר מלחמת העולם הראשונה. פרסם מאמרים ב\"אהל תורה\" - ירושלים תרפ\"ה, באר\" - זאמושץ-וארשא - תרפד, \"בית ועד לחכמים\" - לונדון תרסב, \"דגל הרבנים\" - וארשא תרפו, \"דגל התורה\" - וארשא תרפב, \"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט, \"קהילת יעקב\" - זבארוב-סלובקיה תרפה, \"קובץ דרושים\" - פיעטרקוב תרפג, \"שערי ציון\" - ירושלים תרפא, \"שערי תורה\" - קראקא תרפה."},{"i":42976,"n":"קלצקין, בוריס","bt":"1875","bp":"הורודושץ","b":"בן למשפחת 10 דורות של רבנים. הצטרף לאגודת פועלים, והיה ממיסדי \"ז'ארגאנישע קאמיטעטן\" להפצת תרבות בין הפועלים היהודים. ממיסדי \"וועקער\", פאלקס צייטונג\", ו\"די וועלט\". יסד הוצאת \"קלצקין\", עבר לוארשא ופעל בהוצאה לאור באידיש, וב\"ליטערארישע בלעטער\" בעריכת נחמן מייזל."},{"i":42977,"n":"קלצקין, חיים דב מיאנישוק","f":"ישראל איסר יעקב","b":"חתן הגביר ר אפרים קאהן. מחכמי יאנישוק."},{"i":42978,"n":"קלצקין, יהושע מרדכי מראסיין","f":"ישראל איסר יעקב","bt":"תרכב","bp":"טלון-ליד פונוביז","dt":"תרפה - ח שבט","dp":"ליבאו","b":"חתן ר צבי הירש מה-יפית מוילקוביסק. רב בסויאדושץ, הורודוק, קארטוז-בריוזה(=קארטיזע-בערעזני), ראסיין-תרם על מקום ר משה סולוביציק, ליבאו. דרשן מפורסם. כתביו אבדו בזמן מלחה\"ע ה-I. מתורתו ב\"עמודי שש\" - הכולל דברי תורה מששת בניו הרבנים של זקנו ר נפתלי הרץ קלצקין."},{"i":42979,"n":"קלצקין, יעקב","f":"אליהו","k":"בעל משנת ראשונים","bt":"1882","bp":"קארטוז-בריוזה","dt":"1948","dp":"שוייץ","b":"אביו היה רב בכמה קהלות. תלמיד ישיבות ליטא, פנה להשכלה והיה תלמיד הרמן כהן. עורך \"די וועלט\". חיבר מסות פילוסופיות בעברית ובגרמנית. עורך קבצים וכתבי עת. ממיסדי הוצאת \"אשכול\". עורך ראשי של האנציקלופדיה היהודית בעברית ובגרמנית בברלין. עבר לשוייץ-1933, ארה\"ב. חיבר גם \"הרמן כהן\", ספר הרצאות שנשא עם מבוא מאת אלברט אינשטין, ועוד."},{"i":42980,"n":"קלצקין, יעקב קופל","dt":"תש","b":"רב בקרסלובה"},{"i":42981,"n":"קלצקין, ישראל איסר יעקב מליוונ","f":"נפתלי הרץ משימברג","bt":"תרה","bp":"אושפול","dt":"תרפא","dp":"ליונהוף","b":"רב באנשישוק(=אנושישוק, האנישישאק,אנעשיסיק)-פלך קובנא, ליווענהוף-פלך ויטבסק. נסמך מאת: הנציב מוולוזין, ר אליהו שיק מלידא, ר אריה ליב מדוינסק, ר יוסף רוזין-רוגצובר. מתורתו בספר אחיו ר אליהו \"דבר אליהו\", וב\"עמודי שש\". בניו: ר יהושע מרדכי מקארטיזע-בערעזני, ר מנדל מאבעל-פלך קובנא, ר חיים דב מיאנישוק. חתניו: ר מנדל לייען מנעוויל, ר מרדכי בן יעקב ליב, ר מיכל אדלשטין בן יצחק מרעזיצע, ר שמעון בן יחיאל יאחילמאן מריגא."},{"i":42982,"n":"קלצקין, משה צבי הירש מרומנובה","f":"נפתלי הרץ משימברג","k":"בעל לקוטי צבי","bt":"תרלב","b":"רב ברומנובה(=ראמאנאווא)-פלך מוהילוב-תרס, שימבורג על מקום אביו. נסמך מאת: ר יוסף רוזין-הרוגצובר, ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\", ר צבי דב לאטקער מהאמליא. חיבר גם הערות על התשב\"ץ, על התניא, ועוד - בכת\"י. החזיק בכתבי יד חשובים ובהם: דקדוקי עניות, שו\"ת לנוצרים, לקוטים מאת ר עמנואל חי ריקי, \"לחם יחזקאל\" לבעל \"כנסת יחזקאל\"."},{"i":42983,"n":"קלצקין, נפתלי הרץ משימבורג","f":"נתן","k":"בעל אילה שלוחה","bt":"תקפב-ג","bp":"דוינסק","dt":"תרנד - א שבט","dp":"שימבורג","b":"מצאצאי ר יעקב רישר ממיץ בעל \"חק יעקב\". תלמיד ר משה צבי הלפרין במינסק, בישיבת קרובו - ר מרדכי קלצקי-מלצר בוילנא, ישיבת החת\"ס-תקצז, ישיבת וולוזין אצל ר יצחק מוולוזין, ר יהודה ליב בטלן מדינבורג, ה\"צמח צדק\", ועוד. רב באופאל(=אושפול)-פלך קובנא-תרו או תריא, שימבורג-קורלנד-תריז כ-37 שנה. (סיפר כי בזמנו הגיעו צעירים רבים מליטא ללמוד אצל החת\"ס). סירב להצעת רבנות בפטרבורג ובמוסקבה. בנו הו\"ל מכתביו \"אילה שלוחה\", וששת בניו חיברו ביחד \"עמודי שש\". בניו: ר ישראל איסר מליוענהוף, ר ראובן מליוענהוף, ר דוד פינברג מניו יורק, ר אליהו מלובלין בעל \"אבן הראשה\", ר אברהם מלוזנא(=ליאזני)-פלך מוהילוב, ר שניאור זלמן מרוגצ'וב(=ראהטשאוו)-פלך מוהילוב, ר משה צבי הירש מרומנובה, ובנו גם - ר ראובן מליבנהוף."},{"i":42984,"n":"קלצקין, צבי הירש","b":"פרסם מאמרים ב\"כנסת הגדולה\" - וארשא תרן."},{"i":42985,"n":"קלצקין, שניאור זלמן מרוגצ'וב","f":"נפתלי הרץ משימברג","dt":"תרפט","b":"רב ברוגצ'וב(=רוגאטוב)-תרע. קונטרס ממנו בספר אביו."},{"i":42986,"n":"קלצקיר, זלמן מוילנא","b":"בשליחות קהלת וילנא להביא את כספי התרומות לצפת וירושלים-תקעט עם ר שמואל הוראדנר."},{"i":42987,"n":"קלקס, אלנתן מספרד","f":"משה","b":"מקובל מחכמי סרגוסה-ן'. חיבר \"לבנת הספיר\" בקבלה ובו מביא גם מספר הזהר (שאז התגלה) והאר\"י שבח את ספרו, \"אבן ספיר\" - ויכוח עם הקראים."},{"i":42988,"n":"קלקר, בנימין מראוונאיע","f":"מאיר יצחק","bt":"תרלא","b":"מו\"צ בטשעטשעלניק-פודוליה-תרסו, רב בראוונע(=ראוונאיע)-פלך חרסון-תרסח."},{"i":42989,"n":"קלקר, דוד מטשודנוב","f":"שמריה","bt":"תרכב","b":"מצאצאי בעל הסמ\"ע, ור שמרל וערחיווקער-תלמיד הבעשט. רב בטשודנאוו(=טשודנוב)-ווהלין-תרס. נסמך מאת ר משה מחמילניק."},{"i":42990,"n":"קלקר, נתן מקופנהגן","bt":"תקמח","dt":"תרכא","b":"חיבר \"קול בכי\", \"נטע שעשועים\", ועוד."},{"i":42991,"n":"קלר, אהרן מרדומישל","f":"מאיר","k":"בעל מטה אהרן","bt":"תרסט","bp":"רדומישל","dt":"תשנח","b":"תלמיד ביהמ\"ד לרבנים בברלין. רב בבויטן (שלזיה), עלה לארץ-תרצט. רב בנהריה-תשד. פרסם מאמרים ב\"הצופה\". חתן ר מרדכי סינזון. חיבר \"מטה אהרן\" נהריה תשמה."},{"i":42992,"n":"קלר, אהרן צבי משאמקוט","f":"עזריאל איזיק משאמקוט","bt":"תרך","bp":"שאמקוט","dt":"תרפח - ב אייר","b":"תלמיד ה\"חתן סופר\". חתן ר יעקב קופל ליכטנשטין מבעטלען ומארוש-ואשארהי. רב בואשארהי(=מאראש-ואשאר)-תרמג, טקנדורף. שמקוט(=נאדי-שאמקוט)-תרסד על מקום אביו."},{"i":42993,"n":"קלר, אליהו מפרוביזנא","b":"רב בפרוביזנא-תרפז."},{"i":42994,"n":"קלר, אליעזר מברזאן","f":"יעקב יונה מברזאן","k":"בעל חות אליעזר","bt":"תרכט","bp":"ברזאן","dt":"תשו","dp":"ירושלים","b":"תלמיד המהרש\"ם. חתן ר אשר זליג וייס מקריסנפולי. עלה לארץ-תרצו, והיה דיין בירושלים. חיבר \"חות אליעזר\" ירושלים תשיח."},{"i":42995,"n":"קלר, אריה ליב","b":"חתן אב\"ד חירוב-תרמו."},{"i":42996,"n":"קלר, טוביה מזבורוב","f":"ישראל קלאהר","b":"מחכמי זבורוב, פריס-תרן. תשובה אליו - \"בית יצחק\", \"יד מאיר\"."},{"i":42997,"n":"קלר, יצחק איזיק משומקוט","dt":"תרסד - כד תשרי","b":"רבה הראשון של שומקוט, ובנו ר אהרן צבי על מקומו אחריו."},{"i":42998,"n":"קלר, מנחם מנדל מטלוסט","b":"מחכמי טלוסט, תשובה אליו - \"בית שלמה\"-תרטו."},{"i":42999,"n":"קלר, מרדכי ליב מיגולניצה","b":"מחכמי יגולניצה - תשובה אליו \"בית שלמה\"-תרלב."},{"i":43000,"n":"קלר, משה אורי מצאנז","f":"שלום","k":"בעל ילקוט האורים","bt":"תרם","dt":"תשב","b":"תלמיד ר\"ש פירר ממילובקה. מחכמי צאנז-תרס ועסק במכירה והוצאת ספרים. חיבר \"ילקוט האורים\" צאנז תרסד. עורך קובץ \"אסיפת גדולים\" - קראקא-צאנז תרפז. פרסם מאמרים ב\"הפרדס\" - צאנז תרצא."},{"i":43001,"n":"קלר, משה אריה מקראקא","b":"מחכמי קראקא. תשובה אליו ב\"מחזה אברהם\"-תרסא."},{"i":43002,"n":"קלר, משה מרודניק","f":"שמואל אלימלך","bt":"תקנז","dt":"תרן","b":"רב ברודניק, עלה לצפת-תרכה. חתם משם בשנים תרלג-תרלד (מופיע ב\"כנסיה לשם שמים\" ו\"מעשה אבות\"). חתן נכדת החוזה."},{"i":43003,"n":"קלר, עזריאל איזיק משמקוט","f":"משה","dt":"תרסד - כט תשרי","b":"חתן ר אהרן צבי פריד ממארגרטן. רבה הראשון של שמקוט(=נאדי-שאמקוט)-תרך כ-44 שנה."},{"i":43004,"n":"קלר, שלום ממגרוב","b":"רב במגרוב, בוצאץ, שרנוב (ליד סטניסלב)-תרעד. פרסם מאמרים ב\"יגדיל תורה\" - פראגא-וארשא תרפז."},{"i":43005,"n":"קלר-מרתף, פנחס מטשרנטשין","b":"מראשי חברת \"אהבת ציון\" בפרשבורג. רב בטשרנשטין."},{"i":43006,"n":"קלרמן, אפרים מקראקא","f":"משה אליהו","bt":"תרלד","bp":"קראקא","dt":"תרפה","b":"נכד ר ליבר חריף קורנגולד, ור הרשל לנצהוטר. חתן הגביר ר הירש למלר מקולומיאה ועבר לשם. יו\"ר המועצה היהודית ונציגה בפני השלטון הרומני."},{"i":43007,"n":"קלרמן, חיים מרופשיץ","b":"רב ברופשיץ, זבנא-תרעד."},{"i":43008,"n":"קלרמן, משה מרדכי מדעש","b":"מיסד הישיבה בדעש-תרפט, יחד עם ר רפאל מרדכי פרידמן."},{"i":43009,"n":"קלרמן, שמואל","b":"גיסו של ר צבי הירש מייטשיס ואהל מירוסלב, ובזיוו\"ש חתן השר ר שאול ואהל מטורבין."},{"i":43010,"n":"קלרפלד, יהושע השל הכהן מיברוב","f":"[צבי הירש]","b":"מחכמי יברוב-תרמא."},{"i":43011,"n":"קלרפלד, יצחק אשר מקוזלוב","f":"אפרים נחום מקוזלוב","bt":"תרע","bp":"קוזלוב","b":"עתונאי, איש אגודת ישראל. עלה לארץ-תרצב. ממייסדי פא\"י. ערך גליון \"זכרון יעקב\"-תרצו. הוציא לאורמ קובץ \"לפידים\"-תשב. חתן ר שלמה אלטמן. בנו הסופר והעיתונאי - שלמה נקדימון."},{"i":43012,"n":"קלרפלד, משה אלעזר משטפנשט","k":"בעל ספיח קציר","bp":"דינוביץ-מורביה","b":"מצאצאי ר מאיר מרגליות בעל \"מאיר נתיבים\". משמש בקודש אצל האדמור משטפנשט. הו\"ל ספר זקנו \"מאיר נתיבים\" ברדיטשוב תרס."},{"i":43013,"n":"קלשינר, מרדכי מאדל","f":"שלמה","k":"בעל מאמר מרדכי","bt":"תקס","dt":"תרלב - יא אב","b":"תורה וגדולה במקום אחד,שתדלן בחצר השרים לפדיון שבויים"},{"i":43014,"n":"קמאדער, בנימין","dt":"תרכג - ה סיון","b":"תלמיד ר יואל צבי ראטה. נזכר ב\"תבואות השדה\"."},{"i":43015,"n":"קמאדער, שמואל","dt":"תקיח - יז טבת","dp":"ניקלשבורג","b":"תלמיד ר יואל צבי ראטה. אב\"ד דאראג. נזכר ב\"תבואות השדה\"."},{"i":43016,"n":"קמאי, אברהם צבי ממיר","f":"אליהו ברוך קמאי","bt":"תרך","bp":"שקוד","dt":"תשב - ח חשון","b":"רב בקידאן-עד תרעה, אב\"ד מיר-תרצה. זקן הגאונים בזמנו. נספה בשואה. פרסם מאמרים ב\"חידושי תורה\" - לודז תרצו - קובץ חבורת בני ישיבת מיר בלודז, \"מאסף דרושי\" - וילנא תרסט, \"תורה אור\" - שנחאי תשו."},{"i":43017,"n":"קמאי, אליהו ברוך ממיר","f":"אברהם מטלז","bt":"תר-תרד","bp":"שקוד או טלז","dt":"תרעז","dp":"מינסק","b":"נינו של ר אברהם-אחי הגר\"א. תלמיד וחתן אביו חורגו - ר חיים זאב יפה משקוד. רב בשקוד-תרכה על מקום חותנו, קרליץ-תרלח, ואקשנה-תרמה, צ'חנוביץ-תרמח, ר\"מ במיר על מקום ר חיים ליב טיקטינסקי (שהתעוור) ואב\"ד על מקום האדר\"ת. חתנו - ר אליעזר יהודה פינקל. חיבר חדושים ושו\"ת - בכת\"י. פרסם מאמרים ב\"בית ועד לחכמים\" - לונדון תרסב, חידושי תורה\" - לודז תרצו - קובץ חבורת בני ישיבת מיר בלודז, \"מאסף דרושי\" - וילנא תרסט. מאמר ממנו ב\"תלפיות\" - נ\"י תשד.","bk":[["רבי אליהו ברוך קמאי",""]]},{"i":43018,"n":"קמאי, צבי הירש ממיר","dt":"תשג","b":"רב במיר"},{"i":43019,"n":"קמאיקא, אשר מירושלים","f":"יוסף","dt":"תרכו - יט אלול","dp":"ירושלים","b":"עלה לירושלים-תריז. גביר מחכמי ירושלים. בנו - ר מאיר אניקסטר. נכדו - בעל \"חלקת מחוקק\"."},{"i":43020,"n":"קמאיקא, בערל מוילקוביסק","b":"רב בוילקובישק"},{"i":43021,"n":"קמאיקא, דב בריל מוילקוביסק","b":"דיין בוילקוביסק."},{"i":43022,"n":"קמאיקא, מאיר מליטא וירושלים","f":"אשר מאניקשט","k":"בעל אילה שלוחה","bp":"אניקשט","dt":"תרמה - ל סיון","dp":"ירושלים","b":"חתן ר משה מישל לוריא מקרקנובה, ועבר לשם, מחכמי אניקשט. עלה לירושלים-תרמב(או תריב-תרכב) והיה מחוג הפרושים בירושלים והיה מנהל כולל וילנא וז'אמוט. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה. אשתו רבקה - עלתה לארץ-תרכב, חברה קונטרס באידיש ותורגם לעברית בשם \"זכר עולם\" - ירושלים תרמב. חתם על כתב שליחות ר נתן נטע נאטקין-תרכו."},{"i":43023,"n":"קמאיקו, ליאון","f":"דב","bt":"1864","bp":"וילקוביסק","dt":"1928","dp":"ניו יורק","b":"תלמיד ישיבות ליטא. היגר לארה\"ב, ולמד בסמינר היהודי תיאולוגי בניו יורק. מנהל העתון היהודי היומי הראשון בארה\"ב \"טאגעבלאט\"-1889 שנוסד ע\"י כתריאל שרהזון שהיה אביו החורג. יסד ועד-1914 לעזרת הפליטים במזרח אירופה ואסף 14 מליון דולר בקרב הקהלות האורטודוכסיות. בשליחות באירופה-1920 בעניני עזרה לפליטים. ממנהלי ישיבת ר יצחק אלחנן בניו יורק."},{"i":43024,"n":"קמביל, אברהם מספרד","b":"מדקדק מזמן הראב\"ע. נזכר בספר הזכרון לר יוסף קמחי, אולי הוא ר אברהם בן מאיר המכונה אל חסן בן קמניאל."},{"i":43025,"n":"קמושביץ, אברהם מוארשא","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":43026,"n":"קמחי, אברהם","dt":"תפב","dp":"קושטא","b":"רב ואב\"ד בקושטא-תע\"ד"},{"i":43027,"n":"קמחי, אברהם משלוניקי","dt":"תש..","b":"דרשן ומוהל מחכמי שלוניקי. נספה בשואה."},{"i":43028,"n":"קמחי, אליהו מנאוי-שונציאן","dt":"תשג","b":"רב בנאווא-שוונציאן"},{"i":43029,"n":"קמחי, בכור ביג משלוניקי","b":"רופא בשלוניקי-תרס."},{"i":43030,"n":"קמחי, בנימין מירושלים","b":"מחכמי ירושלים ותלמיד \"בית אל\", הגיה והדפיס הספר \"שערי רחמים ושערי רצון\" שלוניקי תקב."},{"i":43031,"n":"קמחי, דוד מטריפולי","dt":"תרסא","b":"מקורב למלכות,חכם באשי בטריפולי"},{"i":43032,"n":"קמחי, דוד מנרבונא","f":"יוסף","k":"רד\"ק","bt":"ד'תתקכ","bp":"נרבונה-צרפת","dt":"ד'תתקצה","dp":"נרבונה","b":"לאחר שנתייתם גדל ולמד אצל אחיו ר משה. מרביץ תורה בנרבונה. מגדולי המדקדקים, ידוע בחיבורו על התנ\"ך, חיבר גם ספרי דקדוק, \"ספר מכלול\" ובתורת הנסתר"},{"i":43033,"n":"קמחי, חיים מקושטא","f":"יהודה מקושטא","bt":"תך","dt":"תצ-ב - יד אייר","dp":"קושטא או צפת?","b":"דיין ור\"מ בקושטא-תלט, עסק גם במסחר והיה עשיר, סירב להתיר את החרם על נחמיה חייא חיון. בנו - ר יעקב."},{"i":43034,"n":"קמחי, יהודה דוד מטריפולי","bp":"תורכיה","dt":"תרסא-ב","dp":"טריפולי","b":"מחכמי תורכיה, רב ביאניה-תרנה, הגיע לטריפולי-לוב וכיהן כדיין, חכם באשי-תרנו. הסכמה ממנו ב\"יגדיל תורה\" תונס תרסב."},{"i":43035,"n":"קמחי, יהודה רפאל מקושטא","b":"מחכמי קושטא-שנת ת', ראש משפחת קמחי בקושטא. בניו - ר אברהם, ר חיים."},{"i":43036,"n":"קמחי, יוסף מנרבונה - אבי הרד\"ק","f":"יצחק","k":"בעל ספר הזכרון","bt":"ד'תתסה","bp":"ספרד","dt":"ד'תתקל","b":"מגדולי מפרשי המקרא, מדקדק, מתרגם, פייטן, ברח מספרד והתישב בנרבונה-צרפת, מרביץ תורה בנרבונה. חיבר \"מלחמות השם\", \"מלחמת מצוה\" ועוד - בכת\"י. ספר הברית - נדפס בסוף ספר מלחמת חובה לר אברהם רומנו. הרשב\"א ביקרו בהיותו בנרבונה."},{"i":43037,"n":"קמחי, יחיאל מסרייבו","dt":"תרף","dp":"ירושלים","b":"מחכמי סרייבו, אסף את הרומנסות העממיות בעיקר בתורכית ובסרבית - מזמן התקוממות חאג' לוייו, עלה לירושלים."},{"i":43038,"n":"קמחי, יעקב מלונדון","f":"שמואל","k":"בעל שושנת יעקב","b":"רב בקושטא, לונדון-תקל, ופגש שם את החיד\"א."},{"i":43039,"n":"קמחי, יצחק מפרובאנס","f":"מרדכי","b":"פייטן ורב בפרובינצא-שנת ס'. חיבר אזהרות לשבועות, ועוד. אולי ר יצחק בן מרדכי משילון שהתכתב עם הרשב\"א."},{"i":43040,"n":"קמחי, יצחק מקאסטוריא","b":"דיין בקאסטוריא-תיג עם ר חיים אמיגו ור שלמה רוסו."},{"i":43041,"n":"קמחי, ישעיה שלמה מקושטא","b":"רב בקושטא-שנות ה-ת'-תק'."},{"i":43042,"n":"קמחי, ישראל ממצרים","f":"יעקב","b":"מדפיס במצרים-תק אצל אברהם יתום."},{"i":43043,"n":"קמחי, מאיר מקנישין","f":"יהושע","b":"רב בקנישין, פרש מרבנות ועסק במסחר בביאליסטוק. אחיו של ר נתן נטע ממיכאלובה."},{"i":43044,"n":"קמחי, מירקאדו מחברון","b":"תלמיד ר אליהו מני בחברון."},{"i":43045,"n":"קמחי, מרדכי ממונשטיר","b":"גביר במונשטיר-שץ."},{"i":43046,"n":"קמחי, משה יהושע","b":"חתן ר שלום שכנא ילין מירושלים. נסע בשליחותו לחלב לעבור על \"כתר ארם צובא\" על החלק שלא הספיק לעבור."},{"i":43047,"n":"קמחי, משה מחברון","f":"דוד","bt":"תקסט","bp":"בוסניה","b":"עלה לארץ-תקף. דיין בחברון, חתם עם ר אליהו מני ור רחמים פרנקו-החריף, בשנת תרכב בשליחות. הסכים על \"עבודת השם\" לר שניאור זלמן בן מנחם מנדל."},{"i":43048,"n":"קמחי, משה מחברון","f":"יום טוב","b":"מחכמי חברון-תקצט ומראשי הקהלה."},{"i":43049,"n":"קמחי, משה ממונסטיר","b":"מחכמי מונסטיר(=מונאשטיר) ומראשי העדה-שנות ה-ת'."},{"i":43050,"n":"קמחי, משה מנרבונה","f":"יוסף","k":"בעל מהלך שבילי הדעת","dt":"ד'תתקן (1190)","b":"מדקדק מחכמי ספרד בנרבונה, אחיו של הרד\"ק. חיבר גם פירושים לתנך, ועוד."},{"i":43051,"n":"קמחי, נסים יוסף דוד מקושטא","dt":"תקצו","b":"ראב\"ד בקושטא-תקפד. בנו ר שלמה קמחי בעל \"יקהיל שלמה\"."},{"i":43052,"n":"קמחי, נתן נטע ממיכאלובה","f":"יהושע","bt":"תרט","b":"תלמיד ר ברוך מרדכי ליפשיץ מנווהרדוק. רב בצירין-פלך מינסק-תרלח, ניזבאדקי-מיכאלובה-פלך גרודנא-תרמט וראש ישיבה. נסמך מאת: ר יצחק אלחנן מקובנא, ר יצחק איזיק חריף מסלונים, ר ראובן מדינבורג. מבניו: ר אליהו."},{"i":43053,"n":"קמחי, עובדיה מירקדו מחברון","f":"חיים יוסף","bp":"חברון","dt":"תרמח","b":"תלמיד ביהמ\"ד לרבנים בקושטא, פעיל צבור בירושלים, נסע לפאריס, פרסם מאמרים ב\"מנורה\" ועוד."},{"i":43054,"n":"קמחי, רפאל ישראל מקושטא","k":"בעל עבודת ישראל","bp":"קושטא","dt":"תצג","b":"תלמיד ר חיים אלפנדרי, עלה עם רבו לצפת, תלמיד ר יעקב וילנא אלישר בצפת. בשליחות צפת-תפח, ויש כתב הרשאה לנתן לשני גבאי צדקה בקורפו, היה באיטליה בזמן המחלוקת אודות הרמח\"ל והתייצב לימינו וביקש מהרמח\"ל למסור לו את כתביו ולהביאם לבדיקה אצל חכמי צפת, נזכר אצל ר רפאל מילדולה רבה של באינה שאירחו בדרך שליחותו. נפטר בשליחותו. אחיו ר אברהם הדפיס את ספרו \"עבודת ישראל\" אזמיר תצג, חיבר גם פירוש על הסמ\"ק בכת\"י."},{"i":43055,"n":"קמחי, רפאל מקושטא","b":"רב בקושטא-תיב."},{"i":43056,"n":"קמחי, שבתי ממונסטיר","f":"יהושע","b":"רב במונאסטיר-שנות ה-תק', עם ר יצחק פיסו ור עובדיה חיון, דיין-תקנא אצל ר שמואל קלדרון עם ר מתתיה חזן."},{"i":43057,"n":"קמחי, שלמה מקושטא","f":"נסים יוסף דוד מקושטא","k":"בעל מלאכת שלמה","dt":"תרנג - אחרי","b":"מחכמי קושטא, חתן ר יוהדה מוהיל. תלמיד ר אברהם ירושלמי. דיין בקושטא ומחכמי ישיבת \"קול ה\". חברם של ר יוסף אלפנדרי, ור יצחק עקריש. מראשי הלוחמים במשכילים-תריד, שניסו להכניס לימודי חול בחינוך הילדים. עלה לארץ והתישב בחברון. בנו ר חיים נסים יוסף שמתורתו בספרי אביו. חתניו ר נסים אליהו לומברוזו, ר נסים משה המון, ור חיים יעקב בכר. חיבר גם \"ימי שלמה\", \"מימי שלמה\"."},{"i":43058,"n":"קמחי, שלמה מקושטא","b":"רב בקושטא-תקך."},{"i":43059,"n":"קמחי, שמואל","b":"חיבר הקדמה ל\"סדר אליהו רבה וזוטא\" לר אליהו אלפנדרי."},{"i":43060,"n":"קמחי, שמואל מקושטא","b":"מחכמי קושטא-תעד, חתם עם 12 רבנים כנגד נחמיה חיון. מתורתו ב\"משאת משה\" לר משה ישראל. בנו - ר יעקב מלונדון. אחיו - ר ישראל."},{"i":43061,"n":"קמחי, שמואל מקושטא וירושלים","b":"עסקן מחכמי קושטא, עלה לארץ-תרך ועסק בפעילות ציבורית."},{"i":43062,"n":"קמיאל, יעקב קופל","b":"גביר,מגדולי שנייטוך-ש\"פ,בנה ביכנ\"ס ומקוה בקולומיי"},{"i":43063,"n":"קמיניץ, אברהם בצלאל","bp":"ירושלים","dt":"תרעד","dp":"ירושלים","b":"בעל מלון בירושלים."},{"i":43064,"n":"קמיניץ, אליעזר ליפמן מירושלים","f":"מנחם מנדל","bp":"ירושלים","dp":"ירושלים","b":"בעל בית המלון הראשון בירושלים."},{"i":43065,"n":"קמינסקי - הלפרין, אסתר רחל","k":"דוזה היהודית","bt":"1870","bp":"פרוזובה-ליד גרו","dt":"1920","dp":"וארשא","b":", עברה ללונדון, פאריס, חזרה לפולין. אגרותיה באידיש יצאו לאור בוילנא-1927 עם הקדמה מאת מרק טורקוב. בתה - אידה קמינסקי, בנה הכנר יוסף קמינסקי. ?? לא באוצר ??"},{"i":43066,"n":"קמינסקי, ברוך","b":"מבני היכלא של הבעל שם טוב-תק\"י"},{"i":43067,"n":"קמינסקי, דב בעריש מברדיטשוב","b":"שו\"ב ומנקר, עלה מברדיטשוב והתישב בירושלים."},{"i":43068,"n":"קמינסקי, חיים מואלברום","k":"בעל זכרון חיים","bt":"תקלד","dt":"תרכד","b":"תלמיד החוזה מלובלין, ור מאיר מאפטא. רב בקאמניסק, ואדמור-תקצא, עבר לואלברום(=וולברום). נפטר ללא ילדים. חיבר \"זכרון חיים\"."},{"i":43069,"n":"קמינסקי, יוסף","dt":"תשג","b":"רב בנאווידוואר"},{"i":43070,"n":"קמינסקי, יחיאל מקאליש","f":"משה נחום","bp":"אוזרקוב","b":"מחכמי קאליש, רב בטורבין, שצעקוצין. ערך שם את \"תורת צבי\"-תרפח לר צבי נחום פרנקל, והוסיף בו חדושים ממנו. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא, \"שערי תורה\"-תרפב. פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":43071,"n":"קמינסקי, צבי אריה מזדונסקא","f":"משה נחום","bt":"אוזרקוב?","b":"מחכמי זדונסקא-ואליא. אחיו ר יחיאל מקאליש מביא מתורתו בכת\"י."},{"i":43072,"n":"קמינסקי, צבי אריה מריציוואל","b":"אב\"ד ריציוואל. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":43073,"n":"קמינסקי, שלום","bt":"תרמד","dt":"תרצה - טו סיון","b":"רב בוויגובה,מרבני חיפה-תרצ\"ג"},{"i":43074,"n":"קמינסקי, שמעון מקרמנצוג","f":"בער","dt":"תקצח","b":"תלמידו הראשון של ר נחמן מברסלב, ונלווה אליו בנסיעתו לארץ ישראל. עלה לצפת-תקפג. נהרג עק\"ה בפוגרום."},{"i":43075,"n":"קמינצקי, איזיק","dt":"תשג","b":"רב בנאווידוואר"},{"i":43076,"n":"קמינצקי, אליהו עקיבא מלידא","f":"אלימלך מלידא","bt":"תקנח","dt":"תרלה - יד אדר","b":"חתן ר מרדכי-חתנו של ר חיים מוולוזין. רב בפטרבורג. חתנו - ר שמחה מתתיהו שטרשון מוילנא."},{"i":43077,"n":"קמינצקי, בנימין","f":"שמואל צבי","dt":"תרפא - ט חשון","b":"מחכמי קאלושקאווי. בנו - ר יעקב מארה\"ב."},{"i":43078,"n":"קמינצקי, חיים משה מארה\"ב","b":"פרסם מאמרים ב\"המאסף\" - ירושלים-אלכסנדריה תרנו-תרעג."},{"i":43079,"n":"קמינצקי, יוסף אליהו","b":"רב בלידא-תר\"נ"},{"i":43080,"n":"קמינצקי, יעקב מציטאווין ונ\"י","f":"בנימין בן שמואל צבי","k":"בעל אמת ליעקב","bt":"תרנא","bp":"קאלושקאווי-פלך מינסק","dt":"תשמו","b":"תלמיד ישיבות סלובודקא, סלוצק, מאלץ, לומזה. חתן ר דב צבי-משגיח ישיבת סלובודקא. רב בציטאוויאן-פלך קובנא, היגר לארה\"ב-תרצח, וכיהן כראש ישיבת \"תורה ודעת\" בניו יורק. חיבר \"אמת ליעקב\" ניו יורק תשמט. פרסם מאמרים ב\"בית ישראל\" - קובנא תרפב, \"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה.. בנו ר נתן - חיבר ספר באנגלית על אביו \"להיות גדול\"."},{"i":43081,"n":"קמינצקי, יצחק מסנוק","f":"ישראל חיים","b":"מחכמי סנוק-תרעא. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":43082,"n":"קמינצקי, יצחק מפרוביטש","b":"רב בפרוביטש. פרסם מאמרים ב\"אסיפת חכמים\" - אטיניא-בויאן תרע-תרעד."},{"i":43083,"n":"קמינקר, אהרן מסאוורוב","f":"שמואל","bt":"תרמא","dt":"תשטז","b":"נינו של ר הירש קמינקער-תלמיד הבעש\"ט, נכד-אבי אמו ר אברהם דוד טאראשמשער-נכד הבעש\"ט. תלמיד דודו ר אברהם דוד מיראפאליע, ר שמריה נח שניאורסון מבוברויסק. רב בסאוורוב-ווהלין-תרסח, עלה לארץ והתישב בת\"א. פרסם מאמרים ב\"בית הכנסת\" - תל אביב תשו, \"המאור\" - תל אביב תרצה. נסמך מאת: ר שמריהו נח שניאורסון, ר משה שמואל שפירא מבוברויסק, ר אהרן גליסקין מפאריץ."},{"i":43084,"n":"קמינקר, אהרן מתל אביב","b":"רב בתל אביב, מנהל מחלקת \"משמרת שבת\" ברבנות הראשית-תש."},{"i":43085,"n":"קמינקר, אלכסנדר מסקודל","f":"שמואל קמינקר","b":"מו\"צ בסקודל"},{"i":43086,"n":"קמינקר, חיים","f":"שמואל מרבינו קמינקר","b":"בנו - ר מאיר יצחק איזיק."},{"i":43087,"n":"קמינקר, מאיר יצחק איזיק","f":"חיים בן שמואל","dt":"תקפה - טו אייר","dp":"הורדנא","b":"מחכמי הורדנא. נפטר צעיר (בגיל 30). בנו - ר צבי הירש בויארסקי."},{"i":43088,"n":"קמינקר, שמואל - הנכד","b":"רב-שנת תר\"נ. בנו - ר אהרן מסאוורוב."},{"i":43089,"n":"קמינר, יהודה הלוי מחנטשין","f":"יחיאל מאיר","k":"בעל דגל יהודה","bt":"תקפג","dt":"תרנה - כד תשרי","b":"נכד ר ברוך פ\"ת בעל \"ברוך טעם\". חתן ר משה חיים רוטנברג-אחיו של בעל חדושי הרי\"ם. גביר תלמיד חכם. חסיד ר מנחם מנדל מקוצק, דודו בעל חדושי הרי\"ם, ר חנוך הניך מאלכסנדר. חתנו - בעל \"שפת אמת\" האדמור מגור."},{"i":43090,"n":"קמינר, יהודה ליב מטבריה","f":"יוסף","dt":"תקנב - אחרי","b":"אלה לארץ-תקמו."},{"i":43091,"n":"קמינר, מאיר יחיאל","dt":"תרז - א חשון","b":"רב בברדיטשוב"},{"i":43092,"n":"קמלהר, גרשון מטרנוב","f":"יצחק שלמה","k":"בעל מבשר טוב","bt":"תקפה","b":"התייתם בילדותו וגדל אצל קרובו האדמור רצ\"ה מרימנוב. חתן ר יקותיאל אריה הסופר מפריסטיק. שו\"ב בקולשיץ, טרנוב-תרמב. חיבר \"מבשר טוב\" פודגורזע תרס (תולדות רצ\"ה מרימנוב)."},{"i":43093,"n":"קמלהר, יקותיאל אריה מסטניסלב","f":"גרשון מקולשיץ","k":"בעל מופת הדור","bt":"תרלא","bp":"קולשיץ","dt":"תרצט - ט אלול","dp":"ירושלים","b":"חתן ר יצחק כץ (השחור) מקורטשין. עבר לקורטשין והקים שם ישיבה. רב בלנצהוט, רישא, ר\"מ בישיבת ר אלתר יחיאל נבנצל בסטניסלב, ארה\"ב, עלה לירושלים-תרצג. רוב כתביו אבדו בזמן מלחמת העולם ה-I. פרסם מאמרים ומחקרים והוציא לאור ירחון \"אהל מועד\" - פודגורזע תרנח. חיבר \"מופת הדור\" מונקטש תרסג (עם הסכמת הרב קוק). מקורב לאדמור מדזיקוב (אבל היה מחלוקת בגלל ספרו \"מופת הדור\" שהתפרש כנגד החסידות). עורך \"קול מחז\"ה (שפרש מ\"מחז\"ה). פרסם מאמרים ב\"הפלס\" - בעילום שמו. חיבר גם \"בקר יזרח\" תרנו, \"מבשר טוב\" תרס, חדושי הרמב\"ם - בכת\"י. הו\"ל כתב עת \"הבונה\" - תרסד. פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז, \"הבאר\" - זאמושץ-וארשא - תרפד, \"בית ועד לחכמים\" - לונדון תרסב, \"הלבנון\" - סטמר תרפח, \"הפלס\" - ברלין תרסא-תרסה, \"הפרדס\" פיעטרקוב-שיקגו תרעג-תרפז, \"שערי ציון\" - ירושלים תרפא."},{"i":43094,"n":"קמלהר, ישראל מרישא","f":"יקותיאל אריה","k":"בעל רבינו אלעזר מגרמ","bt":"תרן","dt":"תשב","b":"מזכיר אגודת ישראל בפפדם. פרסם מאמרים בעתונות הדתית. נספה בשואה. חיבר \"רבינו אלעזר מגרמיזא\" רישא תרץ, ועוד."},{"i":43095,"n":"קמלהר, משה מרישא","f":"יקותיאל אריה","bt":"תרנו","bp":"קורטשין","dt":"תשלט","b":"למד בישיבת אור תורה של אביו. מראשי \"המזרחי\" ברישא. עבר לברין והקים שם בית ספר וסניף המזרחי. חתן ר פנחס אורי אנגלרד מסנוק, עבר לסנוק. עלה לירושלים-תרצד. בשליחות המזרחי בחו\"ל. התישב בראשון לציון. הוציא לאור ספרי אביו."},{"i":43096,"n":"קמניאל, אברהם","f":"מאיר","k":"ר' אברהם אבן מוחג'יר","dt":"ד'תתס","b":"מחכמי ספרד, מדקדק, תוכן וקרוב למלכות, גזבר המס ומנהיג קהילת סביליה. שיר לכבודו מאת ר משה ן עזרא, ור יהודה הלוי חיבר שיר שנחקק על מצבתו."},{"i":43097,"n":"קמניצקי, יעקב מליטא וטורונטו","bt":"תרנא","b":"רב בציטיוואן(=ציטוביאן), טורונטו-תרצח."},{"i":43098,"n":"קמניצר, דוד","f":"שמואל קמניצר"},{"i":43099,"n":"קמניצר, שמואל"},{"i":43100,"n":"קמף, אברהם מראווה","b":"תלמיד ה\"שואל ומשיב\" (ומוזכר בספרו). מחכמי ראווה-תרח."},{"i":43101,"n":"קמף, צבי הירש ממושציסק","bt":"תקנג","dt":"תרלה","b":"רב במושציסק."},{"i":43102,"n":"קמפלר, משה אהרן מיבורוזנה","f":"יוסף","k":"הו\"ל כוכב מיעקב","b":"תלמיד ר דב בר מטשבין. מחכמי יבורוזנה. ניצל מהשואה. היגר לארה\"ב ועסק במסחר ספרים בניו יורק. ההדיר \"כוכב מיעקב\" לרבו."},{"i":43103,"n":"קמפנר, אהרן מטאטא","f":"שמואל משטאמפן","dt":"תקעג - טו אד\"א","dp":"שטמפן","b":"רב בטאטוס(=טאטא) כ-50 שנה, ור יוסף קוטנא על מקומו אחריו."},{"i":43104,"n":"קמפנר, אהרן מפרשבורג","b":"מראשי קהלת פרשבורג-תרצב."},{"i":43105,"n":"קמפנר, אהרן משטמפן","f":"מרדכי","dp":"שטאמפי","b":"מחכמי שטאמפי."},{"i":43106,"n":"קמפנר, דוד אברהם מביאליסטוק","f":"יהודה ליב מפלוצק","k":"בעל למטה יהודה","bt":"תקפא","bp":"פלאצק","dt":"תרנב","b":"גביר מחכמי ביאליסטוק. חיבר \"למטה יהודה\" עם הקדמה ובה לתולדות משפחתו - וארשא תרנב."},{"i":43107,"n":"קמפנר, חיים רפאל","f":"יהודה ליב מפלוצק","b":"חתן ר משה הירש ארליך מלובלין. אחיו - ר דוד אברהם מביאליסטוק בעל \"למטה יהודה\"."},{"i":43108,"n":"קמפנר, יהודה ליב מפלוצק","f":"יהושע פאלקמקמפנה","b":"חתן ר יצחק פלוצקר מפלוצק. מחכמי פלוצק - ואשתו עסקה במסחר ועסקה בצדקה וחסד. בניו - ר חיים רפאל-חתנו של ר משה עהרליך מלובלין, ר דוד אברהם מביאליסטוק בעל \"למטה יהודה\". חתניו - ר מאיר הכהן מלוטימורסק, אחיינו - ר זאב וולף ליפשיץ מלאווע, ר יעקב שמלקי הורביץ."},{"i":43109,"n":"קמפנר-שטמפן, שלמה זלמן מטרביט","b":"רב בטרביטש-תק עד תקך."},{"i":43110,"n":"קמפף, שמואל יצחק מפרג","b":"מרבני פרג-תקצ\"ח"},{"i":43111,"n":"קמץ, אפרים מוערשנא","f":"אשר מטיקטין","b":"רב בוורעשנא-תק\"פ"},{"i":43112,"n":"קמץ, אשר מטיקטין","dt":"תקמ - ד כסלו","dp":"וישגארד","b":"שימש את ר שלום מטיקטין. מקובל, רב בטיקטין בהוראת רבו ר שלום שהעדיפו על פני בניו, וישגארד. חתנו - ר אריה ליב כץ מפרידאן בעל \"פני אריה\"."},{"i":43113,"n":"קמרינו, שלמה מירושלים","b":"רב בירושלים-שנות ה-ר'-ש'."},{"i":43114,"n":"קמרנו, חיים מקושטא","f":"שבתי","b":"מדפיס בקושטא-רעט עם ר אשטרוק די טולון."},{"i":43115,"n":"קן, בער מפפד\"מ","f":"ליב מפפד\"מ","dt":"תקטו - ה טבת","dp":"גריסהיים","b":"גביר מראשי קהילת פפד\"מ, ויחד עם אחיו-ר משה ניהל את הקרן שהקדיש אביהם לתמיכה בתלמידי חכמים והעבירו את הקרן לקהילה. היה עם אחיו בראש מחנה שהיה במחלוקת עם מחנה קולפא-תקי. בביה\"כ בגרוס-גיראו היו אומרים \"מי שבירך\" לו ולאחיו בכל שבת. החזיק באחוזה בגריסהיים ויסד שם בימ\"ד וביכ\"נ."},{"i":43116,"n":"קן, יהודה ליב מפפד\"מ","dt":"תעט","b":"גביר מראשי קהילת פפד\"מ, הקים קרן לתמיכה בלומדי תורה, ובניו: ר בער ור משה-רבה של דרמשטט - העבירו את הקרן לקהילה. חתנו - ר גומפל וימפפן."},{"i":43117,"n":"קן, יצחק מטלז","k":"העילוי מטאקום","dt":"תשג","b":"רב בטלז"},{"i":43118,"n":"קן, ליב הירש משטמפן","b":"מחכמי שטמפן, חתם-תקנג על מינוי ר שלום אולמן לרבה של שטמפן."},{"i":43119,"n":"קן, ליב מפפד\"מ","f":"משה","dt":"תקיב - י תשרי","dp":"פפד\"מ","b":"מחכמי פפד\"מ."},{"i":43120,"n":"קן, משה מפפד\"מ","f":"ליב מפפד\"מ","dt":"תקכב - טו כסלו","dp":"פפד\"מ","b":"חתן הגביר ר שמשון ורטהיימר מפפד\"מ, ובזיוו\"ש חתן ר ברמן הלברשטט-נציג הקהילה בוינה, ובזיוו\"ש חתן הדיין ר משה שפייאר. יחד עם אחיו ר בער היה מראשי קהילת פפד\"מ, ר\"מ ורב הקלויז בפפד\"מ ומשפחתו תרמה להחזקתו, רב מחוז דרמשטט ומדינת הסן. היה שותף להדפסת הש\"ס-תעא בפפד\"מ - והיה מחלוקת בינו לבין שותפו - פרנקפורטר ובצו הקיסר היו הטפסים אסורים בהפצה במשך שנים רבות. בזמנו הלשין המומר פאול כריסטיאן נגד התלמוד ור משה פעל כדי למנוע את החרמת התלמוד. בנו - ר יהודה ליב."},{"i":43121,"n":"קן, פער מפפד\"מ","f":"ליב מפפד\"מ","dt":"תקטו - ד טבת","dp":"פפד\"מ","b":"שתדלן מחכמי פפד\"מ."},{"i":43122,"n":"קן, שמואל דוב מפוניבז","dt":"תשג","b":"מרביץ תורה בפוניבאז'"},{"i":43123,"n":"קן, שמואל מאויבן","b":"דיין באויבן-תקמב."},{"i":43124,"n":"קנאל, יצחק מאיר מוארשא","bt":"תרכב","dt":"תשג","b":"רב בלאשקי, ראש אגודת הרבנים ומזקני הרבנים בוארשא. חסיד ומקורב לבעל \"שפת אמת\". נספה בשואה."},{"i":43125,"n":"קנארד, יהודה ליב מהמבורג","f":"מרדכי","dt":"תקפז - ב אדר","dp":"אלטונא","b":"אחיינו של הדיין ר אליעזר ליפמן מאלטונא. גביר וממנהלי הת\"ת בהמבורג."},{"i":43126,"n":"קנביץ, יוסף מקוברסק וארה\"ב","f":"אליהו חיים","k":"בעל דברי יוסף","bt":"תרלא או תרלח","bp":"קאשודאר-ליד זעזמיר","dt":"תשד - טו סיון","b":"תלמיד ישיבת סלוצק (היה מ-14 התלמידים שהביא עמו ר איסר זלמן מלצר - כשהקים את הישיבה), דרשן, חתן הרידב\"ז, רב בשאדובה-תרסב, קוברסק-תרסז, מו\"צ ור\"מ בישיבת הרידב\"ז בצפת, טרנטון-ארה\"ב-תרסה, ניו יורק-תרפט. חיבר \"דברי יוסף\" נ\"י תשז, \"חיי היהודי\", \"חגים וזמנים\". פרסם מאמרים ב\"יגדיל תורה\" - נ\"י תרעו, \"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"שערי ציון\" - ירושלים תרפא. היה במחלוקת עם ר יעקב בן ציון מנדלסון ועל כך ב\"משנת יעב\"ץ\" בקונטרס דברי ריבות."},{"i":43127,"n":"קנבל, אליעזר ליפמן מברוזדוביץ","f":"יהודה ליב מירוסלב","k":"בעל שות וחדושי מהראל","bt":"תקע","bp":"ירוסלב","dt":"תרלו - כ שבט","b":"חתן הגביר ר יקותיאל אבאלי הכהן יאליש מלמברג ובזיוו\"ש חתן ר מרדכי הלפרין מברודי. התגורר בלמברג והתידד עם השו\"מ. תלמיד ר שמעון מירוסלב - סירב לבקשתו שימלא מקומו אחריו. רב בריזדוביץ (ליד סטרי)-תרח, רוזניאטוב-תריג. רוב כתביו אבדו. חיבר \"שות וחדושי מוהראל\" וינה תרצז. לתולדותיו - \"פאר הדור\". על קברו הוקם \"אוהל\"."},{"i":43128,"n":"קנבל, שבח מטיסמניץ","f":"אליעזר ליפמן","k":"בעל גרם המעלות","bt":"תרכג","dt":"תרצט","b":"עבר עם אמו לאחר שנתייתם מרוזניאטוב לברודי. תלמיד רא\"ב קלוגר. חתן ר יעקב ליכטמן מטיסמניץ. ערך \"יידישעס פאמיליען\". עבר לוינה בזמן מלחמת העולם ה-I. חיבר \"גרם המעלות\" (על ר משולם איגרא) למברג תרעד, ועוד."},{"i":43129,"n":"קנדיוטי, יהושע מקושטא","b":"תלמיד הרא\"ם. מחכמי קנדיא, רב עדת הרומנים בקושטא על מקום הרא\"ם - עם ר אליהו בן בנימין הלוי."},{"i":43130,"n":"קנדיוטי, ישעיה מקושטא","b":"רב עדת הרומנים בקושטא-שנות ה-ש'. (אולי הוא ר יהושע שהיה תלמיד הרא\"ם או בן משפחתו)."},{"i":43131,"n":"קנדינוף, אהרן הכהן מבוכרה","bt":"תקפא","bp":"בוכרה","dt":"תרסט - א תמוז","dp":"ירושלים","b":"מראשוני העולים מבוכרה לירושלים, מקורב לאמיר בבוכרה, הואשם שסייע לרוסים להשתלט על בוכרה וכדי להינצל נאלץ להתאסלם, ברח לרוסיה עם רכוש רב ומשם עלה לירושלים ושב ליהדות."},{"i":43132,"n":"קנדס, דוד מוילנא","f":"יחיאל מיכל","dt":"תקנב - ג חשון","dp":"וילנא","b":"תלמיד הגר\"א. מו\"צ בוילנא על מקום ר אברהם שמעון - שמעון הגדול. נשלח עם ר יהושע זליג לפרסם את הכרוז נגד החסידים-תקמא. בנו - ר חיים."},{"i":43133,"n":"קנובל, משה מאויהל","k":"בעל אבני שהם","b":"דומ\"צ באויהעל-תר\"ל"},{"i":43134,"n":"קנובלוך, יהושע מקראקא","dt":"תש..","b":"מחסידי בלז בקראקא. נכד בעל \"חדושי רד\"מ\". עבר לטשנסטוכוב אחר חתונתו. נספה בשואה."},{"i":43135,"n":"קנובלוך, יוסף מלנצהוט","f":"ברוך","bt":"תרעט","bp":"לנצהוט","dt":"תשנד","dp":"ירושלים","b":"ניצל מהשואה - גלה לסיביר. עלה לארץ דרך קפריסין. מחשובי חסידי בלז."},{"i":43136,"n":"קנובלוך, ישראל מדומברובה","b":"רב בדומברובה. בנו ר מרדכי דוד אביו של הגביר ר משה יעקב מבריסל."},{"i":43137,"n":"קנובלר, אהרן מניימרקט","b":"מחכמי ניימרקט-תרפה."},{"i":43138,"n":"קנול, דוד צבי מסטניסלב","b":"מחכמי סטניסלב-תרסט."},{"i":43139,"n":"קנול, משה מסטרי","f":"דוד צבי מסטניסלב","k":"בעל בית משה","b":"תלמיד ר דוד הורביץ אב\"ד סטניסלב. מחכמי סטרי, רב במיקוליטשין. נספה בשואה. חיבר \"בית משה\" פיעטרקוב תרפט. פרסם מאמרים ב\"משכנות יעקב\" - דרוהוביטש-בילגוריי תרצב. ?? לא באוצר ??"},{"i":43140,"n":"קנולר, חיים מפרמישלא","f":"דוד","k":"בעל פרי חיים","bt":"תרז","bp":"פרמישלא","dt":"תרפז","b":"חתן הגביר ר אברהם יצחק מפרמישלא. מנהיג חסידי צאנז בפרמישלא. רב ומדפיס. חיבר \"פרי חיים\" פרמישלא תרמג, ועוד. פרסם מאמרים ב\"המגיד\" - סטמר תרפח-תרצט."},{"i":43141,"n":"קנופלר, יצחק נפתלי מצי'לי","f":"רפאל אהרן-מנורת אהרן","k":"בעל קני מנורה","b":"רב בסנטיאגו דה צ'ילי. בספרו \"קני מנורה\" מביא את תולדות המשפחה."},{"i":43142,"n":"קנורוסובסקי, ישעיהו","f":"משה","bt":"1858","bp":"גרודנא","dt":"1914","b":"למד משפטים ומוסיקה בפטרבורג. יסד כתב עת ברוסית \"רוסיה התיאטרלית\", ו\"חצים\". עורך מוסיקלי ב\"תיאטרון ואמנות\" ופרסם מאמרים רבים על מוסיקה יהודית עממית. יו\"ר החברה למוסיקה יהודית."},{"i":43143,"n":"קנטון, יצחק ברכיה מאיטליה","k":"בעל יתד האהל","b":"רב באנקונא, טורינו-תצט. תשובה ממנו ב\"שמש צדקה\" וחלק על הרב מורפורגו. חברו של בעל \"פחד יצחק\". חיבר \"יתד האהל\" על ספר \"אהל מועד\". ?? לא באוצר ??"},{"i":43144,"n":"קנטור אורנשטין, בנימין אליהו","k":"בעל מזבח אבנים","b":"רב בזאלשין-פלך קאליש-תר\"ע. בניו: ר שמואל אריה-חתנו של ר שלמה יהודה ליב אלברשטין מסטאק, ר חיים צבי מפייזער."},{"i":43145,"n":"קנטור יעקב דב","bt":"1903","dt":"ה'תשמח 1988","bk":[["באר יעקב",""]]},{"i":43146,"n":"קנטור, חיים צבי הירש מפייזר","f":"בנימין אליהו אורנשטי","bt":"תרם","b":"רב בפייזער(=פייזערן)-פלך קאליש-תרסה."},{"i":43147,"n":"קנטור, יהודה ליב מליבאוי","f":"יוסף ש\"ץ","k":"מ. בלשן","bt":"1849","bp":"וילנא","dt":"1915","dp":"ריגא","b":"תלמיד ביהמ\"ד לרבנים בוילנא וזיטומיר, הצטרף לקבוצה סוציאליסטית בהנהגת א. ליברמן. עבר ללמוד רפואה בברלין ופרסם מאמרים בעתונים עבריים ובהם \"הצפירה\", עבר לפטרבורג והיה מעורכי \"רוסקי יאבריי\". יסד בברלין-1886 את העתון העברי היומי הראשון \"היום\", והירחון \"בן עמי\". קירב לספרות העברית את דוד פרישמן, שמעון פרוג, וי.ל. כצנלסון. פרש מעבודתו הספרותית וכיהן כרב בליבאוי(=ליבוי) על מקום הרב ד\"ר הלל קליין (שעבר לניו יורק), רב מטעם בוילנא. פעל בפטרבורג למניעת גזירת גירוש יהודי קורלנד. חזר לעבודה ספרותית-1910. כינוייו הספרותיים: \"מנחם אב\", \"עוקץ\", \"בן בג בג\", \"נחום בן עוזר\"."},{"i":43148,"n":"קנטור, יצחק איזיק מריגא","bp":"טלז","dt":"תשג","b":"רב בריגא-תרפה"},{"i":43149,"n":"קנטור-פינסקר, חיים דב מא\"י","f":"שלמה","bt":"תרכז","bp":"פינסק","b":"חתן ר יעקב דוד ספקטור מירושלים-אחיו של ר יצחק אלחנן מקובנא. רב ושו\"ב במושבה מאיר שפיה-תרנד. מחותן עם ר דוד בהר\"ן. הניח חדושי תורה ויומן - בכת\"י. חתנו - ר נחום בהרן-נהרג עק\"ה-תרפט."},{"i":43150,"n":"קנטרוביץ, יהושע בצלאל","f":"יעקב קופל","k":"בעל תורת יהושע","bt":"תקפח","bp":"מאלץ' (ליד ביאליסטוק)","dt":"תרמה","dp":"ירושלים","b":"אביו שהיה נכדו של הגרא נתמנה לרבה של וולוזין ור יהושע למד שם בישיבה. חיבר \"תורת יהושע\" בהיותו כבן 16. נתמנה לרב במאלץ' ואחר כך רב בביאליסטוק, בשנת תרלא עלה לירושלים ונתמנה לראש ישיבת עץ חיים. חיבר \"חנוך בצלאל\" ירושלים תרמא - וחתנו - ר חיים אליעזר הויזדורף חיבר לו הקדמה בשם \"חנוכת הבית\"."},{"i":43151,"n":"קנטרוביץ, יעקב מטימקוביץ ונ\"י","f":"זאב חיים","k":"בעל צלותא דשמעתתא","bt":"תרלג","bp":"אוזדא","dt":"תשי - כא תשרי","dp":"ניו יורק","b":"תלמיד ישיבת וולוזין, והיה תלמידו המובהק של ר רפאל שפירא, נסמך ממנו, ונתמנה לממלא מקום רבו כשנעדר מהישיבה. חתן ר יצחק יחיאל דוידוביץ מקרליץ. למד בכולל למצוינים מישיבת וולוזין מיסודו של הגביר ברודסקי. רב בואראטינשטענע-ליד מוהילוב, אוזידא-תרסו, שאצקי-תרעו, טימקוביץ, טרנטון--ניו גרסי-ארה\"ב-תרפח, היגר לארה\"ב- וכיהן כרב קהלת \"פועלי אמת\" בטרנטון-ניו ג'רסי-תרפח, ראש ישיבת \"תורה ודעת\" בניו יורק-תרצג. חיבר גם \"חדושי הגר\"י\". פרסם מאמרים ב\"היכל התורה\" - נ\"י תרצג, \"המסלה\" - נ\"י תרצו, \"המתיבתא\" - נ\"י תשג, \"שערי אורה\" - מיהאלביץ תרץ-תרצד, \"שערי אורה\" - מיהאלביץ תרץ-תרצד. בניו: ר נפתלי הרץ מטרנטון, ר אברהם מברוקלין, ר דב מארץ ישראל, ר יצחק יחיאל הי\"ד-נספה בשואה. חתניו: ר יעקב משה שורקין מניו יורק, ר ישראל לעוו על מקומו אחריו בטרנטון, ר ברוך סוסלוביץ מניו יורק, ר אליעזר ליפשיץ מארץ ישראל."},{"i":43152,"n":"קנטרוביץ, יצחק יחיאל","f":"יעקב מארה\"ב","dt":"תשב - כה אב","dp":"זעטל-ליד וילנא","b":"רב בזעטל. נספה בשואה."},{"i":43153,"n":"קנטרוביץ, משה מסמילוביץ","b":"גביר מחכמי סמילוביץ. מחותן עם הגדול ממינסק (בתו נשאה לר בן ציון פרלמן)."},{"i":43154,"n":"קנטרוביץ, שמעון יהודה ליב","f":"יעקב משה","bt":"תרלא","b":"מו\"צ בבאצייקעוו-פלך ויטבסק-תרסב, רב בטורופץ(=טאראפעץ)-פלך פעסקוב-תרסה."},{"i":43155,"n":"קנטריג' קנטרוביץ, מוריס","bt":"1881","bp":"אוטיאן","dt":"1964","b":"בנו של חזן בליטא. היגר לדרום אפריקה, למד משפטים והיה עו\"ד, ציר בפרלמנט. פעיל בחיים הציבוריים היהודים. סגן יו\"ר הפדרציה הציונית."},{"i":43156,"n":"קנטרמן, חיים אפרים פישל מארה\"ב","k":"בעל שעשוע אפרים","b":"רב בארה\"ב-תרעו."},{"i":43157,"n":"קנטרמן, נפתלי בער מארעל","f":"טוביה זאב","bt":"תריא","b":"נסמך מאת: ר חיים ברלין, בעל \"עמודי אש\". רב בארעל-פלך חרסון-תרמז. חיבר חדושים על יו\"ד - בכת\"י."},{"i":43158,"n":"קנטשיקר, נפתלי הרץ","b":"רב בטיסמניץ-תק\"צ"},{"i":43159,"n":"קניאזיק, בנימין","k":"בעל חלקת בנימין","b":"נדד מליטא למושבות בפלך חרסון-תרל וכיהן כרב 45 שנה. חיבר גם \"קנאת סופרים\" בדקדוק, ספר טהרה, ועוד."},{"i":43160,"n":"קניאזיק, מאיר מצארצונקא","f":"בנימין - חלקת בנימין","bt":"תריז","b":"תלמיד ישיבת ניעזין. רב בצריצנקע(=צאריצאנקע)-פלך פולטובה-תרמב. נסמך מאת: ר ישראל הכהן מקאביליאק."},{"i":43161,"n":"קניאל, יהושע מחיפה","f":"ישראל זליג","bt":"תרנו","dt":"תשל","b":"רב ראשי בחיפה-תרפה. פרסם מאמרים ב\"שערי ציון\" - ירושלים תרפא."},{"i":43162,"n":"קניג, אברהם מפרשבורג","b":"מראשי קהלת פרשבורג. חתם על תקנות ביה\"ס למלאכה שע\"י הקהלה-תקפא. ממיסדי ביה\"ס בפרשבורג-תקף כנגד דעת החרדים."},{"i":43163,"n":"קניג, בן ציון","b":"פרסם מאמרים ב\"אור המאיר\" - נ\"י תשח."},{"i":43164,"n":"קניג, חיים ישעיה מיאקע ונ\"י","k":"בעל חקי חיים","b":"רב ביאקע, ניו יורק."},{"i":43165,"n":"קניג, יוליוס מפרשבורג","b":"שירת כקצין בצבא האוסטרי בזמן מלחה\"ע ה-I, ממארגני ההגנה היהודית בפרשבורג - בזמן הפרעות בסיום מלחה\"ע ה-I."},{"i":43166,"n":"קניג, ירחמיאל משה","k":"בעל שרשי הים","b":"בנו ר נתן צבי מראשי חסידות ברסלב."},{"i":43167,"n":"קניג, משה הלוי מקוברסדורף","bt":"תרך","dt":"תרעד - יב אדר","dp":"קוברסדורף","b":"תלמיד הכת\"ס, ור יהודה אסאד ור אברהם שאג מקוברסדורף. חתן ר שלמה מאיר אדלר מקוברסדורף ועבר לשם. רב בקוברסדורף-תרנה. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"קובץ מפרשי התורה\" - מארגרטן תרצג, \"דבר בעתו\" - פאקש תרסט, \"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":43168,"n":"קניג, נתן צבי מבני ברק","f":"ירחמיאל משה-שרשי הים","r":"ראש כולל ברסלב בבני ברק וממנהיגי חסידות ברסלב","bt":"תש","dt":"תשנח - כז תשרי","b":"תלמיד ישיבת מיר. ראש חסידי ברסלב בבני ברק, ועמד בראש הכולל הגדול בארץ. חיבר ספרים רבים.","bk":[["תורת נתן ובו ג' חלקים א. ערכי הרמ\"ק. ב. ערכי האריז\"ל. ג. ערכי התיקונים",""]]},{"i":43169,"n":"קניג, שלמה","dt":"תשד","b":"רב ביאקא"},{"i":43170,"n":"קניג, שלמה ליב מעיר חדש","b":"דומ\"צ בעיר חדש-תר. חתנו - ר איסר טויבר בעל \"אזרח רענן\"."},{"i":43171,"n":"קניג, שלמה מבראסכאטש","f":"צבי","dt":"תש..","b":"תלמיד ישיבת \"עץ חיים\" בובוב בקשאנוב. נספה בשואה."},{"i":43172,"n":"קניגסברג, אליקים געץ מקורמאנד","dt":"תר","b":"רב בקהילה הניאולוגית בקורמאנד-מחוז וואש. נזכר בשו\"ת החת\"ס."},{"i":43173,"n":"קניגסברג, חיים שלמה מבוכניה","f":"יוסף משה הכהן","k":"בעל אין פייער און","bt":"תרפג","bp":"בוכניה","dt":"תשסד","b":"תלמיד ישיבות טשבין ובובוב. ניצל מהשואה. עלה לארץ והיגר לניו יורק. חיבר \"אין פייער און אין וואסער\" ניו יורק תשנג, ותורגם לעברית \"באש ובמים\" תשנו."},{"i":43174,"n":"קניגסברג, יהודה ליבוש","f":"יוסף הכהן","dt":"תרץ","b":"שו\"ב של האדמור משיניבה. נסע לארה\"ב-תרן, וחזר כל שנה להיות עם רבו בתשרי."},{"i":43175,"n":"קניגסברג, יוסף מראדום","b":"גביר מחכמי ראדום. מנהל ישיבת חכמי לובלין. ניסה להעלות את הישיבה לארץ - אך לא הצליח. בגיטו וארשא עסק בתורה וחסד. היה מיוזמי המרד. נספה בשואה."},{"i":43176,"n":"קניגסברג, יוסף משה הכהן מזלין","f":"צבי הירש ממקלנבורג","k":"בעל אילת אהבים","bp":"זלין","b":"חתן ר ישעיה דוד קלמן מבוכניה. חסיד בובוב. רוב כתביו אבדו. הדפיס \"אילת אהבים\". ?? לא באוצר ??"},{"i":43177,"n":"קניגסברג, ישכר דב מלימנוב","f":"ישראל הכהן","bt":"תרמד","bp":"לימנוב","dt":"תשלה","b":"עבר עם אביו לניו יורק - נשלח ע\"י האדמור משיניבה ליסד את כולל גליציה בניו יורק. תלמיד ישיבת עץ חיים שהפכה לישיבת ר יצחק אלחנן. ממיסדי \"ישראל הצעיר\" והמזרחי."},{"i":43178,"n":"קניגסברג, לוי יצחק מזלישטשיק","b":"מחכמי זלישטשיק-תריד."},{"i":43179,"n":"קניגסברג, ליב משטינמנגר","b":"רב בשטיינמנגר-תר\"ו"},{"i":43180,"n":"קניגסברג, נח מליזנסק","f":"לוי יצחק","k":"בעל מי נח","bt":"תרך","dt":"תרץ","b":"שו\"ב בגלוסק, קרליפקה (ליד ליזנסק)-תרמח. חיבר \"מי נח\" פשמישל תרסז. ?? לא באוצר ??"},{"i":43181,"n":"קניגסברגר, יהודה ליב משטינמנגר","f":"עוזר","bt":"תקנא","bp":"צעהלים","dt":"תרכב - יא טבת","dp":"שטיינמנגר","b":"תלמיד החת\"ס במטרסדורף, ור שלום אולמן מלקנבך. חתן הגביר ר אהרן אונגר מרכניץ ועבר לשם. רב ברכניץ-תקעח לצד האב\"ד ר אלכסנדר מייזלש. רבה הראשון של שטיינמנגר(=סאמבאט-האלי=סומבוט הי)-תקצט."},{"i":43182,"n":"קניגסברגר, יצחק איזיק מצעהלים","f":"עוזר","bt":"תקמה","bp":"צעהלים","dt":"תרי - טז תשרי","dp":"צעהלים","b":"תלמיד החת\"ס. חתן ר יעקב יהודה גשטטנר מטשארנא. מחכמי צעהלים. תשובה אליו ב\"חתם סופר\". החת\"ס סיפר שר נתן אדלר קיבל דמי פדיונו. חתנו (בזיוו\"ש) - ר שלמה זלמן אולמן בעל \"יריעות שלמה\"."},{"i":43183,"n":"קניגסהופר, משה יונה מפיורדא","f":"מנחם אריה מנדל ליב","bt":"תרד","bp":"ועללבהויזן","dt":"תרנד","dp":"פיורדא","b":"תלמיד הכת\"ס, ור נתן בנימין ליבר מפרשבורג, ור יצחק דב במברגר מוירצבורג. חתן ר משה אוטנהימר ממינכן, ובזיוו\"ש חתן ר נתן פויכטוונגר משוואבאך. רב בבערמרויט ומחוז האגענבאך (האכיבעך, אובער פרנקוניה)-תרכה, רב בפיורדא ומנהל בית היתומים בפיורדא-תרכז."},{"i":43184,"n":"קניזל, יעקב מפאס","b":"רב בפאס-שנות ה-ר', על קברו התפללו בעת צרה ובשנת שעג התפללו על קברו ונענו. לדעת ר יעקב משה טולדנו ב\"אפריון\" הוא ר יעקב קינו שהגיע מספרד עם ר יעקב בירב ודרשו שניהם בתלמסאן."},{"i":43185,"n":"קניזניק, זלדה","bt":"1869","bp":"ויז'ון","b":"בגיל 15 ברחה לוילנא כדי ללמוד מיילדות - הוריה החזירוה והשיאוה. חיברה שירים רבים באידיש ולאחר שפרסה את אברהם רייזין החלה לפרסמם ב\"צוקונפט\"."},{"i":43186,"n":"קניטופסקי, אפרים מניו יורק","k":"בעל זכרן אפרים","b":"רב בניו יורק. חיבר גם \"עטרת אפרים\"."},{"i":43187,"n":"קניטי, אברהם יוסף מירושלים","f":"יוסף","k":"בעל מקיץ בן חי","b":"בצעירותו עלה לצפת, עבר לארם צובא ולמד אצל ר עזרא אסי, ואחר כך לקנדיא(=כרתים) שם כיהן כרב, משם לאלגיר נפגש שם עם ר יהודה עייאש, עבר לליוורנו וכיהן שם כרב. בשנת תקד שב לירושלם ואחר כך לליוורנו, חיבר ספר \"מקיץ בן חי\" קושטא תקז, \"שיח אברהם\"."},{"i":43188,"n":"קניטי, אהרן מאדרינופול","b":"דיין באדרינופול, חתם-תקעח עם ר יהושע גירון ור יצחק בן מרדכי."},{"i":43189,"n":"קניטי, חיים מוידין","b":"חתן הגביר ר רפאל אברהם אשכנזי מוידין. גביר בוידין לצד חותנו."},{"i":43190,"n":"קניטי, שלמה בכור מירושלים","b":"מחכמי ירושלים-תרלג, חתם בענינים שונים עם בנו - ר אברהם."},{"i":43191,"n":"קנייבסקי, חיים מבני ברק","f":"יעקב ישראל-הסטייפלר","b":"חתן ר יוסף שלום אלישיב, ואשתו בת שבע היתה צדקת שהרבה נשים נתברכו ממנה. פרסם מאמרים ב\"תפארת ציון\" - בני ברק תשב - קובץ תלמידי ישיבת \"תפארת ציון\"."},{"i":43192,"n":"קנייבסקי, יעקב ישראל מבני ברק","k":"הסטייפלר - קהילות יע","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ, \"כנסת ישראל\" - סלובודקה - ירושלים תשא, \"השער\" - בני ברק תשח."},{"i":43193,"n":"קניפל, קופל","b":"תלמיד ר יחיאל מיכל היבנר מניזנוב (שהזכירו בספרו \"לבושי מכלול\")."},{"i":43194,"n":"קנישע, משה מיינק ופרוינקירכן","b":"תלמיד החת\"ס. חתן ר מרדכי טאסק מפרשבורג. רב ביונק(=יינק)-תקפג וראש ישיבה שם, פרוינקירכן-תקצג. נזכר ב\"חתם סופר\"."},{"i":43195,"n":"קנלר, אברהם זאב לנצהוטר","f":"ישראל הלל מלנצהוט","bt":"תרסט","dt":"תש..","b":"תלמיד ר דוד באבד בעל \"חבצל השרון\". מחסידי בלז ורב בחצר בלז, רב בלנצהוט. חתן ר אברהם פיקסלר ממנוקטש - עבר לשם ועמד בראש ישיבת בלז. נספה בשואה."},{"i":43196,"n":"קנלר, אהרן שמואל","f":"משה מאוסטילה","k":"בעל מנחת מרחשת","b":"דרשן בקהילות ליבאמלע וקאוולע, עבר לברודי, למברג-תרעד. חיבר \"מנחת מרחשת\" לובלין תרסח, ועוד."},{"i":43197,"n":"קנלר, ישראל הלל מלנצהוט","f":"אברהם זאב מלנצהוט","k":"בעל משאת משה","bt":"תרלג","bp":"לנצהוט","dt":"תשט","b":"רב וגביר בלנצהוט ומראשי הקהלה. ניצל מהשואה (גורש לסיביר), עבר לאחר השואה ללונדון, ואנטורפן. נפטר בדרכו לארץ. חיבר \"משאת משה\" תל אביב תשמט."},{"i":43198,"n":"קננגיסר, ברוך מקראקא","f":"דוד גרונר","bt":"תרסו","bp":"קראקא","dt":"תשג","b":"תלמיד בישיבת עץ חיים דבובוב בקראקא. חתן ר דודו אלימלך צנגר ממונטריאול. ר\"מ בישיבת בובוב. הקים מחדש את ישיבת בובוב בוישניצא תחת הכיבוש הנאצי. נספה בשואה-תשג על קדוש השם."},{"i":43199,"n":"קננגיסר, ישראל יצחק מקראקא","f":"דוד גרונר","bt":"תרעג","bp":"קראקא","dt":"תש..","b":"לאחר שנתייתם. גדל אצל ר שלמה הלברשטט מבובוב. חתן ר אליעזר שו\"ב דטשנסקוביץ ועבר לשם. נספה בשואה."},{"i":43200,"n":"קננגיסר, משה","f":"לוי מאמסנא","b":"תלמיד בישיבת בובוב-תרפט."},{"i":43201,"n":"קנפוס די, שלמה","f":"טוביה וארון","b":"מחכמי צפת, בשנת תנה - תס בשליחות במרוקו. אביו היה מחכמי ירושלים. בשנת תנה היה בונציה ופגש את ר מרדכי אשכנזי."},{"i":43202,"n":"קנפוס, אברהם מסרייבו","b":"מראשי קהלת סרייבו-שנות ה-ת' - אחד משבעת טובי העיר."},{"i":43203,"n":"קנפוס, טוביה","b":"מחכמי ירושלים מוזכר ב\"חרבות ירושלים\" כאחד הסובלים בפרעות אבן פארוך בשנת שפה."},{"i":43204,"n":"קנפוס, יצחק מסרייבו","b":"רב בסרייבו-שץ."},{"i":43205,"n":"קנפוס, משה מסרייבו","b":"מחכמי שלוניקי-שפ, רב בסרייבו."},{"i":43206,"n":"קנפלד, אלכסנדר מסיראק","f":"אליעזר ליפמן מטיניע","bt":"תרסא","bp":"טיניע","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור ישעיה זילברשטין מוויצען. חתן ר יעקב שרגא הלוי יונגרייז מנאגרד-בערצעל.רב בסיראק-תרצג. נספה בשואה."},{"i":43207,"n":"קנפלר, אברהם יהודה מטיניע","f":"רפאל אהרן מטיניע","dt":"תרנח - כב סיון","dp":"טיניע","b":"תלמיד החת\"ס והכתב סופר. חתן ר ישראל אבלס מסערדאהעל. רב בטיניע."},{"i":43208,"n":"קנפלר, אליעזר ליפמן מטיניע","f":"אברהם יהודה מטיניע","b":"מחכמי טיניע-תרסא. בניו - ר אלכסנדר מסיראק ור רפאל אהרן מטיניע."},{"i":43209,"n":"קנפלר, אלכסנדר מסיראק","dt":"תשד","b":"רב בסיראק"},{"i":43210,"n":"קנפלר, ישעיה מאויהל","b":"דומ\"צ באויהעל-תר\"כ"},{"i":43211,"n":"קנפלר, רפאל אהרן מטיניע","f":"יוסף מטיניע","bt":"תקנו","bp":"זשאמבאק","dt":"תרכד - כו כסלו","dp":"טיניע","b":"תלמיד החת\"ס. מחכמי טיניע."},{"i":43212,"n":"קנפלר, שמעון מדברצין","f":"אברהם יהודה מטיניע","bp":"טיניע","dt":"תרסט - כג חשון","dp":"דברעצין","b":"תלמיד הכת\"ס, והשב\"ס. חתן דודו ר צבי הרש לידרמן מדברצין."},{"i":43213,"n":"קנפמכר, יוסף מניקלשבורג","bt":"תקעה","dt":"תרסט","b":"מרביץ תורה בניקלסבורג"},{"i":43214,"n":"קנפנטון יהודה בן שלמה; בלוי משה יהודה","bt":"1912","dt":"ה'תשסג 2003","bk":[["ספר ארבעה קנינים",""]]},{"i":43215,"n":"קנפנטון, יהודה מספרד","f":"שלמה","k":"בעל ארבעה קניינים","b":"מקובל,תלמיד הריטב\"א בא ממולינה(ספרד),גבר בויכוחים על כמרים נוצרים,גלה להוניין,חיבר \"ארבעה קניינים\""},{"i":43216,"n":"קנפנטון, יוסף שאלתיאל מצפת","b":"מחכמי צפת בשנת תנח, בשנת תסא בשליחות ירושלים."},{"i":43217,"n":"קנפנטון, יצחק מקסטיליא","f":"יעקב","k":"בעל דרכי התלמוד","bt":"קכ","bp":"ספרד","dt":"רכג","dp":"פניאפיאל","b":"גדול חכמי ספרד בדור שלפני הגירוש. נקבר לבקשתו לצד המקובל ר יצחק גיקטיליא. בתשובות המבי\"ט מוזכר ר שלמה קנפנטון - כנראה בנו או נכדו."},{"i":43218,"n":"קנפנטון, ישראל משלוניקי","dt":"תמו","dp":"שלוניקי","b":"רב ורופא בשלוניקי."},{"i":43219,"n":"קנפנטון, משה משלוניקי","dt":"תיג - כה אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":43220,"n":"קנפנטון, שם טוב משלוניקי","dt":"תיב - ט תשרי","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":43221,"n":"קנציפוביץ, יעקב מסלובודקה","b":"רב בסלובודקה. בניו: רבנים בסמיאטיץ, שימענצע, יעזנא. חתניו - ר יהודה ליב פיין מאסמינא, ר יצחק אריה ביליצקי ממאליאט, רבה של טיקטין, ר שמעון רוזובסקי מאישישוק."},{"i":43222,"n":"קנר, אברהם אביש הלוי","f":"יעקב שמשון מקלויזנב'","k":"אדמור מבוקרשט","bt":"תרנד","dt":"תשמד","b":"חתן ר מרדכי יוסף משה מושקוביץ האדמור מסוליצה. עבר לבוטושן והנהיג את חסידי חותנו ביאסי. ניצל מהשואה. והיה לאדמור מבוקרשט. עלה לארץ-תשח והתישב בחיפה. חיבר \"אהל קדושים\" ירושלים תשיד."},{"i":43223,"n":"קנר, אברהם אביש מסנוק","f":"אהרן הלוי מסטריזוב","b":"גביר בעל אחוזות בסנוק שעסק רק בתורה. חסיד הדברי חיים ומתומכיו הגדולים. הקים קלויז צאנז בחצרו."},{"i":43224,"n":"קנר, אברהם חיים מארה\"ב","f":"יוסף","k":"בעל לקח טוב - בכת\"י","b":"רב בקולוניה דובראווא-גליל רוזינא, \"במורד ההר\" בוולוזין, ברונזויל-ניו יורק,"},{"i":43225,"n":"קנר, אברהם מקרוטושין","f":"מאיר קנר","b":"רב בקרטשין. בנו - ר אריה ליב מרימנוב."},{"i":43226,"n":"קנר, אברהם שלום מסטניסלב","bt":"תקפה","b":"גביר מחכמי סטניסלב ודיין בסטניסלב-תרס. בנו ר ישראל רב בשווינינגן (הולנד)."},{"i":43227,"n":"קנר, אהרן הלוי מסטריזוב","f":"משה ראכעל מלינסק","b":"גביר מחכמי סטריזוב. בנו ר אברהם אביש מסנוק."},{"i":43228,"n":"קנר, אריה ליב מרימנוב - א","f":"אברהם מטיטשין?","k":"אדמור מרימנוב","dt":"יז אד\"ב","b":"מצאצאי ה\"שארית יוסף\". תלמיד וחתן ר צבי הירש מרימנוב, ובזיוו\"ש חתן ר מרדכי זיסקינד לנדא מסטרי. רב ואדמור ברימנוב-תקן. חתניו - ר יוסף הולנדר מאמסנא, ר יהושע מטומשוב. בנו (או נכדו) - ר חיים יעקב שטרום-קנר (שטרויס) רב בדוקלא."},{"i":43229,"n":"קנר, אריה ליב מרימנוב - ב","f":"אברהם מקורטשין","bt":"תקף","dt":"תרמב","b":"חתן ר שמחה מדולקא נכד המג\"ש. בנו ר צבי הירש מחירוב."},{"i":43230,"n":"קנר, ברוך הלוי (הלברשטם)","f":"יעקב שמשון מקלויזנב'","k":"אדמור מצאנז","bt":"תרנה","dt":"תשיג","b":"חתן דודו ר שלום הלברשטם מפיקעלי ונקרא גם בשם חותנו - הלברשטם. רב בצאנז וטשחויב על מקום אביו. אדמור מצאנז על מקום חותנו.ניצל מהשואה, הגיע לצרפת אחריה, היגר לארה\"ב-תשיג. נפטר בלי ילדים."},{"i":43231,"n":"קנר, חיים מפודגורזא וניו יורק","f":"יעקב שמשון מקלויזנב'","k":"אדמור משינאווא","b":"רב בפודגורזע, סאליצה, אדמור משינאווא בניו יורק."},{"i":43232,"n":"קנר, יהודה יוסף מיבלונוב","f":"שלום הכהן מבלשביץ","dt":"תש..","b":"חתן ר קלונימוס קלמן צוקרמן מיבלונוב, רב ביבלונוב לצד חותנו. נספה בשואה. תשובה אליו בספר חותנו \"מנחת הקומץ\"."},{"i":43233,"n":"קנר, יעקב שמשון הלוי מטשכויב","f":"אלעזר-נכד ר אלימלך","k":"אדמור מטשכויב","dt":"תשב - ו סיון","b":"נכד ר פנחס יוסף שפירא - חתן האדמור ר חיים מקוסוב. והיה גם מצאצאי הבעשט. חתן ר משה הלברשטם האדמור משינאווא. רב ואדמור בצ'כויב-גליציה אחר פטירת חותנו, אדמור בקלויזנבורג-תרעד."},{"i":43234,"n":"קנר, יעקב שמשון מקלויזנבורג","f":"משה מסנוק","bt":"תרלו","dt":"תשב","b":"חתן ר משה הלברשטם משיניבה. רב בטשחויב על מקום דודו ר ישעיה הלברשטם. עבר לקלויזנבורג-תרעד וכיהן שם כאדמור. בנו - ר אברהם אביש מבוטושאן-חיפה, חתנו - ר יעקב יוסף שלמה הלפרין האדמו\"ר מואסלוי."},{"i":43235,"n":"קנר, ישכר מפשמישל","f":"אברהם שמחה","k":"בעל זמירות לשבת","bt":"תרפה","bp":"פשמישל","dt":"תשן","b":"תלמיד יח\"ל בגיל 13. ניצל מהשואה, ואחריה למד בקראקא אצל מר\"א זוברמן. עלה לבני ברק. חסיד בובוב ומנהל הישיבה. חיבר \"זמירות לשבת וליום טוב\" כמנהג בובוב - בני ברק תשלו."},{"i":43236,"n":"קנר, ישראל ליפא מרישא","b":"מחכמי רישא - ממשתתפי \"אהל מועד\"."},{"i":43237,"n":"קנר, מאיר הכהן מטיסמניץ","b":"מחכמי טיסמניץ, בנו ר יחיאל מיכל מטיסמניץ. תלמיד ר משולם איגרא. עלה לארץ והתגורר בצפת. חתן ר נפתלי צבי נכד החכם צבי."},{"i":43238,"n":"קנר, מאיר מחירוב","b":"רב בחירוב"},{"i":43239,"n":"קנר, מאיר מחירוב","f":"אברהם מטיטשין","b":"מצאצאי הט\"ז. תלמיד ר אלמילך מליזנסק. על מצבתו נכתב \"שאליהו הנביא היה מתגלה אליו\". בנו ר אברהם-חותנו של ר צבי הירש מרימנוב."},{"i":43240,"n":"קנר, מנחם מנדל מסאהל","b":"רב בסאהל-תרס."},{"i":43241,"n":"קנר, משה הלוי מסנוק","f":"אברהם אביש מסנוק","b":"תלמיד ר נתן גולדברג מלימנוב. חתן ר פנחס יוסף (חתנו של ר חיים מקוסוב). גביר מחכמי סנוק וסירב לרבנות. מחותן עם גדולי האדמורים."},{"i":43242,"n":"קנר, משה מטרנוב","b":"עבר מטרנוב לאושפיצין - ידידו של רש\"א רובין - שהזכירו בספרו \"שם עולם\"-תרטו."},{"i":43243,"n":"קנר, נחום דוד","f":"צבי","bt":"תרטו","bp":"טיראספול","b":"רב באודסה-תרסג."},{"i":43244,"n":"קנר, פנחס יוסף מזגורז","f":"משה הלוי מסנוק","bt":"תרלח","bp":"סנוק","dt":"תרפח","b":"חתן ר מאיר יהודה שפירא האדמור מבוקובסק. רב בזגורז(זגרש, זאגארש)-ליד סנוק-תרסג, וחתנו ר ברוך הורביץ על מקומו אחריו."},{"i":43245,"n":"קנר, שלום הכהן","dt":"תשג","b":"חתן ר מאיר גוטשטין מבלשביץ, רב בבלשביץ (קנה את הרבנות מגיסו ר נפתלי גוטשטין). נספה בשואה."},{"i":43246,"n":"קנריק, יהודה ביניש מרוזוודוב","b":"מחכמי רוזוודוב - תשובה אליו \"קול יהודה\"-תרמה."},{"i":43247,"n":"קנריק, ישראל מארה\"ב","b":"פרסם מאמרים ב\"המתיבתא\" - נ\"י תשג."},{"i":43248,"n":"קנריק, רפאל משנדישוב","b":"מחכמי שנדישוב. פרסם מאמרים ב\"המפלפל\" - קראקא תרעג."},{"i":43249,"n":"קנריק, שלמה זלמן (זלקא) מטרנוב","bt":"תרטו","bp":"סוקילניק (גליציה)","dt":"תרצב - ו טבת","dp":"ניו יורק","b":"חתן הגביר ר ליבוש זינגר מטורנא. רב בטרנוב, היגר לארה\"ב-תרס וכיהן כרב בסקרנטון-פנסילבניה, רב בניו יורק-תרסו. פרסם מאמרים ב\"יגדיל תורה\" - נ\"י תרעו, \"עמק הלכה\" - באטארקס תרפא, \"פרח הלבנון\" - וארשא תרעח."},{"i":43250,"n":"קנרפוגל, אברהם אבלי","f":"מרדכי מרישא","k":"בעל בארות המים","b":"חסיד רצ\"ה מרימנוב. חתן ר ישראל חיאל נ\"י מרימנוב. חיבר \"בארות המים\" פשמישל תרמח - נדפס עם ספר טעמי המצות לרקנטי. ?? לא באוצר ??"},{"i":43251,"n":"קנשיט, יצחק מרדוביץ","b":"פרסם מאמרים ב\"המגיד\" - סטמר תרפח."},{"i":43252,"n":"קנשינו - משפחה","b":"משפחת מתרגמים באלגיר וספרד - בשנים שאחרי הגירוש."},{"i":43253,"n":"קנשינו, אברהם מאלגיר","f":"יעקב בן חיים","k":"בעל אגודת אזוב","dt":"תן","dp":"ליוורנו","b":"רב פוסק ופייטן בווהראן, גלה לאיטליה-תכז - לאחר שהספרדים כבשו את אורן(=ווהראן) והתישב בליוורנו, ופסק הלכות שם \"אהל יעקב\" אמשטרדם תצז - רוב תשובותיו אבדו. קינות ממנו ב\"נגיד ומצוה\" אמשטרדם תעב. חיבר \"אגודת אזוב\" - ואבד."},{"i":43254,"n":"קנשינו, יעקב מאלגיר - השני","f":"חיים בן יצחק בן יעקב","b":"מחכמי ואהרן-אלגיר, בן למשפחת מתרגמים למלכי ספרד, והיה מתורגמן למלך ספרד-תך. הו\"ל ספר בספרדית לר משה אלמושנינו ובסופו - קורות בני משפחתו."},{"i":43255,"n":"קנשינו, יצחק מאלגיר","f":"חיים בן יצחק","b":"מחכמי ווהראן, ספרא רבא ומשורר. חיבר שיר לכבוד ר אברהם קנשינו, וקינה על פטירת ר אהרן קנשינו."},{"i":43256,"n":"קנשינו, שלמה מאלגיר","b":"דיין בווהראן. נזכר במחזור כת\"י של ר יצחק קנשינו - שם קינה לזכרו."},{"i":43257,"n":"קס, מרדכי מקוסוב","b":"מחכמי קוסוב - ממשתתפי \"אהל מועד\"."},{"i":43258,"n":"קסובר, יהושע","f":"יצחק קאך","dt":"תקסט - יג ניסן","b":"רב בקאסוב"},{"i":43259,"n":"קסוויץ, ליב","dt":"תקמג - יב תשרי","b":"מרביץ תורה,ראב\"ד בפרג"},{"i":43260,"n":"קסוטו, יהודה ממונשטיר","b":"דיין במונשטיר-שנות ה-ת' אצל ר בנימין די מדינה."},{"i":43261,"n":"קסוטו, יוסף מירושלים","f":"חיים","bt":"תרמב","bp":"ירושלים","dt":"תרצה - יד אד\"א","dp":"ירושלים","b":"עבר לארגנטינה והיה פעיל בעניני צבור, חזר לארץ-תרצה."},{"i":43262,"n":"קסוטו, יוסף מירושלים","f":"משה","bt":"תרס","bp":"ירושלים","b":"פעיל צבור בירושלים."},{"i":43263,"n":"קסוטו, יוסף ממונסטיר","b":"רב במונסטיר-תס\"א"},{"i":43264,"n":"קסוטו, יוסף ממונסטיר","b":"מחכמי מונסטיר(=מונאשטיר) ומראשי העדה-שנות ה-ת'."},{"i":43265,"n":"קסוטו, יצחק מלאריסה","b":"רב בלאריסה לפני השואה, ואחריה. סירב לשתף פעולה עם הגרמנים בזמן השואה, ובזכותו הספיקו להימלט חלק מיהודי לאריסה."},{"i":43266,"n":"קסטור, יצחק מגרוסורדין","b":"מחכמי גרוסורדין-תרלז. חבר ב\"מחזיקי תורה\". נזכר ב\"אגרת צפון\" לשוורץ."},{"i":43267,"n":"קסטיל, אברהם מחברון","f":"ניסים","b":"מחכמי חברון, חתן ר שלום מני. מו\"צ בליסבון-תרע. אחיו של ר חיים מאתונה."},{"i":43268,"n":"קסטיל, אברהם מחברון","b":"בשנת תקיז ראש רבני חברון. נכדו של ר' אברהם אזולאי, תלמיד ר אברהם ישראל זאבי, ר נחמיה דנינו, ר יצחק ן ארחא, ר חיים מרדכי זאבי, ר עזריה אשכנזי. חתום בשנת תקד על אגרת שליחות ר אברהם גדיליה, בשנת תקי חתום על קבלת כספים מאת ר יהודה אסיאו, הסכים על ספרו של החידא \"שער יוסף\" בשנת תקיד, ועל ספר \"אורים גדולים\" לר אברהם חיים ישראל זאבי בשנת תקיח."},{"i":43269,"n":"קסטיל, אליהו יהודה","b":"מחכמי חברון, חתם בשנת תקי על קבלת כספים מר יהודה אסיאו, בתקכה חתם על אגרת רבני חברון שנדפסה בונציה, בתקמב חתם על אגרת שליחות ר ישראל זאבי"},{"i":43270,"n":"קסטיל, חיים","f":"נסים","bt":"תרמו","dt":"תרפד - כח סיון","b":"גדול בתורה ומדע,רב באתונה-תרע\"ד"},{"i":43271,"n":"קסטיל, חיים מחברון","f":"נסים","bt":"תרמו","dt":"תרפד - כח סיון","dp":"אתונה","b":"תלמיד ישיבת \"שדי חמד\" בחברון, מחכמי חברון, אחיו של ר אברהם מליסבון, נשלח בהמלצת ר\"א דנון והד\"ר אביגדור יעקבזון מקושטא לכהן כרב באתונה-תרעד. פרסם מאמרים ב\"איל ז'ודייו\", ועוד ובהם מחקרים על קהלות היהודים בפאטראס, לאריסה, חאלקירה, קורפו, קאבאלה, דראמה, פלורינה, בירייה."},{"i":43272,"n":"קסטיל, חיים שלום","b":"מחכמי חברון בשנת תריא."},{"i":43273,"n":"קסטיל, יהודה","b":"מחכמי חברון, בשנת תקכג חתם על כתב שליחות ר רחמים באגיו ור יצחק זאבי, ובשנת תקצט על שליחות ר מנחם בורלא ור יוסף אליקים."},{"i":43274,"n":"קסטיל, יהודה מחברון","f":"אליעזר","k":"בעל קול זמרה","bt":"תרלא","bp":"חברון","dt":"תרצו - טו תמוז","dp":"ירושלים","b":"מו\"ץ ושו\"ב בעזה, מחכמי חברון, ר\"מ בירושלים, מנהל ת\"ת בסמרקנד וקוקנד-בוכרה-תרסב, מורה ב\"דורש ציון\", פעיל צבור ואסף פיוטי קדמונים, ואף חיבר שירים ומנגינות. אחיו של ר מאיר שמואל מחברון."},{"i":43275,"n":"קסטיל, יוסף דב מנ\"י","b":"פרסם מאמרים ב\"קובץ חדושי תורה\" - נ\"י תשד - קובץ תלמידי ישיבות \"תומכי תמימים ליובאויטש\"."},{"i":43276,"n":"קסטיל, יוסף חיים מירושלים","f":"יהודה","bt":"תרנט","bp":"ירושלים","b":"פעיל במוסדות תרבות שונים, עתונאי ב\"הארץ\", עבר לפאריס, לונדון והו\"ל שבועון יהודי באנגלית שלחם בפשיסטים באנגליה."},{"i":43277,"n":"קסטיל, יוסף מחברון","b":"מחכמי חברון, בשנת תפז חתם על כתב שליחות, ובשנת תקד על כתב שליחות ר אברהם גדיליה."},{"i":43278,"n":"קסטיל, יוסף משלוניקי","k":"בעל פירוש על ר בחיי","b":"מרבני שאלוניקי"},{"i":43279,"n":"קסטיל, יעקב מחברון","b":"מחכמי חברון, בשנת תקד חתם על כתב שליחות ר אברהם גדיליה. חתם על קבלת כספים מר יהודה אסיאו."},{"i":43280,"n":"קסטיל, יצחק מירושלים","b":"רב בירושלים-תקצו, חתם על מינוי ר יונה משה נבון לראשל\"צ."},{"i":43281,"n":"קסטיל, יצחק נובו מרומא","b":"רב ברומא. חתום ב\"מלחמה לה'\"-תעד על החרם נגד נחמיה חיון."},{"i":43282,"n":"קסטיל, מאיר","b":"מחכמי חברון, בשנת תקצט חתם על סדרי הכוללות."},{"i":43283,"n":"קסטיל, מאיר שמואל מחברון","f":"אליעזר","bt":"תרך","bp":"חברון","dt":"תרפט - יז אב","dp":"חברון","b":"מחכמי חברון, בשנת תרמד בשליחות בעירק והודו, בשנת תרנו בשליחות באלגיר, בשנת תרפא ראש הקהלה המשותפת לאשכנזים וספרדים. דיין אצל בעל \"שדי חמד\". נרצח על ידי הערבים בפרעות תרפט."},{"i":43284,"n":"קסטיל, משה מירושלים","bt":"תרסט","bp":"ירושלים","b":"צייר. תלמיד \"בצלאל\", למד אמנות בפאריס, התישב בתל אביב."},{"i":43285,"n":"קסטיל, נחמיה","b":"מחכמי חברון, חתם בשנת תקצט על תקנה."},{"i":43286,"n":"קסטיל, נסים מחברון","b":"מחכמי חברון-תרם, בניו - ר אברהם ור חיים."},{"i":43287,"n":"קסטילו, יוסף","f":"אברהם יצחק","b":"רב ומשורר. עליו ב\"קול עוגב\"."},{"i":43288,"n":"קסטיליו, אברהם יצחק","bt":"תפו","bp":"ספרד","dt":"תקמט - ט אב","b":"פייטן, דרשן, רב בליוורנו"},{"i":43289,"n":"קסטיליונה, שמואל ממנטובה","f":"משה","b":"רופא ומשורר מחכמי מנטובה - במאה ה-16. חיבר \"מאור הגולה\". והגה לפירוש ר נסים גירונדי למגילה."},{"i":43290,"n":"קסטיליוני, יצחק חיים מטריאסט","k":"בעל תולדות לשון עבר","b":"מחכמי טריאסט. תרגם לעברית את ספרו של שד\"ל \"תולדות לשון עבר\"."},{"i":43291,"n":"קסטין, יעקב אריה ליב מראגולה","k":"בעל משפטי יעקב","dt":"תש..","b":"רב בראגולה. נספה בשואה. פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":43292,"n":"קסטל, יהודה ממראקש","b":"מחכמי מראקש-שנות ה-ר'. מתורתו ב\"מראה עינים\" לר אלעזר בהלול."},{"i":43293,"n":"קסטלאץ - משפחה","b":"משפחה שמקורה בעיר קסטלאצו במחוז פיימונטה-איטליה (על כך ישעיהו זנה ודוד קויפמן, ובמאמר אברהם דוד \"משפחת קסטלצו\" - סיני תשכט). מבני המשפחה ר אברהם זכ\"ש מאיטליה שנשא ונתן עם המהרי\"ק, ר יחיאל שנשא ונתן עם ר יוסף קארו והמבי\"ט, ר שמעון ממצרים, ועוד."},{"i":43294,"n":"קסטלאץ אשכנזי, אביג","f":"שמעון קוסטילאץ","dt":"תיט","b":"מגדולי התורה במצרים"},{"i":43295,"n":"קסטלאץ, אביגדור ממצרים","f":"שמעון ממצרים","dt":"תיט - יט אדר","b":"רב במצרים, אחיו של ר משה מצפת, חברו של ר אהרן ן חיים בעל \"קרבן אהרן\", נזכר אצל ר יוסף סמברי אודות הנס שנולד בו. תלמידו ר יעקב פאראג'י מביא בתשובותיו -הנזכרות בחידא - מפסקי רבו."},{"i":43296,"n":"קסטלאץ, יחיאל זק\"ש","f":"[משה זכ\"ש מאיטליה]","bp":"אשכנז","dt":"שכה - אחרי","dp":"ירושלים","b":"עבר מאשכנז למצרים. בשנת רפט היה תלמיד ר יוסף זלמוני מאובן, התיישב בשלוניקי שם פגש את ר שלמה עטייה המזכירו בספרו. עלה לירושלים והיה מחכמי ירושלים, נשא ונתן עם ר יוסף קארו וחלק עליו בענין אשכנזי שעבר על חרם רבנו גרשום ונשא שתי נשים ונזכר ב\"ברכי יוסף\", וכן חלק עליו בדבר היחס לרש\"י כפוסק. נקרא גם ר יחיאל אשכנזי והוא אינו ר יחיאל בעל \"היכל ה'\" שחי כ-60 שנה אחריו. בניו ר שמעון קסטליץ רב במצרים, ור משה מחכמי מצרים וצפת."},{"i":43297,"n":"קסטלאץ, משה מצפת","f":"שמעון או יחיאל ממצרי","b":"רבה של הקהלה האשכנזית בצפת בזמן המהרי\"ט, אחיו של ר אביגדור (ולפי רוזניס אחיו של ר שמעון) ממצרים. השיב לר מאיר גאביזון ממצרים ונזכר בשו\"ת מהר\"ם גאביזון."},{"i":43298,"n":"קסטלאץ, שמעון ממצרים","f":"יחיאל בן משה זכש","k":"בעל מגילת סתרים","dt":"שמח - כ אייר","dp":"מצרים","b":"מחכמי קהיר תלמיד הרדב\"ז וחבר לר בצלאל אשכנזי, לאר\"י ור יעקב קאשטרו - המהריק\"ש, וחתם אתם על פסקים ותקנות. חתם-שכט על מכתב התמיכה של רבני קושטא ומצרים בדון יוסף נשיא. בשנת שמז חתם על תקנת המס. הניח שו\"ת וחדושים בכת\"י, חיבר פירוש על מגלת אסתר בשם \"מגלה סתרים\" (או מגילת סתרים) - בכת\"י, תשובותיו בספרי חכמי דורו, ב\"דברי יוסף\" מונהו כדור ה-26 לרבן יוחנן בן זכאי. בנו ר אביגדור רב במצרים.","bk":[["מגילת סתרים - מגילת אסתר",""]]},{"i":43299,"n":"קסטלבולונייזי, מזל טוב ישי","f":"גור אריה","bt":"תרן","dt":"תשי - בערך","b":"רב ראשי בלוב-תרצג - מטעם השלטון האיטלקי - כשנתיים. עליו ב\"יהודים בארץ ערבית\" מאת רנצו דה פליצ'ה - תל אביב 1980."},{"i":43300,"n":"קסטלמן, יחיאל פישל מטלומטש","f":"יעקב","k":"בעל מסעות שליח צפת","bt":"תקפה","bp":"טלומטש","b":"עלה לארץ-תרי. בשליחות-תריט בארצות המזזרח. וחיבר \"מסעות שליח צפת\" ירושלים תשב. בנו משה נרצח-תרכט על ידי ערבים."},{"i":43301,"n":"קסטנבוים, אהרן צבי","dt":"תשד","b":"מו\"צ באוילאק"},{"i":43302,"n":"קסטנברג, אברהם יהודה אריה הלוי","b":"רב בראדום. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"יבנה\" - לבוב תרפט."},{"i":43303,"n":"קסטנברג, חיים מנחם מנדל","f":"יחיאל הלוי","bt":"תרכב","b":"נכד-אבי אמו ר יהודה ליבוש רייטביין מגריצא. חתן ר פנחס מרגליות. דומ\"צ בראדום-תרנ\"ה. נסמך מאת ר חיים אלעזר וקס מקאליש, ר ישראל יהושע מקוטנא בעל \"ישועות ישראל\", ר ישראל יצחק מפאוואנזיק. פרסם מאמרים ב\"המאסף\" - ירושלים - ובהם חיבור על הלכות נידה. בנו - ר יחיא.ל."},{"i":43304,"n":"קסטנברג, יחיאל מראדום","f":"חיים מנחם מנדל מראדו","bt":"תרמח","bp":"ראדום","dt":"תשג","b":"נסמך מאת: רמ\"נ ירושלמיסקי. רב בוירזבניק-תרעג, ראדום על מקום אביו. עזר לסנגוריה בזמן משפט בייליס. פרסם מאמרים ב\"המאסף\" - ירושלים. נספה בשואה?"},{"i":43305,"n":"קסטנברג, משה יוסף","b":"תשובה אליו ב\"שואל ומשיב\"-תריד."},{"i":43306,"n":"קסטנברון, יוסף מקולומיאה","b":"רב בקולומיאה, ויזניץ. תשובות רבות אליו."},{"i":43307,"n":"קסטנברון, משה","f":"יוסף מקולומיאה","b":"תשובה אליו לנדבורנה-תריד."},{"i":43308,"n":"קסטנר, דוד מפרשבורג","f":"עזריאל מפרשבורג","dt":"תרפד - ח אד\"א","dp":"פרשבורג","b":"תלמיד השב\"ס. מחכמי פרשבורג. ממיסדי אגודת \"מבקשי תורה\" בפרשבורג-תרעו, \"עץ חיים\"-תרעא."},{"i":43309,"n":"קסטנר, חיים דב מפרשבורג","b":"עסק בהצלת יהודים בראשית ימי השואה - תרצח."},{"i":43310,"n":"קסטנר, עזריאל מפרשבורג","b":"חתן ר משה אריה ליב ליטש-רוזנבוים מפרשבורג."},{"i":43311,"n":"קסטרובסקי, דוד","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי."},{"i":43312,"n":"קסי ן, אברהם","b":"דיין בטוליטולה"},{"i":43313,"n":"קסיס, יוסף מאיטליה","b":"רופא מגדולי חכמי איטליה,רב במנטובה-ת\"ס"},{"i":43314,"n":"קסיס, מאיר משלוניקי","b":"מחכמי שלוניקי-שי."},{"i":43315,"n":"קסל, דוד","k":"הו\"ל יסוד עולם","b":"הו\"ל \"יסוד עולם\" לר יצחק הישראלי - ברלין תרה, יחד עם חברו ר דב בער גולדברג."},{"i":43316,"n":"קסל, טודרוס מוילנא","f":"יצחק איזיק","dt":"תקצד - ח שבט","b":"חתן ר שמעון נעכעס מוילנא. פרנס בוילנא וחתם בראש. בנו ר אברהם אליהו."},{"i":43317,"n":"קסל, משה אבא","dt":"תשא","b":"רב בועד הרבנים בווילנה"},{"i":43318,"n":"קסלוביץ, אריה ליב מקרשוב","b":"פרסם מאמרים ב\"מציון תצא תורה\" - זאמושט תרפט."},{"i":43319,"n":"קסלינר, יעקב","b":"רב בלאקטש,ר\"מ בקאוולי"},{"i":43320,"n":"קסלמן, שמואל הכהן","f":"ישראל","bt":"תרלב","b":"רב בטשארטאריע חדשה-ווהלין-תרסג."},{"i":43321,"n":"קסלר, אפרים ברוך מליטוביסק","dt":"תשג","b":"רב בליטוביסק, נספה בשואה יחד עם בנו ר יחזקאל יום טוב ליפא."},{"i":43322,"n":"קסלר, יוסף אביגדור מליטא וארהב","f":"יו\"ט ליפמן","k":"בעל תפארת יוסף-תשא","bt":"תרמה","bp":"קלם","dt":"תשטז","b":"תלמיד ישיבת קלם(=קעלם), מיר, איישישוק, וולוזין. חתן ר זאב טורבוביץ מקרוז' בעל \"תפארת זיו\". רב בווארזאן(ורז'אן), קרוז' על מקום חותנו, היגר לארה\"ב-תרפג וכיהן כרב בראקוויי-פרק-ארה\"ב. הו\"ל ספר חותנו \"תפארת זיו\" עם הערות ממנו בשם \"יד יוסף\". חבר בועד הרבנים בארה\"ב ועסקן ציבורי חשוב. מאמר ממנו ב\"שערי אורה\" - מיהאלביץ תרץ-תרצד."},{"i":43323,"n":"קסלר, ישראל אהרן מירוסלב","f":"יצחק איזיק מהולשיץ","bt":"תרסב","bp":"ירוסלב","dt":"תשנז","b":"חתן ר משה ירוסלביץ מכפר ריצא (ליד נרול). ניצל מהשואה - גלה לסיביר. בזיוו\"ש חתן ר פסח גרינברג מלוביטש. היגר לארה\"ב ונדד כשו\"ב באזור ניו יורק. חסיד בובוב וסקווירא."},{"i":43324,"n":"קסלר, לייב","b":"תלמיד הבעשט שגילה לו על הסתלקותו הקרובה, ועמד ליד מיטת רבו בשעת פטירתו."},{"i":43325,"n":"קסלר, צבי מלבוטשנה","dt":"תש..","b":"שו\"ב ורב בלוטשנה - שבקרפטים. נספה בשואה."},{"i":43326,"n":"קספו, יעקב","dt":"תסח - כב שבט","b":"רב בליסבון"},{"i":43327,"n":"קסרס, בנימין חזקיה בצלאל","b":"רב בקורסאו-תקץ ודיין עם ר משה לופיס פינייא."},{"i":43328,"n":"קסרס, שמואל מאמשטרדם","dt":"תך","dp":"אמשטרדם","b":"סופר ומשורר באמשטרדם, גיסו של ברוך שפינוזה, תלמיד ר שאול מורטירה. ר\"מ בישיבת \"עץ חיים\" באמשטרדם-תג, הגיה את תרגום התנך לספרדית. חיבר שירים ופיוטים ובהם \"יגדל אלקים חי\". חברו של ר שלמה אוליוירה."},{"i":43329,"n":"קעדס (קרעס), משה","b":"מתלמידי הבעש\"ט-תקכ"},{"i":43330,"n":"קעוואל, בנימין","k":"בעל פרחי קדם","b":"בקי בלשונות. חיבר \"פרחי קדם\" והוא ממשלי אזופוס - וינה תרג."},{"i":43331,"n":"קעל, בנימין זאב הלוי משארבוגרד","b":"פרסם מאמרים ב\"יגדיל תורה\" - ברלין-קראקא תרנא."},{"i":43332,"n":"קעלין, גבריאל הלוי","b":"נכד ר שמואל בעל מחצית השקל. תלמידר יצחק משה פרלס מבאניהאד והחת\"ס. נפטר בהיותו חתן בחיי רבו שהספידו."},{"i":43333,"n":"קעלין, שמואל הלוי מבסקביץ","f":"נתן נטע הלוי","k":"בעל מחצית השקל","bt":"ה'תפד","dt":"תקסז - כח אדר","b":"מרביץ תורה, רב בבסקביץ-תקז. מאמר ממנו ב\"עמק הלכה\" - באטארקס תרפא. בנו - ר בנימין זאב וולף בוסקוביץ בעל \"סדר משנה\", ר יעקב.","bk":[["מחצית השקל [על או\"ח ויו\"ד",""],["עהש\"ס]",""],["מחצית השקל",""]]},{"i":43334,"n":"קעלל, נתן נטע משארבאגארד","f":"אהרן הלוי","bt":"תריב","dt":"תרפד - כח תשרי","b":"נכד ר שמואל הלוי קעלין מבסקביץ בעל \"מחצית השקל\". תלמיד הכת\"ס, ור אליעזר זוסמן סופר מפאקש ואחיו ר חיים סופר מבודפשט. חתן ר אברהם צבי אבלס משארבאגארד. רב בשרבוגרד על מקום חותנו-תרלב וחתנו ר צבי הרש אברמזון על מקומו אחריו. פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה, \"וילקט יוסף\", \"תל תלפיות\"."},{"i":43335,"n":"קעסילמן","k":"ראה: קסלמן","b":"ר\"מ בישיבת \"בית אהרן\". פרסם מאמרים ב\"בית אברהם\" - וארשא תרצד."},{"i":43336,"n":"קעסלין, חיים מברלין","f":"נפתלי","k":"בעל המסלול","b":"מחכמי ברלין. חיבר \"המסלול\" המבורג תקמח, \"קריאת התורה\", מאמר בשם \"באר רחובות\" על לשון המשנה."},{"i":43337,"n":"קעסען, אברהם מנחם מארה\"ב","dp":"ניו יורק","b":"רב בניו יורק."},{"i":43338,"n":"קעפעטש, שמואל מקלויזנבורג","b":"רב בקלויזנבורג-תרף."},{"i":43339,"n":"קערן, יעקב מפעסט","bt":"תקסד","dt":"תרכה - ב תשרי","b":"גביר בפעסט-תקץ ומראשי הקהלה. הקים חברות לעזרת היהודים ובהם חברת לעבודת האדמה."},{"i":43340,"n":"ק\"פ, יוסף","b":"נזכר בשו\"ת מהרם פאדובה עם חברו ר משה הלוי כרעיו האהובים."},{"i":43341,"n":"ק\"פ, יוסף מאיטליה","b":"מחכמי איטליה-שנת ש'"},{"i":43342,"n":"קפואה, דוד מירושלים","b":"מחכמי ירושלים, בשליחות בקושטא-תיח והתחבר שם עם ש\"ץ בתחילת דרכו."},{"i":43343,"n":"קפוסטין, זאב וולף","dt":"תרצח - ח אב","b":"רב בפילדלפיה"},{"i":43344,"n":"קפוצטו, אליהו מקושטא","f":"משה","b":"מחכמי קושטא-רן בזמן הרא\"ם."},{"i":43345,"n":"קפוצטו, משה משלוניקי","dt":"רן - בערך","b":"רב ופייטן בשלוניקי-ריז. חיבר פירוש לתורה, פיוטים ממנו במחזור רומנייא-קושטא, וקורפו. לחם בקראים ובדעותיהם. בנו - ר אליהו. חכמי הקראים כתבו כנגדו ובהם: ר אליהו בשייצי, ר אברהם בלי הרופא ב\"אגרת אסור נר שבתי\", ר כלב אבא אפונדופולו."},{"i":43346,"n":"קפין, יהודה יום טוב מרודוס","b":"רב ברודוס-תקן בערך."},{"i":43347,"n":"קפלוטו, חיים מירושלים","b":"מרבני ירושלים-ת\"ר"},{"i":43348,"n":"קפלוטו, חיים מירושלים","f":"ירחמיאל","b":"מרבני ירושלים-תרמ\"ז"},{"i":43349,"n":"קפלוטו, יעקב מירושלים","k":"בעל תקנות ירושלים","dt":"תרכד","b":"ראב\"ד בירושלים"},{"i":43350,"n":"קפלוטו, נסים","f":"יעקב","bt":"תקצו","bp":"ירושלים","b":"מחכמי ירושלים וחברון, בשנת תריא חתם על כתב שליחות ר דוד הכהן. בשנת תרכג בשליחות, ובשנת תרכח בשליחות באדרינופול."},{"i":43351,"n":"קפלונסקי, אברהם יעקב מסילעץ","b":"רב בסילעץ(=שיליעץ)-תרסו, הסכים על אור ישן."},{"i":43352,"n":"קפליבטובסקי, דוד","f":"יונה מאפרעשטי","b":"נכד-אבי אמו ר מנחם נחום מטשרנוביל. תלמיד ישיבת בריסק, נווהרדוק."},{"i":43353,"n":"קפליבטובסקי, יונה מקאפרשטי","f":"יצחק אייזיק מפרניבקה","k":"בעל כנפי יונה","bt":"תרכב","b":"דור 13 ברבנות. חתן ר מנחם נחום מצרנוביל. רב בקאלאניע לובלין-בסרביה, קאפרשטי(=קאפרעשטי)-בסרביה-תרנב. נסמך מאת:ר ישראל איזנשטין בעל \"עמודי אש\", ר קלמן ברקוביץ מסאווראן, ר יחזקאל שפירא מבאפאלי, ר מרדכי פרנקל מסאראקא, ר אשר דויסמן ממאהלוב. חיבר שו\"ת \"כנפי יונה\" - בכת\"י. בנו - ר דוד, חתנו - ר זאב דערבארמדיגר מאישישוק."},{"i":43354,"n":"קפליבטובסקי, יצחק איזיק","dt":"תרם","b":"מצאצאי ר יצחק איזיק מקוריץ בעל \"ברית כהונת עולם\". רב בפארניבקה(=פארניווקע)-פודוליה על מקום אבותיו."},{"i":43355,"n":"קפלן אברהם אליהו","r":"ר\"מ בבית מדרש לרבנים בברלין","bt":"1890","dt":"ה'תרפד 1924","bk":[["מאמר",""],["בעקבות היראה",""],["דברי תלמוד",""],["מבחר כתבים",""]]},{"i":43356,"n":"קפלן, אבא ליב מארה\"ב","b":"רב בשיקגו."},{"i":43357,"n":"קפלן, אברהם אליהו מקידאן - אב","bt":"תריד","bp":"ראקוב","dt":"תרמט","dp":"קידאן","b":"ראש ישיבה בלומז'ה. תלמיד ישיבת וולוזין, מינסק. חתן הרב במראקוב, ובזיוו\"ש חתן ר זלמן טרויב, התישב בקידאן. ר\"מ בביהמ\"ד בברלין, ר יחיאל יעקב וינברג בעל \"שרידי אש\" על מקומו אחריו. נפטר צעיר ובנו שנולד אחר פטירתו נקרא ע\"ש. חיבר כתבים רבים ורובם אבדו בשריפה הגדולה בקידאן. נשאר מעט מחדושיו ומחברת משיריו."},{"i":43358,"n":"קפלן, אברהם אליהו מקידאן - בן","f":"אברהם אליהו מקידאן","bt":"תרן","bp":"קידאן","dt":"תרפד","b":"נולד אחר פטירת אביו ונקרא ע\"ש. גדל אצל זקנו ר שמעון טרויב מקידאן. תלמיד ישיבת טלז, בת\"ת אנשי המוסר בקלם, ישיבת סלובודקה אצל הסבא מסלובודקה. אחר מלחה\"ע החל עוסק בעניני ציבור, ממיסדי ארגון הנוער \"צעירי ישראל\". ר\"מ בביהמ\"ד בברלין והנהיג שם שיטת לימוד ליטאית, ר יחיאל יעקב וינברג בעל \"שרידי אש\" על מקומו אחריו. החל לחבר פירוש חדש לתלמוד והספיק רק את המבוא. נפטר צעיר. פרסם מאמרים ב\"ישורון\" - ברלין תרף, \"שילה\" - ירושלים תשה, \"תבונה\" - ירושלים תשא, ועוד, ובהם \"בעקבות היראה\" שהתפרסם בזמנו."},{"i":43359,"n":"קפלן, אברהם הכהן","k":"בעל חיי אברהם מאפו","bt":"1839","bp":"קובנא","dt":"1897","b":"מחבר ומתרגם. פרסם מאמרים ב\"המגיד\", \"השחר\", \"הצפירה\", ועוד. חיבר גם \"תרועת מלך\". תרגם לעברית את ההיסטוריה של גרץ, ועוד."},{"i":43360,"n":"קפלן, אברהם מארה\"ב","bp":"קיידנוב-פלך מינסק","b":"עסקן צבור בניו יורק."},{"i":43361,"n":"קפלן, אלחנן הכהן","b":"דיין בסוויסלאטש"},{"i":43362,"n":"קפלן, אליהו יוסף מפורליץ","f":"יעקב","bt":"תרמג","b":"רב בפורליץ-בסרביה-תרסח."},{"i":43363,"n":"קפלן, אליעזר","bt":"1851","bp":"גרודנא","dt":"1915","b":"תלמיד ישיבות ליטא, התקרב להשכלה. סוכן בית החרושת לטבק של שרשבסקי בוארשא, מראשוני חובבי ציון בוארשא וממיסדי חברת \"מנוחה ונחלה\". ממיסדי \"חברת אחיאסף\" שהוציאה את \"הדור\", \"דער יוד\", ועוד. פרסם מאמרים בעניני ספרות וספרים."},{"i":43364,"n":"קפלן, אליעזר זאב מראדין","dt":"תשג","b":"נכד החפץ חיים. חתן ר ר צבי הירש לוינזון. ר\"מ בראדין-תרפה. נספה בשואה."},{"i":43365,"n":"קפלן, אלכסנדר סנדר","k":"בעל שלמי נדרים-בכת\"י","bt":"1816?","dt":"תרמד","b":"דיין בוילקומיר אצל ר אהרן מוילקומיר, רב בקופשאק-תרל כ-45 שנה.","bk":[["שלמי נדרים","מפרשי ש\"ס - אחרונים"]]},{"i":43366,"n":"קפלן, אפרים","f":"זלמן פנחס","k":"בעל מפלגות וכיתות","bt":"1879","bp":"שאט","dt":"1943","b":"אביו היה רב ביאזנה, גאלוואן. נכד ר מאיר מיכל רבינוביץ, ונינו של ר אברהם אחי הגר\"א. תלמיד ישיבת סלובודקה. פנה להשכלה ועבר לקובנא. פרסם ב\"המליץ\", \"הצפירה\", ועוד. היגר לארה\"ב-1904, עורך \"מארגן ז'ורנאל\" בניו יורק. חיבר גם \"ראשי הגולה\", \"נוסעים יהודים בימי הביניים\", ועוד."},{"i":43367,"n":"קפלן, אריה ליב הכהן מארה\"ב","f":"אלחנן מזעלווא וגרודנ","bt":"תרמג","bp":"סויסלוביץ-פלך גרודנא","b":"תלמיד ישיבת קריניק, ראדין, ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\", ונסמך ממנו ומאת בעל \"חבל יעקב\" מוילקומיר. חתן ר שלמה נתן קוטלר. היגר לארה\"ב-תרסז וכיהן כרב בשיקגו. פרסם מאמרים ב\"הפרדס\" ועוד. חבר אגודת הרבנים באמריקה, ואגודת ישראל."},{"i":43368,"n":"קפלן, ברוך","dt":"תשג","b":"רב בשאקאט"},{"i":43369,"n":"קפלן, גרשון הכהן מריגא","f":"אברהם יצחק","bt":"תרסג","bp":"מינסק","dt":"תשג - יד ניסן","b":"תלמיד ישיבת גרודנא, מיר, ונסמך מאת: ר שמעון שקופ, ור אליעזר יהודה פינקל. חתןר בנימין בלוך. רב בריגא. נספה בשואה."},{"i":43370,"n":"קפלן, דב אריה","dt":"תשג","b":"רב בטשכנווצה"},{"i":43371,"n":"קפלן, דוד","f":"צבי מאיר","bt":"1900","bp":"בוטרימנץ","dt":"1965","dp":"ירושלים","b":"מהנדס כימאי. עלה לארץ-1927, עבר במפעלי ים המלח."},{"i":43372,"n":"קפלן, דן","bt":"1879","bp":"זאלווה-פלך גרודנא","dt":"1952","dp":"מיאמי","b":"הצטרף לתנועה הסוציאליסטית, נאסר בוארשא ובמוסקבה, ברח והיגר לארה\"ב. פרסם שירים. עורך \"וועקער\". תרגם לאידיש \"ממרכס עד לנין\", ועוד."},{"i":43373,"n":"קפלן, זאב וולף - זק\"ן","bt":"1826","bp":"טרישקי","dt":"1887","dp":"ריגא","b":"משורר ומשכיל. תלמיד מ.א. גינצבורג. חבר של מיכ\"ל חבר ומחותן עם יל\"ג. מנהל בית ספר עברי בריגא. פרסם ב\"השחר\", \"האסיף\", ועוד. פעיל בתנועה הציונית.","bk":[["זיו משנה","מפרשי רמב\"ם"]]},{"i":43374,"n":"קפלן, זלמן פנחס מיאזנה","bt":"תר","bp":"פוניבז","dt":"תרפא","dp":"גאלוואן","b":"נכד ר אברהם-אחי הגר\"א. חתן ר מאיר מיכל רבינוביץ משאט. רב ביאזנה, גאלוואן על מקום ר יהושע קלוואן. בזמן מלחה\"ע ה-I נאסר עם כמה יהודים והובלו לוילנא, שוחרר עם נסיגת הרוסים. בנו הסופר אפרים קפלן."},{"i":43375,"n":"קפלן, חיים","dt":"תשג","b":"רב בפאבירזש"},{"i":43376,"n":"קפלן, יהושע הכהן מוידוקלה","f":"מאיר","k":"בעל שער יהושע","bt":"תרלג","bp":"פאטשיצה-פלך מינסק","dt":"תשג","b":"תלמיד ישיבת סלובודקה, ונודע בכינוי \"המתמיד מבוברויסק\", וולוזין. חתן ר יהודה פאלישץ, והמשיך ללמוד בכולל האברכים בוולוזין ע\"ש ברודסקי. רב בוארשא-תרעג, קרוקי-תרעט, סוביינישוק-תרף, רבה האחרון של וידוקלה-תרפז. חיבר גם \"שערי הקדש\", ועוד. נספה בשואה עם בני עדתו. בנו ר מאיר קפלן דיין בתל אביב."},{"i":43377,"n":"קפלן, יוסף בר מארה\"ב","f":"יעקב ליב","bt":"תרעה","bp":"ניו יורק","b":"תלמיד ישיבת \"תורה ודעת\" בניו יורק, ישיבת קמניץ, מיר. נסמך מאת ר ברוך בר ליבוביץ ממיר. חתן ר יצחק אליעזר שינפלד. רב קהלת \"מגן ומושיע בית דוד\" בבוסטון. חבר אגודת הרבנים באמריקה."},{"i":43378,"n":"קפלן, יחיאל מנ\"י","b":"פרסם מאמרים ב\"נר מערבי\" - נ\"י תרפד - קובץ ישיבת ר יצחק אלחנן."},{"i":43379,"n":"קפלן, יעקב זלמן הכהן מוילנא","b":"מו\"צ בוילנא."},{"i":43380,"n":"קפלן, יעקב ממינסק","f":"שלמה זלמן","b":"מחכמי מינסק ומשכיל, הגיה וערך \"ארץ קדומים\"."},{"i":43381,"n":"קפלן, יצחק יונה מהרארדוק","f":"חיים קויפמן","b":"חתן ר אברהם מאיר הלר מקאיידנוב. רב בהאראדוק-תר\"מ."},{"i":43382,"n":"קפלן, יצחק מווילקי וארה\"ב","k":"בעל עין יצחק - בכת\"י","b":"רב בווילקי, רוצ'סטר-ארה\"ב."},{"i":43383,"n":"קפלן, יצחק מריגא","dt":"תשג","b":"רב בריגא"},{"i":43384,"n":"קפלן, יקותיאל זוסמן מסטראבין","bt":"תקצט","dt":"תרס - ח אייר","b":"חתן ר אהרן הלוי מסטראבין(=סטרבין). רב בסטראבין."},{"i":43385,"n":"קפלן, ישראל הכהן","f":"יהושע","k":"בעל אין דער טאג טעגל","bt":"1902","bp":"וולוזין","b":"אביו היה רב בוולוזין. הסטוריון. פרסם מאמרים וסיפורים על יהודי ליטא. חיבר ספרי לימוד בעברית ובליטאית. בזמן השואה היה בגיטו קובנא וערך את רשומו הגיטו, עבר לגיטו ריגא, דכאו וניצל יחד ממשפחתו מהשואה - כתבי היד שערך אבדו. עבר למינכן והיה עורך ב\"אונדזער וועג\". חוקר שואה ועורך הקבצים \"פון לעצטן חורבן\". עלה לארץ-1949 וחיבר מונוגרפיות על קהילות ליטא."},{"i":43386,"n":"קפלן, ישראל חיים ממונטריאול","b":"ר\"מ בישיבת בריסק. פרסם מאמרים ב\"מרכז התורה\" - מונטריאול תשב, \"המתיבתא\" - נ\"י תשג, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":43387,"n":"קפלן, ישראל ממינסק","b":"בעל ביה\"ס \"לתורה ודעת\" במינסק-תרן."},{"i":43388,"n":"קפלן, ישראל מנדל","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי."},{"i":43389,"n":"קפלן, ישראל מניו יורק","b":"רב בניו יורק-תר\"נ"},{"i":43390,"n":"קפלן, ישראל מסרדניק","f":"יצחק יונה מהורודוק","k":"בעל חכמה ומוסר","bt":"תרלה-ח","dt":"תרצו - כז ניסן","dp":"קובנא","b":"תלמיד זקנו - ר אברהם מאיר הלר מקוידנוב. חתן ר זאב דב ליפשיץ מסרדניק בעל \"מעין חיים\". נסמך מאת: ר שלמה הכהן מוילנא, ר מרדכי מסלונים. רב בסרדניק-פלך קובנא-תרסא על מקום חותנו. מראשי המזרחי בליטא. פרסם מאמרים בכתב עת ובהם \"העברי\" וחתם בשם \"מזה לבית מזים\". רב צבאי ראשון בליטא-תרף, ציר בקונגרס הציוני-תרפה. חיבר \"חכמה ומוסר\" על פרשיות התורה, ועוד חדושים - בכת\"י. (ביהדות ליטא - תאריך פטירתו - תרפו)."},{"i":43391,"n":"קפלן, מאיר הכהן","dt":"יב טבת תשנ\"ד","b":"פרסם מאמרים ב\"תל תלפיות\" - ירושלים תשא.","bk":[["דברי מאיר",""]]},{"i":43392,"n":"קפלן, מרדכי אהרן מניו יורק","k":"בעל רוח הדעת","b":"רב בניו יורק"},{"i":43393,"n":"קפלן, מרדכי מנחם","k":"בעל ערכי היהדות והתח","bt":"1881","bp":"סאונציאן","b":"היגר לארה\"ב, למד באונ' קולמוביה ובסמינר היהודי התיאולוגי. רב בקהילת \"ישורון\" בניו יורק. מנהל המכון הפדגוגי שע\"י הסמינר התיאולוגי ופרופ' לדרשנות בסמינר. מיסד תנועת ה\"קרונסטרקשן\". לכבודו יצא ספר יובל - ניו יורק תשיג."},{"i":43394,"n":"קפלן, משה מארה\"ב","b":"פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":43395,"n":"קפלן, נחום מהורדנא","f":"עוזיאל","k":"נחומק'ה מהורדנא","r":"מחוללה של אגודת ישראל","bt":"תקעב","bp":"בייסיגולה","dt":"תרם - ח חשון","b":"תלמיד ישיבות ליטא ובהם וולוזין. התישב בגרודנא(=הורדנא) וסירב לרבנות והסכים לשמש כשמש בחברת ש\"ס. התמסר למעשי צדקה וחסד ותמך במאות משפחות, ואת מקומו מילא אחריו - ר אברהם גלרבט מהורדנא. רוב 17 ילדיו נפטרו בחייו. בהלוויתו השתתפו רבבות יהודים ונכרים שכינוהו בשם \"הצדיק\"."},{"i":43396,"n":"קפלן, נתן צבי מקארקלאן","f":"דובער שנפלד מראסיין","dt":"תשג","b":"רב באנושישק, קארקלאן-פלך קובנא."},{"i":43397,"n":"קפלן, צבי","b":"פרסם מאמרים ב\"תבונה\" - ירושלים תשא."},{"i":43398,"n":"קפלן, שלמה זלמן פנחס מגילוואן","f":"יהודה ליב","bt":"תריד","b":"תלמיד ישיבת וולוזין, ור גרשון תנחום ממינסק בעל \"אילנא דחיי\". נסמך מאת: ר יצחק אלחנן מקובנא. חתן ר מאיר מיכל מוילנא בעל \"המאיר לעולם\". רב בגילוואן-פלך וילנא. חיבר חדושי תורה ושו\"ת."},{"i":43399,"n":"קפלן, שמואל ישראל הכהן מקאלנא","f":"ר\"א","bt":"תרלח","dt":"תשג","b":"רב בקאלנא-פלך לומזה-תרסה. פרסם מאמרים ב\"קובץ דרושים\" - פיעטרקוב תרפג."},{"i":43400,"n":"קפלן, שמעון טוביה מוארשא ונ\"י","k":"בעל שביל טוב","b":"רב בוארשא, ניו יורק. חיבר גם \"שם משמעון\". פרסם מאמרים ב\"פרח הלבנון\" - וארשא תרעח."},{"i":43401,"n":"קפלן, שמעון מירושלים","f":"ראובן","bt":"תרג","bp":"יפו","b":"שותף בפירמה \"כספי דיסקין קפלן\" ביפו."},{"i":43402,"n":"קפלנדר, אברהם מארה\"ב","b":"רב מטיף ועסקן צבור בג'ונסטון-פנסילבניה."},{"i":43403,"n":"קפלנוביץ, דן","k":"בעל איינזאמע מענטשן","bt":"1880","bp":"ורניאן-פלך וילנא","dt":"1930","b":"תלמיד ישיבות ליטא. הצטרף לתנועה המהפכנית ונאסף וגלה לסיביר. פרסם תיאורים מחיי הגולים בסיביר ב\"פריינד\", ועוד. תרגם סיפורים. חבר מערכת \"צייט\" בוילנא. חיבר גם \"זכרונות פון א ניקאלאיעווער סאלדאט\" וילנא 1921."},{"i":43404,"n":"קפלנסקי, ? משאוולי","b":"ר\"מ בישיבת שאוולי אצל ר יצחק מאיר יודלביץ."},{"i":43405,"n":"קפלנסקי, חיים זליג מלויקובה","dt":"תשג","b":"רבה האחרון של לויקובה(=ליקובא). נספה בשואה."},{"i":43406,"n":"קפלנסקי, ישראל הלל מליטא וחבר","f":"חיים","bp":"ליקנובה","dt":"תרפט","dp":"חברון","b":"תלמידי ישיבת סלובודקא-חברון. נהרג עק\"ה בפרעות תרפט."},{"i":43407,"n":"קפסלי - משפחה","b":"משפחת רבנים בקנדיא(=כרתים), איטליה וקושטא. מקור השם בעיר קפסאל על האי צירוגו ליד כרתים."},{"i":43408,"n":"קפסלי, אליהו מקושטא","b":"קושטא-ר\"נ-ש'"},{"i":43409,"n":"קפסלי, אליהו מקנדיא - הזקן","f":"משה","b":"רב בקנדיאה(=כרתים). בר פלוגתיה של מוהר\"ם אלאשקר (ואולי הכוונה לנכדו?). תלמיד ר יהודה מינץ בפדובה המביא ממנו בספרו. מתלמידיו - ר שמואל אלגזי בעל \"תולדות אדם\" - ונציה. בנו - ר משה מקושטא. נכדו ר אליהו בן אבא אלקנה כתב כי זקנו ניצל ממות באיטליה - לאחר ששודדים הרגו את כל מלויו (תלמידים ורבנים) בדרכם לישיבה באיטליה."},{"i":43410,"n":"קפסלי, אליהו מקנדיא - הנכד","f":"אבא אלקנה","k":"בעל דברי הימים ליהוד","bt":"רנ או רמ","b":"נכד ר אליהו הראשון. מקובל, דרשן, מגדולי חכמי איטליה. נשלח ללמוד באיטליה והגיע לפדובה שבוע לפני פטירתו של מהר\"י מינץ, תלמיד ר ישראל איסרל אשכנזי, ר יצחק הלוי אינגלהיים, חזר לקנדיא ולמד אצל דודו ר מנחם. בעל ספריה גדולה. רב בקנדיא בזמן ר עמנואל חן, ר שאול הכהן, ור יהודה דילמדיגו - והיה מחלוקת בינו לבין חבריו - וכמה מחכמי הדור נתבקשו להכריע ביניהם ובהם ר יוסף קארו. חיבר \"דבי אליהו\" - \"דברי הימים ליהודי תוגרמה\", \"נועם וחובלים\", \"מאה שערים\". \"סדר אליהו זוטא\". תשובה ממנו בענין - קוסטנר (תליין יהודי אצל התורכים - שהכריחו את היהודים לבחור תליין כדי להשפיל את הנתלים שנהרגו בידי יהודים - ודן האם התליין כשר לעדות). בנו - ר משה."},{"i":43411,"n":"קפסלי, אליעזר מקנדיא","f":"אליעזר","b":"מחכמי קנדיא. נזכר בתקנות קנדיא שנדפסו ב\"אהל דוד\"."},{"i":43412,"n":"קפסלי, אלעזר מקושטא","b":"מראשוני חכמי קושטא-ר' בזמן ר משה קפסלי ור אליהו הלוי הראשון. לימד תורה לקראים כדי לקרבם והיה מחלוקת כנגדו מצד ר משה קפסלי."},{"i":43413,"n":"קפסלי, אלקנה מקנדיא","b":"תלמיד ר יהודה מינץ. מחכמי קנדיא ומראשי הקהילה בזמן גירוש ספרד - ופעל רבות לסייע למגורשים שהגיעו לקנדיא. נזכר בספר בנו ר אליהו מקנדיא ואיטליה."},{"i":43414,"n":"קפסלי, דוד מקנדיא","b":"מחכמי קנדיא, אחיו של ר משה מקושטא."},{"i":43415,"n":"קפסלי, משה מקושטא","f":"אליהו","dt":"רנה-ז","dp":"קושטא","b":"מקורב למלכות, ראש הרבנים בקושטא, והיה במחלוקת עם מהר\"י קולון ור משה עשרים וארבע השליח מירושלים. ר אליהו מזרחי - הרא\"ם, על מקומו אחריו. אחיו - ר דוד מקנדיא."},{"i":43416,"n":"קפרוקופו, מנחם משלוניקי","b":"מחכמי שלוניקי הקדומים, נזכר באוצר שיטות ותשובות."},{"i":43417,"n":"קצבורג, אביגדור מוייצען","b":"הו\"ל \"נטעי בחורים\" - וויצען תרסד. פרסם מאמרים ב\"אפריון\" - בודפשט תרפד."},{"i":43418,"n":"קצבורג, דוד צבי מוייצען","f":"משלם זלמן מבודפשט","k":"בעל מבשר צדק","bt":"תרטז","bp":"נאדי-בארזשאן","dt":"תרצז - ג אדר","dp":"וויצען","b":"תלמיד השב\"ס, ור נפתלי סופר מפטשי-ניידארף. ודודו ר ישראל חיים קצבורג מאוזד-באליאק. חתן ר אברהם יהושע זליג שוורץ מטיסא, ועבר לשם. רב בגרוסורדין-תרמג, סעטע-תרמח, ניערגעש-אויפאלו-תרמט, וויצען-תרנב. נסמך מאת: ר פיבל פלויט משוראן, ר ידידיה פישר משטוהלא סנבורג, ר שמחה בונם סופר מפרשבורג. חיבר גם \"מבשר צדק\" ועוד. חתניו - ר יצחק שמואל קצבורג מאוזד, ור משה יעקב פריד מקין-סנט מרטון. עורך \"תל תלפיות\" בוויצען ובודפשט. (במורשת רבני הונגריה נרשם אביו - ר ישראל חיים מאוזד', ובנו נרשם ר ירחמיאל - רבה האחרון של אוזד - כמו כן נרשם שהיה רב בטפלטשין - ואולי הוא בלבול עם ר יהושע דוד צבי קצבורג-ראה בערכו). פרסם מאמרים ב\"המגיד\" - סטמר תרפח. מאמר ממנו ב\"המעין\" - בודפשט תשז (לאחר השואה!). עורך \"תל תלפיות\" - וייצען תרנב-תרעד - שהחל לתמוך בציונות במאמריו. חיבר הקדמה ל\"שערי תשובה\" - פרשבורג תרעו - שהו\"ל ר מרדכי וינר, ובחלק מהטפסים הוסרה ההקדמה - כנראה בכוונה."},{"i":43419,"n":"קצבורג, יהושע דוד צבי","dt":"תקפו-צו -א תמוז","b":"ראב\"ד בטאפאלטשין"},{"i":43420,"n":"קצבורג, יצחק שמואל הכהן מאוזד","b":"רב באוזד. חתן ר ישראל יונגרייז מנאדאודוואר."},{"i":43421,"n":"קצבורג, ירחמיאל כץ מאזד","f":"ישראל חיים מאוזד","bt":"תרם","dt":"תשד","b":"נכד ר יוסף יואל דייטש מבאלאשא. רבה האחרון של אוזד(=אזד), על מקום אביו (לפי מורשת רבני הונגריה אביו היה - ר דוד צבי). מתורתו ב\"תל תלפיות\"."},{"i":43422,"n":"קצבורג, ישראל חיים מאוזד-באליק","f":"יהושע דוד צבי קצבורג","k":"בעל כתבי מהריח","bt":"תקצה","bp":"טאפאלטשאן","dt":"תרסט - יד תשרי","dp":"באליאק","b":"תלמיד הכת\"ס, ור נפתלי סופר מעטשי-ניידורף. חתן ר יחיאל רובינשטין מקדלבורג ועבר לשם-תרך. רבה הראשון של אוזד-באליאק-תרכח, בנו ר דוד צבי על מקומו אחריו (ונכדו ר ירחמיאל על מקומו אחריו - בחת\"ס ותלמידיו - מופיע כבנו ואילו ר דוד צבי נרשם כאחיינו)."},{"i":43423,"n":"קצבורג, ליפמן הכהן מטירנוי","b":"מדפיס בטירנוי, הדפיס כתב עת \"המעין\" - פרשבורג תרצד."},{"i":43424,"n":"קצבורג, משה מנחם הכהן מפרשבורג","b":"מחכמי פרשבורג, עלה לארץ והתישב בתל אביב. חתנו - ר אברהם לפבקוביץ מבני ברק."},{"i":43425,"n":"קצבי חיים בן יהודה","bt":"1790","dt":"ה'תרכז 1867","bk":[["צרור החיים",""]]},{"i":43426,"n":"קצבי, אברהם","f":"משה","dt":"תר","dp":"צפת - כנראה","b":"מחכמי קושטא, עלה לארץ, בתקלה חתם עם חכמי חברון על כתב שליחות החידא, בתקמג חתם על אגרת שליחות ר חיים אברהם ישראל זאבי, בתקפ\"ה עקב הריסת מתחם הקבר במירון יצא בשליחות צפת להצלת הבנין, בשנת תקפז שהה באיטליה, בשנת תקצא באלגיר בשליחות חברון, בסוף ימיו בצפת."},{"i":43427,"n":"קצבי, חיים מאלגיר","f":"יהודה","k":"בעל צרור החיים","bt":"תקן","dt":"תרכז","dp":"ווהראן","b":"רב ומו\"ץ בתלמסאן, ראש ישיבת \"אהלי יעקב\" ע\"ש ר יעקב לסרי, ורב העיר בווהראן. חיבר גם \"תוצאות החיים\" ליוורנו תרכט, הלכות ומנהגי ק\"ק תלמסאן - ואבד."},{"i":43428,"n":"קצבי, יוסף מקושטא","k":"בעל רב יוסף","bt":"שפה","dt":"תנא","dp":"קושטא?","b":"תלמיד ר יוסף טרני. רב ודרשן באדרינופול-תיט ושוב בשנת תלז, ברוסה-תכה, קושטא-תלט. חברו של ר אברהם רוזנס. השיב לשאלות חכמי דורו ובהם ר משה בנבנישתי, ר יצחק אלנקוה, ר יעקב אלפנדרי, ר אליעזר ן שנג'י, ועוד. בנו - ר יעקב. רוב כתביו אבדו בשריפה הגדולה בקושטא-תך."},{"i":43429,"n":"קצבי, יצחק מאלגיר","b":"מחכמי אלגיר - בשנות ה-ש'. נזכר בכתב העת \"פעמים\" - 24."},{"i":43430,"n":"קצבך, חנוך הניך מסקאהל","b":"דיין בסקול. בנו ר אברהם חתן ר אברהם לורברבוים מזולקוא."},{"i":43431,"n":"קצוביץ, ישראל איסר","k":"בעל ששים שנות חיים","bt":"1859","bp":"מאליסקי-פלך וילנא","dt":"1934","dp":"ניו יורק","b":"תלמיד ביהמ\"ד לרבנים בוילנא, היגר לארה\"ב-1881 עם קבוצת \"עם עולם\". חזר לרוסיה ושוב לארה\"ב (3 פעמים). חבר מערת \"דער אידישער פארמער\" בארה\"ב. חיבר ספר על גידול עופות \"היימישע עופות\""},{"i":43432,"n":"קציאן, יעקב מצ'רנוביץ","b":"מחכמי טשרנוביץ. תשובה אליו \"דברי שאול\"-תרל."},{"i":43433,"n":"קציגין, יהודה מאיטליה","b":"רבו של הרב יחכ\"ם (ר יצחק חיים כהן מהחזנים) - שהזכירו בספרו \"פחד יצחק\"."},{"i":43434,"n":"קציגין, יוסף חיים מקזאלי","dt":"תמא","b":"רב בקזאלי."},{"i":43435,"n":"קציגין, מנשה יוסף מאיטליה","k":"בעל חצי מטה מנשה-כתי","dt":"תקד - טז אדר","b":"מחכמי גארדיסקה(-ליד גוריציאה-איטליה), ומלמד לילדי משפחת מורפורגו. התכתב עם חכמי איטליה ובהם ר יעקב חי חפץ, ר דוד פארדו, ועוד. חיבר ספרים בכת\"י ובהם - חצי מטה מנשה, מעשה ידי אומן, שמריה זוהם - ובהם חלופי אגרות בינו ובין חכמי דורו באיטליה."},{"i":43436,"n":"קציגין, קלונימוס","b":"מגדולי חכמי איטליה,רב במנטובה-שפ\"ג"},{"i":43437,"n":"קציזנא, אלתר","k":"בעל דער גייסט דער מל","bt":"1885","bp":"וילנא","dt":"1941","b":"ישב בוארשא במחיצת י.ל. פרץ, ועסק בעבודה ספרותית ובצילום. מעורכי \"ליטערארישע בלעטער\", \"פריינד\", ועוד. חיבר גם \"דוכס\" על האגדה בדבר גר הצדק הפולני, ועוד. נספה בשואה ע\"י אוקראינים ליד טרנופול."},{"i":43438,"n":"קצין שלמה שאול","bt":"1902","dt":"ה'תשמב 1982","bk":[["בארחות החיים",""],["דברי שלמה",""],["טהרת בנות ישראל",""],["ניצוצי אור",""]]},{"i":43439,"n":"קצין, אברהם מחלב","f":"בכור","k":"בעל לקוטי אברהם","bt":"תקעא","bp":"ארם צובא","dt":"תרנז - ו חשון","dp":"ירושלים","b":"דרשן מחכמי ארם צובא, בשנת תרן עלה לירושלים. בשליחות במרוקו. חיבר \"לקוטי אברהם\" נדפס בתוך \"ויאסוף דוד\" ירושלים תרנט. ?? לא באוצר ??"},{"i":43440,"n":"קצין, אהרן מירושלים","b":"מיסד ישיבת \"בית קצין\" בירושלים בראשות ר בנימין מרדכי נבון, ור יהודה נבון."},{"i":43441,"n":"קצין, אליהו זאב מארה\"ב","f":"אליעזר","bt":"תרלא","b":"רב בדומברוביץ-ווהלין, היגר לארה\"ב וכיהן כרב בפיטסבורג-תרסו."},{"i":43442,"n":"קצין, אליהו מחלב","bt":"תקיח","dt":"תקץ","b":"אב\"ד בארם צובה"},{"i":43443,"n":"קצין, בכור מחלב","bt":"תקו","dt":"תרטו","dp":"חלב","b":"דרשן, מרבני ארם צובה"},{"i":43444,"n":"קצין, דוד מחלב","f":"בכור","k":"בעל ויאסף דוד","bt":"תקן","dt":"תרלז","b":"רב, דיין, דרשן בחלב"},{"i":43445,"n":"קצין, יהודה מחלב","f":"יום טוב","k":"בעל רועי ישראל","bt":"תסח","dt":"תקמד - י חשון","dp":"חלב","b":"רב בארם צובא, עלה לירושלים אך חזר לחלב. חיבר גם \"מחנה יהודה\". מתלמידיו ר ישעיה עטייה בעל \"בגדי ישע\".","bk":[["מחנה יהודה",""]]},{"i":43446,"n":"קצין, יום טוב מחלב","b":"מגדולי רבני ארם צובה-תק\"י"},{"i":43447,"n":"קצין, יעקב מירושלים","f":"שאול","k":"בעל משמרת הקדשין","bt":"תרס","bp":"ירושלים","dt":"תשנה","b":"חתן ר שלום הדאיה. תלמיד \"פורת יוסף\", מחכמי \"חסד לאברהם ובנין שלמה\", יסד ועמד בראש ישיבת \"גן הלבנון\" בירושלים. בשליחות בארה\"ב-תרצב, ראב\"ד בקהילת מגן דוד בניו יורק."},{"i":43448,"n":"קצין, יצחק הנכד","f":"בכור","bt":"תקסז","bp":"אר\"ץ","dt":"תרנז","b":"נכדו של ר יצחק קצין. מחכמי ירושלים. בניו - יהודה, עזרא, שלמה, ומשה."},{"i":43449,"n":"קצין, מרדכי טודרוס משאוולאן","b":"מחכמי שאוולאן-פלך קובנה. קרובו של ר אליקים טודרוס בעל \"כבוד חכמים\" ונזכר בספרו."},{"i":43450,"n":"קצין, רפאל מחלב","f":"אליהו קצין","k":"בעל תקפו של רפאל","bt":"תקן","bp":"חלב","dt":"תרלה - א אדר","b":"רב בחלב, חכם באשי בבגדד-תרט - אולם בגלל מחלוקת בקהלה עזב את תפקידו לאחר 3 שנים והמחלוקת נמשכה גם אחר כך. חיבר ספר \"תקפו של רפאל\" על \"תקפו כהן\" לש\"ך, \"דרך חיים\" נגד \"נתיבות עולם\" שחיבר מסיונר נוצרי בקושטא תרח, \"יין הרקח\" ועוד."},{"i":43451,"n":"קצין, שאול (מעתוק) מחלב","f":"אברהם - לקוטי אברהם","k":"בעל פרי צדיק","bt":"תרכד","bp":"ארם צובא","dt":"תרעז - כו כסלו","dp":"ירושלים","b":"מחכמי ארם צובא, עלה עם אביו לחברון-תרנא, תלמיד ר אליהו מני מחברון, עבר לירושלים ונמנה על תלמידי \"בית אל\", ואחר כך מחכמי \"רחובות הנהר\"-תרנו וכיהן שם כש\"ץ. חיבר \"פרי צדיק\" ירושלים תרצח, \"זיו הזהר\", חיבר גם שו\"ת, חדושים ופירושים."},{"i":43452,"n":"קצין, שלמה מירושלים","f":"שאול","k":"בעל טהרת בנות ישראל","bt":"תרסט","bp":"ירושלים","dt":"תשמג - ו חשון","dp":"ירושלים","b":"אחיו של ר יעקב שאול קצין. דיין בתל אביב, מצרים, ועוד. חיבר גם \"דברי שלמה\", \"כרם שלמה\" ועוד."},{"i":43453,"n":"קצינו, ישעיה משה מקושטא","f":"אליהו","b":"דיין ואב\"ד בקושטא-תקסב."},{"i":43454,"n":"קצינין, יצחק ממנטובה","b":"מגדולי חכמי איטליה,רב במנטובה-שפ\"ג"},{"i":43455,"n":"קציר, שלמה מתימן","b":"מחכמי כומים-תימן - בתחילת המאה ה-20."},{"i":43456,"n":"קצמן, אליעזר הכהן מראקוב","b":"רב בוואלמא,ר\"מ בראקוב"},{"i":43457,"n":"קצנלנבוגן - משפחה","b":"משפחה מצאצאי ר שאול וייל."},{"i":43458,"n":"קצנלנבוגן דוד טבלי בן נפתלי הרץ","bt":"1847","dt":"ה'תרצ 1930","bk":[["דברי דוד",""],["מי נפתוח",""]]},{"i":43459,"n":"קצנלנבוגן, אברהם","f":"יעקב קצנלבוגן","dt":"תקט - כג תמוז","b":"בנו - ר יחזקאל בעל \"כנסת יחזקאל\"."},{"i":43460,"n":"קצנלנבוגן, אברהם אביש מסוכטשוב","f":"צבי הירש","k":"בעל ברכת אברהם","dt":"תקן","dp":"סוכטשוב","b":"מחכמי לאסק, רב בסאכטשוב(=סוכטשוב)-תקנ. בנו ר יהושע שמואל הו\"ל את ספרו \"ברכת אברהם\" עם הקדמה ממנו, ו\"דרכי נועם\". חיבר גם \"יין הרקח\"."},{"i":43461,"n":"קצנלנבוגן, אברהם אברשקה","f":"השר שאול וייל","b":"חתן ר אברהם אלפרש מפוזנה. ר\"מ בבריסק אצל אביו, אב\"ד וורניק, לבוב-שפ. מחותן עם בעל \"תוספות יום טוב\". בנו - ר זלמן מלופקא, חתניו - ר שמואל בן התוי\"ט, ר ליפמן בן יצחק בן פנחס הורביץ."},{"i":43462,"n":"קצנלנבוגן, אברהם חיים מטולטשין","b":"רב בטולטשין. חתן ר אליהו ברוך קאמאי ממיר. פרסם מאמרים ב\"מאסף דרושי\" - וילנא תרסט."},{"i":43463,"n":"קצנלנבוגן, אברהם יהושע השל","f":"מרדכי מאוסטילא","bt":"תקף","dt":"תרנד","b":"נכד ר מרדכי מנשכיז שקרא לבניו בשם משפחת זקניו האחד קצנלבויגן והשני שפירא. חתן ר ישראל מקרמניץ בן המגיד מזלוטשוב. רב בטלוסט, חתנו ר פנחס חודרוב על מקומו אחריו."},{"i":43464,"n":"קצנלנבוגן, אברהם יעקב יוסף מלב","f":"יואל קצינלפוגן","dt":"שצז - ו אייר","dp":"לבוב","b":"רב ביאנוב (ליד לבוב), לבוב-שעד ובנו - ר יעקב על מקומו אחריו. חתם-שפד על תקנות קהלת זולקווא, הסכים על תהלים קב ונקי -הנאו שעו, מדרש רבה-קראקא שצד, שער השמים-שצו, ועוד. נכדו - ר יחזקאל לנדא בעל \"כנסת יחזקאל\". אחיו - ר מתתיהו ליברמן ק\"פ משנייטוך. מחתן עם ר בנימין אהרן סלניק."},{"i":43465,"n":"קצנלנבוגן, אברהם מאויבן","b":"תלמיד מהר\"י וייל, מהרא\"י בעל \"תרומת הדשן\", ר יונה מרגנשבורג בעל או\"ה. רב ברגנשבורג, אויבן-רס. (עליו בהקדמת \"שיח יצחק\"). היה מחלוקת כנגדו באויבן והתלוננו מתנגדיו אצל רבו בעל \"תרומת הדשן\" ור אברהם כתב לקרובו ר יוסף בעל \"לקט יושר\" שימליץ בעדו אצל רבו, והיה מעשה בגט שהכשיר שעורר מחלוקת בין חכמי דורו ולבסוף אישרוהו רבני ניישטט - ר מישטרלין ור יוזמן כץ ור איזיק סגל ורבו מהרא\"י בעל \"תרומת הדשן\" קיבל את דעתם. חתניו - ר עקיבא הכהן מאויבן, ר שלמה."},{"i":43466,"n":"קצנלנבוגן, אברהם מבריסק","f":"דוד מקידאן","dt":"תקנד-סו","b":"רב בסלוצק-תקו, בריסק-תקכה, דאג להביא ב-תפז ילד בן 6 מוילנא - לימים התפרסם כהגר\"א, ומסרו לאביו ללמדו. נספד ב\"ריח השדה\" לר אליעזר מחומסק. הסכים על \"באר אברהם\" - שקלוב תקמג, \"בית יעקב אש\" - פפד\"א תקכה, ועוד. מתורתו ב\"מצודת דוד\" - אלטונא תצו. נזכר ב\"עליות אליהו\". עמד לצדו של ר יונתן איבשיץ בזמן המחלוקת כנגדו. אחיו: ר משלם זלמן מקיידאן, ר שלום מאשאטיז, ר ישראל מקאלוריא, ר יואל מיריטשוב. בניו - ר יחזקאל מסיסלוביץ, ר נחום מבירז, ר יוסף מבריסק, ר יואל מקומורובקא, ר דוד מולקוביסק ובריסק, ר משה. ר אפרים."},{"i":43467,"n":"קצנלנבוגן, אברהם מוילנא","f":"שמחה","k":"בעל מכונת הקיטור","bt":"תקס","bp":"וילנא","dt":"תרלו - י ניסן","b":"אחיו של ר צבי הירש מוילנא. מחכמי וילנא. חיבר גם \"תפלה למשה\", \"מאזני צדק\", \"שער המים\", ועוד. גילה את מעיינות הרפואה בדרוסקניק וזכה להצטיינות מידי ממשלת רוסיה-1837. מתלמידיו רש\"י פין."},{"i":43468,"n":"קצנלנבוגן, אברהם מטריספולי","dt":"תרכז - יג ניסן","b":"תלמיד החוזה מלובלין והיהודי הקדוש מפשיסחא. בנו ר נפתלי מטשחויב."},{"i":43469,"n":"קצנלנבוגן, אברהם מלויצק","f":"יוסף דוד מלוצק","k":"אדמור מלוצק","bt":"תרלז","bp":"לוצק","dt":"תשג - כ אד\"ב","dp":"תל אביב","b":"חתן ר משה זלמן מטשמישלא (ליובאוויטש). אדמור בלוצק, אודיסה, עלה לארץ-תרצו."},{"i":43470,"n":"קצנלנבוגן, אברהם מלמברג","f":"שמואל יהודה קצנלב","b":"רב בלמברג. בנו - ר יעקב מפיורדא. ונכדו - ר אברהם ונינו ר יחזקאל בעל \"כנסת יחזקאל\". אחיו - השר ר שאול וייל."},{"i":43471,"n":"קצנלנבוגן, אברהם משה מירושלים","b":"ראה ישיבה בירושלים - שחינך את תלמידיו לבקיאות עד שעמדו ב\"מבחן הסיכה\" (ידעו בע\"פ את מקום הסיכה בדפים הבאים). פעיל בעסקי ציבור. בניו: ר רפאל אליהו בעל \"באר לחי רואי\", ר אהרן שלמה-מראשי נטורי קרתא, ר יעקב ירוחם."},{"i":43472,"n":"קצנלנבוגן, אהרן מסורוצק","f":"יעקב יוסף מקונסטנטין","k":"אדמור מסורוצק","dt":"תרפז - יד חשון","b":"מצאצאי ר יצחק מנסכיז. חתן ר אפרים פישל מאוחאטי, עבר לפולין, אדמור מבסורוצק, אוטואצק, וארשא. בניו ר יעקב יוסף ור ברוך מוארשא."},{"i":43473,"n":"קצנלנבוגן, אהרן משיח מבלז","f":"צבי","k":"אהרן משיח","bt":"תקל","dt":"תקעז - ב תשרי","b":"רב בבלז. תלמיד ר אלימך מליזנסק, והחוזה מלובלין. על מצבתו נכתב \"עושה פלא לחיים לבל יהיו מתים\". בנו ר משה משיח אב\"ד ולאדובא."},{"i":43474,"n":"קצנלנבוגן, אהרן שלמה מירושלים","f":"אברהם משה מירושלים","b":"מראשי \"נטורי קרתא\" בירושלים."},{"i":43475,"n":"קצנלנבוגן, אוריה","k":"בעל ליטע","bt":"1885","b":"חבר ב\"בונד\". ישב בבירז' ושאוולי ופגש את פעילי התנועה הלאומית הליטאית במחתרת, ופגש את פעילי התנועה הלאומית של רוסיה הלבנה. פרסם סיפורים קצרים בעתוני וילנא, ומאמרים על הצורך בהבנה בין יהודים לליטאים ובין היהודים לרוסים הלבנים (ביאלורוסים). פרסם בעתונות היהודית בקובנא בנושאי ספרות וחינוך. היגר לארה\"ב-1927 ועסק בעבודה ספרותית. תרגם שירי עם ליטאים לאידיש - \"דיינעס ליטווישע און לעטישע פאלקסלידער\"."},{"i":43476,"n":"קצנלנבוגן, אליהו רפאל מירושלים","b":"רב בירושלים. פרסם מאמרים ב\"אור תורה\" - לונדון תרצד."},{"i":43477,"n":"קצנלנבוגן, אליעזר מאלזס בומברג","f":"משה מפודהייץ וזולצבך","bt":"תס","dt":"תקלא","b":"חתן ר שמואל הילמן ממיץ. רב בגראפלד, בומברג, הנאו והמדינה. תשובה ממנו ב\"אור הישר\" בענין הגט מקליווא. בנו - ר נפתלי בעל \"שער נפתלי\"."},{"i":43478,"n":"קצנלנבוגן, אליעזר ריסר מהמבורג","f":"יעקב ריסר","k":"בעל זכר צדיק","dt":"תקפח - כד אדר","dp":"אלטונא","b":"חתן ר רפאל הכהן מהמבורג. מחכמי המבורג, עבר לליבק והתעשר, חזר להמבורג והפך לאחד מראשי הריפורמים ולחם בראשי הקהלה החרדית (ובהם גיסו ר מיכאל שפייר). חיבר \"זכר צדיק\". בנו - ד\"ר גבריאל ריסר."},{"i":43479,"n":"קצנלנבוגן, אפרים מסויסלוביץ","f":"אברהם מבריסק","b":"מחכמי סויסלוביץ. אחד מ7 אחים רבנים ובהם: ר יחזקאל מסויסלוביץ."},{"i":43480,"n":"קצנלנבוגן, אריה ליב מאניקשט","f":"נתן נטע מברוד","b":"רב באניקשט(=אניקסט) והגליל-תקל, אב\"ד ברודי. בנו ר שאול מזאסלב."},{"i":43481,"n":"קצנלנבוגן, אריה ליב מבריסק","f":"יוסף מבריסק","dt":"תקצז - יב אב","dp":"בריסק","b":"אב\"ד בבריסק-תקנח כ-40 שנה, ור יצחק איזיק בן ישראל מפינסק על מקומו אחריו. נזכר ב\"כרם שלמה\", \"מנחה בלולה\" לר שמעון מסלונים, \"שבעה עינים\"."},{"i":43482,"n":"קצנלנבוגן, אריה ליב מטווריג","f":"שאול קצינלבוגן","b":"רב בטווריג-תק\"מ"},{"i":43483,"n":"קצנלנבוגן, בנימין מלבוב","k":"בעל מנורת זהב?","b":"מנהיג ועד ארבע ארצות, חתם-תמז ביריד ירוסלב. אולי הוא המחבר שבעה ספרים הנקראים \"האורות\" - \"מנורת זהב\" - דירנפורט תקלה."},{"i":43484,"n":"קצנלנבוגן, בנימין מסאמטור","f":"שאול","k":"בעל אור חכמים","dt":"תקנה","b":"תלמיד ר שמואל הילמן ממיץ. רב בסאמטור, גלהויזן, קורוטשין. חיבר גם \"לב חכמים\"."},{"i":43485,"n":"קצנלנבוגן, ברוך מקונסטנטין","f":"יוסף מאוסטילא","dt":"תרנא - ג אלול","b":"נכד האדמור ר מרדכי שפירא מנסכיז. חתן ר פנחס מאוסטרהא (או שהיה גיסו וחתן אביו - ר יעקב יוסף-נכד רב ייבי). רב בקסטינין(=קונסטנטין?) הו\"ל \"רב ייבי\" של חותנו זקנו, ובסופו \"רשפי אש\" לזקנו מנסכיז."},{"i":43486,"n":"קצנלנבוגן, גבריאל מלייפניק","f":"פנחס מלייפניק","b":"ראב\"ד בלייפניק, רב במרקבריט-תקל, ניקלשבורג."},{"i":43487,"n":"קצנלנבוגן, דוד טבלי מליסא","f":"נתן נטע או אריה ליב","k":"בעל נפש דוד","bp":"ברודי","dt":"תקנב - טז טבת","dp":"ליסא","b":"מרביץ תורה, רב בזסלב, חורובוב(=הארחוב), ליסא-תקלד. נספד בידי ר אלעזר פלקלש. היה במחלוקת עם נפתלי הרץ ויזל - בהתחלה הסכים על ספריו של ויזל, אולם לאחר שפרסם את \"דברי שלום ואמת\" יצא כנגדו בדרשה-תקמב וויזל השיב על דבריו במכתב \"רחובות\". בנו - ר זכריה מנדל מליסא, חתנו - ר שלמה זלמן ליפשיץ."},{"i":43488,"n":"קצנלנבוגן, דוד טבלי מפטרבורג","f":"נפתלי הרץ","k":"בעל מעין מי נפתוח","bt":"תרי","bp":"טאווריג-פלך קובנא","dt":"תרץ","dp":"פטרבורג(=לנינגרד)","b":"תלמיד ביהמ\"ד בוילנא. מגדולי חכמי דורו, רב בוורזולב(=וירבאלן)-תרלו על מקום ר יהודה בלומגרד, סובאלק-תרנד, יאנישוק, פטרבורג--תרסז. עסקן ציבור ושתדלן לפי השלטון הרוסי והצליח לבטל את גזירת השחיטה בפינלנד, ולשחרר את הרבנים מגיוס לצבא. פעל למען מגורשים וגולים ולמען חנינה לנידונים. בגיל 16 חיבר פירוש לתלמוד ירושלמי ונדפס בש\"ס קרוטושין-תרלא, חיבר גם \"דברי דוד\", ועוד."},{"i":43489,"n":"קצנלנבוגן, דוד מווילקי סרדניק","f":"מרדכי מקידאן ולובלין","b":"רב בווילקי-תקס, סרדניק, צייקישוק. בניו: ר משלם זלמן מיאנישוק, ר מרדכי."},{"i":43490,"n":"קצנלנבוגן, דוד מוילקוביסק","f":"אברהם מבריסק","b":"חתן ר יהודה ליב בעל \"שלמי שמחה\". רב בוילקוביסק, סו\"ד בבריסק-תקע. אחד מ-7 אחים רבנים."},{"i":43491,"n":"קצנלנבוגן, דוד מקוצק","f":"נתן נטע קצינלבוגן","b":"רב בקאצק"},{"i":43492,"n":"קצנלנבוגן, דוד מקידאן","f":"יחזקאל - כנסת יחזקאל","dt":"תקטז","b":"חתן ר שלום ז\"ק מבירז. רב בראגולה, קידאן והגליל, אה\"ו על מקום אביו (למעשה לא נתמנה למרות שאביו מינהו בצוואתו). בזמן שבתי צבי דאגו הוא ובנו ר אברהם מבריסק על הגבלת לימוד הקבלה, וחדשו את התקנה שלא ללמוד זהר לפני גיל 40. לימד את הגר\"א בהיותו בגיל 6. בנו ר משלם זלמן על מקומו אחריו בקידאן, בניו גם - ר אברהם מסלוצק ובריסק, ר שלום מאשאטיז, ר ישראל מקאלווריא, ר יואל מארטשוב ושינאווא."},{"i":43493,"n":"קצנלנבוגן, השל מבריסק","f":"שמחה מזאבלודאוי","b":"מחכמי בריסק-תקסג."},{"i":43494,"n":"קצנלנבוגן, חיים","f":"סעדיה ישעיה ממזריטש","b":"חתן ר גרשון פולץ מניקלשבורג. רב-שנת תק\"ס"},{"i":43495,"n":"קצנלנבוגן, חיים יהודה ליב","f":"צבי הירש","bt":"1814","bp":"וילנא","dt":"תרלו - טז טבת","dp":"וילקומיר","b":"חתן הגביר ר חיים שטרשון. תלמיד אד\"ם הכהן, ר ברוך של שלמה זלמן. בקי בשפות ובחכמת ישראל. מורה לתנ\"ך ותלמוד בביהמ\"ד לרבנים בוילנא, מפקח על מקום אביו עד יום סגירתו-1873. חיבר עם רש\"י פין \"מאמרי המוסר לישראל\" שתורגם לרוסית ונערך ע\"י לבנדה ויל\"ג בשם \"השקפת עולם של התלמודאים\". פרסם ב\"הכרמל\", ועוד. מבניו: הדוקטור מרדכי קצננלנבוגן מוילקומיר."},{"i":43496,"n":"קצנלנבוגן, חיים מרסטוב","dt":"תרצד","b":"רב בשרזנא,טולצין,סמולביץ,נזין,רסטוב"},{"i":43497,"n":"קצנלנבוגן, יהודה","f":"בנימין בינוש"},{"i":43498,"n":"קצנלנבוגן, יהודה מבריסק","f":"השר שאול","b":"מגדולי חכמי בריסק-ש\"פ"},{"i":43499,"n":"קצנלנבוגן, יהושע שמואל מסוכטוש","f":"אברהם - ברכת אברהם","b":"רב בסוכטשוב. הו\"ל ספר אביו \"ברכת אברהם\" עם הקדמה ממנו."},{"i":43500,"n":"קצנלנבוגן, יואל אשכנזי","f":"משה","b":"חתן ר שמואל יהודה מינץ-קצנלנבוגן מונציה. רב-שנת שמ. בניו: ר אברהם יעקב יוסף מיאנוב ולבוב, ר מתתיה ליברמן משנייטוך."},{"i":43501,"n":"קצנלנבוגן, יואל יצחק מז'אזמיר","b":"רב בז'אזמיר-תרץ, לינקובא. בנו ר יחזקאל רב בסארהיי ושירווינט."},{"i":43502,"n":"קצנלנבוגן, יואל יצחק מליטא","f":"מרדכי בן דוד מווילקי","k":"בעל זרע יצחק","bt":"תקסט","bp":"לינקאווא-פלך זאמוט","dt":"תרנא - כב חשון","b":"אביו עבר מלינקאווע לבוקרשט, ואמו שלחתו לוילנא, תלמיד ר מרדכי מלצר ור אבלי פאסוואלער, ור צבי סלנטר בסלנט. חתן הגביר ר אברהם אבא הורביץ. למד בקרלין עם הגביר ר יהושע השל רוקה לוריא. רב בשאד, נתקבל לרבנות נוברדוק על מקום ר אלכסנדר זיסקינד אך סירב, זאזמיר, סמיאטיץ, נאווי-אלכסנדרובסקי, עזב את הרבנות והתישב בטשכנוביץ. גיסו של ר אליקום גצל הורביץ מקלם. בנו ר אברהם אבא הו\"ל את ספרו \"זרע יצחק\" וארשא תרנח."},{"i":43503,"n":"קצנלנבוגן, יואל מקמירבסקי","f":"אברהם מבריסק","b":"רב בקאמירבסקי(=קומרובקי)-תקמו. אחד מ-7 אחים רבנים."},{"i":43504,"n":"קצנלנבוגן, יואל משינאווי","f":"דוד מקידאן","b":"רב בשיניבה(=שינאווי), יריטשוב(=יארטשוב). תשובות ממנו בספר חותנו. הביא לדפוס ספר זקנו \"מים יחזקאל\". (הספרים \"אהל משה\" ו\"אסיפת יהודה\" - אינם ממנו - כפי שנחשב בטעות). הסכים על \"אהל משה\"-זולקוא תקיד, \"אסופת יהודה\"-פפ\"מ תקצג."},{"i":43505,"n":"קצנלנבוגן, יוזפא מאלטונא","f":"מאיר בן יהודה מאלטונ","dt":"תקיז - י ניסן","dp":"אלטונא","b":"מחכמי אלטונא."},{"i":43506,"n":"קצנלנבוגן, יוסף דוד מלויצק","f":"מרדכי מבילירודקא","dt":"תרצה - כח טבת","dp":"תל אביב - ירושלים","b":"מצאצי ר יצחק מנסכיז. חתן ר אברהם מאוסטרהא."},{"i":43507,"n":"קצנלנבוגן, יוסף מאוסטילא","f":"מרדכי שפירא מנסכיז","k":"אדמור מנסכיז אוסטילה","bt":"תקכג","dt":"תקץ - יח אלול","dp":"אוסטרהא","b":"נכד-אבי אמו ר יוסף קצנלנבוגן מלאשנוב וקיבל את שמו. חתן ר יהודה מאיר משפיטובקא (קוריץ). רב בלויצק, הרובשוב, אוסטילא והגליל. מחותן-בנו ברוך התחתן עם בת ר יעקב יוסף נכד הרב ייב\"י והגיע לחתונה באוסטרהא, ונפטר באותו השבוע. בתו נישאה לנכד ר אברהם יהושע השל מאפטא בחתונה האוסטילאית המפורסמת. חתנו ר אהרן צינץ מטורבין-בן ר אריה ליב מפלאצק."},{"i":43508,"n":"קצנלנבוגן, יוסף מאוסטרהא","f":"דוד","k":"קצנלנבוגן ?","dt":"תמה - ה ניסן","dp":"אוסטרהא","b":"מחכמי אוסטרהא, פרנס המדינה. הסכים על תנ\"ך עטיאש-תלח. יש המפרשים קל\"ב - קצנלנבוגן - ואומרים כי הוא נכד השר ר שאול ואהל."},{"i":43509,"n":"קצנלנבוגן, יוסף מבריסק","f":"אברהם מבריסק","dp":"בריסק","b":"רב בבריסק-תקלח על מקום אביו?. אחד מ-7 אחים רבנים. הסכים על \"רזוהי גלין\". בניו - ר שמחה מזבלודאוי, ר אריה ליב מבריסק, ר שאול מוילנא, ר משלם זלמן מלובלין."},{"i":43510,"n":"קצנלנבוגן, יחזקאל מסארהיי","f":"יואל יצחק מז'זמיר","bp":"לינקובה","b":"רב בסארהיי, שירווינט(=ניישטט-שאקי)."},{"i":43511,"n":"קצנלנבוגן, יחזקאל מסוסלוביץ","f":"אברהם מבריסק","b":"רב בסוסלוביץ(=סויסלוביץ)-תקע. אחד מ-7 אחים רבנים."},{"i":43512,"n":"קצנלנבוגן, יחזקאל מקידאן-הנכד","f":"אברהם","k":"בעל כנסת יחזקאל","bt":"תכח","bp":"בריסק","dt":"תקט - כג תמוז","b":"נכד ר יעקב מפיורדא ולבוב. מגדולי דורו. חתן ר שלמה זלמן מבריסק בן יואל-(חתן התוי\"ט ונכד הב\"ח) תלמיד ר מרדכי זיסקינד מבריסק בעל שו\"ת מהר\"ם זיסקינד. רב בזאטל(=זיטל), ישב בראזינאי וחתם שם על תקנות, רב בקידאן על מקום ר צבי הירש הורביץ (לפי מרקוביץ על מקום ר משה מרגליות בעל \"פני משה\") ובנו ר דוד על מקומו אחריו, בירז', אלטונא-תעג והיה רב 3 קהילות אלטונה המבורג ואנדסבק ובנו ר דוד על מקומו אחריו. חיבר גם \"לחם יחזקאל\", ועוד. לדעת שט\"ש הוא המחבר של \"מעורר זכרון\" שנדפס בעילום שם. נספד ע\"י ר יהונתן איבשיץ ב\"יערות דבש\". נכדו ר משולם זלמן מקידאן. הניח הגהות על הש\"ס בכת\"י. גיסו - ר אשר גינצבורגר מויזון. מחותן עם ר משה בן קלונימוס קלמן מואשילישוק, ר שלום ז\"ק מבירז. השתתף בועד ירוסלב של ועד ארבע ארצות. בניו: ר דוד מקידאן, ר יעקב הפרנס בועד 4 ארצות, ר פיבל. חתניו: ר יעקב הלוי שור מקרוז', ר יצחק בן ישראל מהאנוי."},{"i":43513,"n":"קצנלנבוגן, יעקב גרשון הלוי מיר","b":"תלמיד ישיבת \"ר ישראל אמריקנר\" בירושלים. פרסם מאמרים ב\"קובץ חדושי תורה\" - ירושלים תרצה."},{"i":43514,"n":"קצנלנבוגן, יעקב הי\"ד","f":"שאול (או שמואל)","k":"בעל נחלת יעקב","dt":"תנז","b":"נכד ר משה מחעלמא. נהרג עק\"ה. בניו - ר צבי הירש אפטר ור פנחס."},{"i":43515,"n":"קצנלנבוגן, יעקב יוסף מקונסטנטי","f":"ברוך מקונסטנטין","dt":"טז כסלו","b":"נכד האדמור ר מרדכי שפירא מנסכיז. חתן ר שמואל מקאשיווקא - השני."},{"i":43516,"n":"קצנלנבוגן, יעקב מאיטינגן","f":"פנחס - יש מנחילין","k":"בעל ישועות יעקב","dt":"תקנו","dp":"איטינגן","b":"תלמיד ר\"א ברוידא. ר\"מ באוסטרהא-תקך, רב באיטינגן(=איטינגא) ומדינת הסן על מקום ר אברהם בנימין וולף שפירא שעבר לשוואבין, היה גם ר\"מ בלבוב. הסכים על \"יפה עינים\". מחותן עם ר רפאל הכהן מהמבורג - בנו ר אליעזר-חתנו של ר רפאל."},{"i":43517,"n":"קצנלנבוגן, יעקב מלבוב - הזקן","f":"אברהם יעקב יוסף מיאנ","dt":"תכ - יג אדר","dp":"לבוב","b":"ראב\"ד בלבוב, רב במזיבוז, פיורדא. חתם-תג עם ר יצחק איש אויסטריך, חתם-תח עם ר יהודה ליווא אפשטין ור אברהם בן משלם זלצבורג. בנו - ר אברהם ונכדו - ר יחזקאל בעל \"כנסת יחזקאל\"."},{"i":43518,"n":"קצנלנבוגן, יעקב מקידאן","f":"יחזקאל מקידאן","b":"פרנס בקידאן. אחיו של ר דוד מקידאן."},{"i":43519,"n":"קצנלנבוגן, יצחק מניישטט","f":"משה קצינלנפוגן","k":"בעל מולדות יצחק","b":"חתן ר יחיאל לוריא. רב לאחר גירוש היהודים בפרג-ש\"פ, רב בניישטטל. בנו ר מאיר פדובה(???)."},{"i":43520,"n":"קצנלנבוגן, ישעיה מלבוב","f":"מנחם מנדל קצינלפוגן","dt":"תסט - ל ניסן","dp":"לבוב","b":"מרביץ תורה, דיין בלבוב. חתם-תסד עם ר אליהו בן צבי הירש, ר יחיאל מיכל מסקול, ועוד."},{"i":43521,"n":"קצנלנבוגן, ישראל מוילקוביסק","f":"דוד מקידאן","b":"רב בקלוואריה(=קאלואריה), וילקוביסק-תקכב-תקנ על מקום ר צבי הירש רפפורט."},{"i":43522,"n":"קצנלנבוגן, לוי יצחק מסטעפין","f":"יוסף מאוסטילא","k":"אדמור מסטעפין נסכיז","dt":"תרלד - יד טבת","b":"נכד האדמור ר מרדכי שפירא מנסכיז. חתן ר ישראל דב מסטעפין, רב ואדמור בסטעפין על מקום חותנו."},{"i":43523,"n":"קצנלנבוגן, מאיר דאריש מהיבניב","b":"רב ומלמד בהיבניב."},{"i":43524,"n":"קצנלנבוגן, מאיר חיים מסטעפין","f":"לוי יצחק מסטעפין","k":"אדמור מסטעפין נסכיז","b":"רב ואדמור בסטעפין על מקום אביו."},{"i":43525,"n":"קצנלנבוגן, מאיר מאלטונא","f":"יהודה בן משה","dt":"תס - כג אייר","dp":"אלטונא","b":"נכד ר שאול וייל. בנו - ר יוזפא."},{"i":43526,"n":"קצנלנבוגן, מאיר מבריסק","f":"חיים - ר\"ח ר\"ש","b":"חתן ר פנחס הורביץ-גיסו של הרמ\"א. מחכמי בריסק. בנו - ר אהרן בעל \"מנחת אהרן\"."},{"i":43527,"n":"קצנלנבוגן, מאיר מחעלמא","f":"משה קצינלנבוגן","b":"רב בחעלמא-ת\"פ"},{"i":43528,"n":"קצנלנבוגן, מאיר שאול מבריסק","k":"מאיר ואהל","dt":"שצט - אחרי","b":"מיסד ועד יהודי ליטא במאה ה-17, וראש הקצינים של הועד. לכבודו קבעו את בריסק למקום הועד (אחר פטירתו עבר לפרוז'אן). נזכר בפסק דין של יריד גראמניץ-שפג בענין חלוקת הוצאות לצרכי שתדלנות בין ארצות הועד וחלקה של ליטא. חותם בראש בתעודות הועד - שפג-שצט."},{"i":43529,"n":"קצנלנבוגן, מנחם מנדל מראסיין","f":"משלם מיאנישוק","dt":"תרנה - כ טבת","dp":"ראסיין","b":"מחכמי ראסיין. הניח חדושים על הש\"ס - בכת\"י."},{"i":43530,"n":"קצנלנבוגן, מנחם נחום מבירז'","f":"אברהם קצינלנבוגן","b":"חתן ר יצחק הורביץ מאה\"ו (בזיוו\"ש לאחר שנתגרשה מר יעקב לנדא-בן הנודע ביהודה). רב בבירז-תקמ."},{"i":43531,"n":"קצנלנבוגן, מנחם נחום מקידאן","f":"משלם זלמן מקידאן","b":"רב בקידאן-תקל על מקום אביו ובנו ר משה מרדכי על מקומו אחריו, שקוד-תקלח."},{"i":43532,"n":"קצנלנבוגן, מרדכי יונתן","f":"שאול מקאסוב וקוברין","b":"דודו של החזון איש."},{"i":43533,"n":"קצנלנבוגן, מרדכי מאוסטילא","f":"יוסף מאוסטילא","dt":"תרלז - ז אלול","b":"נכד האדמור ר מרדכי שפירא מנסכיז. רב באוסטילה. בנו ר אברהם יהושע השל מטלוסט."},{"i":43534,"n":"קצנלנבוגן, מרדכי מבילירודקא","f":"ברוך מקונסטנטין","k":"אדמור מנסכיז בילירוד","dt":"תרנג - כו אב","b":"נכד האדמור ר מרדכי שפירא מנסכיז. חתן ר צבי אריה מאליק - השני."},{"i":43535,"n":"קצנלנבוגן, מרדכי מוילנא","bt":"1858","dt":"1934","b":"הו\"ל בוילנא את כתבי פרץ סמולנסקין, יל\"ג. הוציא גם ספרים לעם וספרי רומ\"ל."},{"i":43536,"n":"קצנלנבוגן, מרדכי מלובלין","b":"חתם על כתב החרם של ר יעקב חיים מלובלין על היוצאים כנגד ר יהונתן איבשיץ-תקיא."},{"i":43537,"n":"קצנלנבוגן, מרדכי מלובלין וקידן","f":"משלם זלמן מקידאן","b":"מחכמי לובלין-תקל, רב בקידאן על מקום אביו (לפי מרקוביץ - אחיו ר מנחם נחום הוא שהיה רב בקידאן). בניו: ר דוד מוילקי וסרדניק, ור נחום. חתם ב\"לוחות העדות\" עם חכמי לובלין."},{"i":43538,"n":"קצנלנבוגן, מרדכי מסאלחוב","f":"שמעון מזאוויחוואסט","k":"אדמור מסאלאחוב","b":"מצאצי ר יצחק מנסכיז. אחיו של ר יעקב פרלוב מנובומינסק. חתן ר לוי יצחק מסטעפין, ובזיוו\"ש חתן ר משולם זושא יצחק מטלומטש (אניפולי)."},{"i":43539,"n":"קצנלנבוגן, מרדכי פתחיה","f":"אריה ליב","dt":"תקיח","dp":"ירושלים","b":"מחכמי ירושלים, בשנת תצז בשליחות באשכנז עם ר יהודה כהן."},{"i":43540,"n":"קצנלנבוגן, משה","b":"רב-שנת ש\"ל. בניו ר יואל, ר יצחק."},{"i":43541,"n":"קצנלנבוגן, משה","f":"אברהם מבריסק","b":"מחכמי ליטא. אחד מ-7 אחים רבנים."},{"i":43542,"n":"קצנלנבוגן, משה יצחק מקמניץ","f":"נפתלי קצ\"ב","b":"רב בקמניץ(ליטא)"},{"i":43543,"n":"קצנלנבוגן, משה מאיזנשטט","k":"בעל קינה על הגירוש","b":"ראב\"ד באייזנשטט-ת\"ל, חיבר קינה בעת הגירוש"},{"i":43544,"n":"קצנלנבוגן, משה מחעלמא","f":"מאיר וייל-קצנלנבוגן","dt":"תג","b":"נכד השר שאול וייל. רב בלובמלא, חעלמא. בנו - ר שאול (שמואל) מפינטשוב."},{"i":43545,"n":"קצנלנבוגן, משה מירושלים","f":"יצחק","b":"מחכמי ירושלים, בשנת תקכג ותקכח חתם על מכתב קהילת ירושלים לקהילת מיץ. היה מצאצאי ר יעקב שור אבד בריסק."},{"i":43546,"n":"קצנלנבוגן, משה מעלקיש","f":"פנחס הקדוש","b":"רב בעלקיש-ת\"ע"},{"i":43547,"n":"קצנלנבוגן, משה מפודהייץ וזולצב","f":"שאול מפינטשוב","bt":"תל","dt":"תצג - תקד","b":"רב בפודהייץ-תנד, אנשבאך(=אנסבך) או שוואבאך, זולצבך. העלילו עליו עלילה וניצל בנס-תנט. בניו - ר אליעזר מהנאו, ר שלמה זלמן, ר צבי הירש-חתן ר ליב מוכיח."},{"i":43548,"n":"קצנלנבוגן, משה מקרקוביץ","b":"רב בקרקוביץ, למברג."},{"i":43549,"n":"קצנלנבוגן, משה מרדכי מקידאן","f":"מנחם נחום מקידאן","k":"בעל אלפא ביתא","bt":"תקע?","bp":"ליטא","dt":"תקע","dp":"קידאן","b":"תלמיד ר חיים מוולוזין. רב בראגולה, קידאן והגליל-תקמב על מקום אביו, עבר לפפד\"מ. חיבר גם \"והכנעני אז בארץ\", ועוד. הסכים על \"זרע יעקב\" הורדנא תקמח, \"שער הרחמים\" זולקוא תקמח."},{"i":43550,"n":"קצנלנבוגן, משה נפתלי מקרשוב","f":"אברהם מטירספולי","dt":"תרכז - יז ניסן","b":"רב בקרשוב, טרניגרד, חתנו ר אריה ליב טייכר על מקומו אחריו."},{"i":43551,"n":"קצנלנבוגן, משלם זלמן מבריסק","f":"יואל","dt":"תקסו - ח אדר","b":"רב בבריסק."},{"i":43552,"n":"קצנלנבוגן, משלם זלמן מיאנישוק","f":"דוד מווילקי סרדניק","dt":"תקץ","b":"רב ביאנישוק. בנו - ר מנחם מנדל מראסיין."},{"i":43553,"n":"קצנלנבוגן, משלם זלמן מלובלין","f":"יוסף מבריסק","dt":"תקמו - ה אדר","dp":"לובלין","b":"מחכמי לובלין."},{"i":43554,"n":"קצנלנבוגן, משלם זלמן מקידאן","f":"דוד מקידאן","dt":"תקלא","dp":"קידאן","b":"נכד ר יחזקאל בעל \"כנסת יחזקאל\". רב בראגולה(=ראגאלי), קידאן-תקיח על מקום אביו, ובנו ר מרדכי על מקומו אחריו (לפי מרקוביץ בנו - ר מנחם נחום - אחיו של ר מרדכי - על מקומו אחריו). בנו גם - ר מנחם נחום, חתנו - ר נח נתן נטע רבינוביץ מראסיין. הסכים על \"בית יעקב אש\" פפד\"א תקכה, \"תפארת ישראל\" פפד\"א תקלד. חתנו - ר נח נתן נטע רבינוביץ מראסיין."},{"i":43555,"n":"קצנלנבוגן, מתתיהו ליברמן משינט","f":"יואל קצינלנבוגן","b":"רב בשנייטוך-שעו. אחיו - ר יעקב יוסף אברהם מלבוב."},{"i":43556,"n":"קצנלנבוגן, נחום מבירז","f":"אברהם מבריסק","dt":"תקל - בערך","dp":"פומפיאן","b":"חתן ר יצחק הורביץ מאה\"ו. רב בבירז על מקום ר נפתלי הרץ (ולפי ליפמן-קובנא - על מקום ר ישראל בן חיים ז\"ק), ור אברהם-אחי הגר\"א על מקומו אחריו. אחד מ-7 אחים רבנים. נספד ב\"זכר החיים\" לר חיים רפפורט. בניו - ר משה בעל \"אלפא ביתא\", ר משלם זלמן מקידאן? (כל אצל ליפמן-קובנא)."},{"i":43557,"n":"קצנלנבוגן, נחום מווילקי","f":"מרדכי קצנלנפוגן","b":"רב בווילקי-תר\"ס"},{"i":43558,"n":"קצנלנבוגן, נחום מסלוצק","f":"מאיר קצנלנבוגן","b":"אולי הוא שהיה חתן ר יהודה וייל-קצנלנבוגן מבריסק. רב בסלוצק-שצ."},{"i":43559,"n":"קצנלנבוגן, נפתלי הירש מפפד\"א","f":"אליעזר מאלזאס","k":"בעל שער נפתלי","dt":"תקפג","b":"ממשפחת מהר\"ם מפדובה. רב בפפד\"א-תקנג אחר פטירת בעל \"פרי מגדים\", וינצהיים, רב גליל העליון של הריין. ממשתפתי אסיפת הרבנים בפריס-תקסו בהוראת הקיסר. חיבר \"שער נפתלי\" פפד\"א תקנז, ועוד."},{"i":43560,"n":"קצנלנבוגן, נפתלי הרץ מטורוגאן","f":"אריה ליב קצנלנבוגן","b":"רב בטורוגאן-תר\"כ"},{"i":43561,"n":"קצנלנבוגן, נפתלי הרש ממרגינטהל","f":"משה משואבך","bp":"שואבך","dt":"תקסא - ב תשרי","b":"תלמיד וחתן ר יעקב פופרש בעל \"שב יעקב\" מפרג ופפד\"מ, ובזיוו\"ש חתן ר ליב מוכיח (והיה גיסם של ר ישעיה פיק ברלין ור דוד ברלין מאה\"ו). רב במרגנטהיים-תקא על מקום ר שלמה ברודי. והגלילות בהיידלברג ומדינת פפלץ, רב בקורפפאלץ, מנהיים-תקכח. הו\"ל \"תולדות אדם\" לרמב\"ן."},{"i":43562,"n":"קצנלנבוגן, נפתלי הרש מפרנצלוי","b":"רב בפרנצלוי-תקמ\"ד"},{"i":43563,"n":"קצנלנבוגן, נפתלי מטשחויב","f":"אברהם מטריספולי","k":"הצדיק מקרעשוב","b":"אב\"ד טשחויב, קרעשוב, וטרניגראד."},{"i":43564,"n":"קצנלנבוגן, נתן נטע מברוד","f":"אריה ליב מהורדנא","dt":"תקכד","b":"רב בברוד-תקה, השתתף בחרם נגד הפרנקיסטים-תקטז, חתם על כרוז נגד השבתאים - ברודי תקיח. בניו - ר דוד טבלי בעל \"נפש דוד\", ר אריה ליב מאניקשט, חתנו - ר נחמן רפפורט, ר יצחק חיות. (לפי ברוורמן-אנשי שם ר דוד היה בנו של ר אריה ליב מהורדנא)"},{"i":43565,"n":"קצנלנבוגן, נתן נטע ממזריטש","f":"נחום מסלוצק בן מאיר","b":"אב\"ד מזריטש-תכ, עלה לירושלים."},{"i":43566,"n":"קצנלנבוגן, סעדיה ישעיה ממזריטש","f":"שאול מפינטשוב","dt":"תפו","b":"מצאצאי השר ר שאול ואהל. חתן ר נפתלי כץ מאוסטרהא. רב בלעסלוי, מזריטש-תעו, העלישוי. הסכים על \"ילקוט שמעוני\" - פפד\"א."},{"i":43567,"n":"קצנלנבוגן, פנחס מאוסטילא","f":"יוסף מאוסטילא","dt":"יג אייר","b":"נכד האדמור ר מרדכי שפירא מנסכיז. חתן ר אלכסנדר שמואל מהורוחוב. רב באוסטילא-תרכ. בנו ר משה מאוסטילא."},{"i":43568,"n":"קצנלנבוגן, פנחס מאיטינגן","f":"יעקב מאוסטרהא ואיטינ","dt":"תרד","dp":"איטינגן?","b":"חתן ר יהודה ליב לבוב בן יהושע השל בעל \"פני לבנה\", ובזיוו\"ש חתן ר יהושע משה מפיורדא. רב בשוואבך והמחוז, איטינגן על מקום אביו כ-50 שנה. נזכר בספר בן דודו - ר משלם איגרא."},{"i":43569,"n":"קצנלנבוגן, פנחס מלייפניק","f":"משה","k":"בעל יש מנחילין","bt":"תנא","dt":"תקכ","b":"רב בלייפניק,בסקוביץ,וולרשטין,מרקברייט ומדינת שוורצבורג. בניו - ר גבריאל, ר יעקב מאיטינגא."},{"i":43570,"n":"קצנלנבוגן, פנחס מקרקוביץ","f":"יעקב הקדוש-נחלת יעקב","dt":"תקי - יא אד\"ב","dp":"לבוב","b":"נכד ר שאול מפינטשוב. רב בקרקוביץ, ראב\"ד בלבוב-תעט. חתם-תקיא עם ר אברהם סגל מטיסמניץ, ועוד. הסכים על \"בית שמואל\"-תצו, \"ברכת יוסף ואליהו רבה\"-תקז. לדברי בובר תלמידו היה ר מאיר תאומים בעל \"מאירת עינים-רב פנינים\" ומביא בספרו מחדושי רבו."},{"i":43571,"n":"קצנלנבוגן, צבי הירש מוילנא","f":"שמחה","k":"בעל נתיבות עולם","bt":"תקנו","bp":"וילנא","dt":"תרכח - טו אדר","dp":"וילנא","b":"נקרא בשם הירשל שמחה'ס - לפני שקיבל שם משפחה. חתן ר גבריאל גרשונ'ס. למד בישיבת הארבעים. תלמיד ר שאול קצנלנבוגן, ור אבלי מפוסבול, הצטיין בלימודיו ורבו ר שאול הרשה לו להיקרא בשמו - קצנלנבוגן. פרנס קהילת וילנא וייצג את הקהלה בביקורי ליליינטל ומונטיפיורי שעמו החליף מכתבים. מפקח בביהמ\"ד לרבנים-תרט. חיבר \"נתיבות עולם\", \"גבעת שאול\", \"מגלת ספר\", ועוד. פרסם מאמרים ב\"הכרמל\", ועוד. הניח ספריה עשירה. חיבר שירים לכבוד הצאר ומשפחתו וקיבל מדליות מהממשלה. בניו: ר חיים ליב על מקומו אחריו כמפקח, ר שלמה שנפטר בחיי אביו בהורדנא. חתניו: ר יעקב קצנלסון מבוברויסק."},{"i":43572,"n":"קצנלנבוגן, צבי הירש מפאלץ","f":"משה משוואבאך","b":"חתן ר\"מ ליב ברלין (ר אריה ליב מוכיח(3354). רב בפאלץ-תק. גיסו - ר יוסף שטינהרט מביא מתורתו ב\"זכרון יוסף\". הסכים על \"עמודי יהודה\" - תקכה. בנו - הגביר ר איציק מנהיימר."},{"i":43573,"n":"קצנלנבוגן, רפאל מירושלים","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג, תשכג - קובץ \"מדרש בני ציון\", \"תבונה\" - ירושלים תשא. עורך \"קול ישראל\" - ירושלים תרפא - ירחון חדו\"ת מאת \"צעירי אגודת ישראל בירושלים\"."},{"i":43574,"n":"קצנלנבוגן, שאול (שמואל)","f":"אברהם","k":"בעל מגן שאול - בכת\"י","bt":"תרא","b":"נכד ר יחזקאל משיסלוביץ. רב בשילעל(=שילאל)-פלך קובנא-תרן. חיבר שו\"ת \"מגן שאול\" - בכת\"י. חתנו - ר אידל - ר\"מ בבאלטא ושצוצין."},{"i":43575,"n":"קצנלנבוגן, שאול הלוי מקוסוב","b":"מצאצאי ר שמשון אפשטין מקניגסברג. רב בקוסובה(=קאסאווע), קוברין, חתנו ר שמריהו יוסף קרליץ (אביו של בעל החזון איש) על מקומו אחריו בקאסוב. מבניו - ר מרדכי יונתן."},{"i":43576,"n":"קצנלנבוגן, שאול מברוד ופינטשוב","f":"משה מחעלמא","dt":"תנב","b":"נכד ר מאיר וייל. רב בברודי-תלא, חעלמא-תלג, פינטשוב-תמז, קראקא, בריסק-תנא. בנו - ר יעקב הקדוש בעל \"נחלת יעקב\", ר משה מאנשבך."},{"i":43577,"n":"קצנלנבוגן, שאול מוילנא","f":"יוסף מברודי","k":"בעל הגהות לש\"ס","bp":"בריסק","dt":"תקפה - כב טבת","dp":"וילנא","b":"תלמיד הגר\"א בוילנא. מו\"צ בפלאצק, וילנא. הגהותיו על הש\"ס נדפסו בש\"ס וילנא, מקצת מחדושיו פורסמו ע\"י ר צבי קצנלנבוגן. נפטר צעיר ונספד ע\"י המשורר אברהם דב לבנזון בשיר \"אבל כבד\". נכדו שאול הורביץ שחיבר ספר השוואת המשפט העברי לרוסי - וילנא תרמז. חתנו - ר ידידיה ליפמן אליאשברג."},{"i":43578,"n":"קצנלנבוגן, שאול מוילנא","f":"אברהם קיילעס מקיידן","k":"ר שאול קאדאנער","dt":"תרכח - ב סיון","dp":"וילנא","b":"נכד הקדוש ר מרדכי בן יואל מקיידן והמבורג. חתן ר משה יהודה גראממער. גביר מחכמי וילנא."},{"i":43579,"n":"קצנלנבוגן, שלום מאשאטיז","f":"דוד מקידאן","dt":"תקנא - יח כסלו","b":"רב באשאטיז"},{"i":43580,"n":"קצנלנבוגן, שלמה זלמן","f":"משה מאנשבאך","b":"מצאצאי השר ר שאול וייל."},{"i":43581,"n":"קצנלנבוגן, שלמה זלמן מלופקא","f":"אברהם אברשקא","b":"חתן דודו - ר יעקב קצנלנבוגן בן השר שאול וייל. רב בלוקאב(=לופקא)-ליד פוזנא-תז."},{"i":43582,"n":"קצנלנבוגן, שמואל משילאל","b":"רב בשילאל-תרסג (ואולי הוא זהה עם ר שאול."},{"i":43583,"n":"קצנלנבוגן, שמחה מזבלודאוי","f":"יוסף מבריסק","b":"רב בזבלודאווי-תקע. בנו - ר השל"},{"i":43584,"n":"קצנלנבוגן, שמעון מזאויחוואסט","f":"פנסח מאוסטילא","k":"אדמור מנסכיז זאוויחו","dt":"כב אדר","b":"נכד האדמור ר מרדכי שפירא מנסכיז. חתן ר שלמה חיים מקוידנוב."},{"i":43585,"n":"קצנלנבוגן-מינץ, שמואל יהודה","f":"מהר\"ם פדובה","k":"חתן ה\"לבוש\"","r":"המהרשי\"ק היה רב בווינציאה, ובפאדובה","bt":"רנד-פא","dt":"שנז - ו ניסן","dp":"פאדובה","b":"נכד ר יהודה מינץ. גדול חכמי דורו בתורה, רב בפאדובה, ונציה-שכו. מתלמידיו: ר אבטליון מקינסיליו, ר אשר פרינץ - שהדפיס דרשות ממנו - ונציה שמח. בנו - ר שאול וואהל.","bk":[["שנים עשר דרושים \\ דרשות מהר\"י מינץ",""]]},{"i":43586,"n":"קצנלנבוגן-משיח, אהרן","dt":"תקעז","b":"רב בבעלז"},{"i":43587,"n":"קצנלנבוגן-פדובה, אהרן מבריסק","f":"מאיר מבריסק","k":"בעל מנחת אהרן","dt":"תקלח - כג חשון","b":"חתן ר יעקב הלוי מברקעזי, ובזיוו\"ש חתן ר משה מהאלוסק. רב בבריסק. בניו ר חיים, ר מאיר. חתנו ר יחיאל מיכל, ר אריה ליב מביאליסטוק. ונכדו ר יעקב מאיר."},{"i":43588,"n":"קצנלנבוגן-פדובה, יהושע השל מבו","f":"ראה: פרלוב, יהושע ה"},{"i":43589,"n":"קצנלנבוגן-פדובה, מאיר","f":"יצחק","k":"מהר\"ם פדובה","bt":"רלה","dt":"שכה - י שבט","b":"נכד(-אבי אמו) ר יחיאל לוריא מבריסק. חתן ר אברהם מינץ. מגדולי חכמי דורו, פוסק, מקובל, רב בפאדובה-רפב. השיב במחלוקת ר שמעון גינצבורג ור נתן שאטן - וכתב שאין ברשותו גמרא (בגלל שריפת התלמוד?). בנו ר שמואל יהודה. חתניו - ר זלמן רונקיל(18809), ר יעקב הלוי(9702).","bk":[["שו\"ת מהר\"ם פאדובה",""]]},{"i":43590,"n":"קצנלנבוגן-שפירא, מרדכי","f":"יוסף מאוסטילא","dt":"תרלז - ז אלול","b":"רב באוסטילא"},{"i":43591,"n":"קצנלסון, דב אריה הכהן מארשא","b":"רב בארשא,הסכים על \"אור ישן\"."},{"i":43592,"n":"קצנלסון, יהודה ליב מפטרבורג","f":"ישראל מבוברויסק","k":"בעל שירת הזמיר","bt":"תרו","bp":"טשרניגוב","b":"לאחר שנתייתם מאביו גדל אצל זקנו ואצל דודו ר זאב קארכין מטשרניגוב. תלמיד ישיבת בוברויסק. תלמיד ביהמ\"ד לרבנים בזיטומיר, למד רפואה בפטרבורג והיה רופא מומחה שם. פרסם מאמרים ב\"רוסקי יעווריי\", \"בודושצנסט\", \"המליץ\" - וחתם \"בוקי בן יגלי\". כתביו י\"ל בשם \"חזיונות והרהורים\"."},{"i":43593,"n":"קצנלסון, יעקב מלישניווקע","f":"משה כץ","bt":"תריז","bp":"אורעצע-ליד בוברויסק","b":"למד בבוברויסק, וולוזין. רב בלישניווקה-ווהלין-תרמד. נסמך מאת: ר שלמה הכהן מוילנא, ר יעקב יוסף מוילנא, ר אריה ליב משניפישוק, ר חיים הלל מליבאשוב."},{"i":43594,"n":"קצנלסון, יצחק","k":"בעל הנביא","b":"סופר"},{"i":43595,"n":"קצנלסון, מאיר זאביל מארה\"ב","b":"פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":43596,"n":"קצנלסון, ניסן הכהן מליבאוי","f":"יוסף","bt":"תרכב","bp":"בוברויסק","b":"תלמיד ביהמ\"ד לרבנים בברלין, בעל תואר ד\"ר. התקרב להרצל והיה פעיל בתנועה הציונית, התישב בליבאוי, וכיהן כציר בפרלמנט הרוסי (הדומא) מטעם קורלנד."},{"i":43597,"n":"קצנלסון, שאול","f":"שלמה","k":"בעל אמרי בינה","bt":"תקפא","bp":"וילנא","dt":"תרלד","dp":"למברג","b":"הגיע מוילנא ללמברג. תלמיד ר יוזפא שטרן מזולקוא ור אבלי פוסבולר, סייע בהדפסת ספר רבו \"יד יוסף\". חיבר \"אמרי בינה\" למברג תרכז. חיבר ביאור לירושלמי. פרסם מאמרים על נושאים מדעיים ב\"העברי\", \"ישורון\", ועוד. חיבר \"מגן שאול\" - בכת\"י."},{"i":43598,"n":"קצנשטין, שמואל מאלטונא","f":"חיים זליגמן מגאשלר","dt":"תמו - כז ניסן","dp":"אלטונא","b":"מרביץ תורה באלטונא."},{"i":43599,"n":"קצקא, יצחק מפיעטריקוב","f":"אברהם","k":"ר איציקל חריף","b":"תלמיד ר ישכר דב מראדושיץ."},{"i":43600,"n":"קצ'קמטי, ארמין ממאקוב","bt":"1784","b":"רב הקהלה הניאולוגית במאקוב. הסטוריון וחוקר ספרות. מרצה לתולדות היהודים בהונגריה באוני' סאנד-הונגריה."},{"i":43601,"n":"קצקש - משפחה","b":"משפחה חשובה באוסטרהא. מבניהם פרנסים ותלמידי חכמים ובהם ר טויבה חותנו של ר ברוך ממזבוז."},{"i":43602,"n":"קצקש, גרשון מאוסטרהא","f":"צבי הירש","dt":"תקח - כ סיון","dp":"אוסטרהא","b":"חתן ר יוסף קצקש. מחכמי אוסטרהא."},{"i":43603,"n":"קצקש, טוביה מאוסטרהא","b":"מחכמי אוסטרהא. חותנו של ר ברוך ממזבוז, ור ברוך ישב אצלו כמה שנים ולמד עם ר חיים בן יעקב ישראל מאוסטרהא."},{"i":43604,"n":"קצקש, יוסף מאוסטרהא","b":"פרנס באוסטרהא-תצו יחד עם ר שמואל ר יעקב'ס ועם ר מרדכי הלפרין."},{"i":43605,"n":"קצרגיסקי, שניאור זלמן","f":"יצחק וידזער","bt":"תקעח","bp":"קצרגיסק-ליד וילנא","dt":"תרמח - ט תשרי","dp":"וילנא","b":"נקרא ע\"ש בעל התניא. חתן ר אהרן דוד באקשט בעל \"פעולת אדם\". גביר מחכמי וילנא וחסיד ליובאויטש. מימן הדפסת \"מגיני ארץ\" לזיכוי הרבים. תרם לבית החולים בדרוזקניק, ולבית האסף בוילנא. הו\"ל ספר חותנו."},{"i":43606,"n":"קרא יוסף חיים בן יצחק זליג","bt":"1800","dt":"ה'תרנה 1895","bk":[["טבח והכן",""],["יורה ומלקוש",""],["מנחת שבת",""],["קול אומר קרא",""],["קול אמר קרא",""]]},{"i":43607,"n":"קרא, אביגדור - ב","b":"מצאצאי ר אביגדור קרא מפרג. אביו של ר אברהם מפרג בעל הגהות על הטור-רן."},{"i":43608,"n":"קרא, אביגדור מאפטא וגלוגא","f":"שניאור פיבוש קרא","bp":"ווינה","dt":"תלח - כה אדר","b":"חתן ר יונה תאומים בעל \"קקיון דיונה\". רב באפטא, קונסטנטין, גלוגא רבתי. חתנו - ר יעקב אלישר בן נפתלי מוילנא וירושלים, לפי פין חתניו גם - ר רעקב בן אפרים נפתלי, ר יצחק מאיר תאומים. בנו - ר שניאור פיבוש שחתם-תמו על תקנת קהלת זולקוא."},{"i":43609,"n":"קרא, אביגדור מוינה","b":"מחכמי וינה-ש'. במצבות וינה נזכרה בתו הינדל (נפטרה שנז)."},{"i":43610,"n":"קרא, אביגדור מפרג - הזקן","f":"יצחק הקדוש","k":"בעל ספר הקנה","dt":"קצט - ט אייר","dp":"פרג","b":"אחיינו-בן אחותו של ר יהודה ליוואי הזקן מפרג. מגדולי המקובלים בדורו, רב בפרג עם ר ליפמן מליהוזן ור יונה אחי המהר\"ש מוינה, ור מנחם בן יעקב. בנו ר יהודה יודל קרא. היה חי בזמן המלך וענצל והכומר יוהן רוס שיצאו נגד האמונה הקתולית ובספר \"מנהגי מהרי\"ל\" כותב שהיו בקשר עם ר אביגדור והושפעו ממנו בעניני אמונה. חיבר פיוטים ובהם על הפרעות שהיו בחג הפסח בפרג-קמט. חיבר גם \"אבן ספיר\". נחשב למחבר ספר הקנה אבל כפי הנראה הספר קדום ור אביגדור ערכו והוסיף לו הערות. לפי אוצר הרבנים היה רב גם ברגנשבורג. מצאצאיו: ר אברהם קרא מפרג בעל הגהות על הטור."},{"i":43611,"n":"קרא, אברהם מפרג","f":"אביגדור","k":"בעל ביאור לרש\"י","dt":"שג - כז תשרי","b":"רב וראש ישיבה בפרג. חיבר סליחות, ביאור לרש\"י, ביאור לטור ותלמידו ר יעקב בן ברוך חיבר להם קיצור ונדפס על הטור. נזכר ב\"דרכי משה\", נכתב עליו ב\"צמח דוד\". חיבר פיוט לסליחות על גירוש ביהם \"אנא השם אלוקי אבותיכם\". מתלמידיו ר אברהם יפה אביו של בעל הלבושים."},{"i":43612,"n":"קרא, אברהם מפרג","dt":"קצט","b":"רב בפרג"},{"i":43613,"n":"קרא, אריה ליב מנאחוד וקרוטשיץ","f":"חיים קרא","b":"רב בנאחוד-תק\"מ,קראטשיץ,לעסלא-אינוורצלב"},{"i":43614,"n":"קרא, דב בר מצפת","f":"שמואל מסקאלא","b":"מדפיס בצפת-תרכה."},{"i":43615,"n":"קרא, זיסקינד מלעסרין","f":"אברהם אליהו","b":"אב\"ד לעסרין-תרח. מכתב ממנו לקהלת עשבארג-פרוסיה."},{"i":43616,"n":"קרא, חיים מלונטשיץ","f":"יצחק זליג קרא","b":"רב בלונטשיץ-תע\"ט,דומ\"צ בגלוגא רבתי-תקי\"ט"},{"i":43617,"n":"קרא, יהודה ליב מגלוגא","f":"אביגדור","dt":"תפב","b":"חתן ר יוסף הורביץ. רב בגלוגא רבתי-תן. בנו ר יוסף. חתנו ר אפרים הקשר."},{"i":43618,"n":"קרא, יוסף","f":"יהודה יידל קרא","b":"רב בעשרים קהילות בפולין-ת\"ל"},{"i":43619,"n":"קרא, יוסף","f":"יהודה קרא","b":"מגדולי חכמי דורו-ת\"פ"},{"i":43620,"n":"קרא, יוסף חיים מפינע וולאצלובק","k":"בעל קול אומר קרא","bt":"תקס","dt":"תרנה - כז ניסן","b":"דרשן, רב בפינע, פרדן, וולאצלובק-תרכ. פרסם מאמרים ב\"שומר ציון הנאמן\" - אלטונא תרו-תרטז."},{"i":43621,"n":"קרא, יוסף מצרפת","f":"שמעון","k":"בעל פירוש לתורה","b":"אחיינו של ר מנחם חלבו. מגדולי פרשני המקרא בטרויש-ד'תתמ, פגש את רש\"י."},{"i":43622,"n":"קרא, יצחק זליג מהנובר","f":"אריה יהודה ליב מגלוג","dt":"תקטו - טו סיון","dp":"הנובר","b":"רב בשעפס, קאליש-תעד, צילץ, ברסלוי, דעסוי(דעסא), הנובר והמדינה-תצח. בנו - ר חיים."},{"i":43623,"n":"קרא, ישראל מטבריה","b":"מחכמי טבריה, בשנת תקפז בשליחות בתורכיה."},{"i":43624,"n":"קרא, ישראל מליסא","f":"יצחק זעליג קרא","b":"דומ\"צ בגלוגא-תקטז, רב בזלאטווי-פלאטוב-תקכב, פריישטט. הסכים על \"זרע קדש\" עם דייני זלאטווי."},{"i":43625,"n":"קרא, מאיר מטויסט","f":"יחיאל","b":"נכד ר צבי הירש בוצאץ. רב בטויסט-תרכב."},{"i":43626,"n":"קרא, מנחם מפרג","k":"בעל מורה נבוכים","b":"מגדולי פרג-שנת ר'"},{"i":43627,"n":"קרא, צבי הירש מבוצאץ","f":"יעקב","k":"בעל נטע שעשועים","bt":"תק","dt":"תקעד","b":"רב בבוצאץ, חתנו ר אברהם דודו ואהרמן הדעת קדושים על מקומו אחריו. חיבר \"נטע שעשועים\" זולקוא תקפט.","bk":[["נטע שעשועים [שו\"ת]",""]]},{"i":43628,"n":"קרא, שניאור פיבוש מוינה - הזקן","b":"מגדולי חכמי ווינה-שנת ת'"},{"i":43629,"n":"קרא, שניאור פיבוש מזולקוא","f":"אביגדור מגלוגא","b":"נכד(-אבי אמו) הקיקיון דיונה. חתם-תסד על בחירת ראשי קהלת זולקוא."},{"i":43630,"n":"קראוסצקי, ישראל זאב מקראקא","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":43631,"n":"קראז, יצחק מקאוועל","bt":"תרכה","dt":"תרצו - א אייר","b":"רב בקאוועל"},{"i":43632,"n":"קראטקע, יעקב יהודה","f":"אלימלך","b":"פרסם מאמרים ב\"בית שמואל\" - וארשא תרצו."},{"i":43633,"n":"קראטשין, יוסף","b":"רב-שנת תק\"מ"},{"i":43634,"n":"קראטשין, יעקב מברלין","b":"מראשי הקהילה בברלין. חתם על כתב מינו ר יעקב יהושע לרב בברלין-תץ."},{"i":43635,"n":"קראך, יעקב ליב מברסלוי","k":"בעל חזקה רבה","bt":"תקעט","dt":"תרנח - כ תשרי","b":"גביר,רב בברעסלוי"},{"i":43636,"n":"קראלופסקי, ש' הלוי מפרשבורג","b":"תלמיד ר מאיר א\"ש מאונגוואר."},{"i":43637,"n":"קראן, יהודה הכהן ממיטאוי","f":"אליעזר","k":"בעל דרך סלולה","bt":"תקנג","bp":"טוקום","b":"תלמיד ר יוסף בלומנפלד מטוקום. מורה במיטאוי, מתרגם. חיבר \"דרך סלולה\"."},{"i":43638,"n":"קראנאך, אברהם מאלטונא","dt":"תקעג - יב כסלו","dp":"אלטונא","b":"ר\"מ בהמבורג, דיין באלטונא-תקעב."},{"i":43639,"n":"קראסוצקי, ישראל זאב מקראקא","b":"פרסם מאמרים ב\"אור תורה\" - ירושלים תרנז."},{"i":43640,"n":"קראסתו די, דוד נאמיאס מקורסאו","b":"רב בקורסאו-תקץ, וישבו בבית דינו ר בנימין די קאסערעס, ר משה לויפיס פינייא."},{"i":43641,"n":"קראץ, יחיאל צבי מאויבר-ווישווא","b":"מחכמי אויבר-ווישווא. חתנו - ר אברהם דוד מנאפראד."},{"i":43642,"n":"קראקאוו, משה מבערזובקה","b":"ר\"מ בישיבת \"תורה אור\" בבערזובקה - בראשות ר שלמה לנגר."},{"i":43643,"n":"קראקו, בנימין מירושלים","b":"מחכמי ירושלים-סוף שנות ה-תק', שם אשתו - אסתר."},{"i":43644,"n":"קראקוביא, אברהם חיים מונציה","b":"רב בונציה. שות וחבורים ממנו - בכת\"י. זקנו של ר יעקב מנחם קראקוביא."},{"i":43645,"n":"קראשוויץ, יהודה","b":"רב בלבוב-שי\"ז"},{"i":43646,"n":"קראשטו די, יוסף משלוניקי","b":"מדפיס בדפוס גדיליה בשלוניקי--רפב."},{"i":43647,"n":"קרבוז, זלמן אידל מסרדניק","dt":"תשג","b":"רבה האחרון של סרדניק. נספה בשואה. פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":43648,"n":"קרבונירי, ל'","b":"קונסול הולנד בתורכיה-תקצו, כתב על כת ה\"דונמה\"."},{"i":43649,"n":"קרביץ, אברהם יצחק","b":"פרסם מאמרים ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":43650,"n":"קרביץ, זאב","dt":"תשג","b":"רב ברוטקע-קזקי"},{"i":43651,"n":"קרביץ, ישראל דוד","dt":"תשג","b":"רב בדאוויר-גרודק"},{"i":43652,"n":"קרביץ, משה מפאיורה","dt":"תשג","b":"רבה האחרון של פאיורה(=פאייארע). נספה בשואה."},{"i":43653,"n":"קרביצקי, אפרים שלמה מלוקניק","dt":"תשג","b":"חתן ר שלמה הלוי פינזילבר. רב בואקשנה על מקום ר משה רבינוביץ, ור קלמן מגיד-הי\"ד על מקומו אחריו. רב בציטוביאן, רבה האחרון של לוקניק, נספה בשואה."},{"i":43654,"n":"קרבלניקוב, יוסף ליב מהוסטמליא","f":"אברהם אבא","bt":"תרלו","b":"חתן ר צבי גרשון סמינבוסקי מפאבעלוב. רב בהאסטומול(=האסטאמליא, האסטאמעץ)-פלך קיוב-תרסז."},{"i":43655,"n":"קרבן, אברהם חיים הלוי ממגרוב","f":"עובדיה","bt":"תרע..","bp":"מגרוב","dt":"תשמד","dp":"ירושלים","b":"עבר עם אביו מבודפשט למנצסטר, לונדון שם למד אצל ר אליהו לפיאן בישיבת \"עץ חיים\", רב בדונידין (ניו זילנד), לונדון, ניירובי (קניה), סטרנד (דרום אפריקה), עלה לירושלים-תשלח. חתן רמ\"מ גמזו."},{"i":43656,"n":"קרבן, עובדיה הלוי","f":"שלום מברודי","b":"התגורר בבודפשט, עבר למנצסטר."},{"i":43657,"n":"קרבן, שלום הלוי מברוד","f":"עובדיה","dt":"תרע.. - בערך","dp":"ירושלים","b":"חזן בברודי. נכד ר איכל מסקול. עלה לירושלים. הוציא לאור \"דרכי ישרים\" ו\"שירה לחיים\"."},{"i":43658,"n":"קרבצינסקי, אברהם מרדכי","b":"רב בגראייבה"},{"i":43659,"n":"קרבצינסקי-גולד, יעקב מאיר מקפ","f":"אברהם מרדכי מגרייבה","bt":"תרכז-ח","bp":"גרייבה-פלך לומזה","dt":"תרעד - כ כסלו","dp":"גורודיא-פלך מינסק","b":"תלמיד ישיבת וולוזין, כולל קובנא. חתן ר יהושע מנחם גולדואסר משצוצין. דרשן, רב באיזבלין-פלך גרודנא-תרנו, קאפוליא-פלך מינסק (ליד סלוצק), מריאמפול-תרעא. פרסם מאמרים ב\"יגדיל תורה\" - סלוצק-בוברויסק תרסט. בנו - ר וולף משיקגו-ארה\"ב. נלקח כבן ערובה ע\"י הרוסים בזמן מלחה\"ע ה-I יחד עם שבעת טובי העיר ועבר עינויים קשים שמהם נפטר. חיבר שו\"ת, באורים למדרשים - שנפלו בידי הבולשביקים. בנו ר זאב גולד מראשי המזרחי."},{"i":43660,"n":"קרגוי, מנחם מנדל מפאריס","k":"בעל גדולי טהרה","dt":"תרב - כט אלול","b":"מרביץ תורה בפאריס, פיורדא. מאמר ממנו ב\"הפלס\" - ברלין תרסא-תרסה."},{"i":43661,"n":"קרגל, רפאל חיים יצחק","bt":"תצג","dt":"תקלה","b":"דרשן,מחכמי חברון,שד\"ר ללונדון-תקי\"ד"},{"i":43662,"n":"קרגר, ישראל ממישלניץ","b":"מחכמי מישלניץ. תלמיד ר יהושע פנחס בובמך."},{"i":43663,"n":"קרד, אברהם מבורשטין","b":"רב בבורשטין-תרכא."},{"i":43664,"n":"קרדוזו, אברהם מיכאל (ישראל)","bt":"שצו","bp":"ספרד או פורטוגל","b":"מאנוסי פורטוגל וחזר ליהדות, עבר לליוורנו, מצרים, טריפולי. הוגה הדעות של התנועה השבתאית. חיבר ספרים רבים."},{"i":43665,"n":"קרדוזו, אברהם ממכנאס","bp":"תונס","b":"גביר מקורב למלכות במכנאס-שנות ה-תק'. ב\"תהלה לדוד\" 2 שירים לכבודו."},{"i":43666,"n":"קרדוזו, בנימין נתן מארה\"ב","bt":"תרל","bp":"ניו יורק","b":"שופט, חוקר ופילוסוף בארה\"ב, פעיל בקהלה היהודית."},{"i":43667,"n":"קרדוזו, דוד מאמשטרדם","b":"מחכמי אמשטרדם, ממנהיגי הקהלה, ממונה על ההקדשות לארץ ישראל."},{"i":43668,"n":"קרדוזו, יצחק מספרד","k":"בעל המעלות הטובות","bp":"פורטוגל","dt":"תם","dp":"וירונה","b":"רופא ממשפחת אנוסים בפורטוגל ובמדריד, והיה שם ראש הרופאים במדריד. הגיע לונציה-תל, וחזר ליהדות. חיבר שם ספר ברפואה. ברח לונציה ושם חזר ליהדות. חיבר ספר על חכמת המחקר - ונציה, ו\"המעלות הטובות שנמצא בישראל והעלילות אשר שמו עליהם\"."},{"i":43669,"n":"קרדוזו, משה מאזמיר","b":"מחכמי אזמיר-שנות ה-ת'."},{"i":43670,"n":"קרדון, אברהם יצחק מארה\"ב","b":"רב בשיקגו."},{"i":43671,"n":"קרדי, יוסף הפייטן מספרד","f":"יהודה","b":"פייטן בספרד, שיר לכבודו מאת ר\"א בדרשי. לדעת שד\"ל היה תלמיד הרמב\"ם."},{"i":43672,"n":"קרדי, יוסף מטריפולי","f":"יהודה","bt":"תל","dt":"תק - בערך","b":"רב ומשורר בטריפולי. פיוטים ממנו ב\"יום טוב ליטעראטורגעשיכטע דער סינאגאגאלען פאעזיא\" ברלין 1865."},{"i":43673,"n":"קרדינא, אהרן מקרדינא","f":"אברהם","k":"בעל ספר הקרניים","b":"מקובל,רב בקרדינא-שנ\"ו"},{"i":43674,"n":"קרואני, משה מתימן","b":"מחכמי צנעא-תימן. ובנו ר יחיא היה דיין."},{"i":43675,"n":"קרואני, שלמה מתימן","k":"בעל שושני הגנים","bt":"תרסט או תרעג","bp":"רצאבה-תימן","dt":"תשמג - כא חשון","b":"דיין ברצאבה יחד עם חברו ר נסים רצאבי. נכד ר יחיא קרואני. עלה לארץ-תשט והתישב בכפר סבא."},{"i":43676,"n":"קרוגליאק, אהרן","f":"דוד מטערנווקא","b":"חתן ר פנחס מלאדזענקא."},{"i":43677,"n":"קרוגליאק, דוד מטערנווקא","f":"משה אלתר מבוהיסלוב","bt":"תרכג","b":"נינו של ר שמלקא מאומאן ומצאצאי ר שמלקא הורביץ מניקלשבורג. רב בטרנובקה(=טערנווקא)-פודוליה-תרנג. בנו - ר אהרן."},{"i":43678,"n":"קרוגליאק, משה אלתר","b":"רב ומו\"צ בבאהיסלב-תר\"ל"},{"i":43679,"n":"קרוגר, חיים","f":"שמואל יצחק","k":"בעל המאור ביהדות","bt":"1875","bp":"מאז'ייק","b":"תלמיד ישיבת פוניבז, טלז. עבר לשאוולי והצטרף לתנועה הציונית, עבר בעיירות ליטא והטיף לציונות. היגר לקנדה-1907 והיה שוחט במונטריאול. פרסם ב\"קענעדער אדלער\" מאמרים בנושאים שונים. חיבר גם \"השגות\" על ספר ההיסטוריה של גרץ, \"דער רמב\"ם זיין לעבען און שאפען\"."},{"i":43680,"n":"קרודו, דוד מורינו מאזמיר","b":"מחכמי אזמיר, חתם-תרכח על שטר מכירה של חצר בבעלותו, והצטרפו אליו בחתימותיהם ר ישעיה יוסף פונטרימולי, והדיין ר חיים שמואל."},{"i":43681,"n":"קרודובא, משה מירושלים","b":"נכד ר משה קורדובירו מצפת. מחכמי ירושלים-שפה בזמן פרעות אבן פארוך."},{"i":43682,"n":"קרודיל, משה מאזמיר","dt":"תקכא - כז שבט","dp":"אזמיר","b":"מחכמי אזמיר."},{"i":43683,"n":"קרווסקי, שלמה זלמן מארה\"ב","f":"שמעון","bt":"תרלו","bp":"סמרגון","b":"תלמיד ישיבת סלובודקא. נסמך מאת: ר שלמה הכהן מוילנא, ר בצלאל לוריא מסובאלק, ר מרדכי וייזצל מאשמנא, ר י\"ל גורדון מלומזה. היגר לארה\"ב-תרעו וכיהן כרב בקהלת \"אגודת אחים ובני ישראל\" באלנטון. חבר אגודת הרבנים באמריקה."},{"i":43684,"n":"קרוור, ברוך","f":"משה יהושע ניישטטער","b":"מחכמי לוצין-תרל. בנו - ר נחמיה רבינזון מארה\"ב. אחיו - ר שלום ניישטטר, ר בנימין בינוש נייוויידל."},{"i":43685,"n":"קרוז, פנחס מסיפעטער","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":43686,"n":"קרוזיר, דוד","b":"רב במערטש-תר\"ל"},{"i":43687,"n":"קרוחי, רפאל ישראל מצפת","b":"מחכמי צפת. בשליחות באיטליה-תץ. הסכים על פסק ב\"מים רבים\" לר רפאל מילדולה."},{"i":43688,"n":"קרוטשין, אברהם מברלין","f":"ר\"ז","b":"מראשי הקהילה בברלין, חתם על כתב הרבנות של ר צבי הירש מלונדון וברלין-תקלב."},{"i":43689,"n":"קרויזוירט, חיים","b":"פרסם מאמרים ב\"שילה\" - ירושלים תשה."},{"i":43690,"n":"קרויזר, אברהם עביר הלוי","f":"חיים יעקב מדולינה","bp":"דולינה","b":"חתן ר מרדכי זאב גוטסמן מבוליחוב. היגר לארה\"ב-תרסו והתגורר בניו יורק - שם עסק בתורה וחסד וחיזוק היהדות. הו\"ל ספר אביו \"באר יעקב\"."},{"i":43691,"n":"קרויזר, אליעזר הלוי מדולינא","b":"תלמיד החוזה מלובלין. רב בדולינא."},{"i":43692,"n":"קרויזר, דב מאיר","b":"פרסם מאמרים ב\"כרם ציון\" - ירושלים תרצה-תשיג - קובץ \"מדרש בני ציון\"."},{"i":43693,"n":"קרויזר, חיים יעקב הלוי מדולינה","f":"צבי אליעזר מדולינה","k":"בעל באר יעקב","bt":"תרח או תריא","bp":"דולינה","dt":"תרעד","b":"רב בדולינה(=דאלינא)-תרמג על מקום אביו. חסיד האדמור מזידיטשוב. חתן ר יעקב וייזר-גרבר מוורצקי. חיבר \"באר יעקב\" מונקטש תרפז."},{"i":43694,"n":"קרויזר, חיים מקובנא","k":"בעל פרי עץ חיים","b":"רב בקובנה-תר\"כ"},{"i":43695,"n":"קרויזר, צבי אליעזר מדולינה","dt":"תרלד","b":"רב בדולינה, בנו ר חיים יעקב על מקומו אחריו. חסיד החוזה מלובלין ור צבי הירש מזידיטשוב."},{"i":43696,"n":"קרויזר,דוד ממערטש","b":"מצאצאי ר אליהו מקרוז' (קרויזר)-גיסו של הגר\"א. אחיינו-בן אחותו - ר משה זבולון מרגליות מניו יורק."},{"i":43697,"n":"קרויט, שמחה","b":"תלמיד ר צבי הירש מייזלש בישיבת בובוב ביינמרקט-תרצא."},{"i":43698,"n":"קרויטהמר, ישראל מבוצאץ","f":"נפתלי שמואל","bt":"תריב","bp":"בוצאץ","b":"חסיד צורטקוב, מחכמי בוליחוב."},{"i":43699,"n":"קרויס אהרן בן יעקב קופל","bt":"1870","dt":"ה'תרצ 1930","bk":[["מטה אהרן",""]]},{"i":43700,"n":"קרויס, אברהם דוד הכהן מסעבען","f":"משה אהרן מנאדי-בניא","bt":"תרע","dp":"ניו יורק","b":"תלמיד ישיבת מיר-ליטא. עבר לסטרוזוניץ. אב\"ד סעבען, רב בצ'יק-סרדה-תרצט, רב בהרמאנשטדט. ניצל מהשואה ואחריה היגר לארה\"ב, וכיהן כרב בניו יורק."},{"i":43701,"n":"קרויס, אברהם משה דוד פיגל'ס","f":"שמואל חסיד","k":"בעל נפש אדם","bt":"תקפא","dt":"תרנא - כו אדר","b":"תלמיד מהר\"ם א\"ש, דברי חיים מצאנז. רב באונגוור ובני עדתו התיחסו אליו כאדמו\"ר. נזכר ב\"דודאי השדה\" לר אליעזר דייטש מבאניהאד."},{"i":43702,"n":"קרויס, אהרן מאיגלוי","f":"יעקב קופל מאטש","k":"בעל מטה אהרן","bt":"תרלב","bp":"אטש","dt":"תרפח - ו סיון","dp":"איגלוי","b":"תלמיד השב\"ס. חתן ר אברהם יעקב גיסקן מניירא ועבר לשם. רב באיגלוי(=איגלא)-תרנט."},{"i":43703,"n":"קרויס, אהרן מאיר מסידני","f":"יהושע ממישקולץ","k":"בעל זכרון יהושע","b":"אב\"ד בסידני, עבר לניו יורק. נכד ר מרדכי קרויס מעדעלין ומישקולץ, והביא מתורתו בספרו."},{"i":43704,"n":"קרויס, אליעזר צבי מסולאד","b":"חתן ר יוסף שטרן מועספרין. רב בסולאד, שיאפאק."},{"i":43705,"n":"קרויס, אלעזר חיים משענלנקא","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":43706,"n":"קרויס, אשר אנשיל מראצפרט-נ\"י","k":"בעל בירור הלכה","bt":"תרפז","dt":"תשז - כט טבת","b":"מצאצאי ר שמואל פרנקל מדאראג. רב בלינץ, בואנוס איירס, עבר לניו יורק ויסד \"הכנסת אורחים\" בויליאמסבורג. חיבר גם \"די תורה וורט\", \"תורה און סחורה\"."},{"i":43707,"n":"קרויס, בנימין זאב מדברצין","f":"אליעזר צבי מסולאד","k":"בעל מראה בזק-בכת\"י","bt":"תריג","bp":"סולאד","dt":"תרפא - כו שבט","dp":"דברצין","b":"תלמיד הכת\"ס, ור אהרן קוטנא מטאטוס. רב ומיסד בי\"ס יהודי בסאסרעגן ומנהלו. חתן ר הלל פולק מסאסרעגן, ועבר לשם וכיהן כדיין-תרלג. רב בהאלאש-תרמז על מקום ר אליעזר זוסמן סופר, דברצין-תרנב."},{"i":43708,"n":"קרויס, דוד מפרשבורג","b":"ראש הקהלה בפרשבורג-תרעז-תרצא."},{"i":43709,"n":"קרויס, דן מאונגוואר","f":"פתחיה מואגאש","dt":"תשכד - י אב","dp":"ירושלים","b":"תלמיד הדעת סופר, ור יהודה גרינולד מסטמר ור שמואל רוזנברג מאונסדורף. חתן ר מאיר א\"ש מאונגוואר - מצאצאי ר מאיר א\"ש מאונגוואר. עבר לאונגוואר, ניצל מהשואה ועבר לניו יורק, עלה לירושלים. בזיוו\"ש חתן ר יהודה קרויס מלקנבך. הו\"ל \"שירי מצות - שירה לחיים\" עם הערות ממנו."},{"i":43710,"n":"קרויס, הנריק משיקלויש","b":"רב הקהילה הניאולוגית בשיקלויש-מחוז באראניא, עבר לארה\"ב וכיהן כרב בלוס אנגלס."},{"i":43711,"n":"קרויס, חיים יעקב משה מרוגנדורף","dt":"תשד","b":"רב בראיקא=רוגנדורף. חתן ר שמואל שלזינגר-יפה-מרגליות."},{"i":43712,"n":"קרויס, יהודה הכהן מלקנבך","f":"יקותיאל","k":"בעל דבר בעתו","r":"גאב\"ד לאקענבאך ומלפנים גאב\"ד יאנקאווטץ","bt":"תריט","dt":"תרצט - כא שבט","dp":"ירושלים","b":"תלמיד מהר\"ם שיק. חתן ר משה לוינגר מוויצען. רב ביאנקוביץ-תרמד, יאנוש-האלמא-תרמד, לקנבך(=יאקענבאך, לאקאמפאק)-תרנה, עלה לירושלים-תרצג. חיבר גם \"מנהגי ישראל\", \"פלא יועץ\", \"שמחת הנפש\", ועוד - בלשון אשכנז. הו\"ל כתב עת - \"דבר בעתו\" - פאקש תרסט, \"מגד ירחים\" - סיגט תרנח. הו\"ל ספרי דרשות ואגדות בגרמנית באות עברית.","bk":[["אבל משה",""],["דברי אמת",""],["דברי יהודה",""],["דברי שלום",""],["מגן אבות",""],["מורה דרך - מוסר",""],["מנחה חדשה",""],["משיבת נפש – שמחת הנפש, בן משכיל",""],["קול יהודה – צאינה וראינה וחי'",""],["תומר דבורה – פלא יועץ",""],["משיבת נפש – שמחת הנפש",""],["בן משכיל",""]]},{"i":43713,"n":"קרויס, יהושע ברוך מערדא סנזשרץ","f":"שמואל דוד משאראט","dt":"תש..","b":"חתן ר גרשון מנדל קאהן מערדא-סענזשארץ, רב הצעיר בערדא-סענזשארץ. נספה בשואה. פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":43714,"n":"קרויס, יהושע ממישקולץ","f":"מרדכי מעדעלין","bt":"תרנד","bp":"עדעלין","dt":"תשד","dp":"אושוויץ","b":"תלמיד הדעת סופר, ור חנניה יו\"ט ליפא טיטלבוים מסיגט, ור מרדכי יהודה ליב וינקלר מהעדילאמאדע ועוד. חתן ר יצחק איזיק רוזמן ממונקטש. מחכמי עדעלין, מונקטש. נספה בשואה. בנו - ר אהרן מאיר אב\"ד סידני בעל זכרון יהושע."},{"i":43715,"n":"קרויס, יונה מצעהלים","b":"חתן ר צבי יהודה פרידמן מטעפלטשאן - חתן החת\"ס."},{"i":43716,"n":"קרויס, יוסף משה מירושלים","b":"סופר כולל אונגרן בירושלים-תרלט,"},{"i":43717,"n":"קרויס, יחיאל יוסף מסט מארטון","f":"בנימין זאב מדברצין","dt":"תשיט","dp":"טבריה","b":"תלמיד ישיבות הונגריה ובעל תואר ד\"ר ממינכן. חתן ר מרדכי צבי הכהן מרטון מסנט מארטון, רבה האחרון של דיצ'ה סט' מרטון-תרע\"ג על מקום חותנו. ניצל מהשואה ואחריה המשיך לכהן כרב. עלה לארץ-תשט."},{"i":43718,"n":"קרויס, יעקב קופל מאטש","f":"צבי יהודה מפרשבורג","k":"בעל ברכת יעקב","bt":"תקפח","bp":"פרשבורג","dt":"תרעה - ב טבת","dp":"אטש","b":"תלמיד הכת\"ס, ור ישראל יצחק אהרן לנדסברג מגרוסורדין. חתן ר אהרן גרינהוט מסערדאוהל ועבר לשם. רב בסערדאוהל, אטש-תרלא, ובנו ר שמעון על מקומו אחריו. חיבר גם \"עטרת יעקב\", \"בית יעקב\"."},{"i":43719,"n":"קרויס, יצחק מראב","k":"בעל בירורי השיטות","dt":"תשמח - ח שבט","dp":"ירושלים","b":"חתן ר עזרא צורף-גולדשטין מסערדאוהל. חתנו - ר אברהם אהרן שטינר מפרשבורג. רב ומלמד בפרשבורג ובבני ברק, ר\"מ בישיבת נייטרא במונט-קיסקא ובישיבת מחנה אברהם בבני ברק. חיבר \"שבח נעורים\"."},{"i":43720,"n":"קרויס, ישראל מנחם אלתר חיים","f":"נתן אנשיל מסאניסלוי","b":"חתן ר שמואל צבי וייס מבנדקוביץ. אב\"ד בנדקאוויטץ(=בנדקוביץ)."},{"i":43721,"n":"קרויס, מאיר יהודה ליב מבלזנדר","f":"בנימין זאב מדברצין","bt":"תרנ","dt":"תשלה -כב-ג כסלו","dp":"ירושלים","b":"תלמיד ר שמואל רוזנברג מאונסדורף. חתן ר ישראל רייך מבאטורקז בעל \"מנחת ישראל\". רב בבאלאזש(=בלזנדורף)-תרפד, ניצל מהשואה, עלה לארץ-תשו-ט וכיהן כרב בקורדני-קרית ביאליק, עבר לירושלים."},{"i":43722,"n":"קרויס, מיכאל מיארמוט","b":"דומ\"צ ביארמוט-תר\"י"},{"i":43723,"n":"קרויס, מנחם מנדל מבאנפי-הוניאד","b":"מחכמי באנפי-הוניאד. עלה לירושלים. חתנו - ר מרדכי יהודה וינקלר."},{"i":43724,"n":"קרויס, מרדכי מעדעלין","f":"אברהם משאראש-פוטוק","dt":"תשד - כו סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, ור שמואל ארנפלד ממטרסדורף, ור יעקב טננבוים מפוטנק. חתן ר יעקב צימרמן מסנט פעטר. מחכמי עדעלין, מראשי הקהלה במישקולץ. נספה בשואה. מתורתו ב\"זכרון יהושע\" לנכדו ר אהרן מאיר קרויס אב\"ד סידני. בנו ר יהושע ממישקולץ."},{"i":43725,"n":"קרויס, משה אהרן מנאדי-באניה","f":"יהודה הכהן מלקנבך","k":"בעל זכרון יוסף-תרפו","bt":"תרמו","dt":"תשד - טז-כ סיון","dp":"אושוויץ","b":"תלמיד השב\"ס, ר גרשון שטרן ממאראש לודאש, ר אלעיזר דייטש בבניהאד ור יוסף צבי דושינסקי בגאלאנטא. בעל תואר ד\"ר מגרמניה. חתן ר ליב אולמן מלקנבך - נכד ר אברהם אב\"ד לקנבך. מלמד בבית משפחת ארלנגר בלוצרן (שוויץ), רב בנמש-סאלוק-ליד פאפא-תרסח, טשעטשויץ-סלובקיה-תרעג, רב וראש ישיבה בנאדי באניא-ליד סטמר-תרעט. מגדולי הנואמים בטרנסילבניה, בעל תואר ד\"ר - ולמרות זאת חרדי ומקורב לחסידות.. היה מועמד לצ'רנוביץ, ולבוקרשט אך סירב לעזוב את טרנסילבניה. אחיו של ר אדוניהו בעל \"קהלה קדושה לקנבך\" ירושלים תשכג. נספה בשואה. חיבר \"כתוב לאמר\". הו\"ל ספר חותנו זקנו \"בית אברהם\" עם הערות ממנו. מאמר ממנו ב\"המעין\" - בודפשט תשז (לאחר השואה!)."},{"i":43726,"n":"קרויס, משה אהרן מראב","b":"דומ\"צ בראאב-ת\"ר"},{"i":43727,"n":"קרויס, משה אליעזר מקרלסבורג","f":"שמעון-שתילי זיתים","k":"בעל שיח משה","bt":"תרנ-א","bp":"אטש או נאג'-סט מיקלוש","dt":"תשלא - ב אדר","dp":"לונדון","b":"תלמיד השב\"ס, ור אליעזר דוד גרינולד בעל \"קרן לדוד\" מסטמר. חתן הגביר ר צבי הרש גוטליב מסטמר, ועבר לשם. מזכיר הלשכה האורטודוכסית בטרנסילבניה בביסטריץ - אחר מלחמת העולם ה-I. רב בדיערדש-סנט מיקלוש(=ג'רגו סט מיקלוש)-תרפז, רב בקרלסבורג-תרפח - עם הצטרפות העיר לברית הקהלות האורטודוכסיות. ניצל מהשואה והגיע לאנגליה וכיהן כרב בלונדון-תשז, לידז-תשי, לונדון-תשכ. אחיו ר מנשה רב בבזל. בנו ר יעקב אהרן קאפל מירושלים הו\"ל את ספר אביו \"שיח משה\" ירושלים תשלד, חיבר גם \"רגל ישרה\"."},{"i":43728,"n":"קרויס, משה בונם מבאדען","f":"יונה מצעהלים","k":"בעל מנחת משה","bt":"תרלו","bp":"טאפלאטשן","dt":"תרצט - י שבט","dp":"ציריך","b":"נכד החת\"ס. תלמיד השב\"ס, ור יהודה גרינולד מסטמר. חתן ר שמעון פולק בעל \"שם משמעון\" מבעלניעש, ועבר לשם. רב בבאדן (שוויץ). חיבר הקדמה לספר חותנו-תרצב.","bk":[["מנחת משה",""]]},{"i":43729,"n":"קרויס, משה חיים","f":"יהודה ליב מיאנקאוו","dt":"תרלה","dp":"נייטרא","b":"תלמיד החת\"ס. רב בנייטרא."},{"i":43730,"n":"קרויס, משה מאלבא-יוליא","b":"תלמיד בישיבת פרשבורג בזמן מלחה\"ע ה-I. רב באלבא-יוליא."},{"i":43731,"n":"קרויס, משה מדנבר-קולורדו","b":"רב בדנבר-קולורדו. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז."},{"i":43732,"n":"קרויס, נתן אנשיל מסניסלוי","f":"שלום מלעגענע-מיהאי","k":"בעל שארית נתן-תשמה","b":"תלמיד ר יהודה גרינוולד בסטמר. חתן הגביר ר צבי הופמן מכפר אויבר-ביסטרא. רב בסאניסלוי-ליד קרולה, והתפרנס ממתן הכשר ליין שאנשי העיר גם הגויים עסקו ביצורו. נספה בשואה. אחיינו ותלמידו ר שלום קרויס הו\"ל את ספרו עם תולדותיו - נ\"י תשמה. בנו - ר ישראל מנחם אלתר חיים מבנדקאויטץ, חתנו - ר עמרם זילברשטין."},{"i":43733,"n":"קרויס, פתחיה מואגאש","f":"שמואל קרויס","dt":"תרצד - יז ניסן","b":"רב במיקאהאזא,וואגאש"},{"i":43734,"n":"קרויס, צדוק הלוי ממוהילוב וי-","f":"ירחמיאל","dt":"תרכא - ה ניסן","dp":"ירושלים","b":"רב במוהילוב, עלה לירושלים-תקפב, קנה חצר ברחוב חב\"ד ונקראה בשם \"רבי צדוק'ס האש\", ובנה ביכ\"נ לאנשי הו\"ד בשם \"אהבת ציון\", ממיסדי \"עץ חיים\". בשליחות באמריקה-תרט יחד עם ר יהוסף שוורץ בעל \"תבואות השדה\" - במשך כשלש שנים. חתנו ר משה זאקס מירושלים."},{"i":43735,"n":"קרויס, צדוק מירושלים","k":"בעל דברי צדק","bt":"תרכב","dt":"תשי","b":"ממיסדי כולל שומרי החומות בירושלים."},{"i":43736,"n":"קרויס, שלום מאודווארי","k":"בעל דברי שלום","b":"חתן ר ישראל אלתר לנדוי אב\"ד עדעלעני - חתנו של ר ישעיה מקרסטור(=קרסטיר). אב\"ד שאראט אודווארי, רב בניו יורק."},{"i":43737,"n":"קרויס, שלום מוואידא-הוניאד","dt":"תרפ.. - בערך","b":"רב בואידא-הוניאד - החל משנות התרנ'. הספיד את המלכה אליזבת שנרצחה-תרנח."},{"i":43738,"n":"קרויס, שלום ממילאני","b":"חתן ר יהושע ברוך רייניץ מטשטשוביץ. רב בלעגעניעמיהאל(=מילאני)-תרסג. בנו - ר שמואל דוד משארעט."},{"i":43739,"n":"קרויס, שלמה וולף מבייאה","b":"דיין בבייאה-תרלד אצל ר משה נאשאר."},{"i":43740,"n":"קרויס, שמואל דוד משארעט","f":"שלום מלעגעניע","b":"אב\"ד שארעט אודווארי. בניו - ר שלום על מקומו אחריו, ר יהושע ברוך מבערדא סענזשארץ."},{"i":43741,"n":"קרויס, שמואל מבודפשט ווינה","b":"תלמיד ביהמ\"ד לרבנים בבודפשט. מורה בביהמ\"ד לרבנים בוינה-1905 ומנהלו האחרון - עד 1938. פרסם מאמרים ב\"ירושלים\" - ירושלים תרמב-תרעט."},{"i":43742,"n":"קרויס, שמואל מואגאש","dt":"תרסט - ט טבת","b":"תלמיד ר מאיר א\"ש באונגוואר, ומקורב לר יחזקאל שרגא משינאווא שמינהו לאדמור בגיל-80. רב בואגאש, ו\"אוהל\" הוקם על קברו. נכדו - אב\"ד ראגנדורף."},{"i":43743,"n":"קרויס, שמואל סגל מסנינא","f":"דוד פייגלס","dt":"תרעא - יג שבט","b":"רב בסנינא"},{"i":43744,"n":"קרויס, שמעון מאטש","f":"יעקב קאפל מאטש","k":"בעל שתילי זיתים-תרצח","bt":"תרך","dt":"תשד","b":"רב בנאג' סט מיקלוש-תרן, רדלבורג-תרס, סארוואש, ועוד, רב באטש על מקום אביו-תרעה. נספה בשואה. פרסם מאמרים ב\"הלכה למעשה\" - דעש תרצג. ?? לא באוצר ??"},{"i":43745,"n":"קרויס, שמעון מבודפשט","f":"משה אהרן קרויס","b":"רב פעלים,רב בבודפשט-תרכ\"ט,לחם בריפורמים"},{"i":43746,"n":"קרוכמל, אברהם דב מברוד","f":"נחמן-רנ\"ק","k":"בעל ירושלים הבנויה","bt":"תקעז","bp":"זולקוא","dt":"תרמח","dp":"פפד\"מ","b":"תלמיד מהר\"ץ חיות, ר שלמה קלוגר. מחכמי ברודי. משגיח כולל גליציה על מעות א\"י. פנה להשכלה. הוציא לאור \"מעלות היוחסין\" לזקנו ראז\"מ."},{"i":43747,"n":"קרוכמל, אריה יהודה ליב","f":"מנחם מנדל-צמח צדק","k":"בעל פרי גנוסר","dt":"תמד","b":"רב בטרביטש,ניקלסבורג-תל\"א"},{"i":43748,"n":"קרוכמל, חיים מקראקא","k":"בעל מקור חיים","bt":"שפו","dt":"תנו","b":"דרשן גדול בקרקא. חיבר \"מקור החיים\" פיורדא תנז."},{"i":43749,"n":"קרוכמל, מנחם מנדל","r":"אור תורתו זורח בק\"ק ניקלשבורג והגלילות","bt":"שס","dt":"תכא - ב שבט","b":"מגדולי חכמי דורו,פוסק,דיין בקרקא,רב בקרעזמיר-שצ\"ו,פרוסניץ,ניקלשבורג והמדינה-תח.","bk":[["צמח צדק [הקדמון]","שו\"ת - אחרונים"],["צמח צדק – שו\"ת",""],["צמח צדק [שו\"ת] (צמח צדק הראשון)",""]]},{"i":43750,"n":"קרוכמל, מנחם מנדל","f":"דוד איסרל","k":"בעל צמח צדקה","dt":"תקז","b":"רב ברוסטיץ, ראב\"ד בניקלשבורג. מחברי ועד ארבע ארצות וישב עמם בועד ירוסלב ולובלין. דיין בקראקא. בזמן גזירות תח ביקר אצלו ר השל מלובלין והראה לר השל מכתב שקיבל מק\"ק העלישוי אודות ר שבתי בעל הש\"ך אם ראוי להיות לרבם וענה לו כדאי הוא שתפנה לו מקומך פה בניקלשבורג ותלך אתה להלישוי - ור מנחם ברוב ענוותנותו כתב להם מה ששמע מר השל ואכן התקבל הש\"ך לרב בהעלישוי."},{"i":43751,"n":"קרוכמל, נחמן הכהן","f":"שלום","bt":"תקמה","bp":"ברודי","dt":"תר - א אב","dp":"טרנופול","b":"חתן ר שמערל הוכרמן מזולקוא וישב ולמד שם, חזר לברודי, עבר אל בתו בטרנופול. חוקר ופילוסוף."},{"i":43752,"n":"קרוכמל, צבי הירש","k":"בעל נחלת צבי","b":"תלמיד ר משה יעקב דמביצר."},{"i":43753,"n":"קרוכמל-מורפשיק, יונה מקראקא","dt":"תכט - יד שבט","b":"דיין בקראקא"},{"i":43754,"n":"קרול, אהרן (לסקר) מלאסק","k":"בעל תורת אהרן","dt":"תרעט - כ ניסן","b":"גביר מחכמי לאסק(=לוסק), לודז. מתלמידיו ר יצחק גרזון. בנו - ר מרדכי ניסן מלודז הו\"ל מכתבי אביו - \"תורת אהרן\" עם הוספות ממנו."},{"i":43755,"n":"קרול, אהרן מלודז","f":"אריה ליב קרול","b":"דיין בלודז"},{"i":43756,"n":"קרול, אריה ליב מלודז","b":"דיין בלודז"},{"i":43757,"n":"קרול, מרדכי מבאסאן","f":"אברהם מתתיהו","k":"בעל האמת והשלום","bt":"תרמ","b":"נכד ר יעקב קוליא מניעזין-יד ימינו של האדמור ר ישראל נח שניאורסון. רב בבסן חדש(=באסאן)-פלך צרניגוב-תרסח. נסמך מאת: ר רפאל שפירא מוולוזין, ר דוער קראסיק בעל \"פתחי עולם\", ר צבי מהומל."},{"i":43758,"n":"קרול, מרדכי ניסן מלודז","f":"אהרן","dt":"תשג","b":"דיין בלודז-תרעח."},{"i":43759,"n":"קרול, מרדכי שמואל","r":"רב דכפר חסידים","bt":"תרס","dt":"ערב שבועות תשה","b":"מרביץ תורה,רב בזוראוויץ,נובוגרודסיברסקי,כפר חסידים-תרצ\"ב","bk":[["משא דמשק",""]]},{"i":43760,"n":"קרול, שלום מאונסדורף","b":"מחכמי אונסדורף-תקלא."},{"i":43761,"n":"קרומינו, דוד","f":"ליב","b":"רב-שנת תק\"כ"},{"i":43762,"n":"קרומנוי, ליב","dt":"שצ - ד אב","b":"דיין בפרג"},{"i":43763,"n":"קרומר, שלמה יהושע זלמן פלק","f":"אהרן דב","bt":"תרלב","dt":"תשח","b":"תלמיד קיבוץ ואראדאווא, נווהארדוק, וילנא. נסמך מאת: ר רפאל שפירא מוולוזין, ר שלמה הכהן מוילנא, ר יחיאל מיכל אפשטין בעל \"ערוך השלחן\", ר מאיר נח לוין מוילנא, ר אליעזר רבינוביץ ממינסק. רב בקניזיץ-פלך מוהילוב-תרנח, בעלינטש-פלך מוהילוב-תרס, עלה לארץ-תרצב, חבר רבנות ברחובות."},{"i":43764,"n":"קרון, אהרן","f":"דב","bt":"1882","bp":"קובנא","dt":"1951","dp":"ראשון לציון","b":"תלמיד ישיבת סלובודקה, טלז. מנהל החדר המתוקן בגרודנא שהיה גם בית ספר לדוגמא בשביל הקורסים הפדגוגים בגרודנא. מפקח בתי הספר של ייק\"א-1911. עלה לארץ והיה מנהל בית ספר בראשון לציון."},{"i":43765,"n":"קרון, חיים זלמן מזיימל ופוקרוי","dt":"תשג","b":"רב בזיימל, פוקרוי, רבה האחרון של פיקאלן. נספה בשואה."},{"i":43766,"n":"קרון-קראהן, יהושע מבורשטשוב","b":"מחכמי סקאלא, בורשטשוב-תרסג, אראצוב. פניה ממנו לעזרה לאחר שנאסר בגלל עלילה."},{"i":43767,"n":"קרונזניק, אלתר חיים מסוכא","b":"רב בסוכא-תרסח."},{"i":43768,"n":"קרוננברג, ירחמיאל ישראל יצחק","b":"הגיע מלודז. תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":43769,"n":"קרוננברג, נטע מבילגוריי","b":"מדפיס בבילגוריי. הדפיס \"הפרדס\" - תרצא."},{"i":43770,"n":"קרונר, יהושע טרייטיל משטוטגרד","f":"אברהם יעקב מדירנפורט","bt":"תרה","bp":"דדירנפורט","b":"תלמיד ביהמ\"ד לרבנים בברסלוי, בעל תואר ד\"ר. רב במינסטר-תרכט, רב בלנגספעלד ומדינת זאקזען(=סכסוניה), ערפורט, שטוטגרט-תרע. חיבר \"ויכוחים נגד פרופ' ראהלינג\", מאמר על ר אברהם בדרשי, ועוד."},{"i":43771,"n":"קרוסנר, אברהם יהושע מארה\"ב","f":"מאיר","bp":"מינסק","b":"היגר לארה\"ב והתישב בברונסויל-ניו יורק. חתנו - ר מרדכי ליכטנשטין. אחיו - ר פנחס יצחק קרוסנר."},{"i":43772,"n":"קרוסנר, צבי","b":"פרסם מאמרים ב\"אור המאיר\" - נ\"י תשח."},{"i":43773,"n":"קרופמן, מאיר יהושע מיוריעוו","k":"בעל עמודי עולם","bt":"תר","b":"רב ביורייב(=יוריעוו, דערפאט)-פלך ליפלנד-תרלב. נסמך מאת: ר אליהו שיק. חיבר גם: \"חושב מחשבות\", \"חרש וחושב\"."},{"i":43774,"n":"קרופני, לוי","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":43775,"n":"קרופניא, נחמן יוסף מהראזאווע","f":"אברהם","bt":"תרלח","b":"רב בלביקאווא-פלך סובאלק-תרסג, יאנובה-פלך גרודנא-תרסד, הארא-זאווע(=הראזאווע)-פלך מינסק-תרסח."},{"i":43776,"n":"קרוק, זונדל משירווינט","bt":"תרע","dt":"תשא","b":"חתן ר אברהם אריה גרוסברד משירווינט. רבה האחרון של שירווינט לצד חותנו. נספה בשואה."},{"i":43777,"n":"קרושיק, ליפמן הירש","dt":"תשג","b":"רב בניישטט"},{"i":43778,"n":"קרטב, אברהם הפייטן","b":"פייטן-שנות ה-ק', חיבר תחינה לתענית אסתר, פתיחה לשופרות, ועוד."},{"i":43779,"n":"קרטופל, שמואל זנויל מיקטרינסלב","k":"בעל בית שמואל","b":"רב ביקטרינסלב. מחותן עם ר אברהם זאב צייטלין מטשקנט."},{"i":43780,"n":"קרטינגר, דוד משרווינט","b":"מגיד בשרווינט"},{"i":43781,"n":"קרטש, משה מאייזנשטט","f":"פנחס","bt":"תרכב","b":"נכד החת\"ס. תלמיד ר שמואל ארנפלד. מו\"צ באייזנשטט-תרנד. נסמך מאת: ר שלום קוטנא מאיזנשטט, ר נתן מילר מטשין, ר דוד ביכלא מפאסטא-חתנו של ר יהודה אסאד. (עליו בחדש בחדשו תשנט עמ' פג)."},{"i":43782,"n":"קרטשמרובסקי, בן ציון מסימפרפול","b":"אב\"ד סימפעראפל(=סימפרפול)-תרסא. הסכמה ממנו ל\"פרחי חמד\" מאת ר מתתיהו לוין."},{"i":43783,"n":"קריב אברהם","bt":"1900","dt":"ה'תשלו 1976","bk":[["שבת ומועד בדרוש ובחסידות",""]]},{"i":43784,"n":"קריב, אברהם יצחק","f":"יעקב","k":"בעל עיונים - תשי","bt":"1900","bp":"סלובודקה","b":"תלמיד ישיבת קובנא, טלז, מיר. תלמיד ביהמ\"ד למורים באודסה. חבר \"החלוץ\". עלה לארץ-1934 והיה עורך ב\"דבר\", מאזניים\". חיבר גם \"שבת ומועד בדרוש ובחסידות\", ועוד."},{"i":43785,"n":"קריבושייב, דוד","f":"מנחם","bt":"1905","bp":"ראדוולישוק","dt":"1945","dp":"סטלינסק-סיביר","b":"פעיל ציוני סוציאליסטי, ומנהל \"דאס ווארט\". ביקר בארץ-1939 וחזר לליטא. ניהל את העליה הבלתי ליגלית-1940 וסייע לעליית מאות חלוצים מפולין ומליטא, על פעילות זו נאסר וגלה לסיביר שם נפטר."},{"i":43786,"n":"קריגר, אלכסנדר סנדר","f":"יצחק יחיאל מבלז","b":"חסיד בלז (אביו הביא את השר שלום לבלז וחתם על כתב המנוי). מחכמי ברודי, עבר לאודסה לפרנסתו."},{"i":43787,"n":"קריגר, אשר צבי הירש מאודסה","f":"אלכסנדר סנדר מאודסה","bt":"תרלב","dt":"תשטז","dp":"תל אביב","b":"חסיד בלז. חתן שרה שינדל ממשפחת כהנא-שפירא מזגירז בקראקא (משפחה מחסידי גור - והשפת אמת העיר לו על הכנסת המכנסים לגרבים). עבר לקראקא, אנטורפן ועסק ביהלומים. ניצל מהשואה. עלה לארץ-תשח (בעקבות רבו האדמור מבלז)."},{"i":43788,"n":"קריגר, ברוך מקסטפול","dt":"תשג","b":"רב בקסטפול"},{"i":43789,"n":"קריגר, חיים זאב מספיזישוק","f":"אהרן","bt":"תריח","bp":"לינקובה","dt":"תרצג - כג אב","b":"תלמיד ישיבת איישישוק. רב בסאפיזשוק(=ספיזישוק) (ביהדות ליטא - תאריך פטירתו - תרסג או תרעג). בניו: ר ישראל אבא מקושידאר ובוסטון, ד\"ר משה קריגר - רופא ועסקן ציבור."},{"i":43790,"n":"קריגר, חיים צבי מזולקוא","f":"יצחק יחיאל מזולקוא","bt":"תרסג","bp":"זולקוא","dt":"תשמג","dp":"ניו יורק","b":"חסיד בלז. חתן הנגיד ר יהושע אלעזר דורנבוש מפשמישל. רב בפשמישל, בריסל. ניצל מהשואה והגיע לארה\"ב-תרצט. היה מעורב בהצלת כ-30,000 יהודים. ר\"מ בישיבת \"חתן סופר\" ומראשי ועד הרבנים באמריקה."},{"i":43791,"n":"קריגר, יוסף משאוולאן","dt":"תרסב - ט אדר","b":"רב בשאוולאן-תרל\"ח"},{"i":43792,"n":"קריגר, יצחק יחיאל מזולקוא","f":"משלם","dt":"תשג","b":"נכד ה\"תבואת שור\" ו\"מעשה רוקח\". תלמיד ר יצחק שמלקיס בעל \"בית יצחק\". רב בזולקוא. נספה בשואה."},{"i":43793,"n":"קריגר, יצחק צבי מחווידאן-ליטא","bt":"תרי","dt":"תרנז","b":"רב בחווידאן(=קונסטנטינובה) כ-4 שנים, עבר לשיקגו."},{"i":43794,"n":"קריגר, ישראל אברהם אבא","f":"חיים זאב וולף","k":"בעל חינא דחיי","dt":"תרצא - יט טבת","b":"רב בקושידור, קורשן, בוסטון."},{"i":43795,"n":"קריגר, מרדכי משאוולאן","dt":"תרסז","b":"רב בשאוולאן."},{"i":43796,"n":"קריגר, משה","f":"חיים זאב","bt":"1885","bp":"סאפיזישוק","b":"למד רפואה בברלין ופאריס. עלה לארץ-1912. התנדב לצבא התורכי בזמן מלחמת הבלקן ושירת בקושטא. רופא בזכרון יעקב ובחדרה. רופא צבאי בצבא התורכי במלחה\"ע ה-I. מנהל בי\"ח הדסה בצפת. פרסם מאמרים בנושאים רפואיים. יו\"ר ההסתדרות הרפואית-1930."},{"i":43797,"n":"קריגר, שמואל מקאווארסק","f":"אברהם אבא","bt":"תרלב","b":"מצאצאי ר ליב מפאקרויא. תלמיד הכולל בקובנא. רב בקווארסק-פלך קובנא-תרסג. פרסם מאמרים ב\"מאסף דרושי\" לר חיים סגלוביץ - וילנא תרסט."},{"i":43798,"n":"קרידו, יעקב מאזמיר","b":"חתנו של הרב חזן בעל \"עין יוסף\" - שהזכיר בספרו את שחיבר פירוש לתנ\"ך."},{"i":43799,"n":"קריון די, שם טוב מתורכיה","b":"מחכמי תורכיה בזמן ר יוסף טאיטצק - שדן בענינו."},{"i":43800,"n":"קריזוירט, אברהם יוסף ממגנישוב","f":"יעקב שרמן","k":"בעל בית אברהם","bp":"מגנישוב","b":"עבר מפולין לגליציה מפחד הגיוס והתישב בוואיניטש. חתן הגביר ר אהרן קרייזווירט וקיבל את שמו. רב בוואיניטש. רוב כתביו אבדו בשואה. חיבר \"בית אברהם\" תרסט. נספה בשואה. בנו ר חיים היה רב באנטורפן. ?? לא באוצר ??"},{"i":43801,"n":"קריזוירט, אהרן מוואיניטש","b":"גברי חסיד בוואיניטש. חתנו היה ר אברהם יוסף קריזוירט."},{"i":43802,"n":"קריזוירט, חיים מאנטורפן","f":"אברהם יוסף ממגנישוב","k":"העילוי מקראקא","bt":"תרף","bp":"וויניטש","dt":"תשסב","b":"ראש ישיבת טשחויב בקראקא. תלמיד יח\"ל. ניצל מהשואה. חתן ר אברהם גרודזנסקי - משגיח בישיבת סלובודקה. עלה לארץ-תשא, ראש ישיבת סקוקי בשיקגו-תשז, אב\"ד אנטורפן-תשכג. פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה, \"כנסת ישראל\" - סלובודקה - ירושלים תשא, \"תבונה\" - ירושלים תשא-תשח."},{"i":43803,"n":"קריזימלה, מנדלי מפריסטיק","b":"מחכמי פריסטיק - תשובה אליו \"שואל ומשיב\"."},{"i":43804,"n":"קריזל, אברהם מקוסוב","f":"יוסף מקוסוב","bt":"תרמה","bp":"קוסוב","dt":"תשג","b":"מחכמי קוסוב, ממנהיגי המזרחי בעירו, הקים חדר מתוקן. חביר \"ספר התקנות של המנין המזרחי בקוסוב\" בילגוריא תרצב. פרסם מאמרים בעתונים. נספה בשואה. בתו שלומיה - נספתה בשואה. חיברה \"שמש ועבים\" והביא לדפוס אחיה יצחק סדומי - ישראל תשלה ."},{"i":43805,"n":"קריזר, אהרן מקובל","b":"מתורתו ב\"תורה אור\" - שנחאי תשו."},{"i":43806,"n":"קריזר, דוד דוב מקלצק","bt":"תרנא","dt":"תרצא","b":"רב פעלים,ר\"מ בקלצק"},{"i":43807,"n":"קריטנר, חיים מזברז","b":"מחכמי זברז'. אחיינו של ר אברהם מסטרטין. חתן ר שמואל זנויל (הראשון) ברנדויין מסטרטין."},{"i":43808,"n":"קריטשטין, משה מניישטט","b":"רב בניישטט-תרמח."},{"i":43809,"n":"קריטשטין, שמואל ברוך מרישא","b":"פרסם מאמרים ב\"מציון תצא תורה\" - זאמושט תרפט."},{"i":43810,"n":"קרייאר, ישראל זאב מוילנא","k":"בעל וועלט מיט וועלטע","bt":"1860","bp":"סטוקלישוק","dt":"1917","b":"תלמיד ישיבת מייליס בוילנא. מנהל ת\"ת בוילנא. חיבר ספרי מדע פופולריים, ספר דקדוק עברי, ועוד."},{"i":43811,"n":"קריינדל, יהודה ליב מקריטשוב","f":"יוסף","bt":"תריד","b":"חסיד חב\"ד. חתן ר חיים נחום לאקשין מקלימוביץ. ראש ישיבה בקלימוביץ, ראש ישיבה ורב קהלת החסידים בקריטשוב-פלך מוהילוב-תרן. (באותה השנה נרשם כרב גם ר חיים יהודה קאהן). ברח מרוסיה לאחר ההפיכה והשאיר אחריו את רוב כתביו. חתנו ותלמידו - הגרי\"א הנקין. תשובה ממנו ב'לב איברא', מתורתו בספרי חתנו."},{"i":43812,"n":"קריינס, מנחם נחום פדזלבה","f":"מרדכי אריה מסמרגון","bt":"תריז","bp":"סמרגון","b":"נכד ר משה שלמה זלמן מדוקשיץ. תלמיד ישיבת וולוזין, איישישוק, קובנא. רב בקרונשטט-תרמח נאלץ לעזוב-תרנה ועבר להתגורר בוולוזין, רב בפדזלבה-פלך קובנא-תרנח. נסמך מאת: ר יצחק אלחנן מקובנא, ר מרדכי מלצר. הניח חדושים בדרוש והלכה."},{"i":43813,"n":"קריינס, מרדכי אריה ליב","f":"משה שלמה זלמן","b":"רב-שנת תר\"מ"},{"i":43814,"n":"קריינס, משה מוילנא","f":"נחמן נישויזער","k":"בעל אהל משה","bt":"תרג","dt":"תרנה","b":"נתייתם בילדותו וגדל אצל זקנו ר דוד קריינס מסלוצק. חתן נכדת ר דוד ממיר ממשפחת שחור. התישב בוילנא ונתמך בידי מהר\"מ שטרשון. מו\"צ בוילנא-תרמה. חיבר גם \"נחל משה\"."},{"i":43815,"n":"קריינר, אליעזר מאמדור","b":"פרסם מאמרים ב\"תורה מציון\" - ירושלים תרנה-תרסה."},{"i":43816,"n":"קריל, דוד יהודה מדוקלא","b":"מחכמי דוקלא-תרפט. פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח."},{"i":43817,"n":"קרילסהיים, ליב","b":"אין פרטים."},{"i":43818,"n":"קרילסהיים, משה מפרשבורג","b":"מראשי קהלת פרשבורג-תקמג."},{"i":43819,"n":"קרים, משה אליעזר מסטויאנוב","b":"מחכמי סטוניאוב - תשובה אליו - מהרש\"ם."},{"i":43820,"n":"קרימי, אברהם מקרים","k":"בעל שפת אמת","b":"רב בקרים-קכ. היה במחלוקת עם הקראים יחד עם חתנו ר אליקים עד שהקראים נכנעו בפניו ובאו ללמוד ממנו. חיבר ספר לבקשת תלמידו הקראי - חזקיה בן אלחנן הלוי. נזכר במחזור מנהג קרים - שהזכירו נשמתו בחגים. מתורתו אצל ר שמריה מאי קריטי - שאולי היה תלמידו."},{"i":43821,"n":"קרימישין, דוד משלוניקי","b":"מחכמי שלוניקי, תלמיד בישיבת נתן העזתי בשלוניקי-תלז - אחרי המרתו של ש\"ץ."},{"i":43822,"n":"קרימס, מרדכי","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":43823,"n":"קרימר, דב ברל מטשרנוליצה","b":"מחכמי טשרנוליצה - ממשתתפי \"אסיפת חכמים\"-תרעב."},{"i":43824,"n":"קריניצי, אברהם","f":"יעקב","bt":"1886","bp":"גרודנא","b":"הצטרף לפועלי ציון. פעיל בהגנה היהודית בזמן הפרעות. עלה לארץ והתישב ברחובות, ראשון לציון. גורש למצרים וארגן שם קבוצה של פועלי ציון. יסד ביח\"ר ביפו. ממיסדי שכונת נחלת בנימין בתל אביב. היה בצבא התורכי בזמן מלחמ\"ה ה-I וסייע למגורשי תל אביב. ראש עירית רמת גן."},{"i":43825,"n":"קריניצקי, ישראל מאיר","b":"רב בלאנדוועראווע"},{"i":43826,"n":"קרינסקי, חיים מוילנא נאואהרדאק","f":"אליהו","k":"בעל גזע ישישים","bp":"הורדנא","dt":"תריא - כג ניסן","dp":"וילנא","b":"נקרא ע\"ש ר חיים מוולוזין. אחיינו של ר הלל מגרודנא-חתן ר חיים מוולוזין, בזיוו\"ש חתן משפחת אינהורן מהורדנא, ובזיוו\"ש חתן ר מרדכי בן ישכר בער-אחי הגר\"אן, ובזיוו\"ר חתן ר אהרן נתנזון משוינצאן. תלמיד ר דוד מנוורדוק בעל \"גליא מסכת\". גביר מחכמי וילנא. חיבר הספד על רבו ונדפס בתוך \"גליא מסכת\", בשם \"גזע ישישים\", ונדפס ע\"י נכדו ר צמח גם בפני עצמו, חיבר גם \"הוי אריאל\". (באוצר הספרים לבן יעקב נרשם שם המחבר בטעות ר צמח - נכדו שהוא המו\"ל)."},{"i":43827,"n":"קרינסקי, יהודה ליב ממינסק","k":"בעל מחוקקי יהודה"},{"i":43828,"n":"קרינסקי, יעקב מגנוס","f":"יוסף בנימין","k":"בעל ראשית דעת","bt":"1863","bp":"רוז'נוי","dt":"1916","b":"תלמיד ישיבות ליטא, ורכש השכלה כללית. יסד בי\"ס בלודז', עבר לוארשא-1903. חיבר ספרי לימוד רבים, עורך עתונים לנוער ובהם \"השחר\", ו\"בן שחר\". הו\"ל את כתבי \"שלום עליכם\", ועוד. מיסד ומנהל הגימנסיה היהודית הראשונה בוארשא - ברוסית."},{"i":43829,"n":"קריס, אברהם אבא מארה\"ב","f":"בן ציון","k":"בעל ספר הגלגולים","bt":"1893","bp":"פיקאלן","b":"תלמיד ישיבות ליטא. היגר לארה\"ב ולמד בישיבת ר יצחק אלחנן, תרגם לאידיש ולאנגלית יצירות שונות ובהם ספורי מעשיות לר נחמן מברסלב. חיבר שירים וסיפורים. חיבר \"ספר הגלגולים\" בעד הציונות ונגד הבונדאים והסוציאליסטים, גם \"הפילוסופיה של ימי הבינים\"."},{"i":43830,"n":"קריס, צבי הירש מזורובנה","b":"רב בזורובנה, יאסי-תרלו. נכד ר איציקל מאה\"ו."},{"i":43831,"n":"קריסהאבער, אברהם דב מפעשטרזשעב","b":"אב\"ד פעשטערזשעבעט-תרפט."},{"i":43832,"n":"קריסטל","k":"ראה: קרישטל","b":"רב בזויערץ. פרסם מאמרים ב\"בית שמואל\" לתלמידי ישיבת \"בית ישראל\" באלכסנדר - לודז'-פיעטרקוב תרצא."},{"i":43833,"n":"קריסלוב, יצחק מקליבלנד","b":"רב בקליבלנד. פרסם מאמר ב\"אוהל יוסף\" נ\"י תשו, \"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":43834,"n":"קריסנפולר, אלכסנדר מברוד","f":"נחום","k":"בעל חלום ופתרון","bt":"תרמד","dt":"תש..","b":"חתן ר יעקב קופל ביגלאייזן. רב בלינץ (אוסטריה) ומרצה בבימ\"ד (המכון התאולוגוי היהודי) בוינה. עסק עם רמח\"א בלוך בעריכת אוצר ההקדמות לספרים - אבד בשואה. חיבר \"חלום ופתרון חלומות בתלמוד\" תרצב, נספה בשואה. ?? לא באוצר ??"},{"i":43835,"n":"קריסנפולר, יחיאל מיכל בן ציון","f":"מאיר מברודי","k":"בעל אבל כבד","bt":"[תקנג]","bp":"ברודי","dt":"תרכג - ט סיון","b":"גדל ביתמותו אצל גיסו ר משה אפרים אשכנזי אב\"ד קליש. חתן ר אהרן פדווא מבריסק בעל \"מנחת אהרן\". מתנגד, עשיר, רב בברודי-תרו על מקום אביו (והיה מחלוקת בקהלה מצד אלא שראו בו משכיל - וביניהם המהרש\"ק - אולם היה מקובל בעירו), בנו ר מאיר על מקומו אחריו. חיבר \"אבל כבד\" זולקוא תקצה."},{"i":43836,"n":"קריסנפולר, מאיר מברוד","f":"יחיאל מיכל בן ציון","bt":"תקעו","dt":"תרמו","b":"רב בברודי-תרכג על מקום אביו. חתן ר ברוך בנדט בעל \"נר תמיד\"."},{"i":43837,"n":"קריסנפולר, מאיר מקריסנפולי","f":"צבי הירש מבילקמין","k":"בעל יד המאיר","bt":"תק","dt":"תקעה - טז ניסן","b":"אביו הוא מחבר \"מאורות צבי\" והיה רב גם בלבוב. תלמיד ר שמואל שמלקא הורביץ מניקלשבורג. רב בבילקמין על מקום אביו, גלינה, קריסנפולי (ליד בלז), ברודי, בנו ר יחיאל מיכל על מקומו אחריו. חתן הגביר ר אברהם ר שכניש, ובזיוו\"ש חתן הגביר ר זלמן פרלס (אבי משפחת ברז\"פ). חתנו היה ר משה אפרים אשכנזי מקליש. חיבר \"יד המאיר\" ורשא תרלד. הסכים על ספר יראים, \"גאון צבי\"."},{"i":43838,"n":"קריסנפולר, צבי הירש מבילקמין","f":"ראה: ויסשטין, צבי הי"},{"i":43839,"n":"קריספין, אברהם גמליאל מזאגרה","f":"עמרם חיים משה","b":"רב בזאגרה הישנה על מקום דודו ר דוד, ובנו ר משה על מקומו אחריו, עוד מבניו - ר חיים יוסף מזאגרה, ר חיים על מקום אחיו."},{"i":43840,"n":"קריספין, אברהם משלוניקי","dt":"שטו - ו אב","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":43841,"n":"קריספין, אהרן מאזמיר","f":"יהושע אברהם מאזמיר","k":"בעל בית אהרן","b":"מחכמי איזמיר, חיבר \"בית אהרן\". ערך יחד עם אחיו ר יום טוב את ספר אחיהם ר שמואל - \"משק ביתי\""},{"i":43842,"n":"קריספין, אליהו מרדכי","b":"חיבר ספר זכרונות על משפחתו."},{"i":43843,"n":"קריספין, אליעזר משה מרוסג'וק","b":"משכיל מחכמי רוסג'וק, עבר לטורנו-סיבירין-רומניה-תרמז, הו\"ל שבועון בלאדינו (אות לטינית)."},{"i":43844,"n":"קריספין, אשטרוק מספרד","b":"מחכמי ספרד-ן' רב בטרגואנה, נאלץ לברוח בגלל עלילה. נזכר ב\"אבן בוחן\" לר קלונימוס - כאחד מהחכמים שלכבודים חיבר את ספרו."},{"i":43845,"n":"קריספין, גבריאל משה מזאגרה","f":"משה","b":"רב בזאגרה, דיינים אצלו - ר אברהם חובש, ר יצחק אסא. ישב בדין-תקפה עם ר אליקים בן יעקב אברהם גירון בהיותו בזאגרה."},{"i":43846,"n":"קריספין, גמליאל מאזמיר ואדרינו","dp":"אדרינופול","b":"מחכמי אזמיר, עבר לאדרינופול. בניו - ר דוד מזאגרה, ר עמרם חיים משה מאדרינופול."},{"i":43847,"n":"קריספין, דוד מזאגרה","f":"גמליאל מאזמיר","b":"רב באיסקי-זאגרה (=זאגרה הישנה)-תקס בערך, ואחיינו ר משה (רבנו) קריספין על מקומו אחריו. החזיק בכתב היד \"חסדי דוד\" לר יעקב מאג'ר והשליח ר יעקב שאלתיאל ניניו העתיקו והדפיסו."},{"i":43848,"n":"קריספין, חייא שלום יהודה","dt":"תכ","dp":"צפת","b":"מחכמי צפת, בשנת שצז חתם על מכתב חכמי צפת לקהילת מנטובה, חתום על הסכמה לספר \"חוט המשולש\""},{"i":43849,"n":"קריספין, חיים יוסף מזאגרה","f":"אברהם גמליאל","b":"שליח צבור בזאגרה, רב בזאגרה על מקום אחיו ר משה. בניו - ר רפאל מיאמבול, ר אברהם, ר שלום, ר יהושע מקיזנליק, ר יצחק, ר שמואל, ר אליהו, ר מרדכי."},{"i":43850,"n":"קריספין, חיים משה","f":"גבריאל","k":"בעל מילון ספרדי-עברי","bt":"תרכט","bp":"סטארה זאגורה","b":"למד בג'ירפאן, קושטא, פעיל ציוני. ש\"ץ ומורה לעברית בחסקובו, אדרינופול-תרע, מ\"מ האב\"ד ברוסג'וק-תרעה, עלה לארץ-תרפד והתישב בתל אביב והיה ש\"ץ בביהכ\"נ \"שלום\" לעולי בולגריה. חיבר מילון ספרדי-עברי."},{"i":43851,"n":"קריספין, חסדאי משלוניקי","dt":"תקא","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":43852,"n":"קריספין, יהודה מדמשק","b":"מראשי קהלת דמשק-שנות ה-ת'."},{"i":43853,"n":"קריספין, יהודה מצפת","b":"נשא ונתן עם בעל \"דבר שמואל\" והובא בספר."},{"i":43854,"n":"קריספין, יהושע אברהם מאזמיר","k":"בעל אברהם במחזה","dt":"תרטו - טו תמוז","b":"דיין באזמיר אצל ר חיים פלאג'י. חתנו - ר חיים בנימין פונטרימולי בעל \"פתח הדביר\", בניו - ר יום טוב, ר שמואל, ר יצחק.","bk":[["אברהם במחזה",""],["וישב אברהם",""]]},{"i":43855,"n":"קריספין, יהושע מקיזאנליק","f":"חיים יוסף מזאגרה","b":"רב בקיזאנליק."},{"i":43856,"n":"קריספין, יהושע משה מרדכי","f":"יוסף בן משה מאזמיר","k":"בעל מים קדושים","bt":"תרלו","bp":"אזמיר","dp":"אזמיר","b":"מחכמי אזמיר, ביקר בארץ-תרצד.","bk":[["מים קדושים","שו\"ת חו\"מ-דרשות"]]},{"i":43857,"n":"קריספין, יהושע משה משלוניקי","b":"מחכמי שלוניקי. הגיה \"מאמר מרדכי\" לר מרדכי קריספין-תקפח."},{"i":43858,"n":"קריספין, יום טוב מירושלים","f":"יהושע אברהם מאזמיר","k":"בעל בגדי יום טוב","dt":"תרסט - יב אלול","b":"מחכמי ירושלים"},{"i":43859,"n":"קריספין, יום טוב מפאס ומרוקו","bp":"מרוקו","b":"מחכמי פאס, עלה לירושלים, בשנת תעח שליח ירושלים במרוקו, ובשנת תפז בשליחות חברון באיטליה יחד עם ר אברהם גדליה. לפי אוצר הרבנים רב באוטאט-תעח."},{"i":43860,"n":"קריספין, יצחק","b":"תשובות ממנו ב\"כתונת יוסף\"."},{"i":43861,"n":"קריספין, יצחק מאזמיר - א","f":"מנחם מרדכי","k":"בעל זהרי חמה","dt":"תקיא - ב אלול","dp":"ירושלים","b":"תלמיד ר יצחק ן שאנג'י בשלוניקי, וחיבר הקדמה לספרו \"באר יצחק\"-תצה. מחכמי אזמיר, שלוניקי, עלה לירושלים וכיהן כדיין. הו\"ל \"זהרי חמה\" - לקוטים מהזהר. בנו - ר יהושע משה הו\"ל ספר זקנו \"מאמר מרדכי\"."},{"i":43862,"n":"קריספין, יצחק מאזמיר - ב","f":"יהושע אברהם מאזמיר","k":"בעל שמו יצחק","b":"רב באזמיר-תרל."},{"i":43863,"n":"קריספין, יצחק מספרד","f":"שמואל","k":"בעל ספר המוסר","b":"משורר ומתרגם מחכמי ספרד במאה ה-יב. חיבר \"משלי ערב\" ונקרא גם \"משלי אנשים חכמים\" וספר המוסר, רוב הספר ממקור ערבי שתורגם וחלקו ממנו. מוזכר אצל אלחריזי ב\"תחכמוני\"."},{"i":43864,"n":"קריספין, יצחק משלוניקי","b":"מחכמי שלוניקי-שן."},{"i":43865,"n":"קריספין, ישראל יהודה מראשיד","b":"רב בראשיד-שנות ה-ת'-תק'. נזכר ב\"גינת ורדים\"."},{"i":43866,"n":"קריספין, מנחם משלוניקי","dt":"תצח - לפני","dp":"שלוניקי","b":"מחכמי שלוניקי. חיבר ליקוטים מהזהר, ומדרש על חמש מגילות ובסופו סדר הלמוד לסעודת פורים לפי \"חמדת ימים\". מגיה בדפוס שלוניקי."},{"i":43867,"n":"קריספין, מרדכי","b":"רב, מורה ועורך עתון"},{"i":43868,"n":"קריספין, מרדכי משלוניקי","f":"יצחק","k":"בעל מאמר מרדכי","bt":"תצ","bp":"שלוניקי","b":"עבר לרודוס וכיהן שם כרב והעמיד תלמידים. חתן ר משה ישראל מרודוס. נזכר ב\"קול אליהו\". חיבר גם \"דברי מרדכי\". בנו - ר משה."},{"i":43869,"n":"קריספין, משה","b":"חתן ר משה ישראל מרודוס."},{"i":43870,"n":"קריספין, משה מזאגרה","f":"אברהם גמליאל","dt":"תקעה - בערך","b":"רב בזאגרה על מקום אביו, ואחיו ר חיים על מקומו אחריו. נפטר צעיר."},{"i":43871,"n":"קריספין, עמרם חיים משה מאדרינו","f":"גמליאל","dt":"תקעד","dp":"יאמבול","b":"אב\"ד באדרינופול בישיבת הרבנים לבית גירון, עבר ליאמבול. אחיו - ר דוד מזאגרה. בנו ר אברהם גמליאל בכור רב בזאגרה על מקום דודו ר דוד."},{"i":43872,"n":"קריספין, עמרם חיים משה מזאגרה"},{"i":43873,"n":"קריספין, רפאל מיאמבול","f":"חיים יוסף מזאגרה","b":"רב ביאמבול."},{"i":43874,"n":"קריספין, שמואל מאזמיר","f":"יהושע אברהם מאזמיר","k":"בעל משק ביתי","b":"רב באזמיר."},{"i":43875,"n":"קריצלר, אברהם יונתן יהודה ליב","dt":"תרסב - ד ניסן","b":"מקובל מחכמי בניהאד. חתן הצדיק ר שמואל הלוי אוסטרליץ מטאב. גיסו של ר אברהם פופר מטאב. חתנו - ר אברהם בן משה פולק מבאניהאד ומחותנו ר משה הזכירו בספרו \"וידבר משה\"."},{"i":43876,"n":"קריקב, ידי\"ן","b":"מחכמי פאס-תקע\"ז"},{"i":43877,"n":"קריקשטונסקי, ראובן","b":"פרסם מאמרים ב\"כנסת ישראל\" - סלובודקה-ויליאמפולי תרצח - כתב עת תלמידי \"כנסת ישראל\" בסלובודקה."},{"i":43878,"n":"קריש ן, יהודה מאלגיר - ריב\"ק","f":"יצחק","k":"בעל ספר פתרונים","bt":"ד'תרי","dt":"ד'תרף","b":"רב בלשן ורופא בתאהרת-אלגיר (ליד תייארת מחוז ווהראן). פגש את אלדד הדני ורשם מתורתו. חיבר ספר דקדוק, פתרונים, מילון, פירוש לדברי הימים, אגרת ליהודי פאס אודות לימוד ארמית - נדפס בשם \"רסאלה\" פאריס תריז. נזכר בפירוש רש\"י לתהילים, ואצל ר מנחם בן סרוק, ור שלמה פרחון. (כנראה הרב הראשון הידוע מאלגיר). יש הסבורים כי היה קראי."},{"i":43879,"n":"קרישטל, דוד הכהן מזורומין","b":"רב בזורומין. פרסם הספד לבן האדמור מאלכסנדר ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":43880,"n":"קרישטל, חיים מאיר מסקירנוביק","k":"בעל חקר דבר","b":"רב בסקרינוביק, ארה\"ב. חיבר \"חקר דבר\" מונטריאול תשך."},{"i":43881,"n":"קרישטל, נתנאל","b":"תלמיד ישיבת \"בית ישראל\" באלכסנדר. פרסם מאמרים ב\"נהור שרגא\" - אלכסנדר תרצט."},{"i":43882,"n":"קרישק, אברהם בנימין מעיר חדש","b":"פרסם מאמרים ב\"אהל תורה\" - קראקא תרפח, \"בית אברהם\" - וארשא תרצד."},{"i":43883,"n":"קרישר, זאב מפיוונישא","f":"אברהם","bt":"תריט","b":"תלמיד ר שאול שנדורף מטשירטש, ר מרדכי פעסיל מגורליץ, ר נתן נטע בעל \"עורה שחר\", ר בנימין זאב מזמיגרד. חתן ר יעקב יצחק מזידיטשוב בן ר נפתלי מליזנסק. מחסידי הדברי חיים ונסמך ממנו. רב בפיוונישא (ליד צאנז)-תרנג. חתן ר יעקב יצחק ויסבלום מזידיטשוב."},{"i":43884,"n":"קרלבורג, יהודה ליב מבון","k":"בעל שלש יבבות","bt":"תקכה","dt":"תקצה","b":"תלמיד ר נתן אדלר, וחברם של החת\"ס, ור אברהם בון. מגדולי הלוחמים בריפורמים, רב ראשי בווסטפאליע-תקע\"ז, רב בבון, קרעפעלד. מתלמידיו ר צבי אוירבך בעל \"נחל אשכול\", ואחיו ר אהרן מבון."},{"i":43885,"n":"קרלגיק, אברהם מארה\"ב","f":"דוד","bp":"אומאן","b":"סופר בניו יורק."},{"i":43886,"n":"קרליבך אליהו חיים","bt":"1925","dt":"ה'תשנ 1990","bk":[["יד מאור ושמש",""]]},{"i":43887,"n":"קרליבך, אפרים","f":"שלמה קרליבך","bt":"תרמ","dt":"תרצז","b":"רב בלייפציג-תר\"ס-תרצ\"ז,עלה לא\"י-תרצ\"ז"},{"i":43888,"n":"קרליבך, דוד","f":"שלמה קרליבך","b":"רב בקלן,עלה לא\"י-תרצ\"ז"},{"i":43889,"n":"קרליבך, יוסף צבי","f":"שלמה קרליבך","bt":"תרמג","dt":"תשב","b":"מחנך,רב פעלים,רב בלובק-תר\"פ,אלטונה-תרפ\"ו,המבורג-תרצ\"ו"},{"i":43890,"n":"קרליבך, מנחם","f":"שלמה קרליבך","b":"רב בקאלן-תר\"פ"},{"i":43891,"n":"קרליבך, נפתלי מברלין וארה\"ב","f":"שלמה מליבק-בית יוסף","bt":"תרנב","bp":"ליבק-גרמניה","b":"תלמיד ביהמ\"ד לרבנים בברלין, וגם בישיבות ליטא. נסמך מאת ר אהרן באקשט משאוועל. חתן ר אשר מיכל הכהן מבזל. רב בברלין-תרעז, באדן-ויען(=וינה), היגר לארה\"ב-תרצה וכיהן כרב בניו יורק. חבר אגודת הרבנים באמריקה."},{"i":43892,"n":"קרליבך, שלום","f":"שלמה קרליבך","bt":"תרלד","dt":"תרפח - י כסלו","b":"רב פעלים,רב בממל-תרנ\"ט,קעלן-תרס\"ז"},{"i":43893,"n":"קרליבך, שלמה מליבק","dt":"תרעט - אדר","b":"רב בלובק-תרלג. לכבוד יובלו נדפס \"לשלמה\" ובו מתולדותיו. מחותן עם ר זליג פרסיץ ממוסקבה."},{"i":43894,"n":"קרליבך, שלמה מניו יורק"},{"i":43895,"n":"קרלין, מאיר מנ\"י","b":"תלמיד ישיבת \"רבי יצחק אלחנן\". פרסם מאמרים ב\"הדנו\" - נ\"י תרפה, \"תלפיות\" - נ\"י תשד."},{"i":43896,"n":"קרלינסקי, חיים מניו יורק","f":"ישעיה","bt":"תרסז","bp":"ליבוניץ-ליד בוברויסק","b":"נכד(-אבי אמו) ר תנחום גרשון ביליצקי בעל \"גינת ביתן\". תלמיד ישיבת סלובודקא, חברון, מרכז הרב בירושלים. נסמך מאת ר אברהם יצחק הכהן קוק. הגיע לארה\"ב-תרפט, וכיהן כרב בקהלת \"אהל אברהם\" בניו יורק, חזר לארץ, ואח\"כ שב לארה\"ב וכיהן כרב בקהלת \"נחלת ציון\" בניו יורק. עורך ופרסם מאמרים ב\"היהודי\" - נ\"י תרצו - לתולדות כמה רבנים, \"היסוד\" בתל אביב, עורך \"המסלה\" - נ\"י תרצו. חתם בשמות ספרותיים ובהם - \"חיים בן ישעיה\", \"חיים ישעלי\", \"חיים קרלינאי\", ועוד."},{"i":43897,"n":"קרלינסקי, ישעיה מפוחוביץ","f":"אברהם דב בר","bt":"תרלז","bp":"זמברובא","dt":"תשה - ד כסלו","b":"מצאצאי ר פנחס הורביץ בעל ההפלאה. תלמיד ישיבות ראדין, איישישוק, קובנא-סלובודקא וכונה \"העילוי מזמברובא\". נסמך מאת: ר מלכיאל צבי הלוי מקובנא בעל \"דברי מלכיאל\", ר צבי הירש רבינוביץ מקובנא, ר רפאל שפירא. חתן ר תנחום גרשון ביליצקי מיאשניקובה בעל \"גינת ביתן\". רב בליבוניץ-ליד בוברויסק-תרסג, פוחאוויץ-פלך מינסק-תרסז, השתתף באסיפת הרבנים בפטרבורג-בזמן הקומוניסטים, היגר לארה\"ב-תרפד וכיהן כרב בכמה קהלות, יו\"ר הועד הפועל של אגודת הרבנים באמריקה. הניח חדושים בכת\"י."},{"i":43898,"n":"קרליץ, אברהם ישעיה - חזון איש","f":"שמריה יוסף מקוסובה","k":"בעל חזון אי\"ש","bt":"תרלט","bp":"קוסובה-פלך גרודנא","dt":"תשיד - טו חשון","dp":"בני ברק","b":"מגדולי הפוסקים. נכד ר שמואל קצנלנבוגן מקוברין. תלמיד ר משה טוביה. ישב ולמד בחווידאן-ליטא אצל משפחת אשתו והתפרנס מחנות שהחזיקה אשתו. עבר לוילנא ור חיים עוזר גרוזנסקי נעזר בו בעניני הציבור. הו\"ל את ספרו בעילום שמו. סירב לרבנות ירושלים-תרצד, עלה לארץ והתישב בבני ברק-תרצה. היה מנהיג הצבור החרדי בארץ ולאחר השואה גם בעולם. פרסם מאמרים ב\"שמוש חכמים\" - בני ברק תשז.","bk":[["חזון איש","מפרשי ש\"ס - אחרונים"],["חזון איש – ש\"ס ושו\"ע ואגרות",""]]},{"i":43899,"n":"קרליץ, דוד","b":"פרסם מאמרים ב\"כנסת ישראל\" - וילנא תרץ."},{"i":43900,"n":"קרליץ, חיים שאול","b":"ראש ישיבת \"בית מאיר\", גאב\"ד \"שארית ישראל\" בבני ברק."},{"i":43901,"n":"קרליץ, יהודה ליב ממיכאילשוק","f":"מאיר שלום הכהן","b":"רב במיכאלישוק(=מיכאילשוק)-תרל. חתנו - ר מרדכי אליאשברג מבויסק."},{"i":43902,"n":"קרליץ, יצחק זונדל","dt":"תשג","b":"רב בקאסובה"},{"i":43903,"n":"קרליץ, ישעיה מבני ברק","b":"פרסם מאמרים ב\"תפארת ציון\" - בני ברק תשב - קובץ תלמידי ישיבת \"תפארת ציון\"."},{"i":43904,"n":"קרליץ, מאיר מלכוביץ","f":"שמריה יוסף קרליץ","bt":"תרלז","dt":"תשטו - טו אדר","b":"אחיו של ה\"חזון איש\". חתן נכדת בעל \"חשק שלמה\". מו\"צ בוילנא לצדו של ר חיים עוזר גרודזינסקי, רב בלעכוויץ-תרצג, עלה לבני ברק-תרצז, וכיהן כרבה של תנועת \"פועלי אגודת ישראל\". פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא. על שמו ישיבת \"בית מאיר\" בבני ברק."},{"i":43905,"n":"קרליץ, מאיר שלום","bt":"תרא","dt":"תרעב - טו כסלו","b":"נזכר בספר הזכרון לאחיינו ר ברוך קאהן - ניו יורק תרף."},{"i":43906,"n":"קרליץ, משה מוילנא","f":"שמריה יוסף מקוסובה","dt":"תשג","b":"אחיו של ה\"חזון איש\". רב בועד הרבנים בוילנא. עורך \"כנסת ישראל\" - וילנא תרץ-תרצה - כתב עת של תלמידי ישיבת \"כנסת יחזקאל\"."},{"i":43907,"n":"קרליץ, שאול בנימין הכהן מרדיש","f":"יהודה ליב ממיכאלישאק","dt":"תרם","dp":"אומסק-סיביר","b":"נכד ר ברוך משווינצאן. תלמיד ר יצחק מוולוזין. חתן ר מאיר שלום הכהן מאיוויא - תלמיד ר חיים מוולוזין. רב בזאלודאק, רדישקוביץ, עלה לירושלים-תריז והיה מנהל \"עץ חיים\", היה מעורב במחלקות בענין חצר הת\"ת. בשליחות-תרלא באמריקה, אולם רבני ירושלים ובהם ר אברהם אשכנזי הרשל\"צ, ר מאיר אוירבך בעל \"אמרי בינה\" ור שמואל סלנט - התנגדו לנסיעה, ופרסמו ב\"חבצלת\" מכתב גלוי ליהודי אמריקה כנגדו, ור שאול פרסם מניו יורק אגרת ב\"הצופה\" בירושלים להצדיק עצמו, כשחזר לירושלים נמשכה המחלוקת ולבסוף פרשו כוללות החסידים ויסדו בי\"ד לעצמם ובראשו העמידו את ר שאול, בגלל המחלוקת והלשנות נאסר עם אשתו, ושני הצדדים פרסמו חוברות להצדיק עצמם - \"אמת ומשפט\" ו\"דמעת העשוקים\". בשליחות ברוסיה-תרם ונפטר בשליחותו. בנו ר מאיר שלום הכהן מבריינסק - נפטר תרמד, ונכדו ר ברוך הכהן קאהן."},{"i":43908,"n":"קרליץ, שלמה שמשון","f":"מאיר","bt":"תרע","bp":"וילנא","dt":"תשס - ט תשרי","b":"נכד-אבי אמו בעל \"חשק שלמה\". תלמיד דודו ר איצלה קרליץ בישיבת קוסובה, ישיבת מיר. מקורב לר חיים עוזר גרודזינסקי שסמך עליו בענינים חשובים. מו\"ץ בלכוביץ - לצד אביו, עלה לארץ עם אביו וכיהן כדיין ואב\"ד בפתח תקוה. בשם קרובו החזון איש נמסר שאמר עליו \"ר שלמה הוא התלמיד חכם של המשפחה\". פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא, \"כנסת ישראל\" - וילנא תרץ, \"כנסת ישראל\" - סלובודקה - ירושלים תשא, \"שמוש חכמים\" - בני ברק תשז."},{"i":43909,"n":"קרליץ, שמריה יוסף מקוסוב","f":"שמשון","k":"בעל בית התלמוד","bt":"תריב","dt":"תרעו","b":"מצאצאי ר שמשון מסלונים וקניגסברג. חתן ר שאול קצנלנבוגן מקוסובה וקוברין. רב בקוסובה(=קאסאווא)-פלך גרודנא-תרמג. בנו - ר אברהם ישעיה - ה\"חזון איש\", חתנו - ר יעקב ישראל קנייבסקי."},{"i":43910,"n":"קרליץ, שמריהו יוסף - הנכד","b":"פרסם מאמרים ב\"בית מדרש\" - תל אביב תשא. עורך \"שמוש חכמים\" - בני ברק תשז."},{"i":43911,"n":"קרליץ, שמשון מקוסובה","b":"מצאצאי המקובל ר שמשון אפשטין מקניגסברג, מצאצאי ר שמשון מקרמניץ אחי המהר\"ל. מחותן עם ר שאול קצנלנבוגן מקוסובה וקוברין. בנו - ר שמריהו יוסף ונכדו החזון איש."},{"i":43912,"n":"קרליץ-ציבולניק, נחום מאיר","k":"גיסו של החזון איש","bt":"תרמט","dt":"תשיט - ז טבת","b":"תלמיד ישיבות וולוזין, קלם, ראדין ומיר. חתן ר שמריהו יוסף קרליץ מקוסובה וגיסו של החזון איש. רב במיישגולה-פלך וילנא. עלה לארץ-תרצח וכיהן כרב ביה\"כ הליגמן בבני ברק, הקים כולל \"זכרון מאיר\" לימים כולל חזון איש."},{"i":43913,"n":"קרלנשטין, דב צבי מירושלים","k":"בעל תפארת צבי","r":"ראב\"ד בירושלם","bt":"תריז","dt":"תרצ - כא סיון","b":"תלמיד ישיבת סלובדקא, איישישוק. אב\"ד מאלקין-ליד לומז'ה, עלה לירושלים-תרפב נתבקש לכהן כראב\"ד אצל ר חיים זוננפלד אך ויתר לטובת חברו ר מרדכי ליב רובין.","bk":[["תפארת צבי",""]]},{"i":43914,"n":"קרמזיר, משה ליב מפרשבורג","f":"יצחק בן בער סאנסטף","dt":"תקנד - יג סיון","dp":"פרשבורג","b":"נכד ר בער סאנטוף מגלוגא וקרמזיר. מחכמי פרשבורג."},{"i":43915,"n":"קרמי, אלחנן דוד מריגייו","k":"בעל הגהות על השס","dt":"תנג - ז כסלו","b":"מגדולי חכמי איטליה,רב בריגייו. חיבר פסקים ושו\"ת. חיבר הגהות וחדושים על שו\"ע - והזכירם מהרב\"ך בהספדו ב\"גבול בנימין\"."},{"i":43916,"n":"קרמי, יהודה מצליח מאיטליה","f":"יוסף חיים","b":"מראשי קהלת דוכסות פארמה-תקיח עם ר אברהם מיכאל פונטאנילה."},{"i":43917,"n":"קרמי, יוסף ידידיה מאיטליה","f":"ניסן יקותיאל","b":"חזן ומלמד תורה במודנא-שפג - בביה\"כ של האחים אויזילא, גיסו של ר אהרן ברכיה."},{"i":43918,"n":"קרמי, יעקב ישראל מריגיו","b":"מו\"צ בריגייו-תקס, סמך את ר יוסף דוד אחנן אנקונה מלוגו וסינגאליה לרב."},{"i":43919,"n":"קרמי, ישעיה מריגייו","f":"יוסף","dp":"טריאסט","b":"נקרא לכהן כרב ודרשן בטריאסט - ונפטר בדרכו לשם. תלמיד ר ישראל בנימין באסאן, רב בריגיו אחרי פטירת רבו. תלמידו - ר חנניה חי כהן והביא משיריו בספריו."},{"i":43920,"n":"קרמי, שיראל מריגיו","b":"תלמיד ר משה עייאש. רב בריגיו."},{"i":43921,"n":"קרמניץ, יעקב ישראל","k":"בעל אגודת אזוב","r":"המגיד מקרעמניץ","dt":"תקס - כה כסלו","b":"דרשן,מגיד בקרמניץ","bk":[["אגודת אזוב",""],["שבט מישראל – תהלים",""],["שפת אמת",""]]},{"i":43922,"n":"קרמניצר, יוחנן מקרמניץ","f":"מאיר מקרמניץ","k":"בעל אורח מישור","b":"דיין בקרמניץ-תמ. אחיו - ר שמואל נאמן, ר אריה ליב קלישר."},{"i":43923,"n":"קרמניצר, ישעיה מלבוב","b":"דיין בלבוב, חתם-תטו עם ר אברהם בן גרשון גראפין ור משה ר נטע בערמנש."},{"i":43924,"n":"קרמניצר, שמואל מאושפיצין","f":"משה יהודה ממיקוליניץ","k":"בעל שארית שמואל","bt":"תרע","bp":"אושפיצין","b":"ר\"מ בישיבת בובוב בביאלא ביליץ. ניצל מהשואה, עבר לארה\"ב והיה רב קהלה ור\"מ בישיבת בובוב בניו יורק. חיבר \"שארית שמואל\" ניו יורק תשלד."},{"i":43925,"n":"קרמנר, מנחם מנדל מברוד","b":"רב בברודי-תריח."},{"i":43926,"n":"קרמפר, אהרן יהושע","b":"תשובה אליו \"בית יצחק.\"-תריח."},{"i":43927,"n":"קרמר, אברהם מברגישא","f":"אפרים","bt":"תרלד","b":"נכד ר שלמה מטרסטויץ. נסמך מאת: ר חיים ברלין, ר אליהו פוסק מהאליפולי, ר קלונימוס קלמן מסאוורן. מו\"צ בארחנגלסק-תרס\"ה,רב בראגישע-בסרביה."},{"i":43928,"n":"קרמר, אהרן ארקדי","f":"יוסף","bt":"1865","bp":"סואנציאן","dt":"1935","b":"פעיל ב\"בונד\", נאסר כמה פעמים עם יודין, גוזנסקי, קופלזון. עבר לשוייץ, לונדון, ארה\"ב. חזר לרוסיה ונאסר. יצא לצרפת-1912 והיה מהנדס בחברת הרכבות בצרפת. מורה למתמטיקה בסמינר למורים בוילנא. פעיל ב\"יוווא\" וחבר בועד הקהלה."},{"i":43929,"n":"קרמר, אהרן מרדכי משפאלע","f":"יעקב יצחק","bt":"תרלג","b":"דור שישי מצאצאי הבעש\"ט. חתן ר שלמה דב שפירא מבארשיווקא. רב בשפאלע-פלך קיוב-תרסד על מקום אביו. נסמך מאת: ר נפתלי צבי מסקווירא, ר אליעזר מטולנא."},{"i":43930,"n":"קרמר, אלתר מצפת","b":"מראשי כולל צפת-תרס."},{"i":43931,"n":"קרמר, אריה ליב מארה\"ב","f":"יצחק מיכאל","bt":"תרעט","bp":"חלם","b":"תלמיד ישיבת לובאויטש. נסמך מאת: ר שלמה דוד כהנא מוארשא, ר חיים פוזנר מוארשא, ר חיים פוזנר, ר יצחק מאיר קאנאל מוארשא. חתן ר אליהו הלפרין. ר\"מ בישיבת \"אחי התמימים\" בקאלושין. ניצל מהשואה והגיע לארה\"ב-תשב, עבר למונטריאול וסייע ביסוד ישיבת \"תומכי תמימים\" במונטריאול, ומנהלה. חבר אגודת ישראל."},{"i":43932,"n":"קרמר, אשר זליג מרוזניאטוב ונ\"י","f":"יוסף","k":"בעל שושן חוחים","bp":"טלוסט","b":"נכד ר אשר זליג טויסטר, וממשפחת אדמורי סטרטין. ששו\"ב ברוזניאטוב. היגר לארה\"ב-תרס, וכיהן כרב בניו יורק, (נסע לפולין להדפיס את ספריו). חיבר \"שושן חוחים\" דרוהוביטש תרנט, \"מעדנים\" בילגוריא תרפו, \"שמנה לחמו\", ועוד. פרסם מאמרים ב\"יבנה\" - לבוב תרפט, \"הפרדס\" - צאנז תרצא."},{"i":43933,"n":"קרמר, בנימין","f":"אברהם צבי","k":"בעל חזיון ודמיון","bt":"1887","bp":"ואבולניק","b":"תלמיד ישיבת פוניבז, וילנא, גורש מן הישיבה והיה מורה בגימנסיה של קרינסקי בוארשא, ומגיה ב\"היינט\". פרסם מאמרים בעברית ואידיש."},{"i":43934,"n":"קרמר, גרשון בן אברהם אחי הגרא","f":"ראה: רגולר, גרשון"},{"i":43935,"n":"קרמר, יעקב יצחק משפאלע","b":"רב בשפאלע-פלך קיוב-תרמ, ובנו ר אהרן מרדכי על מקומו אחריו."},{"i":43936,"n":"קרמר, יצחק משפולא","b":"דומ\"צ בנייהייזל-תר\"ל,עבר לבודפשט"},{"i":43937,"n":"קרמר, מנחם מנוס","b":"רב בקרמר,לונדון-תרפ\"ט"},{"i":43938,"n":"קרמר, מרדכי מקובנא","dt":"תשג","b":"רב בקובנה"},{"i":43939,"n":"קרמר, משה מוילנא","f":"דוד","bp":"קראקא","dt":"תמה - יח חשון","dp":"וילנא","b":"רב בבריסק, וילנא-תלב ור הלל מחלמא בן ר יונה על מקומו אחריו. חתנו ר יוסף בן יעקב מספר שהחזיק כמה ישיבות על חשבונו, ומביא מתורתו בספרו \"ראש יוסף\". בניו: ר אליהו חסיד (חפץ)-חתן ר פתחיה בן בעל \"באר הגולה\", ור חיים, נכדו ר משה בן יוסף היה אב\"ד קופנהגן. מצאצאיו גם הגר\"א מוילנא. חתנו ר יוסף בן יעקב בעל \"ראש יוסף\". מתורתו ב\"דרוש שמואל\"."},{"i":43940,"n":"קרמר, משה מוינה","f":"יצחק מנייהייזל ווינה","bt":"תרי","bp":"באטורקעז","dt":"תרפב - כח ניסן","dp":"וינה","b":"תלמיד הכת\"ס, וקרובו ר אברהם אליעזר אלט מקוברסדורף, ור עזריאל הילדסהיימר. חתן ר אהרן דב בר גליס מאיזנשטט. רב בשטיינמאנגר-תרלה, רב בוינה על מקום אביו. פרסם מאמרים ב\"רבותינו שבגולה\" - פרשבורג תרעה."},{"i":43941,"n":"קרמר, נפתלי הרצל","b":"רב-שנת תר\"נ"},{"i":43942,"n":"קרמר, צבי הירש מאיר מוילנא","k":"בעל גופי הלכות","b":"רב בוילנא, סן פרנציסקו. חיבר \"גופי הלכות\" וילנא תרנב. פרסם מאמרים ב\"יגדיל תורה\" - נ\"י תרעו."},{"i":43943,"n":"קרמר, שבתי שפטל","b":"מרביץ תורה בסלוצק,קליבלנד-תר\"צ"},{"i":43944,"n":"קרמרמן, אליהו מקלם וקרוז'","dt":"תשג","b":"ראש ישיבה בוילקומיר, קלם, רבה האחרון של קרוז'. נספה בשואה."},{"i":43945,"n":"קרנא","dt":"תשג","b":"רבה האחרון של סערהיי"},{"i":43946,"n":"קרנגיל, מנחם מנדל מקראקא","f":"יוסף פנחס","k":"בעל שערי גאולה","r":"דומ\"ץ בקרקא","bt":"תרז","bp":"קראקא","dt":"תרץ","b":"מחסידי צאנז. חתן ר אברהם לאק ובזיוו\"ש חתן ר משה שניידר. חיבר \"שערי גאולה\" קראקא תרנו, ועוד. פרסם מאמרים ב\"וילקט יוסף\" - מונקטש-פאקש-בוניהאד תרנט-תרעז, \"חדרי תורה\" - קראקא תרפו, \"שערי תורה\" - קראקא תרפה.","bk":[["דבש וחלב - על התורה",""],["טירת כסף - שיר השירים",""],["שערי גאולה - הגדה של פסח",""],["תורת עירובין - בענין הטלטול בעיר קרקא",""]]},{"i":43947,"n":"קרנגיל, צבי מקראקא","f":"אלעזר","bp":"קראקא","b":"מיסד ת\"ת באנטורפן, עלה לירושלים והיה מראשי כולל גליציה, בנו ר הנגיד בריש עבר לניו יורק."},{"i":43948,"n":"קרנגלאס, דוד מבולטימור","k":"בעל דברי דוד","b":"ר\"מ בישיבת \"נר ישראל\" בבולטימור."},{"i":43949,"n":"קרנו, א' מסארהיי","b":"רב בסארהיי-ליטא."},{"i":43950,"n":"קרניגל, יוסף פנחס מקראקא","f":"משה מקראקא","bt":"תקעו","bp":"קראקא","dt":"תרע","b":"חסיד התפארת שלמה מרדמוסק. גביר מחכמי קראקא. חתן ר צבי הירש הכהן רוזנצויג."},{"i":43951,"n":"קרניול, דב מלמברג","f":"יצחק","bt":"תרס","dt":"תרצט","b":"חסיד בלז וממקורבי האדמור. מצאצאיי ר לוי יצחק שור מליבטשוב. דיין בלמברג וממקימי הישיבה שם. חתן ר יהושע רובינפלד מציריך."},{"i":43952,"n":"קרניץ, אברהם אבא","dt":"תשא","b":"רב בטלז, אלסיאד, ונכדו ר משה גימרק כיהן כרב לא רשמי באלסיאד."},{"i":43953,"n":"קרניץ, בן ציון זאב מליטא","f":"אברהם אבא מוארז'אן","bt":"תריח","b":"רב בברזניק-סובאלק-תרמט, פרירסלה(=פריראסלע)-פלך סובאלק-תרנה, פראן(=פרען)-פלך סובאלק, שווקשנה(=שוועקשנא)-פלך קובנא-תרנח, והקים שם ישיבה-קיבוץ בחורים ועמד בראשה, וחתנו ר ישראל תנחום פורטמן הי\"ד על מקומו אחריו."},{"i":43954,"n":"קרניץ, יעקב מוילנא","dt":"1939","dp":"קובנא","b":"מחברי \"התחיה\" בוילנא. יסד-1905 אגודה \"גאולת הארץ\" לאיחוד הפעולות המעשיות למען א\"י סביב קק\"ל. מיוזמי ועדת פינסק-1906. ציר בקונגרס הציוני. נשלח לאוקראינה ליצירת קשר עם חברי צ.צ. שם. עבר לתנועה הרביזיוניסטית."},{"i":43955,"n":"קרניץ, ישראל מזיימל ונאמוקשט","dt":"תשג","b":"רב בזיימל, רבה האחרון של נאמוקשט(=ניעמקסט). נספה בשואה."},{"i":43956,"n":"קרניץ, נפתלי הרץ מסאלוק","b":"תלמיד ר ר יצחק יעקב ריינס בשונציאן. רב בסאלוק-תרס."},{"i":43957,"n":"קרנץ יעקב בן זאב","bt":"1740","dt":"ה'תקסד 1804","bk":[["אהל יעקב",""],["אהל יעקב וקול יעקב",""],["בית יעקב",""],["דברי יעקב",""],["כתבי המגיד מדובנא",""],["משלי המגיד מדובנא",""],["משלי חכמה",""],["משלי יעקב",""],["סדר הגדה של פסח עם פירוש המגיד מדובנא",""],["ספר המדות",""],["קול יעקב",""]]},{"i":43958,"n":"קרנץ, יעקב מדובנא","f":"זאב","k":"המגיד מדובנא","r":"המגיד מדובנא","bt":"תק","bp":"זאטל-פלך וילנא","dt":"תקסה - יז טבת","dp":"זמושץ","b":"חתן ר נחום מקוברין. מגדולי הדרשנים. רב במזריטש, זולקוא, וולודובה, קליש, דובנא, חעלמא, זמושץ. ממקורבי הגר\"א. נחשב לראש הדרשנים ומקובל על כל שכבות העם. חיבר \"קול יעקב\" יוזפוף תקץ. (ביקש מבעל הישועות יעקב שלא יבוא לדרשתו בגלל חולשתו - צחק ואמר שאינו בעל בכי אבל באמצע הדרשה פרץ בבכי ונחלה). פגש את משה מנדלסון בברלין שקרא לו \"איזופ היהודי\". בנו ר יוסף ותלמידו ר אברהם בר פלאום הו\"ל את ספריו \"אהל יעקב\", \"כוכב מיעקב\", \"משלי יעקב\", ועוד. בנו גם ר יצחק, חתנו - ר מרדכי רפפורט.","bk":[["אהל יעקב – עה\"ת",""],["כוכב מיעקב – הפטרות",""],["כתבי המגיד מדובנא",""],["משלי יעקב - דרוש",""],["ספר המדות",""],["קול יעקב – חמש מגילות",""],["קול רינה וישועה – מגילת אסתר",""]]},{"i":43959,"n":"קרנץ, יצחק","f":"יעקב המגיד מדובנא","bt":"תקמ","dt":"תקצא","b":"מגיד"},{"i":43960,"n":"קרנץ, פיליפ","k":"בעל דיא פאמיליע ראטש","bt":"1858","bp":"זופראן","dt":"1922","b":"תלמיד הסמינר לרבנים בזיטומיר. הצטרף לתנועה המהפכנית ונאסר. ברח לפאריס ולמד בסורבון. פרסם חיבור על שפינוזה, ומאמרים שונים. עורך \"ארבייטער פריינד\" בלונדון. פרסם חוברות על הסוציאליזם והשתתף בתעמולה אנטי דתית. ציר בקונגרסים סוציאליסטים. חיבר ספרי מדע וביוגרפיות של גדולי ישראל. עבר לניו יורק-1890 והיה בעל השפעה על הסוציאליזם היהודי."},{"i":43961,"n":"קרנקרויט, ישראל מבובוב","dt":"תש..","b":"רב ור\"מ בבובוב. חתן ר אריה ליב הרצוג מבובוב. נספה בשואה."},{"i":43962,"n":"קרנר, אברהם מנדבורנה","b":"מחכמי נדבורנה - תשובה אליו \"שאול ומשיב\"."},{"i":43963,"n":"קרנר, אפרים זאב מסטרי","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":43964,"n":"קרנר, משה מזלאטווא","k":"בעל ברכת משה","bt":"תקכב","bp":"זלאטווי","dt":"תקצד","dp":"ברסלוי","b":"נכד ר ישכר ברמן בעל \"מטה ישכר\". נדד במקומות שונים ופגש רבים מגדולי דורו, ומביא מהם בספריו. (הקדשה אליו מאת נכד ר ישכר ברמן בעל \"מטה ישכר\" - תקצג)."},{"i":43965,"n":"קרנרט, שמחה מסנוק","b":"פרסם מאמרים ב\"חדרי תורה\" - קראקא תרפו."},{"i":43966,"n":"קרסו - משפחה","b":"משפחת רבנים על שם הנחל קאראסו."},{"i":43967,"n":"קרסו, אשר הלוי משלוניקי","dt":"תריג","dp":"שלוניקי","b":"דיין בשלוניקי. בנו - הפוסק ר יהודה."},{"i":43968,"n":"קרסו, בנימין משלוניקי","b":"משורר בשלוניקי-שנות ה-ש', מחברי ר גדליה ן יחיא המשורר משלוניקי."},{"i":43969,"n":"קרסו, דוד הלוי משלוניקי","f":"יהודה בן דוד משלוניק","dt":"תרטז - ז סיון","dp":"שלוניקי","b":"דיין בשלוניקי, ומורה הוראה לקהלת ה\"דונמה\". נפטר צעיר במגיפה. תשובותיו נדפסו בספר זקנו \"ידי דוד\"-תרכז."},{"i":43970,"n":"קרסו, דוד הלוי משלוניקי - א","dt":"תקלח - אחרי","dp":"שלוניקי","b":"גביר בשלוניקי. סייע בהדפסת \"סוכת דוד\" לר דוד שירירו-תקלח."},{"i":43971,"n":"קרסו, דוד הלוי משלוניקי - ב","f":"יהודה הלוי","k":"בעל ידי דוד","dt":"תקצה - ח כסלו","dp":"שלוניקי","b":"דיין בשלוניקי בשנים תקסב-תקצב, תשובותיו עם תשובות בנו ר יהודה ונכדו ר דוד בספר \"ידי דוד\" שלוניקי תרכז, בנו ר יצחק עזב את המסחר ועסק בתורה וקיבל היתר מחכמי שלוניקי להלוות בהיתר עסקא (היתר זה היה לתלמידי חכמים, מופיע ב\"שער אשר\" ח\"א) . השיב גם לשאלות לבני כת ה\"דונמה\". אולי בנו גם ר שלמה שנפטר במגפה-תקעה. חתם-תקף עם ר יעקב רפאל מנשה ור חיים שמואל גטניו בתשובה לר אברהם משירון. חתם-תקפד עם ר חננאל הכהן חסיד ור חיים שמואל גטניו."},{"i":43972,"n":"קרסו, דוד משלוניקי","f":"שמואל","k":"בעל לה איסטורייה די","b":"גביר מחכמי שלוניקי. נסע לתימן לעסקיו וחיבר בלאדינו ספר על יהודי תימן."},{"i":43973,"n":"קרסו, יוסף משה משלוניקי","dt":"תרפה","dp":"שלוניקי","b":"מחכמי שלוניקי, ראש המוהלים, ודרשן מפורסם בק\"ק פולייא."},{"i":43974,"n":"קרסו, יוסף משלוניקי - א","b":"דרשן,רב בשאלוניקי-ש\"פ"},{"i":43975,"n":"קרסו, יוסף משלוניקי - ב","dt":"תלב","dp":"שלוניקי","b":"דיין בשלוניקי-תח."},{"i":43976,"n":"קרסו, יצחק משלוניקי","f":"יעקב","dt":"תקל - ה חשון","dp":"שלוניקי","b":"דיין בשלוניקי, וראש ישיבה שם ומתלמידיו ר אברהם אמריליו מטריקולה(=טריקלה) המביא מתורתו ב\"ברית אברהם\"."},{"i":43977,"n":"קרסו, משה הלוי משלוניקי","dt":"תקב-תקה","b":"רב בשלוניקי, ומלמד בישיבת \"בית יעקב ג'יניאו\"."},{"i":43978,"n":"קרסו, משה הלוי משלוניקי - ב","dt":"תרמז","dp":"שלוניקי","b":"דיין לחזקת בתים בשלוניקי, וראש ישיבת \"בית יעקב ג'יניאו\"."},{"i":43979,"n":"קרסו, משה משלוניקי","bt":"תרמה","bp":"שלוניקי","b":"עבר משלוניקי לפיריאו, עלה לארץ-תרפד והתישב בתל אביב ופעל להקמת שכונות, עמד בראש הסתדרות עולי יון בתל אביב."},{"i":43980,"n":"קרסו, עמנואל משלוניקי - עו\"ד","bt":"תריח","bp":"שלוניקי","b":"עו\"ד בשלוניקי. הצטרף ל\"תורכים הצעירים\", והיה חבר בפרלמנט התורכי."},{"i":43981,"n":"קרסו, שלמה משלוניקי","f":"דוד","dt":"תקף","b":"מחכמי שלוניקי, נספד מאת ר יעקב רפאל מנשה."},{"i":43982,"n":"קרסו, שם טוב הלוי משלוניקי","b":"רופא בשלוניקי-תרכה."},{"i":43983,"n":"קרסטין, לזר","bt":"1868","bp":"קובנא","b":"צייר. למד בוינה, התישב באודסה, בארץ ישראל, וינה. רוב יצירותיו בנושאים יהודיים."},{"i":43984,"n":"קרסילס, ישראל","dt":"יא תשרי","b":"מו\"צ בברוד"},{"i":43985,"n":"קרסילשציקוב, י'איזיק","bt":"תרמח","b":"בקי,רב בגאדיאץ,פולטובה,קראקוב-עד תרמ\"ט"},{"i":43986,"n":"קרסינטי, אהרן מאלגיר וצפת","f":"אברהם","b":"עלה עם אביו מאלגיר-תקץ והתישבו בצפת. דרשה ממנו לשבת זכור ב\"פרחי ד\"י - אהבת עולם\" ירושלים תרס. חתם עם רבני צפת על הסכמה ל\"באור החיים\" ירושלים תרפה, ועל כתב שליחות ר יצחק מזרחי-תרכז."},{"i":43987,"n":"קרסינטי, יוסף מאלגיר","dt":"תרלז","dp":"תלמסאן-אלגיר","b":"רב ומשורר בתלמסאן-תרכט. מתורתו ב\"זבחים שלמים\" לר אברהם אנקאווא."},{"i":43988,"n":"קרסינטי, מרדכי מאלגיר","f":"אברהם","dt":"תרפג","dp":"טבריה","b":"עלה עם אביו מאלגיר והתישב בטבריה. מלמד תורה. עליו ב\"טוב רא\"י\" לרי\"ח ילון."},{"i":43989,"n":"קרסינטי, נסים מאלגיר","f":"אליהו","k":"בעל לחם שעורים","bt":"תקף","dt":"תרס - בערך","b":"מחכמי ווהראן, מדפיס ומשורר. חיבר \"לחם שעורים\" - ווהראן תרטז. הו\"ל \"שובע שמחות\" ווהראן תרטז, \"חינוך לנוער\", \"עשרת הדברות\". חיבר גם פיוטים ובהם לכבוד נצחון הצרפתים באלגיר-תקץ."},{"i":43990,"n":"קרסינטי, פארוז מאלגיר","k":"בעל גושפנקא דמלכא","dt":"תרי","b":"רב ודיין בתלמסאן, ווהראן. תשובות ממנו בכתב. הסכים על ספר הזכרון - ליוורנו תרה."},{"i":43991,"n":"קרסינטי, שמואל מאלגיר","bt":"תקנט","dt":"תרכט","b":"רב בתלמסאן, ווהראן."},{"i":43992,"n":"קרסינטי, ששון ממרוקו","b":"מו\"ץ בטיטואן-מרוקו, חתם-תפא על פס\"ד."},{"i":43993,"n":"קרסינטיא, יוסף","b":"רב באלג'יר-תר\"י"},{"i":43994,"n":"קרסיק, אברהם שלמה מוילנא","f":"צבי הירש","bt":"תקעג","bp":"חרקוב","dt":"תרמו - ז אד\"ב","dp":"וילנא","b":"חתן ר פרץ ולטשטין. מנהל עסקיו של הברון יוזל גינצבורג-בזמן מלחמת קרים, ופעל לקבורת החיילים היהודים בקבר ישראל. התישב בוילנא לרגל עסקיו והיה גביר מנכבדי וילנא. החזיק עשרה לומדים. גבאי בת\"ת יחד עם ר יונה גרשטין. בשליחות הקהלה בפטרברוג אל הצאר אלכסנדר השני והשלישי-תרמה יחד עם ר מאיר גורדון, ר שעפטל קלצקי."},{"i":43995,"n":"קרסיק, דב בר מקרלביץ","k":"בעל פתחי עולם","b":"רב בקרלביץ-תרן. חיבר גם \"טיב שמות גיטין\", ועוד."},{"i":43996,"n":"קרסל, אליקים גצל","b":"ביבליוגרף, סופר."},{"i":43997,"n":"קרסנובסקי, דב בר מחאטימסק","f":"חיים יצחק","bt":"תרה","b":"רב במנסטריצה(=מאנאסטירשצעגע), חוטימסק(=חאטימסק)-פלך מוהילוב-תרמד."},{"i":43998,"n":"קרעדיטור, ל' ש'","k":"בעל דער רמב\"ם"},{"i":43999,"n":"קרעזמיר, משה מפרשבורג","b":"תלמיד החת\"ס, עלה לארץ בברכת רבו."},{"i":44000,"n":"קרעי, יעקב","b":"פרסם מאמרים ב\"הירח\" - ג'רבה תשח."},{"i":44001,"n":"קרפונקל, אהרן מנאחוד","f":"יהודה ליב","k":"בעלת שאלתות אביה","b":"אב\"ד נאחוד-תקן. חיבר \"שאלתות אביה\" וחלק ממנו נדפס בשם \"נפך וברקת\" עם פירוש \"משוח מלחמה\"."},{"i":44002,"n":"קרפילוב, יונה","k":"עילוי ממינסק","dt":"תשג","b":"מתורתו ב\"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר, \"תורה אור\" - שנחאי תשו."},{"i":44003,"n":"קרפיליו, דוד מלאריסה","b":"רב בלאריסה-שנות ה-ש'."},{"i":44004,"n":"קרפין, דב ברל מדולינא","b":"רב בדולינא-תרנב."},{"i":44005,"n":"קרפל, אברהם משה מארה\"ב","f":"יעקב","bp":"אשמענא","b":"תלמיד קבוץ סמרגון אצל ה\"סאסניצער עלוי\", ישיבת וולוזין, כולל קובנא, איישישוק, וילנא. נסמך מאת: ר מרדכי אשמענער, ר רפאל שפירא, ר שלמה הכהן מוילנא, ר משה בצלאל מסובאלק, ר יעקב יצחק ריינס מלידא, ר צבי הירש מקובנא, ר משה דנישבסקי. רב באלשן-פלך וילנא, היגר לארה\"ב וכיהן כרב בניו יורק. פרסם מאמרים ב\"כנסת ישראל\" - נ\"י תרצב - כתב עת הסתדרות תלמידי סלובודקה באמריקה."},{"i":44006,"n":"קרפל, יום טוב ליפמן משופרון","b":"מחכמי סערדאוהל, שופרון. חתן ר משה בניהאד-פולק מסערדאוהל. אביו של ר יצחק מפאקש."},{"i":44007,"n":"קרפל, יצחק מפאקש","f":"יו\"ט ליפמן משופרון","k":"בעל נפש יצחק","bp":"סערדאוהל","dt":"תש - כד כסלו","dp":"פאקש","b":"תלמיד השב\"ס, ור דוד ניימן מפרשבורג. חתן ר משה ישכר בר שלזינגר מפאקש, ועבר לשם. דיין בפאקש-תרנא. פרסם מאמרים ב\"וילקט יוסף\"."},{"i":44008,"n":"קרפלס, אברהם הכהן מגירבא","f":"אליעזר הכהן מאייבניץ","k":"בעל אהל אברהם","bt":"תקץ","bp":"אייבניץ","dt":"תרנה - כח תשרי","b":"תלמיד הכת\"ס. חתן ר יהודה ליב וייס מגירבא-פינצעהעל(=גורבו פינצאהאי)-מחוז טולנא, רב על מקום חותנו-תריג (עפ\"י הוראת הכת\"ס). סידר והגיה את תשובות הכתב סופר."},{"i":44009,"n":"קרפלס, אליעזר הכהן מאייבניץ","f":"משה מבסקביץ","b":"רב באייבניץ. אביו של ר אברהם מגירבא-פינצעהעל."},{"i":44010,"n":"קרפלס, אלעזר מפרג ואירשא","f":"נפתלי (או דוד)","k":"בעל אבן האות","bt":"תקיד","dt":"תקצב - כג ניסן","b":"תלמיד ר יחזקאל לנדא בעל \"הנודע ביהודה\", ר זרח אידליץ. רב באלברט-אירשא-תקן - (פוטר לאחר 3 שנים), ליבנא(=ליבען) וגליל קוירשם-ליד פרג. חיבר גם \"יחזקאל למופת\". מתלמידיו ר משה שיפמן מואטיץ ופרג."},{"i":44011,"n":"קרפלס, יהודה ליב מגירבא","f":"אברהם קרפלס איבניץ","bt":"תרטו","dt":"תרלו - ד תמוז","dp":"פרשבורג","b":"תלמיד השב\"ס, ור בנימין זאב וולף ברייער מטאב. נפטר בצעירותו בעת לומדו בפרשבורג."},{"i":44012,"n":"קרפלס, יצחק הכהן","f":"משה פרגר מבסקביץ","k":"יצחק בסקביץ","b":"תלמיד החת\"ס בפרשבורג-תקפח ורשם מחדושיו."},{"i":44013,"n":"קרפלס, משה הכהן מבסקביץ","b":"רב בבסקביץ. אביו של ר אליעזר מאייבניץ."},{"i":44014,"n":"קרפלס, עקיבא ממריאמפול","f":"זאב וולף","b":"תלמיד החת\"ס. דיין בויליאמפול-סלובודקא, חתם-תרד עם ר חנוך הניך איטלסון בענין היתר עגונה."},{"i":44015,"n":"קרפניטי, מרדכי מפיררה","f":"דוד","b":"רב בפיררה. תשובה ממנו בענין חזקת חנויות מפיררה, בזמן הרבנים פינצי וטראצינה."},{"i":44016,"n":"קרפנשפרונג, מרדכי מקוברין ומיר","b":"ניצל מהשואה והגיע לשנחאי-סין. פרסם מאמרים ב\"מאור תורה\" - שנחאי-סין תשד - קובץ תלמידי ישיבת מיר בשנחאי, \"היכל התורה\" - מיר-נוברדוק תרצה, \"חדרי תורה\" - קראקא תרפו, \"כנסת ישראל\" - וילנא תרץ, \"התבונה\" - נ\"י תשז - קובץ תלמידי ישיבת מיר."},{"i":44017,"n":"קרפר, יצחק מדעש","f":"מנחם","k":"בעל שדה יצחק - כת\"י","bp":"חוסט","b":"תלמיד בעל \"ערוגת הבשם\" בחוסט ובעל \"עצי חיים\" בסיגט. מחכמי דעש ויסד-תרפב חברת \"מחזיקי תורה\" להקמת חדרים מיוחדים לילדי החסידים ועמד בראש בימ\"ד חסידי, עבר לטשאנד וכיהן כמנהל הישיבה בראשות ר מרדכי בריסק."},{"i":44018,"n":"קרצינטי, שלום ממרוקו","f":"יעקב","b":"ראש חברת הזהר במראקש. עלה לארץ לאחר קום המדינה."},{"i":44019,"n":"קרצינסקי, שיימא יצחק ליב","f":"ברוך","bt":"תרלו","b":"רב באווידיפלע-פלך חרסון-תרסה."},{"i":44020,"n":"קרצמר, אברהם מוילנא","f":"יעקב בן מאיר","k":"בעל יד קידושין","bt":"תרה-ו","bp":"וילנא","dp":"וילנא","b":"תלמיד דודו ר שלמה הכהן מוילנא, ר יעקב בארים בישיבת ר חיים נחמן פרנס בוילנא. מו\"צ באנטקליא-פרבר וילנא-תרלא. מגיה בבית הדפוס של ראם ומו\"ץ. תרגם לאידיש את ספר \"היראה\" לר יונה גירונדי. חיבר גם \"אבן ישרה\" - בכת\"י, ועוד. הגהותיו על המשנה נדפסו במשניות - דפוס ראם. נסמך מאת: דודיו ר שלמה הכהן ור בצלאל הכהן מוילנא. אחיו: ר יוסף מבאחמוט, ר בן ציון מסימפאראפל."},{"i":44021,"n":"קרצמר, בן ציון מפוסוואל","f":"יעקב בן מאיר","bt":"תרל","dt":"תרץ","b":"בן אחות ר בצלאל הכהן ור שלמה הכהן מוילנא. חתן ר בנימין באלי דיאמנט(=דימנד) מפוסבול(=פוסוואל). רב בפוסוואל על מקום חותנו, סימפרופול(=סימפעראפאל)-תרנה על מקום חותנו."},{"i":44022,"n":"קרצמר, יוסף מבאחמוט","f":"יעקב בן מאיר","bt":"תרכג","b":"נכד-אבי אמו ר ישראל משה הכהן-אביהם של ר שלמה ור בצלאל מוילנא. תלמיד אחיו הגדול ר אברהם מאנקטליא, דודו - ר שלמה בעל \"חשק שלמה\" בקלויז ר שואל בוילנא, תלמיד ישיבות איישישוק, וולוזין. חתן ר אהרן ליפמן הנדלר. רב בטאלסן-תרמז, ביעופטריא, באחמוט-פלך יקטרינסלב-תרנז.. נסמך מאת: הנצי\"ב, ר יצחק מאיר מסלובודקא, ר צבי הירש רבינוביץ מקובנא."},{"i":44023,"n":"קרצמר, יעקב מפוסוואל","f":"מאיר","b":"רב בפוסוואל-תרמ. בניו - ר בן ציון, ר אברהם ור יוסף מבאכמוט."},{"i":44024,"n":"קרצמר, נפתלי הרץ מפוניבז","f":"אברהם","k":"בעל נועם המצוות","bp":"ביאליסטוק","dt":"תרעג","b":"נישא לפוניבז ועבר לשם. יסד חברות שונות ללימוד תורה ולימד בהם."},{"i":44025,"n":"קרצקי, הענאך מאיר","b":"פרסם מאמרים ב\"הנשר\" - טירנוי תרצג-תשד."},{"i":44026,"n":"קרקא, צבי הירש מניקלשבורג","b":"רב בניקלסבורג-תק\"מ"},{"i":44027,"n":"קרקובסקי, אברהם ישכר מקטוביץ","b":"פרסם מאמרים ב\"כתר תורה\" - סוסנוביץ-פיעטרקוב תרץ-תרצט."},{"i":44028,"n":"קרקובסקי, אפרים מפשדבורז","k":"אדמור מפשדבורז","b":"מצאצאי האדמור ר דוד מללוב, נכד ר משה מפשדבורז. אדמור בפשדבורז, עלה לארץ וחדל מאדמורות."},{"i":44029,"n":"קרקובסקי, יוסף יואל","f":"מאיר מפשדבורז","b":"נכד האדמור ר דוד מללוב. חתן ר אהרן בורנשטין מטשעקטשין."},{"i":44030,"n":"קרקובסקי, מאיר מפשדבורז","f":"אליקים קראקובר","k":"אדמור מפשדבורז","b":"מצאצאי בעל הב\"ח - בן אחר בן. חתן ר דודו מללוב. אדמור בפשדבורז. בניו: ר שלמה צבי-חתן ר ישראל מלובלין, ר יוסף יואל, ר משה מפשדבורז."},{"i":44031,"n":"קרקובסקי, מנחם מוילנא","f":"צבי בעל חמודי דניאל","k":"בעל עבודת המלך","bt":"תרל","bp":"וילקוביסק","dt":"תרצ - יג חשון","b":"תלמיד ר אליעזר לנדא מוילקוביסק, ר מאיר רבינזון מקרוק. בגיל 13 דרש בבהיכ\"נ בסובאלק. תלמיד ישיבת וולוזין. חתן ר אליהו פינשטין מפרוז'ין, וגיסו של ר משה סולוביציק מניו יורק. מגדולי הדרשנים בדורו. רב בטימקוביץ, חסאלביץ, נוברדוק על מקום בעל \"ערוך השלחן\", מגיד מישרים בוילנא. הסכים על \"תהלה לדוד\" ירושלים תריג, \"מטע משה\" תרנח. חיבר רשימה ביוגרפית של חותנו ובה תיאור על התנהלות הרבנות בליטא, חיבר גם \"יער הלבנון\". ממיסדי כתב העת \"שבוע\" ופרסם מאמרים רבים בשמות שונים ובהם: \"מבקר\", \"לבנון\", \"הירשנזון\", ועוד. מדרשותיו ב\"ארזי הלבנון\", פרסם מאמרים ב\"יגדיל תורה\" - סלוצק-בוברויסק תרסט. הספד לזכרו ב\"קול תורה\" - ירושלים תרץ."},{"i":44032,"n":"קרקובסקי, משה מפשדבורז","f":"מאיר מפשדבורז","b":"נכד האדמור ר דוד מללוב. רב בפשדבורז."},{"i":44033,"n":"קרקובסקי, צבי הירש","b":"מצאצאי ר דניאל מהורדנא בעל \"חמודי דניאל\". בנו - ר מנחם בעל \"עבודת המלך\"."},{"i":44034,"n":"קרקובסקי, שלמה צבי","f":"מאיר מפשדבורז","b":"נכד האדמור ר דוד מללוב. חתן ר ישראל מלובלין."},{"i":44035,"n":"קרקובר כץ רפפורט, משה","f":"אברהם רפא"},{"i":44036,"n":"קרקובר, דוד מאיזנשטט","b":"דיין באייזנשטט-תנ\"ט"},{"i":44037,"n":"קרקובר, זלמן מאיזנשטט","b":"מתורתו ב\"קובץ מפרשי התורה\" - מארגרטן תרצג."},{"i":44038,"n":"קרקובר, זלמן מלבוב","b":"מגיד בלבוב, נזכר ב\"אדני פז\"-זולקוא תקם. ראה גם: ר שלמה זלמן קרקובר, ר יקותיאל זלמן בן נח יחיאל."},{"i":44039,"n":"קרקובר, יצחק (באב\"ד) מברוד","f":"ישכר דב בעריש","dt":"תסה","b":"רב בברזאן, אב\"ד ברודי, אבי משפחת באב\"ד. חתן ר דוד כתבן מזולקוא חתנו של הש\"ך."},{"i":44040,"n":"קרקובר, ישראל מברודי","f":"יצחק קרקוור","b":"רב בזסלב-ת\"י"},{"i":44041,"n":"קרקובר, ישראל מרישא הי\"ד","b":"חתם-תנט בועד ירוסלב. נהרג עק\"ה."},{"i":44042,"n":"קרקובר, שלום מירושלים","b":"מחכמי ירושלים, בשליחות-תסב, ונזכר במכתב-תעז שלא שמעו ממנו."},{"i":44043,"n":"קרקובר, שלמה זלמן (מקרקוביץ)","f":"יצחק","dt":"תעט - ט חשון","dp":"לבוב","b":"ראב\"ד ור\"מ בלבוב. חתם-תמו עם ר אברהם גראפין ור יהודה אברהם הלוי, חתם-תנד עם ר שלמה קרקובר."},{"i":44044,"n":"קרקובר, שמואל מפרג","b":"תלמיד ר מרדכי בנט. מחכמי פרג. תשובה אליו-תרג ב\"יד אלעזר\" לר אלעזר הלוי הורביץ מוינה."},{"i":44045,"n":"קרקובר, שמריהו מקראקא ולבוב","b":"דיין בקראקא-תד, חתם בלבוב-תד עם ר יוסף בן אלכסנדר מאופלה."},{"i":44046,"n":"קרקובר-יאס, שמואל מפרג","b":"מגדולי מרביצי התורה בחכמי פרג-ת\"צ"},{"i":44047,"n":"קרקלינסקי, אברהם צבי הכהן","f":"פנחס יוסף","bt":"תרכב","b":"תלמיד ישיבת וולוזין. מו\"צ ביעליסאוועטגראד-פלך חרסון-תרנו. פרסם מאמרים ב\"כנסת חכמי ישראל\" - אודסה-פיעטרקוב-ברדיטשוב תרנג-תרס."},{"i":44048,"n":"קרקסאני, יוסף הקראי מבבל","f":"יעקב","k":"בעל בראשית","bp":"כרכמיש-בבל","b":"מחכמי הקראים הקדומים, חיבר ספר שרשי הדת בשם \"בראשית\", פייטן ומפיוטיו בסדור התפלה הקראי, היה מהפלג הקראי \"רכוב\" - המחמירים בדיני עריות. אולי בן דורו של ר סעדיה גאון."},{"i":44049,"n":"קרקשיני, אברהם","f":"משה","b":"נזכר בראב\"ד, כנראה הוא ר אברהם מפשקיירא שנזכר ב\"מסעות ר בנימין\"."},{"i":44050,"n":"קרקשיני, אליהו מפרובנס","f":"יצחק","b":"חתן ר משלם בן משה. מחכמי פרובנס-שנת ל'. חיבר פירוש ל\"מורה נבוכים\". אולי הוא שחיבר ספר האסופות והיה תלמיד ר אלעזר מגרמיזא, אך לדעת ר חיים מיכל מחבר ספר האסופות - ר יהודה בן יעקב."},{"i":44051,"n":"קרקשיני, אליהו מקושטא","b":"מחכמי קושטא-תיח, מתומכי ש\"ץ בתחלת דרכו."},{"i":44052,"n":"קרקשיני, דוד מקושטא","f":"נתנאל","b":"מחכמי קושטא. בשליחות באיטליה והולנד לאסוף כספים כדי לפדות שבויים מפולין בזמן גזירות תח-תט."},{"i":44053,"n":"קרש, דב בריש מקוצק","f":"ירמיה","bt":"תרלא","b":"רב בקוצק-פלך שדליץ-תרסב."},{"i":44054,"n":"קרש, יצחק מרדכי מרישא","b":"פרסם מאמרים ב\"הירדן\" - רישא תרץ."},{"i":44055,"n":"קרשביהו הנקדן מספרד","k":"בעל הגהות על הסמג","b":"מגדולי חכמי ספרד-שנת ס'. חיבר גם הגהות על התרומה."},{"i":44056,"n":"קרשביץ, יהודה הכהן מלבוב","f":"זליג","dt":"שעח - כו ניסן","dp":"לבוב","b":"ר\"מ בלבוב ונזכר ב\"צמח דוד\" שהיה בזמנו של הרב שכנא והיו שלשה ראשי ישיבות - האחד ר קלמן וירמיש, השני ר קלמן הברקשטן, והשלישי ר יהודה קראשוויץ. גיסו - מהר\"ם מלובלין (לפי אוצר הרבנים). לפי בובר יש בלבול בין שני רבנים האחד בשם יהודה בן זליג והשני יהודה קראשוויץ."},{"i":44057,"n":"קרשטין, אשר ממינסק ועפולה","bt":"תרמו","dt":"תשלה - כג סיון","b":"רב במינסק,רב בעפולה-תרצ\"ו"},{"i":44058,"n":"קרשטיק, זאב וולף מגלינא","b":"מחכמי גלינא - תשובה אליו \"נחלי מים\"."},{"i":44059,"n":"קרשניק, יצחק","dt":"שנג - כג ניסן","b":"מגדולי חכמי קרקא,שו\"ב ומוהל"},{"i":44060,"n":"קרשניק, מרדכי","b":"דיין הגדול בקרקא-ת\"ג,רב בלונטשיץ"},{"i":44061,"n":"קרשקש חסדאי בן אברהם","bt":"1340","dt":"ה'קע 1410","bk":[["אור ה'",""],["משפט הבחירה",""]]},{"i":44062,"n":"קרשקש, אליעזר מצרפת","f":"יהושע","k":"בונפיס קרשקש","b":"רב בצרפת, יצא לגלות-קנה. חיבר \"בית זבול\" - \"מקור חיים\", אולי הוא מחבר הפיוט \"המלך בנפלא בגודל רחמיך\"."},{"i":44063,"n":"קרשקש, אשטרוק","b":"מחכמי ספרד, רב בשלשונה-ק\"נ"},{"i":44064,"n":"קרשקש, אשר מאלגיר","b":"רב מאלג'יריה, פילוסוף. מתורתו ב\"עומר השכחה\"."},{"i":44065,"n":"קרשקש, אשר מפרובנס","f":"אברהם","k":"בעל אות נפש","b":"מגדולי חכמי פרובינצה-ד'תתק\"צ - או ה'ק. חיבר ביאור על מורה נבוכים, פירוש על ראב\"ע בשם \"אות נפש\", ועוד."},{"i":44066,"n":"קרשקש, דוד מאלגיר","dt":"תקסו - לפני","b":"מרבני קצמטינא. נזכר ב\"אשכבתא דרבנן\" ב\"אהל דוד\"."},{"i":44067,"n":"קרשקש, דוד מאלגיר","b":"רב באלגיר. שאלות ממנו לרי\"ש צרור. תלמידו - ר מכלוף עמר ומביא מתורת רבו ב\"דרושים\"."},{"i":44068,"n":"קרשקש, חסדאי מספרד - ב","f":"אברהם או יהודה","k":"בעל אור השם","bt":"ק'","bp":"ברצלונה","dt":"קצ - טז אב","dp":"ברצלונה","b":"מגדולי חכמי דורו, הוגה דעות, מדינאי, מרביץ תורה, חוקר, מקורב למלכות, רב בברצלונה, סרגוסה. נהרג עק\"ה - לאחר הלשנה נכלא בברצלונה עם עוד ששה נשואי פנים, ונרצח זמן קצר לאחר מכן. מחבר \"אור השם\". לפי כנסת ישראל - בנו הוא שנהרג עק\"ה. (יש רושמים תאריך פטירתו - קעב)."},{"i":44069,"n":"קרשקש, חסדאי מספרד - הזקן","f":"יהודה בן חסדאי","dt":"קט","b":"מגדולי חכמי התורה בספרד, מתלמידיו - ר יצחק בן ששת-הריב\"ש - המזכירו בתשובותיו. תשובות ממנו לר יעקב בעל הטורים ולאחיו ר יהודה."},{"i":44070,"n":"קרשקש, יוסף מאלגיר","f":"שלמה","bt":"תם","dt":"תקי - בערך","b":"תלמיד ר רפאל ידידיה שלמה צרור. מרביץ תורה בביכה\"נ \"דאר בן נהוראי הנקרא דאר שראב\". חתם על החרם נגד נחמיה חייא חיון. נזכר במנהגי אלגיר לר יהודה עייאש."},{"i":44071,"n":"קרשקש, יוסף מאלגיר","f":"משה","b":"רב ומשורר באלגיר. בקשות ממנו במחזור אלגיר - כת\"י."},{"i":44072,"n":"קרשקש, יצחק מברצלונה","f":"אברהם","b":"תלמיד הרמבן, מרבותיו של הרשב\"א. חיבר פירוש על הריף."},{"i":44073,"n":"קרשקש, יצחק מקנדיא","b":"רב בקנדיא-שנות ה-ת'. בנו - חיים."},{"i":44074,"n":"קרשקש, ישראל הלוי קסלרי","f":"יוסף","b":"רופא ופייטן - שנות ה-ק'. חיבר פיוט לפורים \"מי כמוכה יוצר שם רוח אדם\"."},{"i":44075,"n":"קרשקש, מאיר מאלגיר","f":"נתנאל","bt":"תנ","dt":"תקך - בערך","b":"מחכמי אלגיר, הו\"ל שו\"ת התשב\"ץ, עם הקדמה ממנו - אמשטרדם תצט. נדד רבות בקושטא, אזמיר, איטליה, נפל בשבי ונפדה ואז נדר להדפיס את הספר, נדד בארצות אירופה ובהם צרפת וגרמניה, וקיבץ תרומות לצורך הדפסת הספר."},{"i":44076,"n":"קרשקש, נהוראי מאלגיר","bt":"[רע]","dt":"שן - בערך","b":"רב באלגיר, נזכר ב\"פרי צדיק\", וב\"חוט המשולש\". על שמו בית כנסת באלגיר בשם \"חבורת נהוראי\"."},{"i":44077,"n":"קרשקש, נתנאל מאלגיר","bt":"של - בערך","dt":"תי - בערך","b":"רב באלגיר וממונה על הגיטין. הסכים על תשובות ר שלמה צרור בעל \"חוט המשולש\" לבקשת ר שלמה. היה במחלוקת עם ר משה שוראקי מתלמסאן בענין גט."},{"i":44078,"n":"קרשקש, צמח מאלגיר","b":"דיין באלג'יר, נזכר ב\"אשכבתא דרבנן\"."},{"i":44079,"n":"קרשקש, שלמה מאלג'יר","f":"נהוראי","bt":"תך - בערך","dt":"תצה - בערך","b":"רב באלג'יר. נזכר ב\"פרי צדיק\". חתם על החרם באלג'יר נגד נחמיה חיון."},{"i":44080,"n":"קשאש (קסאס), שלם מאלגיר","bt":"[רך]","dt":"רץ - בערך","b":"רב בביסכרא בזמן ר שמעון בן הרשב\"ש."},{"i":44081,"n":"קשאש ראה גם קאזיס","b":"קשאש, קסאס, גאג'יג' וקאזיס - כולם אותו המקום."},{"i":44082,"n":"קשאתי, אליעזר מקושטא","b":"רב בקושטא-שנות ה-ת'."},{"i":44083,"n":"קשאתי, דוד מקושטא","f":"אליעזר","b":"מדפיס בקושטא-שלה יחד עם ר אליעזר בן יצחק אשכנזי. הדפיסו שו\"ת הגאונים."},{"i":44084,"n":"קשטיליאר, משה משלוניקי","dt":"רצח - כה חשון","dp":"שלוניקי","b":"מחכמי שלוניקי."},{"i":44085,"n":"קשטילנובו, יצחק מרומא","b":"מחכמי הישיבה ברומא. הסכים על \"ראשית בכורי קציר\" - ונציה-פיררה תעה."},{"i":44086,"n":"קשטרו די, יצחק מתארטס הקדוש","bp":"תארטס-מחוז גאסקונה","dt":"תח-תיח - שבט","dp":"ליסבון","b":"בן למשפחת אנוסים. היגר לברזיל בזמן השלטון ההולנדי והתישב בפרחייבו-פלך באהייה, לאחר הכיבוש הפורטוגזי נתפס ונשלח ע\"י האינקויזיציה לליסבון ונהרג עק\"ה. לזכרו חיבר ר שלמה די אוליוירה הספד."},{"i":44087,"n":"קשטרו די, מנדיס מאמשטרדם","b":"הראשון שהעתיק והדפיס תורה בספרדית (די רוסי)."},{"i":44088,"n":"קשטרו, אברהם ממצרים","b":"רב במצרים-שנות ה-ת'. אחיינו של ר יעקב קשטרו ממצרים."},{"i":44089,"n":"קשטרו, אברהם ממצרים - הזקן","k":"ר' אברהם הנגיד","dt":"רפד - כח אדר","b":"ממגורשי ספרד, עבר למצרים, נגיד, שר האוצר ובעל צדקה, ונזכר ב\"אבן שוהם\" למקובל ר יוסף צייאח - שכתב את ספרו לבקשת ר אברהם. נזכר ב\"פורים של מצרים\" - שבשנת רעד הצליח לפעול להציל את הקהילה. (לדברי רוזניס נפטר - רצז). ר תאג'יר על מקומו אחריו כנגיד במצרים."},{"i":44090,"n":"קשטרו, אברהם ממצרים - הנכד","b":"תלמיד ר יעקב קשטרו. רב במצרים-שסז, תמך ברבו - ר יעקב במחלוקתו בענין גט עם ר בצלאל אשכנזי."},{"i":44091,"n":"קשטרו, אברהם משלוניקי","dt":"תריא","dp":"שלוניקי","b":"רופא בשלוניקי."},{"i":44092,"n":"קשטרו, אברהם משלוניקי","f":"משה","b":"מחכמי שלוניקי-תרס."},{"i":44093,"n":"קשטרו, דוד מירושלים","b":"מחכמי ירושלים-שפג, מוזכר במכתב משנת שפה שקנה את כתבי ר חיים ויטאל מאת בנו ר גדליה, ומכונה חכם גדול. בשות \"באר עשק\" מביא ר דניאל פינצי כי התיעץ עם ר דוד בשאלה בהלכות ציצית."},{"i":44094,"n":"קשטרו, יוסף ממצרים","b":"מגדולי רבני מצרים-רפ\"ז"},{"i":44095,"n":"קשטרו, יחזקאל מפורטוגל ואיטליה","b":"רופא מחכמי פורטוגל, עבר לוירונה. חיבר ספרים בלטינית."},{"i":44096,"n":"קשטרו, יעקב ממצרים","f":"אברהם או משה","k":"בעל ערך לחם","bt":"רפה-ח","bp":"מצרים או ירושלים","dt":"שע","dp":"קהיר","b":"מחכמי מצרים, נצר למשפחה מהעיר קאסטרו בספרד. עלה לארץ ישראל ולמד אצל הרלב\"ח והרדב\"ז והתארח אצל ר יוסף קארו בצפת. היה רב קהילת המערבים בקהיר, ועמד בראש ישיבה שם, וראש הרבנים על מקום ר בצלאל אשכנזי. בשנת של היה בצפת והתאכסן אצל ר יוסף קארו, ובספריו מספר על הנהגות שונות שראה שם. נחשב לאחד מגדולי הפוסקים ותשובותיו בספרי חכמי דורו. חיבר \"אהלי יעקב\" ליוורנו תקמג, ועוד. (ריבלין-חכמי ירושלים - מסתפק בחלק מהפרטים)."},{"i":44097,"n":"קשטרו, יצחק ממצרים","f":"יעקב","b":"גביר ורב במצרים-שנת ת' בזמן מהר\"י אבושערה, ור יוסף ברוך."},{"i":44098,"n":"קשטרו, מרדכי משלוניקי","b":"מצאצאי הדיין ר משה קאשטרו. מחכמי שלוניקי-תרף."},{"i":44099,"n":"קשטרו, משה ממצרים","f":"צדוק (צדיק)","b":"עלה ממצרים לארץ ישראל בשנת רפז, למד אצל ר יעקב בירב במצרים. תמך ברלב\"ח במחלוקת הסמיכה כנגד רבו ר יעקב בירב. לדעת רבלין היה במקורו מירושלים."},{"i":44100,"n":"קשטרו, משה משלוניקי","f":"אברהם","k":"בעל ירים משה","dt":"תרמז - יד אב","dp":"שלוניקי","b":"תלמיד ר יצחק ברזילי. אב\"ד של גוביינות-שלוניקי. למד גם קבלה והו\"ל כמה ספרי קבלה ובהם \"תורת חכם\" לר חיים די לה רוזה ועוד. מבניו: ר אברהם, ומנכדיו הדיין ר שאול קשטרו."},{"i":44101,"n":"קשטרו, משה צדיק מירושלים","b":"ממגורשי ספרד, מחכמי ירושלים-רע."},{"i":44102,"n":"קשטרו, עובד מירושלים","b":"מחכמי ירושלים, בשנת רפז היה סופר הקהלה, חתום על קיום שטר עם ר אהרן בכר עזוז."},{"i":44103,"n":"קשטרו, רפאל מירושלים","f":"משה קשטרו","dt":"שה","b":"מחכמי ירושלים-רפז, נהרג עק\"ה."},{"i":44104,"n":"קשטרו, שאול משלוניקי","b":"דיין בשלוניקי-תרס."},{"i":44105,"n":"קשלרי, אברהם הרופא מקטלוניה","f":"דוד","k":"בעל עלה רענן","b":"רב בבשלדיק-קטלוניה. ר קלונימוס בעל \"אבן בוחן\" כותב כי חיבר את ספרו לכבוד עשרה חכמים והוא אחד מהם. חיבר ספרי רפואה, ובהם על מגפת הדבר-1348, \"המסעדים\", יתכן שחיבר גם\"עלה רענן\" (וי\"א שהוא מר אברהם בן יחיאל)."},{"i":44106,"n":"קשלרי, אשר קרשקש וידאל","k":"בעל ספר רפואה","b":"מגדולי הראשונים, משורר, פוסק, רופא, מרביץ תורה במרסיליה-שנת ס', קרפנטרץ-פרובנס. תרגם ספר רפואה שחיבר מאשטרי בארנאבא דלא נאוויא-סז."},{"i":44107,"n":"קשלרי, יהושע מפרובאנס","b":"פייטן מחכמי פרובאנס-שנות ה-ש'. קינות ממנו במחזור אויניון."},{"i":44108,"n":"קשלרי, ירחמיאל מספרד","b":"רב בספרד בדור שאחר הריב\"ש. השתתף בויכוח לפני האפיפיור-קעג, שבו היה ר יוסף אלבו ראש המדברים."},{"i":44109,"n":"קשמן, יוסף יוזפא הלוי עסא","f":"משה","k":"בעל נוהג כצאן יוסף","dt":"תקיט - יב תשרי","b":"מצאצאי ר יוסף האן מפפד\"מ. חתן ר יהודה מילר. רב בדייץ, אמשטרדם. חיבר ספר על מנהגי פפד\"מ, לבקשת פרנסי קהילות קטנות שבקשו לדעת את ההבדלים בין מנהג אשכנז למנהג פולין, סייעו בידו קרוביו ר ברמן מהלברשטט ור הרץ מוינה, ור שמואל שטרן מפפד\"מ ובנו ר זיסקינד, הרופא ר קופל מילר מבינגן ועוד."},{"i":44110,"n":"קשמן, מרדכי הלוי","b":"דיין בניקלסבורג-תע\"ט"},{"i":44111,"n":"קשרבי (קאשרווי), יעקב","f":"אברהם","b":"רופא מחכמי גלינא. דיין בנריוב."},{"i":44112,"n":"קשריש, יוסף","b":"מגדולי חכמי ספרד-שנת ס'"}];
window.RB_LOADED&&window.RB_LOADED(18);
